def _voice_catalog_store() -> VoiceCatalogStore:
    """允许测试或多实例服务通过 VOICE_CATALOG_PATH 切换持久化目录。"""

    global VOICE_CATALOG_STORE
    if VOICE_CATALOG_STORE.path != VOICE_CATALOG_PATH:
        VOICE_CATALOG_STORE = VoiceCatalogStore(VOICE_CATALOG_PATH)
    return VOICE_CATALOG_STORE
