LOCAL_IMAGE_LIBRARY_LOCK = threading.Lock()
LOCAL_IMAGE_THUMBNAILS: dict[str, bytes] = {}
LOCAL_IMAGE_THUMBNAILS_LOCK = threading.Lock()
LOCAL_IMAGE_THUMBNAIL_SLOTS = threading.Semaphore(3)


def _douyin_monitor_json(path: str, *, method: str = "GET") -> tuple[int, dict[str, object]]:
    """Call the existing Douyin monitor API without exposing its session data."""

    request = Request(f"{DOUYIN_MONITOR_BASE_URL}{path}", method=method)
    if method == "POST":
        request.add_header("Content-Length", "0")
    try:
        with urlopen(request, timeout=4) as response:
            status = int(getattr(response, "status", 200))
            payload = json.loads(response.read().decode("utf-8"))
            return status, payload if isinstance(payload, dict) else {}
    except HTTPError as exc:
        try:
            payload = json.loads(exc.read().decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            payload = {}
        return int(exc.code), payload if isinstance(payload, dict) else {}
    except (OSError, URLError, TimeoutError, json.JSONDecodeError, ValueError):
        return 0, {}


def _read_douyin_login_file() -> dict[str, object]:
    try:
        value = json.loads(DOUYIN_LOGIN_STATUS_PATH.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def _douyin_service_inspection() -> dict[str, object]:
    try:
        return inspect_service(SERVICE_SPECS["douyin_monitor_web"])
    except (KeyError, OSError, ServiceGovernanceError):
        return {"overall": "unknown", "listener_count": 0, "instances": []}


def _douyin_auth_status() -> dict[str, object]:
    """Return a safe login-state summary; never return cookies or session contents."""

    inspection = _douyin_service_inspection()
    service_state = str(inspection.get("overall") or "unknown")
    code, remote = _douyin_monitor_json("/api/login/status") if service_state == "current" else (0, {})
    local = _read_douyin_login_file()
    remote_status = str(remote.get("status") or "").strip().lower()
    local_status = str(local.get("status") or "").strip().lower()
    effective_status = remote_status or local_status
    cookie_file_exists = DOUYIN_SESSION_COOKIE_PATH.is_file()
    try:
        login_age = time.time() - float(local.get("updated_at") or 0)
    except (TypeError, ValueError):
        login_age = float("inf")
    login_status_fresh = 0 <= login_age <= DOUYIN_LOGIN_STATUS_MAX_AGE_SECONDS

    if effective_status == "success" and cookie_file_exists and login_status_fresh:
        return {
            "available": True,
            "state": "available",
            "label": "Cookie 可用",
            "message": "抖音登录态已确认，可用于采集。",
            "service_state": service_state,
            "service_reachable": code == 200,
        }
    if effective_status == "success" and cookie_file_exists and not login_status_fresh:
        return {
            "available": False,
            "state": "unavailable",
            "label": "登录态需重新确认",
            "message": "Cookie 状态记录已过期，请点击此处重新扫码确认。",
            "service_state": service_state,
            "service_reachable": code == 200,
        }
    if effective_status in {"starting", "waiting"}:
        return {
            "available": False,
            "state": "pending",
            "label": "等待扫码",
            "message": str(remote.get("message") or local.get("message") or "请完成抖音扫码登录"),
            "qr_available": DOUYIN_LOGIN_QR_PATH.is_file(),
            "service_state": service_state,
            "service_reachable": code == 200,
        }
    if effective_status == "expired":
        return {
            "available": False,
            "state": "unavailable",
            "label": "二维码已过期",
            "message": "二维码已过期，请点击“刷新二维码”重新生成。",
            "qr_available": False,
            "service_state": service_state,
            "service_reachable": code == 200,
        }
    if service_state == "foreign":
        return {
            "available": False,
            "state": "blocked",
            "label": "登录服务被占用",
            "message": "8080 端口被其他项目占用，未自动结束该进程。",
            "service_state": service_state,
            "service_reachable": False,
        }
    if effective_status in {"error", "timeout"}:
        return {
            "available": False,
            "state": "unavailable",
            "label": "Cookie 不可用",
            "message": str(remote.get("message") or local.get("message") or "登录态不可用，请重新扫码"),
            "service_state": service_state,
            "service_reachable": code == 200,
        }
    return {
        "available": False,
        "state": "unavailable",
        "label": "Cookie 未就绪",
        "message": "尚未确认抖音登录态，点击此处获取二维码。",
        "service_state": service_state,
        "service_reachable": code == 200,
    }


def _start_douyin_login() -> dict[str, object]:
    """Reuse or start the governed 8080 service, then start its existing QR flow."""

    inspection = _douyin_service_inspection()
    if inspection.get("overall") == "foreign":
        raise ServiceGovernanceError("8080 端口被其他项目占用，未启动或结束该服务。")
    if inspection.get("overall") != "current":
        start_service("douyin_monitor_web")
    code, payload = _douyin_monitor_json("/api/login/start", method="POST")
    if code < 200 or code >= 300:
        raise ServiceGovernanceError(str(payload.get("error") or "抖音登录服务启动失败"))
    return _douyin_auth_status()


def _resolve_jianying_draft_root(value: object = None) -> Path:
    """Resolve the user-selected Windows Jianying draft parent directory."""

    raw = str(value or "").strip().strip('"') or str(JIANYING_DRAFT_ROOT)
    return Path(raw).expanduser().resolve()


def _jianying_exe_candidates() -> list[Path]:
    """Return configurable and common Jianying executable locations."""

    values = [os.environ.get("JIANYING_EXE_PATH", ""), str(JIANYING_EXE_PATH), *DEFAULT_JIANYING_EXE_CANDIDATES]
    candidates: list[Path] = []
    seen: set[str] = set()
    for value in values:
        raw = str(value or "").strip().strip('"')
        if not raw:
            continue
        path = Path(raw).expanduser().resolve()
        key = str(path).casefold()
        if key in seen:
            continue
        seen.add(key)
        candidates.append(path)
    return candidates


def _resolve_jianying_exe_path(value: object = None) -> Path:
    """Resolve a selected Jianying executable, falling back to known paths."""

    raw = str(value or "").strip().strip('"')
    if raw:
        return Path(raw).expanduser().resolve()
    for path in _jianying_exe_candidates():
        if path.is_file() and path.suffix.lower() == ".exe":
            return path
    return Path(str(JIANYING_EXE_PATH)).expanduser().resolve()


def _jianying_exe_candidates_snapshot() -> dict[str, object]:
    """Expose only local path/existence metadata for the production selector."""

    selected = _resolve_jianying_exe_path()
    candidates = [
        {"path": str(path), "exists": path.is_file() and path.suffix.lower() == ".exe"}
        for path in _jianying_exe_candidates()
    ]
    return {
        "status": "ready" if selected.is_file() else "blocked",
        "selected": str(selected),
        "candidates": candidates,
    }


def _resolve_editing_draft_name(value: object, source_story_task_id: str, task_id: str) -> str:
    """Use the requested draft name, or preserve the legacy automatic name."""

    requested = str(value or "").strip()
    return requested or f"video_console_{source_story_task_id[:8]}_{task_id[:8]}_win"


def _draft_directory(value: object, label: str) -> Path:
    """Resolve and validate one local Jianying DraftFolder."""

    path = Path(str(value or "").strip().strip('"')).expanduser().resolve()
    if not path.is_dir():
        raise ValueError(f"{label}不存在或不是文件夹：{path}")
    if not (path / "draft_info.json").is_file():
        try:
            load_draft_content(path)
        except Exception as exc:
            raise ValueError(f"{label}缺少可解析的剪映草稿 JSON：{path}") from exc
    return path


def _opening_output_name(value: object) -> str:
    name = str(value or "").strip()
    if not name:
        raise ValueError("请填写片头模板套用后的输出草稿名称")
    if name in {".", ".."} or any(char in name for char in '<>:"/\\|?*'):
        raise ValueError("输出草稿名称不能包含路径分隔符或 Windows 保留字符")
    return name


def _draft_info_for_validation(path: Path, label: str) -> dict[str, object]:
    """Read a Jianying draft's timeline data and expose a stable duration field."""

    fallback_info: dict[str, object] = {}
    try:
        raw_info = json.loads((path / "draft_info.json").read_text(encoding="utf-8"))
        if isinstance(raw_info, Mapping):
            fallback_info = dict(raw_info)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        pass
    if int(fallback_info.get("duration") or 0) > 0:
        return fallback_info
    try:
        draft = load_draft_content(path)
    except Exception as exc:
        raise ValueError(f"{label}缺少可解析的剪映草稿 JSON：{path}") from exc
    info: dict[str, object] = dict(draft)
    duration_us = int(info.get("duration") or 0)
    if duration_us <= 0:
        try:
            meta = json.loads((path / "draft_meta_info.json").read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            meta = {}
        if isinstance(meta, Mapping):
            duration_us = int(meta.get("tm_duration") or 0)
    info["duration"] = duration_us
    return info


def _list_jianying_drafts(root_value: object = None) -> dict[str, object]:
    """List local DraftFolders under the selected parent for page selectors."""

    root = _resolve_jianying_draft_root(root_value)
    if not root.is_dir():
        return {"root": str(root), "root_exists": False, "drafts": []}
    drafts: list[dict[str, object]] = []
    try:
        children = list(root.iterdir())
    except OSError:
        children = []
    for child in children:
        if not child.is_dir():
            continue
        info: dict[str, object] = {}
        try:
            raw_info = json.loads((child / "draft_info.json").read_text(encoding="utf-8"))
            if isinstance(raw_info, Mapping):
                info = dict(raw_info)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            pass
        draft: dict[str, object] = {}
        try:
            draft = load_draft_content(child)
        except Exception:
            # 保留旧版只有 draft_info.json 的目录；新版剪映则可只靠 draft_content.json。
            if not (child / "draft_info.json").is_file():
                continue
        duration_us = int(info.get("duration") or 0)
        if duration_us <= 0:
            duration_us = int(draft.get("duration") or 0)
        if duration_us <= 0:
            try:
                meta = json.loads((child / "draft_meta_info.json").read_text(encoding="utf-8"))
                duration_us = int(meta.get("tm_duration") or 0) if isinstance(meta, Mapping) else 0
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                duration_us = 0
        try:
            modified_at = int(child.stat().st_mtime)
        except OSError:
            modified_at = 0
        packaging_eligible = bool(draft)
        packaging_reason = "" if packaging_eligible else "缺少可解析的 draft_content.json"
        drafts.append({
            # 剪映重命名可能只更新 DraftFolder 名称；下拉菜单必须以实际
            # 文件夹为主，避免旧 draft_info.json 名称遮蔽用户刚改的名称。
            "name": child.name,
            "draft_internal_name": str(info.get("name") or draft.get("name") or child.name),
            "folder_name": child.name,
            "path": str(child),
            "duration_us": duration_us,
            "template_eligible": duration_us >= OPENING_TEMPLATE_WINDOW_US,
            "packaging_eligible": packaging_eligible,
            "packaging_reason": packaging_reason,
            "modified_at": modified_at,
        })
    drafts.sort(key=lambda item: (int(item.get("modified_at") or 0), str(item.get("name") or "")), reverse=True)
    return {"root": str(root), "root_exists": True, "drafts": drafts}


_RECOGNITION_PACKAGING_GROUP_LABELS = {
    "opening": "片头包装",
    "image": "图片单图包装",
    "image_sequence": "图片+3（连续三图以上）包装",
    "digital_human": "数字人包装",
    "explanation": "说明镜头包装",
    "mixed_explanation": "混合说明包装",
    "ending": "片尾包装",
    "unclassified": "待校对",
    "global": "全局包装",
}
_RECOGNITION_PACKAGING_COMPONENT_LABELS = (
    ("variables", "变量层"),
    ("effects", "特效"),
    ("filters", "滤镜"),
    ("stickers", "贴纸"),
    ("audio_tracks", "音轨"),
    ("text", "文字"),
    ("text_templates", "文字模板"),
    ("keyframes", "关键帧"),
)
_RECOGNITION_PACKAGING_SUMMARY_ORDER = (
    "opening", "image", "image_sequence", "digital_human",
    "explanation", "mixed_explanation", "ending",
)
_RECOGNITION_GROUP_OVERLAP_TOLERANCE_US = 250_000
# AIGC、通用变量、全局字幕及全局音频都是素材/角色标签，不是独立包装分类。
# 全局音频归入“全局包装”的组件；局部特效可保留为待人工校对的包装证据，但不能
# 仅因与这些内容或角色同一时间段就自动生成独立包装分组。
_RECOGNITION_CONTENT_ONLY_CATEGORIES = frozenset({
    "aigc", "variable", "global_audio", "global_subtitles",
})
_RECOGNITION_PACKAGING_AUDIO_ROLES = frozenset({
    "sfx", "sound_effect", "transition", "transition_sfx", "visual_enhancement_sfx",
})


def _recognition_segment_has_packaging_evidence(
    lane: Mapping[str, object],
    segment: Mapping[str, object],
) -> bool:
    """返回能证明该片段属于包装层的直接证据，避免把内容变量强行当成包装。"""

    track_type = str(lane.get("track_type") or "").strip().lower()
    track_name = str(lane.get("track_name") or lane.get("name") or "").strip()
    if bool(segment.get("is_packaging_evidence")) or track_name.startswith("包装-"):
        return True
    if track_type in {"effect", "filter", "sticker"}:
        return True
    refs = segment.get("parameter_refs")
    collections = {
        str(item.get("collection") or "").strip().lower()
        for item in (refs if isinstance(refs, list) else [])
        if isinstance(item, Mapping)
    }
    material_type = str(segment.get("material_type") or "").strip().lower()
    if track_type == "text" and (material_type == "text_template" or "text_templates" in collections):
        return True
    audio_role = str(segment.get("audio_role") or lane.get("audio_role") or "").strip().lower()
    # 音效不是内容变量：转场、点击、翻页、写字等音效均属于包装层音频，
    # 不能因系统只标记了其中一段为 evidence 而漏出当前包装分组。
    return track_type == "audio" and audio_role in _RECOGNITION_PACKAGING_AUDIO_ROLES


def _recognition_group_component(lane: Mapping[str, object], segment: Mapping[str, object]) -> str | None:
    """将草稿片段归入包装分组的组件清单；不改变原始分类。"""

    track_type = str(lane.get("track_type") or "").strip().lower()
    category = str(segment.get("category") or "").strip().lower()
    material_type = str(segment.get("material_type") or "").strip().lower()
    audio_role = str(segment.get("audio_role") or lane.get("audio_role") or "").strip().lower()
    refs = segment.get("parameter_refs")
    collections = {
        str(item.get("collection") or "").strip().lower()
        for item in (refs if isinstance(refs, list) else []) if isinstance(item, Mapping)
    }
    if track_type in {"video", "image"}:
        return "variables"
    if track_type == "effect":
        return "effects"
    if track_type == "filter":
        return "filters"
    if track_type == "sticker":
        return "stickers"
    if track_type == "audio":
        return "variables" if audio_role in {"narration", "original_audio"} else "audio_tracks"
    if track_type == "text":
        if material_type == "text_template" or "text_templates" in collections:
            return "text_templates"
        return "variables" if category in {"variable", "global_subtitles"} else "text"
    return None


def _build_packaging_recognition_groups(
    catalog: Mapping[str, object],
    *,
    duration_us: int = 0,
) -> dict[str, object]:
    """按变量时间窗聚合包装组件，保留未完整的候选组供人工校对。

    这只是识别界面的只读候选，不会把没有出现的组件误当成错误，也不会回写草稿。
    """

    lanes = catalog.get("track_lanes")
    lane_rows = [item for item in lanes if isinstance(item, Mapping)] if isinstance(lanes, list) else []
    all_rows: list[dict[str, object]] = []
    for lane in lane_rows:
        raw_index = int(lane.get("raw_track_index") or lane.get("track_index") or 0)
        segments = lane.get("segments")
        if not isinstance(segments, list):
            continue
        for raw_segment in segments:
            if not isinstance(raw_segment, Mapping):
                continue
            start_us = max(0, int(raw_segment.get("start_us") or 0))
            end_us = max(start_us, int(raw_segment.get("end_us") or start_us))
            if end_us <= start_us:
                continue
            segment = dict(raw_segment)
            all_rows.append({
                "key": f"{raw_index}:{int(segment.get('segment_index') or 0)}",
                "lane": lane,
                "segment": segment,
                "start_us": start_us,
                "end_us": end_us,
                "category": str(segment.get("category") or "unclassified").strip().lower() or "unclassified",
                "is_global": bool(segment.get("is_global_element")),
            })

    evidence_rows = [
        row for row in all_rows
        if isinstance(row.get("lane"), Mapping)
        and isinstance(row.get("segment"), Mapping)
        and _recognition_segment_has_packaging_evidence(row["lane"], row["segment"])
    ]
    timeline_duration_us = max(
        int(duration_us or 0),
        max((int(row.get("end_us") or 0) for row in all_rows), default=0),
    )

    def overlaps(row: Mapping[str, object], start_us: int, end_us: int) -> bool:
        return (
            min(int(row.get("end_us") or 0), end_us) + _RECOGNITION_GROUP_OVERLAP_TOLERANCE_US
            > max(int(row.get("start_us") or 0), start_us) - _RECOGNITION_GROUP_OVERLAP_TOLERANCE_US
        )

    def has_packaging_evidence(start_us: int, end_us: int, *, global_group: bool = False) -> bool:
        """只有包装证据和变量时间窗相交时，才建立包装候选。"""

        for row in evidence_rows:
            if global_group:
                if bool(row.get("is_global")) and overlaps(row, start_us, end_us):
                    return True
            elif not bool(row.get("is_global")) and overlaps(row, start_us, end_us):
                return True
        return False

    def direct_packaging_evidence_count(start_us: int, end_us: int, *, global_group: bool = False) -> int:
        """统计真实重叠的包装证据；250ms 容差不能用于典型案例展示。"""

        return sum(
            1
            for row in evidence_rows
            if bool(row.get("is_global")) == global_group
            and min(int(row.get("end_us") or 0), end_us) > max(int(row.get("start_us") or 0), start_us)
        )

    def direct_overlap_us(row: Mapping[str, object], start_us: int, end_us: int) -> int:
        """返回不带时间容差的真实交叠时长。"""

        return max(
            0,
            min(int(row.get("end_us") or 0), end_us)
            - max(int(row.get("start_us") or 0), start_us),
        )

    def matches_group_category(
        row: Mapping[str, object],
        *,
        category: str,
        anchor_keys: set[str],
        global_group: bool,
    ) -> bool:
        """判断弹窗中的片段是否属于当前包装分类，而非仅与它时间重叠。"""

        lane = row.get("lane")
        segment = row.get("segment")
        if not isinstance(lane, Mapping) or not isinstance(segment, Mapping):
            return False
        key = str(row.get("key") or "")
        if global_group:
            # 全局分组的范围就是全局元素集合；BGM 等全局音频也应在范围内
            # 作为目标分类显示，而不是被误画成非本分类上下文。
            return bool(row.get("is_global")) or key in anchor_keys
        if bool(row.get("is_global")):
            # 局部主时间轴片段只校对局部包装；贯穿全片的暗角、BGM 等
            # 全局元素虽然会在时间上重叠，也必须保留为灰色上下文。
            return False
        if category in {"opening", "ending"}:
            return key in anchor_keys or str(segment.get("boundary_category") or "") == category
        if category == "image_sequence":
            return key in anchor_keys or str(row.get("category") or "") == "image_sequence"
        if key in anchor_keys or str(row.get("category") or "") == category:
            return True
        # 待校对的包装音频没有可靠的自身分类，只能在目标主时间轴片段内、
        # 且存在真实交叠时归入当前案例。避免把前一镜头仅相差几十毫秒的音效
        # 误高亮，也避免把下一镜头的包装效果扩进当前案例。
        return (
            _recognition_segment_has_packaging_evidence(lane, segment)
            and direct_overlap_us(row, start_us, end_us) >= 100_000
        )

    def make_group(
        *,
        group_id: str,
        category: str,
        start_us: int,
        end_us: int,
        anchor_keys: set[str],
        anchor_count: int,
        global_group: bool = False,
    ) -> dict[str, object]:
        components: dict[str, dict[str, object]] = {
            key: {"key": key, "label": label, "count": 0, "names": []}
            for key, label in _RECOGNITION_PACKAGING_COMPONENT_LABELS
        }
        member_rows: list[dict[str, object]] = []
        for row in all_rows:
            if global_group:
                if not bool(row.get("is_global")):
                    continue
            elif not overlaps(row, start_us, end_us):
                continue
            lane = row["lane"]
            segment = row["segment"]
            if not isinstance(lane, Mapping) or not isinstance(segment, Mapping):
                continue
            component_key = _recognition_group_component(lane, segment)
            matches_category = matches_group_category(
                row,
                category=category,
                anchor_keys=anchor_keys,
                global_group=global_group,
            )
            # 组件统计只统计当前目标分类；非本分类轨道仍保留在 members 中，
            # 由弹窗按灰色上下文显示，不污染包装分组卡片上的组件数量。
            if component_key and matches_category:
                component = components[component_key]
                component["count"] = int(component["count"]) + 1
                name = str(segment.get("material_name") or segment.get("name") or "未命名元素").strip()
                names = component["names"]
                if isinstance(names, list) and name and name not in names:
                    names.append(name)
            keyframes = segment.get("keyframes")
            keyframe_count = int(keyframes.get("point_count") or 0) if isinstance(keyframes, Mapping) else 0
            if keyframe_count and matches_category:
                component = components["keyframes"]
                component["count"] = int(component["count"]) + keyframe_count
                names = component["names"]
                if isinstance(names, list):
                    names.append(f"{str(segment.get('material_name') or '未命名元素')}（{keyframe_count} 点）")
            # 目标主时间轴片段范围内的所有轨道片段都保留。component_key 为空时
            # 仅作为上下文显示，不进入组件计数。
            member_rows.append({
                "key": str(row.get("key") or ""),
                "raw_track_index": int(lane.get("raw_track_index") or lane.get("track_index") or 0),
                "segment_index": int(segment.get("segment_index") or 0),
                "track_name": str(lane.get("track_name") or lane.get("name") or "未命名轨道"),
                "track_type": str(lane.get("track_type") or "未知"),
                "material_name": str(segment.get("material_name") or segment.get("name") or "未命名元素"),
                "start_us": int(row.get("start_us") or 0),
                "end_us": int(row.get("end_us") or 0),
                "category": str(row.get("category") or "unclassified"),
                "component_key": component_key or ("keyframes" if keyframe_count else "context"),
                "matches_group_category": matches_category,
            })
        included = [item for item in components.values() if int(item["count"]) > 0]
        missing = [key for key, _label in _RECOGNITION_PACKAGING_COMPONENT_LABELS if not int(components[key]["count"])]
        return {
            "group_id": group_id,
            "label": _RECOGNITION_PACKAGING_GROUP_LABELS.get(category, f"{category} 包装"),
            "category": category,
            "time_range_us": {"start_us": start_us, "end_us": end_us},
            "anchor_count": anchor_count,
            "anchor_keys": sorted(anchor_keys),
            "member_count": len(member_rows),
            "members": sorted(member_rows, key=lambda item: (int(item["start_us"]), str(item["key"]))),
            "components": included,
            "missing_component_keys": missing,
            "is_global_group": global_group,
        }

    groups: list[dict[str, object]] = []
    # 片头/片尾是分类标准，不是固定 5 秒的展示窗口。先在保护区内找到一条
    # 真实的主时间轴内容片段，再用它的完整起止时间作为校对范围；没有主内容
    # 片段时才退回保护区窗口，避免把后续镜头或下一段包装效果硬塞进案例。
    boundary_window_us = 5_000_000
    for boundary_category in ("opening", "ending"):
        boundary_evidence = [
            row for row in evidence_rows
            if isinstance(row.get("segment"), Mapping)
            and str(row["segment"].get("boundary_category") or "") == boundary_category
        ]
        if not boundary_evidence:
            continue
        if boundary_category == "opening":
            boundary_start_us = 0
            boundary_end_us = min(timeline_duration_us, boundary_window_us)
        else:
            boundary_start_us = max(0, timeline_duration_us - boundary_window_us)
            boundary_end_us = timeline_duration_us
        if boundary_end_us <= boundary_start_us:
            continue
        boundary_main_rows = [
            row
            for row in all_rows
            if isinstance(row.get("lane"), Mapping)
            and str(row["lane"].get("track_type") or "").strip().lower() in {"video", "image"}
            and str((row.get("segment") or {}).get("boundary_category") or "") == boundary_category
            and not bool(row.get("is_global"))
            and direct_overlap_us(row, boundary_start_us, boundary_end_us) > 0
        ]
        selected_main = None
        if boundary_main_rows:
            ranked_boundary_rows = []
            for row in boundary_main_rows:
                row_start = int(row.get("start_us") or 0)
                row_end = int(row.get("end_us") or row_start)
                evidence_count = direct_packaging_evidence_count(row_start, row_end)
                context_track_count = len({
                    int((other.get("lane") or {}).get("raw_track_index")
                        or (other.get("lane") or {}).get("track_index") or 0)
                    for other in all_rows
                    if direct_overlap_us(other, row_start, row_end) > 0
                    and str(other.get("key") or "") != str(row.get("key") or "")
                    and isinstance(other.get("lane"), Mapping)
                })
                ranked_boundary_rows.append((
                    (
                        int(evidence_count > 0),
                        evidence_count,
                        -context_track_count,
                        row_end - row_start,
                        -row_start if boundary_category == "opening" else row_start,
                    ),
                    row,
                ))
            selected_main = max(ranked_boundary_rows, key=lambda item: item[0])[1]
        if selected_main is not None:
            main_start_us = int(selected_main.get("start_us") or boundary_start_us)
            main_end_us = int(selected_main.get("end_us") or main_start_us)
            main_anchor_keys = {str(selected_main.get("key") or "")}
            main_anchor_count = 1
            main_range_source = "content_track"
        else:
            main_start_us = boundary_start_us
            main_end_us = boundary_end_us
            main_anchor_keys = set()
            main_anchor_count = len(boundary_evidence)
            main_range_source = "boundary_window_fallback"
        groups.append(make_group(
            group_id=f"{boundary_category}_boundary_1",
            category=boundary_category,
            start_us=main_start_us,
            end_us=main_end_us,
            anchor_keys=main_anchor_keys | {str(row.get("key") or "") for row in boundary_evidence},
            anchor_count=main_anchor_count,
        ))
        groups[-1]["main_timeline_range_source"] = main_range_source
    sequence_member_keys: set[str] = set()
    image_patterns = catalog.get("image_packaging_patterns")
    sequences = image_patterns.get("sequences") if isinstance(image_patterns, Mapping) else []
    if isinstance(sequences, list):
        for index, raw_sequence in enumerate(sequences, start=1):
            if not isinstance(raw_sequence, Mapping):
                continue
            time_range = raw_sequence.get("time_range_us")
            if not isinstance(time_range, Mapping):
                continue
            start_us = max(0, int(time_range.get("start") or time_range.get("start_us") or 0))
            end_us = max(start_us, int(time_range.get("end") or time_range.get("end_us") or start_us))
            if end_us <= start_us:
                continue
            members = raw_sequence.get("members")
            anchor_keys = {
                f"{int(item.get('raw_track_index') or 0)}:{int(item.get('segment_index') or 0)}"
                for item in members if isinstance(item, Mapping)
            } if isinstance(members, list) else set()
            if not has_packaging_evidence(start_us, end_us):
                continue
            sequence_member_keys.update(anchor_keys)
            groups.append(make_group(
                group_id=str(raw_sequence.get("sequence_id") or f"image_sequence_{index}"),
                category="image_sequence",
                start_us=start_us,
                end_us=end_us,
                anchor_keys=anchor_keys,
                anchor_count=len(anchor_keys),
            ))

    # 同一内容轨、同一包装类别且时间连续的变量片段，归并成一个包装分组；
    # 片段本身仍完整保留在 members 中，供弹窗逐项校正。
    anchor_runs: dict[tuple[int, str], list[dict[str, object]]] = {}
    for row in all_rows:
        lane = row["lane"]
        segment = row["segment"]
        if not isinstance(lane, Mapping) or not isinstance(segment, Mapping):
            continue
        if bool(row.get("is_global")) or str(row.get("key") or "") in sequence_member_keys:
            continue
        if str(lane.get("track_type") or "").strip().lower() not in {"video", "image"}:
            continue
        raw_track_index = int(lane.get("raw_track_index") or lane.get("track_index") or 0)
        category = str(row.get("category") or "unclassified")
        anchor_runs.setdefault((raw_track_index, category), []).append(row)

    merged_anchor_runs: list[tuple[str, list[dict[str, object]]]] = []
    for (_track_index, category), rows in anchor_runs.items():
        current: list[dict[str, object]] = []
        current_end_us = 0
        for row in sorted(rows, key=lambda item: (int(item["start_us"]), int(item["end_us"]))):
            start_us = int(row["start_us"])
            end_us = int(row["end_us"])
            if current and start_us > current_end_us + _RECOGNITION_GROUP_OVERLAP_TOLERANCE_US:
                merged_anchor_runs.append((category, current))
                current = []
                current_end_us = 0
            current.append(row)
            current_end_us = max(current_end_us, end_us)
        if current:
            merged_anchor_runs.append((category, current))

    anchor_index = 1
    for category, members in sorted(merged_anchor_runs, key=lambda item: (int(item[1][0]["start_us"]), item[0])):
        if category in _RECOGNITION_CONTENT_ONLY_CATEGORIES:
            continue
        start_us = min(int(item["start_us"]) for item in members)
        end_us = max(int(item["end_us"]) for item in members)
        if not has_packaging_evidence(start_us, end_us):
            continue
        groups.append(make_group(
            group_id=f"recognition_group_{anchor_index}",
            category=category,
            start_us=start_us,
            end_us=end_us,
            anchor_keys={str(item.get("key") or "") for item in members},
            anchor_count=len(members),
        ))
        anchor_index += 1

    global_rows = [row for row in evidence_rows if bool(row.get("is_global"))]
    if global_rows:
        groups.append(make_group(
            group_id="global_packaging_1",
            category="global",
            start_us=min(int(row["start_us"]) for row in global_rows),
            end_us=max(int(row["end_us"]) for row in global_rows),
            anchor_keys={str(row.get("key") or "") for row in global_rows},
            anchor_count=len(global_rows),
            global_group=True,
        ))

    # 纯文字、纯音频、全局字幕等分类没有视频/图片变量锚点，也必须在典型案例
    # 中保留一个可审阅入口，不能因为没有内容轨就从分类列表消失。
    categories = catalog.get("categories")
    represented_categories = {str(item.get("category") or "") for item in groups}
    if isinstance(categories, Mapping):
        rows_by_category: dict[str, list[dict[str, object]]] = {}
        for row in all_rows:
            rows_by_category.setdefault(str(row.get("category") or "unclassified"), []).append(row)
        for category, raw_category in categories.items():
            if not isinstance(raw_category, Mapping) or int(raw_category.get("segment_count") or 0) <= 0:
                continue
            category_text = str(category)
            if category_text in _RECOGNITION_CONTENT_ONLY_CATEGORIES:
                continue
            if category_text in represented_categories:
                continue
            choices = [
                row for row in (rows_by_category.get(category_text) or [])
                if isinstance(row.get("lane"), Mapping)
                and isinstance(row.get("segment"), Mapping)
                and _recognition_segment_has_packaging_evidence(row["lane"], row["segment"])
            ]
            if not choices:
                continue
            sample = max(
                choices,
                key=lambda item: (
                    int(item.get("end_us") or 0) - int(item.get("start_us") or 0),
                    -int(item.get("start_us") or 0),
                ),
            )
            groups.append(make_group(
                group_id=f"category_sample_{category_text}",
                category=category_text,
                start_us=int(sample.get("start_us") or 0),
                end_us=int(sample.get("end_us") or 0),
                anchor_keys={str(sample.get("key") or "")},
                anchor_count=1,
                global_group=bool(sample.get("is_global")),
            ))
            represented_categories.add(category_text)

    def group_start(item: Mapping[str, object]) -> int:
        time_range = item.get("time_range_us")
        return int(time_range.get("start_us") or 0) if isinstance(time_range, Mapping) else 0

    groups.sort(key=lambda item: (group_start(item), str(item.get("group_id") or "")))

    def choose_typical_range(group: dict[str, object]) -> None:
        """选择一个主时间轴片段，并把它的完整范围交给弹窗校对。"""

        time_range = group.get("time_range_us")
        if not isinstance(time_range, Mapping):
            return
        start_us = int(time_range.get("start_us") or 0)
        end_us = max(start_us, int(time_range.get("end_us") or start_us))
        category = str(group.get("category") or "unclassified")
        global_group = bool(group.get("is_global_group"))
        # 片头、片尾、贯穿全场，以及连续三图都必须保留完整作用范围。
        # 连续三图的判断依赖同一原始轨道中的连续片段；若只截取其中一张图，
        # 人工无法核对“连续三图以上”这一分类，因此不能压缩成单段典型案例。
        if category in {"opening", "ending", "global", "image_sequence"} or end_us <= start_us:
            selected_range = {"start_us": start_us, "end_us": end_us}
            group["main_timeline_range_us"] = selected_range
            group["representative_range_us"] = selected_range
            group["main_timeline_range_source"] = group.get("main_timeline_range_source") or "group_range"
            group["representative_context_track_count"] = 0
            group["representative_packaging_evidence_count"] = direct_packaging_evidence_count(
                start_us, end_us, global_group=global_group,
            )
            return
        anchor_keys = {
            str(item) for item in (group.get("anchor_keys") or [])
            if str(item).strip()
        }
        anchors = [
            row for row in all_rows
            if str(row.get("key") or "") in anchor_keys
            and overlaps(row, start_us, end_us)
        ]
        if not anchors:
            selected_range = {"start_us": start_us, "end_us": end_us}
            group["main_timeline_range_us"] = selected_range
            group["representative_range_us"] = selected_range
            group["main_timeline_range_source"] = "group_range_fallback"
            group["representative_context_track_count"] = 0
            group["representative_packaging_evidence_count"] = direct_packaging_evidence_count(
                start_us, end_us, global_group=global_group,
            )
            return

        ranked: list[tuple[tuple[int, int, int, int, int, int, int], int, int, int, int, str]] = []
        for anchor in anchors:
            candidate_start = max(start_us, int(anchor.get("start_us") or start_us))
            candidate_end = min(end_us, int(anchor.get("end_us") or candidate_start))
            if candidate_end <= candidate_start:
                continue
            # 典型范围严格采用目标主时间轴片段的完整起止。包装音效若与它
            # 实际交叠，会在这个范围内显示；只在片段结束后才开始的音效、
            # 下一张图片或下一镜头包装不得反向扩张当前案例。
            rows_in_candidate = [
                row for row in all_rows
                if min(int(row.get("end_us") or 0), candidate_end)
                > max(int(row.get("start_us") or 0), candidate_start)
            ]
            matching_rows = [
                row for row in rows_in_candidate
                if matches_group_category(
                    row,
                    category=category,
                    anchor_keys=anchor_keys,
                    global_group=global_group,
                )
            ]
            context_rows = [row for row in rows_in_candidate if row not in matching_rows]
            context_track_count = len({
                int((row.get("lane") or {}).get("raw_track_index") or (row.get("lane") or {}).get("track_index") or 0)
                for row in context_rows
                if isinstance(row.get("lane"), Mapping)
            })
            candidate_evidence_count = direct_packaging_evidence_count(
                candidate_start, candidate_end, global_group=global_group,
            )
            ranked.append((
                (
                    int(candidate_evidence_count > 0),
                    candidate_evidence_count,
                    -context_track_count,
                    -len(context_rows),
                    len(matching_rows),
                    candidate_end - candidate_start,
                    -candidate_start,
                ),
                candidate_start,
                candidate_end,
                context_track_count,
                candidate_evidence_count,
                str(anchor.get("key") or ""),
            ))
        if not ranked:
            selected_range = {"start_us": start_us, "end_us": end_us}
            group["main_timeline_range_us"] = selected_range
            group["representative_range_us"] = selected_range
            group["main_timeline_range_source"] = "group_range_fallback"
            group["representative_context_track_count"] = 0
            group["representative_packaging_evidence_count"] = direct_packaging_evidence_count(
                start_us, end_us, global_group=global_group,
            )
            return
        _score, candidate_start, candidate_end, context_track_count, candidate_evidence_count, anchor_key = max(
            ranked, key=lambda item: item[0],
        )
        selected_range = {"start_us": candidate_start, "end_us": candidate_end}
        group["main_timeline_range_us"] = selected_range
        group["representative_range_us"] = selected_range
        group["main_timeline_range_source"] = "content_track"
        group["main_timeline_anchor_key"] = anchor_key
        group["representative_context_track_count"] = context_track_count
        group["representative_packaging_evidence_count"] = candidate_evidence_count

    for group in groups:
        choose_typical_range(group)
    # 候选卡必须包含真实重叠的包装层；只有相邻、没有重叠的特效不能撑起包装分组。
    groups = [
        group for group in groups
        if int(group.get("representative_packaging_evidence_count") or 0) > 0
    ]

    # 工作台只展示每个包装分类的一个典型案例，避免把全部识别结果铺满页面。
    # 先选非本分类轨道更少的典型片段，再比较组件完整度、变量锚点和时长。
    representative_by_category: dict[str, dict[str, object]] = {}
    for group in groups:
        category = str(group.get("category") or "unclassified")
        time_range = group.get("time_range_us")
        start_us = int(time_range.get("start_us") or 0) if isinstance(time_range, Mapping) else 0
        end_us = int(time_range.get("end_us") or start_us) if isinstance(time_range, Mapping) else start_us
        component_counts = {
            str(item.get("key") or ""): int(item.get("count") or 0)
            for item in (group.get("components") or [])
            if isinstance(item, Mapping)
        }
        audio_count = component_counts.get("audio_tracks", 0)
        score = (
            int(audio_count > 0),
            audio_count,
            -int(group.get("representative_context_track_count") or 0),
            len(group.get("components") or []),
            int(group.get("anchor_count") or 0),
            int(group.get("member_count") or 0),
            max(0, end_us - start_us),
            -start_us,
        )
        existing = representative_by_category.get(category)
        if existing is None:
            representative_by_category[category] = group
            continue
        existing_range = existing.get("time_range_us")
        existing_start = int(existing_range.get("start_us") or 0) if isinstance(existing_range, Mapping) else 0
        existing_end = int(existing_range.get("end_us") or existing_start) if isinstance(existing_range, Mapping) else existing_start
        existing_component_counts = {
            str(item.get("key") or ""): int(item.get("count") or 0)
            for item in (existing.get("components") or [])
            if isinstance(item, Mapping)
        }
        existing_audio_count = existing_component_counts.get("audio_tracks", 0)
        existing_score = (
            int(existing_audio_count > 0),
            existing_audio_count,
            -int(existing.get("representative_context_track_count") or 0),
            len(existing.get("components") or []),
            int(existing.get("anchor_count") or 0),
            int(existing.get("member_count") or 0),
            max(0, existing_end - existing_start),
            -existing_start,
        )
        if score > existing_score:
            representative_by_category[category] = group
    representative_groups = sorted(
        representative_by_category.values(),
        key=lambda item: (group_start(item), str(item.get("category") or "")),
    )
    category_summary: list[dict[str, object]] = []
    if isinstance(categories, Mapping):
        for key in _RECOGNITION_PACKAGING_SUMMARY_ORDER:
            item = categories.get(key)
            if not isinstance(item, Mapping):
                continue
            count = int(item.get("segment_count") or 0)
            if count:
                category_summary.append({
                    "key": key,
                    "label": str(item.get("label") or _RECOGNITION_PACKAGING_GROUP_LABELS.get(key, key)),
                    "segment_count": count,
                })
    return {
        "group_count": len(groups),
        "groups": groups,
        "representative_group_count": len(representative_groups),
        "representative_groups": representative_groups,
        "category_summary": category_summary,
        "component_policy": "先锁定目标分类的主时间轴片段，再展示该完整起止范围内的全部轨道；时间对齐采用 ±0.25 秒容差，避免微秒级边界差漏掉同一包装组件；只有范围内的目标包装组件计入候选，非本分类轨道保留为灰色上下文；未出现的组件保留为空，不视为错误；没有包装层的时间片不会进入候选，不强行识别包装层。",
    }


def _inspect_packaging_recognition_draft(payload: Mapping[str, object]) -> dict[str, object]:
    """只读解析一份剪映 DraftFolder，供包装人工校准界面展示。

    这个入口刻意不创建包装包、不写回草稿，也不替用户确认元素分类。
    它只把已有的草稿解析能力转换为可点击的时间线轨道数据和候选归类。
    """

    raw_path = str(payload.get("draft_path") or "").strip().strip('"')
    if not raw_path:
        raise ValueError("请先选择或粘贴一个剪映 DraftFolder 路径")
    source = Path(raw_path).expanduser().resolve()
    if source.is_file():
        if source.name.lower() != "draft_content.json":
            raise ValueError("请选择剪映 DraftFolder，或其中的 draft_content.json 文件")
        source = source.parent
    if not source.is_dir():
        raise ValueError(f"草稿目录不存在：{source}")
    draft_content = source / "draft_content.json"
    if not draft_content.is_file():
        raise ValueError(f"该目录不是可识别的剪映草稿，缺少 draft_content.json：{source}")
    try:
        draft = load_draft_content(source)
        analysis = analyze_full_draft_style(draft, source_path=str(source))
        track_roles = infer_track_roles(analysis)
        catalog = build_parameter_catalog(draft, track_roles=track_roles)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, VideoPackagingBundleError, PackagingCaptureError, ValueError) as exc:
        raise ValueError(f"草稿识别失败：{exc}") from exc

    categories = catalog.get("categories") if isinstance(catalog.get("categories"), Mapping) else {}
    lane_rows = catalog.get("track_lanes") if isinstance(catalog.get("track_lanes"), list) else []
    duration_us = max(0, int(draft.get("duration") or 0))
    global_element_count = 0
    for raw_lane in lane_rows:
        if not isinstance(raw_lane, Mapping):
            continue
        raw_segments = raw_lane.get("segments")
        if not isinstance(raw_segments, list):
            continue
        for raw_segment in raw_segments:
            if not isinstance(raw_segment, dict):
                continue
            start_us = max(0, int(raw_segment.get("start_us") or 0))
            end_us = max(start_us, int(raw_segment.get("end_us") or start_us))
            segment_duration_us = end_us - start_us
            duration_ratio = segment_duration_us / duration_us if duration_us else 0.0
            # 用户规则：单个元素覆盖全片超过一半，统一作为全局元素候选。
            raw_segment["duration_ratio"] = duration_ratio
            raw_segment["is_global_element"] = duration_ratio > 0.5
            raw_segment["is_packaging_evidence"] = _recognition_segment_has_packaging_evidence(raw_lane, raw_segment)
            if raw_segment["is_global_element"]:
                global_element_count += 1
    packaging_groups = _build_packaging_recognition_groups(catalog, duration_us=duration_us)
    packaging_group_count = int(packaging_groups.get("group_count") or 0)
    summary_categories = {
        key: {
            "label": str(value.get("label") or key),
            "track_count": int(value.get("track_count") or 0),
            "segment_count": int(value.get("segment_count") or 0),
        }
        for key, value in categories.items()
        if isinstance(value, Mapping)
    }
    return {
        "status": "ready",
        "mode": "read_only_no_draft_write",
        "message": (
            "未发现包装层证据：当前草稿仅显示变量层，不会强行创建包装分组。"
            if not packaging_group_count
            else "已读取草稿；候选分类需要你在时间线中确认，当前不会生成或覆盖包装包。"
        ),
        "source": {
            "draft_path": str(source),
            "draft_name": str(draft.get("name") or source.name),
            "duration_us": duration_us,
            "timeline_unit": "microseconds",
        },
        "summary": {
            "track_count": len(lane_rows),
            "segment_count": sum(len(item.get("segments") or []) for item in lane_rows if isinstance(item, Mapping)),
            "categories": summary_categories,
            "global_element_count": global_element_count,
            "global_element_threshold": 0.5,
            "packaging_group_count": packaging_group_count,
            "audio_role_needs_confirmation": bool(track_roles.get("needs_confirmation")),
            "manual_confirmation": catalog.get("confirmation") or {},
        },
        "track_roles": track_roles,
        "catalog": {
            "track_lanes": lane_rows,
            "categories": categories,
            "composition_patterns": catalog.get("composition_patterns") or {},
            "image_packaging_patterns": catalog.get("image_packaging_patterns") or {},
            "packaging_groups": packaging_groups,
            "inference": catalog.get("inference") or {},
            "confirmation": catalog.get("confirmation") or {},
            "track_index_contract": catalog.get("track_index_contract") or {},
        },
    }


def _list_editing_generated_drafts(root_value: object = None) -> dict[str, object]:
    """List successful full drafts produced by this console's editing step."""

    root = _resolve_jianying_draft_root(root_value)
    if not root.is_dir():
        return {"root": str(root), "root_exists": False, "drafts": []}
    drafts: list[dict[str, object]] = []
    seen: set[str] = set()
    candidates: list[dict] = list(_list_style_tasks(limit=2000))
    try:
        candidates.extend(_persisted_task_snapshots())
        for archive_root in RUNTIME_ARCHIVE_DIR.iterdir():
            task_dir = archive_root / "executor_tasks"
            if not task_dir.is_dir():
                continue
            for task_path in task_dir.glob("*.json"):
                try:
                    task = json.loads(task_path.read_text(encoding="utf-8"))
                except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                    continue
                if isinstance(task, dict):
                    candidates.append(task)
    except OSError:
        pass
    for task in candidates:
        if task.get("task_type") != "editing_draft" or task.get("state") != "succeeded":
            continue
        result = task.get("result")
        if not isinstance(result, Mapping):
            continue
        raw_path = str(result.get("draft_path") or "").strip()
        if not raw_path:
            continue
        path = Path(raw_path).expanduser().resolve()
        if not path.is_dir() or path.parent != root or str(path) in seen:
            continue
        seen.add(str(path))
        drafts.append({
            "name": str(result.get("draft_name") or path.name),
            "path": str(path),
            "duration_us": int(result.get("duration_us") or 0),
            "task_id": str(task.get("task_id") or ""),
            "modified_at": int(task.get("updated_at") or 0),
        })
    drafts.sort(key=lambda item: (int(item.get("modified_at") or 0), str(item.get("name") or "")), reverse=True)
    return {"root": str(root), "root_exists": True, "drafts": drafts}


def _safe_video_packaging_bundle_name(value: object) -> str:
    raw = str(value or "").strip() or "video_packaging_bundle"
    safe = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff_.-]+", "_", raw).strip("._")
    if not safe:
        raise ValueError("视频包装包名称为空或不包含有效字符")
    return safe[:80]


def _next_video_packaging_version(bundle_name: object, category: str = "") -> str:
    """为包装包或单分类模板生成独立递增版本，首次从 0.1 开始。"""

    safe_name = _safe_video_packaging_bundle_name(bundle_name)
    requested_name = str(bundle_name or "").strip()
    safe_category = str(category or "").strip()
    versions: list[tuple[int, int]] = []
    category_root = VIDEO_PACKAGING_BUNDLE_ROOT / "_category_templates"
    roots = [category_root] if safe_category else [VIDEO_PACKAGING_BUNDLE_ROOT]
    for root in roots:
        if not root.is_dir():
            continue
        for child in root.iterdir():
            if not child.is_dir():
                continue
            manifest_path = child / "bundle_manifest.json"
            if not manifest_path.is_file():
                continue
            try:
                manifest = load_bundle_manifest(child)
            except VideoPackagingBundleError:
                continue
            manifest_name = str(manifest.get("bundle_name") or "").strip()
            expected_name = f"{requested_name}_{safe_category}" if safe_category else requested_name
            if manifest_name != expected_name:
                continue
            match = re.fullmatch(r"(\d+)\.(\d+)", str(manifest.get("version") or ""))
            if match:
                versions.append((int(match.group(1)), int(match.group(2))))
    if not versions:
        return "0.1"
    major, minor = max(versions)
    return f"{major}.{minor + 1}"


def _director_package_video_style_package(package_id: object) -> dict[str, object]:
    """把编导包的镜头分类快照适配为包装构建器使用的 x+2 契约。"""

    spec = _resolve_director_package(package_id)
    return build_video_style_package(
        str(spec["label"]),
        str(spec.get("version") or "1.0"),
        list(spec.get("script_categories") or []),
        description=str(spec.get("description") or ""),
    )


def _director_package_summary(package: Mapping[str, object]) -> dict[str, object]:
    package_id = str(package.get("package_id") or "").strip()
    category_order = [*list(package.get("script_categories") or []), "opening", "ending"]
    return {
        "director_package_id": package_id,
        "name": package.get("label", ""),
        "version": package.get("version", "1.0"),
        "source": package.get("source", ""),
        "script_categories": list(package.get("script_categories") or []),
        "fixed_categories": ["opening", "ending"],
        "category_order": category_order,
        "category_labels": {key: VIDEO_PACKAGING_CATEGORY_LABELS.get(key, key) for key in category_order},
        "category_count": len(category_order),
        "structure": f"{len(package.get('script_categories') or [])}+2",
        "description": package.get("description", ""),
        "dynamic_params_schema": package.get("dynamic_params_schema", {}),
    }


def _list_director_packages() -> list[dict[str, object]]:
    return [_director_package_summary(package) for package in DIRECTOR_PACKAGE_SPECS.values()]


def _video_style_package_summary(package: Mapping[str, object]) -> dict[str, object]:
    validation = validate_video_style_package(package)
    return {
        "video_style_package_id": package.get("video_style_package_id", ""),
        "name": package.get("name", ""),
        "version": package.get("version", ""),
        "script_categories": list(package.get("script_categories") or []),
        "fixed_categories": list(package.get("fixed_categories") or []),
        "category_order": list(package.get("category_order") or []),
        "category_labels": {key: VIDEO_PACKAGING_CATEGORY_LABELS.get(key, key) for key in list(package.get("category_order") or [])},
        "category_count": validation["category_count"],
        "structure": validation["structure"],
        "description": package.get("description", ""),
        "upstream_style_profile_id": package.get("upstream_style_profile_id", ""),
    }


def _list_video_style_packages() -> list[dict[str, object]]:
    packages: list[dict[str, object]] = [_video_style_package_summary(DEFAULT_VIDEO_STYLE_PACKAGE)]
    if VIDEO_STYLE_PACKAGE_ROOT.is_dir():
        for path in sorted(VIDEO_STYLE_PACKAGE_ROOT.glob("vstyle_*.json"), key=lambda item: item.stat().st_mtime, reverse=True):
            try:
                package = load_video_style_package(path)
            except VideoStylePackageError:
                continue
            if package.get("video_style_package_id") == DEFAULT_VIDEO_STYLE_PACKAGE["video_style_package_id"]:
                packages[0] = _video_style_package_summary(package)
            else:
                packages.append(_video_style_package_summary(package))
    return packages


def _get_video_style_package(package_id: object) -> dict[str, object]:
    wanted = str(package_id or "").strip()
    if wanted == DEFAULT_VIDEO_STYLE_PACKAGE["video_style_package_id"]:
        for path in VIDEO_STYLE_PACKAGE_ROOT.glob("vstyle_*.json") if VIDEO_STYLE_PACKAGE_ROOT.is_dir() else []:
            try:
                package = load_video_style_package(path)
            except VideoStylePackageError:
                continue
            if package.get("video_style_package_id") == wanted:
                return package
        return DEFAULT_VIDEO_STYLE_PACKAGE
    for path in VIDEO_STYLE_PACKAGE_ROOT.glob("vstyle_*.json") if VIDEO_STYLE_PACKAGE_ROOT.is_dir() else []:
        try:
            package = load_video_style_package(path)
        except VideoStylePackageError:
            continue
        if package.get("video_style_package_id") == wanted:
            return package
    raise ValueError(f"找不到视频风格包：{wanted}")


def _create_video_style_package(payload: Mapping[str, object]) -> dict[str, object]:
    package = build_video_style_package(
        str(payload.get("name") or "").strip(),
        str(payload.get("version") or "1.0").strip(),
        payload.get("script_categories") if isinstance(payload.get("script_categories"), list) else [],
        style_profile_id=str(payload.get("style_profile_id") or "").strip(),
        description=str(payload.get("description") or "").strip(),
    )
    output = VIDEO_STYLE_PACKAGE_ROOT / f"{package['video_style_package_id']}.json"
    return write_video_style_package(package, output)


def _list_video_packaging_bundles() -> dict[str, object]:
    root = VIDEO_PACKAGING_BUNDLE_ROOT.resolve()
    if not root.is_dir():
        return {"root": str(root), "bundles": []}
    bundles: list[dict[str, object]] = []
    for child in sorted(root.iterdir(), key=lambda path: path.stat().st_mtime if path.exists() else 0, reverse=True):
        if not child.is_dir() or not (child / "bundle_manifest.json").is_file():
            continue
        try:
            manifest = load_bundle_manifest(child)
        except VideoPackagingBundleError:
            continue
        validation = manifest.get("validation") if isinstance(manifest.get("validation"), Mapping) else {}
        manifest_categories = {
            str(item.get("category") or "").strip()
            for item in manifest.get("categories") or []
            if isinstance(item, Mapping) and str(item.get("category") or "").strip()
        }
        # 子模板才是当前实际配置来源；历史完整包清单可能只保留了早期
        # 单分类快照，不能再用它覆盖已经提取的分类数量。
        try:
            category_templates = _list_video_packaging_category_templates(
                manifest.get("bundle_name", child.name), manifest.get("version", "1.0")
            ).get("templates", [])
        except (OSError, ValueError, TypeError):
            category_templates = []
        template_categories = {
            str(item.get("category") or "").strip()
            for item in category_templates
            if isinstance(item, Mapping) and str(item.get("category") or "").strip()
        }
        actual_categories = manifest_categories | template_categories
        required_categories = list(
            validation.get("required_categories")
            or manifest.get("required_categories")
            or VIDEO_PACKAGING_REQUIRED_CATEGORIES
        )
        full_style = manifest.get("full_draft_style") if isinstance(manifest.get("full_draft_style"), Mapping) else {}
        full_audio = full_style.get("audio") if isinstance(full_style.get("audio"), Mapping) else {}
        full_visual = full_style.get("visual") if isinstance(full_style.get("visual"), Mapping) else {}
        full_subtitles = full_style.get("subtitles") if isinstance(full_style.get("subtitles"), Mapping) else {}
        full_transitions = full_style.get("transitions") if isinstance(full_style.get("transitions"), Mapping) else {}
        bundles.append({
            "bundle_name": manifest.get("bundle_name", child.name),
            "version": manifest.get("version", ""),
            "path": str(child),
            "category_count": len(actual_categories),
            "missing_categories": [item for item in required_categories if item not in actual_categories],
            "status": validation.get("status", "unknown"),
            "video_style_package_id": (manifest.get("upstream_video_style_package") or {}).get("video_style_package_id", "") if isinstance(manifest.get("upstream_video_style_package"), Mapping) else "",
            "video_style_package_version": (manifest.get("upstream_video_style_package") or {}).get("version", "") if isinstance(manifest.get("upstream_video_style_package"), Mapping) else "",
            "structure": validation.get("structure", "历史未绑定"),
            "full_draft_style_enabled": bool(full_style),
            "full_draft_style_summary": {
                "audio_track_count": int(full_audio.get("track_count") or 0),
                "has_full_timeline_effect": bool(full_visual.get("has_full_timeline_effect")),
                "has_full_timeline_filter": bool(full_visual.get("has_full_timeline_filter")),
                "subtitle_profile_count": int(full_subtitles.get("profile_count") or 0),
                "applied_transition_count": int(full_transitions.get("applied_count") or 0),
            },
        })
    return {"root": str(root), "bundles": bundles}


def _get_video_packaging_full_draft_style(bundle_name: object, version: object) -> dict[str, object]:
    """读取已保存包装包中的全片风格分析，不重新读取源草稿。"""

    safe_name = _safe_video_packaging_bundle_name(bundle_name)
    safe_version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(version or "1.0")).strip("._") or "1.0"
    bundle_dir = (VIDEO_PACKAGING_BUNDLE_ROOT / f"{safe_name}_v{safe_version}").resolve()
    manifest_path = bundle_dir / "bundle_manifest.json"
    if not manifest_path.is_file():
        raise ValueError(f"找不到包装包：{safe_name} v{safe_version}")
    try:
        manifest = load_bundle_manifest(bundle_dir)
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc
    full_style = manifest.get("full_draft_style")
    if not isinstance(full_style, Mapping):
        return {
            "status": "not_available",
            "bundle_name": str(manifest.get("bundle_name") or safe_name),
            "version": str(manifest.get("version") or safe_version),
            "full_draft_style": {},
        }
    return {
        "status": "ready",
        "bundle_name": str(manifest.get("bundle_name") or safe_name),
        "version": str(manifest.get("version") or safe_version),
        "full_draft_style": dict(full_style),
    }


def _style_override_number(value: object, *, minimum: float, maximum: float) -> float | None:
    if isinstance(value, bool):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if number != number or number in {float("inf"), float("-inf")}:  # NaN/Infinity
        return None
    return round(minimum if number < minimum else maximum if number > maximum else number, 6)


def _style_override_text(value: object, *, maximum_length: int = 160) -> str:
    return str(value or "").strip()[:maximum_length]


def _sanitize_full_draft_style_overrides(value: object) -> dict[str, object]:
    """只接受页面支持的微调字段，避免把任意页面数据写回包装包。"""

    raw = value if isinstance(value, Mapping) else {}

    def indexed_rows(key: str, fields: Mapping[str, str]) -> list[dict[str, object]]:
        result: list[dict[str, object]] = []
        rows = raw.get(key)
        if not isinstance(rows, list):
            return result
        for index, item in enumerate(rows):
            if not isinstance(item, Mapping):
                continue
            row: dict[str, object] = {"index": index}
            for target, source in fields.items():
                if source not in item:
                    continue
                if target in {"muted", "enabled", "has_shadow"}:
                    row[target] = bool(item.get(source))
                elif target in {"font_name", "alignment", "typesetting", "audio_effect"}:
                    row[target] = _style_override_text(item.get(source))
                else:
                    limits = {
                        "volume_percent": (0.0, 300.0),
                        "coverage_percent": (0.0, 100.0),
                        "duration_percent": (0.0, 300.0),
                        "font_size": (1.0, 500.0),
                        "line_spacing": (-100.0, 100.0),
                        "shadow_alpha": (0.0, 1.0),
                        "shadow_distance": (0.0, 1000.0),
                        "shadow_smoothing": (0.0, 1000.0),
                        "border_width": (0.0, 1000.0),
                    }
                    minimum, maximum = limits.get(target, (-100000.0, 100000.0))
                    number = _style_override_number(item.get(source), minimum=minimum, maximum=maximum)
                    if number is not None:
                        row[target] = number
            if len(row) > 1:
                result.append(row)
        return result

    return {
        "audio_tracks": indexed_rows(
            "audio_tracks", {"volume_percent": "volume_percent", "muted": "muted"}
        ),
        "overall_effects": indexed_rows(
            "overall_effects", {"enabled": "enabled", "coverage_percent": "coverage_percent"}
        ),
        "overall_filters": indexed_rows(
            "overall_filters", {"enabled": "enabled", "coverage_percent": "coverage_percent"}
        ),
        "transitions": indexed_rows(
            "transitions", {"enabled": "enabled", "duration_percent": "duration_percent", "audio_effect": "audio_effect"}
        ),
        "subtitle_profiles": indexed_rows(
            "subtitle_profiles",
            {
                "font_name": "font_name",
                "font_size": "font_size",
                "alignment": "alignment",
                "typesetting": "typesetting",
                "line_spacing": "line_spacing",
                "has_shadow": "has_shadow",
                "shadow_alpha": "shadow_alpha",
                "shadow_distance": "shadow_distance",
                "shadow_smoothing": "shadow_smoothing",
                "border_width": "border_width",
            },
        ),
    }


def _save_video_packaging_style_overrides(payload: Mapping[str, object]) -> dict[str, object]:
    """保存完整视频整体风格的手动微调，不改动原始识别结果。"""

    safe_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    safe_version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(payload.get("version") or "1.0")).strip("._") or "1.0"
    bundle_dir = (VIDEO_PACKAGING_BUNDLE_ROOT / f"{safe_name}_v{safe_version}").resolve()
    if not (bundle_dir / "bundle_manifest.json").is_file():
        raise ValueError(f"找不到包装包：{safe_name} v{safe_version}")
    try:
        manifest = load_bundle_manifest(bundle_dir)
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc
    full_style = manifest.get("full_draft_style")
    if not isinstance(full_style, Mapping):
        raise ValueError("当前包装包还没有完整视频整体风格数据，不能微调")
    updated = json.loads(json.dumps(manifest, ensure_ascii=False))
    updated_style = dict(updated.get("full_draft_style") or {})
    updated_style["manual_overrides"] = _sanitize_full_draft_style_overrides(payload.get("overrides"))
    updated_style["manual_overrides_updated_at"] = int(time.time())
    updated["full_draft_style"] = updated_style
    validation = dict(updated.get("validation") or {})
    validation["full_draft_style_manual_overrides"] = True
    updated["validation"] = validation
    manifest_path = bundle_dir / "bundle_manifest.json"
    manifest_path.write_text(json.dumps(updated, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (bundle_dir / "validation_report.json").write_text(
        json.dumps(validation, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    return {
        "status": "saved",
        "bundle_name": str(updated.get("bundle_name") or safe_name),
        "version": str(updated.get("version") or safe_version),
        "full_draft_style": updated_style,
    }


def _list_video_packaging_category_templates(bundle_name: object, version: object) -> dict[str, object]:
    """List already extracted category sub-templates for one style package."""

    safe_name = _safe_video_packaging_bundle_name(bundle_name)
    safe_version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(version or "1.0")).strip("._") or "1.0"
    # 完整包装包是一次生成时的真实快照。应用某个版本时必须优先读取它，
    # 不能被同名包装包下历史的独立子模板覆盖，否则重新提取后仍会套用旧数据。
    bundle_dir = (VIDEO_PACKAGING_BUNDLE_ROOT / f"{safe_name}_v{safe_version}").resolve()
    bundle_manifest_path = bundle_dir / "bundle_manifest.json"
    if bundle_manifest_path.is_file():
        try:
            bundle_manifest = load_bundle_manifest(bundle_dir)
        except VideoPackagingBundleError:
            bundle_manifest = {}
        exact_entries = bundle_manifest.get("categories") if isinstance(bundle_manifest, Mapping) else None
        if isinstance(exact_entries, list):
            exact_templates: list[dict[str, object]] = []
            modified_at = int(bundle_dir.stat().st_mtime) if bundle_dir.exists() else 0
            for raw_entry in exact_entries:
                if not isinstance(raw_entry, Mapping):
                    continue
                category = str(raw_entry.get("category") or "").strip()
                raw_snapshot = str(raw_entry.get("raw_snapshot") or "").strip()
                if not category or not raw_snapshot:
                    continue
                raw_dir = (bundle_dir / Path(raw_snapshot)).resolve()
                try:
                    raw_dir.relative_to(bundle_dir)
                except ValueError:
                    continue
                draft_content_path = raw_dir / "draft_content.json"
                if not draft_content_path.is_file():
                    continue
                category_dir = raw_dir.parent
                category_manifest: Mapping[str, object] = {}
                category_manifest_path = category_dir / "category_manifest.json"
                if category_manifest_path.is_file():
                    try:
                        loaded = json.loads(category_manifest_path.read_text(encoding="utf-8"))
                        if isinstance(loaded, Mapping):
                            category_manifest = loaded
                    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                        category_manifest = {}
                category_validation = category_manifest.get("validation") if isinstance(category_manifest.get("validation"), Mapping) else {}
                collected_components = category_validation.get("collected_components") if isinstance(category_validation.get("collected_components"), Mapping) else raw_entry.get("collected_components")
                if not isinstance(collected_components, Mapping):
                    collected_components = {}
                exact_templates.append({
                    "category": category,
                    "category_label": raw_entry.get("label") or VIDEO_PACKAGING_CATEGORY_LABELS.get(category, category),
                    "version": str(bundle_manifest.get("version") or safe_version),
                    "path": str(bundle_dir),
                    "category_output_dir": str(category_dir),
                    "source_draft": ((raw_entry.get("source") or {}).get("source_path", "") if isinstance(raw_entry.get("source"), Mapping) else ""),
                    "description": "已保存完整草稿、特效、转场和相对时间数据。",
                    "collected_components": {
                        key: int(collected_components.get(key) or 0)
                        for key in ("effects", "keyframes", "transitions", "text_templates")
                    },
                    "modified_at": modified_at,
                    "history_count": 1,
                })
            if exact_templates:
                exact_templates.sort(key=lambda item: (str(item.get("category") or ""), str(item.get("version") or "")))
                return {
                    "root": str(bundle_dir),
                    "bundle_name": safe_name,
                    "version": safe_version,
                    "templates": exact_templates,
                    "history_count": 1,
                }
    root = VIDEO_PACKAGING_BUNDLE_ROOT / "_category_templates"
    # 子模板版本独立于完整包装包版本；按名称筛选后再从 manifest 读取分类和版本。
    prefix = f"{safe_name}_v"
    latest_by_category: dict[str, tuple[tuple[int, int], int, dict[str, object]]] = {}
    history_count = 0
    if not root.is_dir():
        return {"root": str(root), "bundle_name": safe_name, "version": safe_version, "templates": [], "history_count": 0}
    for child in sorted(root.iterdir(), key=lambda path: path.stat().st_mtime if path.exists() else 0, reverse=True):
        if not child.is_dir() or not child.name.startswith(prefix):
            continue
        try:
            manifest = load_bundle_manifest(child)
        except VideoPackagingBundleError:
            continue
        history_count += 1
        entries = manifest.get("categories") if isinstance(manifest.get("categories"), list) else []
        entry = entries[0] if entries and isinstance(entries[0], Mapping) else {}
        source = entry.get("source") if isinstance(entry.get("source"), Mapping) else {}
        category = str(entry.get("category") or child.name.removeprefix(prefix)).strip()
        category_manifest = {}
        category_manifest_path = child / "categories" / category / "category_manifest.json"
        if category_manifest_path.is_file():
            try:
                loaded_category_manifest = json.loads(category_manifest_path.read_text(encoding="utf-8"))
                if isinstance(loaded_category_manifest, Mapping):
                    category_manifest = dict(loaded_category_manifest)
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                category_manifest = {}
        category_validation = category_manifest.get("validation") if isinstance(category_manifest.get("validation"), Mapping) else {}
        collected_components = category_validation.get("collected_components") if isinstance(category_validation.get("collected_components"), Mapping) else entry.get("collected_components")
        if not isinstance(collected_components, Mapping):
            fallback_draft = category_manifest.get("template_draft") or category_manifest.get("raw_draft")
            collected_components = summarize_template_components(fallback_draft) if isinstance(fallback_draft, Mapping) else {}
        collected_components = {
            key: int(collected_components.get(key) or 0)
            for key in ("effects", "keyframes", "transitions", "text_templates")
        }
        version_text = str(manifest.get("version") or safe_version)
        match = re.fullmatch(r"(\d+)\.(\d+)", version_text)
        version_key = (int(match.group(1)), int(match.group(2))) if match else (0, 0)
        try:
            modified_at = int(child.stat().st_mtime)
        except OSError:
            modified_at = 0
        item = {
            "category": category,
            "category_label": entry.get("label") or VIDEO_PACKAGING_CATEGORY_LABELS.get(category, category),
            "version": version_text,
            "path": str(child),
            "category_output_dir": str(child / "categories" / category),
            "source_draft": source.get("source_path", ""),
            "description": "已保存完整草稿、特效、转场和相对时间数据。",
            "collected_components": collected_components,
            "modified_at": modified_at,
            "history_count": history_count,
        }
        current = latest_by_category.get(category)
        if current is None or (version_key, modified_at) > (current[0], current[1]):
            latest_by_category[category] = (version_key, modified_at, item)
    templates = [item for _version_key, _modified_at, item in latest_by_category.values()]
    templates.sort(key=lambda item: (str(item.get("category") or ""), str(item.get("version") or "")))
    return {
        "root": str(root),
        "bundle_name": safe_name,
        "version": safe_version,
        "templates": templates,
        "history_count": history_count,
    }


def _coerce_transition_time_us(value: object, unit: object = "microseconds") -> int | None:
    """把上游转场时间安全归一到整数微秒，容忍数字字符串和小数。"""

    if isinstance(value, bool):
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number) or number < 0:
        return None
    normalized_unit = str(unit or "microseconds").strip().lower().replace("μ", "µ")
    if normalized_unit in {"ms", "millisecond", "milliseconds"}:
        number *= 1_000
    elif normalized_unit not in {"us", "µs", "microsecond", "microseconds"}:
        return None
    return int(round(number))


def _resolve_editing_packaging_application(
    payload: Mapping[str, object],
    shot_script: Sequence[Mapping[str, object]],
    upstream_transition_points: Sequence[Mapping[str, object]] = (),
    upstream_transition_unit: object = "microseconds",
    opening_title: object = "",
) -> dict[str, object] | None:
    """把页面选择的包装包解析为原生写入层可消费的只读模板路径。"""

    selected = payload.get("packaging_bundle")
    if not isinstance(selected, Mapping):
        return None
    bundle_name = str(selected.get("bundle_name") or "").strip()
    version = str(selected.get("version") or "1.0").strip()
    if not bundle_name:
        return None
    listing = _list_video_packaging_category_templates(bundle_name, version)
    templates = listing.get("templates") if isinstance(listing.get("templates"), list) else []
    categories: dict[str, dict[str, object]] = {}
    for item in templates:
        if not isinstance(item, Mapping):
            continue
        category = str(item.get("category") or "").strip()
        output_dir = Path(str(item.get("category_output_dir") or "")).expanduser()
        draft_path = output_dir / "raw_snapshot" / "draft_content.json"
        if category and draft_path.is_file():
            categories[category] = {
                "category": category,
                "version": str(item.get("version") or version),
                "category_output_dir": str(output_dir.resolve()),
                "draft_content_path": str(draft_path.resolve()),
                "collected_components": dict(item.get("collected_components") or {})
                if isinstance(item.get("collected_components"), Mapping)
                else {},
            }
    if not categories:
        raise ValueError(f"已选择包装包“{bundle_name}”，但没有可应用的分类模板数据")

    def category_for_shot(item: Mapping[str, object]) -> str:
        media_type = str(item.get("media_type") or item.get("shot_class") or "").strip()
        return {
            "static_image": "image",
            "digital_human_video": "digital_human",
            "aigc_video": "aigc",
            "explanation_video": "explanation",
            "overlay_explanation": "mixed_explanation",
            "image": "image",
            "digital_human": "digital_human",
        }.get(media_type, media_type if media_type in VIDEO_PACKAGING_REQUIRED_CATEGORIES else "")

    shot_categories = {
        str(item.get("shot_id") or ""): category_for_shot(item)
        for item in shot_script
        if str(item.get("shot_id") or "").strip()
    }
    ordered_shot_ids = [
        str(item.get("shot_id") or "")
        for item in shot_script
        if str(item.get("shot_id") or "").strip()
    ]
    shot_ids = set(ordered_shot_ids)
    transition_points: list[dict[str, object]] = []
    for raw_point in upstream_transition_points:
        if not isinstance(raw_point, Mapping):
            continue
        from_shot_id = str(raw_point.get("from_shot_id") or "").strip()
        to_shot_id = str(raw_point.get("to_shot_id") or "").strip()
        if not from_shot_id or not to_shot_id or from_shot_id not in shot_ids or to_shot_id not in shot_ids:
            continue
        at_us = _coerce_transition_time_us(raw_point.get("at_us"), upstream_transition_unit)
        if at_us is None:
            continue
        raw_index = raw_point.get("transition_index")
        try:
            transition_index = int(raw_index)
        except (TypeError, ValueError):
            transition_index = len(transition_points)
        transition_points.append({
            "transition_index": transition_index,
            "at_us": at_us,
            "from_shot_id": from_shot_id,
            "to_shot_id": to_shot_id,
            "from_group_id": str(raw_point.get("from_group_id") or ""),
            "to_group_id": str(raw_point.get("to_group_id") or ""),
            "classification_level": str(
                raw_point.get("classification_level")
                or raw_point.get("transition_level")
                or (
                    "level_3"
                    if raw_point.get("from_group_id")
                    and raw_point.get("from_group_id") == raw_point.get("to_group_id")
                    else "level_2"
                )
            ),
            "default_enabled": raw_point.get(
                "default_enabled",
                not (
                    raw_point.get("from_group_id")
                    and raw_point.get("from_group_id") == raw_point.get("to_group_id")
                ),
            ),
            "enabled": raw_point.get("enabled"),
        })
    full_draft_style: dict[str, object] = {}
    full_draft_source = ""
    effect_overrides: dict[str, dict[str, object]] = {}
    try:
        full_style_result = _get_video_packaging_full_draft_style(bundle_name, version)
        if full_style_result.get("status") == "ready":
            candidate = full_style_result.get("full_draft_style")
            if isinstance(candidate, Mapping):
                full_draft_style = dict(candidate)
                source = candidate.get("source")
                if isinstance(source, Mapping):
                    full_draft_source = str(source.get("path") or "").strip()
            raw_overrides = full_style_result.get("effect_overrides")
            if isinstance(raw_overrides, Mapping):
                effect_overrides = {
                    str(name): dict(values)
                    for name, values in raw_overrides.items()
                    if str(name).strip() and isinstance(values, Mapping)
                }
    except (OSError, ValueError, VideoPackagingBundleError):
        # 旧包装包可能只有分类母版，没有完整视频分析；分类模板仍可继续应用。
        full_draft_style = {}
    return {
        "bundle_name": bundle_name,
        "version": version,
        # 标题是全片级字段；应用层再次收口长度，避免旧稿或手工输入把
        # 超长标题带入片头文字模板。
        "opening_title": str(opening_title or "").strip()[:12],
        "categories": categories,
        "shot_categories": shot_categories,
        "first_shot_id": ordered_shot_ids[0] if ordered_shot_ids else "",
        "last_shot_id": ordered_shot_ids[-1] if ordered_shot_ids else "",
        "transition_timeline_unit": "microseconds",
        "transition_tolerance_us": TRANSITION_POINT_TOLERANCE_US,
        "transition_timeline_source": "upstream.transition_points" if transition_points else "none",
        "transition_points": transition_points,
        "full_draft_style": full_draft_style,
        "full_draft_source": full_draft_source,
        "effect_overrides": effect_overrides,
        "available_categories": sorted(categories),
        "missing_categories": [
            category for category in VIDEO_PACKAGING_REQUIRED_CATEGORIES if category not in categories
        ],
    }


def _create_video_packaging_bundle(payload: Mapping[str, object]) -> dict[str, object]:
    categories = payload.get("categories")
    if not isinstance(categories, Mapping):
        raise ValueError("categories 必须是分类到母版草稿路径的对象")
    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"剪映草稿父目录不存在：{draft_root}")
    director_package_id = str(
        payload.get("director_package") or payload.get("director_package_id") or ""
    ).strip()
    style_package_id = str(payload.get("video_style_package_id") or "").strip()
    if director_package_id:
        director_package = _resolve_director_package(director_package_id)
        video_style_package = _director_package_video_style_package(director_package["package_id"])
    elif style_package_id:
        # Keep old clients and already saved drafts compatible while the UI
        # moves to the explicit director-package contract.
        director_package = None
        video_style_package = _get_video_style_package(style_package_id)
    else:
        raise ValueError("新包装包必须绑定上游编导包")
    required_categories = list(video_style_package.get("required_categories") or [])
    category_sources: dict[str, Path] = {}
    for category, raw_path in categories.items():
        category = str(category).strip()
        # “无”是合法的缺省配置，不创建空模板，也不参与后续提取。
        if str(raw_path or "").strip() in {"__none__", "none", "无"}:
            continue
        if category not in required_categories:
            raise ValueError(f"不支持的包装分类：{category}")
        source = _draft_directory(raw_path, f"{VIDEO_PACKAGING_CATEGORY_LABELS.get(category, category)}母版草稿")
        if source.parent != draft_root:
            raise ValueError(f"{VIDEO_PACKAGING_CATEGORY_LABELS[category]}母版必须位于选择的剪映草稿父目录下")
        category_sources[category] = source
    full_draft_value = (
        payload.get("full_draft")
        or payload.get("full_video_draft")
        or payload.get("complete_draft")
    )
    full_draft_source: Path | None = None
    if str(full_draft_value or "").strip():
        full_draft_source = _draft_directory(full_draft_value, "完整视频风格识别草稿")
        if full_draft_source.parent != draft_root:
            raise ValueError("完整视频识别草稿必须位于选择的剪映草稿父目录下")
    extra = [category for category in category_sources if category not in required_categories]
    if extra:
        raise ValueError("包装包存在上游风格包未声明的分类：" + "、".join(VIDEO_PACKAGING_CATEGORY_LABELS.get(item, item) for item in extra))
    bundle_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = _next_video_packaging_version(bundle_name)
    output_dir = VIDEO_PACKAGING_BUNDLE_ROOT / f"{bundle_name}_v{version}"
    try:
        result = build_video_packaging_bundle(
            category_sources,
            output_dir,
            bundle_name=bundle_name,
            version=version,
            # 缺省分类允许为空；清单仍保留完整 x+2 结构，并记录 missing_categories。
            require_all_categories=False,
            video_style_package=video_style_package,
            full_draft_source=full_draft_source,
        )
        if director_package is not None:
            manifest_path = output_dir / "bundle_manifest.json"
            manifest = load_bundle_manifest(output_dir)
            manifest["upstream_director_package"] = {
                "director_package_id": director_package["package_id"],
                "name": director_package["label"],
                "version": director_package.get("version", "1.0"),
                "source": director_package.get("source", ""),
                "script_categories": list(director_package.get("script_categories") or []),
                "category_order": required_categories,
                "structure": f"{len(director_package.get('script_categories') or [])}+2",
            }
            manifest["validation"] = {
                **dict(manifest.get("validation") or {}),
                "upstream_director_package_bound": True,
            }
            manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            result = {**manifest, "output_dir": str(output_dir)}
        return result
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc


def _analyze_video_packaging_full_draft(payload: Mapping[str, object]) -> dict[str, object]:
    """预览完整视频草稿的全片级风格识别结果，不写入包装包。"""

    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"剪映草稿父目录不存在：{draft_root}")
    source = _draft_directory(
        payload.get("full_draft") or payload.get("full_video_draft") or payload.get("complete_draft"),
        "完整视频风格识别草稿",
    )
    if source.parent != draft_root:
        raise ValueError("完整视频识别草稿必须位于选择的剪映草稿父目录下")
    draft = load_draft_content(source)
    return {
        "status": "analyzed",
        "source_draft": str(source),
        "analysis": analyze_full_draft_style(draft, source_path=str(source)),
        "write_policy": "preview_only",
    }


def _diff_video_packaging_full_draft(payload: Mapping[str, object]) -> dict[str, object]:
    """读取修改后的剪映草稿，并返回包装包可回写的参数差异。"""

    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"剪映草稿父目录不存在：{draft_root}")
    source = _draft_directory(
        payload.get("full_draft") or payload.get("full_video_draft") or payload.get("complete_draft"),
        "微调后的完整视频草稿",
    )
    if source.parent != draft_root:
        raise ValueError("微调后的草稿必须位于选择的剪映草稿父目录下")
    bundle_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(payload.get("version") or "1.0")).strip("._") or "1.0"
    baseline_result = _get_video_packaging_full_draft_style(bundle_name, version)
    baseline = baseline_result.get("full_draft_style") if isinstance(baseline_result.get("full_draft_style"), Mapping) else {}
    if not baseline:
        raise ValueError(f"包装包 {bundle_name} v{version} 没有完整视频基线，无法识别微调")
    current_draft = load_draft_content(source)
    current = analyze_full_draft_style(current_draft, source_path=str(source))
    baseline_timing = None
    baseline_source_path = dict(baseline.get("source") or {}).get("path") if isinstance(baseline.get("source"), Mapping) else ""
    if baseline_source_path:
        try:
            baseline_timing = normalize_template_timing(load_draft_content(Path(str(baseline_source_path))))
        except (OSError, ValueError, VideoPackagingBundleError):
            baseline_timing = None
    try:
        current_timing = normalize_template_timing(current_draft)
    except (OSError, ValueError, VideoPackagingBundleError):
        current_timing = None
    diff = diff_full_draft_style(
        baseline,
        current,
        baseline_timing=baseline_timing,
        current_timing=current_timing,
    )
    return {
        **diff,
        "bundle_name": bundle_name,
        "version": version,
        "baseline_source": dict(baseline.get("source") or {}) if isinstance(baseline.get("source"), Mapping) else {},
        "current_source": dict(current.get("source") or {}) if isinstance(current.get("source"), Mapping) else {},
        "write_policy": "diff_preview_only",
        "source_draft_mutated": False,
    }


def _save_video_packaging_full_draft_style(payload: Mapping[str, object]) -> dict[str, object]:
    """把完整视频识别结果增量保存到已有包装包。"""

    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"剪映草稿父目录不存在：{draft_root}")
    source = _draft_directory(
        payload.get("full_draft") or payload.get("full_video_draft") or payload.get("complete_draft"),
        "完整视频风格识别草稿",
    )
    if source.parent != draft_root:
        raise ValueError("完整视频识别草稿必须位于选择的剪映草稿父目录下")
    bundle_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(payload.get("version") or "1.0")).strip("._") or "1.0"
    bundle_dir = (VIDEO_PACKAGING_BUNDLE_ROOT / f"{bundle_name}_v{version}").resolve()
    if not (bundle_dir / "bundle_manifest.json").is_file():
        raise ValueError(f"找不到要补充全片风格数据的包装包：{bundle_dir}")
    try:
        return update_bundle_full_draft_style(bundle_dir, source)
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc


def _extract_video_packaging_category_template(payload: Mapping[str, object]) -> dict[str, object]:
    """Extract one category draft into a reusable sub-template package."""

    category = str(payload.get("category") or "").strip()
    if category not in VIDEO_PACKAGING_CATEGORY_LABELS:
        raise ValueError(f"不支持的包装分类：{category}")
    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"剪映草稿父目录不存在：{draft_root}")
    source = _draft_directory(payload.get("source_draft"), f"{VIDEO_PACKAGING_CATEGORY_LABELS[category]}母版草稿")
    if source.parent != draft_root:
        raise ValueError(f"{VIDEO_PACKAGING_CATEGORY_LABELS[category]}母版必须位于选择的剪映草稿父目录下")
    bundle_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = _next_video_packaging_version(bundle_name, category)
    output_dir = VIDEO_PACKAGING_BUNDLE_ROOT / "_category_templates" / f"{bundle_name}_v{version}_{category}"
    if output_dir.exists():
        manifest_path = output_dir / "bundle_manifest.json"
        if manifest_path.is_file():
            manifest = load_bundle_manifest(output_dir)
            return {
                **manifest,
                "output_dir": str(output_dir),
                "category_output_dir": str(output_dir / "categories" / category),
                "source_draft": str(source),
                "reused": True,
            }
        raise ValueError(f"子模板输出目录已存在但不完整，为避免覆盖已停止：{output_dir}")
    try:
        result = build_video_packaging_bundle(
            {category: source},
            output_dir,
            bundle_name=f"{bundle_name}_{category}",
            version=version,
            require_all_categories=False,
        )
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc
    result["category_output_dir"] = str(output_dir / "categories" / category)
    result["source_draft"] = str(source)
    result["category"] = category
    result["version"] = version
    return result


def _rename_video_packaging_bundle(payload: Mapping[str, object]) -> dict[str, object]:
    """重命名已有包装包及其分类子模板目录，避免只修改输入框显示。"""

    old_name = _safe_video_packaging_bundle_name(payload.get("old_bundle_name"))
    new_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(payload.get("version") or "1.0")).strip("._") or "1.0"
    if old_name == new_name:
        return {
            "status": "unchanged",
            "old_bundle_name": old_name,
            "bundle_name": new_name,
            "version": version,
            "renamed_count": 0,
        }

    root = VIDEO_PACKAGING_BUNDLE_ROOT.resolve()
    category_root = (root / "_category_templates").resolve()
    candidates: list[tuple[Path, str, str]] = []

    def read_manifest(path: Path) -> dict[str, object] | None:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return None
        return dict(value) if isinstance(value, Mapping) else None

    if root.is_dir():
        for child in root.iterdir():
            if not child.is_dir() or child.name == "_category_templates":
                continue
            manifest_path = child / "bundle_manifest.json"
            manifest = read_manifest(manifest_path)
            if not manifest or str(manifest.get("bundle_name") or "").strip() != old_name:
                continue
            manifest_version = re.sub(
                r"[^0-9A-Za-z_.-]+",
                "_",
                str(manifest.get("version") or version),
            ).strip("._") or version
            candidates.append((child, "", manifest_version))

    if category_root.is_dir():
        for child in category_root.iterdir():
            if not child.is_dir():
                continue
            manifest_path = child / "bundle_manifest.json"
            manifest = read_manifest(manifest_path)
            if not manifest:
                continue
            entries = manifest.get("categories") if isinstance(manifest.get("categories"), list) else []
            entry = entries[0] if entries and isinstance(entries[0], Mapping) else {}
            category = str(entry.get("category") or "").strip()
            if category and str(manifest.get("bundle_name") or "").strip() == f"{old_name}_{category}":
                category_version = re.sub(
                    r"[^0-9A-Za-z_.-]+",
                    "_",
                    str(manifest.get("version") or version),
                ).strip("._") or version
                candidates.append((child, category, category_version))

    rename_plan: list[tuple[Path, Path, str]] = []
    planned_targets: set[Path] = set()
    for source, category, manifest_version in candidates:
        target_parent = category_root if category else root
        target_name = (
            f"{new_name}_v{manifest_version}_{category}"
            if category
            else f"{new_name}_v{manifest_version}"
        )
        target = (target_parent / target_name).resolve()
        if target in planned_targets or (target != source.resolve() and target.exists()):
            # Display names are user-controlled. Keep old physical folders and
            # allocate an internal suffix when the requested name already exists.
            suffix = 2
            while target in planned_targets or (target != source.resolve() and target.exists()):
                target = (target_parent / f"{target_name}__{suffix}").resolve()
                suffix += 1
        planned_targets.add(target)
        rename_plan.append((source, target, category))

    renamed: list[dict[str, str]] = []
    for source, target, category in rename_plan:
        if source.resolve() != target:
            source.rename(target)
        manifest = read_manifest(target / "bundle_manifest.json") or {}
        manifest["bundle_name"] = f"{new_name}_{category}" if category else new_name
        target_manifest = target / "bundle_manifest.json"
        target_manifest.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        renamed.append({"from": str(source), "to": str(target), "category": category})

    return {
        "status": "renamed" if renamed else "name_ready",
        "old_bundle_name": old_name,
        "bundle_name": new_name,
        "version": version,
        "renamed_count": len(renamed),
        "renamed": renamed,
    }


def _archive_video_packaging_bundle(payload: Mapping[str, object]) -> dict[str, object]:
    """从当前包装包列表移除一个包装包，但把完整目录移入归档区。"""

    bundle_name = _safe_video_packaging_bundle_name(payload.get("bundle_name"))
    version = re.sub(
        r"[^0-9A-Za-z_.-]+", "_", str(payload.get("version") or "1.0")
    ).strip("._") or "1.0"
    root = VIDEO_PACKAGING_BUNDLE_ROOT.resolve()
    if not root.is_dir():
        raise ValueError("当前还没有可删除的包装包")

    requested_path = str(payload.get("bundle_path") or "").strip()
    candidate: Path | None = None
    if requested_path:
        path = Path(requested_path).expanduser().resolve()
        if path.parent != root or path.name in {"_archive", "_category_templates"}:
            raise ValueError("包装包路径不合法")
        candidate = path
    else:
        exact = (root / f"{bundle_name}_v{version}").resolve()
        if exact.parent == root and exact.is_dir():
            candidate = exact
        else:
            # 重命名冲突时物理目录可能带 __2 后缀，因此按清单再查一次。
            for child in root.iterdir():
                if not child.is_dir() or child.name in {"_archive", "_category_templates"}:
                    continue
                manifest_path = child / "bundle_manifest.json"
                if not manifest_path.is_file():
                    continue
                try:
                    manifest = load_bundle_manifest(child)
                except VideoPackagingBundleError:
                    continue
                manifest_version = re.sub(
                    r"[^0-9A-Za-z_.-]+", "_", str(manifest.get("version") or "1.0")
                ).strip("._") or "1.0"
                if str(manifest.get("bundle_name") or "").strip() == bundle_name and manifest_version == version:
                    candidate = child.resolve()
                    break

    if candidate is None or candidate.parent != root or not candidate.is_dir():
        raise ValueError(f"找不到指定的包装包：{bundle_name} v{version}")
    try:
        manifest = load_bundle_manifest(candidate)
    except VideoPackagingBundleError as exc:
        raise ValueError(str(exc)) from exc
    actual_name = str(manifest.get("bundle_name") or "").strip()
    actual_version = re.sub(
        r"[^0-9A-Za-z_.-]+", "_", str(manifest.get("version") or version)
    ).strip("._") or version
    if actual_name != bundle_name or actual_version != version:
        raise ValueError("包装包清单与删除请求不一致，已停止以避免误删")

    archive_root = (root / "_archive").resolve()
    archive_root.mkdir(parents=True, exist_ok=True)
    archive_id = f"{candidate.name}_{time.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:8]}"
    archive_dir = (archive_root / archive_id).resolve()
    if archive_dir.parent != archive_root:
        raise ValueError("包装包归档路径不合法")
    shutil.move(str(candidate), str(archive_dir))
    (archive_dir / "archive_manifest.json").write_text(
        json.dumps(
            {
                "schema_version": "video_packaging_bundle_archive_v1",
                "archived_at": int(time.time()),
                "bundle_name": bundle_name,
                "version": version,
                "source_dir": str(candidate),
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    return {
        "status": "archived",
        "bundle_name": bundle_name,
        "version": version,
        "archive_dir": str(archive_dir),
        "message": "包装包已从当前列表移除；原始包装包文件已归档保留。",
    }


def _validate_opening_template_inputs(
    template_dir: Path, full_dir: Path, draft_root: Path
) -> tuple[dict, dict]:
    """Enforce the local folder and five-second template governance contract."""

    if template_dir == full_dir:
        raise ValueError("片头模板草稿和完整目标草稿不能是同一个草稿")
    if template_dir.parent != draft_root or full_dir.parent != draft_root:
        raise ValueError("片头模板、完整目标草稿和输出目录必须位于同一个剪映草稿目录")
    template_info = _draft_info_for_validation(template_dir, "片头模板草稿")
    full_info = _draft_info_for_validation(full_dir, "完整目标草稿")
    template_duration = int(template_info.get("duration") or 0)
    if template_duration < OPENING_TEMPLATE_WINDOW_US:
        raise ValueError("片头模板草稿时长必须至少为 5 秒")
    if int(full_info.get("duration") or 0) <= 0:
        raise ValueError("完整目标草稿时长无效")
    return template_info, full_info


def _run_opening_template_task(task_id: str, payload: dict) -> None:
    """Apply a five-second opening template to a full Jianying draft."""

    def report(stage: str, progress: int, message: str) -> None:
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, progress)), message=message)

    try:
        report("loading_drafts", 10, "正在读取片头模板草稿和完整目标草稿")
        template_dir = _draft_directory(payload.get("template_draft"), "片头模板草稿")
        full_dir = _draft_directory(payload.get("full_draft"), "完整目标草稿")
        output_root = _resolve_jianying_draft_root(payload.get("draft_root"))
        if not output_root.is_dir():
            raise ValueError(f"草稿保存目录不存在或不是文件夹：{output_root}")
        _validate_opening_template_inputs(template_dir, full_dir, output_root)
        output_name = _opening_output_name(
            payload.get("output_name") or f"{full_dir.name}_套用片头模板"
        )
        output_dir = (output_root / output_name).resolve()
        if output_dir.exists():
            raise FileExistsError(f"目标草稿已存在，为避免覆盖已停止：{output_dir}")
        report("merging_opening_template", 42, "正在合并前 5 秒视频、音频、特效和文字模板轨")
        from tools.apply_opening_template_to_full_draft import build as apply_opening_template

        result = apply_opening_template(template_dir, full_dir, output_dir)
        report("validating_output", 88, "正在检查输出草稿时长、媒体路径和前 5 秒轨道")
        if int(result.get("missing_media_count") or 0) != 0:
            raise ValueError(f"输出草稿存在 {result['missing_media_count']} 个缺失媒体路径")
        result_payload = {
            **result,
            "output_name": output_name,
            "draft_root": str(output_root),
            "template_draft": str(template_dir),
            "full_draft": str(full_dir),
        }
        _set_task(
            task_id,
            state="succeeded",
            stage="opening_template_applied",
            progress=100,
            message="片头模板已套用并完成结构、时长和媒体路径校验",
            result=result_payload,
        )
    except Exception as exc:
        detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:600]
        TASK_LOGGER.exception("opening template task %s crashed", task_id)
        _set_task(
            task_id,
            state="failed",
            stage="opening_template_failed",
            progress=100,
            message=f"片头模板套用失败：{type(exc).__name__}：{detail or '无错误详情'}",
            result={"error": detail},
        )


def _create_opening_template_task(payload: dict) -> dict:
    template_dir = _draft_directory(payload.get("template_draft"), "片头模板草稿")
    full_dir = _draft_directory(payload.get("full_draft"), "完整目标草稿")
    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"草稿保存目录不存在或不是文件夹：{draft_root}")
    _validate_opening_template_inputs(template_dir, full_dir, draft_root)
    output_name = _opening_output_name(
        payload.get("output_name") or f"{full_dir.name}_套用片头模板"
    )
    output_dir = (draft_root / output_name).resolve()
    if output_dir.exists():
        raise FileExistsError(f"目标草稿已存在，为避免覆盖已停止：{output_dir}")
    generated_paths = {
        Path(str(item.get("path") or "")).resolve()
        for item in _list_editing_generated_drafts(draft_root).get("drafts", [])
        if item.get("path")
    }
    if full_dir not in generated_paths:
        raise ValueError("完整目标草稿必须来自本模块已生成的草稿")
    for item in _list_style_tasks(limit=2000):
        if item.get("task_type") == "opening_template_apply" and item.get("state") in {"queued", "running"}:
            return item
    task_id = uuid.uuid4().hex
    now = int(time.time())
    task = {
        "task_id": task_id,
        "task_type": "opening_template_apply",
        "template_draft": str(template_dir),
        "full_draft": str(full_dir),
        "draft_root": str(draft_root),
        "output_name": output_name,
        "state": "queued",
        "stage": "queued",
        "progress": 0,
        "message": "片头模板套用任务正在排队",
        "created_at": now,
        "updated_at": now,
    }
    with STYLE_TASKS_LOCK:
        STYLE_TASKS[task_id] = task
    try:
        _persist_task_required(task) if task.get("task_type") else _persist_task(task)
    except TaskPersistenceError:
        with STYLE_TASKS_LOCK:
            STYLE_TASKS.pop(task_id, None)
        raise
    threading.Thread(target=_run_opening_template_task, args=(task_id, dict(payload)), daemon=True).start()
    return _task_snapshot(task_id) or task


class _TaskInterrupted(RuntimeError):
    """内部信号：用户已停止任务，工作线程不得再写入成功或失败终态。"""


def _configure_task_logger() -> logging.Logger:
    """Keep executor failures inspectable after the local service exits."""
    logger = logging.getLogger("video_production_console.tasks")
    if logger.handlers:
        return logger
    logger.setLevel(logging.INFO)
    try:
        STYLE_TASK_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        handler: logging.Handler = logging.FileHandler(STYLE_TASK_LOG_PATH, encoding="utf-8")
        handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s"))
    except OSError:
        # The console must remain usable in a restricted desktop sandbox.
        # Persistence is best-effort and must never take down the HTTP service.
        handler = logging.NullHandler()
    logger.addHandler(handler)
    return logger


TASK_LOGGER = _configure_task_logger()


def _profile_summary(record: dict) -> dict:
    profile = record.get("style_profile", {})
    overview = profile.get("overview", "") if isinstance(profile, dict) else ""
    if record.get("review_status") == "APPROVED" and str(overview).strip() == PENDING_PROFILE_OVERVIEW:
        overview = APPROVED_PROFILE_OVERVIEW
    enabled_value = record.get("enabled")
    if enabled_value is None:
        enabled_value = str(record.get("review_status") or "").upper() == "APPROVED"
    elif isinstance(enabled_value, str):
        enabled_value = enabled_value.strip().lower() not in {"", "0", "false", "no", "off", "disabled"}
    raw_sample_count = record.get("sample_count")
    try:
        sample_count = int(raw_sample_count or 0)
    except (TypeError, ValueError):
        sample_count = 0
    # 新版 Writing-DNA 记录会把门禁写入 style_profile。历史风格包没有
    # 这份证据，不能因为它曾经是 APPROVED 就推断达到生产标准；保留在
    # 历史/兼容列表中，但明确标记为实验版并从新版生产选择中排除。
    raw_gate = profile.get("writing_dna_gate") if isinstance(profile, dict) else None
    gate_is_explicit = isinstance(raw_gate, Mapping)
    if gate_is_explicit:
        writing_dna_gate = dict(raw_gate)
        try:
            gate_sample_count = int(writing_dna_gate.get("sample_count", sample_count) or 0)
        except (TypeError, ValueError):
            gate_sample_count = sample_count
        writing_dna_gate["sample_count"] = gate_sample_count
        writing_dna_gate["formal"] = writing_dna_gate.get("formal") is True
        writing_dna_gate["status"] = str(writing_dna_gate.get("status") or "").strip().upper() or (
            "READY_FOR_REVIEW" if writing_dna_gate["formal"] and gate_sample_count >= 30 else "EXPERIMENTAL"
        )
    else:
        writing_dna_gate = {
            "status": "EXPERIMENTAL",
            "formal": False,
            "sample_count": sample_count,
            "reliability_note": "历史风格包缺少 Writing-DNA 门禁记录，只能作为兼容/实验资产。",
        }
    production_eligible = bool(
        gate_is_explicit
        and writing_dna_gate.get("formal") is True
        and int(writing_dna_gate.get("sample_count") or 0) >= 30
        and str(record.get("review_status") or "").upper() == "APPROVED"
        and bool(enabled_value)
    )
    raw_source_ids = profile.get("knowledge_source_ids") if isinstance(profile, dict) else None
    knowledge_source_ids = [str(item) for item in raw_source_ids if str(item).strip()] if isinstance(raw_source_ids, (list, tuple, set)) else []
    knowledge_source_versions = dict(profile.get("knowledge_source_versions") or {}) if isinstance(profile, dict) and isinstance(profile.get("knowledge_source_versions"), Mapping) else {}
    return {
        "style_profile_id": record.get("style_profile_id"),
        "style_profile_version": record.get("style_profile_version", ""),
        "current_version": record.get("current_version") or record.get("style_profile_version", ""),
        "enabled": bool(enabled_value),
        "version_count": int(record.get("version_count") or len(record.get("version_history") or [])),
        "versions": list(record.get("version_history") or []) if isinstance(record.get("version_history"), list) else [],
        "review_status": record.get("review_status"),
        "created_at": record.get("created_at"),
        "last_used_at": record.get("last_used_at", ""),
        "usage_count": record.get("usage_count", 0),
        "sample_count": sample_count,
        "writing_dna_gate": writing_dna_gate,
        "production_eligible": production_eligible,
        "production_eligibility_reason": (
            "已审核、已启用且 Writing-DNA 样本门禁通过"
            if production_eligible
            else (
                "历史风格包缺少 Writing-DNA 门禁记录"
                if not gate_is_explicit
                else "需要达到 30 篇完整作品并完成审核、启用"
            )
        ),
        "creator_name": record.get("creator_name", ""),
        "profile_name": profile.get("profile_name", "未命名风格包") if isinstance(profile, dict) else "未命名风格包",
        "overview": overview,
        "account_id": str(profile.get("account_id") or "") if isinstance(profile, dict) else "",
        "source_ids": knowledge_source_ids or (list(profile.get("source_ids") or profile.get("evidence_work_ids") or []) if isinstance(profile, dict) else []),
        "knowledge_source_ids": knowledge_source_ids,
        "knowledge_source_versions": knowledge_source_versions,
    }


def _delete_style_asset_cascade(style_profile_id: str) -> dict[str, object]:
    """删除风格包及其账号知识资产、任务快照，避免前台残留假数据。"""
    profile = STYLE_PACKAGE_STORE.get_profile(style_profile_id)
    profile_payload = profile.get("style_profile") if isinstance(profile.get("style_profile"), Mapping) else {}
    account_id = str(profile_payload.get("account_id") or profile.get("account_id") or "").strip()
    result = STYLE_PACKAGE_STORE.delete_profile_cascade(style_profile_id)
    deleted_tasks = 0
    task_ids: set[str] = set()
    for task in _persisted_task_snapshots():
        if str(task.get("style_profile_id") or "") == str(style_profile_id) or (account_id and str(task.get("account_id") or "") == account_id):
            task_id = str(task.get("task_id") or "").strip()
            if task_id:
                task_ids.add(task_id)
    with STYLE_TASKS_LOCK:
        for task_id, task in list(STYLE_TASKS.items()):
            if str(task.get("style_profile_id") or "") == str(style_profile_id) or (account_id and str(task.get("account_id") or "") == account_id):
                task_ids.add(task_id)
                STYLE_TASKS.pop(task_id, None)
    for task_id in task_ids:
        for directory in (STYLE_TASK_DIR, DEFAULT_STYLE_TASK_DIR):
            path = directory / f"{task_id}.json"
            if path.is_file():
                path.unlink()
                deleted_tasks += 1
    if account_id:
        repository = _configured_obsidian_vault(create=False)
        result.update(repository.delete_account(account_id))
    result["deleted_task_snapshots"] = deleted_tasks
    _invalidate_style_task_listing_cache()
    return result


def _delete_account_asset_cascade(account_id: str) -> dict[str, object]:
    """删除账号及其全部风格包资产。"""
    account = str(account_id or '').strip()
    if not account:
        raise ValueError('缺少 account_id')
    removed_profiles = 0
    for profile in STYLE_PACKAGE_STORE.list_profiles():
        payload = profile.get('style_profile') if isinstance(profile.get('style_profile'), Mapping) else {}
        if str(payload.get('account_id') or profile.get('account_id') or '').strip() == account:
            STYLE_PACKAGE_STORE.delete_profile_cascade(str(profile.get('style_profile_id') or ''))
            removed_profiles += 1
    repository = _configured_obsidian_vault(create=False)
    result = repository.delete_account(account)
    result['deleted_style_profiles'] = removed_profiles
    _invalidate_style_task_listing_cache()
    return result


def _rewrite_summary(record: dict) -> dict:
    """Small, safe list payload for the persisted rewrite review queue."""
    source = record.get("case_source", {})
    result = record.get("result", {})
    source_ids = result.get("knowledge_source_ids", []) if isinstance(result, Mapping) else []
    human_writing = result.get("human_writing", {}) if isinstance(result, Mapping) else {}
    asset_versions = result.get("asset_versions", {}) if isinstance(result, Mapping) else {}
    writing_context = result.get("writing_context", {}) if isinstance(result, Mapping) else {}
    writing_context = writing_context if isinstance(writing_context, Mapping) else {}
    return {
        "rewrite_id": record.get("rewrite_id"),
        "created_at": record.get("created_at"),
        "review_status": record.get("review_status"),
        "style_profile_id": record.get("style_profile_id"),
        "source_url": source.get("source_url", "") if isinstance(source, dict) else "",
        "source_title": source.get("title", "") if isinstance(source, dict) else "",
        "rewritten_copy_preview": str(result.get("rewritten_copy", ""))[:180] if isinstance(result, dict) else "",
        "knowledge_source_ids": [str(item) for item in source_ids if str(item).strip()] if isinstance(source_ids, (list, tuple)) else [],
        "knowledge_source_versions": dict(result.get("knowledge_source_versions") or {}) if isinstance(result, Mapping) and isinstance(result.get("knowledge_source_versions"), Mapping) else {},
        "style_profile_version": str(asset_versions.get("style_profile_version") or "") if isinstance(asset_versions, Mapping) else "",
        "human_writing_status": str(human_writing.get("status") or "") if isinstance(human_writing, Mapping) else "",
        "orchestrator_version": str(asset_versions.get("orchestrator_version") or "") if isinstance(asset_versions, Mapping) else "",
        "topic": str(writing_context.get("topic") or result.get("topic") or "") if isinstance(result, Mapping) else "",
        "target_platform": str(writing_context.get("target_platform") or result.get("target_platform") or "") if isinstance(result, Mapping) else "",
        "audience": str(writing_context.get("audience") or result.get("audience") or "") if isinstance(result, Mapping) else "",
        "thinking_package_id": str(writing_context.get("thinking_package_id") or result.get("thinking_package_id") or "") if isinstance(result, Mapping) else "",
        "writing_mode": str(result.get("writing_mode") or "legacy") if isinstance(result, Mapping) else "legacy",
    }


def _platform_from_url(value: str) -> str:
    try:
        # Accept a full share message or v.douyin.com short link, the same
        # input formats already supported by the project's Douyin collector.
        extract_douyin_share_url(value)
        return "douyin"
    except DouyinCollectorError:
        pass
    hosts: set[str] = set()
    for match in __import__("re").findall(r"https?://[^\s，。；、]+", str(value)):
        try:
            hostname = urlparse(match).hostname
        except ValueError:
            hostname = None
        if hostname:
            hosts.add(str(hostname).lower().removeprefix("www."))
    try:
        hostname = urlparse(value).hostname
    except ValueError:
        hostname = None
    host = str(hostname or "").lower().removeprefix("www.")
    if host in {"douyin.com", "v.douyin.com"} or hosts.intersection({"douyin.com", "v.douyin.com"}):
        return "douyin"
    if host == "space.bilibili.com" or host == "bilibili.com":
        return "bilibili"
    return "unsupported"


WRITING_PLATFORM_PUBLISH_FORMATS = {
    "xiaohongshu": "小红书图文",
    "wechat_article": "微信公众号长文",
    "douyin": "抖音口播",
    "zhihu": "知乎回答",
}


def _normalize_writing_task_context(payload: Mapping[str, object]) -> dict[str, str]:
    """Normalize the structured fields submitted by the production workbench.

    The existing ``/api/case-rewrites`` contract remains intact.  These fields
    are additive and are also folded into the bounded creative brief so the
    model receives the same context that is persisted in the task snapshot.
    """

    topic = str(
        payload.get("topic")
        or payload.get("writing_topic")
        or payload.get("creative_topic")
        or ""
    ).strip()[:2_000]
    audience = str(
        payload.get("audience")
        or payload.get("target_audience")
        or payload.get("writing_audience")
        or ""
    ).strip()[:200]
    target_platform = str(
        payload.get("target_platform")
        or payload.get("publish_platform")
        or ""
    ).strip().lower()[:80]
    thinking_package_id = str(
        payload.get("thinking_package_id")
        or payload.get("viewpoint_package_id")
        or ""
    ).strip()[:160]
    account_id = str(payload.get("account_id") or "").strip()
    # 当前账号知识库的稳定主键就是账号级思维包主键；只有前端未显式
    # 传入 thinking_package_id 时才使用它，避免伪造第二套资产 ID。
    if not thinking_package_id and account_id:
        thinking_package_id = account_id

    publish_format = str(payload.get("publish_format") or "").strip()
    mapped_format = WRITING_PLATFORM_PUBLISH_FORMATS.get(target_platform, "")
    # 新工作台的目标平台优先于旧页面默认值；自定义/历史 publish_format
    # 仍按原契约保留，避免破坏旧抖音案例入口。
    if mapped_format and (not publish_format or publish_format == "知识口播短视频"):
        publish_format = mapped_format
    if not publish_format:
        publish_format = "知识口播短视频"
    return {
        "topic": topic,
        "audience": audience,
        "target_platform": target_platform,
        "thinking_package_id": thinking_package_id,
        "publish_format": publish_format[:120],
    }


def _knowledge_source_registry() -> KnowledgeSourceRegistry:
    """返回当前配置路径对应的知识源注册表，便于测试和多实例切换。"""

    global KNOWLEDGE_SOURCE_REGISTRY, KNOWLEDGE_SOURCE_REGISTRY_PATH
    configured = str(os.environ.get("KNOWLEDGE_SOURCE_REGISTRY_PATH") or "").strip()
    path = Path(configured).expanduser() if configured else Path(ROOT / "outputs" / "knowledge_sources" / "sources.json")
    if KNOWLEDGE_SOURCE_REGISTRY.path != path:
        KNOWLEDGE_SOURCE_REGISTRY_PATH = path
        KNOWLEDGE_SOURCE_REGISTRY = KnowledgeSourceRegistry(path)
    return KNOWLEDGE_SOURCE_REGISTRY


def _knowledge_source_public(record: Mapping[str, object], *, include_content: bool = False) -> dict[str, object]:
    """API 对外的知识源摘要；正文只在明确绑定任务时读取。"""

    value = dict(record)
    if not include_content:
        value.pop("content", None)
    value["status_label"] = SOURCE_STATUS_LABELS.get(str(value.get("status") or ""), value.get("status_label", ""))
    value["usage_scope_label"] = USAGE_SCOPE_LABELS.get(str(value.get("usage_scope") or ""), "")
    value["bound_task_ids"] = list(value.get("bound_task_ids") or [])
    value["bound_asset_ids"] = list(value.get("bound_asset_ids") or [])
    return value


def _knowledge_source_summary(*, status: str = "", limit: int = 100) -> dict[str, object]:
    registry = _knowledge_source_registry()
    records = registry.list(status=status, limit=limit)
    counts = {key: 0 for key in SOURCE_STATUSES}
    for record in registry.list(limit=2000):
        state = str(record.get("status") or "").upper()
        if state in counts:
            counts[state] += 1
    return {
        "status": "ready",
        "schema_version": "knowledge-source-v1",
        "sources": [_knowledge_source_public(record) for record in records],
        "counts": counts,
        "status_labels": dict(SOURCE_STATUS_LABELS),
        "usage_scope_labels": dict(USAGE_SCOPE_LABELS),
    }


def _obsidian_config_read() -> dict[str, object]:
    configured = str(os.environ.get("ACCOUNT_KNOWLEDGE_VAULT_PATH") or "").strip()
    file_value: dict[str, object] = {}
    try:
        if OBSIDIAN_CONFIG_PATH.is_file():
            loaded = json.loads(OBSIDIAN_CONFIG_PATH.read_text(encoding="utf-8"))
            if isinstance(loaded, Mapping):
                file_value = dict(loaded)
    except (OSError, ValueError):
        file_value = {}
    vault = configured or str(file_value.get("vault_path") or "").strip()
    return {
        "status": "configured" if vault else "not_configured",
        "vault_path": vault,
        "exists": bool(vault and Path(vault).expanduser().is_dir()),
        "registry_path": str(_knowledge_source_registry().path),
        "skill_versions": dict(KNOWLEDGE_SOURCE_SKILL_VERSIONS),
        "skill_governance": dict(SKILL_GOVERNANCE),
    }


def _configured_obsidian_vault(*, create: bool = True) -> ObsidianRepository:
    """读取当前生效的 Vault 配置；环境变量优先，配置文件用于重启恢复。"""

    configured = _obsidian_config_read().get("vault_path")
    value = str(configured or "").strip()
    if not value:
        raise VaultConfigError("未配置 Obsidian Vault 路径")
    # 让既有账号知识库桥接和新知识源登记使用同一份配置。
    os.environ["ACCOUNT_KNOWLEDGE_VAULT_PATH"] = value
    return ObsidianRepository(value, create=create)


def _obsidian_config_save(payload: Mapping[str, object]) -> dict[str, object]:
    value = str(payload.get("vault_path") or payload.get("path") or "").strip()
    if not value:
        raise ValueError("请提供 Obsidian Vault 路径")
    candidate = Path(value).expanduser().resolve()
    candidate.mkdir(parents=True, exist_ok=True)
    OBSIDIAN_CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)
    temporary = OBSIDIAN_CONFIG_PATH.with_name(f".{OBSIDIAN_CONFIG_PATH.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(
        json.dumps({"schema_version": "obsidian-config-v1", "vault_path": str(candidate), "updated_at": datetime.now(timezone.utc).isoformat(timespec="seconds")}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    temporary.replace(OBSIDIAN_CONFIG_PATH)
    # 当前进程立即可用；重启时 _obsidian_config_read 可从配置文件恢复。
    os.environ["ACCOUNT_KNOWLEDGE_VAULT_PATH"] = str(candidate)
    return _obsidian_config_read()


def _knowledge_source_register(payload: Mapping[str, object]) -> tuple[int, dict[str, object]]:
    registry = _knowledge_source_registry()
    repository: ObsidianRepository | None = None
    try:
        # 新知识源必须有真实的 Obsidian 落盘位置；没有配置时只允许调用
        # /api/knowledge-sources/detect 预览，不能用注册表 JSON 冒充已入库。
        repository = _configured_obsidian_vault(create=True)
    except VaultConfigError as exc:
        return 503, {
            "status": "vault_not_configured",
            "message": str(exc),
            "source": None,
        }
    try:
        record = registry.register(payload, repository=repository)
    except KnowledgeSourceError as exc:
        return 400, {"status": "invalid_input", "message": str(exc)}
    except (ObsidianRepositoryError, OSError) as exc:
        # register() 已把失败状态落盘；API 不宣称已写入。
        source_id = ""
        try:
            source_id = str(registry.list(limit=1)[0].get("source_id") or "")
        except Exception:
            pass
        return 503, {"status": "vault_write_failed", "message": str(exc), "source_id": source_id}
    return 201, {"status": "registered", "source": _knowledge_source_public(record)}


def _knowledge_source_confirm(source_id: str, payload: Mapping[str, object]) -> tuple[int, dict[str, object]]:
    registry = _knowledge_source_registry()
    try:
        current = registry.get(source_id)
        repository = None
        if current and str(current.get("obsidian_path") or "").strip():
            repository = _configured_obsidian_vault(create=False)
        record = registry.confirm(source_id, payload, repository=repository)
    except KnowledgeSourceError as exc:
        return 409, {"status": "confirmation_blocked", "message": str(exc), "source_id": source_id}
    except (VaultConfigError, ObsidianRepositoryError, OSError) as exc:
        return 503, {
            "status": "vault_sync_failed",
            "message": f"人工确认未完成，Vault 元数据同步失败：{exc}",
            "source_id": source_id,
        }
    return 200, {"status": "confirmed", "source": _knowledge_source_public(record)}


def _knowledge_source_bind(source_id: str, payload: Mapping[str, object]) -> tuple[int, dict[str, object]]:
    task_id = str(payload.get("task_id") or payload.get("writing_task_id") or "").strip()
    asset_id = str(payload.get("asset_id") or "").strip()
    if not task_id and not asset_id:
        return 400, {"status": "invalid_input", "message": "task_id 或 asset_id 至少提供一个"}
    registry = _knowledge_source_registry()
    try:
        record = registry.get(source_id)
        if record is None:
            raise KnowledgeSourceError("未找到知识源")
        if task_id:
            record = registry.bind_task(source_id, task_id)
        if asset_id:
            record = registry.bind_asset(source_id, asset_id)
    except KnowledgeSourceError as exc:
        return 404, {"status": "source_missing", "message": str(exc), "source_id": source_id}
    return 200, {"status": "bound", "source": _knowledge_source_public(record)}


def _knowledge_source_transition(source_id: str, payload: Mapping[str, object]) -> tuple[int, dict[str, object]]:
    target = str(payload.get("status") or "").strip().upper()
    if target not in SOURCE_STATUSES:
        return 400, {"status": "invalid_input", "message": "不支持的知识源状态"}
    try:
        current = _knowledge_source_registry().get(source_id)
        repository = None
        if current and str(current.get("obsidian_path") or "").strip():
            repository = _configured_obsidian_vault(create=False)
        record = _knowledge_source_registry().transition(
            source_id,
            target,
            error_code=str(payload.get("error_code") or ""),
            error_message=str(payload.get("error_message") or payload.get("message") or ""),
            repository=repository,
        )
    except KnowledgeSourceError as exc:
        return 404, {"status": "source_missing", "message": str(exc), "source_id": source_id}
    except (VaultConfigError, ObsidianRepositoryError, OSError) as exc:
        return 503, {
            "status": "vault_sync_failed",
            "message": f"状态更新未完成，Vault 元数据同步失败：{exc}",
            "source_id": source_id,
        }
    return 200, {"status": "updated", "source": _knowledge_source_public(record)}


def _knowledge_source_repository(record: Mapping[str, object], *, create: bool = False) -> ObsidianRepository:
    """Resolve the Vault used by a registered knowledge source.

    A source is only considered real after its note exists in the configured
    Vault.  Keeping this lookup in one helper avoids a processing endpoint
    accidentally writing to a second, implicit directory.
    """

    if not str(record.get("obsidian_path") or "").strip():
        raise VaultConfigError("知识源尚未写入 Obsidian Vault")
    return _configured_obsidian_vault(create=create)


def _knowledge_source_attachment_bytes(record: Mapping[str, object], repository: ObsidianRepository) -> bytes:
    """Read an attachment previously persisted by ``register`` inside Vault."""

    raw_path = str(record.get("obsidian_attachment_path") or "").strip()
    if not raw_path:
        return b""
    candidate = Path(raw_path).expanduser().resolve()
    try:
        candidate.relative_to(repository.vault_path.resolve())
    except ValueError as exc:
        raise ObsidianRepositoryError("知识源附件超出 Obsidian Vault 边界") from exc
    try:
        return candidate.read_bytes()
    except OSError as exc:
        raise ObsidianRepositoryError(f"无法读取知识源附件：{candidate.name}") from exc


def _extract_knowledge_source_file_text(raw: bytes, filename: str) -> tuple[str, str]:
    """Extract text from formats that are safe to process locally.

    PDF/DOCX parsing is attempted only when the corresponding optional parser
    is already installed.  If it is unavailable or the document is malformed,
    the caller receives an explicit failure instead of a fabricated summary.
    """

    suffix = Path(str(filename or "")).suffix.lower()
    if suffix in {".txt", ".md", ".markdown", ".html", ".htm", ".json", ".csv"}:
        return raw.decode("utf-8", errors="replace").strip()[:200_000], "local_text"
    if suffix == ".pdf":
        try:
            from pypdf import PdfReader  # type: ignore

            reader = PdfReader(io.BytesIO(raw))
            text = "\n".join(str(page.extract_text() or "") for page in reader.pages).strip()
            if text:
                return text[:200_000], "pypdf"
            raise ValueError("PDF 未提取到文字层")
        except ImportError as exc:
            raise ValueError("PDF 已保存附件，但当前环境未安装 pypdf；请补充正文后重试") from exc
        except Exception as exc:
            raise ValueError(f"PDF 已保存附件，但正文提取失败：{type(exc).__name__}") from exc
    if suffix == ".docx":
        try:
            from docx import Document  # type: ignore

            document = Document(io.BytesIO(raw))
            text = "\n".join(str(paragraph.text or "") for paragraph in document.paragraphs).strip()
            if text:
                return text[:200_000], "python-docx"
            raise ValueError("DOCX 未提取到正文段落")
        except ImportError as exc:
            raise ValueError("DOCX 已保存附件，但当前环境未安装 python-docx；请补充正文后重试") from exc
        except Exception as exc:
            raise ValueError(f"DOCX 已保存附件，但正文提取失败：{type(exc).__name__}") from exc
    raise ValueError(f"暂不支持自动提取 {suffix or '该文件'}；原始附件已保留，请补充正文后重试")


def _knowledge_source_processing_summary(result: Mapping[str, object], *, route: str) -> dict[str, object]:
    """Keep only a small, auditable processing summary in the registry."""

    summary: dict[str, object] = {
        "route": route,
        "status": str(result.get("status") or ""),
        "content_type": str(result.get("content_type") or ""),
        "transcript_status": str(result.get("transcript_status") or ""),
        "title": str(result.get("title") or ""),
        "final_url": str(result.get("final_url") or ""),
    }
    for key in ("collector", "video_id", "bvid", "selection_id", "item_count", "ready_count", "task_id"):
        value = result.get(key)
        if value not in (None, "", [], {}):
            summary[key] = value
    return summary


def _style_collection_policy(payload: Mapping[str, object] | None = None) -> tuple[int, int]:
    """Validate the durable collection settings for an account-style task."""

    values = dict(payload or {})
    try:
        sample_target = int(values.get("sample_target") or values.get("minimum_samples") or 50)
    except (TypeError, ValueError) as exc:
        raise ValueError("采集作品数必须是 50 或 100") from exc
    if sample_target not in STYLE_COLLECTION_SAMPLE_TARGETS:
        raise ValueError("采集作品数仅支持 50 或 100；30/80 仅兼容历史任务")
    try:
        max_video_duration_seconds = int(
            values.get("max_video_duration_seconds")
            or values.get("video_duration_limit_seconds")
            or LEGACY_STYLE_MAX_VIDEO_DURATION_SECONDS
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("视频时长筛选值必须是秒数") from exc
    if not 1 <= max_video_duration_seconds <= LEGACY_STYLE_MAX_VIDEO_DURATION_SECONDS:
        raise ValueError("视频时长筛选范围必须在 1 秒到 10 分钟之间")
    return sample_target, max_video_duration_seconds


def _knowledge_source_process(source_id: str, payload: Mapping[str, object] | None = None) -> tuple[int, dict[str, object]]:
    """Process one registered source into usable content or an explicit failure.

    The endpoint is intentionally idempotent for already processed sources. URL
    collection reuses the existing Douyin/Bilibili collectors and
    ``collect_topic_source``; profile URLs are routed to the existing account
    style-collection worker and are never treated as ordinary article text.
    """

    values = dict(payload or {})
    registry = _knowledge_source_registry()
    try:
        record = registry.get(source_id)
    except KnowledgeSourceError as exc:
        return 400, {"status": "invalid_input", "message": str(exc), "source_id": source_id}
    if record is None:
        return 404, {"status": "source_missing", "message": "未找到知识源", "source_id": source_id}
    source_id = str(record.get("source_id") or source_id).strip()
    state = str(record.get("status") or "").upper()
    if state in {"PENDING_CONFIRMATION", "PENDING_IDENTIFICATION"}:
        return 409, {
            "status": "confirmation_required",
            "message": "知识源尚未完成人工确认，不能开始处理",
            "source_id": source_id,
            "source": _knowledge_source_public(record),
        }
    if state == "PROCESSING":
        return 202, {
            "status": "processing",
            "message": "知识源正在处理中，请稍后刷新队列",
            "source_id": source_id,
            "source": _knowledge_source_public(record),
        }
    # Repeating the action after a successful extraction should not download or
    # transcribe the same source again unless the caller explicitly requests a
    # retry.  ``PENDING_REVIEW`` remains usable for a writing task while it is
    # waiting for human knowledge review.
    force_retry = values.get("force") is True or str(values.get("force") or "").strip().lower() in {"1", "true", "yes", "retry"}
    if state in {"PENDING_REVIEW", "INGESTED"} and bool(record.get("content_available")) and not force_retry:
        return 200, {
            "status": "ready",
            "message": "知识源正文已就绪，无需重复处理",
            "source_id": source_id,
            "source": _knowledge_source_public(record),
        }
    try:
        repository = _knowledge_source_repository(record, create=False)
    except (VaultConfigError, ObsidianRepositoryError) as exc:
        return 503, {
            "status": "vault_not_available",
            "message": str(exc),
            "source_id": source_id,
        }

    route = ""
    try:
        # 兼容早期登记记录：旧识别器会把“查看 TA 的更多作品 +
        # v.douyin.com 短链”保存成 video。现在可以利用持久化的
        # original_input 重新识别为 profile，先修正记录再进入账号采集，
        # 避免用户必须删除历史知识源后重新登记。
        redetected = detect_source(
            str(record.get("original_input") or record.get("raw_url") or "")
        )
        current_kind = str(record.get("source_kind") or record.get("material_type") or "").lower()
        if redetected.get("material_type") == "profile" and current_kind != "profile":
            record = registry.update_processing(
                source_id,
                status="PENDING_PROCESSING",
                metadata={
                    "platform": redetected.get("platform") or record.get("platform") or "douyin",
                    "source_kind": "profile",
                    "material_type": "profile",
                    "detection_status": "detected",
                    "detection_confidence": redetected.get("detection_confidence", 0.95),
                    "detection_reason": redetected.get("detection_reason") or "抖音博主主页分享文案",
                    "processing_route": "account_style_collection",
                    "processing_result": {"route": "account_style_collection", "reclassified": True},
                    "last_processed_at": utc_now(),
                },
                repository=repository,
            )
        # A profile is an account corpus entry point.  Reuse the existing style
        # worker so creator works become Obsidian work cards before Nuwa/DNA
        # distillation; never project a profile page into a fake article body.
        if str(record.get("source_kind") or record.get("material_type") or "").lower() == "profile":
            platform = str(record.get("platform") or "").lower()
            if platform not in {"douyin", "bilibili"}:
                raise ValueError("当前仅支持抖音或 B 站博主主页进入账号采集；其它主页需人工导入作品卡")
            raw_url = str(record.get("raw_url") or "").strip()
            if not raw_url:
                raise ValueError("博主主页缺少有效链接")
            try:
                sample_target, max_video_duration_seconds = _style_collection_policy(values)
            except ValueError as exc:
                return 400, {"status": "invalid_input", "message": str(exc), "source_id": source_id}
            collection_policy = {
                "sample_target": sample_target,
                "max_video_duration_seconds": max_video_duration_seconds,
            }
            registry.update_processing(
                source_id,
                status="PROCESSING",
                metadata={
                    "processing_route": "account_style_collection",
                    "processing_result": {
                        "route": "account_style_collection", "platform": platform,
                        "collection_policy": collection_policy,
                    },
                    "processing_task_id": "",
                    "last_processed_at": utc_now(),
                },
                repository=repository,
            )
            task = _create_style_task(
                {
                    "creator_home_url": raw_url,
                    "creator_name": str(record.get("author") or "").strip(),
                    "sample_target": sample_target,
                    "max_video_duration_seconds": max_video_duration_seconds,
                    "account_id": str(record.get("account_id") or "").strip(),
                    "account_knowledge_mode": "required",
                    "knowledge_source_id": source_id,
                    "knowledge_source_ids": [source_id],
                    "evidence_only": True,
                }
            )
            task_id = str(task.get("task_id") or "").strip()
            if not task_id:
                raise RuntimeError("账号采集任务未返回 task_id")
            registry.update_processing(
                source_id,
                status="PROCESSING",
                metadata={
                    "processing_route": "account_style_collection",
                    "processing_task_id": task_id,
                    "processing_result": {
                        "route": "account_style_collection",
                        "platform": platform,
                        "task_id": task_id,
                        "collection_policy": collection_policy,
                    },
                    "last_processed_at": utc_now(),
                },
                repository=repository,
            )
            registry.bind_task(source_id, task_id)
            current = registry.get(source_id) or record
            return 202, {
                "status": "processing",
                "message": "博主主页已进入 TikHub 账号作品采集任务；完成后将形成可追踪证据集，等待后续 Skill 蒸馏",
                "task_id": task_id,
                "source_id": source_id,
                "source": _knowledge_source_public(current),
            }

        registry.update_processing(
            source_id,
            status="PROCESSING",
            metadata={"processing_route": "content_extraction", "last_processed_at": utc_now()},
            repository=repository,
        )
        record = registry.get(source_id) or record
        raw_url = str(record.get("raw_url") or "").strip()
        platform = str(record.get("platform") or "unknown").lower()
        kind = str(record.get("source_kind") or record.get("material_type") or "unknown").lower()
        content = str(record.get("content") or "").strip()
        metadata: dict[str, object] = {"processing_route": "content_extraction"}

        if content:
            route = "stored_content"
            result = {"status": "ready", "content_type": "stored_content", "transcript_status": "provided_text", "title": record.get("title") or ""}
            metadata.update({"content_type": "stored_content", "transcript_status": "provided_text"})
        elif str(record.get("input_type") or "").lower() == "file" or platform == "local":
            route = "local_file"
            raw = _knowledge_source_attachment_bytes(record, repository)
            if not raw:
                raise ValueError("本地资料附件不存在；请重新选择文件登记")
            content, extractor = _extract_knowledge_source_file_text(raw, str(record.get("file_name") or ""))
            if not content:
                raise ValueError("本地资料未提取到正文；请补充正文后重试")
            result = {"status": "ready", "content_type": "local_file", "transcript_status": extractor, "title": record.get("title") or record.get("file_name") or ""}
            metadata.update({"content_type": "local_file", "transcript_status": extractor})
        elif kind == "video" or platform in {"douyin", "bilibili", "kuaishou", "weixin_video"}:
            route = f"{platform}_video_collector"
            if platform == "douyin":
                result = collect_douyin_case_video(raw_url)
            elif platform == "bilibili":
                result = collect_case_video(raw_url)
            else:
                raise ValueError(f"{platform} 当前没有接入可验证的视频字幕采集器")
            content = str(result.get("transcript") or "").strip()
            if len(content) < MIN_SOURCE_TEXT_CHARS:
                raise ValueError(str(result.get("message") or "视频没有取得足够字幕/转写正文"))
            metadata.update({
                "content_type": "video_transcript",
                "transcript_status": str(result.get("transcript_status") or ""),
                "final_url": str(result.get("source_url") or raw_url),
                "title": str(result.get("title") or record.get("title") or ""),
                "source_metadata": {"collector": route, **({"video_id": result.get("video_id")} if result.get("video_id") else {}), **({"bvid": result.get("bvid")} if result.get("bvid") else {})},
            })
        elif raw_url:
            route = "article_html_collector"
            result = collect_topic_source(
                {
                    "selection_id": source_id,
                    "source_url": raw_url,
                    "platform": platform if platform != "unknown" else "",
                    "title": record.get("title") or "",
                    "source_metadata": {"source_id": source_id, "material_type": kind},
                }
            )
            if str(result.get("status") or "") != "ready":
                raise ValueError(str(result.get("message") or "文章正文未取得"))
            content = str(result.get("content") or "").strip()
            if len(content) < MIN_SOURCE_TEXT_CHARS:
                raise ValueError("文章页面没有达到文案消费所需的正文长度")
            metadata.update({
                "content_type": str(result.get("content_type") or "html_text"),
                "transcript_status": "collected_html",
                "final_url": str(result.get("final_url") or raw_url),
                "title": str(result.get("title") or record.get("title") or ""),
            })
        else:
            raise ValueError("知识源缺少可处理的正文、文件或链接")

        metadata["processing_route"] = route or "content_extraction"
        metadata["processing_result"] = _knowledge_source_processing_summary(result, route=route or "content_extraction")
        metadata["last_processed_at"] = utc_now()
        updated = registry.update_content(
            source_id,
            content,
            metadata=metadata,
            repository=repository,
            status="PENDING_REVIEW",
        )
        return 200, {
            "status": "ready",
            "message": "知识源正文已提取并写回 Obsidian，等待人工审核",
            "source_id": source_id,
            "source": _knowledge_source_public(updated),
        }
    except (BilibiliCollectorError, DouyinCollectorError) as exc:
        error_code = "collector_blocked"
        message = str(exc)
    except (TopicWritingGovernanceError, TopicCollectionError) as exc:
        error_code = "content_collection_failed"
        message = str(exc)
    except (ObsidianRepositoryError, OSError) as exc:
        error_code = "vault_read_failed"
        message = str(exc)
    except (ValueError, RuntimeError) as exc:
        error_code = "content_extraction_failed"
        message = str(exc)
    try:
        updated = registry.update_processing(
            source_id,
            status="FAILED",
            metadata={
                "processing_route": route or "content_extraction",
                "processing_result": {"route": route or "content_extraction", "error_code": error_code},
                "last_processed_at": utc_now(),
            },
            error_code=error_code,
            error_message=message,
            repository=repository,
        )
    except Exception:
        updated = registry.get(source_id) or record
    return 422, {
        "status": "processing_failed",
        "message": message or "知识源处理失败",
        "error_code": error_code,
        "source_id": source_id,
        "source": _knowledge_source_public(updated),
    }


def _knowledge_source_detect(payload: Mapping[str, object]) -> dict[str, object]:
    """只做自动识别预览，不写注册表、不写 Vault。"""

    value = payload.get("raw_url") or payload.get("source_url") or payload.get("url") or payload.get("value")
    file_value = payload.get("file") if isinstance(payload.get("file"), Mapping) else {}
    file_name = file_value.get("name") if isinstance(file_value, Mapping) else payload.get("file_name")
    mime_type = file_value.get("mime_type") or file_value.get("type") if isinstance(file_value, Mapping) else payload.get("mime_type")
    detection = detect_source(value, file_name=file_name, mime_type=mime_type)
    return {
        "status": "ready",
        "schema_version": "knowledge-source-v1",
        "detection": detection,
        "message": detection.get("detection_reason") or "已完成自动识别",
    }


def _knowledge_source_ids(payload: Mapping[str, object]) -> list[str]:
    values: list[object] = []
    raw = payload.get("knowledge_source_ids")
    if isinstance(raw, (list, tuple, set)):
        values.extend(raw)
    elif raw:
        values.append(raw)
    single = payload.get("knowledge_source_id") or payload.get("source_id")
    if single:
        values.append(single)
    result: list[str] = []
    for value in values:
        item = str(value or "").strip()
        if item and item not in result:
            result.append(item)
    return result[:50]


def _knowledge_source_records_for_task(
    payload: Mapping[str, object], *, require_content: bool = False
) -> tuple[list[str], list[dict[str, object]]]:
    """校验文案任务引用的知识源，并返回不含正文的追踪摘要。"""

    ids = _knowledge_source_ids(payload)
    if not ids:
        return [], []
    registry = _knowledge_source_registry()
    records: list[dict[str, object]] = []
    missing: list[str] = []
    for source_id in ids:
        try:
            record = registry.get(source_id)
        except KnowledgeSourceError:
            record = None
        if record is None:
            missing.append(source_id)
            continue
        state = str(record.get("status") or "").upper()
        if state in {"FAILED", "PENDING_CONFIRMATION"}:
            raise ValueError(f"知识源 {source_id} 当前为 {SOURCE_STATUS_LABELS.get(state, state)}，不能进入文案任务")
        if require_content and not str(record.get("content") or "").strip():
            raise ValueError(f"知识源 {source_id} 正文尚未就绪，请先完成处理后再生成文案")
        records.append(
            {
                "source_id": str(record.get("source_id") or source_id),
                "source_version": str(record.get("source_version") or "source-v1"),
                "raw_url": str(record.get("raw_url") or ""),
                "platform": str(record.get("platform") or "unknown"),
                "material_type": str(record.get("material_type") or "unknown"),
                "author": str(record.get("author") or ""),
                "status": state,
                "obsidian_path": str(record.get("obsidian_path") or ""),
            }
        )
    if missing:
        raise ValueError("未找到知识源：" + ", ".join(missing))
    return ids, records


def _knowledge_source_mark_task(source_ids: Sequence[str], task_id: str, status: str = "") -> None:
    """把 source_id 与异步文案 task 绑定；失败不静默吞掉。"""

    registry = _knowledge_source_registry()
    for source_id in source_ids:
        registry.bind_task(source_id, task_id)
        if status:
            current = registry.get(source_id)
            if current and str(current.get("status") or "").upper() not in {"FAILED", "INGESTED"}:
                repository = None
                if str(current.get("obsidian_path") or "").strip():
                    repository = _configured_obsidian_vault(create=False)
                registry.transition(source_id, status, repository=repository)


def _prepare_knowledge_source_rewrite_payload(payload: Mapping[str, object]) -> tuple[dict[str, object], list[dict[str, object]]]:
    """把文案页选择的 source_id 转成现有三选一输入契约。

    旧的抖音案例字段保持不变；只有没有旧输入时，才把已经有正文的
    知识源落成 topic-writing 的手工正文来源。URL 尚未提取正文时明确阻断，
    不会用前端状态冒充可生成内容。
    """

    normalized = dict(payload)
    ids = _knowledge_source_ids(normalized)
    if not ids:
        return normalized, []
    has_primary = any(str(normalized.get(key) or "").strip() for key in ("case_video_url", "source_content_id", "source_text", "topic_selection_id"))
    _, records = _knowledge_source_records_for_task(normalized, require_content=not has_primary)
    normalized["knowledge_source_ids"] = ids
    if has_primary:
        return normalized, records
    registry = _knowledge_source_registry()
    # A task may select more than one already-ingested source.  Preserve every
    # source in the governed manual input (with explicit source markers) rather
    # than silently using only the first record.  The registry remains the
    # source of truth; this aggregation is only the existing topic-writing
    # compatibility projection consumed by rewrite_case_copy.
    source_records_with_content: list[tuple[dict[str, object], str]] = []
    for record in records:
        source_id = str(record.get("source_id") or "").strip()
        source = registry.get(source_id) or {}
        content = str(source.get("content") or "").strip()
        if content:
            source_records_with_content.append((source, content))
    if not source_records_with_content:
        raise ValueError("所选知识源正文尚未就绪（至少需要可用正文），请先在 Obsidian 队列完成处理")
    chunks: list[str] = []
    remaining = MAX_SOURCE_TEXT_CHARS
    for source, content in source_records_with_content:
        marker = f"\n\n【知识源 {str(source.get('source_id') or '')}】\n"
        if remaining <= len(marker):
            break
        excerpt = content[: max(0, remaining - len(marker))]
        chunks.append(marker + excerpt)
        remaining -= len(marker) + len(excerpt)
        if len(excerpt) < len(content):
            break
    content = "".join(chunks).strip()
    if len(content) < MIN_SOURCE_TEXT_CHARS:
        raise ValueError("所选知识源正文尚未就绪（至少需要可用正文），请先在 Obsidian 队列完成处理")
    try:
        manual = TOPIC_WRITING_GOVERNANCE_STORE.save_manual_source(
            content,
            title=(
                str(source_records_with_content[0][0].get("title")
                    or source_records_with_content[0][0].get("file_name")
                    or "知识源正文")
                + (f" 等 {len(source_records_with_content)} 条资料" if len(source_records_with_content) > 1 else "")
            ),
            source_name=str(source_records_with_content[0][0].get("author") or ""),
            source_url=str(source_records_with_content[0][0].get("raw_url") or ""),
        )
    except TopicWritingGovernanceError as exc:
        raise ValueError(str(exc)) from exc
    normalized["source_content_id"] = str(manual.get("source_content_id") or "")
    normalized["governance_mode"] = "joint"
    return normalized, records


def _obsidian_queue_snapshot() -> dict[str, object]:
    summary = _knowledge_source_summary(limit=200)
    sources = summary.get("sources") if isinstance(summary.get("sources"), list) else []
    return {
        "status": "ready",
        "schema_version": "obsidian-queue-v1",
        "vault": _obsidian_config_read(),
        "counts": summary.get("counts", {}),
        "status_labels": summary.get("status_labels", {}),
        "sources": sources,
    }


def _obsidian_assets_snapshot() -> dict[str, object]:
    knowledge = _account_knowledge_runtime_summary()
    try:
        profiles = [_profile_summary(record) for record in STYLE_PACKAGE_STORE.list_profiles()]
    except StylePackageStoreError:
        profiles = []
    try:
        rewrites = [_rewrite_summary(record) for record in STYLE_PACKAGE_STORE.list_rewrites(limit=20)]
    except StylePackageStoreError:
        rewrites = []
    return {
        "status": "ready",
        "schema_version": "obsidian-assets-v1",
        "knowledge": knowledge,
        "style_packages": profiles,
        "rewrites": rewrites,
        "skill_versions": dict(KNOWLEDGE_SOURCE_SKILL_VERSIONS),
        "skill_governance": dict(SKILL_GOVERNANCE),
    }


def _account_knowledge_runtime_summary() -> dict[str, object]:
    """返回文案页可安全展示的账号知识库摘要，不暴露笔记正文。"""

    vault_value = str(_obsidian_config_read().get("vault_path") or "").strip()
    if not vault_value:
        return {
            "status": "not_configured",
            "configured": False,
            "accounts": [],
            "account_count": 0,
            "work_card_count": 0,
            "dna_complete_count": 0,
            "message": "未配置 ACCOUNT_KNOWLEDGE_VAULT_PATH",
        }
    try:
        # Resolve the persisted page configuration as well as an inherited
        # environment variable. ``from_env`` alone fails after restart when
        # the config file is present but the process environment is clean.
        repository = _configured_obsidian_vault(create=False)
        accounts: list[dict[str, object]] = []
        total_cards = 0
        dna_complete = 0
        for account_id in repository.list_account_ids():
            account_name = account_id
            try:
                frontmatter, _ = repository.read_account_note(account_id, filename="account.md")
                account_name = str(frontmatter.get("account_name") or account_id)
            except ObsidianRepositoryError:
                pass
            cards = repository.list_work_cards(account_id)
            evidence_sets = repository.list_evidence_sets(account_id)
            jobs = repository.list_distillation_jobs(account_id=account_id)
            latest_evidence = max(evidence_sets, key=lambda item: str(item.updated_at or "")) if evidence_sets else None
            latest_job = max(jobs, key=lambda item: str(item.updated_at or "")) if jobs else None
            dna = repository.load_account_dna_context(account_id, include_pending=False)
            dna_versions = repository.list_account_dna_versions(account_id)
            current_dna_version = next((item for item in dna_versions if item.get("current")), {})
            work_count = len(cards)
            total_cards += work_count
            dna_status = str(dna.get("knowledge_status") or "MISSING")
            if dna_status == "APPROVED":
                dna_complete += 1
            accounts.append({
                "account_id": account_id,
                "account_name": account_name,
                "work_count": work_count,
                "sample_count": int(dna.get("sample_count") or 0),
                "dna_status": dna_status,
                "distillation_status": str(dna.get("distillation_status") or "MISSING"),
                # 只有已审核且启用的账号思维包才能进入生产工作台。
                "dna_enabled": bool(dna.get("enabled", dna_status == "APPROVED")) and dna_status == "APPROVED",
                "dna_current_version": str(current_dna_version.get("version_id") or ""),
                "dna_versions": dna_versions,
                "evidence_work_ids": list(dna.get("evidence_work_ids") or []),
                "knowledge_source_ids": list(dna.get("knowledge_source_ids") or []),
                "knowledge_source_versions": dict(dna.get("knowledge_source_versions") or {}) if isinstance(dna.get("knowledge_source_versions"), Mapping) else {},
                "missing_files": list(dna.get("missing_files") or []),
                "candidate_count": int(latest_evidence.candidate_count) if latest_evidence else 0,
                "eligible_work_count": int(latest_evidence.eligible_work_count) if latest_evidence else work_count,
                "target_valid_works": int(latest_evidence.target_valid_works) if latest_evidence else 50,
                "target_reached": bool(latest_evidence.target_reached) if latest_evidence else False,
                "evidence_status": str(latest_evidence.status) if latest_evidence else "WAITING_FOR_EVIDENCE",
                "evidence_set_id": str(latest_evidence.evidence_set_id) if latest_evidence else "",
                "checkpoint_state": str(latest_evidence.checkpoint_state) if latest_evidence else "none",
                "distillation_job_status": str(latest_job.status) if latest_job else "",
                "distillation_job_id": str(latest_job.job_id) if latest_job else "",
                "distillation_task_id": str(latest_job.job_id) if latest_job else "",
            })
        return {
            "status": "ready",
            "configured": True,
            "vault_name": repository.vault_path.name,
            "accounts": accounts,
            "account_count": len(accounts),
            "work_card_count": total_cards,
            "dna_complete_count": dna_complete,
            "evidence_sets": [item.to_dict() for account in accounts for item in repository.list_evidence_sets(str(account.get("account_id") or ""))],
            "distillation_jobs": [item.to_dict() for account in accounts for item in repository.list_distillation_jobs(account_id=str(account.get("account_id") or ""))],
        }
    except (ObsidianRepositoryError, OSError, ValueError) as exc:
        return {
            "status": "error",
            "configured": True,
            "accounts": [],
            "account_count": 0,
            "work_card_count": 0,
            "dna_complete_count": 0,
            "message": str(exc),
        }


def _obsidian_account_dna_snapshot(account_id: str) -> dict[str, object]:
    """返回 Obsidian 账号思维包的治理摘要，不把笔记正文送到浏览器。"""

    repository = _configured_obsidian_vault(create=False)
    account = str(account_id or "").strip()
    context = repository.load_account_dna_context(account, include_pending=False)
    versions = repository.list_account_dna_versions(account)
    current = next((item for item in versions if item.get("current")), {})
    return {
        "status": "ready",
        "account_id": account,
        "knowledge_status": str(context.get("knowledge_status") or "MISSING"),
        "distillation_status": str(context.get("distillation_status") or "MISSING"),
        "enabled": bool(context.get("enabled")),
        "sample_count": int(context.get("sample_count") or 0),
        "evidence_work_ids": list(context.get("evidence_work_ids") or []),
        "knowledge_source_ids": list(context.get("knowledge_source_ids") or []),
        "knowledge_source_versions": dict(context.get("knowledge_source_versions") or {}) if isinstance(context.get("knowledge_source_versions"), Mapping) else {},
        "current_version": str(current.get("version_id") or ""),
        "versions": versions,
    }


def _obsidian_account_dna_approve(account_id: str, payload: Mapping[str, object]) -> dict[str, object]:
    reviewer = str(payload.get("reviewer") or payload.get("approved_by") or "").strip()
    if not reviewer:
        raise ValueError("请填写审核人")
    repository = _configured_obsidian_vault(create=False)
    repository.approve_account_dna(
        account_id,
        reviewer=reviewer,
        notes=str(payload.get("notes") or "").strip(),
    )
    return _obsidian_account_dna_snapshot(account_id)


def _obsidian_account_dna_enable(account_id: str, payload: Mapping[str, object]) -> dict[str, object]:
    reviewer = str(payload.get("reviewer") or "").strip()
    if not reviewer:
        raise ValueError("请填写操作人")
    value = payload.get("enabled")
    enabled = value is True or str(value or "").strip().lower() in {"1", "true", "yes", "on", "enable", "enabled"}
    repository = _configured_obsidian_vault(create=False)
    result = repository.set_account_dna_enabled(
        account_id,
        enabled=enabled,
        reviewer=reviewer,
        notes=str(payload.get("notes") or "").strip(),
    )
    return {"status": "updated", **result}


def _obsidian_account_dna_rollback(account_id: str, payload: Mapping[str, object]) -> dict[str, object]:
    reviewer = str(payload.get("reviewer") or "").strip()
    version_id = str(payload.get("version_id") or "").strip()
    if not reviewer:
        raise ValueError("请填写操作人")
    if not version_id:
        raise ValueError("请选择要回滚的账号思维包版本")
    repository = _configured_obsidian_vault(create=False)
    result = repository.rollback_account_dna(
        account_id,
        version_id,
        reviewer=reviewer,
        notes=str(payload.get("notes") or "").strip(),
    )
    return {"status": "rolled_back", **result}


def _account_knowledge_context_for_rewrite(account_id: str) -> dict[str, object]:
    """Load the selected account's governed Obsidian context for one rewrite."""

    account = str(account_id or "").strip()
    if not account:
        return {}
    if not str(_obsidian_config_read().get("vault_path") or "").strip():
        raise VaultConfigError("已选择思维包，但未配置 Obsidian Vault")
    repository = _configured_obsidian_vault(create=False)
    context = repository.load_account_dna_context(
        account,
        # 生产文案只能读取已审核且启用的账号思维包，实验版仅供后台查看。
        include_pending=False,
        max_chars_per_note=2_400,
    )
    if not context.get("available"):
        raise ObsidianRepositoryError(
            f"账号 {account} 的五份 Writing-DNA 尚未完整写入，不能用于本次文案"
        )
    return context


def _register_account_knowledge_material(payload: Mapping[str, object]) -> tuple[int, dict[str, object]]:
    """Register a video/article/document into the Obsidian professional inbox."""

    if not str(_obsidian_config_read().get("vault_path") or "").strip():
        return 503, {
            "status": "vault_not_configured",
            "message": "未配置 ACCOUNT_KNOWLEDGE_VAULT_PATH，资料未写入。",
        }
    material_type = str(payload.get("material_type") or "").strip().lower()
    if material_type not in {"video", "article", "document"}:
        return 400, {"status": "invalid_input", "message": "资料类型必须是 video、article 或 document"}
    source_url = str(payload.get("source_url") or "").strip()
    if source_url and not re.fullmatch(r"https?://[^\s]+", source_url, flags=re.IGNORECASE):
        return 400, {"status": "invalid_input", "message": "来源 URL 必须是 HTTP(S) 地址"}
    platform = str(payload.get("platform") or "auto").strip().lower() or "auto"
    allowed_platforms = {
        "auto", "douyin", "bilibili", "kuaishou", "weixin_video",
        "xiaohongshu", "wechat_article", "zhihu", "weibo", "other",
    }
    if platform not in allowed_platforms:
        return 400, {"status": "invalid_input", "message": "来源平台不在支持列表中"}
    content_text = str(payload.get("content_text") or "").strip()
    if len(content_text) > 60_000:
        return 413, {"status": "invalid_input", "message": "正文或摘要超过 60000 字符"}
    title = str(payload.get("title") or "").strip()[:200]
    domain = str(payload.get("domain") or "未分类").strip()[:80] or "未分类"
    tags_raw = payload.get("tags")
    tags = [str(item).strip() for item in tags_raw] if isinstance(tags_raw, (list, tuple)) else [
        item.strip() for item in re.split(r"[,，、\s]+", str(tags_raw or "")) if item.strip()
    ]
    tags = list(dict.fromkeys(tags))[:30]
    attachment_bytes: bytes | None = None
    attachment_name = ""
    attachment_mime = ""
    attachment = payload.get("file")
    if isinstance(attachment, Mapping):
        attachment_name = str(attachment.get("name") or "").strip()[:160]
        attachment_mime = str(attachment.get("mime_type") or "").strip()[:120]
        encoded = str(attachment.get("base64") or "").strip()
        if encoded:
            try:
                attachment_bytes = base64.b64decode(encoded, validate=True)
            except (ValueError, binascii.Error) as exc:
                return 400, {"status": "invalid_input", "message": "本地资料编码无效"}
            if len(attachment_bytes) > 24 * 1024 * 1024:
                return 413, {"status": "invalid_input", "message": "本地资料超过 24MB"}
    if not source_url and not content_text and attachment_bytes is None:
        return 400, {"status": "invalid_input", "message": "请提供链接、正文摘要或本地资料"}
    if material_type == "document" and attachment_bytes is None and not content_text:
        return 400, {"status": "invalid_input", "message": "本地文档类型需要选择文件或粘贴正文"}
    if platform == "auto" and source_url:
        host = urlparse(source_url).netloc.lower().removeprefix("www.")
        platform = {
            "douyin.com": "douyin", "v.douyin.com": "douyin",
            "bilibili.com": "bilibili", "b23.tv": "bilibili",
            "kuaishou.com": "kuaishou", "xiaohongshu.com": "xiaohongshu",
            "zhihu.com": "zhihu", "weibo.com": "weibo",
        }.get(host, "other")
    identity = "\x1f".join([material_type, platform, source_url, content_text, attachment_name])
    if attachment_bytes is not None:
        identity += "\x1f" + hashlib.sha256(attachment_bytes).hexdigest()
    material_id = "material-" + hashlib.sha256(identity.encode("utf-8")).hexdigest()[:20]
    repository = _configured_obsidian_vault(create=True)
    source_label = attachment_name or source_url or "粘贴正文"
    body_parts = [f"# {title or source_label}", "", f"- 资料类型：{material_type}", f"- 来源平台：{platform}", f"- 知识主题：{domain}", f"- 来源：{source_url or '未提供'}"]
    if tags:
        body_parts.append(f"- 标签：{'、'.join(tags)}")
    if content_text:
        body_parts.extend(["", "## 内容摘要 / 正文", content_text])
    body = "\n".join(body_parts) + "\n"
    paths = repository.save_professional_material(
        material_id=material_id,
        metadata={
            "material_type": material_type,
            "platform": platform,
            "source_url": source_url,
            "title": title or source_label,
            "domain": domain,
            "tags": tags,
            "attachment_name": attachment_name,
            "attachment_mime": attachment_mime,
            "registered_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        },
        body=body,
        source_bytes=attachment_bytes,
        source_suffix=Path(attachment_name).suffix.lower() if attachment_name else "",
    )
    return 201, {
        "status": "pending_processing",
        "message": "资料已写入 Obsidian 专业知识库待处理区，等待后续解析/蒸馏。",
        "material_id": material_id,
        "platform": platform,
        "material_type": material_type,
        "paths": paths,
    }


def _sync_style_collection_account_knowledge(
    report: Mapping[str, object],
    payload: Mapping[str, object],
    *,
    progress_reporter: Callable[[str, int, str], None] | None = None,
    distill_assets: bool = True,
    task_id: str = "",
    checkpoint_state: str = "saved",
    candidate_count: int | None = None,
) -> tuple[dict[str, object] | None, ObsidianRepository | None]:
    """在显式配置 Vault 时执行 8768→Obsidian 的桥接。

    账号主页第一阶段只落 RawSource/WorkCard/EvidenceSet/DistillationJob，
    通过 ``distill_assets=False`` 明确禁止模型；历史风格包入口继续使用
    默认的完整模型链，保持旧调用兼容。
    """

    mode = str(payload.get("account_knowledge_mode") or "optional").strip().lower()
    if mode not in {"required", "optional", "disabled"}:
        mode = "optional"
    if mode == "disabled":
        return {"status": "disabled", "knowledge_status": "NOT_USED"}, None
    if not str(_obsidian_config_read().get("vault_path") or "").strip():
        if mode == "required":
            raise VaultConfigError("未配置 ACCOUNT_KNOWLEDGE_VAULT_PATH；请先指定 Obsidian Vault 后再开始采集")
        return {
            "status": "not_configured",
            "knowledge_status": "NOT_CONFIGURED",
            "message": "未配置 ACCOUNT_KNOWLEDGE_VAULT_PATH，保留旧风格包链路",
        }, None
    try:
        repository = _configured_obsidian_vault(create=True)
        provider = None
        if distill_assets:
            provider = AccountKnowledgeModelProvider.from_runtime_config(
                api_management_config_path=API_MANAGEMENT_CONFIG_PATH,
                use_api_management_runtime=True,
            )
        if distill_assets and not task_id and checkpoint_state == "saved" and candidate_count is None:
            # Keep injected legacy bridge shims and old direct callers on the
            # original keyword contract; the evidence-only path below uses
            # the extended durable fields explicitly.
            result = sync_collection_to_obsidian(
                report,
                repository=repository,
                provider=provider,
                requested_account_id=str(payload.get("account_id") or ""),
                progress_reporter=progress_reporter,
            )
        else:
            result = sync_collection_to_obsidian(
                report,
                repository=repository,
                provider=provider,
                requested_account_id=str(payload.get("account_id") or ""),
                progress_reporter=progress_reporter,
                distill_assets=distill_assets,
                task_id=task_id,
                checkpoint_state=checkpoint_state,
                candidate_count=candidate_count,
            )
        return result, repository
    except (ObsidianRepositoryError, AccountKnowledgeModelError, ArkStoryConfigError, ArkStoryTransportError, ProductionBridgeError) as exc:
        # Account-level distillation is an optional enhancement for the
        # historical style-package entry.  A persisted Vault configuration
        # alone does not mean its model credentials are available; in that
        # case keep the legacy style-package path usable and expose the
        # degraded state in the returned report.  ``required`` still raises
        # so production callers that explicitly opt in cannot get a false
        # success.
        if mode == "optional":
            return {
                "status": "not_configured",
                "knowledge_status": "NOT_CONFIGURED",
                "message": f"账号知识库暂不可用，保留风格包链路：{str(exc)}",
                "error_type": type(exc).__name__,
            }, None
        raise ProductionBridgeError(str(exc)) from exc


def _create_style_package(
    payload: dict, *, progress_reporter: Callable[[str, int, str], None] | None = None,
    checkpoint: Mapping[str, object] | None = None,
    checkpoint_reporter: Callable[[dict[str, object]], None] | None = None,
    task_id: str = "",
) -> tuple[int, dict]:
    creator_url = str(payload.get("creator_home_url") or "").strip()
    # The first-stage account corpus path is deliberately evidence-only.  The
    # historical direct style-package entry leaves this flag unset and keeps
    # its existing model-backed behavior.
    distill_available_samples = payload.get("distill_available_samples") is True or str(payload.get("distill_available_samples") or "").strip().lower() in {"1", "true", "yes", "on"}
    evidence_only = payload.get("evidence_only") is True or str(payload.get("evidence_only") or "").strip().lower() in {"1", "true", "yes", "on"}
    # The production intake persists both values in the task snapshot.  The
    # historical 30/80 targets remain valid only for old direct callers.
    try:
        sample_target, max_video_duration_seconds = _style_collection_policy(payload)
    except ValueError as exc:
        return 400, {"status": "invalid_input", "message": str(exc)}
    # A production distillation task is always rooted in one or more
    # registered knowledge sources.  Keep the association on the task and on
    # the resulting assets; direct legacy callers without a source id remain
    # supported for backwards compatibility.
    source_ids = _knowledge_source_ids(payload)
    # 绑定了知识源的账号任务就是新的证据采集路径；即使旧调用方没有
    # 显式写 evidence_only，也不能让它悄悄退回浏览器/Cookie 链路。
    # A completed candidate inventory may contain fewer usable works than the
    # planning target.  When the user explicitly chooses to distill now, reuse
    # that durable report and let the distillers consume all available works.
    # An explicit request to reuse the completed local corpus is the only
    # transition out of evidence-only mode; persisted legacy snapshots may
    # still carry evidence_only=true and must not override that choice.
    if distill_available_samples:
        evidence_only = False
    else:
        evidence_only = evidence_only or bool(source_ids)
    source_versions: dict[str, str] = {}
    if source_ids:
        registry = _knowledge_source_registry()
        for source_id in source_ids:
            source_record = registry.get(source_id)
            if source_record is None:
                return 404, {
                    "status": "knowledge_source_missing",
                    "message": f"未找到知识源：{source_id}",
                    "knowledge_source_ids": source_ids,
                }
            source_versions[source_id] = str(source_record.get("source_version") or "source-v1")
    precollected_report = checkpoint.get("precollected_report") if isinstance(checkpoint, Mapping) else None
    collection_id = str(checkpoint.get("precollected_collection_id") or "").strip() if isinstance(checkpoint, Mapping) else ""
    item_sync_errors: list[str] = []

    def report_collected_item(item: Mapping[str, object]) -> None:
        """Persist one completed transcript before the batch finishes."""

        if not evidence_only:
            return
        fragment = {
            "collection_status": "partial",
            "platform": "douyin",
            "creator_id": str(item.get("creator_id") or payload.get("creator_id") or "").strip(),
            "creator_url": creator_url,
            "creator_name": str(payload.get("creator_name") or "").strip(),
            "items": [dict(item)],
            "knowledge_source_ids": list(source_ids),
            "knowledge_source_versions": dict(source_versions),
            "target_valid_works": sample_target,
        }
        try:
            _sync_style_collection_account_knowledge(
                fragment,
                payload,
                progress_reporter=None,
                distill_assets=False,
                task_id=task_id,
                checkpoint_state="item_saved",
                candidate_count=0,
            )
        except Exception as exc:
            item_sync_errors.append(f"{str(item.get('video_id') or item.get('bvid') or 'unknown')}: {type(exc).__name__}")
    if isinstance(precollected_report, Mapping):
        report = dict(precollected_report)
        if progress_reporter is not None:
            progress_reporter("collected", 72, "已读取已有采集结果，使用现有样本继续蒸馏")
    else:
        try:
            platform = _platform_from_url(creator_url)
            if progress_reporter is not None:
                progress_reporter("collecting", 5, "正在校验达人主页链接")
            if platform == "douyin":
                if evidence_only:
                    # 新的账号证据采集默认走 TikHub。适配器失败只返回
                    # blocked/partial，不自动触发旧浏览器、Cookie 或扫码。
                    report = collect_douyin_creator_tikhub(
                        creator_url,
                        limit=sample_target,
                        target_samples=sample_target,
                        crawl_limit=int(payload.get("url_inventory_target") or 80),
                        max_video_duration_seconds=max_video_duration_seconds,
                        progress_reporter=progress_reporter,
                        checkpoint=checkpoint,
                        checkpoint_reporter=checkpoint_reporter,
                        item_reporter=report_collected_item,
                        adapter=TikHubDouyinAdapter(transport=TIKHUB_TRANSPORT),
                        account_id=str(payload.get("account_id") or ""),
                        creator_name=str(payload.get("creator_name") or ""),
                        source_id=source_ids[0] if source_ids else "",
                        evidence_set_id=str((checkpoint or {}).get("evidence_set_id") or "") if isinstance(checkpoint, Mapping) else "",
                    )
                else:
                    # 历史直接风格包入口保持原浏览器/Cookie 采集兼容。
                    report = collect_douyin_creator(
                        creator_url,
                        limit=sample_target,
                        target_samples=sample_target,
                        max_video_duration_seconds=max_video_duration_seconds,
                        progress_reporter=progress_reporter,
                        checkpoint=checkpoint,
                        checkpoint_reporter=checkpoint_reporter,
                        item_reporter=None,
                    )
            elif platform == "bilibili":
                if progress_reporter is not None:
                    progress_reporter("collecting", 15, "正在采集 B 站公开作品")
                report = collect_creator(
                    creator_url,
                    limit=sample_target,
                    max_video_duration_seconds=max_video_duration_seconds,
                )
            else:
                return 422, {"status": "collection_blocked", "message": "当前支持抖音主页；B 站为兼容入口。请粘贴展开后的主页链接。"}
        except (BilibiliCollectorError, DouyinCollectorError) as exc:
            return 422, {"status": "collection_blocked", "message": str(exc)}
    if not collection_id:
        collection_id = STYLE_PACKAGE_STORE.save_collection(report)
    report["collection_policy"] = {
        "sample_target": sample_target,
        "max_video_duration_seconds": max_video_duration_seconds,
    }
    checkpoint_statuses = (
        dict(report.get("checkpoint") or {}).get("transcript_status", {})
        if isinstance(report.get("checkpoint"), Mapping)
        else {}
    )
    resumed_completed_evidence = bool(
        evidence_only
        and isinstance(checkpoint_statuses, Mapping)
        and any(str(value).strip() == "local_whisper" for value in checkpoint_statuses.values())
    )
    if report.get("collection_status") not in {"completed", "partial"} or (
        not report.get("items") and not resumed_completed_evidence
    ):
        return 422, {"status": "collection_blocked", "collection_id": collection_id, "message": "抖音主页采集未完成", "report": report}
    creator_name = str(report.get("creator_name") or "").strip()
    if not creator_name:
        return 422, {
            "status": "creator_name_missing",
            "collection_id": collection_id,
            "message": "未能从达人主页读取博主名称；为避免使用模型自动名称，未生成风格包。",
            "report": report,
        }
    ready_count = int(report.get("transcript_ready_count") or 0)
    report["sample_target_reached"] = ready_count >= sample_target
    report["sample_target_policy"] = "soft_cap"
    report["distillation_sample_count"] = ready_count
    if ready_count <= 0 and not evidence_only:
        return 422, {
            "status": "sample_empty", "collection_id": collection_id,
            "message": "没有可用于蒸馏的有效转写样本；未生成风格包。",
            "report": report,
        }
    if source_ids:
        # Source identity must be present before the bridge writes raw works,
        # work cards and account DNA.  This makes the Vault the first durable
        # asset stage rather than a side effect after language distillation.
        report["knowledge_source_ids"] = list(source_ids)
        report["knowledge_source_versions"] = dict(source_versions)
    account_knowledge = None
    account_repository = None
    try:
        if progress_reporter is not None:
            progress_reporter("storing_works", 78, "正在写入 Obsidian 原始转写和作品卡")
        sync_kwargs = {
            "progress_reporter": progress_reporter,
        }
        if evidence_only:
            sync_kwargs.update({
                "distill_assets": False,
                "task_id": task_id,
                "checkpoint_state": "collected",
                "candidate_count": int(report.get("candidate_count") or report.get("raw_listed_count") or report.get("listed_count") or len(report.get("items") or [])),
            })
        account_knowledge, account_repository = _sync_style_collection_account_knowledge(report, payload, **sync_kwargs)
    except (ObsidianRepositoryError, ProductionBridgeError) as exc:
        diagnostics = dict(report.get("diagnostics") or {})
        diagnostics["account_knowledge_error"] = str(exc)
        diagnostics["account_knowledge_error_type"] = type(exc).__name__
        report["diagnostics"] = diagnostics
        return 503, {
            "status": "account_knowledge_distillation_failed",
            "collection_id": collection_id,
            "message": str(exc),
            "report": report,
        }
    report["account_knowledge"] = account_knowledge or {"status": "not_used"}
    if evidence_only and isinstance(account_knowledge, Mapping):
        # 证据集是在逐篇落盘后由桥接层生成的；把它回写到同一份稳定
        # checkpoint，便于服务重启后从 Obsidian 继续而不依赖临时 URL。
        resolved_evidence_set_id = str(account_knowledge.get("evidence_set_id") or "").strip()
        if resolved_evidence_set_id:
            report["evidence_set_id"] = resolved_evidence_set_id
            if checkpoint_reporter is not None and isinstance(report.get("checkpoint"), Mapping):
                durable_checkpoint = dict(report.get("checkpoint") or {})
                durable_checkpoint["evidence_set_id"] = resolved_evidence_set_id
                if source_ids and not durable_checkpoint.get("source_id"):
                    durable_checkpoint["source_id"] = source_ids[0]
                checkpoint_reporter(durable_checkpoint)
    if item_sync_errors:
        report.setdefault("diagnostics", {})["item_sync_errors"] = list(item_sync_errors)
        if evidence_only and account_knowledge and account_knowledge.get("status") == "not_configured":
            return 503, {"status": "account_knowledge_distillation_failed", "collection_id": collection_id, "message": "部分作品未能逐篇写入 Obsidian：" + "；".join(item_sync_errors[:3]), "report": report}

    if evidence_only:
        evidence_status = str((account_knowledge or {}).get("evidence_status") or "WAITING_FOR_EVIDENCE")
        evidence_message = (
            f"已保存 {int((account_knowledge or {}).get('eligible_work_count') or 0)}/{int((account_knowledge or {}).get('target_valid_works') or sample_target)} 篇合格作品"
        )
        if evidence_status == "READY_TO_DISTILL":
            evidence_message += "；证据集已达到目标，等待后续 Skill 蒸馏"
        else:
            evidence_message += "；证据不足，可从断点继续采集"
        if progress_reporter is not None:
            progress_reporter("ready_to_distill" if evidence_status == "READY_TO_DISTILL" else "waiting_for_evidence", 78 if evidence_status == "READY_TO_DISTILL" else 72, evidence_message)
        return 201, {
            "status": "ready_to_distill" if evidence_status == "READY_TO_DISTILL" else "waiting_for_evidence",
            "account_knowledge": account_knowledge,
            "report": report,
            "collection_id": collection_id,
            "evidence_set_id": (account_knowledge or {}).get("evidence_set_id", ""),
        }
    try:
        if progress_reporter is not None:
            progress_reporter(
                "style_distilling", 99,
                f"已写入作品卡和账号思维包；使用 {ready_count} 条有效样本蒸馏语言风格包",
            )
        profile, samples = distill_style_package(
            creator_url=creator_url,
            source_items=report["items"],
            minimum_samples=sample_target,
            allow_partial_samples=True,
            fallback_profile_name=creator_name,
            fallback_overview="基于已采集公开样本提炼的可复用表达规则；生成后请到知识资产中枢后台管理中修改或启用。",
            transport=ArkStoryFailoverHTTPTransport.from_runtime_config(
                include_language_model_api_fallback=True,
            ),
            )
    except ArkStoryConfigError as exc:
        return 503, {"status": "model_not_configured", "collection_id": collection_id, "message": str(exc), "report": report}
    except (ArkStoryTransportError, StylePackageError) as exc:
        diagnostics = dict(report.get("diagnostics") or {})
        diagnostics["distillation_error"] = str(exc)
        diagnostics["distillation_error_type"] = type(exc).__name__
        report["diagnostics"] = diagnostics
        return 502, {"status": "distillation_failed", "collection_id": collection_id, "message": str(exc), "report": report}
    # The number that governs Writing-DNA reliability is the number of
    # complete, usable samples returned by the distiller—not merely the
    # requested collection target or scanned candidates.  Persist the gate in
    # the profile so approval and runtime selection cannot silently treat a
    # small corpus as a formal style asset.
    try:
        effective_sample_count = len(samples) if isinstance(samples, Sequence) and not isinstance(samples, (str, bytes)) else ready_count
        writing_dna_gate = validate_writing_dna_sample_count(effective_sample_count)
    except (TypeError, ValueError) as exc:
        return 422, {
            "status": "sample_invalid",
            "collection_id": collection_id,
            "message": str(exc),
            "report": report,
        }
    report["writing_dna_gate"] = dict(writing_dna_gate)
    profile = dict(profile)
    profile["writing_dna_gate"] = dict(writing_dna_gate)
    profile["distillation_sample_count"] = effective_sample_count
    if source_ids:
        # ``knowledge_source_ids`` is the authoritative source trace for the
        # language package.  Keep ``source_ids`` as an additive compatibility
        # alias for existing readers that already display that field.
        profile["knowledge_source_ids"] = list(source_ids)
        profile["knowledge_source_versions"] = dict(source_versions)
        profile["source_ids"] = list(source_ids)
    if account_knowledge and account_knowledge.get("status") == "review_required" and account_repository is not None:
        account_id = str(account_knowledge.get("account_id") or "").strip()
        if account_id:
            try:
                profile = dict(profile)
                profile["account_id"] = account_id
                profile["account_knowledge_context"] = account_repository.load_account_dna_context(
                    account_id,
                    include_pending=True,
                )
            except Exception as exc:
                return 503, {
                    "status": "account_knowledge_context_failed",
                    "collection_id": collection_id,
                    "message": f"账号知识库已写入，但风格包未能绑定账号上下文：{type(exc).__name__}",
                    "account_knowledge": account_knowledge,
                    "report": report,
                }
    record = STYLE_PACKAGE_STORE.save_profile(
        profile=profile,
        creator_url=creator_url,
        collection_id=collection_id,
        sample_count=effective_sample_count,
        creator_name=creator_name,
    )
    if source_ids:
        binding_errors: list[str] = []
        asset_ids = [str(record.get("style_profile_id") or "").strip()]
        account_id = str((account_knowledge or {}).get("account_id") or profile.get("account_id") or "").strip()
        if account_id:
            # Prefix the account asset id so the registry can distinguish the
            # account thinking package from the language style package.
            asset_ids.append(f"account-dna-{account_id}")
        for source_id in source_ids:
            for asset_id in asset_ids:
                if not asset_id:
                    continue
                try:
                    registry.bind_asset(source_id, asset_id)
                except (KnowledgeSourceError, OSError) as exc:
                    binding_errors.append(f"{source_id} -> {asset_id}: {type(exc).__name__}")
        report["source_binding_status"] = "complete" if not binding_errors else "partial"
        if binding_errors:
            report["source_binding_errors"] = binding_errors
    if progress_reporter is not None:
        progress_reporter("completed", 100, "账号资产已生成，请到知识资产中枢后台管理修改或启用")
    return 201, {"status": "pending_user_review", "record": record, "report": report}


def _task_file(task_id: str) -> Path:
    return STYLE_TASK_DIR / f"{task_id}.json"


def _task_scan_dirs() -> list[Path]:
    """Return the active task directory plus the legacy directory for read-only recall."""

    directories = [STYLE_TASK_DIR]
    try:
        active = STYLE_TASK_DIR.resolve()
        default = DEFAULT_STYLE_TASK_DIR.resolve()
    except OSError:
        active = STYLE_TASK_DIR
        default = DEFAULT_STYLE_TASK_DIR
    # Only an explicit runtime override inherits the old AppData archive. Tests
    # and story-scoped temporary dirs must stay isolated from the user's tasks.
    if TASK_RUNTIME_ROOT_OVERRIDE and active != default and _TASK_RUNTIME_INCLUDE_LEGACY:
        directories.append(DEFAULT_STYLE_TASK_DIR)
    unique: list[Path] = []
    seen: set[str] = set()
    for directory in directories:
        key = str(directory).lower()
        if key not in seen:
            seen.add(key)
            unique.append(directory)
    return unique


def _task_paths(task_id: str | None = None) -> list[Path]:
    if task_id:
        return [directory / f"{task_id}.json" for directory in _task_scan_dirs()]
    paths: list[Path] = []
    for directory in _task_scan_dirs():
        try:
            paths.extend(directory.glob("*.json"))
        except OSError:
            continue
    return paths


def _persisted_task_snapshots() -> list[dict]:
    """Read current snapshots first, then legacy snapshots without duplicate IDs."""

    by_id: dict[str, dict] = {}
    for path in _task_paths():
        task = _load_persisted_task(path.stem)
        if not isinstance(task, dict) or not task.get("task_id"):
            continue
        by_id.setdefault(str(task["task_id"]), task)
    return list(by_id.values())


def _style_task_listing_cache_key() -> str:
    """Return a process-local key that also changes for isolated test runtimes."""

    try:
        active = str(STYLE_TASK_DIR.resolve())
        default = str(DEFAULT_STYLE_TASK_DIR.resolve())
    except OSError:
        active = str(STYLE_TASK_DIR)
        default = str(DEFAULT_STYLE_TASK_DIR)
    return "|".join((active, default, str(bool(_TASK_RUNTIME_INCLUDE_LEGACY)), str(id(STYLE_TASKS))))


def _invalidate_style_task_listing_cache() -> None:
    """Invalidate the read-only list cache after a durable task update."""

    with STYLE_TASK_LIST_CACHE_LOCK:
        STYLE_TASK_LIST_CACHE["key"] = ""
        STYLE_TASK_LIST_CACHE["created_at"] = 0.0
        STYLE_TASK_LIST_CACHE["tasks"] = []


def _utc_timestamp() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


class TaskPersistenceError(RuntimeError):
    """A required task snapshot could not be written durably."""


def _task_input_fingerprint(task_type: str, payload: Mapping[str, object] | None) -> str:
    """Build a stable, non-secret identity for idempotent task creation."""

    public_payload = dict(payload or {})
    if task_type == "case_rewrite":
        public_payload = {
            "case_video_url": str(public_payload.get("case_video_url") or "").strip(),
            "source_content_id": str(public_payload.get("source_content_id") or "").strip(),
            "source_text": str(public_payload.get("source_text") or "").strip(),
            "topic_selection_id": str(public_payload.get("topic_selection_id") or "").strip(),
            "knowledge_source_ids": sorted({
                str(value).strip()
                for value in (public_payload.get("knowledge_source_ids") or [])
                if str(value).strip()
            }) if isinstance(public_payload.get("knowledge_source_ids"), (list, tuple, set)) else [str(public_payload.get("knowledge_source_ids") or "").strip()] if str(public_payload.get("knowledge_source_ids") or "").strip() else [],
            "knowledge_source_versions": dict(public_payload.get("knowledge_source_versions") or {}) if isinstance(public_payload.get("knowledge_source_versions"), Mapping) else {},
            "style_profile_id": str(public_payload.get("style_profile_id") or "").strip(),
            "topic": str(public_payload.get("topic") or public_payload.get("writing_topic") or "").strip(),
            "target_platform": str(public_payload.get("target_platform") or public_payload.get("publish_platform") or "").strip().lower(),
            "audience": str(public_payload.get("audience") or public_payload.get("target_audience") or public_payload.get("writing_audience") or "").strip(),
            "thinking_package_id": str(public_payload.get("thinking_package_id") or public_payload.get("viewpoint_package_id") or "").strip(),
            "rewrite_goal": str(public_payload.get("rewrite_goal") or "保留事实与观点，重新表达").strip(),
            "publish_format": str(public_payload.get("publish_format") or "知识口播短视频").strip(),
            "target_duration": str(public_payload.get("target_duration") or "60 秒").strip(),
            "personalized_slogan": str(public_payload.get("personalized_slogan") or "").strip(),
            "creative_direction": str(public_payload.get("creative_direction") or "").strip(),
        }
    canonical = json.dumps(
        {"task_type": str(task_type or ""), "input": public_payload},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _task_lifecycle_status(task: Mapping[str, object]) -> str:
    """Return the durable lifecycle bucket used for visibility and recovery."""

    explicit = str(task.get("lifecycle_status") or "").strip().lower()
    # 归档、替代和废弃是不可由当前状态推翻的治理标记；recoverable 也要
    # 保留，避免服务重启后把人工可恢复任务重新归入普通历史。旧快照中常见
    # 的 ``lifecycle_status=active`` 不能直接信任，否则 failed/succeeded 会
    # 继续出现在“当前任务”视图。
    if explicit in {"recoverable", "archived", "superseded", "deprecated"}:
        return explicit
    if task.get("archived_at") or task.get("runtime_data_archived"):
        return "archived"
    if task.get("superseded_by"):
        return "superseded"
    if task.get("deprecated") is True:
        return "deprecated"
    task_type = str(task.get("task_type") or "")
    state = str(task.get("state") or "")
    stage = str(task.get("stage") or "")
    if state in {"queued", "running"}:
        return "active"
    if state == "interrupted" or (
        task_type == "style_collection" and stage in _RESUMABLE_STYLE_PARTIAL_STAGES
    ):
        return "recoverable"
    return "archived"


def _normalize_task_snapshot(task: Mapping[str, object]) -> dict:
    """Apply the durable task contract without removing legacy fields."""

    normalized = dict(task)
    task_type = str(normalized.get("task_type") or "unknown")
    # 极早期的通用状态探针只有 task_id/state/updated_at，不属于可执行任务。
    # 保持它们的原始形状，避免兼容读取把诊断对象误升级成生产任务；真正的
    # 风格/编导/素材任务都会带 input、worker、result 或 task_type，继续补齐
    # 完整持久化契约。
    if task_type == "unknown" and not any(
        key in normalized for key in ("input", "worker", "result", "source_story_task_id")
    ):
        return normalized
    input_payload = normalized.get("input")
    input_mapping = dict(input_payload) if isinstance(input_payload, Mapping) else {}
    normalized.setdefault("workflow_version", TASK_WORKFLOW_VERSION)
    normalized.setdefault("schema_version", TASK_SCHEMA_VERSION)
    normalized.setdefault("state", "unknown")
    normalized.setdefault("stage", "unknown")
    normalized.setdefault("progress", 0)
    normalized.setdefault("message", "")
    normalized.setdefault("created_at", int(time.time()))
    normalized.setdefault("updated_at", normalized.get("created_at", int(time.time())))
    normalized.setdefault("input_fingerprint", _task_input_fingerprint(task_type, input_mapping))
    normalized.setdefault("parent_task_id", str(normalized.get("source_story_task_id") or ""))
    normalized.setdefault("archive_id", "")
    normalized.setdefault("legacy_status", "legacy" if task_type == "style_collection" else "current")
    normalized.setdefault("error_code", "")
    normalized.setdefault("error_detail", "")
    normalized.setdefault("worker_entry_path", str(normalized.get("worker", {}).get("entry_path") or "") if isinstance(normalized.get("worker"), Mapping) else "")
    normalized.setdefault("worker_pid", int(normalized.get("worker", {}).get("pid") or 0) if isinstance(normalized.get("worker"), Mapping) else 0)
    # 旧快照可能把终态任务错误持久化为 ``active``。每次读取都按当前
    # state/stage 重算生命周期，保留 recoverable/archived 等治理标记，避免
    # failed 的 collection_blocked 任务继续冒充正在执行。
    normalized["lifecycle_status"] = _task_lifecycle_status(normalized)
    return normalized


def _external_style_worker(task: Mapping[str, object] | None) -> bool:
    if not isinstance(task, Mapping) or task.get("task_type") != "style_collection":
        return False
    worker = task.get("worker")
    return isinstance(worker, Mapping) and bool(worker.get("pid"))


def _style_worker_identity(task: Mapping[str, object]) -> bool | None:
    """验证蒸馏子进程是否仍属于当前工作树；无法读取进程表时保持保守。"""

    worker = task.get("worker")
    if not isinstance(worker, Mapping):
        return False
    try:
        pid = int(worker.get("pid") or 0)
    except (TypeError, ValueError):
        return False
    if pid <= 0:
        return False
    task_id = str(task.get("task_id") or "").strip()

    def fresh_heartbeat() -> bool:
        """在受限 Windows 进程表漏掉子进程时，信任短期有效的自维护心跳。

        服务重启或轮询期间，Get-Process/Win32_Process 可能暂时看不到由
        venv launcher 拉起的真实 worker PID。只要心跳仍由同一 task/PID
        写入且未超过 45 秒，就不能把正在执行的任务误判为已退出；否则
        后续进度写入会被 ``_set_task`` 的 interrupted 保护锁住，页面会
        永久停在旧百分比。
        """
        marker_path = STYLE_WORKER_HEARTBEAT_DIR / f"{task_id}.json"
        try:
            marker = json.loads(marker_path.read_text(encoding="utf-8"))
            marker_pid = int(marker.get("pid") or 0)
            heartbeat_at = float(marker.get("heartbeat_unix") or 0)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError):
            return False
        return bool(
            marker.get("state") == "running"
            and marker.get("task_id") == task_id
            and marker_pid == pid
            and heartbeat_at > 0
            and time.time() - heartbeat_at <= 45
        )

    processes = process_snapshot()
    if processes:
        process = processes.get(pid)
        if not isinstance(process, Mapping):
            # 受限 Windows 进程枚举可能漏掉真实 worker；新鲜心跳优先于
            # “PID 不在列表”这一条弱证据，避免服务重启时误中断任务。
            return fresh_heartbeat()
        command = str(process.get("command_line") or "").lower().replace("/", "\\")
        if not command:
            # Windows fallback process listing exposes the PID but can omit the
            # command line. A fresh worker heartbeat is enough to distinguish
            # this from a genuinely exited worker without killing its task.
            return fresh_heartbeat()
        entry = str(STYLE_WORKER_ENTRY.resolve()).lower().replace("/", "\\")
        root = str(ROOT.resolve()).lower().replace("/", "\\")
        return bool(task_id and entry in command and root in command and task_id.lower() in command)

    # 受限环境无法读取 Win32_Process 时，使用 worker 自己维护的短期心跳；
    # 没有近期心跳时宁可中断并允许用户从断点恢复，也不把死进程当成运行中。
    return fresh_heartbeat()


def _read_style_worker_heartbeat(task_id: str) -> dict[str, object] | None:
    marker_path = STYLE_WORKER_HEARTBEAT_DIR / f"{task_id}.json"
    try:
        marker = json.loads(marker_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    if not isinstance(marker, dict) or str(marker.get("task_id") or "") != task_id:
        return None
    try:
        if int(marker.get("pid") or 0) <= 0:
            return None
    except (TypeError, ValueError):
        return None
    return marker


def _attach_style_worker_heartbeat(task: Mapping[str, object]) -> dict[str, object]:
    """把 worker 心跳以只读元数据附加到任务详情，供前台判断是否仍存活。"""
    snapshot = dict(task)
    if str(snapshot.get("task_type") or "") != "style_collection":
        return snapshot
    task_id = str(snapshot.get("task_id") or "").strip()
    marker = _read_style_worker_heartbeat(task_id) if task_id else None
    if marker is None:
        snapshot["worker_heartbeat"] = {"available": False, "alive": False}
        return snapshot
    try:
        heartbeat_unix = float(marker.get("heartbeat_unix") or 0)
    except (TypeError, ValueError):
        heartbeat_unix = 0.0
    age = max(0.0, time.time() - heartbeat_unix) if heartbeat_unix else None
    snapshot["worker_heartbeat"] = {
        "available": True,
        "alive": marker.get("state") == "running" and age is not None and age <= 45,
        "state": str(marker.get("state") or "unknown"),
        "heartbeat_unix": heartbeat_unix,
        "age_seconds": round(age, 1) if age is not None else None,
        "pid": int(marker.get("pid") or 0),
    }
    return snapshot


def _annotate_style_worker_heartbeat(task_id: str, **values: object) -> None:
    marker = _read_style_worker_heartbeat(task_id)
    if marker is None:
        return
    marker.update(values)
    target = STYLE_WORKER_HEARTBEAT_DIR / f"{task_id}.json"
    temporary = target.with_suffix(".tmp")
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary.write_text(json.dumps(marker, ensure_ascii=False, indent=2), encoding="utf-8")
        temporary.replace(target)
    except OSError:
        pass


def _style_worker_metadata(
    task_id: str,
    pid: int,
    command: list[str],
    *,
    state: str,
    launcher_pid: int | None = None,
    **extra: object,
) -> dict[str, object]:
    metadata = {
        "kind": "style_collection_worker",
        "task_id": task_id,
        "pid": int(pid),
        "state": state,
        "started_at": _utc_timestamp(),
        "project_root": str(ROOT.resolve()),
        "worktree_root": str(SERVICE_SPEC.worktree_root),
        "entry_path": str(STYLE_WORKER_ENTRY.resolve()),
        "launch_command": list(command),
        "heartbeat_path": str((STYLE_WORKER_HEARTBEAT_DIR / f"{task_id}.json").resolve()),
    }
    if launcher_pid is not None:
        metadata["launcher_pid"] = int(launcher_pid)
    metadata.update(extra)
    return metadata


def _start_style_worker(task_id: str) -> dict[str, object]:
    """启动独立蒸馏进程；8768 不再承载采集线程。"""

    command = [sys.executable, str(STYLE_WORKER_ENTRY), "--task-id", str(task_id)]
    worker_log = TASK_RUNTIME_DIR / f"style_worker_{task_id}.log"
    worker_log.parent.mkdir(parents=True, exist_ok=True)
    try:
        with worker_log.open("a", encoding="utf-8", newline="\n") as log:
            process = subprocess.Popen(
                command,
                cwd=str(ROOT),
                env=os.environ.copy(),
                stdout=log,
                stderr=log,
                creationflags=getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
    except OSError as exc:
        raise RuntimeError(f"蒸馏独立进程启动失败：{type(exc).__name__}") from exc

    # Windows venv\Scripts\python.exe may be a launcher: Popen.pid can exit
    # while the real Python child continues under another PID.  Wait briefly
    # for the worker heartbeat and record the child PID as the service identity.
    marker: dict[str, object] | None = None
    deadline = time.monotonic() + 5.0
    while time.monotonic() < deadline:
        marker = _read_style_worker_heartbeat(task_id)
        if marker is not None:
            _annotate_style_worker_heartbeat(task_id, launcher_pid=int(process.pid))
            marker["launcher_pid"] = int(process.pid)
            break
        time.sleep(0.1)
    actual_pid = int(marker.get("pid") or process.pid) if marker else int(process.pid)
    state = str(marker.get("state") or "running") if marker else "running"
    extra = {
        key: marker[key]
        for key in ("finished_at", "final_state")
        if marker is not None and key in marker
    }
    return _style_worker_metadata(
        task_id,
        actual_pid,
        command,
        state=state,
        launcher_pid=int(process.pid),
        **extra,
    )


def _material_inputs_path(story_task_id: str) -> Path:
    return DIRECTOR_REVIEW_DIR / story_task_id / "material_inputs.json"


def _save_material_inputs(story_task_id: str, payload: Mapping[str, object]) -> dict:
    """保存用户明确选择的素材层图片与可选 BGM；只保存本机文件路径。"""
    target_dir = DIRECTOR_REVIEW_DIR / story_task_id / "material_inputs"
    target_dir.mkdir(parents=True, exist_ok=True)

    def decode_images(key: str, prefix: str) -> list[str]:
        values = payload.get(key)
        if not isinstance(values, list):
            return []
        paths: list[str] = []
        for index, value in enumerate(values, start=1):
            if not isinstance(value, str) or not value.startswith("data:image/") or "," not in value:
                raise ValueError(f"{key} 第 {index} 项不是有效图片")
            header, encoded = value.split(",", 1)
            mime = header.split(";")[0].removeprefix("data:").lower()
            extension = {"image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp"}.get(mime)
            if extension is None:
                raise ValueError(f"{key} 仅支持 JPG、PNG、WebP")
            try:
                binary = base64.b64decode(encoded, validate=True)
            except ValueError as exc:
                raise ValueError(f"{key} 第 {index} 项解码失败") from exc
            if not binary or len(binary) > 12 * 1024 * 1024:
                raise ValueError(f"{key} 第 {index} 项大小必须在 1 字节到 12MB 之间")
            path = target_dir / f"{prefix}_{index:02d}{extension}"
            path.write_bytes(binary)
            paths.append(str(path.resolve()))
        return paths

    style_paths = decode_images("style_reference_images", "style_reference")
    digital_paths = decode_images("digital_human_images", "digital_human")
    existing = _load_material_inputs(story_task_id)
    guidance_present = "visual_guidance_prompt" in payload
    guidance_prompt = str(
        payload.get("visual_guidance_prompt", existing.get("visual_guidance_prompt", "")) or ""
    ).strip()[:2000]
    guidance_source = str(payload.get("visual_guidance_source") or payload.get("source") or "").strip()
    result = {
        "style_reference_images": style_paths if "style_reference_images" in payload else existing.get("style_reference_images", []),
        "digital_human_images": digital_paths if "digital_human_images" in payload else existing.get("digital_human_images", []),
        "bgm_audio": existing.get("bgm_audio"),
        "visual_guidance_prompt": guidance_prompt,
        "visual_guidance_source": (
            "explicit_user" if guidance_present and guidance_prompt and guidance_source == "explicit_user"
            else "" if guidance_present
            else str(existing.get("visual_guidance_source") or "")
        ),
    }
    _material_inputs_path(story_task_id).write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    return {
        "style_reference_count": len(style_paths),
        "digital_human_count": len(digital_paths),
        "bgm_uploaded": bool(result["bgm_audio"]),
    }


def _upload_material_images(story_task_id: str, kind: str, payload: Mapping[str, object]) -> dict[str, object]:
    """Save one browser-selected image group without overwriting the other group."""
    fields = {
        "style": ("style_reference_images", "style_reference"),
        "digital": ("digital_human_images", "digital_human"),
    }
    if kind not in fields:
        raise ValueError("图片类型必须是 style 或 digital")
    images = payload.get("images")
    if not isinstance(images, list) or not images:
        raise ValueError("请选择至少一张图片")
    if len(images) > MAX_REFERENCE_IMAGES:
        raise ValueError(f"一次最多选择 {MAX_REFERENCE_IMAGES} 张图片")

    field, prefix = fields[kind]
    target_dir = DIRECTOR_REVIEW_DIR / story_task_id / "material_inputs"
    target_dir.mkdir(parents=True, exist_ok=True)
    saved_paths: list[str] = []
    for index, value in enumerate(images, start=1):
        if not isinstance(value, str) or not value.startswith("data:image/") or "," not in value:
            raise ValueError(f"第 {index} 项不是有效图片")
        header, encoded = value.split(",", 1)
        mime = header.split(";")[0].removeprefix("data:").lower()
        extension = {"image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp"}.get(mime)
        if extension is None:
            raise ValueError("仅支持 JPG、PNG、WebP 图片")
        try:
            binary = base64.b64decode(encoded, validate=True)
        except ValueError as exc:
            raise ValueError(f"第 {index} 项解码失败") from exc
        if not binary or len(binary) > 12 * 1024 * 1024:
            raise ValueError(f"第 {index} 项大小必须在 1 字节到 12MB 之间")
        destination = target_dir / f"{prefix}_{index:02d}{extension}"
        destination.write_bytes(binary)
        saved_paths.append(str(destination.resolve()))

    material_inputs = _load_material_inputs(story_task_id)
    material_inputs[field] = saved_paths
    _material_inputs_path(story_task_id).write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return _material_inputs_public_summary(story_task_id)


def _load_material_inputs(story_task_id: str) -> dict[str, object]:
    try:
        value = json.loads(_material_inputs_path(story_task_id).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {"style_reference_images": [], "digital_human_images": [], "bgm_audio": None, "visual_guidance_prompt": "", "visual_guidance_source": ""}
    if not isinstance(value, Mapping):
        return {"style_reference_images": [], "digital_human_images": [], "bgm_audio": None, "visual_guidance_prompt": "", "visual_guidance_source": ""}
    result: dict[str, object] = {
        key: [str(item) for item in value.get(key, []) if Path(str(item)).is_file()]
        for key in ("style_reference_images", "digital_human_images")
    }
    bgm_path = str(value.get("bgm_audio") or "").strip()
    result["bgm_audio"] = bgm_path if bgm_path and Path(bgm_path).is_file() else None
    result["visual_guidance_prompt"] = str(value.get("visual_guidance_prompt") or "").strip()[:2000]
    result["visual_guidance_source"] = str(value.get("visual_guidance_source") or "").strip()
    return result


def _save_visual_guidance(story_task_id: str, payload: Mapping[str, object]) -> dict[str, object]:
    """保存用户对参考图的额外视觉要求，不改变已选素材。"""
    material_inputs = _load_material_inputs(story_task_id)
    prompt = str(payload.get("visual_guidance_prompt") or "").strip()[:2000]
    material_inputs["visual_guidance_prompt"] = prompt
    material_inputs["visual_guidance_source"] = "explicit_user" if prompt else ""
    path = _material_inputs_path(story_task_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return _material_inputs_public_summary(story_task_id)


def _save_material_bgm(story_task_id: str, payload: Mapping[str, object]) -> dict[str, object]:
    """保存用户上传的单条可选 BGM，不覆盖参考图与数字人形象图。"""
    value = payload.get("audio")
    if not isinstance(value, str) or not value.startswith("data:audio/") or "," not in value:
        raise ValueError("请选择有效的音频文件")
    header, encoded = value.split(",", 1)
    mime = header.split(";")[0].removeprefix("data:").lower()
    extension = {
        "audio/mpeg": ".mp3", "audio/mp3": ".mp3", "audio/wav": ".wav",
        "audio/x-wav": ".wav", "audio/mp4": ".m4a", "audio/aac": ".aac",
        "audio/ogg": ".ogg",
    }.get(mime)
    if extension is None:
        raise ValueError("BGM 仅支持 MP3、WAV、M4A、AAC、OGG")
    try:
        binary = base64.b64decode(encoded, validate=True)
    except ValueError as exc:
        raise ValueError("BGM 文件解码失败") from exc
    if not binary or len(binary) > 80 * 1024 * 1024:
        raise ValueError("BGM 大小必须在 1 字节到 80MB 之间")
    target_dir = DIRECTOR_REVIEW_DIR / story_task_id / "material_inputs"
    target_dir.mkdir(parents=True, exist_ok=True)
    destination = target_dir / f"background_music{extension}"
    destination.write_bytes(binary)
    material_inputs = _load_material_inputs(story_task_id)
    material_inputs["bgm_audio"] = str(destination.resolve())
    _material_inputs_path(story_task_id).write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return _material_inputs_public_summary(story_task_id)


def _remove_material_bgm(story_task_id: str) -> dict[str, object]:
    material_inputs = _load_material_inputs(story_task_id)
    old_path = material_inputs.get("bgm_audio")
    if isinstance(old_path, str):
        try:
            Path(old_path).unlink(missing_ok=True)
        except OSError:
            pass
    material_inputs["bgm_audio"] = None
    _material_inputs_path(story_task_id).write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return _material_inputs_public_summary(story_task_id)


def _material_bgm_path(story_task_id: str) -> Path | None:
    value = _load_material_inputs(story_task_id).get("bgm_audio")
    path = Path(value) if isinstance(value, str) else None
    return path if path and path.is_file() else None


def _save_material_image_paths(story_task_id: str, kind: str, paths: list[str]) -> dict[str, object]:
    """Copy picker-selected images into the local task and update its material manifest."""
    fields = {
        "style": ("style_reference_images", "style_reference"),
        "digital": ("digital_human_images", "digital_human"),
    }
    if kind not in fields:
        raise ValueError("图片类型必须是 style 或 digital")
    if len(paths) > MAX_REFERENCE_IMAGES:
        raise ValueError(f"一次最多选择 {MAX_REFERENCE_IMAGES} 张图片")
    field, prefix = fields[kind]
    target_dir = DIRECTOR_REVIEW_DIR / story_task_id / "material_inputs"
    target_dir.mkdir(parents=True, exist_ok=True)
    saved_paths: list[str] = []
    for index, raw_path in enumerate(paths, start=1):
        source = Path(raw_path).resolve()
        extension = source.suffix.lower()
        if extension not in {".jpg", ".jpeg", ".png", ".webp"} or not source.is_file():
            raise ValueError("仅支持存在的 JPG、PNG、WebP 图片")
        size = source.stat().st_size
        if size <= 0 or size > 12 * 1024 * 1024:
            raise ValueError(f"{source.name} 大小必须在 1 字节到 12MB 之间")
        normalized_extension = ".jpg" if extension == ".jpeg" else extension
        destination = target_dir / f"{prefix}_{index:02d}{normalized_extension}"
        if source != destination.resolve():
            shutil.copy2(source, destination)
        saved_paths.append(str(destination.resolve()))

    material_inputs = _load_material_inputs(story_task_id)
    material_inputs[field] = saved_paths
    _material_inputs_path(story_task_id).write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return {
        "style_reference_count": len(material_inputs["style_reference_images"]),
        "digital_human_count": len(material_inputs["digital_human_images"]),
        "selected": [
            {
                "name": Path(path).name,
                "preview_url": f"/api/material-input-preview/{story_task_id}/{kind}/{index}",
            }
            for index, path in enumerate(saved_paths)
        ],
    }


def _remove_material_image(story_task_id: str, kind: str, index: int) -> dict[str, object]:
    fields = {"style": "style_reference_images", "digital": "digital_human_images"}
    field = fields.get(kind)
    if field is None:
        raise ValueError("图片类型必须是 style 或 digital")
    material_inputs = _load_material_inputs(story_task_id)
    values = material_inputs[field]
    if index < 0 or index >= len(values):
        raise ValueError("待移除图片序号无效")
    values.pop(index)
    _material_inputs_path(story_task_id).write_text(
        json.dumps(material_inputs, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return {
        "style_reference_count": len(material_inputs["style_reference_images"]),
        "digital_human_count": len(material_inputs["digital_human_images"]),
        "selected": [
            {
                "name": Path(path).name,
                "preview_url": f"/api/material-input-preview/{story_task_id}/{kind}/{item_index}",
            }
            for item_index, path in enumerate(values)
        ],
    }


def _material_input_preview_path(story_task_id: str, kind: str, index: int) -> Path | None:
    fields = {"style": "style_reference_images", "digital": "digital_human_images"}
    field = fields.get(kind)
    if field is None:
        return None
    values = _load_material_inputs(story_task_id)[field]
    if index < 0 or index >= len(values):
        return None
    path = Path(values[index])
    return path if path.is_file() else None


def _material_inputs_public_summary(story_task_id: str) -> dict[str, object]:
    values = _load_material_inputs(story_task_id)

    def records(kind: str, field: str) -> list[dict[str, str]]:
        return [
            {
                "name": Path(path).name,
                "preview_url": f"/api/material-input-preview/{story_task_id}/{kind}/{index}",
            }
            for index, path in enumerate(values[field])
        ]

    return {
        "style_reference_count": len(values["style_reference_images"]),
        "digital_human_count": len(values["digital_human_images"]),
        "style": records("style", "style_reference_images"),
        "digital": records("digital", "digital_human_images"),
        "bgm": (
            {
                "name": Path(str(values["bgm_audio"])).name,
                "preview_url": f"/api/material-bgm-preview/{story_task_id}",
            }
            if values.get("bgm_audio")
            else None
        ),
        "visual_guidance_prompt": str(values.get("visual_guidance_prompt") or ""),
        "visual_guidance_source": str(values.get("visual_guidance_source") or ""),
    }


def _refresh_local_image_library(*, limit: int = 36) -> list[dict[str, str]]:
    """Index recent images from common user folders without exposing absolute paths."""
    roots = [Path.home() / name for name in ("Pictures", "Desktop", "Downloads")]
    candidates: list[tuple[float, Path]] = []
    for root in roots:
        if not root.is_dir():
            continue
        scanned = 0
        for directory, subdirectories, filenames in os.walk(root):
            subdirectories[:] = [name for name in subdirectories if not name.startswith(".")]
            for filename in filenames:
                scanned += 1
                if scanned > 5000:
                    break
                path = Path(directory) / filename
                if path.suffix.lower() not in {".jpg", ".jpeg", ".png", ".webp"}:
                    continue
                try:
                    size = path.stat().st_size
                    modified = path.stat().st_mtime
                except OSError:
                    continue
                if 0 < size <= 12 * 1024 * 1024:
                    candidates.append((modified, path.resolve()))
            if scanned > 5000:
                break
    candidates.sort(key=lambda item: item[0], reverse=True)
    selected = candidates[:limit]
    records: list[dict[str, str]] = []
    library: dict[str, str] = {}
    for _modified, path in selected:
        token = hashlib.sha256(str(path).encode("utf-8")).hexdigest()[:24]
        library[token] = str(path)
        records.append(
            {
                "token": token,
                "name": path.name,
                "folder": path.parent.name,
                "preview_url": f"/api/local-image-library-preview/{token}",
            }
        )
    with LOCAL_IMAGE_LIBRARY_LOCK:
        LOCAL_IMAGE_LIBRARY.clear()
        LOCAL_IMAGE_LIBRARY.update(library)
    return records


def _local_image_library_path(token: str) -> Path | None:
    with LOCAL_IMAGE_LIBRARY_LOCK:
        raw_path = LOCAL_IMAGE_LIBRARY.get(token)
    if not raw_path:
        return None
    path = Path(raw_path)
    return path if path.is_file() else None


def _local_image_thumbnail(token: str) -> bytes | None:
    with LOCAL_IMAGE_THUMBNAILS_LOCK:
        cached = LOCAL_IMAGE_THUMBNAILS.get(token)
    if cached is not None:
        return cached
    path = _local_image_library_path(token)
    if path is None:
        return None
    with LOCAL_IMAGE_THUMBNAIL_SLOTS:
        with LOCAL_IMAGE_THUMBNAILS_LOCK:
            cached = LOCAL_IMAGE_THUMBNAILS.get(token)
        if cached is not None:
            return cached
        if Image is not None:
            try:
                with Image.open(path) as source:
                    source.seek(0)
                    thumbnail_image = source.convert("RGB")
                    resampling = getattr(Image, "Resampling", Image)
                    thumbnail_image.thumbnail((320, 240), resampling.LANCZOS)
                    output = io.BytesIO()
                    thumbnail_image.save(output, format="JPEG", quality=82, optimize=True)
                    thumbnail = output.getvalue()
                with LOCAL_IMAGE_THUMBNAILS_LOCK:
                    LOCAL_IMAGE_THUMBNAILS[token] = thumbnail
                return thumbnail
            except Exception:
                # Some uncommon/corrupt files are still handled by ffmpeg below.
                pass
        completed = subprocess.run(
            [
                "ffmpeg",
                "-v",
                "error",
                "-i",
                str(path),
                "-vf",
                "scale=320:240:force_original_aspect_ratio=decrease",
                "-frames:v",
                "1",
                "-f",
                "image2pipe",
                "-vcodec",
                "mjpeg",
                "pipe:1",
            ],
            capture_output=True,
            timeout=12,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        if completed.returncode != 0 or not completed.stdout:
            return None
        thumbnail = bytes(completed.stdout)
        with LOCAL_IMAGE_THUMBNAILS_LOCK:
            LOCAL_IMAGE_THUMBNAILS[token] = thumbnail
        return thumbnail


def _select_local_material_images(
    story_task_id: str, kind: str, payload: Mapping[str, object]
) -> dict[str, object]:
    tokens = payload.get("tokens")
    if not isinstance(tokens, list) or not tokens or not all(isinstance(item, str) for item in tokens):
        raise ValueError("请至少选择一张本机图片")
    if len(tokens) > MAX_REFERENCE_IMAGES:
        raise ValueError(f"一次最多选择 {MAX_REFERENCE_IMAGES} 张图片")
    paths: list[str] = []
    for token in tokens:
        path = _local_image_library_path(token)
        if path is None:
            raise ValueError("选中的本机图片已失效，请刷新图片库")
        paths.append(str(path))
    result = _save_material_image_paths(story_task_id, kind, paths)
    return _material_inputs_public_summary(story_task_id) | {"selected": result["selected"]}


def _persist_task(task: dict, *, required: bool = False) -> bool:
    """Persist a public task snapshot; required writes must not fall back to memory."""
    task = _normalize_task_snapshot(task)
    temporary: Path | None = None
    try:
        with TASK_PERSIST_LOCK:
            STYLE_TASK_DIR.mkdir(parents=True, exist_ok=True)
            destination = _task_file(str(task["task_id"]))
            # 主进程和独立 worker 共享任务目录，但各自持有不同的进程锁；
            # 固定 .tmp 文件会在 Windows 上互相覆盖，导致 WinError 32。
            temporary = destination.with_name(
                f".{destination.name}.{os.getpid()}.{threading.get_ident()}.tmp"
            )
            temporary.write_text(json.dumps(task, ensure_ascii=False, indent=2), encoding="utf-8")
            for attempt in range(4):
                try:
                    temporary.replace(destination)
                    temporary = None
                    break
                except PermissionError:
                    if attempt == 3:
                        raise
                    time.sleep(0.05 * (2**attempt))
    except OSError as exc:
        TASK_LOGGER.warning(
            "task persistence unavailable for %s (%s: %s)",
            task.get("task_id"), type(exc).__name__, str(exc),
        )
        if required:
            raise TaskPersistenceError(
                f"任务 {task.get('task_id', '')} 无法持久化：{type(exc).__name__}"
            ) from exc
        return False
    finally:
        if temporary is not None:
            try:
                temporary.unlink()
            except OSError:
                pass
    _invalidate_style_task_listing_cache()
    return True


def _persist_task_required(task: dict) -> bool:
    """Persist a task before execution, retaining compatibility with test/worker shims."""

    try:
        return bool(_persist_task(task, required=True))
    except TypeError as exc:
        # Older injected worker shims accepted only ``task``.  Keep that
        # compatibility explicit, while never hiding a real persistence error.
        if "unexpected keyword argument 'required'" not in str(exc):
            raise
        return bool(_persist_task(task))


def _load_persisted_task(task_id: str) -> dict | None:
    for path in _task_paths(task_id):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, json.JSONDecodeError):
            continue
        if isinstance(data, dict):
            return _normalize_task_snapshot(data)
    return None


def _runtime_archives_for_story(story_task_id: str) -> list[tuple[Path, dict]]:
    """Locate completed runtime archives for one story without exposing them globally."""

    target = str(story_task_id or "").strip()
    if not target:
        return []
    found: list[tuple[Path, dict]] = []
    try:
        archive_dirs = list(RUNTIME_ARCHIVE_DIR.iterdir())
    except OSError:
        return []
    for archive_dir in archive_dirs:
        if not archive_dir.is_dir():
            continue
        manifest_path = archive_dir / "archive_manifest.json"
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(manifest, dict) or str(manifest.get("source_story_task_id") or "") != target:
            continue
        found.append((archive_dir, manifest))
    return sorted(found, key=lambda item: int(item[1].get("archived_at") or 0), reverse=True)


def _remap_archived_runtime_paths(value: object, archive_root: Path, story_task_id: str) -> object:
    """Translate archived snapshots' old absolute paths to their archived files."""

    mappings = (
        (DIRECTOR_REVIEW_DIR / story_task_id, archive_root / "director_story_reviews" / story_task_id),
        (STYLE_TASK_DIR, archive_root / "executor_tasks"),
        (STYLE_PACKAGE_STORE.rewrites_dir, archive_root / "style_packages" / "rewrites"),
        (STYLE_PACKAGE_STORE.collections_dir, archive_root / "style_packages" / "collections"),
    )

    # Snapshots contain long model prompts and many nested records.  Rewriting
    # the serialized JSON is materially faster than recursively visiting every
    # prose string, while still restricting replacements to known local roots.
    serialized = json.dumps(value, ensure_ascii=False)
    for old_root, new_root in mappings:
        old_text = json.dumps(str(old_root.resolve()), ensure_ascii=False)[1:-1]
        new_text = json.dumps(str(new_root.resolve()), ensure_ascii=False)[1:-1]
        serialized = serialized.replace(old_text, new_text)
    return json.loads(serialized)


def _archived_story_task_snapshots(story_task_id: str) -> list[dict]:
    """Load task snapshots from a story archive for direct handoff reuse only."""

    result: list[dict] = []
    for archive_root, manifest in _runtime_archives_for_story(story_task_id):
        task_dir = archive_root / "executor_tasks"
        try:
            task_paths = list(task_dir.glob("*.json"))
        except OSError:
            continue
        for task_path in task_paths:
            try:
                task = json.loads(task_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(task, dict) or not _task_matches_story(task, story_task_id):
                continue
            task = _remap_archived_runtime_paths(task, archive_root, story_task_id)
            task["archived_at"] = int(manifest.get("archived_at") or 0)
            task["archive_id"] = str(manifest.get("archive_id") or archive_root.name)
            task["runtime_data_archived"] = True
            result.append(task)
    return sorted(result, key=lambda item: int(item.get("updated_at") or 0), reverse=True)


def _handoff_story_task_snapshot(story_task_id: str) -> dict | None:
    """Resolve an active story or its archived snapshot for the editing handoff only."""

    active = _task_snapshot(story_task_id)
    if active is not None:
        return active
    candidates = [
        task for task in _archived_story_task_snapshots(story_task_id)
        if task.get("task_type") == "director_story_review"
        and str(task.get("task_id") or "") == str(story_task_id)
    ]
    return candidates[0] if candidates else None


def _merge_asset_result_snapshots(current: object, incoming: object) -> object:
    """合并并行分支的结果快照，防止旧分支覆盖已完成的付费资产。"""

    if not isinstance(current, Mapping) or not isinstance(incoming, Mapping):
        return incoming
    current_status = str(current.get("status") or "")
    incoming_status = str(incoming.get("status") or "")
    if current_status == "succeeded" and incoming_status in {"failed", "running", "queued", ""}:
        return dict(current)
    merged = dict(current)
    for key, value in incoming.items():
        if key == "shot_results" and isinstance(value, list) and isinstance(current.get(key), list):
            by_shot = {
                str(item.get("shot_id") or ""): dict(item)
                for item in current[key]
                if isinstance(item, Mapping) and str(item.get("shot_id") or "")
            }
            for item in value:
                if not isinstance(item, Mapping):
                    continue
                shot_id = str(item.get("shot_id") or "")
                if not shot_id:
                    continue
                old = by_shot.get(shot_id)
                if old and old.get("status") == "succeeded" and item.get("status") != "succeeded":
                    continue
                by_shot[shot_id] = dict(item)
            merged[key] = list(by_shot.values())
            continue
        if isinstance(value, list) and isinstance(current.get(key), list) and len(current[key]) > len(value):
            continue
        if value not in (None, "", [], {}):
            merged[key] = value
    if isinstance(merged.get("shot_results"), list):
        records = [item for item in merged["shot_results"] if isinstance(item, Mapping)]
        for field, status in (("succeeded_count", "succeeded"), ("failed_count", "failed"), ("submitted_count", "submitted")):
            merged[field] = sum(item.get("status") == status for item in records)
    return merged


def _merge_task_result_snapshots(current: object, incoming: object) -> dict:
    """在任务锁内合并类别与素材结果，而不是用并行分支的旧快照整体覆盖。"""

    if not isinstance(current, Mapping):
        return dict(incoming) if isinstance(incoming, Mapping) else {}
    if not isinstance(incoming, Mapping):
        return dict(current)
    merged = dict(current)
    asset_keys = {"first_frame_assets", "aigc_video_assets", "digital_human_assets", "bgm_assets"}
    for key, value in incoming.items():
        if key == "categories" and isinstance(value, Mapping):
            categories = dict(current.get("categories") or {}) if isinstance(current.get("categories"), Mapping) else {}
            for category_key, category_value in value.items():
                if not isinstance(category_value, Mapping):
                    categories[category_key] = category_value
                    continue
                previous = categories.get(category_key)
                if isinstance(previous, Mapping):
                    previous_state = str(previous.get("state") or "")
                    incoming_state = str(category_value.get("state") or "")
                    previous_completed = int(previous.get("completed") or 0)
                    incoming_completed = int(category_value.get("completed") or 0)
                    if previous_completed > incoming_completed or (
                        previous_state in {"succeeded", "failed", "blocked", "interrupted"}
                        and incoming_state in {"queued", "running"}
                        and previous_completed >= incoming_completed
                    ):
                        continue
                categories[category_key] = dict(category_value)
            merged["categories"] = categories
        elif key in asset_keys:
            merged[key] = _merge_asset_result_snapshots(current.get(key), value)
        elif value not in (None, "", [], {}):
            merged[key] = value
    return merged


def _set_task(task_id: str, **changes: object) -> None:
    preserve_terminal = bool(changes.pop("_preserve_terminal", False))
    allow_interrupted_resume = bool(changes.pop("_allow_interrupted_resume", False))
    remove_result_keys = [
        str(key).strip()
        for key in changes.pop("_remove_result_keys", []) or []
        if str(key).strip()
    ]
    with STYLE_TASKS_LOCK:
        if task_id not in STYLE_TASKS:
            # 控制台重启后，历史任务只存在于磁盘快照。补跑/恢复必须先装入内存，
            # 否则状态更新会被静默丢弃，页面永远停留在旧失败状态。
            persisted = _load_persisted_task(task_id)
            if persisted is None:
                return
            STYLE_TASKS[task_id] = persisted
        current_state = str(STYLE_TASKS[task_id].get("state") or "")
        incoming_state = str(changes.get("state") or "")
        if preserve_terminal and current_state in {"failed", "interrupted"} and incoming_state in {"queued", "running"}:
            # 并行分支只能补写 result，不能把主流程已经确认的终态重开成 running。
            changes = {key: value for key, value in changes.items() if key not in {"state", "stage", "progress", "message"}}
        if (
            current_state == "interrupted"
            and incoming_state in {"queued", "running", "succeeded", "failed"}
            and not allow_interrupted_resume
        ):
            # 停止按钮一旦落盘，正在返回的外部请求不能把任务重新显示为运行中、成功或失败。
            # 允许仅补写 result，避免丢失已经返回的中间数据，但保持人工停止终态。
            changes = {key: value for key, value in changes.items() if key not in {"state", "stage", "progress", "message"}}
        if "result" in changes:
            merged_result = _merge_task_result_snapshots(
                STYLE_TASKS[task_id].get("result"), changes.get("result")
            )
            for key in remove_result_keys:
                merged_result.pop(key, None)
            changes["result"] = merged_result
        if incoming_state in {"failed", "interrupted"}:
            changes.setdefault("error_code", str(changes.get("stage") or "task_failed"))
            changes.setdefault("error_detail", str(changes.get("message") or "任务未完成"))
            if incoming_state == "interrupted":
                changes.setdefault("lifecycle_status", "recoverable")
        elif incoming_state in {"queued", "running"}:
            changes.setdefault("lifecycle_status", "active")
        elif incoming_state == "succeeded":
            changes.setdefault("lifecycle_status", "archived")
        STYLE_TASKS[task_id].update(changes)
        STYLE_TASKS[task_id] = _normalize_task_snapshot(STYLE_TASKS[task_id])
        STYLE_TASKS[task_id]["updated_at"] = int(time.time())
        task = dict(STYLE_TASKS[task_id])
    _persist_task_required(task) if task.get("task_type") else _persist_task(task)


def _task_snapshot(task_id: str) -> dict | None:
    with STYLE_TASKS_LOCK:
        task = STYLE_TASKS.get(task_id)
        if task is not None:
            if _external_style_worker(task):
                persisted = _load_persisted_task(task_id)
                if persisted is not None:
                    STYLE_TASKS[task_id] = persisted
                    task = persisted
            return _attach_style_worker_heartbeat(_asset_resume_metadata(_reconcile_local_video_retry(_normalize_task_snapshot(dict(task)))))
    persisted = _load_persisted_task(task_id)
    return _attach_style_worker_heartbeat(_asset_resume_metadata(_reconcile_local_video_retry(_normalize_task_snapshot(persisted)))) if persisted else None


def _archive_runtime_data(*, source_story_task_id: str, completed_task_id: str) -> dict[str, object]:
    """Archive completed production state and leave only style profiles visible.

    This is deliberately scoped to runtime artifacts created by the console:
    executor snapshots, story/material directories, and rewrite/sample records.
    Approved style profiles remain in ``style_packages/profiles``.  The stable
    TTS cache also remains in place because it is a paid-asset reuse cache rather
    than UI history.  Active tasks belonging to another story are not moved.
    """
    safe_story = re.sub(r"[^0-9A-Za-z_-]+", "_", str(source_story_task_id or "unknown"))[:32] or "unknown"
    archive_id = f"{time.strftime('%Y%m%d_%H%M%S')}_{safe_story}_{uuid.uuid4().hex[:8]}"
    archive_root = RUNTIME_ARCHIVE_DIR / archive_id
    archive_root.mkdir(parents=True, exist_ok=True)
    moved: list[str] = []
    errors: list[str] = []

    with STYLE_TASKS_LOCK:
        live_tasks = {task_id: dict(task) for task_id, task in STYLE_TASKS.items()}
    active_story_ids = {
        str(task.get("source_story_task_id") or "").strip()
        for task in live_tasks.values()
        if str(task.get("state") or "") in {"queued", "running"}
        and str(task.get("source_story_task_id") or "").strip()
    }

    # Also protect active snapshots that were persisted before an executor restart.
    try:
        for task in _persisted_task_snapshots():
            if task and str(task.get("state") or "") in {"queued", "running"}:
                story_id = str(task.get("source_story_task_id") or "").strip()
                if story_id:
                    active_story_ids.add(story_id)
    except OSError as exc:
        errors.append(f"读取活动任务失败：{type(exc).__name__}")

    def move_child(child: Path, target_dir: Path) -> None:
        target_dir.mkdir(parents=True, exist_ok=True)
        destination = target_dir / child.name
        if destination.exists():
            destination = target_dir / f"{child.stem}_{uuid.uuid4().hex[:8]}{child.suffix}"
        try:
            shutil.move(str(child), str(destination))
            moved.append(str(destination.relative_to(archive_root)))
        except OSError as exc:
            errors.append(f"{child.name}：{type(exc).__name__}")

    # Move terminal executor snapshots.  The completed task itself is included;
    # it remains available only in memory until the browser receives success.
    try:
        if STYLE_TASK_DIR.is_dir():
            for child in list(STYLE_TASK_DIR.iterdir()):
                if child.is_file() and child.suffix.lower() == ".json":
                    task = _load_persisted_task(child.stem)
                    if task:
                        state = str(task.get("state") or "")
                        if state in {"queued", "running"}:
                            continue
                        # 失败/中断的风格任务可能保留已付费样本和断点，必须留在主任务目录，
                        # 让用户可以查看原因并在确认后继续；不能被剪辑归档动作隐藏。
                        if _is_style_collection_task(task) and state in {"failed", "interrupted"}:
                            continue
                move_child(child, archive_root / "executor_tasks")
    except OSError as exc:
        errors.append(f"归档执行器快照失败：{type(exc).__name__}")

    # Move story reviews, material inputs, paid media and editing handoff files.
    try:
        if DIRECTOR_REVIEW_DIR.is_dir():
            for child in list(DIRECTOR_REVIEW_DIR.iterdir()):
                if child.name in active_story_ids:
                    continue
                move_child(child, archive_root / "director_story_reviews")
    except OSError as exc:
        errors.append(f"归档故事目录失败：{type(exc).__name__}")

    # Rewrites and raw sample collections are review history, not reusable style
    # profiles.  Keep profiles in place so the next project can still select them.
    for source_dir, relative_target in (
        (STYLE_PACKAGE_STORE.rewrites_dir, Path("style_packages") / "rewrites"),
        (STYLE_PACKAGE_STORE.collections_dir, Path("style_packages") / "collections"),
    ):
        try:
            if source_dir.is_dir():
                for child in list(source_dir.iterdir()):
                    move_child(child, archive_root / relative_target)
        except OSError as exc:
            errors.append(f"归档 {source_dir.name} 失败：{type(exc).__name__}")

    # Clear in-memory image-library state so a fresh page cannot show stale uploads.
    with LOCAL_IMAGE_LIBRARY_LOCK:
        LOCAL_IMAGE_LIBRARY.clear()
    with LOCAL_IMAGE_THUMBNAILS_LOCK:
        LOCAL_IMAGE_THUMBNAILS.clear()

    archived_at = int(time.time())
    with STYLE_TASKS_LOCK:
        for task_id, task in list(STYLE_TASKS.items()):
            if task_id == completed_task_id:
                continue
            state = str(task.get("state") or "")
            keep_recoverable_style_task = (
                _is_style_collection_task(task) and state in {"failed", "interrupted"}
            )
            if state not in {"queued", "running"} and not keep_recoverable_style_task:
                STYLE_TASKS.pop(task_id, None)
        completed = STYLE_TASKS.get(completed_task_id)
        if completed is not None:
            completed["archived_at"] = archived_at
            completed["archive_id"] = archive_id
            completed["runtime_data_archived"] = True

    report = {
        "status": "partial" if errors else "completed",
        "archive_id": archive_id,
        "archived_at": archived_at,
        "moved_count": len(moved),
        "moved": moved,
        "preserved": [
            "outputs/style_packages/profiles",
            "outputs/director_tts_cache（付费 TTS 复用缓存）",
        ],
        "errors": errors,
    }
    try:
        (archive_root / "archive_manifest.json").write_text(
            json.dumps(
                {
                    "schema_version": "runtime_archive_v1",
                    "source_story_task_id": source_story_task_id,
                    **report,
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
    except OSError as exc:
        report["status"] = "partial"
        report["errors"] = [*errors, f"写入归档清单失败：{type(exc).__name__}"]
    return report


def _asset_preview_path(task_id: str, shot_id: str) -> Path | None:
    """返回指定首帧的本机预览文件；不把临时公网 URL 交给浏览器。"""
    task = _preview_task_snapshot(task_id)
    result = task.get("result") if isinstance(task, Mapping) else None
    if not isinstance(result, Mapping):
        return None
    fallback = result.get("digital_human_fallbacks")
    if isinstance(fallback, Mapping):
        record = fallback.get(shot_id)
        if isinstance(record, Mapping):
            candidate = _safe_director_review_file(record.get("image_path"))
            if candidate is not None:
                return candidate
    trace = result.get("first_frame_prompt_trace")
    assets = result.get("first_frame_assets")
    paths = assets.get("image_paths") if isinstance(assets, Mapping) else None
    if not isinstance(trace, list):
        return None
    index = next((idx for idx, item in enumerate(trace) if isinstance(item, Mapping) and str(item.get("shot_id")) == shot_id), None)
    if index is None:
        return None
    try:
        if isinstance(paths, list) and index < len(paths):
            candidate = _safe_director_review_file(paths[index])
        else:
            # 若首帧都已下载、但后续视频阶段崩溃，仍可恢复展示这些真实图片。
            output_dir = Path(str(result.get("output_dir") or "")).resolve()
            candidate = output_dir / "images" / f"first_frame_{index + 1:02d}.jpg"
            candidate = _safe_director_review_file(candidate)
    except (OSError, ValueError):
        return None
    return candidate if candidate is not None and candidate.is_file() else None


def _safe_director_review_file(value: object) -> Path | None:
    """只接受活动素材目录或已登记归档目录内、已经存在的本地文件。"""

    try:
        candidate = Path(str(value or "")).expanduser().resolve()
        allowed_roots = [DIRECTOR_REVIEW_DIR.resolve(), RUNTIME_ARCHIVE_DIR.resolve()]
        if not any(candidate == root or root in candidate.parents for root in allowed_roots):
            return None
    except (OSError, ValueError):
        return None
    return candidate if candidate is not None and candidate.is_file() else None


def _preview_task_snapshot(task_id: str) -> dict | None:
    """读取当前或归档的素材任务，供只读媒体预览接口使用。"""

    requested = str(task_id or "").strip()
    if not requested or Path(requested).name != requested:
        return None
    active = _task_snapshot(requested)
    if active is not None:
        return active
    try:
        archive_dirs = list(RUNTIME_ARCHIVE_DIR.iterdir())
    except OSError:
        return None
    for archive_root in archive_dirs:
        if not archive_root.is_dir():
            continue
        task_path = archive_root / "executor_tasks" / f"{requested}.json"
        if not task_path.is_file():
            continue
        try:
            task = json.loads(task_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue
        if not isinstance(task, dict) or str(task.get("task_id") or "") != requested:
            continue
        story_task_id = str(task.get("source_story_task_id") or "").strip()
        if story_task_id:
            task = _remap_archived_runtime_paths(task, archive_root, story_task_id)
        task["archived_at"] = int(task.get("archived_at") or 0)
        task["archive_id"] = archive_root.name
        task["runtime_data_archived"] = True
        return task
    return None


def _first_frame_paths_by_shot(result: Mapping[str, object]) -> dict[str, Path]:
    """从首帧 trace 与本地路径建立 shot_id -> 裁切首帧索引。"""

    assets = result.get("first_frame_assets")
    trace = result.get("first_frame_prompt_trace")
    paths = assets.get("image_paths") if isinstance(assets, Mapping) else None
    if not isinstance(trace, list) or not isinstance(paths, list):
        return {}
    mapped: dict[str, Path] = {}
    for index, item in enumerate(trace):
        if not isinstance(item, Mapping) or index >= len(paths):
            continue
        shot_id = str(item.get("shot_id") or "").strip()
        path = _safe_director_review_file(paths[index])
        if shot_id and path is not None:
            mapped[shot_id] = path
    return mapped


def _first_frame_grid_ids_by_shot(result: Mapping[str, object]) -> dict[str, str]:
    """建立裁切首帧所属宫格，供替代记录追溯来源。"""

    assets = result.get("first_frame_assets")
    batches = assets.get("grid_batches") if isinstance(assets, Mapping) else None
    mapped: dict[str, str] = {}
    for batch in batches or []:
        if not isinstance(batch, Mapping):
            continue
        grid_id = str(batch.get("grid_id") or "")
        for cell in batch.get("cells") or []:
            if isinstance(cell, Mapping) and cell.get("shot_id"):
                mapped[str(cell["shot_id"])] = grid_id
    return mapped


def _is_digital_human_auth_error(error: BaseException) -> bool:
    """只把明确的登录、鉴权、权限失败识别为可降级错误。"""

    text = str(error or "").lower()
    markers = (
        "鉴权", "认证", "凭据", "登录", "未登录", "api key", "apikey", "token",
        "unauthorized", "unauthorised", "forbidden", "access denied", "permission",
        "权限", "http 401", "http 403", "状态码 401", "状态码 403",
    )
    return any(marker in text for marker in markers)


def _queue_digital_human_grid_fallback(
    task_id: str, shot_ids: list[str], reason: str
) -> None:
    """把待替代数字人坑位写入任务快照，等首帧分支完成后再选图。"""

    snapshot = _task_snapshot(task_id) or {}
    result = dict(snapshot.get("result") or {})
    pending = dict(result.get("digital_human_fallback_pending") or {})
    current_ids = [str(item or "").strip() for item in pending.get("shot_ids") or [] if str(item or "").strip()]
    pending["shot_ids"] = list(dict.fromkeys(current_ids + [str(item or "").strip() for item in shot_ids if str(item or "").strip()]))
    pending["reason"] = str(reason or "数字人后台登录/鉴权不可用")[:320]
    pending["policy"] = "digital_human_auth_unavailable_to_stable_random_grid_image"
    result["digital_human_fallback_pending"] = pending
    _set_task(task_id, result=result)


def _apply_pending_digital_human_grid_fallback(task_id: str) -> dict[str, object]:
    """用已有宫格裁切首帧替换鉴权失败的数字人坑位，不产生新付费任务。"""

    snapshot = _task_snapshot(task_id) or {}
    result = dict(snapshot.get("result") or {})
    pending = result.get("digital_human_fallback_pending")
    if not isinstance(pending, Mapping):
        return {"applied": 0, "missing": []}
    target_ids = [str(item or "").strip() for item in pending.get("shot_ids") or [] if str(item or "").strip()]
    if not target_ids:
        result.pop("digital_human_fallback_pending", None)
        _set_task(task_id, result=result, _remove_result_keys=["digital_human_fallback_pending"])
        return {"applied": 0, "missing": []}

    path_by_shot = _first_frame_paths_by_shot(result)
    grid_by_shot = _first_frame_grid_ids_by_shot(result)
    candidates = sorted(path_by_shot.items(), key=lambda item: item[0])
    if not candidates:
        return {"applied": 0, "missing": target_ids}

    try:
        script_task = _latest_shot_script_task(str(snapshot.get("source_story_task_id") or ""))
        script_shots = [
            dict(item) for item in (script_task.get("result") or {}).get("shot_video_script") or []
            if isinstance(item, Mapping)
        ]
    except (ValueError, KeyError):
        script_shots = []
    script_by_id = {str(item.get("shot_id") or ""): item for item in script_shots}
    all_digital_ids = [
        str(item.get("shot_id") or "") for item in script_shots
        if _shot_requires_digital_human(item) and item.get("shot_id")
    ]
    digital_assets = result.get("digital_human_assets")
    digital_assets = digital_assets if isinstance(digital_assets, Mapping) else {}
    old_records = {
        str(item.get("shot_id") or ""): dict(item)
        for item in digital_assets.get("shot_results") or []
        if isinstance(item, Mapping) and item.get("shot_id")
    }
    overrides = dict(result.get("media_type_overrides") or {})
    fallbacks = dict(result.get("digital_human_fallbacks") or {})
    missing: list[str] = []
    applied = 0
    task_seed = str(task_id)
    fallback_video_dir = Path(str(result.get("output_dir") or "")).expanduser() / "digital_humans" / "fallback"
    fallback_video_dir.mkdir(parents=True, exist_ok=True)
    for shot_id in target_ids:
        old = old_records.get(shot_id)
        old_video = _safe_director_review_file(old.get("video_path")) if old else None
        if old and old.get("status") == "succeeded" and old_video is not None:
            continue
        if shot_id not in script_by_id:
            missing.append(shot_id)
            continue
        digest = hashlib.sha256(f"{task_seed}:{shot_id}".encode("utf-8")).digest()
        source_shot_id, image_path = candidates[int.from_bytes(digest[:8], "big") % len(candidates)]
        shot = script_by_id[shot_id]
        try:
            duration_s = max(0.1, (int(shot.get("end_us") or 0) - int(shot.get("start_us") or 0)) / 1_000_000)
        except (TypeError, ValueError):
            duration_s = 1.0
        fallback_video = fallback_video_dir / f"{shot_id}.mp4"
        valid_image = image_path.is_file() and image_path.stat().st_size >= 1024
        if valid_image and (not fallback_video.is_file() or fallback_video.stat().st_size <= 0):
            command = [
                "ffmpeg", "-y", "-loop", "1", "-i", str(image_path),
                "-t", f"{duration_s:.3f}", "-r", "30", "-an",
                "-pix_fmt", "yuv420p", str(fallback_video),
            ]
            completed = subprocess.run(command, capture_output=True, text=True, encoding="utf-8", errors="replace", check=False)
            if completed.returncode != 0 or not fallback_video.is_file() or fallback_video.stat().st_size <= 0:
                missing.append(shot_id)
                continue
        if not valid_image:
            # 测试/异常快照可能只有占位字节，此时保留历史图片回退契约。
            fallback = {
                "shot_id": shot_id, "status": "fallback_image", "media_type": "static_image",
                "image_path": str(image_path.resolve()), "reused_paid_asset": True,
                "reused_from_grid_shot_id": source_shot_id, "source_grid_id": grid_by_shot.get(source_shot_id, ""),
                "fallback_reason": str(pending.get("reason") or "数字人后台登录/鉴权不可用")[:320],
                "selection_policy": "stable_random_existing_grid_cell",
            }
            old_records[shot_id] = fallback
            fallbacks[shot_id] = fallback
            overrides[shot_id] = "static_image"
            applied += 1
            continue
        fallback = {
            "shot_id": shot_id,
            "status": "succeeded",
            "media_type": "digital_human_video",
            "image_path": str(image_path.resolve()),
            "video_path": str(fallback_video.resolve()),
            "fallback_video": True,
            "reused_paid_asset": True,
            "reused_from_grid_shot_id": source_shot_id,
            "source_grid_id": grid_by_shot.get(source_shot_id, ""),
            "fallback_reason": str(pending.get("reason") or "数字人后台登录/鉴权不可用")[:320],
            "selection_policy": "stable_random_existing_grid_cell",
        }
        old_records[shot_id] = fallback
        fallbacks[shot_id] = fallback
        applied += 1

    ordered = [old_records[shot_id] for shot_id in all_digital_ids if shot_id in old_records]
    result["digital_human_assets"] = {
        **dict(digital_assets),
        "shot_results": ordered,
        "task_ids": [str(item.get("task_id") or "") for item in ordered if item.get("task_id")],
        "video_paths": [str(item.get("video_path") or "") for item in ordered if item.get("status") == "succeeded"],
        "succeeded_count": sum(item.get("status") == "succeeded" for item in ordered),
        "fallback_count": sum(item.get("status") == "fallback_image" for item in ordered),
        "failed_count": sum(item.get("status") == "failed" for item in ordered),
    }
    result["digital_human_fallbacks"] = fallbacks
    result["media_type_overrides"] = overrides
    if missing:
        result["digital_human_fallback_pending"] = {**dict(pending), "shot_ids": missing}
    else:
        result.pop("digital_human_fallback_pending", None)
    categories = dict(result.get("categories") or {})
    category = dict(categories.get("digital_humans") or {})
    total = len(all_digital_ids) or len(target_ids)
    category.update(
        state="succeeded" if not missing else "failed",
        submitted=sum(item.get("status") in {"submitted", "succeeded", "failed"} for item in ordered),
        completed=sum(item.get("status") in {"succeeded", "failed", "fallback_image"} for item in ordered),
        total=total,
        message=(
            f"数字人后台登录/鉴权不可用，已跳过数字人调用；已用 {applied} 张已有宫格图片替换对应坑位。"
            + (f"仍缺少可替代宫格图片：{'、'.join(missing)}。" if missing else "已成功资产和付费记录均保留。")
        ),
    )
    categories["digital_humans"] = category
    result["categories"] = categories
    remove_keys = ["digital_human_fallback_pending"] if not missing else []
    _set_task(task_id, result=result, _remove_result_keys=remove_keys)
    return {"applied": applied, "missing": missing}


def _grid_preview_path(task_id: str, grid_id: str) -> Path | None:
    """返回真实宫格原图，不把裁切后的单格伪装成宫格预览。"""
    task = _preview_task_snapshot(task_id)
    result = task.get("result") if isinstance(task, Mapping) else None
    assets = result.get("first_frame_assets") if isinstance(result, Mapping) else None
    batches = assets.get("grid_batches") if isinstance(assets, Mapping) else None
    if not isinstance(batches, list) or not any(isinstance(item, Mapping) and item.get("grid_id") == grid_id for item in batches):
        return None
    try:
        candidate = _safe_director_review_file(
            Path(str(result.get("output_dir") or "")) / "grids" / f"{grid_id}.jpg"
        )
    except (OSError, ValueError):
        return None
    if candidate is not None:
        return candidate
    # 数字人补全任务复用原任务的首帧数据，宫格文件仍在 base_asset_task_id
    # 对应的原始素材目录；回溯查找，避免页面把有效宫格显示成破损图片。
    base_task_id = str(task.get("base_asset_task_id") or "").strip() if isinstance(task, Mapping) else ""
    if base_task_id and base_task_id != task_id:
        return _grid_preview_path(base_task_id, grid_id)
    return None


def _asset_video_preview_path(task_id: str, shot_id: str) -> Path | None:
    """按 AIGC 镜头顺序安全读取本机视频预览文件。"""
    task = _preview_task_snapshot(task_id)
    result = task.get("result") if isinstance(task, Mapping) else None
    if not isinstance(result, Mapping):
        return None
    assets = result.get("aigc_video_assets")
    records = assets.get("shot_results") if isinstance(assets, Mapping) else None
    if not isinstance(records, list):
        return None
    # 失败镜头不会生成本地文件。不能再按 video_paths 的数组下标回推，
    # 否则一条失败记录会使它之后的全部成功镜头预览错位。
    record = next(
        (item for item in records if isinstance(item, Mapping) and str(item.get("shot_id") or "") == shot_id),
        None,
    )
    if not isinstance(record, Mapping) or str(record.get("status") or "") != "succeeded":
        return None
    try:
        candidate = _safe_director_review_file(record.get("video_path"))
    except (OSError, ValueError):
        return None
    return candidate


