def _recent_task_snapshots(limit: int = 20) -> list[dict]:
    tasks = _persisted_task_snapshots()
    return sorted(tasks, key=lambda task: task.get("updated_at", 0), reverse=True)[:limit]


def _task_matches_story(task: Mapping[str, object], story_task_id: str) -> bool:
    """判断任务是否属于指定故事，兼容任务顶层和结果快照两种来源字段。"""

    target = str(story_task_id or "").strip()
    if not target:
        return True
    if str(task.get("task_id") or "") == target or str(task.get("source_story_task_id") or "") == target:
        return True
    result = task.get("result")
    return isinstance(result, Mapping) and str(result.get("source_story_task_id") or "") == target


def _list_style_tasks(limit: int = 20, *, source_story_task_id: str = "") -> list[dict]:
    """Return persisted tasks, optionally returning the complete archive for one story.

    The normal console view stays bounded, but the assets page must not lose a paid
    asset merely because many unrelated tasks were created after it.  A story-scoped
    request therefore scans the archive and applies the limit only after filtering.
    """

    _reconcile_style_worker_tasks()
    story_filter = str(source_story_task_id or "").strip()
    if story_filter:
        task_by_id = {
            str(task["task_id"]): task
            for task in _archived_story_task_snapshots(story_filter)
            if task.get("task_id")
        }
        try:
            persisted_tasks = [
                _style_task_listing_snapshot(task)
                for task in _persisted_task_snapshots()
                if task is not None
                and not task.get("archived_at")
                and _task_matches_story(task, story_filter)
            ]
        except OSError:
            persisted_tasks = []
        with STYLE_TASKS_LOCK:
            live_tasks = [
                _style_task_listing_snapshot(task)
                for task in STYLE_TASKS.values()
                if not task.get("archived_at")
                if _task_matches_story(task, story_filter)
            ]
        persisted_by_id = {str(task["task_id"]): task for task in persisted_tasks if task.get("task_id")}
        task_by_id.update(persisted_by_id)
        for task in live_tasks:
            task_id = str(task.get("task_id") or "")
            if not task_id:
                continue
            # 独立 worker 会跨进程写快照；页面不能被 8768 启动时留下的
            # 内存副本覆盖，因此 worker 任务优先读取磁盘状态。
            task_by_id[task_id] = persisted_by_id.get(task_id, task) if _external_style_worker(task) else task
        return sorted(task_by_id.values(), key=lambda task: task.get("updated_at", 0), reverse=True)[: max(1, int(limit))]

    cache_key = _style_task_listing_cache_key()
    now = time.monotonic()
    with STYLE_TASK_LIST_CACHE_LOCK:
        cached_at = float(STYLE_TASK_LIST_CACHE.get("created_at") or 0.0)
        cached_key = str(STYLE_TASK_LIST_CACHE.get("key") or "")
        cached_tasks = STYLE_TASK_LIST_CACHE.get("tasks")
        if (
            cached_key == cache_key
            and now - cached_at < STYLE_TASK_LIST_CACHE_TTL_SECONDS
            and isinstance(cached_tasks, list)
        ):
            return [dict(task) for task in cached_tasks[:limit] if isinstance(task, Mapping)]

    # 仅允许一个请求刷新磁盘快照，其余轮询请求复用刷新结果；构建过程不持有
    # CACHE_LOCK，避免资产本地补跑恢复时写任务快照造成锁顺序反转。
    with STYLE_TASK_LIST_BUILD_LOCK:
        now = time.monotonic()
        with STYLE_TASK_LIST_CACHE_LOCK:
            cached_at = float(STYLE_TASK_LIST_CACHE.get("created_at") or 0.0)
            cached_key = str(STYLE_TASK_LIST_CACHE.get("key") or "")
            cached_tasks = STYLE_TASK_LIST_CACHE.get("tasks")
            if (
                cached_key == cache_key
                and now - cached_at < STYLE_TASK_LIST_CACHE_TTL_SECONDS
                and isinstance(cached_tasks, list)
            ):
                return [dict(task) for task in cached_tasks[:limit] if isinstance(task, Mapping)]

        task_by_id = {
            str(task["task_id"]): _style_task_listing_snapshot(task)
            for task in _recent_task_snapshots(limit=200)
            if task.get("task_id") and not task.get("archived_at")
        }
        persisted_by_id = dict(task_by_id)
        with STYLE_TASKS_LOCK:
            for task_id, task in STYLE_TASKS.items():
                if task.get("archived_at"):
                    continue
                task_snapshot = _style_task_listing_snapshot(task)
                task_by_id[task_id] = persisted_by_id.get(task_id, task_snapshot) if _external_style_worker(task_snapshot) else task_snapshot
        listing = sorted(task_by_id.values(), key=lambda task: task.get("updated_at", 0), reverse=True)
        with STYLE_TASK_LIST_CACHE_LOCK:
            STYLE_TASK_LIST_CACHE["key"] = cache_key
            STYLE_TASK_LIST_CACHE["created_at"] = time.monotonic()
            STYLE_TASK_LIST_CACHE["tasks"] = listing
        return [dict(task) for task in listing[:limit]]


def _task_matches_view(task: Mapping[str, object], view: str) -> bool:
    """Filter task API views without changing internal recovery scans."""

    normalized = str(view or "all").strip().lower() or "all"
    lifecycle = _task_lifecycle_status(task)
    if normalized in {"all", "internal"}:
        return True
    if normalized == "active":
        return lifecycle == "active"
    if normalized in {"recoverable", "recovery"}:
        return lifecycle == "recoverable"
    if normalized in {"history", "archived"}:
        return lifecycle != "active"
    return True


def _resolve_asset_task_for_retry(
    asset_task_id: str, source_story_task_id: str = ""
) -> tuple[str, dict | None]:
    """Resolve a retry request to a live asset task, including stale-page recovery.

    The asset page can remain open across an executor restart or a new asset-task
    snapshot. In that case the card still has the old task id even though the
    story still has a valid, persisted asset task containing the prompt,
    references and paid outputs. Resolve by story only when the submitted id is
    missing or is not an asset-production task; never replace a valid task id.
    """

    requested_id = str(asset_task_id or "").strip()
    task = _task_snapshot(requested_id) if requested_id else None
    if isinstance(task, Mapping) and task.get("task_type") == "asset_production":
        return requested_id, dict(task)

    story_id = str(source_story_task_id or "").strip()
    if not story_id:
        return requested_id, None
    candidates = []
    for item in _list_style_tasks(limit=2000, source_story_task_id=story_id):
        if not isinstance(item, Mapping) or item.get("task_type") != "asset_production":
            continue
        result = item.get("result")
        result_story_id = str(result.get("source_story_task_id") or "") if isinstance(result, Mapping) else ""
        if str(item.get("source_story_task_id") or result_story_id or "") == story_id:
            candidates.append(item)
    if not candidates:
        return requested_id, None
    resolved = max(candidates, key=lambda item: int(item.get("updated_at") or 0))
    resolved_id = str(resolved.get("task_id") or "").strip()
    return resolved_id, dict(resolved) if resolved_id else None


def _mark_orphaned_tasks(*, include_inprocess_tasks: bool = True) -> None:
    """仅在服务启动时中断失去归属的线程；轮询时只收敛独立 worker。"""
    for task in _recent_task_snapshots(limit=200):
        director_task = task.get("task_type") in {"director_story_review", "director_shot_script"}
        if (
            director_task
            and task.get("state") == "interrupted"
            and task.get("error_code") == "executor_restarted"
            and "继续未完成采集" in str(task.get("message") or "")
        ):
            # 兼容修复前已经落盘的快照：只更新可见恢复提示，不改变 task_id、输入或断点。
            task.update(
                message="本机执行器在任务完成前退出；输入与已保存断点仍在，可点击“从断点继续编导任务”恢复。",
                error_detail="主服务在任务完成前退出；编导任务未自动重试，避免未经确认重复调用付费模型。",
                updated_at=int(time.time()),
            )
            _persist_task_required(task)
            continue
        if task.get("state") in {"queued", "running"}:
            if _external_style_worker(task):
                identity = _style_worker_identity(task)
                if identity is True or identity is None:
                    # True 已确认当前 worker；None 时进程表不可读，不能误判并打断它。
                    continue
                checkpoint = _style_task_checkpoint(task)
                has_precollected_report = isinstance(checkpoint.get("precollected_report"), Mapping)
                if has_precollected_report:
                    # A partial-distillation worker can exit between its last
                    # durable report and the monitor reconciliation pass. Keep
                    # it in the evidence-waiting state so the UI exposes the
                    # safe "use existing samples" action instead of sending
                    # the user back to a new crawl.
                    task.update(
                        state="interrupted",
                        stage="waiting_for_evidence",
                        message="已有 11 条有效样本；可使用已有样本生成思维包和语言风格包",
                        error_code="waiting_for_evidence",
                        error_detail="蒸馏进程退出，但已保存完整采集报告；不会重新采集。",
                        lifecycle_status="recoverable",
                        updated_at=int(time.time()),
                    )
                    _persist_task_required(task)
                    continue
                task.update(
                    state="interrupted",
                    stage="style_worker_exited",
                    message="蒸馏独立进程已退出；可点击“继续未完成采集”从最近断点恢复。",
                    error_code="style_worker_exited",
                    error_detail="独立蒸馏 worker 已退出；未自动重试。",
                    lifecycle_status="recoverable",
                    updated_at=int(time.time()),
                )
                _persist_task_required(task)
                continue
            if not include_inprocess_tasks:
                # 当前 8768 进程内的编导线程没有独立 PID/心跳可供轮询确认。
                # 任务列表刷新不能因此把它误判成“执行器重启”。
                continue
            task.update(
                state="interrupted",
                stage="executor_restarted",
                message=(
                    "本机执行器在任务完成前退出；输入与已保存断点仍在，可点击“从断点继续编导任务”恢复。"
                    if director_task
                    else "本机执行器在任务完成前退出；可点击“继续未完成采集”恢复。"
                ),
                error_code="executor_restarted",
                error_detail=(
                    "主服务在任务完成前退出；编导任务未自动重试，避免未经确认重复调用付费模型。"
                    if director_task
                    else "主服务在任务完成前退出；未自动重试。"
                ),
                lifecycle_status="recoverable",
                updated_at=int(time.time()),
            )
            _persist_task_required(task)


def _reconcile_style_worker_tasks() -> None:
    """任务列表轮询仅检查独立蒸馏 worker，绝不终止当前编导线程。"""
    global STYLE_WORKER_RECONCILE_LAST_AT, STYLE_WORKER_RECONCILE_KEY
    cache_key = _style_task_listing_cache_key()
    now = time.monotonic()
    with STYLE_WORKER_RECONCILE_LOCK:
        if (
            STYLE_WORKER_RECONCILE_KEY == cache_key
            and now - STYLE_WORKER_RECONCILE_LAST_AT < STYLE_WORKER_RECONCILE_TTL_SECONDS
        ):
            return
        _mark_orphaned_tasks(include_inprocess_tasks=False)
        STYLE_WORKER_RECONCILE_KEY = cache_key
        STYLE_WORKER_RECONCILE_LAST_AT = time.monotonic()


def _style_task_input(payload: Mapping[str, object]) -> dict[str, object]:
    """Persist only the public inputs required to resume a style collection."""
    # Tasks created through the HTTP/UI production entry must not silently
    # fall back to the legacy JSON-only style chain.  Direct unit callers can
    # still pass ``optional`` explicitly while migrating old fixtures.
    account_mode = str(payload.get("account_knowledge_mode") or "required").strip().lower()
    if account_mode not in {"required", "optional", "disabled"}:
        account_mode = "optional"
    raw_source_ids = payload.get("knowledge_source_ids")
    if isinstance(raw_source_ids, (list, tuple, set)):
        source_ids = [str(value or "").strip() for value in raw_source_ids if str(value or "").strip()]
    else:
        source_ids = []
    single_source_id = str(payload.get("knowledge_source_id") or "").strip()
    if single_source_id and single_source_id not in source_ids:
        source_ids.append(single_source_id)
    try:
        sample_target, max_video_duration_seconds = _style_collection_policy(payload)
    except ValueError:
        # This helper also normalizes old persisted task snapshots.  Route
        # handlers validate new requests before task creation, while legacy
        # snapshots without an explicit duration retain their old ten-minute
        # behavior rather than being made unusable by an upgrade.
        try:
            sample_target = int(payload.get("sample_target") or payload.get("minimum_samples") or 50)
        except (TypeError, ValueError):
            sample_target = 50
        max_video_duration_seconds = LEGACY_STYLE_MAX_VIDEO_DURATION_SECONDS
    return {
        "creator_home_url": str(payload.get("creator_home_url") or "").strip(),
        "creator_name": str(payload.get("creator_name") or "").strip(),
        "sample_target": sample_target,
        "max_video_duration_seconds": max_video_duration_seconds,
        "url_inventory_target": max(1, min(int(payload.get("url_inventory_target") or 80), 200)),
        "account_id": str(payload.get("account_id") or "").strip(),
        "account_knowledge_mode": account_mode,
        # Profile URLs launched from the knowledge-source queue use the first
        # stage evidence-only path. Direct historical style tasks remain
        # model-backed when this flag is absent.
        "evidence_only": payload.get("evidence_only") is True or str(payload.get("evidence_only") or "").strip().lower() in {"1", "true", "yes", "on"},
        # Profile URLs entered from the unified knowledge-source intake carry
        # their source identity into the durable worker snapshot.  Keeping the
        # list bounded and de-duplicated makes the association auditable after
        # a service restart without persisting arbitrary request fields.
        "knowledge_source_ids": source_ids[:50],
    }


def _is_legacy_style_collection_task(task: Mapping[str, object]) -> bool:
    """识别早期未写入 task_type 的风格采集任务，不把其他任务误当成可恢复任务。"""

    if task.get("task_type"):
        return False
    if str(task.get("state") or "") == "interrupted" and str(task.get("stage") or "") == "executor_restarted":
        return True
    result = task.get("result")
    report = result.get("report") if isinstance(result, Mapping) else None
    return isinstance(report, Mapping) and str(report.get("platform") or "").lower() in {"douyin", "bilibili"}


def _is_style_collection_task(task: Mapping[str, object]) -> bool:
    return task.get("task_type") == "style_collection" or _is_legacy_style_collection_task(task)


_RESUMABLE_STYLE_INTERRUPTION_STAGES = {"executor_restarted", "style_worker_exited"}
_RESUMABLE_STYLE_PARTIAL_STAGES = {
    "sample_insufficient",
    "distillation_failed",
    "account_knowledge_distillation_failed",
}
_RESUMABLE_STYLE_EVIDENCE_STAGES = {"waiting_for_evidence"}


def _style_task_listing_snapshot(task: Mapping[str, object]) -> dict:
    """为旧任务补充只读兼容标记，确保前端不会因缺少 task_type 静默失效。"""

    snapshot = _asset_resume_metadata(_normalize_task_snapshot(_reconcile_local_video_retry(dict(task))))
    checkpoint = _style_task_checkpoint(snapshot)
    if (
        snapshot.get("task_type") == "style_collection"
        and snapshot.get("state") == "interrupted"
        and snapshot.get("stage") == "style_worker_exited"
        and isinstance(checkpoint.get("precollected_report"), Mapping)
    ):
        # A worker can exit after persisting the complete report but before
        # the monitor records its final result. Expose this as an evidence
        # retry in the page index so the user can reuse samples safely.
        snapshot["stage"] = "waiting_for_evidence"
        snapshot["error_code"] = "waiting_for_evidence"
        snapshot["message"] = "已有有效样本；可使用已有样本生成思维包和语言风格包"
    if _is_legacy_style_collection_task(snapshot):
        snapshot.setdefault("task_type", "style_collection")
        snapshot["legacy_resume"] = True
        has_checkpoint = _has_style_checkpoint(_style_task_checkpoint(snapshot))
        snapshot["resume_mode"] = "checkpoint" if has_checkpoint else "restart_without_checkpoint"
        if not has_checkpoint:
            snapshot["message"] = "旧任务未保存主页链接或采集断点；请粘贴主页链接后继续。"
    return snapshot


def _style_task_summary(task: Mapping[str, object]) -> dict:
    """Return the small task index used for page navigation and task lookup.

    Full ``result`` payloads can contain TTS timelines, shot scripts and asset
    metadata. They are fetched from the task-detail endpoint only when a page
    needs to render them; putting them in the navigation index makes every
    page parse the entire historical archive.
    """

    snapshot = dict(task)
    result = snapshot.pop("result", None)
    if isinstance(result, Mapping):
        for key in ("source_rewrite_id", "source_story_task_id", "review_status"):
            if result.get(key) is not None:
                snapshot[key] = result[key]
        # 资产页需要在轻量列表阶段恢复逐镜路由，不能为此再下载完整素材结果。
        # 只把编导脚本（不含外部素材大字段）带入摘要，资产任务仍走详情接口。
        if snapshot.get("task_type") == "director_shot_script":
            snapshot["result"] = {
                "source_story_task_id": result.get("source_story_task_id", ""),
                "source_rewrite_id": result.get("source_rewrite_id", ""),
                "shot_video_script": result.get("shot_video_script", []),
            }
        elif snapshot.get("task_type") == "asset_production":
            compact_result: dict[str, object] = {
                "source_story_task_id": result.get("source_story_task_id", ""),
                "categories": result.get("categories", {}),
            }
            first_frame = result.get("first_frame_assets")
            if isinstance(first_frame, Mapping):
                compact_result["first_frame_assets"] = {
                    # 仅保留“可复用首帧”信号，避免把宫格原图/URL塞进任务索引。
                    "available": True,
                }
            snapshot["result"] = compact_result
        elif snapshot.get("task_type") == "style_collection":
            # The writing page needs one durable, non-sensitive checkpoint
            # signal to distinguish an exhausted candidate inventory (which
            # can distill existing samples) from an ordinary resumable crawl.
            # Keep the task index compact; the full report remains available
            # from the task-detail endpoint.
            checkpoint = result.get("checkpoint")
            if isinstance(checkpoint, Mapping):
                snapshot["result"] = {
                    "checkpoint": {
                        "candidate_inventory_complete": bool(
                            checkpoint.get("candidate_inventory_complete") is True
                        ),
                        "precollected_report": bool(
                            isinstance(checkpoint.get("precollected_report"), Mapping)
                        ),
                    }
                }
    return snapshot


def _style_task_checkpoint(task: Mapping[str, object]) -> dict[str, object]:
    result = task.get("result")
    if not isinstance(result, Mapping):
        return {}
    checkpoint = result.get("checkpoint")
    return dict(checkpoint) if isinstance(checkpoint, Mapping) else {}


def _has_style_checkpoint(checkpoint: Mapping[str, object] | None) -> bool:
    """识别旧浏览器候选断点和 TikHub 稳定断点两种形状。"""

    if not isinstance(checkpoint, Mapping):
        return False
    if checkpoint.get("candidates"):
        return True
    return bool(
        checkpoint.get("sec_user_id")
        or checkpoint.get("completed_work_ids")
        or str(checkpoint.get("max_cursor") or "0") not in {"", "0"}
    )


def _run_style_task(task_id: str, payload: dict, checkpoint: Mapping[str, object] | None = None) -> None:
    def report(stage: str, progress: int, message: str) -> None:
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, int(progress))), message=message)

    def save_checkpoint(value: dict[str, object]) -> None:
        _set_task(task_id, result={"checkpoint": dict(value)})

    source_ids = _knowledge_source_ids(payload)

    def mark_sources(status: str, *, error_code: str = "", error_message: str = "") -> None:
        """Reflect the worker lifecycle on every source bound to this task.

        Source state is audit metadata, not a reason to lose a completed style
        task.  If the Vault/registry is temporarily unavailable we keep the
        worker result and log the synchronization failure for an explicit
        retry from the queue.
        """

        if not source_ids:
            return
        try:
            _knowledge_source_mark_task(source_ids, task_id, status)
            if status == "FAILED" and error_message:
                registry = _knowledge_source_registry()
                for source_id in source_ids:
                    try:
                        current = registry.get(source_id)
                        if current is None:
                            continue
                        repository = None
                        if str(current.get("obsidian_path") or "").strip():
                            repository = _configured_obsidian_vault(create=False)
                        registry.transition(
                            source_id,
                            "FAILED",
                            error_code=error_code or "style_task_failed",
                            error_message=error_message,
                            repository=repository,
                        )
                    except Exception:
                        TASK_LOGGER.exception("style source %s failure status sync failed", source_id)
        except Exception:
            TASK_LOGGER.exception("style task %s source status sync failed", task_id)

    try:
        mark_sources("PROCESSING")
        if checkpoint:
            report("resuming", 22, "独立蒸馏进程已恢复采集断点，继续处理未完成候选作品")
        else:
            report("starting", 1, "独立蒸馏进程已启动，准备启动采集器")
        status, result = _create_style_package(
            payload,
            progress_reporter=report,
            checkpoint=checkpoint,
            checkpoint_reporter=save_checkpoint,
            task_id=task_id,
        )
        if 200 <= status < 300:
            account_knowledge = result.get("account_knowledge") if isinstance(result, Mapping) else None
            evidence_status = str(account_knowledge.get("evidence_status") or "") if isinstance(account_knowledge, Mapping) else ""
            if evidence_status == "WAITING_FOR_EVIDENCE":
                # Evidence collection is intentionally resumable.  Do not
                # convert an under-target corpus into a successful/100% task
                # and do not delete its checkpoint.
                mark_sources("PENDING_REVIEW")
                # Keep the queue status within the existing source contract,
                # while exposing the evidence gate in processing_result so the
                # console can distinguish "待补齐证据" from a finished asset.
                if source_ids:
                    try:
                        registry = _knowledge_source_registry()
                        for source_id in source_ids:
                            current = registry.get(source_id)
                            repository = _configured_obsidian_vault(create=False) if current and str(current.get("obsidian_path") or "").strip() else None
                            registry.update_processing(
                                source_id,
                                status="PENDING_REVIEW",
                                metadata={
                                    "processing_route": "account_style_collection",
                                    "processing_task_id": task_id,
                                    "processing_result": {
                                        "route": "account_style_collection",
                                        "task_id": task_id,
                                        "evidence_status": "WAITING_FOR_EVIDENCE",
                                        "eligible_work_count": int(account_knowledge.get("eligible_work_count") or 0),
                                        "target_valid_works": int(account_knowledge.get("target_valid_works") or 50),
                                        "evidence_set_id": str(account_knowledge.get("evidence_set_id") or ""),
                                    },
                                    "last_processed_at": utc_now(),
                                },
                                repository=repository,
                            )
                    except Exception:
                        TASK_LOGGER.exception("style task %s evidence status sync failed", task_id)
                _set_task(
                    task_id,
                    state="interrupted",
                    stage="waiting_for_evidence",
                    progress=72,
                    message=str((account_knowledge or {}).get("eligible_work_count", 0)) + "/" + str((account_knowledge or {}).get("target_valid_works", 50)) + " 篇合格作品；可继续采集",
                    result=result,
                )
                return
            # Style collection produces a governed asset.  It remains outside
            # the production-ready source state until the knowledge console
            # updates or enables the resulting account/style package.
            mark_sources("PENDING_REVIEW")
            # 第一阶段的 evidence_only 任务在达到目标后只完成证据集，不能
            # 伪装成思维包/语言风格包已经生成。保留 succeeded 作为采集任务
            # 的终态，但用 ready_to_distill 阶段明确表示后续 Skill 尚未执行。
            if evidence_status == "READY_TO_DISTILL" and (
                payload.get("evidence_only") is True
                or str(payload.get("evidence_only") or "").strip().lower() in {"1", "true", "yes", "on"}
            ):
                _set_task(
                    task_id,
                    state="succeeded",
                    stage="ready_to_distill",
                    progress=80,
                    message=str((account_knowledge or {}).get("eligible_work_count", 0))
                    + "/"
                    + str((account_knowledge or {}).get("target_valid_works", 50))
                    + " 篇合格作品；证据集已达标，等待后续 Skill 蒸馏",
                    result=result,
                    _remove_result_keys=[],
                )
                return
            if evidence_status == "READY_TO_DISTILL" and source_ids:
                try:
                    registry = _knowledge_source_registry()
                    for source_id in source_ids:
                        current = registry.get(source_id)
                        repository = _configured_obsidian_vault(create=False) if current and str(current.get("obsidian_path") or "").strip() else None
                        registry.update_processing(
                            source_id,
                            status="PENDING_REVIEW",
                            metadata={
                                "processing_route": "account_style_collection",
                                "processing_task_id": task_id,
                                "processing_result": {
                                    "route": "account_style_collection",
                                    "task_id": task_id,
                                    "evidence_status": evidence_status,
                                    "eligible_work_count": int(account_knowledge.get("eligible_work_count") or 0) if isinstance(account_knowledge, Mapping) else 0,
                                    "target_valid_works": int(account_knowledge.get("target_valid_works") or 50) if isinstance(account_knowledge, Mapping) else 50,
                                    "evidence_set_id": str(account_knowledge.get("evidence_set_id") or "") if isinstance(account_knowledge, Mapping) else "",
                                },
                                "last_processed_at": utc_now(),
                            },
                            repository=repository,
                        )
                except Exception:
                    TASK_LOGGER.exception("style task %s ready evidence status sync failed", task_id)
            _set_task(
                task_id, state="succeeded", stage="completed", progress=100, message="账号资产已生成，请到知识资产中枢后台管理修改或启用",
                result=result,
                _remove_result_keys=[] if payload.get("evidence_only") else ["checkpoint"],
            )
        else:
            mark_sources(
                "FAILED",
                error_code=str(result.get("status") or "style_task_failed"),
                error_message=str(result.get("message") or "采集任务失败"),
            )
            _set_task(task_id, state="failed", stage=str(result.get("status", "failed")), message=str(result.get("message", "采集任务失败")), result=result)
    except Exception as exc:
        TASK_LOGGER.exception("style task %s crashed", task_id)
        mark_sources("FAILED", error_code="style_task_internal_error", error_message=str(exc))
        _set_task(task_id, state="failed", stage="internal_error", message=f"本机执行器异常：{type(exc).__name__}")


def _create_style_task(payload: dict) -> dict:
    task_id = uuid.uuid4().hex
    now = int(time.time())
    task_input = _style_task_input(payload)
    with STYLE_TASKS_LOCK:
        STYLE_TASKS[task_id] = {
            "task_id": task_id,
            "task_type": "style_collection",
            "input": task_input,
            "state": "queued",
            "stage": "queued",
            "progress": 0,
            "message": "任务正在排队",
            "created_at": now,
            "updated_at": now,
            "worker": {"kind": "style_collection_worker", "state": "starting", "task_id": task_id},
        }
        task = dict(STYLE_TASKS[task_id])
    # 任务快照必须先落盘，再启动独立 worker；否则服务/浏览器重启后无法召回。
    try:
        _persist_task_required(task)
    except TaskPersistenceError:
        with STYLE_TASKS_LOCK:
            STYLE_TASKS.pop(task_id, None)
        raise
    try:
        _set_task(task_id, worker=_start_style_worker(task_id))
    except RuntimeError as exc:
        _set_task(
            task_id,
            state="failed",
            stage="style_worker_start_failed",
            progress=0,
            message=str(exc),
            worker={"kind": "style_collection_worker", "state": "failed", "task_id": task_id},
        )
    return _task_snapshot(task_id) or {"task_id": task_id}


def _resume_style_task(task_id: str, fallback_payload: Mapping[str, object] | None = None) -> dict:
    task = _task_snapshot(task_id)
    if task is None or not _is_style_collection_task(task):
        raise ValueError("未找到可恢复的风格采集任务")
    state = str(task.get("state") or "")
    stage = str(task.get("stage") or "")
    checkpoint = _style_task_checkpoint(task)
    has_precollected_report = isinstance(checkpoint.get("precollected_report"), Mapping)
    partial_retry = (
        state == "failed" and stage in _RESUMABLE_STYLE_PARTIAL_STAGES
    ) or (
        state == "interrupted"
        and stage == "style_worker_exited"
        and has_precollected_report
    )
    waiting_retry = state == "interrupted" and stage in _RESUMABLE_STYLE_EVIDENCE_STAGES
    interruption_retry = state == "interrupted" and stage in _RESUMABLE_STYLE_INTERRUPTION_STAGES
    partial_available = waiting_retry and bool(checkpoint.get("candidate_inventory_complete"))
    if partial_available and isinstance(fallback_payload, Mapping):
        partial_available = str(fallback_payload.get("distill_available_samples") or "").lower() in {"1", "true", "yes", "on"} or fallback_payload.get("distill_available_samples") is True
    if not partial_retry and not waiting_retry and not interruption_retry:
        raise ValueError("仅服务意外退出或已有样本可重试的任务可以继续；手动停止或已结束任务不会自动恢复")
    payload = task.get("input")
    resume_payload = _style_task_input(payload) if isinstance(payload, Mapping) else _style_task_input({})
    if not resume_payload["creator_home_url"] and fallback_payload:
        resume_payload = _style_task_input(fallback_payload)
    if partial_retry or partial_available:
        result = task.get("result")
        report = result.get("report") if isinstance(result, Mapping) else None
        if not isinstance(report, Mapping):
            report = checkpoint.get("precollected_report")
        ready_count = int(report.get("transcript_ready_count") or 0) if isinstance(report, Mapping) else 0
        if not isinstance(report, Mapping) or ready_count <= 0:
            raise ValueError("该任务没有可继续蒸馏的有效样本")
        if not resume_payload["creator_home_url"]:
            resume_payload["creator_home_url"] = str(report.get("creator_url") or "").strip()
        checkpoint = dict(checkpoint)
        checkpoint["precollected_report"] = dict(report)
        checkpoint["precollected_collection_id"] = str(result.get("collection_id") or "").strip() if isinstance(result, Mapping) else ""
        resume_checkpoint = checkpoint
        resume_payload["distill_available_samples"] = True
        resume_message = f"已保留 {ready_count} 条有效样本，直接继续蒸馏，不重新采集"
    elif (waiting_retry or _has_style_checkpoint(checkpoint)) and resume_payload["creator_home_url"]:
        resume_checkpoint = checkpoint
        resume_message = "已读取本地断点，准备继续未完成采集"
    else:
        if not resume_payload["creator_home_url"]:
            raise ValueError("该旧任务没有保存主页链接或采集断点；请先粘贴达人主页链接，再点击继续未完成采集")
        resume_checkpoint = {}
        resume_message = "旧任务没有可用断点，已按当前主页重新采集；本次将逐候选保存断点"
    _set_task(
        task_id,
        task_type="style_collection",
        input=resume_payload,
        state="queued",
        stage="partial_distill_queued" if (partial_retry or partial_available) else "resume_queued",
        progress=max(1, int(task.get("progress") or 0)),
        message=resume_message,
        result={"checkpoint": dict(resume_checkpoint)},
        # An evidence-waiting task is an intentional, user-requested resume
        # just like an executor interruption or partial-distillation retry.
        # Without this flag _set_task's terminal-state guard restores the
        # previous ``interrupted`` state, so the child worker exits immediately
        # and the UI appears to do nothing.
        _allow_interrupted_resume=interruption_retry or waiting_retry or partial_retry,
    )
    try:
        _set_task(task_id, worker=_start_style_worker(task_id))
    except RuntimeError as exc:
        _set_task(
            task_id,
            state="failed",
            stage="style_worker_start_failed",
            message=str(exc),
            worker={"kind": "style_collection_worker", "state": "failed", "task_id": task_id},
        )
    return _task_snapshot(task_id) or {"task_id": task_id}


def _get_approved_rewrite(rewrite_id: str) -> dict:
    """Only an explicitly approved copy may enter the director runtime."""
    record = STYLE_PACKAGE_STORE.get_rewrite(rewrite_id)
    if record.get("review_status") != "APPROVED":
        raise ValueError("文案尚未审核通过，不能进入编导层")
    approved_copy = str(record.get("approved_copy") or record.get("approved_payload", {}).get("approved_copy") or "").strip()
    if not approved_copy:
        raise ValueError("已审核文案缺少 approved_copy，不能进入编导层")
    return record


def _voice_catalog_snapshot() -> dict[str, Any]:
    """读取当前运行时的官方音色目录；历史定制音色永不进入生产。"""

    def official_only(value: Mapping[str, Any]) -> dict[str, Any]:
        voices = []
        for item in value.get("voices", []):
            if not isinstance(item, Mapping):
                continue
            if str(item.get("voice_type") or "official").strip().lower() != "official":
                continue
            if str(item.get("custom_speaker_id") or "").strip():
                continue
            if str(item.get("speaker_id") or "").strip() == CUSTOM_SPEAKER_PROTOCOL_ID:
                continue
            if str(item.get("resource_id") or DEFAULT_TTS_RESOURCE_ID).strip() != DEFAULT_TTS_RESOURCE_ID:
                continue
            # 运行时目录只向页面和后续 TTS 链路发布官方字段。
            # custom_speaker_id 即使为空也不再下发，避免旧目录元数据
            # 让用户误以为仍支持声音复刻或定制音色。
            cleaned = dict(item)
            cleaned.pop("custom_speaker_id", None)
            cleaned["voice_type"] = "official"
            cleaned["billing_mode"] = "official"
            cleaned["slot_source"] = ""
            voices.append(cleaned)
        if not voices:
            raise RuntimeError("官方 TTS 音色目录为空，已阻止定制音色回退")
        voice_keys = {str(item.get("voice_key") or "").strip() for item in voices}
        defaults_raw = value.get("defaults") if isinstance(value.get("defaults"), Mapping) else {}
        defaults = {
            gender: str(defaults_raw.get(gender) or "").strip()
            if str(defaults_raw.get(gender) or "").strip() in voice_keys
            else ""
            for gender in ("male", "female", "neutral")
        }
        enabled_by_gender = {
            gender: next(
                (
                    str(item.get("voice_key") or "")
                    for item in voices
                    if bool(item.get("enabled", True))
                    and str(item.get("gender") or "neutral") == gender
                ),
                "",
            )
            for gender in ("male", "female", "neutral")
        }
        for gender, fallback in enabled_by_gender.items():
            if not defaults[gender] and fallback:
                defaults[gender] = fallback
        return {"version": str(value.get("version") or "local"), "defaults": defaults, "voices": voices}

    try:
        # 页面渲染是只读操作；目录不存在时直接使用内置种子，避免测试/只读
        # 环境因首次打开页面而尝试写入受保护的 AppData 目录。
        store = _voice_catalog_store()
        raw = store.load() if VOICE_CATALOG_PATH.is_file() else normalize_voice_catalog(DEFAULT_VOICE_CATALOG)
        return official_only(raw)
    except VoiceCatalogStoreError as exc:
        raise RuntimeError(f"音色目录不可用：{exc}") from exc


def _voice_catalog_public_snapshot() -> dict[str, Any]:
    catalog = _voice_catalog_snapshot()
    return {
        "schema_version": VoiceCatalogStore.schema_version,
        "version": catalog.get("version", "local"),
        "defaults": dict(catalog.get("defaults") or {}),
        "voices": [
            {key: value for key, value in dict(item).items() if key != "custom_speaker_id"}
            for item in catalog.get("voices", [])
        ],
    }


def _register_voice_profile(payload: Mapping[str, Any]) -> dict[str, Any]:
    voice = dict(payload)
    voice.pop("secrets", None)
    voice["voice_type"] = str(voice.get("voice_type") or "official").strip().lower()
    if voice["voice_type"] != "official":
        raise ValueError("定制音色/声音复刻已停用；当前仅允许使用官方 TTS 音色目录")
    speaker_id = str(voice.get("speaker_id") or "").strip()
    if not speaker_id or speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
        raise ValueError("登记官方 TTS 音色必须提供真实 speaker_id")
    if str(voice.get("custom_speaker_id") or "").strip():
        raise ValueError("官方 TTS 音色不允许携带 custom_speaker_id")
    if str(voice.get("resource_id") or DEFAULT_TTS_RESOURCE_ID).strip() != DEFAULT_TTS_RESOURCE_ID:
        raise ValueError("官方 TTS 音色仅支持 resource_id=seed-tts-2.0")
    voice["speaker_id"] = speaker_id
    voice["custom_speaker_id"] = ""
    voice["resource_id"] = DEFAULT_TTS_RESOURCE_ID
    # 官方音色状态接口未必返回性别；未提供时按 neutral 登记。
    voice.setdefault("gender", "neutral")
    # 页面登记官方音色时允许省略内部 voice_key；由展示名与真实 speaker_id
    # 派生稳定标识，避免重复填写或后续静默变更。
    if not str(voice.get("voice_key") or "").strip():
        voice["voice_key"] = _voice_clone_generated_key(
            str(voice.get("display_name") or "官方 TTS 音色"), speaker_id,
        )
    voice.setdefault("training_status", "ready")
    voice.setdefault("authorization_status", "verified")
    voice.setdefault("enabled", True)
    voice.setdefault("verified", True)
    try:
        catalog = _voice_catalog_store().register(voice)
    except VoiceCatalogStoreError as exc:
        raise ValueError(str(exc)) from exc
    return {"status": "registered", "voice_key": str(voice.get("voice_key") or ""), "catalog": catalog}


def _update_voice_profile(voice_key: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    patch = dict(payload)
    patch.pop("secrets", None)
    current_catalog = _voice_catalog_snapshot()
    current_voice = next(
        (item for item in current_catalog.get("voices", ()) if str(item.get("voice_key") or "") == voice_key),
        None,
    )
    if not isinstance(current_voice, Mapping):
        raise ValueError("未找到官方 TTS 音色；定制音色目录已停用")
    if str(current_voice.get("voice_type") or "official").strip().lower() != "official":
        raise ValueError("定制音色/声音复刻已停用；当前仅允许更新官方 TTS 音色状态")
    # 官方音色只允许修改本地启用开关，避免通过 PATCH 注入自定义 speaker、
    # resource_id 或训练状态。
    allowed_fields = {"enabled"}
    patch = {key: value for key, value in patch.items() if key in allowed_fields}
    # verified 只能由真实验收流程写入；普通页面更新不允许伪造已验收状态。
    patch.pop("verified", None)
    try:
        catalog = _voice_catalog_store().update(voice_key, patch)
    except VoiceCatalogStoreError as exc:
        raise ValueError(str(exc)) from exc
    return {"status": "updated", "voice_key": voice_key, "catalog": catalog}


def _verify_voice_profile(voice_key: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    """执行不产生费用的音色契约检查；不会伪造 verified 或发起 TTS。"""

    if str(payload.get("confirm") or "").strip() != "readonly-voice-verify":
        raise ValueError("音色验证需要 confirm=readonly-voice-verify；真实 TTS 验收必须走独立受控流程")
    catalog = _voice_catalog_snapshot()
    voice = next((item for item in catalog.get("voices", ()) if item.get("voice_key") == voice_key), None)
    if not isinstance(voice, Mapping):
        raise ValueError("未找到指定 voice_key")
    voice_type = str(voice.get("voice_type") or "official")
    resource_id = str(voice.get("resource_id") or "")
    provider_speaker_id = str(voice.get("speaker_id") or "").strip()
    custom_speaker_id = str(voice.get("custom_speaker_id") or "").strip()
    checks = {
        "voice_key": bool(str(voice.get("voice_key") or "").strip()),
        "speaker_id": bool(provider_speaker_id),
        "custom_speaker_id": (
            bool(custom_speaker_id)
            if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID
            else not custom_speaker_id
        ),
        "enabled": bool(voice.get("enabled")),
        "resource_id": bool(resource_id),
        "resource_type_match": (
            (voice_type == "official" and resource_id == "seed-tts-2.0")
            or (voice_type == "custom" and resource_id in CUSTOM_VOICE_RESOURCE_IDS)
        ),
    }
    # ``enabled`` 是本地发布开关，不应阻断对刚同步音色的契约检查；
    # 新音色先以停用状态进入目录，检查通过后再由管理员显式启用。
    contract_checks = {key: value for key, value in checks.items() if key != "enabled"}
    passed = all(contract_checks.values())
    return {
        "status": "passed" if passed else "failed",
        "evidence_level": "offline_catalog_contract",
        "voice_key": voice_key,
        "voice": dict(voice),
        "checks": checks,
        "verified": bool(voice.get("verified")),
        "ready_to_enable": bool(passed and not voice.get("enabled")),
        "message": "目录契约检查通过；尚未发起真实 TTS，不会自动修改 verified。" if passed else "目录契约检查未通过；未发起真实 TTS。",
    }


def _story_task_voice_snapshot(story_task_id: str) -> dict[str, Any]:
    task = _handoff_story_task_snapshot(story_task_id) or _task_snapshot(story_task_id)
    if not isinstance(task, Mapping):
        raise ValueError("未找到 v2 编导任务")
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    voice = task.get("voice_resolution") if isinstance(task.get("voice_resolution"), Mapping) else result.get("voice_resolution")
    if not isinstance(voice, Mapping):
        director_result = result.get("director_result") if isinstance(result.get("director_result"), Mapping) else {}
        tts = director_result.get("tts") if isinstance(director_result.get("tts"), Mapping) else {}
        voice = (
            tts.get("tts_voice_resolution")
            if isinstance(tts.get("tts_voice_resolution"), Mapping)
            else (_tts_contract_view(tts).get("voice") if isinstance(tts, Mapping) else {})
        )
    return {
        "story_task_id": story_task_id,
        "task_state": str(task.get("state") or ""),
        "locked": bool(voice),
        "voice": dict(voice) if isinstance(voice, Mapping) else {},
    }


def _resolve_story_voice(voice_key: str = "") -> dict:
    """Resolve the page selection through the唯一音色目录 before any paid call."""

    try:
        return resolve_voice_selection(
            {"voice_key": voice_key} if voice_key else {},
            catalog=_voice_catalog_snapshot(),
        )
    except VoiceCatalogError as exc:
        raise ValueError(f"配音音色无效：{exc}") from exc


def _resolve_voice_for_paid_preview(voice_key: str) -> dict:
    """解析已训练音色，供读取训练接口返回的 ``demo_audio``。

    这里故意不要求本地 ``enabled``。试听只读取训练接口返回的短音频，
    不会发起正式 TTS；新音色在用户试听前通常仍是停用状态，不能因为
    停用就把试听入口挡住。正式 TTS 仍由 ``resolve_voice_selection`` 的
    enabled/verified 门槛控制。
    """

    # 保留普通解析器作为第一入口，便于测试替身和已经验收的官方音色复用
    # 同一份绑定逻辑；未验证的已训练音色再走下面的“预览专用”门槛。
    try:
        resolved = _resolve_story_voice(voice_key)
    except ValueError:
        resolved = {}
    if isinstance(resolved, Mapping) and resolved:
        training_status = str(resolved.get("training_status") or "").strip().lower()
        authorization_status = str(resolved.get("authorization_status") or "").strip().lower()
        if training_status in {"success", "active", "ready"} and (
            not authorization_status or authorization_status in {"active", "verified", "authorized", "success"}
        ):
            return dict(resolved)

    catalog = normalize_voice_catalog(_voice_catalog_snapshot())
    voice = next((item for item in catalog["voices"] if item["voice_key"] == voice_key), None)
    if voice is None:
        raise ValueError("未找到指定 voice_key")
    training_status = str(voice.get("training_status") or "").strip().lower()
    if training_status not in {"success", "active", "ready"}:
        raise ValueError("音色训练尚未完成，暂不能试听")
    authorization_status = str(voice.get("authorization_status") or "").strip().lower()
    if authorization_status not in {"active", "verified", "authorized", "success"}:
        raise ValueError("音色授权状态尚未就绪，暂不能试听")
    return dict(voice)


def _voice_clone_download_demo_audio(preview_url: str, voice_key: str) -> tuple[str, int]:
    """下载训练接口返回的一小时有效 ``demo_audio`` 并发布为本地试听文件。

    该函数只访问训练响应中的试听地址，不创建 TTS transport，也不发送
    ``X-Api-Key``。本地文件名固定为受控 token，避免把供应商 URL 直接
    暴露给页面或把任意路径带入 ``VOICE_PREVIEW_DIR``。
    """

    source = str(preview_url or "").strip()
    if not source:
        raise ValueError("训练接口尚未返回 demo_audio；请先查询训练状态或重新训练")

    # 已经下载过的本地试听可以直接复用，避免重复请求供应商短链。
    local_prefix = "/api/voice-preview/"
    if source.startswith(local_prefix):
        token = unquote(source[len(local_prefix):].strip("/"))
        if not re.fullmatch(r"[A-Za-z0-9_-]+\.mp3", token):
            raise ValueError("本地试听地址无效")
        path = (VOICE_PREVIEW_DIR / token).resolve()
        try:
            path.relative_to(VOICE_PREVIEW_DIR.resolve())
        except ValueError as exc:
            raise ValueError("本地试听地址越界") from exc
        if not path.is_file():
            raise ValueError("本地试听文件不存在；请重新查询训练状态获取 demo_audio")
        return f"{local_prefix}{quote(token)}", path.stat().st_size

    parsed = urlparse(source)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError("训练接口返回的 demo_audio 不是有效的 http/https 地址")

    request = Request(
        source,
        headers={
            "Accept": "audio/*",
            "User-Agent": "workflowpyhua-voice-preview/1.0",
        },
    )
    try:
        with urlopen(request, timeout=30) as response:
            content_length = ""
            headers = getattr(response, "headers", None)
            if headers is not None:
                try:
                    content_length = str(headers.get("Content-Length") or "").strip()
                except AttributeError:
                    content_length = ""
            if content_length:
                try:
                    declared_length = int(content_length)
                except (TypeError, ValueError):
                    declared_length = 0
                if declared_length > MAX_AUDIO_BYTES:
                    raise ValueError("训练试听音频超过 10MB，已拒绝下载")
            audio = response.read(MAX_AUDIO_BYTES + 1)
    except HTTPError as exc:
        raise ValueError(f"训练试听音频下载失败（HTTP {exc.code}）") from exc
    except (URLError, TimeoutError, OSError) as exc:
        raise ValueError("训练试听音频下载失败，请稍后重试") from exc

    if not isinstance(audio, (bytes, bytearray)) or not audio:
        raise ValueError("训练接口返回的 demo_audio 为空")
    if len(audio) > MAX_AUDIO_BYTES:
        raise ValueError("训练试听音频超过 10MB，已拒绝下载")

    VOICE_PREVIEW_DIR.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(
        f"{voice_key}|{source}|{uuid.uuid4().hex}".encode("utf-8")
    ).hexdigest()[:24]
    token = f"demo-{digest}.mp3"
    path = (VOICE_PREVIEW_DIR / token).resolve()
    try:
        path.relative_to(VOICE_PREVIEW_DIR.resolve())
    except ValueError as exc:  # pragma: no cover - digest token is constrained
        raise ValueError("试听文件路径无效") from exc
    partial = path.with_suffix(".part")
    try:
        partial.write_bytes(bytes(audio))
        partial.replace(path)
    except OSError as exc:
        try:
            partial.unlink(missing_ok=True)
        except OSError:
            pass
        raise ValueError("训练试听音频无法保存到本地") from exc
    return f"{local_prefix}{quote(token)}", len(audio)


_PROTAGONIST_GENDERS = {"auto", "male", "female", "neutral"}
_PROTAGONIST_AGE_GROUPS = {
    "auto", "child", "teen", "young_adult", "adult", "middle_aged", "elderly",
}


def _normalize_protagonist_profile(value: object) -> dict[str, str]:
    """规范化编导层主角身份，禁止再隐式沿用历史固定人物。"""
    raw = value if isinstance(value, Mapping) else {}
    mode = str(raw.get("mode") or "auto").strip().lower()
    name = str(raw.get("name") or "").strip()[:80]
    gender = str(raw.get("gender") or "auto").strip().lower()
    age_group = str(raw.get("age_group") or "auto").strip().lower()
    identity = str(raw.get("identity") or "").strip()[:160]
    if mode not in {"auto", "manual"}:
        raise ValueError("主角模式仅支持自动识别或手动设定")
    if gender not in _PROTAGONIST_GENDERS:
        raise ValueError("主角性别设置无效")
    if age_group not in _PROTAGONIST_AGE_GROUPS:
        raise ValueError("主角年龄段设置无效")
    if mode == "manual" and not any((name, identity, gender != "auto", age_group != "auto")):
        raise ValueError("手动主角设定至少需要填写姓名、身份、性别或年龄段之一")
    return {
        "mode": mode,
        "name": name,
        "gender": gender,
        "age_group": age_group,
        "identity": identity,
    }


def _tts_cache_key(director_result: dict, voice_resolution: Mapping[str, Any] | None = None) -> str:
    """Only identical synthesized text and runtime voice settings may reuse audio."""
    voice = voice_resolution or _resolve_story_voice()
    payload = {
        "segments": director_result["director_output"]["segments"],
        "voice_key": voice["voice_key"],
        "speaker_id": voice["speaker_id"],
        "resource_id": voice.get("resource_id", ""),
        "model": voice.get("model", ""),
        "speed_ratio": 1.1,
        "loudness_rate": 0,
        "pitch": 0,
        "silence_duration": 0,
        "tts_runtime": "volcengine_tts_2.0_local_v1",
    }
    encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _tts_audio_only(tts: Mapping[str, Any]) -> dict:
    """删除历史 TTS 时长字段；当前唯一时间权威是 CapCut STT。

    新任务只保留 ``tts_contract``；旧快照仍由迁移适配器原样读取。
    """

    if isinstance(tts.get("tts_contract"), Mapping):
        return _tts_contract_only(tts)

    return {
        **{
            key: value for key, value in tts.items()
            if key not in {"tts_durations", "tts_group_timelines", "total_timeline"}
        },
        "timing_authority": "capcut_stt_required",
    }


def _load_cached_tts(cache_key: str, segment_count: int) -> dict | None:
    manifest_path = DIRECTOR_TTS_CACHE_DIR / cache_key / "manifest.json"
    try:
        cached = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        return None
    try:
        contract = _tts_contract_view(cached)
    except (RuntimeError, ValueError, TypeError):
        # 历史缓存可能绑定了已停用的 ICL/定制音色；直接视为未命中，
        # 重新按当前官方 TTS 音色合成，不能让旧缓存阻断任务。
        return None
    paths = contract["audio"].get("paths")
    if not isinstance(paths, list) or len(paths) != segment_count:
        return None
    if not all(isinstance(path, str) and Path(path).is_file() for path in paths):
        return None
    return {**_tts_audio_only(cached), "cache": {"hit": True, "key": cache_key}}


def _store_tts_cache(cache_key: str, tts: dict) -> dict:
    """Copy generated audio into a stable cache, never reference a transient task folder."""
    contract = _tts_contract_view(tts) if isinstance(tts.get("tts_contract"), Mapping) else None
    paths = contract["audio"].get("paths") if contract else tts.get("tts_paths")
    if not isinstance(paths, list) or not all(isinstance(path, str) and Path(path).is_file() for path in paths):
        return tts
    cache_dir = DIRECTOR_TTS_CACHE_DIR / cache_key
    audio_dir = cache_dir / "audios"
    audio_dir.mkdir(parents=True, exist_ok=True)
    cached_paths: list[str] = []
    for index, source_path in enumerate(paths, start=1):
        source = Path(source_path)
        target = audio_dir / f"voice_{index:02d}{source.suffix or '.mp3'}"
        shutil.copy2(source, target)
        cached_paths.append(str(target.resolve()))
    if contract is not None:
        cached_contract = dict(contract)
        cached_audio = dict(contract.get("audio") or {})
        cached_audio["paths"] = cached_paths
        cached_contract["audio"] = cached_audio
        cached = {
            **_tts_contract_only({**tts, "tts_contract": cached_contract}),
            "cache": {"hit": False, "key": cache_key},
        }
    else:
        cached = {
            **_tts_audio_only(tts),
            "tts_paths": cached_paths,
            "cache": {"hit": False, "key": cache_key},
        }
    manifest_path = cache_dir / "manifest.json"
    temporary = manifest_path.with_suffix(".tmp")
    temporary.write_text(json.dumps(cached, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(manifest_path)
    return cached


def _recover_previous_tts(cache_key: str, segment_count: int) -> dict | None:
    """Promote a completed task's valid audio into the stable cache on first use."""
    for task in _list_style_tasks(limit=200):
        if task.get("task_type") != "director_story_review" or task.get("state") != "succeeded":
            continue
        result = task.get("result")
        director_result = result.get("director_result") if isinstance(result, dict) else None
        if not isinstance(director_result, dict):
            continue
        try:
            stored_tts = director_result.get("tts")
            stored_voice = (
                _tts_contract_view(stored_tts).get("voice")
                if isinstance(stored_tts, Mapping)
                else None
            )
            # 没有保存音色绑定的历史任务无法证明与当前 TTS 配置相同；
            # 跳过该条缓存，不能为了命中缓存而再次解析一个隐式默认音色。
            if not isinstance(stored_voice, Mapping):
                continue
            if _tts_cache_key(director_result, stored_voice) != cache_key:
                continue
        except (KeyError, TypeError, ValueError, RuntimeError):
            continue
        tts = director_result.get("tts")
        if not isinstance(tts, dict):
            continue
        cached = _store_tts_cache(cache_key, tts)
        if _load_cached_tts(cache_key, segment_count) is not None:
            return {**cached, "cache": {"hit": True, "key": cache_key, "source": "previous_completed_task"}}
    return None


def _ensure_director_task_active(task_id: str) -> None:
    task = _task_snapshot(task_id)
    if not task or task.get("state") == "interrupted":
        raise _TaskInterrupted("编导任务已被用户停止")


def _director_pipeline_progress(child_progress: int) -> int:
    """把内部逐镜阶段映射到用户可见的整条编导任务进度。"""

    value = max(0, min(100, int(child_progress)))
    return 80 + int(round(value * 0.2))


def _report_director_child_progress(
    parent_task_id: str, *, stage: str, progress: int, message: str,
) -> None:
    """同步内部逐镜任务进度到父任务，页面始终只观察一条任务线。"""

    parent = _task_snapshot(parent_task_id)
    if not parent or parent.get("task_type") != "director_story_review":
        return
    _set_task(
        parent_task_id,
        state="running",
        stage=f"shot_script_{stage}",
        progress=_director_pipeline_progress(progress),
        message=message,
        result={"checkpoint": "shot_script", "shot_script_task_id": parent.get("shot_script_task_id", "")},
    )


def _run_director_story_task(task_id: str, payload: dict, *, resume: bool = False) -> None:
    """Run the locked live director → TTS → story-review chain in a worker."""
    def report(stage: str, progress: int, message: str) -> None:
        _ensure_director_task_active(task_id)
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, int(progress))), message=message)

    try:
        rewrite_id = str(payload["rewrite_id"])
        aspect_ratio = str(payload["aspect_ratio"])
        director_package = _resolve_director_package(payload.get("director_package"))
        director_dynamic_params = _normalize_director_dynamic_params(
            director_package, payload.get("director_dynamic_params"),
        )
        voice_resolution = _resolve_story_voice(str(payload.get("voice_key") or "").strip())
        protagonist_profile = _normalize_protagonist_profile(payload.get("protagonist_profile"))
        record = _get_approved_rewrite(rewrite_id)
        auth_document = _require_director_runtime_auth_document(
            "未找到方舟/TTS 鉴权文档，无法启动真实编导任务"
        )

        task_dir = DIRECTOR_REVIEW_DIR / task_id
        task_dir.mkdir(parents=True, exist_ok=True)
        input_path = task_dir / "approved_copy.json"
        approved_copy = str(record["approved_copy"]).strip()
        input_path.write_text(json.dumps({"text": approved_copy}, ensure_ascii=False, indent=2), encoding="utf-8")

        persisted = _task_snapshot(task_id) or {}
        persisted_result = persisted.get("result") if isinstance(persisted, Mapping) else None
        persisted_result = persisted_result if isinstance(persisted_result, Mapping) else {}
        checkpoint = str(persisted_result.get("checkpoint") or "")
        if resume and checkpoint in {"full_text_directing", "tts_timeline", "tts_audio", "stt_timeline", "cinematic_story", "shot_script", "shot_script_queued"}:
            raw_director_result = persisted_result.get("director_result")
            director_result = dict(raw_director_result) if isinstance(raw_director_result, Mapping) else None
        else:
            director_result = None
        if director_result is None:
            report("full_text_directing", 8, f"正在加载{director_package['label']}并生成全文分段")
            director_result = _run_selected_director_package(
                director_package["package_id"], input_path, auth_document
            )
            _set_task(task_id, result={"checkpoint": "full_text_directing", "director_result": director_result})
        _ensure_director_task_active(task_id)
        segment_count = len(director_result["director_output"]["segments"])
        cache_key = _tts_cache_key(director_result, voice_resolution)
        cached_tts = _load_cached_tts(cache_key, segment_count) or _recover_previous_tts(cache_key, segment_count)
        # 服务重启或缓存清理后，断点中的旧音频路径可能已经失效；
        # 只有契约完整且所有音频仍在磁盘时才允许跳过 TTS，避免把失效路径带入 STT。
        resume_tts = director_result.get("tts") if isinstance(director_result, Mapping) else None
        resume_tts_valid = False
        if isinstance(resume_tts, Mapping):
            try:
                resume_audio = _tts_contract_view(resume_tts).get("audio", {}).get("paths", [])
                resume_tts_valid = (
                    isinstance(resume_audio, list)
                    and len(resume_audio) == segment_count
                    and all(isinstance(path, str) and Path(path).is_file() for path in resume_audio)
                )
            except (RuntimeError, ValueError, TypeError):
                resume_tts_valid = False
        if resume and checkpoint in {"tts_timeline", "tts_audio", "stt_timeline", "cinematic_story", "shot_script", "shot_script_queued"} and resume_tts_valid:
            report("tts_cache_hit", 40, "已从断点恢复旁白音频，跳过重复合成")
        elif cached_tts is not None:
            report("tts_cache_hit", 40, "TTS 文案与参数未变，已命中本机音频缓存，跳过付费合成")
            director_result["tts"] = cached_tts
        else:
            report("tts_audio", 40, "全文分段已生成，正在调用火山方舟 TTS 生成旁白音频")
            director_result["tts"] = _store_tts_cache(
                cache_key,
                run_live_tts(
                    director_result,
                    auth_document,
                    task_dir / "tts",
                    voice_key=voice_resolution["voice_key"],
                ),
            )
        if isinstance(director_result.get("tts"), Mapping):
            # 新任务只持久化版本化契约；旧任务的 tts_* 字段仅在
            # _tts_contract_view 迁移适配器内读取。
            director_result["tts"] = _tts_contract_only(director_result["tts"])
        _set_task(task_id, result={"checkpoint": "tts_audio", "director_result": director_result})
        if resume and checkpoint in {"stt_timeline", "cinematic_story", "shot_script", "shot_script_queued"} and isinstance(director_result.get("subtitle"), Mapping):
            report("capcut_stt_timeline", 60, "已从断点恢复剪映 STT 字幕时间线，跳过重复转录")
        else:
            report("capcut_stt_timeline", 60, "旁白音频已生成，正在由剪映字幕独立项目生成字幕与唯一时间线")
            _ensure_director_task_active(task_id)
            director_result["subtitle"] = run_live_subtitle_pipeline(director_result)
        _set_task(task_id, result={"checkpoint": "stt_timeline", "director_result": director_result})
        persisted_story = persisted_result.get("story_draft") if isinstance(persisted_result, Mapping) else None
        if resume and checkpoint in {"cinematic_story", "shot_script", "shot_script_queued"} and isinstance(persisted_story, Mapping):
            story_draft = dict(persisted_story)
            report("cinematic_story", 78, "已从断点恢复默片故事，继续生成逐镜脚本")
        else:
            report("cinematic_story", 78, "剪映 STT 时间线已生成，正在调用方舟撰写连续默片故事")
            _ensure_director_task_active(task_id)
            story_draft = run_live_story_draft(
                director_result,
                input_path,
                auth_document,
                protagonist_profile=protagonist_profile,
            )
        _ensure_director_task_active(task_id)
        _set_task(task_id, result={"checkpoint": "cinematic_story", "director_result": director_result, "story_draft": story_draft})

        review = {
            "task_id": task_id,
            "review_status": "PENDING_USER_REVIEW",
            "source_rewrite_id": rewrite_id,
            "director_package": director_package["package_id"],
            "director_package_source": director_package["source"],
            "director_dynamic_params": director_dynamic_params,
            "style_profile_id": record.get("style_profile_id", ""),
            "aspect_ratio": aspect_ratio,
            "voice_resolution": voice_resolution,
            "protagonist_profile": protagonist_profile,
            "approved_copy": approved_copy,
            "director_result": director_result,
            "story_draft": story_draft,
        }
        (task_dir / "story_review.json").write_text(json.dumps(review, ensure_ascii=False, indent=2), encoding="utf-8")
        _set_task(
            task_id,
            state="running",
            stage="shot_script_queued",
            progress=80,
            message="旁白音频、剪映 STT 时间线与故事已完成，正在继续生成最终逐镜视频脚本。",
            result={**review, "checkpoint": "shot_script_queued"},
        )
        # v2 is a single user-facing task: immediately continue from the
        # internal story context into the final shot script without approval.
        child = _create_director_shot_script_task(task_id)
        _set_task(task_id, result={"shot_script_task_id": child.get("task_id", "")})
    except _TaskInterrupted:
        TASK_LOGGER.info("director story task %s stopped by user", task_id)
        return
    except Exception as exc:
        TASK_LOGGER.exception("director story task %s crashed", task_id)
        detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:240]
        if (_task_snapshot(task_id) or {}).get("state") == "interrupted":
            TASK_LOGGER.info("director story task %s finished after user stop", task_id)
            return
        _set_task(
            task_id,
            state="failed",
            stage="director_runtime_failed",
            message=f"真实编导任务失败：{type(exc).__name__}：{detail or '无错误详情'}",
        )
        _mark_voice_replacement_failed_preserved(
            task_id,
            f"{type(exc).__name__}: {detail or '无错误详情'}",
        )


def _resolve_director_package(value: object) -> dict[str, Any]:
    package_id = str(value or DEFAULT_DIRECTOR_PACKAGE).strip().lower()
    spec = DIRECTOR_PACKAGE_SPECS.get(package_id)
    if spec is None:
        raise ValueError("编导包无效：请选择已接入的 v1、v2 或 v3 编导包")
    return dict(spec)


def _normalize_director_dynamic_params(
    director_package: Mapping[str, object], value: object,
) -> dict[str, object]:
    """只让 v3 消费动态评分参数，避免旧包接受却不生效。"""

    package_id = str(director_package.get("package_id") or "").strip().lower()
    if package_id != "v3":
        if value not in (None, {}, ""):
            raise ValueError("动态参数仅适用于 v3 编导包")
        return {}
    if value is None:
        raw: Mapping[str, object] = {}
    elif isinstance(value, Mapping):
        raw = value
    else:
        raise ValueError("v3 动态参数必须是 JSON 对象")
    try:
        return dict(normalize_v3_dynamic_params(raw))
    except MediaRouteScoringV3Error as exc:
        raise ValueError(str(exc)) from exc


def _run_selected_director_package(
    package_id: str, input_path: Path, auth_document: Path
) -> dict[str, Any]:
    """Load the selected package envelope before invoking the locked runtime.

    v1/v2/v3 共用已经验证过的全文导演、TTS 与故事链；v3 的差异只在冻结
    镜头后的五类媒体评分与轨道选择，避免另起一条未经验证的文本模型调用。
    """
    package = _resolve_director_package(package_id)
    result = run_live_director_text(input_path, auth_document)
    result["director_package"] = package["package_id"]
    result["director_package_source"] = package["source"]
    return result


def _latest_director_story_task_for_rewrite(
    rewrite_id: str, *, states: set[str] | None = None
) -> dict | None:
    """按文案编号找回编导任务，供页面恢复和创建接口去重使用。"""

    target = str(rewrite_id or "").strip()
    if not target:
        return None
    allowed = states or {"queued", "running", "succeeded", "failed", "interrupted"}
    candidates: list[dict] = []
    for task in _list_style_tasks(limit=2000):
        if task.get("task_type") != "director_story_review" or task.get("state") not in allowed:
            continue
        source = str(task.get("source_rewrite_id") or "").strip()
        result = task.get("result")
        if not source and isinstance(result, Mapping):
            source = str(result.get("source_rewrite_id") or "").strip()
        if source == target:
            candidates.append(task)
    return max(candidates, key=lambda item: int(item.get("updated_at") or 0)) if candidates else None


def _latest_director_shot_script_task(
    source_story_task_id: str, *, states: set[str] | None = None
) -> dict | None:
    """按故事任务编号找回逐镜脚本，避免页面恢复与后台自动推进重复创建。"""

    target = str(source_story_task_id or "").strip()
    if not target:
        return None
    allowed = states or {"queued", "running", "succeeded", "failed", "interrupted"}
    candidates: list[dict] = []
    for task in _list_style_tasks(limit=2000, source_story_task_id=target):
        if task.get("task_type") != "director_shot_script" or task.get("state") not in allowed:
            continue
        source = str(task.get("source_story_task_id") or "").strip()
        result = task.get("result")
        if not source and isinstance(result, Mapping):
            source = str(result.get("source_story_task_id") or "").strip()
        if source == target:
            candidates.append(task)
    return max(candidates, key=lambda item: int(item.get("updated_at") or 0)) if candidates else None


def _task_tts_fingerprint(task: Mapping[str, Any] | None) -> str:
    """从任务结果中读取已落盘的 TTS 指纹，不重新计算或猜测。"""

    if not isinstance(task, Mapping):
        return ""
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    direct = str(result.get("tts_fingerprint") or "").strip() if isinstance(result, Mapping) else ""
    if direct:
        return direct
    lock = result.get("director_lock") if isinstance(result, Mapping) and isinstance(result.get("director_lock"), Mapping) else {}
    if isinstance(lock, Mapping):
        direct = str(lock.get("tts_fingerprint") or "").strip()
        if direct:
            return direct
    director_result = result.get("director_result") if isinstance(result, Mapping) and isinstance(result.get("director_result"), Mapping) else {}
    if isinstance(director_result, Mapping):
        direct = str(director_result.get("tts_fingerprint") or "").strip()
        if direct:
            return direct
        lock = director_result.get("director_lock") if isinstance(director_result.get("director_lock"), Mapping) else {}
        return str(lock.get("tts_fingerprint") or "").strip() if isinstance(lock, Mapping) else ""
    return ""


def _requested_tts_fingerprint(
    task: Mapping[str, Any], voice: Mapping[str, Any]
) -> str:
    """为异步音色替换生成不含音频观测值的候选配置指纹。

    该指纹只用于排队阶段审计；真正 active 版本仍必须使用新任务完成后
    由 TTS 音频、剪映 STT 时间线共同生成的最终指纹。
    """

    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    director_result = (
        result.get("director_result")
        if isinstance(result, Mapping) and isinstance(result.get("director_result"), Mapping)
        else {}
    )
    output = (
        director_result.get("director_output")
        if isinstance(director_result, Mapping)
        and isinstance(director_result.get("director_output"), Mapping)
        else {}
    )
    segments = output.get("segments") if isinstance(output, Mapping) else []
    if not isinstance(segments, list):
        segments = []
    text = "\n".join(str(item) for item in segments)
    if not text:
        text = str(
            task.get("source_rewrite_id")
            or (result.get("source_rewrite_id") if isinstance(result, Mapping) else "")
            or task.get("task_id")
            or "tts-replacement"
        )
    return build_tts_fingerprint(
        text=text,
        voice_key=str(voice.get("voice_key") or ""),
        speaker_id=str(voice.get("speaker_id") or ""),
        resource_id=str(voice.get("resource_id") or ""),
        model=str(voice.get("model") or ""),
        speed_ratio=1.1,
        performance={"loudness_rate": 0, "pitch": 0, "silence_duration": 0},
    )


def _story_task_dependent_ids(story_task_id: str) -> list[str]:
    """列出引用同一故事任务的下游任务，不改变任务状态。"""

    target = str(story_task_id or "").strip()
    if not target:
        return []
    result_ids: list[str] = []
    # 失效必须覆盖旧故事的全部下游任务，不能受首页最近 20/2000 条列表限制。
    for task in _list_style_tasks(limit=100000):
        task_id = str(task.get("task_id") or "").strip()
        if not task_id or task_id == target:
            continue
        source = str(task.get("source_story_task_id") or "").strip()
        result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
        if not source and isinstance(result, Mapping):
            source = str(result.get("source_story_task_id") or "").strip()
        if source == target:
            result_ids.append(task_id)
    return result_ids


def _mark_story_dependents_invalidation(
    story_task_id: str,
    *,
    status: str,
    replacement_task_id: str,
    scope: list[str],
    old_fingerprint: str = "",
    new_fingerprint: str = "",
) -> list[str]:
    """把旧故事引用的 TTS/时间线/素材/剪辑任务标为失效候选。"""

    dependent_ids = _story_task_dependent_ids(story_task_id)
    for dependent_id in dependent_ids:
        marker = {
            "change_type": "tts_config_changed",
            "status": status,
            "scope": list(scope),
            "source_story_task_id": story_task_id,
            "replacement_task_id": replacement_task_id,
            "reason": "上游 TTS 音色/资源变化，必须按新 active 版本重建",
            "updated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        }
        if str(old_fingerprint or "").strip():
            marker["old_fingerprint"] = str(old_fingerprint).strip()
        if str(new_fingerprint or "").strip():
            marker["new_fingerprint"] = str(new_fingerprint).strip()
        changes: dict[str, object] = {"result": {"invalidation": marker}}
        if status == "stale":
            changes["superseded_by"] = replacement_task_id
            changes["lifecycle_status"] = "superseded"
        _set_task(dependent_id, **changes)
    return dependent_ids


def _change_story_task_voice(task_id: str, payload: Mapping[str, Any]) -> dict:
    """更换已锁定任务的音色：新任务完整成功后才替代旧 active 版本。"""

    if str(payload.get("confirm") or "").strip() != "rebuild-with-new-voice":
        raise ValueError("音色变更会重新生成 TTS、STT、字幕、镜头时间线和数字人；需要 confirm=rebuild-with-new-voice")
    old_task = _task_snapshot(task_id)
    if not old_task or old_task.get("task_type") != "director_story_review":
        raise ValueError("未找到可变更音色的 v2 编导任务")
    if str(old_task.get("state") or "") in {"queued", "running"}:
        raise ValueError("任务仍在运行，请等待完成后再变更音色")
    new_voice = _resolve_story_voice(str(payload.get("voice_key") or "").strip())
    old_voice = old_task.get("voice_resolution") if isinstance(old_task.get("voice_resolution"), Mapping) else {}
    if str(old_voice.get("voice_key") or "") == new_voice["voice_key"]:
        return {"status": "unchanged", "task": old_task, "voice_resolution": new_voice}
    result = old_task.get("result") if isinstance(old_task.get("result"), Mapping) else {}
    rewrite_id = str(old_task.get("source_rewrite_id") or result.get("source_rewrite_id") or "").strip()
    if not rewrite_id:
        raise ValueError("旧任务缺少 source_rewrite_id，不能安全重建")
    old_result = result if isinstance(result, Mapping) else {}
    old_fingerprint = str(
        _task_tts_fingerprint(old_task)
        or old_result.get("active_version")
        or ""
    ).strip()
    requested_fingerprint = _requested_tts_fingerprint(old_task, new_voice)
    new_payload = {
        "rewrite_id": rewrite_id,
        "aspect_ratio": str(old_task.get("aspect_ratio") or result.get("aspect_ratio") or "9:16"),
        "director_package": str(old_task.get("director_package") or result.get("director_package") or DEFAULT_DIRECTOR_PACKAGE),
        "director_dynamic_params": old_task.get("director_dynamic_params") or result.get("director_dynamic_params") or {},
        "voice_key": new_voice["voice_key"],
        "protagonist_profile": old_task.get("protagonist_profile") or result.get("protagonist_profile") or {},
        "replacement_of_task_id": task_id,
    }
    event_holder: list[dict[str, Any]] = []
    replacement_holder: dict[str, Any] = {}

    def queue_rebuild(current: dict[str, Any], _scope: Mapping[str, Any]) -> dict[str, Any]:
        replacement = _create_director_story_task(new_payload)
        replacement_holder.update(dict(replacement))
        replacement_task_id = str(replacement.get("task_id") or "").strip()
        if not replacement_task_id:
            raise RuntimeError("替代编导任务未返回 task_id，旧 active 版本保持不变")
        candidate = dict(current)
        candidate.update({
            "replacement_task_id": replacement_task_id,
            "new_voice_key": new_voice["voice_key"],
            "new_voice_resolution": dict(new_voice),
        })
        return candidate

    def capture_event(event: Mapping[str, Any]) -> None:
        event_holder.append(dict(event))

    transaction = transactional_tts_rebuild(
        {
            "active_version": old_fingerprint,
            "tts_fingerprint": old_fingerprint,
        },
        new_fingerprint=requested_fingerprint,
        rebuild=queue_rebuild,
        event_sink=capture_event,
        group_id=task_id,
        defer_commit=True,
    )
    if transaction["status"] != "replacement_pending":
        # 创建候选任务失败时，显式记录 failed_preserved；不把旧任务标成
        # stale，也不删除其可用音频/字幕/时间线。
        failed_event = dict(transaction.get("event") or {})
        failed_event.update({
            "old_task_id": task_id,
            "old_voice_key": old_voice.get("voice_key", ""),
            "new_voice_key": new_voice["voice_key"],
            "affected_task_ids": [],
        })
        event_path = DIRECTOR_REVIEW_DIR / task_id / "events.jsonl"
        event_path.parent.mkdir(parents=True, exist_ok=True)
        with event_path.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(failed_event, ensure_ascii=False) + "\n")
        _set_task(task_id, result={
            "invalidation": failed_event,
            "active_version": old_fingerprint,
        })
        return {"status": transaction["status"], "old_task_id": task_id, "event": failed_event}

    replacement = replacement_holder or {
        "task_id": str(transaction["state"].get("replacement_task_id") or "")
    }
    replacement_task_id = str(replacement.get("task_id") or "").strip()
    scope = invalidation_scope("tts_config_changed", group_id=task_id)
    dependent_ids = _mark_story_dependents_invalidation(
        task_id,
        status="stale_pending_rebuild",
        replacement_task_id=replacement_task_id,
        scope=list(scope["scope"]),
        old_fingerprint=old_fingerprint,
        new_fingerprint=requested_fingerprint,
    )
    event = dict(event_holder[-1] if event_holder else transaction.get("event") or {})
    event.update({
        "reason": "用户确认更换音色并重建完整下游链路",
        "old_voice_key": old_voice.get("voice_key", ""),
        "new_voice_key": new_voice["voice_key"],
        "old_task_id": task_id,
        "new_task_id": replacement_task_id,
        "old_fingerprint": old_fingerprint,
        "new_fingerprint": requested_fingerprint,
        "affected": list(scope["scope"]),
        "affected_task_ids": dependent_ids,
    })
    event_path = DIRECTOR_REVIEW_DIR / task_id / "events.jsonl"
    event_path.parent.mkdir(parents=True, exist_ok=True)
    with event_path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(event, ensure_ascii=False) + "\n")
    # 替代任务尚未完成时不改变旧任务状态；旧音频、STT、字幕和时间线仍可回滚/复用。
    pending_state = transaction["state"]
    _set_task(task_id, result={
        "invalidation": event,
        "active_version": str(pending_state.get("active_version") or old_fingerprint),
        "pending_version": replacement_task_id,
        "voice_change_pending": {
            "replacement_task_id": replacement_task_id,
            "new_voice_key": new_voice["voice_key"],
            "requested_fingerprint": requested_fingerprint,
            "affected": list(scope["scope"]),
        },
    })
    return {"status": "rebuild_queued", "old_task_id": task_id, "new_task": replacement, "event": event}


def _commit_voice_replacement(new_task_id: str) -> dict[str, Any]:
    """在完整下游成功后，以事务方式提交替代关系。

    事务只在这里切换 ``active_version``；排队和逐镜脚本完成阶段均不会
    触碰旧任务的 active 指针。重复收到素材完成回调时返回
    ``already_committed``，不重复写入替代事件。
    """

    new_task = _task_snapshot(new_task_id)
    if not isinstance(new_task, Mapping):
        return {"status": "missing_new_task", "new_task_id": new_task_id}
    old_task_id = str(new_task.get("replacement_of_task_id") or "").strip()
    if not old_task_id:
        return {"status": "not_a_replacement", "new_task_id": new_task_id}
    old_task = _task_snapshot(old_task_id)
    if not isinstance(old_task, Mapping):
        return {"status": "missing_old_task", "old_task_id": old_task_id}
    new_result = new_task.get("result") if isinstance(new_task.get("result"), Mapping) else {}
    new_voice_change = new_result.get("voice_change") if isinstance(new_result, Mapping) else {}
    if (
        isinstance(new_voice_change, Mapping)
        and str(new_voice_change.get("status") or "").strip() == "committed"
    ):
        return {"status": "already_committed", "old_task_id": old_task_id, "new_task_id": new_task_id}

    old_result = old_task.get("result") if isinstance(old_task.get("result"), Mapping) else {}
    old_fingerprint = str(
        _task_tts_fingerprint(old_task)
        or old_result.get("active_version")
        or ""
    ).strip()
    new_fingerprint = _task_tts_fingerprint(new_task)
    if not new_fingerprint:
        return {
            "status": "failed_preserved",
            "old_task_id": old_task_id,
            "new_task_id": new_task_id,
            "error": "替代任务缺少最终 TTS/STT 指纹，拒绝切换 active",
        }

    event_holder: list[dict[str, Any]] = []

    def commit_candidate(current: dict[str, Any], _scope: Mapping[str, Any]) -> dict[str, Any]:
        candidate = dict(current)
        candidate.update({
            "active_version": new_fingerprint,
            "tts_fingerprint": new_fingerprint,
            "committed_task_id": new_task_id,
        })
        return candidate

    transaction = transactional_tts_rebuild(
        {
            "active_version": old_fingerprint,
            "tts_fingerprint": old_fingerprint,
        },
        new_fingerprint=new_fingerprint,
        rebuild=commit_candidate,
        event_sink=lambda event: event_holder.append(dict(event)),
        group_id=old_task_id,
    )
    if transaction["status"] != "committed":
        return {
            "status": transaction["status"],
            "old_task_id": old_task_id,
            "new_task_id": new_task_id,
            "event": transaction.get("event", {}),
        }

    scope = invalidation_scope("tts_config_changed", group_id=old_task_id)
    dependent_ids = _mark_story_dependents_invalidation(
        old_task_id,
        status="stale",
        replacement_task_id=new_task_id,
        scope=list(scope["scope"]),
        old_fingerprint=old_fingerprint,
        new_fingerprint=new_fingerprint,
    )
    event = dict(event_holder[-1] if event_holder else transaction.get("event") or {})
    event.update({
        "reason": "替代任务已完成 TTS、STT、字幕、镜头脚本及素材生产，提交新 active 版本",
        "old_task_id": old_task_id,
        "new_task_id": new_task_id,
        "old_fingerprint": old_fingerprint,
        "new_fingerprint": new_fingerprint,
        "affected": list(scope["scope"]),
        "affected_task_ids": dependent_ids,
        "committed_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    })
    invalidation = dict(old_result.get("invalidation") or {}) if isinstance(old_result, Mapping) else {}
    invalidation.update(event)
    invalidation["status"] = "committed"
    _set_task(
        old_task_id,
        lifecycle_status="superseded",
        superseded_by=new_task_id,
        result={"invalidation": invalidation, "active_version": old_fingerprint},
        _remove_result_keys=["pending_version", "voice_change_pending"],
    )
    _set_task(
        new_task_id,
        result={
            "voice_change": {"status": "committed", "replaces_task_id": old_task_id},
            "active_version": transaction["state"]["active_version"],
            "version_status": "active",
        },
    )
    event_path = DIRECTOR_REVIEW_DIR / old_task_id / "events.jsonl"
    event_path.parent.mkdir(parents=True, exist_ok=True)
    with event_path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(event, ensure_ascii=False) + "\n")
    return {"status": "committed", "old_task_id": old_task_id, "new_task_id": new_task_id, "event": event}


def _commit_voice_replacement_after_asset_production(asset_task_id: str) -> bool:
    """仅在完整素材任务成功后提交音色替代，避免时间轴/数字人半成品成为 active。

    编导逐镜脚本成功只代表 TTS、STT、字幕和镜头时间线已经重建；音色替换
    仍需等素材层所有分支完成。这个门禁不主动触发付费任务，失败或部分成功
    时保留旧 active 版本，等待用户补跑后再次检查。
    """

    asset_task = _task_snapshot(asset_task_id)
    if not isinstance(asset_task, Mapping) or asset_task.get("task_type") != "asset_production":
        return False
    if str(asset_task.get("state") or "") != "succeeded":
        return False
    source_story_task_id = str(asset_task.get("source_story_task_id") or "").strip()
    if not source_story_task_id:
        return False
    replacement = _task_snapshot(source_story_task_id)
    if not isinstance(replacement, Mapping) or not str(replacement.get("replacement_of_task_id") or "").strip():
        return False

    result = asset_task.get("result") if isinstance(asset_task.get("result"), Mapping) else {}
    categories = result.get("categories") if isinstance(result, Mapping) else {}
    if not isinstance(categories, Mapping):
        return False
    terminal_bad = {
        str(category)
        for category, value in categories.items()
        if isinstance(value, Mapping)
        and str(value.get("state") or "") in {"failed", "blocked", "interrupted", "running", "queued"}
    }
    if terminal_bad:
        return False

    # 数字人补全任务只允许在其 base full 任务已经成功时提交，避免把
    # 单独补跑的局部结果误当成完整替代版本。
    if str(asset_task.get("mode") or "full") == "digital_only":
        base_asset_task_id = str(asset_task.get("base_asset_task_id") or "").strip()
        base_asset = _task_snapshot(base_asset_task_id) if base_asset_task_id else None
        if (
            not isinstance(base_asset, Mapping)
            or str(base_asset.get("state") or "") != "succeeded"
            or str(base_asset.get("source_story_task_id") or "") != source_story_task_id
        ):
            return False

    commit_result = _commit_voice_replacement(source_story_task_id)
    if str(commit_result.get("status") or "") not in {"committed", "already_committed"}:
        # 新任务虽然素材分支成功，但缺少最终指纹或事务提交失败时，不能
        # 把素材任务伪装成已切换 active；旧版本继续保持可用。
        return False
    _set_task(
        asset_task_id,
        result={
            "voice_change_commit": {
                "status": "committed",
                "source_story_task_id": source_story_task_id,
                "committed_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            }
        },
    )
    return True


def _mark_voice_replacement_failed_preserved(
    replacement_task_id: str, error: str
) -> dict[str, Any] | None:
    """候选任务失败时恢复旧 active，并留下可审计失败事件。"""

    replacement = _task_snapshot(replacement_task_id)
    if not isinstance(replacement, Mapping):
        return None
    old_task_id = str(replacement.get("replacement_of_task_id") or "").strip()
    if not old_task_id:
        return None
    old_task = _task_snapshot(old_task_id)
    if not isinstance(old_task, Mapping):
        return None
    old_result = old_task.get("result") if isinstance(old_task.get("result"), Mapping) else {}
    old_fingerprint = str(
        _task_tts_fingerprint(old_task)
        or old_result.get("active_version")
        or ""
    ).strip()
    invalidation = dict(old_result.get("invalidation") or {}) if isinstance(old_result, Mapping) else {}
    scope = list(invalidation.get("scope") or invalidation_scope("tts_config_changed", group_id=old_task_id)["scope"])
    requested_fingerprint = str(
        invalidation.get("new_fingerprint")
        or invalidation.get("requested_fingerprint")
        or ""
    ).strip()
    detail = str(error or "候选音色重建失败").replace("\r", " ").replace("\n", " ").strip()[:500]
    event = {
        "event_type": "tts_config_changed",
        "status": "failed_preserved",
        "reason": "新音色重建失败，旧 active 版本保持可用",
        "old_task_id": old_task_id,
        "new_task_id": replacement_task_id,
        "old_fingerprint": old_fingerprint,
        "new_fingerprint": requested_fingerprint or _task_tts_fingerprint(replacement),
        "affected": scope,
        "error": detail,
        "created_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
    }
    dependent_ids = _mark_story_dependents_invalidation(
        old_task_id,
        status="failed_preserved",
        replacement_task_id=replacement_task_id,
        scope=scope,
        old_fingerprint=old_fingerprint,
        new_fingerprint=event["new_fingerprint"],
    )
    event["affected_task_ids"] = dependent_ids
    updated_invalidation = dict(invalidation)
    updated_invalidation.update(event)
    updated_invalidation["status"] = "failed_preserved"
    _set_task(
        old_task_id,
        result={
            "invalidation": updated_invalidation,
            "active_version": old_fingerprint,
        },
        _remove_result_keys=["pending_version", "voice_change_pending"],
    )
    _set_task(
        replacement_task_id,
        result={
            "voice_change": {
                "status": "failed_preserved",
                "replaces_task_id": old_task_id,
                "error": detail,
            },
            "active_version": old_fingerprint,
            "version_status": "discarded",
        },
    )
    event_path = DIRECTOR_REVIEW_DIR / old_task_id / "events.jsonl"
    event_path.parent.mkdir(parents=True, exist_ok=True)
    with event_path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(event, ensure_ascii=False) + "\n")
    return event


def _mark_voice_replacement_waiting_for_assets(story_task_id: str) -> None:
    """记录逐镜脚本已完成，但替代版本仍等待素材层完成。"""

    story_task = _task_snapshot(story_task_id)
    if not isinstance(story_task, Mapping):
        return
    old_task_id = str(story_task.get("replacement_of_task_id") or "").strip()
    if not old_task_id:
        return
    old_task = _task_snapshot(old_task_id)
    old_result = old_task.get("result") if isinstance(old_task, Mapping) and isinstance(old_task.get("result"), Mapping) else {}
    _set_task(
        story_task_id,
        result={
            "voice_change": {
                "status": "pending_downstream_assets",
                "replaces_task_id": old_task_id,
                "required_stage": "asset_production_completed",
            },
            "active_version": str(old_result.get("active_version") or _task_tts_fingerprint(old_task) or ""),
            "pending_version": story_task_id,
        },
    )


def _create_director_story_task(payload: dict) -> dict:
    rewrite_id = str(payload.get("rewrite_id") or "").strip()
    aspect_ratio = str(payload.get("aspect_ratio") or "").strip()
    director_package = _resolve_director_package(payload.get("director_package"))
    director_dynamic_params = _normalize_director_dynamic_params(
        director_package, payload.get("director_dynamic_params"),
    )
    voice_resolution = _resolve_story_voice(str(payload.get("voice_key") or "").strip())
    protagonist_profile = _normalize_protagonist_profile(payload.get("protagonist_profile"))
    if not rewrite_id:
        raise ValueError("缺失已审核文案编号")
    if aspect_ratio not in SUPPORTED_ASPECT_RATIOS:
        raise ValueError("画幅仅支持 9:16、16:9、1:1、3:2、2:3")
    _get_approved_rewrite(rewrite_id)

    # 页面切换、刷新或重复点击不能创建第二条编导任务线。只复用仍在执行的
    # 同一文案任务；已经完成的任务仍允许用户明确点击“重新生成”时重新运行。
    with DIRECTOR_TASK_CREATION_LOCK:
        existing = _latest_director_story_task_for_rewrite(
            rewrite_id, states={"queued", "running"}
        )
        if existing is not None:
            return existing

        task_id = uuid.uuid4().hex
        now = int(time.time())
        with STYLE_TASKS_LOCK:
            STYLE_TASKS[task_id] = {
                "task_id": task_id,
                "task_type": "director_story_review",
                "source_rewrite_id": rewrite_id,
                "input": {
                    "rewrite_id": rewrite_id,
                    "aspect_ratio": aspect_ratio,
                    "director_package": director_package["package_id"],
                    "director_dynamic_params": director_dynamic_params,
                    "voice_key": voice_resolution["voice_key"],
                    "protagonist_profile": protagonist_profile,
                },
                "director_package": director_package["package_id"],
                "director_dynamic_params": director_dynamic_params,
                "voice_resolution": voice_resolution,
                "protagonist_profile": protagonist_profile,
                "replacement_of_task_id": str(payload.get("replacement_of_task_id") or "").strip(),
                "state": "queued",
                "stage": "queued",
                "progress": 0,
                "message": "真实编导任务正在排队",
                "created_at": now,
                "updated_at": now,
            }
            task = dict(STYLE_TASKS[task_id])
        # 编导任务同样先写入可召回快照，再启动线程。
        try:
            _persist_task_required(task)
        except TaskPersistenceError:
            with STYLE_TASKS_LOCK:
                STYLE_TASKS.pop(task_id, None)
            raise
    threading.Thread(
        target=_run_director_story_task,
        args=(task_id, {
            "rewrite_id": rewrite_id,
            "aspect_ratio": aspect_ratio,
            "director_package": director_package["package_id"],
            "director_dynamic_params": director_dynamic_params,
            "voice_key": voice_resolution["voice_key"],
            "protagonist_profile": protagonist_profile,
        }),
        daemon=True,
    ).start()
    return _task_snapshot(task_id) or {"task_id": task_id}


def _stop_director_story_task(task_id: str) -> dict:
    """Stop a queued/running story-review task before it reaches a later paid stage."""
    task = _task_snapshot(task_id)
    if not task or task.get("task_type") != "director_story_review":
        raise ValueError("未找到指定的v2 编导任务")
    state = str(task.get("state") or "")
    if state == "interrupted":
        return task
    if state not in {"queued", "running"}:
        raise ValueError("v2 编导任务已经结束，不能再停止")
    progress = max(0, min(100, int(task.get("progress") or 0)))
    _set_task(
        task_id,
        state="interrupted",
        stage="user_stopped",
        progress=progress,
        message="已手动停止编导审核任务；当前外部请求返回后不会继续调用后续步骤。",
    )
    return _task_snapshot(task_id) or task


def _approve_director_story_task(task_id: str) -> dict:
    """Persist the user approval before allowing the material layer to open."""
    task = _task_snapshot(task_id)
    if not task or task.get("task_type") != "director_story_review":
        raise ValueError("未找到指定的v2 编导任务")
    if task.get("state") != "succeeded":
        raise ValueError("故事任务尚未成功完成，不能确认")
    result = task.get("result")
    if not isinstance(result, dict) or not isinstance(result.get("story_draft", {}).get("story"), dict):
        raise ValueError("故事审核稿不完整，不能确认")
    result = dict(result)
    result["review_status"] = "APPROVED"
    result["approved_at"] = int(time.time())
    _set_task(
        task_id,
        stage="story_approved",
        message="故事已确认，素材生产层已解锁。",
        result=result,
    )
    review_file = DIRECTOR_REVIEW_DIR / task_id / "story_review.json"
    try:
        review_file.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    except OSError:
        TASK_LOGGER.warning("director story approval persistence unavailable for %s", task_id)
    return result


def _shot_duration_us(shot: Mapping[str, object]) -> int | None:
    timeline = shot.get("timeline")
    if not isinstance(timeline, Mapping):
        return None
    start = timeline.get("start_us", timeline.get("start"))
    end = timeline.get("end_us", timeline.get("end"))
    if isinstance(start, bool) or isinstance(end, bool) or not isinstance(start, int) or not isinstance(end, int):
        return None
    return end - start if end > start else None


def _opening_title_from_story_payload(
    payload: Mapping[str, object] | None, *, fallback_source: object = ""
) -> str:
    """读取编导生成的开场标题；兼容旧稿并保证下游始终有悬念标题。"""

    if isinstance(payload, Mapping):
        candidates: list[object] = [payload.get("opening_title")]
        story = payload.get("story")
        if isinstance(story, Mapping):
            candidates.append(story.get("opening_title"))
        story_draft = payload.get("story_draft")
        if isinstance(story_draft, Mapping):
            candidates.append(story_draft.get("opening_title"))
            draft_story = story_draft.get("story")
            if isinstance(draft_story, Mapping):
                candidates.append(draft_story.get("opening_title"))
        lock = payload.get("director_lock")
        if isinstance(lock, Mapping):
            cinematic_story = lock.get("cinematic_story")
            if isinstance(cinematic_story, Mapping):
                candidates.append(cinematic_story.get("opening_title"))
        for value in candidates:
            title = str(value or "").strip()
            if title:
                return " ".join(title.split())[:12]
    return fallback_opening_title(fallback_source)[:12]


def _segment_timelines_for_transition(
    director_lock: Mapping[str, object], *, director_package: str
) -> list[dict[str, object]]:
    """读取 v2/v3 一级分段窗口，供旁白/BGM范围使用；不作为镜头转场依据。"""

    if str(director_package or "").strip().lower() not in {"v2", "v3"}:
        return []
    groups = director_lock.get("groups")
    if not isinstance(groups, list):
        raise RuntimeError("v2 编导锁定结果缺少 groups，无法输出分段时间数据")
    timelines: list[dict[str, object]] = []
    for index, raw_group in enumerate(groups):
        if not isinstance(raw_group, Mapping):
            raise RuntimeError(f"v2 编导锁定分组 {index} 不是对象")
        group_id = str(raw_group.get("group_id") or "").strip()
        segment_text = str(raw_group.get("segment_text") or "")
        timeline = raw_group.get("timeline")
        if not group_id or not segment_text or not isinstance(timeline, Mapping):
            raise RuntimeError(f"v2 编导锁定分组 {index} 缺少分段或时间线")
        start = timeline.get("start_us", timeline.get("start"))
        end = timeline.get("end_us", timeline.get("end"))
        if (
            isinstance(start, bool)
            or not isinstance(start, int)
            or isinstance(end, bool)
            or not isinstance(end, int)
            or end <= start
        ):
            raise RuntimeError(f"v2 {group_id} 分段时间线必须是有效的整数微秒窗口")
        timelines.append({
            "segment_index": index,
            "segment_id": group_id,
            "segment_text": segment_text,
            "start_us": start,
            "end_us": end,
            "duration_us": end - start,
        })
    return timelines


def _secondary_segment_timelines_for_transition(
    director_lock: Mapping[str, object], *, director_package: str
) -> list[dict[str, object]]:
    """读取 v2 细化后的二级镜头窗口，供转场按微秒边界定位。"""

    if str(director_package or "").strip().lower() not in {"v2", "v3"}:
        return []
    shots = director_lock.get("shots")
    if not isinstance(shots, list):
        raise RuntimeError("v2 编导锁定结果缺少 shots，无法输出二级分段时间数据")
    timelines: list[dict[str, object]] = []
    for index, raw_shot in enumerate(shots):
        if not isinstance(raw_shot, Mapping):
            raise RuntimeError(f"v2 编导锁定镜头 {index} 不是对象")
        shot_id = str(raw_shot.get("shot_id") or "").strip()
        group_id = str(raw_shot.get("group_id") or "").strip()
        production_spec = raw_shot.get("production_spec")
        production_spec = production_spec if isinstance(production_spec, Mapping) else {}
        segment_text = str(
            raw_shot.get("narration_text")
            or raw_shot.get("source_text")
            or production_spec.get("narration_text")
            or ""
        ).strip()
        timeline = raw_shot.get("timeline")
        if not shot_id or not group_id or not segment_text or not isinstance(timeline, Mapping):
            raise RuntimeError(f"v2 编导锁定镜头 {index} 缺少二级分段或时间线")
        start = timeline.get("start_us", timeline.get("start"))
        end = timeline.get("end_us", timeline.get("end"))
        if (
            isinstance(start, bool)
            or not isinstance(start, int)
            or isinstance(end, bool)
            or not isinstance(end, int)
            or end <= start
        ):
            raise RuntimeError(f"v2 {shot_id} 二级分段时间线必须是有效的整数微秒窗口")
        timelines.append({
            "secondary_segment_index": index,
            "shot_index": raw_shot.get("shot_index", index),
            "shot_id": shot_id,
            "group_id": group_id,
            "segment_text": segment_text,
            "start_us": start,
            "end_us": end,
            "duration_us": end - start,
        })
    return timelines


def _transition_points_from_secondary_timelines(
    timelines: list[Mapping[str, object]],
) -> list[dict[str, object]]:
    """显式区分二级转场和三级接缝；三级默认不加转场。"""

    points: list[dict[str, object]] = []
    for index, (current, following) in enumerate(zip(timelines, timelines[1:], strict=False)):
        points.append({
            "transition_index": index,
            "at_us": current["end_us"],
            "from_shot_id": current["shot_id"],
            "to_shot_id": following["shot_id"],
            "from_group_id": current["group_id"],
            "to_group_id": following["group_id"],
            "classification_level": (
                "level_3"
                if current["group_id"] == following["group_id"]
                else "level_2"
            ),
            "default_enabled": current["group_id"] != following["group_id"],
        })
    return points


def _media_routes_by_shot(director_result: dict, material_plan: dict) -> dict[str, dict]:
    """读取当前编导锁定的媒体路由；旧稿不得绕过锁定数据。"""

    lock = director_result.get("director_lock")
    shots = lock.get("shots") if isinstance(lock, dict) else None
    if not isinstance(shots, list) or not all(isinstance(item, dict) for item in shots):
        raise RuntimeError("媒体路由缺少 DirectorLockedManifest.shots")
    route_lock = material_plan.get("media_route_lock")
    if route_lock is None:
        raise RuntimeError("素材生产缺少 DIRECTOR_MEDIA_LOCKED 媒体路由，禁止使用旧版兜底；请重新生成当前逐镜脚本")
    if not isinstance(route_lock, dict) or route_lock.get("status") != "DIRECTOR_MEDIA_LOCKED":
        raise RuntimeError("素材生产必须使用已锁定的逐镜媒体路由")
    is_v3 = route_lock.get("schema_version") == "director-media-route-lock-v3"
    allowed_media_types = {"digital_human_video", "aigc_video", "static_image"}
    if is_v3:
        allowed_media_types.update({"explanation", "mixed_explanation"})
    routes = route_lock.get("routes")
    if not isinstance(routes, list) or len(routes) != len(shots):
        raise RuntimeError("逐镜媒体路由数量与冻结镜头数量不一致")
    route_by_shot: dict[str, dict] = {}
    for index, (shot, route) in enumerate(zip(shots, routes, strict=True)):
        if not isinstance(route, dict) or route.get("shot_id") != shot.get("shot_id"):
            raise RuntimeError("逐镜媒体路由顺序或 shot_id 与冻结镜头不一致")
        if route.get("media_type") not in allowed_media_types:
            raise RuntimeError("逐镜媒体路由包含未知类型")
        if index == 0 and route.get("media_type") != "aigc_video":
            raise RuntimeError(f"{shot.get('shot_id')} 是全片第一个镜头，必须使用 AIGC 视频")
        if is_v3:
            shot_class = str(route.get("shot_class") or "")
            if shot_class not in {"aigc", "image", "digital_human", "explanation", "mixed_explanation"}:
                raise RuntimeError("v3 逐镜媒体路由缺少合法 shot_class")
            render_plan = route.get("render_plan") if isinstance(route.get("render_plan"), Mapping) else {}
            if shot_class in {"explanation", "mixed_explanation"}:
                if not render_plan.get("template_id"):
                    raise RuntimeError("v3 说明镜头缺少已锁定的关系模板")
                if not render_plan.get("template_version"):
                    raise RuntimeError("v3 说明镜头缺少模板版本，必须由编导路由锁定")
                if not render_plan.get("relation_type"):
                    raise RuntimeError("v3 说明镜头缺少关系类型，必须由编导路由锁定")
                relation_objects = render_plan.get("relation_objects")
                if not isinstance(relation_objects, list) or len(relation_objects) < 2:
                    raise RuntimeError("v3 说明镜头缺少不少于两个关系对象，无法生成说明模板")
            if shot_class == "mixed_explanation" and not render_plan.get("overlay_tracks"):
                raise RuntimeError("v3 混合说明镜头缺少数字人画中画轨道")
        else:
            production = shot.get("production_spec") if isinstance(shot.get("production_spec"), Mapping) else {}
            pacing = production.get("media_pacing") if isinstance(production, Mapping) else {}
            force_aigc = isinstance(pacing, Mapping) and bool(pacing.get("force_aigc"))
            if (
                index != 0
                and (_shot_duration_us(shot) or 0) < 3_000_000
                and route.get("media_type") != "static_image"
            ):
                raise RuntimeError(f"{shot.get('shot_id')} 低于 3 秒，旧媒体路由仍为视频；必须重建为静态图片后才能生产")
        route_by_shot[str(route["shot_id"])] = route
    return route_by_shot


def _group_video_prompt_inputs(director_result: dict, material_plan: dict) -> dict:
    """只将 AIGC 视频镜头按原索引送入 195692，图片和数字人必须跳过。"""
    groups = director_result["shot_refinement"]["output"]["Code_list"]
    seeds = material_plan.get("motion_seed")
    refs = material_plan.get("ref_image")
    durations = material_plan.get("int_duration")
    governance = material_plan.get("director_governance")
    contexts = governance.get("shot_contexts") if isinstance(governance, dict) else None
    lock = director_result.get("director_lock")
    locked_shots = lock.get("shots") if isinstance(lock, dict) else None
    if not isinstance(locked_shots, list):
        raise RuntimeError("逐镜视频脚本缺少当前 DirectorLockedManifest.shots，禁止使用旧版镜头占位")
    if not all(isinstance(value, list) for value in (groups, seeds, refs, durations, contexts, locked_shots)):
        raise RuntimeError("逐镜视频脚本缺少 116616 的动态种子、参考图或时长")
    if not (len(seeds) == len(refs) == len(durations) == len(contexts) == len(locked_shots)):
        raise RuntimeError("逐镜视频脚本的素材数组与冻结镜头数量不一致")
    routes_by_shot = _media_routes_by_shot(director_result, material_plan)
    items: list[dict] = []
    grouped_seeds: list[dict] = []
    grouped_refs: list[list[str]] = []
    grouped_durations: list[dict] = []
    shot_ids: list[str] = []
    skipped_shot_ids: list[str] = []
    cursor = 0
    for group in groups:
        shots = group.get("shots") if isinstance(group, dict) else None
        if not isinstance(shots, list) or not shots:
            raise RuntimeError("镜头精细化输出存在空镜头组")
        count = len(shots)
        group_seeds = seeds[cursor:cursor + count]
        group_refs = refs[cursor:cursor + count]
        group_durations = durations[cursor:cursor + count]
        group_contexts = contexts[cursor:cursor + count]
        if not (len(group_seeds) == len(group_refs) == len(group_durations) == len(group_contexts) == count):
            raise RuntimeError("116616 输出与镜头精细化的小镜头数量不一致")
        # 原 Coze 节点以大分段作 batch，但当前模型会把同组的多个分镜错误地
        # 压成一条 plan。为保证“每个冻结小镜头恰有一条运镜计划”，这里仍按原
        # 顺序进入 195692，只将每个小镜头拆成一个 batch item。
        for shot, seed, value, duration, context in zip(shots, group_seeds, group_refs, group_durations, group_contexts, strict=True):
            locked_shot = locked_shots[cursor]
            if not isinstance(locked_shot, dict):
                raise RuntimeError("冻结镜头记录必须是对象")
            shot_id = str(locked_shot.get("shot_id") or "")
            route = routes_by_shot.get(shot_id)
            if not shot_id or route is None:
                raise RuntimeError("逐镜视频提示词缺少媒体路由")
            media_type = route["media_type"]
            if media_type != "aigc_video":
                skipped_shot_ids.append(shot_id)
                cursor += 1
                continue
            source = value.get("ref_image", []) if isinstance(value, dict) else []
            if not isinstance(source, list) or not all(isinstance(item, str) for item in source):
                raise RuntimeError("116616 的参考图字段不符合 195692 批处理契约")
            visual = context.get("visual_direction") if isinstance(context, dict) else None
            if not isinstance(visual, dict) or not visual.get("camera_motion"):
                raise RuntimeError("视觉导演没有给小镜头提供统筹运镜")
            items.append({
                "group_id": group.get("group_id", ""),
                "shots": [shot],
                "director_camera_language": {
                    "camera_intent": context.get("camera_intent", ""),
                    "camera_angle": visual.get("camera_angle", ""),
                    "shot_size": visual.get("shot_size", ""),
                    "composition": visual.get("composition", ""),
                    "recommended_camera_motion": visual["camera_motion"],
                },
            })
            grouped_seeds.append({"motion_seed": [str(seed)]})
            # 本步骤尚未生成首帧，因此允许空数组；195692 仍据镜头上下文生成运镜方案。
            grouped_refs.append(source)
            grouped_durations.append({"clip_duration": [int(duration)]})
            shot_ids.append(shot_id)
            cursor += 1
    if cursor != len(seeds):
        raise RuntimeError("116616 存在未归属的动态种子，拒绝生成无序逐镜脚本")
    return {
        "items": items, "motion_seed": grouped_seeds, "ref_image": grouped_refs,
        "clip_duration": grouped_durations, "shot_ids": shot_ids,
        "skipped_shot_ids": skipped_shot_ids,
    }


VIDEO_PROMPT_PARALLEL_WORKERS = 4


def _resolve_video_prompt_workers(value: int | None = None) -> int:
    if value is not None:
        if isinstance(value, bool) or not isinstance(value, int) or value < 1:
            raise ValueError("视频提示词并行 worker 数必须是正整数")
        return value
    raw = os.environ.get("DIRECTOR_VIDEO_PROMPT_PARALLEL_WORKERS", "").strip()
    if raw:
        try:
            parsed = int(raw)
        except ValueError:
            parsed = VIDEO_PROMPT_PARALLEL_WORKERS
        if parsed > 0:
            return parsed
    return VIDEO_PROMPT_PARALLEL_WORKERS


def _run_live_video_prompt_script(
    director_result: dict,
    material_plan: dict,
    auth_document: Path,
    progress_reporter: Callable[[int, int, str], None] | None = None,
    parallel_workers: int | None = None,
) -> dict:
    """真实执行 195692 图生视频提示词导演，仅生成可审核的逐镜动作/运镜方案。"""
    model = DualSeed21TurboTextTransport(auth_document.resolve(), max_tokens=5000, timeout=180, json_mode=True)
    system_base = (
        "你是图生视频提示词导演。必须严格按用户消息中的镜头顺序输出合法 JSON，"
        "格式为 {\"plans\":[{\"shot_index\":整数,\"duration\":整数,\"stages\":[{\"action\":\"\",\"camera_motion\":\"\",\"time_range\":\"\"}]}],"
        "\"reasoning_content\":\"\",\"visual_lock\":\"\"}。"
        "每个镜头至少一个 stage；action 是可见动作，camera_motion 是明确运镜（固定/推近/拉远/横移/跟拍/摇镜等），"
        "time_range 覆盖该镜头时长。不得改写镜头数量、顺序或时长；禁止可读文字、UI、品牌和对白。"
        "用户消息 items.director_camera_language 是编导层已锁定的镜头语言；camera_motion 必须采用其中 recommended_camera_motion 对应的运镜，可加速度或节奏修饰，但不得改成另一类运镜。"
    )

    def transport(request: VideoPromptDirectorRequest) -> dict:
        expected = len(request.clip_duration["clip_duration"])
        system = system_base + f" 本次 clip_duration 共 {expected} 项，所以 plans 必须恰好输出 {expected} 项；每项 shot_index 依次从 1 到 {expected}。"
        raw = model(system, render_user_prompt(request))
        try:
            payload = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise RuntimeError("195692 方舟响应不是合法 JSON") from exc
        if not isinstance(payload, dict):
            raise RuntimeError("195692 方舟响应根节点不是对象")
        return payload

    params = _group_video_prompt_inputs(director_result, material_plan)
    started_at = time.perf_counter()
    outputs: list[dict] = []
    # 每个冻结小镜头本来就是独立 batch item。逐镜重试可以保留前面已通过的
    # 结果，避免第 19 镜失败时把前 18 镜再次付费生成。
    total = len(params["items"])
    if not total:
        return {"plan_out_list": [], "shot_ids": params["shot_ids"]}
    worker_count = min(_resolve_video_prompt_workers(parallel_workers), total)

    def run_one(index: int) -> tuple[int, dict]:
        single = {
            key: [params[key][index]]
            for key in ("items", "motion_seed", "ref_image", "clip_duration")
        }
        last_error: Exception | None = None
        for _attempt in range(2):
            try:
                result = run_video_prompt_batch(single, transport=transport)
                groups = result.get("plan_out_list")
                if not isinstance(groups, list) or len(groups) != 1:
                    raise VideoPromptDirectorValidationError("单镜运镜计划数量不是 1")
                return index, groups[0]
            except (VideoPromptDirectorValidationError, RuntimeError) as exc:
                last_error = exc
        raise RuntimeError(
            f"195692 第 {index + 1} 镜连续两次未返回完整运镜计划：{last_error}"
        ) from last_error

    indexed_outputs: dict[int, dict] = {}
    errors: list[tuple[int, Exception]] = []
    with ThreadPoolExecutor(max_workers=worker_count, thread_name_prefix="video-prompt") as executor:
        futures = {
            executor.submit(run_one, index): index
            for index in range(total)
        }
        for future in as_completed(futures):
            index = futures[future]
            try:
                result_index, output = future.result()
                indexed_outputs[result_index] = output
                if progress_reporter is not None:
                    progress_reporter(
                        len(indexed_outputs), total, str(params["shot_ids"][result_index])
                    )
            except Exception as error:
                errors.append((index, error))
    if errors:
        _, error = min(errors, key=lambda item: item[0])
        raise error

    outputs = [indexed_outputs[index] for index in range(total)]
    return {
        "plan_out_list": outputs,
        "shot_ids": params["shot_ids"],
        "performance": {
            "video_prompt_parallel_workers": worker_count,
            "video_prompt_completed": total,
            "video_prompt_elapsed_ms": round((time.perf_counter() - started_at) * 1000, 1),
        },
    }


def _build_shot_video_script(director_result: dict, material_plan: dict, video_plan: dict) -> list[dict]:
    """将冻结时间线、媒体路由和逐镜导演结果收口为素材层输入。"""
    lock = director_result.get("director_lock")
    governance = material_plan.get("director_governance")
    if not isinstance(lock, dict) or not isinstance(governance, dict):
        raise RuntimeError("逐镜脚本缺少 DirectorLockedManifest 或视觉导演治理结果")
    shots = lock.get("shots")
    contexts = governance.get("shot_contexts")
    prompts = material_plan.get("prompt")
    seeds = material_plan.get("motion_seed")
    plan_groups = video_plan.get("plan_out_list")
    if not all(isinstance(value, list) for value in (shots, contexts, prompts, seeds, plan_groups)):
        raise RuntimeError("逐镜脚本输入结构不完整")
    if not (len(shots) == len(contexts) == len(prompts) == len(seeds)):
        raise RuntimeError("逐镜脚本数组数量不一致，拒绝产生错位素材任务")
    routes_by_shot = _media_routes_by_shot(director_result, material_plan)
    video_shot_ids = video_plan.get("shot_ids")
    if not isinstance(video_shot_ids, list):
        # 保持已落盘旧审核稿可读；新版本必须提供 shot_ids，避免索引错位。
        video_shot_ids = [shot.get("shot_id") for shot in shots if routes_by_shot.get(str(shot.get("shot_id")), {}).get("media_type") == "aigc_video"]
    plan_by_shot: dict[str, dict] = {}
    if len(plan_groups) == len(video_shot_ids):
        for shot_id, group in zip(video_shot_ids, plan_groups, strict=True):
            plans = group.get("plans") if isinstance(group, dict) else None
            if not isinstance(shot_id, str) or not isinstance(plans, list) or len(plans) != 1 or not isinstance(plans[0], dict):
                raise RuntimeError("AIGC 视频镜头必须且只能有一条运镜计划")
            plan_by_shot[shot_id] = plans[0]
    else:
        fallback_plans = [plan for group in plan_groups if isinstance(group, dict) for plan in group.get("plans", [])]
        if len(fallback_plans) != len(video_shot_ids) or not all(isinstance(plan, dict) for plan in fallback_plans):
            raise RuntimeError("AIGC 视频计划数量与媒体路由不一致")
        plan_by_shot = dict(zip(video_shot_ids, fallback_plans, strict=True))
    result: list[dict] = []
    for index, (shot, context, prompt, seed) in enumerate(zip(shots, contexts, prompts, seeds, strict=True), start=1):
        if not isinstance(shot, dict) or not isinstance(context, dict):
            raise RuntimeError("逐镜脚本存在非对象镜头记录")
        if shot.get("shot_id") != context.get("shot_id"):
            raise RuntimeError("视觉导演镜头 ID 与冻结镜头不一致")
        timeline = shot.get("timeline", {})
        start_us = int(timeline.get("start_us", 0))
        end_us = int(timeline.get("end_us", 0))
        if end_us <= start_us:
            raise RuntimeError("冻结时间线包含非正时长镜头")
        production_spec = shot.get("production_spec", {})
        narration = production_spec.get("narration_text") if isinstance(production_spec, dict) else None
        if not isinstance(narration, str) or not narration.strip():
            raise RuntimeError("冻结镜头缺少剪映 STT 旁白，拒绝把画面语义锚点当作旁白交付")
        route = routes_by_shot.get(str(shot.get("shot_id")))
        if route is None:
            raise RuntimeError("冻结镜头缺少媒体路由")
        media_type = route["media_type"]
        visual = context.get("visual_direction", {}) if isinstance(context.get("visual_direction"), dict) else {}
        plan = plan_by_shot.get(str(shot.get("shot_id")))
        stages = plan.get("stages") if isinstance(plan, dict) and isinstance(plan.get("stages"), list) else []
        if media_type == "aigc_video" and not stages:
            raise RuntimeError("AIGC 视频镜头未返回运镜阶段")
        skip = route.get("skip") if isinstance(route.get("skip"), dict) else {}
        reference_records = material_plan.get("ref_image")
        reference_item = (
            reference_records[index - 1]
            if isinstance(reference_records, list) and index <= len(reference_records)
            else {}
        )
        reference_urls = reference_item.get("ref_image", []) if isinstance(reference_item, Mapping) else []
        if not isinstance(reference_urls, list):
            reference_urls = []
        reference_urls = [str(value).strip() for value in reference_urls if str(value).strip()]
        first_frame_reference = {
            "used": bool(reference_urls) and not bool(skip.get("skip_first_frame")),
            "reference_count": len(reference_urls) if not bool(skip.get("skip_first_frame")) else 0,
            # URL 只属于内部素材清单；审核页只显示来源与用途，避免暴露临时素材地址。
            "source": "素材层参考图" if reference_urls else "未引用外部参考图",
            "purpose": "固定角色、画风或场景连续性" if reference_urls else "当前仅按编导层画面描述生成",
            "urls": reference_urls if not bool(skip.get("skip_first_frame")) else [],
        }
        result.append({
            "shot_no": index,
            "shot_id": shot["shot_id"],
            "group_id": shot["group_id"],
            "start_us": start_us,
            "end_us": end_us,
            "start_s": round(start_us / 1_000_000, 3),
            "end_s": round(end_us / 1_000_000, 3),
            "duration_s": round((end_us - start_us) / 1_000_000, 3),
            # narration_text 来自剪映 STT 冻结的旁白坑位；source_text 只是
            # 给素材导演使用的画面语义锚点，绝不能伪装成会被朗读的字幕。
            "narration": narration,
            "semantic_anchor": shot.get("source_text", ""),
            "slot_policy": "semantic_and_capcut_stt_timeline_locked",
            "shot_class": route.get("shot_class", ""),
            "media_type": media_type,
            "media_label": route.get("media_label", media_type),
            "media_reason": route.get("media_reason", ""),
            "required_assets": route.get("required_assets", []),
            "editing_track": route.get("editing_track", "main_visual"),
            "render_plan": dict(route.get("render_plan") or {}) if isinstance(route.get("render_plan"), Mapping) else {},
            "requires_digital_human": any(
                isinstance(asset, Mapping) and asset.get("asset") == "digital_human_video"
                for asset in (route.get("required_assets") or [])
            ),
            "shot_design_type": context.get("shot_design_type", ""),
            "transition_role": context.get("transition_role", "无"),
            "viewpoint": visual.get("camera_angle", ""),
            "shot_size": visual.get("shot_size", ""),
            "camera_motion": [
                {"time_range": stage.get("time_range", ""), "action": stage.get("action", ""), "camera_motion": stage.get("camera_motion", "")}
                for stage in stages
            ],
            "shot_content": context.get("blocking", ""),
            "continuity_in": context.get("continuity_in", ""),
            "continuity_out": context.get("continuity_out", ""),
            "first_frame_prompt": None if skip.get("skip_first_frame") else prompt,
            "image2_prompt": None if skip.get("skip_first_frame") else _compact_image2_prompt({
                "first_frame_prompt": prompt,
                "shot_size": visual.get("shot_size", ""),
                "viewpoint": visual.get("camera_angle", ""),
            }),
            "first_frame_reference": first_frame_reference,
            "motion_seed": seed if media_type == "aigc_video" else None,
        })
    return result


def _shot_requires_digital_human(shot: Mapping[str, object]) -> bool:
    """混合说明的画中画也必须进入数字人素材分支。"""

    return (
        str(shot.get("media_type") or "") == "digital_human_video"
        or bool(shot.get("requires_digital_human"))
        or str(shot.get("shot_class") or "") == "mixed_explanation"
    )


def _shot_is_explanation(shot: Mapping[str, object]) -> bool:
    return str(shot.get("shot_class") or "") in {"explanation", "mixed_explanation"}


def _shot_is_grid_image(shot: Mapping[str, object]) -> bool:
    """只有普通画面进入首帧宫格；数字人和说明性镜头走各自分支。"""
    return bool(shot.get("first_frame_prompt")) and not _shot_requires_digital_human(shot) and not _shot_is_explanation(shot)


def _asset_categories(shots: list[dict]) -> dict[str, dict]:
    """按已冻结路由创建真实执行分类，不能把跳过伪装成已完成。"""
    image_shots = [item for item in shots if _shot_is_grid_image(item)]
    video_shots = [item for item in shots if item.get("media_type") == "aigc_video"]
    digital_shots = [item for item in shots if _shot_requires_digital_human(item)]
    explanation_shots = [
        item for item in shots
        if str(item.get("shot_class") or "") in {"explanation", "mixed_explanation"}
    ]
    return {
        "first_frame_images": {"label": "首帧图片", "total": len(image_shots), "submitted": 0, "completed": 0, "state": "queued", "message": "等待创建 Image 2 首帧任务"},
        "aigc_videos": {"label": "AIGC 视频", "total": len(video_shots), "completed": 0, "state": "queued", "message": "等待首帧完成后创建 Seedance 任务"},
        "bgm": {"label": "背景音乐", "total": 1, "completed": 0, "state": "queued", "message": "等待读取已锁定的音乐任务"},
        "digital_humans": {"label": "数字人", "total": len(digital_shots), "completed": 0, "state": "queued", "message": "等待读取数字人形象图与对应 TTS"},
        "explanation_videos": {"label": "说明镜头视频", "total": len(explanation_shots), "completed": 0, "state": "queued", "message": "等待首帧风格锁定后调用 Remotion"},
    }


def _asset_retry_targets(result: Mapping[str, object], shots: list[dict]) -> dict[str, set[str] | bool]:
    """只找出失败资产，供“仅重新生成失败素材”使用。

    这里故意以已落盘的逐项记录为准，而不是以任务总状态推断成功与否。
    这样重试任务可以继承原任务的首帧、视频、BGM 和数字人结果，避免把
    已付费的成功资产再次提交；没有逐项记录的失败分支才会按冻结脚本
    的对应范围补全。
    """
    categories = result.get("categories") if isinstance(result, Mapping) else {}
    categories = categories if isinstance(categories, Mapping) else {}

    def category_state(name: str) -> str:
        item = categories.get(name)
        return str(item.get("state") or "") if isinstance(item, Mapping) else ""

    shot_by_id = {
        str(item.get("shot_id") or ""): item
        for item in shots
        if isinstance(item, Mapping) and str(item.get("shot_id") or "")
    }
    image_order = [
        shot_id for shot_id, item in shot_by_id.items() if item.get("first_frame_prompt")
    ]
    image_ids = set(image_order)
    aigc_ids = {
        shot_id for shot_id, item in shot_by_id.items()
        if item.get("media_type") == "aigc_video"
    }
    digital_ids = {
        shot_id for shot_id, item in shot_by_id.items()
        if _shot_requires_digital_human(item)
    }
    explanation_ids = {
        shot_id for shot_id, item in shot_by_id.items()
        if str(item.get("shot_class") or "") in {"explanation", "mixed_explanation"}
    }

    first_frame_assets = result.get("first_frame_assets") if isinstance(result, Mapping) else {}
    first_frame_assets = first_frame_assets if isinstance(first_frame_assets, Mapping) else {}
    grid_batches = first_frame_assets.get("grid_batches")
    grid_batches = grid_batches if isinstance(grid_batches, list) else []
    grid_records = first_frame_assets.get("grid_task_records")
    grid_records = grid_records if isinstance(grid_records, list) else []
    grid_status = {
        str(item.get("grid_id") or ""): str(item.get("status") or "").lower()
        for item in grid_records
        if isinstance(item, Mapping)
    }
    failed_grid_ids: set[str] = set()
    failed_image_ids: set[str] = set()
    for batch in grid_batches:
        if not isinstance(batch, Mapping):
            continue
        grid_id = str(batch.get("grid_id") or "")
        status = grid_status.get(grid_id, "completed")
        if status not in {"completed", "success", "succeeded"}:
            failed_grid_ids.add(grid_id)
            failed_image_ids.update(
                str(cell.get("shot_id") or "")
                for cell in batch.get("cells") or []
                if isinstance(cell, Mapping) and str(cell.get("shot_id") or "") in image_ids
            )
    image_paths = first_frame_assets.get("image_paths")
    if category_state("first_frame_images") in {"failed", "blocked", "interrupted"}:
        if not grid_batches:
            failed_image_ids = set(image_ids)
        elif not failed_image_ids and (not isinstance(image_paths, list) or len(image_paths) < len(image_ids)):
            # 旧任务可能只保存了部分图片路径，没有保存失败的 grid record；
            # 这种情况下只补缺失的尾部索引，已存在文件仍保持不动。
            failed_image_ids = set(image_order[len(image_paths or []):])
            if not failed_image_ids:
                failed_image_ids = set(image_ids)

    def failed_records(asset_key: str, allowed_ids: set[str], category_key: str) -> set[str]:
        assets = result.get(asset_key) if isinstance(result, Mapping) else {}
        assets = assets if isinstance(assets, Mapping) else {}
        records = assets.get("shot_results")
        records = records if isinstance(records, list) else []
        by_id = {
            str(item.get("shot_id") or ""): str(item.get("status") or "").lower()
            for item in records
            if isinstance(item, Mapping) and str(item.get("shot_id") or "") in allowed_ids
        }
        # fallback_image 是数字人鉴权失败后的已完成图片替代，不应再次进入
        # 付费数字人补跑；真正失败仍保留为可重试项。
        failed = {
            shot_id for shot_id, status in by_id.items()
            if status not in {"succeeded", "fallback_image"}
        }
        if category_state(category_key) in {"failed", "blocked", "interrupted"} and not records:
            failed.update(allowed_ids)
        return failed

    failed_aigc_ids = failed_records("aigc_video_assets", aigc_ids, "aigc_videos")
    failed_digital_ids = failed_records("digital_human_assets", digital_ids, "digital_humans")
    failed_explanation_ids = failed_records("explanation_assets", explanation_ids, "explanation_videos")
    bgm_assets = result.get("bgm_assets") if isinstance(result, Mapping) else {}
    bgm_assets = bgm_assets if isinstance(bgm_assets, Mapping) else {}
    bgm_failed = (
        category_state("bgm") in {"failed", "blocked", "interrupted"}
        or str(bgm_assets.get("status") or "").lower() in {"failed", "interrupted"}
    ) and str(bgm_assets.get("source_type") or "generated") != "uploaded"
    return {
        "first_frame": failed_image_ids,
        "first_frame_grids": failed_grid_ids,
        "aigc": failed_aigc_ids,
        "digital": failed_digital_ids,
        "explanation": failed_explanation_ids,
        "bgm": bool(bgm_failed),
    }


def _retry_failed_asset_production(asset_task_id: str) -> dict:
    """按失败分类启动补跑，绝不清理原任务的成功资产。

    当前 AIGC 补跑沿用已验收的断点续跑实现；数字人只有在没有 AIGC
    失败时才创建独立的 digital_only 任务，以便其内部继续严格串行，且
    通过 base_asset_task_id 回溯原任务的首帧、视频和 BGM。上传 BGM 和
    已成功的付费记录不会进入补跑集合。
    """
    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    if _asset_task_has_unrecoverable_grid_checkpoint(task):
        _raise_grid_checkpoint_unrecoverable()
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script_task = _latest_shot_script_task(source_story_task_id)
    shots = [
        dict(item) for item in (script_task.get("result") or {}).get("shot_video_script") or []
        if isinstance(item, Mapping)
    ]
    targets = _asset_retry_targets(result, shots)
    # 可选分支缺少输入时，直接在原任务上继续收敛；不创建 digital_only
    # 新任务，也不重复已成功的首帧/AIGC 付费任务。
    material = result.get("material_inputs") if isinstance(result, Mapping) else {}
    if targets["digital"] and not (material or {}).get("digital_human_count"):
        with ASSET_RESUME_LOCK:
            if asset_task_id in ASSET_RESUME_TASKS:
                return _task_snapshot(asset_task_id) or dict(task)
            ASSET_RESUME_TASKS.add(asset_task_id)
        def continue_optional_fallback() -> None:
            try:
                _run_asset_production_task(
                    asset_task_id,
                    source_story_task_id,
                    str(task.get("grid_layout") or "3x3"),
                    mode=str(task.get("mode") or "full"),
                    base_asset_task_id=str(task.get("base_asset_task_id") or ""),
                    aspect_ratio=str(task.get("aspect_ratio") or "") or None,
                    resume_from_checkpoint=True,
                )
            finally:
                with ASSET_RESUME_LOCK:
                    ASSET_RESUME_TASKS.discard(asset_task_id)
        threading.Thread(target=continue_optional_fallback, name=f"asset-optional-fallback-{asset_task_id[:12]}", daemon=True).start()
        return _task_snapshot(asset_task_id) or dict(task)
    if targets["aigc"]:
        return _retry_failed_asset_videos(asset_task_id)
    if targets["explanation"]:
        return _retry_failed_explanation_shots(asset_task_id)
    if targets["digital"]:
        return _create_asset_production_task(
            source_story_task_id,
            grid_layout=str(task.get("grid_layout") or "3x3"),
            mode="digital_only",
            base_asset_task_id=asset_task_id,
            aspect_ratio=str(task.get("aspect_ratio") or "") or None,
        )
    if targets["bgm"]:
        raise ValueError("BGM 失败项需要重新执行 BGM 生成；上传 BGM 不会被自动重试")
    if targets["first_frame"] or targets["first_frame_grids"]:
        return _retry_failed_first_frame_grids(asset_task_id, set(targets["first_frame_grids"]))
    raise ValueError("当前任务没有可重新生成的失败素材")


def _retry_failed_first_frame_grids(asset_task_id: str, grid_ids: set[str]) -> dict:
    """用户确认后，重新创建全部宫格并合并回原素材结果。"""
    task = _task_snapshot(asset_task_id)
    result = task.get("result") if isinstance(task, Mapping) else {}
    assets = result.get("first_frame_assets") if isinstance(result, Mapping) else {}
    batches = assets.get("grid_batches") if isinstance(assets, Mapping) else []
    # 旧快照可能写入 null；按空计划处理并从冻结逐镜脚本重建。
    if not isinstance(batches, (list, tuple)):
        batches = []
    batches = [dict(batch) for batch in batches if isinstance(batch, Mapping)]
    # “重新生成”是整组重建，不区分当前成功或失败状态；空集合表示全部宫格。
    if batches and not grid_ids:
        grid_ids = {str(batch.get("grid_id") or "") for batch in batches if str(batch.get("grid_id") or "")}
    # 任务在创建阶段即因状态不明确失败时，主快照可能尚未写入
    # first_frame_assets；此时从冻结逐镜脚本重建宫格计划，仅选失败批次。
    if not batches:
        script_result = (_latest_shot_script_task(str(task.get("source_story_task_id") or "")).get("result") or {}) if isinstance(task, Mapping) else {}
        all_image_shots = [dict(item) for item in (script_result.get("shot_video_script") or []) if isinstance(item, Mapping) and _shot_is_grid_image(item)]
        rebuilt = build_first_frame_grid_plan(all_image_shots, cells_per_grid=9 if str(task.get("grid_layout") or "3x3") == "3x3" else 4, grid_layout=str(task.get("grid_layout") or "3x3"), aspect_ratio=str(result.get("aspect_ratio") or "9:16"))
        all_batches = [dict(batch) for batch in rebuilt.get("batches", []) if isinstance(batch, Mapping)]
        # 旧任务可能只落盘了成功批次；“重新生成”要求整组提交，
        # 因此不再按 checkpoint 排除成功批次。
        if not grid_ids:
            grid_ids = {str(batch.get("grid_id") or "") for batch in all_batches if str(batch.get("grid_id") or "")}
        batches = [batch for batch in all_batches if str(batch.get("grid_id") or "") in grid_ids]
        assets = {"grid_batches": batches}
    cells = [cell for batch in batches or [] if isinstance(batch, Mapping) and str(batch.get("grid_id") or "") in grid_ids for cell in (batch.get("cells") or []) if isinstance(cell, Mapping)]
    shot_ids = {str(cell.get("shot_id") or "") for cell in cells if str(cell.get("shot_id") or "")}
    if not shot_ids:
        raise ValueError("没有可重新生成的失败宫格")
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script = _latest_shot_script_task(source_story_task_id).get("result") or {}
    selected = [dict(item) for item in (script.get("shot_video_script") or []) if isinstance(item, Mapping) and str(item.get("shot_id") or "") in shot_ids and _shot_is_grid_image(item)]
    if not selected:
        raise ValueError("失败宫格没有可用的首帧提示词")
    output_dir = Path(str(result.get("output_dir") or "")).expanduser() / "first_frame_retry"
    output_dir.mkdir(parents=True, exist_ok=True)
    category = dict((result.get("categories") or {}).get("first_frame_images") or {})
    category.update(state="queued", message=f"等待用户确认后重新生成全部宫格：{'、'.join(sorted(grid_ids))}")
    queued = dict(result)
    # 首帧变化会使既有 AIGC 视频失效：清空其任务记录与本地产物，
    # 让后续链路在首帧完成后重新创建，避免沿用旧视频。
    old_aigc = dict(queued.get("aigc_video_assets") or {})
    root = Path(str(result.get("output_dir") or "")).expanduser().resolve()
    for record in old_aigc.get("shot_results") or []:
        if not isinstance(record, Mapping):
            continue
        raw_path = str(record.get("video_path") or "").strip()
        if not raw_path:
            continue
        try:
            candidate = Path(raw_path).expanduser().resolve()
            if candidate.is_file() and candidate.is_relative_to(root):
                candidate.unlink()
        except (OSError, ValueError):
            continue
    old_aigc.update(shot_results=[], succeeded_count=0, failed_count=0, submitted_count=0)
    queued["aigc_video_assets"] = old_aigc
    old_first = dict(queued.get("first_frame_assets") or {})
    for raw_path in old_first.get("image_paths") or []:
        try:
            candidate = Path(str(raw_path)).expanduser().resolve()
            if candidate.is_file() and candidate.is_relative_to(root):
                candidate.unlink()
        except (OSError, ValueError):
            pass
    old_first.update(image_paths=[], image_urls=[], grid_task_records=[])
    queued["first_frame_assets"] = old_first
    # 首帧变化会使所有依赖首帧的输出失效：数字人、说明性镜头、图片镜头
    # 均清空任务记录和本地产物，避免页面继续展示旧版本。
    for asset_key in ("digital_human_assets", "explanation_assets"):
        old_branch = dict(queued.get(asset_key) or {})
        for record in old_branch.get("shot_results") or []:
            if not isinstance(record, Mapping):
                continue
            raw_path = str(record.get("video_path") or "").strip()
            if raw_path:
                try:
                    candidate = Path(raw_path).expanduser().resolve()
                    if candidate.is_file() and candidate.is_relative_to(root):
                        candidate.unlink()
                except (OSError, ValueError):
                    pass
        old_branch.update(shot_results=[], task_ids=[], video_paths=[], succeeded_count=0, failed_count=0, submitted_count=0)
        queued[asset_key] = old_branch
    categories = {**dict(result.get("categories") or {}), "first_frame_images": category}
    aigc_category = dict(categories.get("aigc_videos") or {})
    aigc_category.update(state="queued", submitted=0, completed=0, message="等待首帧重新生成完成后重新创建 AIGC 视频")
    categories["aigc_videos"] = aigc_category
    for key, message in (("digital_humans", "等待首帧重新生成完成后重新创建数字人任务"), ("explanation_videos", "等待首帧重新生成完成后重新渲染说明镜头")):
        branch = dict(categories.get(key) or {})
        branch.update(state="queued", submitted=0, completed=0, message=message)
        categories[key] = branch
    queued["categories"] = categories
    _set_task(asset_task_id, state="queued", stage="first_frame_retry_queued", progress=0, message=category["message"], result=queued)
    def worker() -> None:
        try:
            # 每次用户明确点击“重新生成”都开启一轮全新的宫格提交；
            # 旧重试断点可能残留不完整句柄，不能让它阻断新一轮创建。
            retry_checkpoint = output_dir / "first_frame_checkpoint.json"
            try:
                retry_checkpoint.unlink(missing_ok=True)
            except OSError:
                pass
            generated = generate_images_as_grids({"shots": selected, "aspect_ratio": result.get("aspect_ratio") or "9:16"}, _runtime_auth_document(), output_dir, grid_layout=str(task.get("grid_layout") or "3x3"), checkpoint_path=retry_checkpoint, resume=False, publish=True)
            old = dict((_task_snapshot(asset_task_id) or {}).get("result") or result)
            old_assets = dict(old.get("first_frame_assets") or {})
            old_paths = list(old_assets.get("image_paths") or []); old_urls = list(old_assets.get("image_urls") or [])
            by_shot = {str(item.get("shot_id") or ""): i for i, item in enumerate(selected)}
            source_order = [str(item.get("shot_id") or "") for item in (script.get("shot_video_script") or []) if isinstance(item, Mapping) and item.get("first_frame_prompt")]
            for sid, idx in by_shot.items():
                if sid in source_order:
                    pos = source_order.index(sid)
                    while len(old_paths) <= pos: old_paths.append("")
                    while len(old_urls) <= pos: old_urls.append("")
                    old_paths[pos] = (generated.get("image_paths") or [""])[idx]
                    old_urls[pos] = (generated.get("image_urls") or [""])[idx]
            old_assets.update(image_paths=old_paths, image_urls=old_urls)
            # 旧任务快照可能没有 image_paths，但裁切文件已落盘；按镜头顺序补回。
            if len(old_paths) < len(source_order) or any(not str(p or '').strip() for p in old_paths[:len(source_order)]):
                root_dir = Path(str(result.get("output_dir") or "")).expanduser()
                retry_dir = root_dir / "first_frame_retry"
                recovered_paths = []
                for index in range(1, len(source_order) + 1):
                    candidates = [retry_dir / f"first_frame_shot_{index:03d}.png", root_dir / f"first_frame_shot_{index:03d}.png"]
                    found = next((str(p) for p in candidates if p.is_file()), "")
                    recovered_paths.append(found)
                if all(recovered_paths):
                    old_paths = recovered_paths
                    old_urls = publish_existing_grid_images([Path(p) for p in old_paths], _runtime_auth_document(), output_dir / "recovered_publish.json", force_refresh=False)
                    old_assets.update(image_paths=old_paths, image_urls=old_urls)
            # 合并重生成批次回原任务，供后续 AIGC 链路判定首帧完整可复用。
            merged_batches = {str(b.get("grid_id") or ""): dict(b) for b in (old_assets.get("grid_batches") or []) if isinstance(b, Mapping) and str(b.get("grid_id") or "")}
            for b in generated.get("grid_batches") or []:
                if isinstance(b, Mapping) and str(b.get("grid_id") or ""):
                    merged_batches[str(b.get("grid_id"))] = dict(b)
            if merged_batches:
                old_assets["grid_batches"] = [merged_batches[k] for k in sorted(merged_batches)]
            old["first_frame_assets"] = old_assets
            cats = dict(old.get("categories") or {})
            cats["first_frame_images"] = {**dict(cats.get("first_frame_images") or {}), "state": "succeeded", "message": "全部宫格已重新生成；旧 AIGC、数字人、说明镜头输出已清零并重新联动。"}
            old["categories"] = cats
            _set_task(asset_task_id, state="queued", stage="first_frame_retry_completed", progress=42, message="全部宫格已生成，正在重新创建联动 AIGC 视频任务。", result=old)
            # 首帧是 AIGC 视频的硬依赖。复用同一素材任务继续执行后续分支，
            # 由 _run_asset_production_task 读取已合并首帧并重新创建视频任务。
            _run_asset_production_task(
                asset_task_id,
                source_story_task_id,
                str(task.get("grid_layout") or "3x3"),
                mode=str(task.get("mode") or "full"),
                base_asset_task_id=asset_task_id,
                aspect_ratio=str(task.get("aspect_ratio") or "") or None,
                resume_from_checkpoint=False,
            )
        except Exception as exc:
            _set_task(asset_task_id, state="failed", stage="first_frame_retry_failed", progress=100, message=f"失败宫格重生成失败：{type(exc).__name__}：{str(exc)[:260]}", result=(_task_snapshot(asset_task_id) or {}).get("result") or result)
    threading.Thread(target=worker, daemon=True).start()
    return _task_snapshot(asset_task_id) or task


def _retry_failed_explanation_shots(
    asset_task_id: str,
    shot_id: str | None = None,
    *,
    force: bool = False,
    remotion_settings: Mapping[str, object] | None = None,
) -> dict:
    """补跑说明镜头；微调模式生成新目录，保留旧 Remotion 输出。"""
    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    if _asset_task_has_unrecoverable_grid_checkpoint(task):
        _raise_grid_checkpoint_unrecoverable()
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script_task = _latest_shot_script_task(source_story_task_id)
    shots = [dict(item) for item in (script_task.get("result") or {}).get("shot_video_script") or [] if isinstance(item, Mapping)]
    explanation_shots = [
        item for item in shots
        if str(item.get("shot_class") or "") in {"explanation", "mixed_explanation"}
    ]
    if not explanation_shots:
        raise ValueError("当前逐镜脚本没有说明镜头")
    assets = result.get("explanation_assets") if isinstance(result, Mapping) else {}
    records = [dict(item) for item in (assets.get("shot_results") if isinstance(assets, Mapping) else []) or [] if isinstance(item, Mapping)]
    existing_by_id = {str(item.get("shot_id") or ""): item for item in records}
    failed_ids = {
        str(item.get("shot_id") or "") for item in explanation_shots
        if str(item.get("shot_id") or "") and existing_by_id.get(str(item.get("shot_id") or ""), {}).get("status") != "succeeded"
    }
    if force:
        failed_ids = {
            str(item.get("shot_id") or "") for item in explanation_shots if str(item.get("shot_id") or "")
        }
    selected = str(shot_id or "").strip()
    if selected:
        if selected not in {str(item.get("shot_id") or "") for item in explanation_shots}:
            raise ValueError("指定镜头不在当前冻结逐镜脚本中")
        if selected not in failed_ids:
            raise ValueError(f"{selected} 已有成功说明视频，不会重复渲染")
        target_ids = {selected}
    else:
        target_ids = failed_ids
    if not target_ids:
        raise ValueError("当前没有失败或缺失的说明镜头")
    output_dir_value = str(result.get("output_dir") or "").strip()
    if not output_dir_value:
        raise ValueError("素材任务缺少输出目录，无法安全重试说明镜头")
    explanation_root = Path(output_dir_value).expanduser().resolve() / "explanation"
    task_dir = explanation_root / (f"tuned-{int(time.time())}-{uuid.uuid4().hex[:8]}" if force else "")
    task_dir.mkdir(parents=True, exist_ok=True)
    queued_result = dict(result)
    effective_settings = normalize_style_override(
        remotion_settings
        if remotion_settings is not None
        else result.get("remotion_settings") if isinstance(result, Mapping) else None
    )
    queued_result["remotion_settings"] = effective_settings
    categories = dict(queued_result.get("categories") or {})
    category = dict(categories.get("explanation_videos") or {})
    category.update(state="queued", message=f"准备补跑说明镜头：{'、'.join(sorted(target_ids))}")
    categories["explanation_videos"] = category
    queued_result["categories"] = categories
    _set_task(asset_task_id, state="queued", stage="explanation_retry_queued", progress=0, message=category["message"], result=queued_result)

    def worker() -> None:
        try:
            latest = dict((_task_snapshot(asset_task_id) or {}).get("result") or result)
            render_result = render_explanation_shots(
                shots,
                latest,
                task_dir,
                retry_shot_ids=target_ids,
                packaging_override=effective_settings,
                width=_video_input_dimensions(normalize_aspect_ratio(str(task.get("aspect_ratio") or "9:16")))[0],
                height=_video_input_dimensions(normalize_aspect_ratio(str(task.get("aspect_ratio") or "9:16")))[1],
                fps=30,
            )
            fresh_by_id = {str(item.get("shot_id") or ""): dict(item) for item in render_result.get("shot_results") or [] if isinstance(item, Mapping)}
            ordered = [fresh_by_id.get(str(item.get("shot_id") or ""), existing_by_id.get(str(item.get("shot_id") or ""), {"shot_id": item.get("shot_id"), "status": "failed"})) for item in explanation_shots]
            latest["explanation_assets"] = dict(render_result, shot_results=ordered, succeeded_count=sum(item.get("status") == "succeeded" for item in ordered), failed_count=sum(item.get("status") != "succeeded" for item in ordered))
            categories = dict(latest.get("categories") or {})
            categories["explanation_videos"] = {
                "label": "说明镜头视频",
                "state": "succeeded" if all(item.get("status") == "succeeded" for item in ordered) else "failed",
                "completed": sum(item.get("status") == "succeeded" for item in ordered),
                "total": len(ordered),
                "message": "说明镜头补跑完成；已复用成功输出。",
            }
            latest["categories"] = categories
            other_failed = any(
                key != "explanation_videos"
                and isinstance(value, Mapping)
                and str(value.get("state") or "") in {"failed", "blocked", "interrupted"}
                for key, value in categories.items()
            )
            if categories["explanation_videos"]["state"] == "succeeded" and not other_failed:
                _set_task(asset_task_id, state="succeeded", stage="explanation_retry_completed", progress=100, message="说明镜头补跑完成；成功输出已保留。", result=latest)
            elif categories["explanation_videos"]["state"] == "succeeded":
                _set_task(asset_task_id, state="failed", stage="explanation_retry_completed_partial", progress=100, message="说明镜头补跑完成，但其他素材分支仍失败；成功输出已保留。", result=latest)
            else:
                _set_task(asset_task_id, state="failed", stage="explanation_retry_failed", progress=100, message="说明镜头补跑后仍有失败输出；成功输出已保留。", result=latest)
        except Exception as exc:
            latest = dict((_task_snapshot(asset_task_id) or {}).get("result") or result)
            categories = dict(latest.get("categories") or {})
            categories["explanation_videos"] = {
                "label": "说明镜头视频", "state": "failed", "completed": 0,
                "total": len(explanation_shots),
                "message": f"说明镜头补跑失败：{type(exc).__name__}：{str(exc)[:260]}",
            }
            latest["categories"] = categories
            _set_task(asset_task_id, state="failed", stage="explanation_retry_failed", progress=100, message=categories["explanation_videos"]["message"], result=latest)

    threading.Thread(target=worker, daemon=True).start()
    return _task_snapshot(asset_task_id) or {"task_id": asset_task_id}


def _confirm_first_frame_grids(asset_task_id: str, payload: Mapping[str, object]) -> dict:
    """记录宫格人工审核结果；仅全部合格后才允许进入剪辑交付。"""
    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    result = dict(task.get("result") or {})
    assets = result.get("first_frame_assets")
    batches = assets.get("grid_batches") if isinstance(assets, Mapping) else None
    if not isinstance(batches, list) or not batches:
        raise ValueError("当前没有可审核的宫格首帧")
    incoming = payload.get("reviews")
    if not isinstance(incoming, Mapping):
        raise ValueError("宫格审核结果格式无效")
    valid_ids = {str(item.get("grid_id") or "") for item in batches if isinstance(item, Mapping)}
    reviews = {
        str(key): str(value).lower()
        for key, value in incoming.items()
        if str(key) in valid_ids and str(value).lower() in {"approved", "rejected"}
    }
    if bool(payload.get("final")) and any(value != "approved" for value in reviews.values()):
        raise ValueError("存在不合格宫格；请先完成对应宫格重试后重新审核")
    complete = set(reviews) == valid_ids
    if bool(payload.get("final")) and not complete:
        missing = sorted(valid_ids - set(reviews))
        raise ValueError("请先逐一审核全部宫格：" + "、".join(missing))
    result["first_frame_review"] = {
        "status": "approved" if complete else "reviewing",
        "reviews": reviews,
        "approved_at": _utc_timestamp(),
    }
    _set_task(asset_task_id, result=result)
    return _task_snapshot(asset_task_id) or task


def _save_remotion_settings(asset_task_id: str, payload: Mapping[str, object]) -> dict:
    """保存素材页的说明镜头样式；可选地启动一次保留旧结果的重渲染。"""

    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    if str(task.get("state") or "").lower() in {"queued", "running"}:
        raise ValueError("素材任务正在运行，不能同时修改 Remotion 参数")
    raw_settings = payload.get("settings")
    if raw_settings is not None and not isinstance(raw_settings, Mapping):
        raise ValueError("Remotion 微调参数必须是对象")
    settings = normalize_style_override(raw_settings if isinstance(raw_settings, Mapping) else None)
    result = dict(task.get("result") or {}) if isinstance(task.get("result"), Mapping) else {}
    result["remotion_settings"] = settings
    _set_task(asset_task_id, result=result)
    if not bool(payload.get("apply")):
        return _task_snapshot(asset_task_id) or {"task_id": asset_task_id}
    return _retry_failed_explanation_shots(
        asset_task_id,
        force=True,
        remotion_settings=settings,
    )


def _retry_failed_digital_humans(asset_task_id: str) -> dict:
    """仅补跑数字人分类中失败或缺失的镜头，保留其余付费资产。"""
    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    if _asset_task_has_unrecoverable_grid_checkpoint(task):
        _raise_grid_checkpoint_unrecoverable()
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script_task = _latest_shot_script_task(source_story_task_id)
    shots = [
        dict(item) for item in (script_task.get("result") or {}).get("shot_video_script") or []
        if isinstance(item, Mapping)
    ]
    targets = _asset_retry_targets(result, shots)
    target_ids = set(targets.get("digital") or set())
    if not target_ids:
        raise ValueError("当前数字人没有失败或缺失镜头，不会重复生成")

    # 失败卡片可能在主任务仍有其他分支运行时就被点击；只排除明确仍在
    # RunningHub 运行中的记录，失败和缺失记录仍可立即进入数字人补全任务。
    digital_assets = result.get("digital_human_assets") if isinstance(result, Mapping) else {}
    records = digital_assets.get("shot_results") if isinstance(digital_assets, Mapping) else []
    in_flight = {
        str(item.get("shot_id") or "")
        for item in records or []
        if isinstance(item, Mapping)
        and str(item.get("shot_id") or "") in target_ids
        and str(item.get("status") or "").lower() in {"submitted", "running"}
    }
    retry_ids = [
        str(item.get("shot_id") or "")
        for item in shots
        if str(item.get("shot_id") or "") in target_ids
        and str(item.get("shot_id") or "") not in in_flight
        and _shot_requires_digital_human(item)
    ]
    if not retry_ids:
        running = "、".join(sorted(in_flight))
        raise ValueError(f"数字人任务仍在生成中，请等待当前任务结束：{running}")
    return _create_asset_production_task(
        source_story_task_id,
        grid_layout=str(task.get("grid_layout") or "3x3"),
        mode="digital_only",
        base_asset_task_id=asset_task_id,
        aspect_ratio=str(task.get("aspect_ratio") or "") or None,
        retry_shot_ids=retry_ids,
    )


def _retry_asset_shot(
    asset_task_id: str, shot_id: str, source_story_task_id: str = ""
) -> dict:
    """只重试用户点击的失败占位镜头，成功资产和其他镜头全部保留。"""
    asset_task_id, task = _resolve_asset_task_for_retry(asset_task_id, source_story_task_id)
    if not task or task.get("task_type") != "asset_production":
        if source_story_task_id:
            raise ValueError("未找到当前故事的素材生产任务，请先刷新素材生产页")
        raise ValueError("未找到素材生产任务")
    if _asset_task_has_unrecoverable_grid_checkpoint(task):
        _raise_grid_checkpoint_unrecoverable()
    shot_id = str(shot_id or "").strip()
    if not shot_id:
        raise ValueError("缺少需要重试的镜头编号")
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script_task = _latest_shot_script_task(source_story_task_id)
    shots = [
        dict(item) for item in (script_task.get("result") or {}).get("shot_video_script") or []
        if isinstance(item, Mapping)
    ]
    shot = next((item for item in shots if str(item.get("shot_id") or "") == shot_id), None)
    if not shot:
        raise ValueError("指定镜头不在当前冻结逐镜脚本中")
    media_type = str(shot.get("media_type") or "")
    shot_class = str(shot.get("shot_class") or "")
    if media_type not in {"aigc_video", "digital_human_video"} and shot_class not in {"explanation", "mixed_explanation"}:
        raise ValueError("只有 AIGC 视频、数字人或说明镜头支持点击重试")
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    asset_key = (
        "aigc_video_assets" if media_type == "aigc_video"
        else "digital_human_assets" if media_type == "digital_human_video"
        else "explanation_assets"
    )
    assets = result.get(asset_key) if isinstance(result, Mapping) else {}
    records = assets.get("shot_results") if isinstance(assets, Mapping) else []
    record = next(
        (item for item in records or [] if isinstance(item, Mapping) and str(item.get("shot_id") or "") == shot_id),
        None,
    )
    status = str(record.get("status") or "").lower() if isinstance(record, Mapping) else ""
    if status == "succeeded":
        raise ValueError(f"{shot_id} 已有成功资产，不会重复付费生成")
    if status in {"submitted", "running"}:
        raise ValueError(f"{shot_id} 当前仍在生成中，请等待任务结束")
    category_name = (
        "aigc_videos" if media_type == "aigc_video"
        else "digital_humans" if media_type == "digital_human_video"
        else "explanation_videos"
    )
    category = (result.get("categories") or {}).get(category_name) if isinstance(result, Mapping) else {}
    category_state = str(category.get("state") or "").lower() if isinstance(category, Mapping) else ""
    if not record and str(task.get("state") or "").lower() in {"queued", "running"} and category_state in {"queued", "running"}:
        raise ValueError(f"{shot_id} 当前仍在生成中，请等待任务结束")
    if media_type == "aigc_video":
        return _retry_failed_asset_videos(asset_task_id, shot_id=shot_id)
    if shot_class in {"explanation", "mixed_explanation"}:
        return _retry_failed_explanation_shots(asset_task_id, shot_id=shot_id)
    return _create_asset_production_task(
        source_story_task_id,
        grid_layout=str(task.get("grid_layout") or "3x3"),
        mode="digital_only",
        base_asset_task_id=asset_task_id,
        aspect_ratio=str(task.get("aspect_ratio") or "") or None,
        retry_shot_id=shot_id,
    )


def _compact_image2_prompt(shot: Mapping[str, object]) -> str:
    """把逐镜导演数据投影为稳定、可执行的 Image2 首帧提示词。

    导演脚本中的故事锚点、前后镜承接和审计理由只服务于编导，不应直接
    发送给生图模型。这里固定为“画幅—参考—主体动作—场景—镜头—光影—
    质量—负面约束”模板，既保留画面信息，也便于用户在素材页审阅。
    """
    return compile_first_frame_prompt(shot, aspect_ratio=shot.get("aspect_ratio") or "9:16")


def _attach_style_reference_urls(shots: list[dict], style_urls: Sequence[str]) -> int:
    """将已发布的画风参考图 URL 注入需要首帧的镜头。"""

    normalized_urls = list(dict.fromkeys(
        str(value).strip()
        for value in style_urls
        if str(value).strip().startswith(("http://", "https://"))
    ))
    if not normalized_urls:
        return 0
    attached = 0
    for shot in shots:
        if not shot.get("first_frame_prompt"):
            continue
        reference = dict(shot.get("first_frame_reference") or {})
        existing = [
            str(value).strip()
            for value in reference.get("urls", [])
            if str(value).strip().startswith(("http://", "https://"))
        ]
        merged_urls = list(dict.fromkeys(existing + normalized_urls))
        reference["urls"] = merged_urls
        reference.update(
            used=True,
            reference_count=len(merged_urls),
            source="素材层画风参考图",
            purpose="固定画风、主角与场景连续性",
        )
        shot["first_frame_reference"] = reference
        attached += 1
    return attached


def _asset_manifest_from_shots(shots: list[dict], *, aspect_ratio: str = "9:16") -> dict:
    """将逐镜脚本投影为已有真实执行器所需的最小清单，保持 shot_id 顺序。"""
    manifest_shots = []
    for item in shots:
        video_request = build_video_request(item)
        first_frame_request = build_first_frame_request(item, aspect_ratio=aspect_ratio)
        first_frame_prompt = str(first_frame_request["prompt"])
        visual_direction = item.get("visual_direction") if isinstance(item.get("visual_direction"), Mapping) else {}
        visual_direction = visual_direction if isinstance(visual_direction, Mapping) else {}
        manifest_shots.append({
            "shot_id": str(item["shot_id"]),
            # Source Director fields remain on ``item``.  The compiled form is
            # a first-frame-only projection with deterministic warnings.
            "compiled_first_frame_prompt": first_frame_prompt,
            "first_frame_prompt": first_frame_prompt,
            # 宫格首帧使用独立字段，不能复用视频生成 prompt。
            "grid_prompt": first_frame_prompt,
            "prompt": video_request["prompt"],
            "semantic_anchor": str(item.get("semantic_anchor") or ""),
            "shot_content": str(item.get("shot_content") or ""),
            "shot_design_type": str(item.get("shot_design_type") or ""),
            "motion_seed": str(item.get("motion_seed") or ""),
            "camera_motion": list(item.get("camera_motion") or []) if isinstance(item.get("camera_motion"), list) else [],
            # 这些字段要随 manifest 进入 first_frame_grid.cells，不能只存在编导任务里。
            "shot_size": str(item.get("shot_size") or visual_direction.get("shot_size") or ""),
            "viewpoint": str(item.get("viewpoint") or item.get("camera_angle") or visual_direction.get("viewpoint") or visual_direction.get("camera_angle") or ""),
            "composition": str(item.get("composition") or visual_direction.get("composition") or ""),
            "staging": str(item.get("staging") or visual_direction.get("staging") or ""),
            "first_frame_prompt_audit": dict(first_frame_request.get("prompt_audit") or {}),
            "camera_fixed": video_request["camera_fixed"],
            "duration_s": float(item["duration_s"]),
            "duration_ms": int(round(float(item["duration_s"]) * 1000)),
            "ref_images": list((item.get("first_frame_reference") or {}).get("urls") or []),
            # 视觉模型失败时仍要把用户原文带进宫格规划；不能只保存在素材任务摘要。
            "visual_guidance": dict(item.get("visual_guidance") or {})
            if isinstance(item.get("visual_guidance"), Mapping)
            else {},
        })
    return {"aspect_ratio": aspect_ratio, "video_model": "auto", "shots": manifest_shots}


def _run_visual_guidance_model(
    user_prompt: str,
    reference_urls: list[str],
) -> dict[str, object]:
    """用多模态模型把用户补充要求和参考图收口为可复用视觉约束。"""
    request_text = (
        "用户额外视觉要求：\n" + user_prompt.strip() + "\n\n"
        "请观察参考图，输出严格 JSON，不要输出 Markdown："
        '{"reference_usage":"","positive_prompt":"","negative_prompt":""}。'
        "reference_usage 说明所有宫格如何共享参考图；positive_prompt 只写需要强化的视觉特征；"
        "negative_prompt 只写需要禁止的视觉偏差。不要编造参考图没有的特征。"
    )
    try:
        transport = DirectorsV2PluginHTTPTransport.from_env()
        raw = transport.run_plugin(
            system_prompt=(
                "你是素材生产层的多模态视觉约束导演。你必须同时依据用户文字和参考图，"
                "把视觉要求转成简洁、可执行、适合 Image 2 宫格生图的约束。"
            ),
            prompt=request_text,
            image_urls=reference_urls,
        ).get("output_5_5", "")
        text = str(raw or "").strip()
        match = re.search(r"\{[\s\S]*\}", text)
        parsed = json.loads(match.group(0) if match else text)
        if not isinstance(parsed, Mapping):
            raise ValueError("视觉模型返回的根节点不是 JSON 对象")
        return {
            "status": "succeeded",
            "reference_usage": str(parsed.get("reference_usage") or "").strip(),
            "positive_prompt": str(parsed.get("positive_prompt") or "").strip(),
            "negative_prompt": str(parsed.get("negative_prompt") or "").strip(),
            "user_prompt": user_prompt.strip(),
            "model": os.environ.get("DIRECTORS_V2_MODEL_VISION", "gpt-4o"),
        }
    except (DirectorsV2PluginConfigError, DirectorsV2PluginTransportError, ValueError, json.JSONDecodeError) as exc:
        return {
            "status": "blocked",
            "reason": f"视觉模型未完成：{type(exc).__name__}: {str(exc)[:240]}",
            "user_prompt": user_prompt.strip(),
        }


def _run_first_frame_guidance_expander(
    user_prompt: str,
    *,
    grid_layout: str,
    aspect_ratio: str,
    reference_image_count: int,
    config: VisualGuidanceExpanderConfig | None = None,
    runner: Callable[[Mapping[str, object]], object] | object | None = None,
) -> dict[str, object]:
    """把用户注意力引导扩成首帧全局约束，一次任务最多调用一次小模型。

    默认关闭，可复用已有 directors_v2 或 API 管理的方舟文本 Provider。这里不读取或写入
    用户素材，不创建图片任务；任何配置/Provider/JSON 失败都由强化器回退。
    """

    resolved = config or VisualGuidanceExpanderConfig.from_env()
    if resolved.cache_path is None:
        resolved = replace(
            resolved,
            cache_path=DIRECTOR_REVIEW_DIR / "first_frame_guidance_expander_cache.json",
        )
    resolved_runner = runner
    if resolved.enabled and resolved.mode == "ON" and resolved_runner is None:
        provider = resolved.provider.strip().lower()
        if provider == "directors-v2":
            try:
                resolved_runner = ExistingModelGuidanceExpanderAdapter(
                    DirectorsV2PluginHTTPTransport.from_env()
                )
            except (DirectorsV2PluginConfigError, DirectorsV2PluginTransportError, TypeError):
                # 不在这里吞掉强化器本身的审计。让它以 ERROR 状态、原文回退返回。
                resolved_runner = None
        elif provider in {"ark-story-writing", "story-writing"}:
            try:
                base_config = ArkStoryConfig.from_env()
                resolved_runner = ExistingModelGuidanceExpanderAdapter(
                    ArkStoryHTTPTransport(
                        replace(
                            base_config,
                            model=resolved.model,
                            timeout=resolved.timeout,
                        )
                    )
                )
            except (ArkStoryConfigError, ArkStoryTransportError, TypeError):
                resolved_runner = None
    return LightweightVisualGuidanceExpander(
        config=resolved,
        runner=resolved_runner,
    ).expand(
        user_prompt,
        context={
            "grid_layout": grid_layout,
            "aspect_ratio": aspect_ratio,
            "reference_image_count": max(0, int(reference_image_count or 0)),
        },
    )


def _apply_visual_guidance(shots: list[dict], guidance: Mapping[str, object]) -> None:
    """把视觉模型结果挂到每个首帧镜头，供宫格模板统一继承。"""
    for shot in shots:
        if shot.get("first_frame_prompt"):
            shot["visual_guidance"] = dict(guidance)


def _grid_preview_from_script(
    script_result: Mapping[str, object],
    *,
    grid_layout: str = "3x3",
    aspect_ratio: str | None = None,
    visual_guidance_prompt: str = "",
    visual_guidance_source: str = "",
    reference_image_count: int = 0,
) -> dict:
    """按真实首帧执行器的同一规划器生成页面预览，禁止页面自行猜测分组。"""
    requested_aspect_ratio = str(aspect_ratio or "").strip()
    if requested_aspect_ratio and requested_aspect_ratio not in SUPPORTED_ASPECT_RATIOS:
        raise ValueError("画幅仅支持 9:16、16:9、1:1、3:2、2:3")
    resolved_aspect_ratio = normalize_aspect_ratio(
        requested_aspect_ratio or script_result.get("aspect_ratio") or "9:16"
    )
    shots = script_result.get("shot_video_script")
    if not isinstance(shots, list):
        raise ValueError("逐镜脚本缺少 shot_video_script")
    # 页面预览必须与实际执行使用同一份已保存引导，而不是等任务启动后才可见。
    image_shots = [dict(item) for item in shots if isinstance(item, dict) and item.get("first_frame_prompt")]
    saved_guidance = str(visual_guidance_prompt or "").strip()
    # user_prompt 只可能来自素材页的用户输入；source 为空是早期保存格式，
    # 也应在预览和实际创建时保留，避免用户已填写的注意力引导静默丢失。
    if saved_guidance and str(visual_guidance_source or "").strip() in {"", "explicit_user"}:
        _apply_visual_guidance(
            image_shots,
            {"status": "direct_user_prompt", "source": "explicit_user", "user_prompt": saved_guidance},
        )
    manifest = _asset_manifest_from_shots(image_shots, aspect_ratio=resolved_aspect_ratio)
    plan = build_first_frame_grid_plan(
        manifest["shots"],
        cells_per_grid=9 if grid_layout == "3x3" else 4,
        grid_layout=grid_layout,
        aspect_ratio=resolved_aspect_ratio,
    )
    # 预览不需要把本地参考图路径放进返回 JSON，但必须与真实执行器一样
    # 生成“根据参考图……”的首句。用批次元数据表达这一事实，避免泄露路径。
    if int(reference_image_count or 0) > 0:
        for batch in plan.get("batches", []):
            batch["has_reference_images"] = True
            batch["prompt"] = build_grid_prompt(batch)
            batch.pop("has_reference_images", None)
    return {
        "aspect_ratio": resolved_aspect_ratio,
        "aspect_ratio_source": "asset_user_override" if requested_aspect_ratio else "director_locked",
        "grid_layout": grid_layout,
        "grid_batches": plan["batches"],
        "skipped_digital_human_count": len(shots) - len(image_shots),
    }


def _select_first_frames_for_video_shots(
    image_state: Mapping[str, object], image_shots: list[dict], video_shots: list[dict]
) -> dict[str, list[str]]:
    """从全部首帧结果按 shot_id 取出 AIGC 视频镜头所需的首帧。

    静态图片镜头同样需要首帧，但不会进入 Seedance 视频生成；不能再按两个
    数组长度相等的错误前提传递。
    """
    image_urls = image_state.get("image_urls")
    image_paths = image_state.get("image_paths")
    if not isinstance(image_urls, list) or len(image_urls) != len(image_shots):
        raise RuntimeError("首帧结果与首帧镜头数量不一致")
    if not isinstance(image_paths, list) or len(image_paths) != len(image_shots):
        raise RuntimeError("首帧本地文件与首帧镜头数量不一致")
    by_shot_id = {
        str(shot["shot_id"]): (str(image_urls[index]), str(image_paths[index]))
        for index, shot in enumerate(image_shots)
    }
    selected = [by_shot_id.get(str(shot["shot_id"])) for shot in video_shots]
    if any(item is None or not item[0].startswith(("http://", "https://")) for item in selected):
        missing = [str(video_shots[index]["shot_id"]) for index, item in enumerate(selected) if item is None]
        raise RuntimeError(f"AIGC 视频镜头缺少对应首帧：{', '.join(missing) or '首帧 URL 无效'}")
    return {
        "image_urls": [item[0] for item in selected if item is not None],
        "image_paths": [item[1] for item in selected if item is not None],
    }


def _video_input_dimensions(aspect_ratio: str) -> tuple[int, int]:
    """Return stable, exact-ratio dimensions accepted by the video API."""
    return {
        "9:16": (720, 1280),
        "16:9": (1280, 720),
        "1:1": (1024, 1024),
        "3:2": (1200, 800),
        "2:3": (800, 1200),
    }.get(str(aspect_ratio or "9:16"), (720, 1280))


def _prepare_video_input_image_state(
    image_state: Mapping[str, object],
    image_shots: list[dict],
    video_shots: list[dict],
    *,
    aspect_ratio: str,
    auth_document: Path,
    task_dir: Path,
) -> dict[str, list[str]]:
    """Normalize existing cropped frames before Seedance, without calling Image2 again.

    Grid cropping can leave a one-pixel remainder, producing images such as 307x551
    instead of an exact 9:16 frame. Seedance rejects those as invalid first/last
    frames. We preserve the original preview assets and create a separate, exact
    ratio video-input copy, then publish only that copy to TOS.
    """
    image_paths = image_state.get("image_paths")
    image_urls = image_state.get("image_urls")
    if not isinstance(image_paths, list) or not isinstance(image_urls, list):
        raise RuntimeError("首帧结果缺少本地路径或公网 URL，无法准备视频输入")
    if len(image_paths) != len(image_shots) or len(image_urls) != len(image_shots):
        raise RuntimeError("首帧结果与首帧镜头数量不一致")

    width, height = _video_input_dimensions(aspect_ratio)
    output_dir = task_dir / "video_input_images"
    output_dir.mkdir(parents=True, exist_ok=True)
    normalized_paths: list[str] = []
    for index, source_value in enumerate(image_paths, start=1):
        source = Path(str(source_value)).expanduser()
        if not source.is_file():
            raise RuntimeError(f"首帧本地文件不存在：{source}")
        target = output_dir / f"video_input_{index:03d}.jpg"
        command = [
            "ffmpeg", "-y", "-loglevel", "error", "-i", str(source),
            "-vf", f"scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height}",
            "-frames:v", "1", "-q:v", "2", str(target),
        ]
        completed = subprocess.run(command, capture_output=True, text=True, timeout=120)
        if completed.returncode != 0 or not target.is_file() or target.stat().st_size < 5_000:
            detail = (completed.stderr or "").strip()[:240]
            raise RuntimeError(f"首帧视频输入规范化失败：{source.name}{('；' + detail) if detail else ''}")
        normalized_paths.append(str(target.resolve()))

    published_urls = publish_existing_grid_images(
        normalized_paths,
        auth_document,
        output_dir / "published_video_input_images.json",
    )
    by_shot = {
        str(shot["shot_id"]): (published_urls[index], normalized_paths[index])
        for index, shot in enumerate(image_shots)
    }
    selected = [by_shot.get(str(shot["shot_id"])) for shot in video_shots]
    if any(item is None for item in selected):
        missing = [
            str(video_shots[index]["shot_id"])
            for index, item in enumerate(selected)
            if item is None
        ]
        raise RuntimeError(f"视频镜头缺少规范化首帧：{', '.join(missing)}")
    return {
        "image_urls": [item[0] for item in selected if item is not None],
        "image_paths": [item[1] for item in selected if item is not None],
    }


def _latest_shot_script_task(source_story_task_id: str) -> dict:
    tasks = [
        task for task in _list_style_tasks(limit=2000, source_story_task_id=source_story_task_id)
        if task.get("task_type") == "director_shot_script"
        and task.get("state") == "succeeded"
        and isinstance(task.get("result"), dict)
        and task["result"].get("source_story_task_id") == source_story_task_id
    ]
    if not tasks:
        raise ValueError("未找到已完成的逐镜视频脚本；请先在编导层生成并审核逐镜脚本")
    return max(tasks, key=lambda item: int(item.get("updated_at") or 0))


def _approve_director_shot_script_task(source_story_task_id: str) -> dict:
    """原子确认故事与最终逐镜视频脚本，作为素材生产唯一闸门。"""

    story_task = _task_snapshot(source_story_task_id)
    if (
        not story_task
        or story_task.get("task_type") != "director_story_review"
        or story_task.get("state") != "succeeded"
    ):
        raise ValueError("未找到已完成的v2 编导任务")
    story_result = story_task.get("result") if isinstance(story_task.get("result"), Mapping) else {}
    if story_result.get("review_status") not in {None, "PENDING_USER_REVIEW", "APPROVED"}:
        raise ValueError("内部编导结果状态无效，不能确认最终视频脚本")
    script_task = _latest_shot_script_task(source_story_task_id)
    result = script_task.get("result") if isinstance(script_task.get("result"), Mapping) else {}
    if not result.get("shot_video_script"):
        raise ValueError("最终视频脚本为空，不能确认")
    approved_at = int(time.time())
    if result.get("review_status") != "APPROVED":
        result = dict(result)
        result["review_status"] = "APPROVED"
        result["approved_at"] = approved_at
        _set_task(
            str(script_task["task_id"]),
            stage="shot_script_approved",
            message="最终视频脚本已确认，素材生产层已解锁。",
            result=result,
        )
    # 当前页面只提供“确认最终视频脚本并进入素材生产”这一项用户操作。
    # 因而同一次确认必须同步写入父故事审核，否则素材层会错误地把已经
    # 进入素材页的任务拦截为“故事尚未确认”。对历史已确认子任务也补齐父状态。
    if story_result.get("review_status") != "APPROVED":
        approved_story_result = dict(story_result)
        approved_story_result["review_status"] = "APPROVED"
        approved_story_result["approved_at"] = approved_at
        approved_story_result["approval_source"] = "final_shot_script_approval"
        _set_task(
            source_story_task_id,
            stage="story_and_shot_script_approved",
            message="故事与最终视频脚本已确认，素材生产层已解锁。",
            result=approved_story_result,
        )
    return _task_snapshot(str(script_task["task_id"])) or script_task


def _digital_narration_assets(script_result: Mapping[str, object]) -> dict[str, dict]:
    """按 group_id 建立已锁定 TTS 音频索引，不重新生成 TTS。"""
    director_lock = script_result.get("director_lock")
    assets = director_lock.get("narration_assets") if isinstance(director_lock, Mapping) else None
    result: dict[str, dict] = {}
    if isinstance(assets, list):
        for item in assets:
            if not isinstance(item, Mapping):
                continue
            group_id = str(item.get("group_id") or "").strip()
            local_path = str(item.get("local_path") or "").strip()
            if group_id and local_path:
                result[group_id] = dict(item)
    return result


def _missing_digital_tts_assets(
    script_result: Mapping[str, object], digital_shots: list[Mapping[str, object]]
) -> list[str]:
    """返回数字人镜头所需、但尚未落盘的分段 TTS 音频。"""

    narration_by_group = _digital_narration_assets(script_result)
    required_groups = list(dict.fromkeys(
        str(shot.get("group_id") or "").strip()
        for shot in digital_shots
        if str(shot.get("group_id") or "").strip()
    ))
    missing: list[str] = []
    for group_id in required_groups:
        narration = narration_by_group.get(group_id)
        local_path = str(narration.get("local_path") or "").strip() if narration else ""
        path = Path(local_path).expanduser() if local_path else Path()
        try:
            ready = path.is_file() and path.stat().st_size > 0
        except OSError:
            ready = False
        if not ready:
            missing.append(f"{group_id}: {local_path or '未登记本地路径'}")
    return missing


def _digital_human_audio_window(
    shot: Mapping[str, object], narration_asset: Mapping[str, object]
) -> dict[str, int | str]:
    """把数字人小镜头时间线换算为所属 CapCut STT 分段内的相对窗口。

    编导层只为每个大分段生成一条真实 TTS；数字人却是逐小镜头创建任务。
    因此不能把整段 TTS 直接重复交给每个数字人镜头，必须用冻结的
    ``shot_video_script`` 时间线在对应大分段音频内裁出本镜窗口。
    """
    shot_id = str(shot.get("shot_id") or "").strip()
    group_id = str(shot.get("group_id") or "").strip()
    shot_timeline_value = shot.get("timeline")
    shot_timeline = shot_timeline_value if isinstance(shot_timeline_value, Mapping) else shot
    group_timeline_value = narration_asset.get("timeline")
    group_timeline = group_timeline_value if isinstance(group_timeline_value, Mapping) else narration_asset

    def bounds(value: Mapping[str, object], label: str) -> tuple[int, int]:
        start = value.get("start_us", value.get("start"))
        end = value.get("end_us", value.get("end"))
        if isinstance(start, bool) or not isinstance(start, int) or isinstance(end, bool) or not isinstance(end, int):
            raise RuntimeError(f"{label} 必须使用整数微秒")
        if end <= start:
            raise RuntimeError(f"{label} 必须满足 end_us > start_us")
        return start, end

    shot_start, shot_end = bounds(shot_timeline, f"{shot_id} 时间线")
    group_start, group_end = bounds(group_timeline, f"{group_id} 剪映 STT 分段时间线")
    if shot_start < group_start or shot_end > group_end:
        raise RuntimeError(
            f"{shot_id} 数字人对白时间窗 {shot_start}-{shot_end} 超出 {group_id} 剪映 STT 分段时间线 {group_start}-{group_end}"
        )
    return {
        "shot_id": shot_id,
        "group_id": group_id,
        "shot_start_us": shot_start,
        "shot_end_us": shot_end,
        "group_start_us": group_start,
        "group_end_us": group_end,
        "relative_start_us": shot_start - group_start,
        "duration_us": shot_end - shot_start,
    }


def _resolve_digital_audio_ffmpeg() -> str:
    """解析数字人对白裁切所需的本机 FFmpeg，不伪造裁切结果。"""
    configured = (
        os.environ.get("INFINITETALK_FFMPEG_PATH", "").strip()
        or os.environ.get("FFMPEG_PATH", "").strip()
    )
    resolved = configured or shutil.which("ffmpeg") or ""
    if resolved:
        return resolved
    try:
        import imageio_ffmpeg  # type: ignore

        return imageio_ffmpeg.get_ffmpeg_exe()
    except Exception as exc:
        raise RuntimeError("未找到 FFmpeg，无法按数字人镜头坑位裁切 TTS 对白") from exc


def _slice_digital_human_audio(
    shot: Mapping[str, object],
    narration_asset: Mapping[str, object],
    output_dir: Path,
) -> tuple[Path, dict[str, int | str]]:
    """从大分段 TTS 裁出一个数字人小镜头的独立音频文件。

    输出文件按源音频摘要和微秒窗口命名，跨任务可稳定复用；裁切后的音频
    末尾补静音并严格截到坑位时长，避免 RunningHub 生成的视频对白越过镜头。
    """
    window = _digital_human_audio_window(shot, narration_asset)
    source_path = Path(str(narration_asset.get("local_path") or "")).expanduser()
    if not source_path.is_file():
        raise RuntimeError(f"{window['shot_id']} 缺少已锁定 TTS 音频：{source_path}")
    source_digest = _file_digest(source_path)
    key_payload = {
        "source_digest": source_digest,
        "relative_start_us": window["relative_start_us"],
        "duration_us": window["duration_us"],
    }
    key = hashlib.sha256(
        json.dumps(key_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()[:24]
    target = output_dir / f"{window['shot_id']}-{key}.mp3"
    if target.is_file() and target.stat().st_size >= 1_024:
        return target.resolve(), window

    output_dir.mkdir(parents=True, exist_ok=True)
    temporary = output_dir / f".{window['shot_id']}-{key}.part.mp3"
    ffmpeg = _resolve_digital_audio_ffmpeg()
    duration_seconds = int(window["duration_us"]) / 1_000_000
    offset_seconds = int(window["relative_start_us"]) / 1_000_000
    command = [
        ffmpeg,
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-ss",
        f"{offset_seconds:.6f}",
        "-i",
        str(source_path),
        "-t",
        f"{duration_seconds:.6f}",
        "-vn",
        "-af",
        f"apad,atrim=duration={duration_seconds:.6f}",
        "-ar",
        "48000",
        "-ac",
        "2",
        "-codec:a",
        "libmp3lame",
        "-b:a",
        "128k",
        str(temporary),
    ]
    try:
        completed = subprocess.run(command, capture_output=True, text=True, timeout=180, check=False)
        if completed.returncode != 0 or not temporary.is_file() or temporary.stat().st_size < 1_024:
            detail = (completed.stderr or "").strip().replace("\r", " ").replace("\n", " ")[-500:]
            raise RuntimeError(f"数字人对白裁切失败{': ' + detail if detail else ''}")
        temporary.replace(target)
    finally:
        temporary.unlink(missing_ok=True)
    return target.resolve(), window


def _tos_bucket_configs_from_runtime_auth(auth: Mapping[str, str]) -> list[TOSBucketConfig]:
    """把页面/环境变量与鉴权文档合并成主桶、备用桶配置。"""

    def value(*names: str, fallback: str = "") -> str:
        for name in names:
            current = os.environ.get(name, "").strip()
            if current:
                return current
        return fallback.strip()

    endpoint = value(
        "ARK_TTS_TOS_ENDPOINT",
        "INFINITETALK_TOS_ENDPOINT",
        fallback=str(auth.get("tos_endpoint") or "https://tos-cn-beijing.volces.com"),
    )
    region = value(
        "ARK_TTS_TOS_REGION",
        "INFINITETALK_TOS_REGION",
        fallback=str(auth.get("tos_region") or "cn-beijing"),
    )
    primary = {
        "access_key": value("ARK_TTS_TOS_ACCESS_KEY", "INFINITETALK_TOS_ACCESS_KEY", fallback=str(auth.get("tos_access_key") or "")),
        "secret_key": value("ARK_TTS_TOS_SECRET_KEY", "INFINITETALK_TOS_SECRET_KEY", fallback=str(auth.get("tos_secret_key") or "")),
        "bucket": value("ARK_TTS_TOS_BUCKET", "INFINITETALK_TOS_BUCKET", fallback=str(auth.get("tos_bucket") or "")),
        "endpoint": endpoint,
        "region": region,
    }
    configs: list[TOSBucketConfig] = []
    if all(primary.values()):
        configs.append(TOSBucketConfig(**primary))
    backup_endpoint = value("ARK_TTS_TOS_BACKUP_ENDPOINT", "INFINITETALK_TOS_BACKUP_ENDPOINT", fallback=endpoint)
    backup_region = value("ARK_TTS_TOS_BACKUP_REGION", "INFINITETALK_TOS_BACKUP_REGION", fallback=region)
    backup = {
        "access_key": value("ARK_TTS_TOS_BACKUP_ACCESS_KEY", "INFINITETALK_TOS_BACKUP_ACCESS_KEY"),
        "secret_key": value("ARK_TTS_TOS_BACKUP_SECRET_KEY", "INFINITETALK_TOS_BACKUP_SECRET_KEY"),
        "bucket": value("ARK_TTS_TOS_BACKUP_BUCKET", "INFINITETALK_TOS_BACKUP_BUCKET"),
        "endpoint": backup_endpoint,
        "region": backup_region,
    }
    if all(backup.values()):
        configs.append(TOSBucketConfig(**backup))
    return configs


def _tos_publisher_from_runtime_auth(
    auth: Mapping[str, str], *, prefix: str, url_expires: int = 7200
) -> TOSAudioPublisher:
    """为所有本地上传旁支复用同一套 TOS 主/备用桶降级。"""

    return TOSAudioPublisher(
        _tos_bucket_configs_from_runtime_auth(auth),
        prefix=prefix,
        url_expires=url_expires,
        failover_strategy=os.environ.get("TOS_FAILOVER_STRATEGY", "primary_then_backup"),
    )


def _publish_digital_input(path: Path, auth: Mapping[str, str], task_dir: Path, role: str) -> str:
    """把本地数字人输入临时发布为 RunningHub 可下载 URL；凭据只在内存中使用。"""
    if not path.is_file():
        raise RuntimeError(f"数字人{role}文件不存在：{path}")
    publisher = _tos_publisher_from_runtime_auth(
        auth,
        prefix=f"1256/infinitetalk/{task_dir.name}",
    )
    media_type = mimetypes.guess_type(path.name)[0] or ("audio/mpeg" if role == "音频" else "image/png")
    result = publisher(
        path.read_bytes(),
        f"{role}-{hashlib.sha256(path.read_bytes()).hexdigest()[:16]}{path.suffix.lower() or ('.mp3' if role == '音频' else '.png')}",
        {"mime_type": media_type, "source_name": path.name},
    )
    url = str(result.get("url") or "")
    if not url.startswith(("http://", "https://")):
        raise RuntimeError(f"数字人{role}发布后没有得到可访问 URL")
    return url


def _download_digital_output(url: str, target: Path) -> Path:
    """下载 RunningHub 终态视频到本机，供素材页和剪辑层复用。"""
    import requests

    response = requests.get(url, timeout=120, stream=True)
    response.raise_for_status()
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_suffix(target.suffix + ".tmp")
    with temporary.open("wb") as handle:
        for chunk in response.iter_content(chunk_size=1024 * 1024):
            if chunk:
                handle.write(chunk)
    if not temporary.is_file() or temporary.stat().st_size < 50_000:
        temporary.unlink(missing_ok=True)
        raise RuntimeError("数字人终态视频下载为空或文件过小")
    temporary.replace(target)
    return target


def _digital_human_cache_path(source_story_task_id: str) -> Path:
    return DIRECTOR_REVIEW_DIR / source_story_task_id / "digital_human_asset_cache.json"


def _load_digital_human_cache(path: Path) -> dict[str, object]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        payload = {}
    entries = payload.get("entries") if isinstance(payload, Mapping) else {}
    return {"version": 1, "entries": dict(entries) if isinstance(entries, Mapping) else {}}


def _save_digital_human_cache(path: Path, cache: Mapping[str, object]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(dict(cache), ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(path)


def _file_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _digital_human_cache_key(
    shot: Mapping[str, object],
    script_result: Mapping[str, object],
    image_path: Path,
    audio_path: Path,
) -> str:
    relevant = {
        key: shot.get(key)
        for key in (
            "shot_id", "group_id", "start_us", "end_us", "duration_s", "narration",
            "shot_content", "viewpoint", "shot_size", "camera_motion", "aspect_ratio",
            "digital_human_params",
            "production_spec", "route",
        )
        if shot.get(key) is not None
    }
    payload = {
        "version": 1,
        "shot": relevant,
        "script_aspect_ratio": script_result.get("aspect_ratio"),
        "image_digest": _file_digest(image_path),
        "audio_digest": _file_digest(audio_path),
    }
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _digital_human_create_params(
    shot: Mapping[str, object],
    script_result: Mapping[str, object],
    *,
    api_key: str,
    image_url: str,
    audio_url: str,
) -> tuple[dict[str, object], dict[str, str]]:
    """将锁定的逐镜导演数据投影为 RunningHub 数字人请求。"""
    production_spec = shot.get("production_spec") if isinstance(shot.get("production_spec"), Mapping) else {}
    route = shot.get("route") if isinstance(shot.get("route"), Mapping) else {}
    director_lock = script_result.get("director_lock") if isinstance(script_result.get("director_lock"), Mapping) else {}
    policy: dict[str, object] = {}
    for candidate in (
        shot.get("digital_human_params"),
        production_spec.get("digital_human_params"),
        route.get("digital_human_params"),
        director_lock.get("digital_human_params"),
        director_lock.get("digital_human_policy"),
    ):
        if isinstance(candidate, Mapping):
            policy.update(candidate)

    narration = str(shot.get("narration") or production_spec.get("narration_text") or "").strip()
    shot_content = str(shot.get("shot_content") or "").strip()
    viewpoint = str(shot.get("viewpoint") or "").strip()
    shot_size = str(shot.get("shot_size") or "").strip()
    camera_motion = shot.get("camera_motion")
    camera_motion_text = "、".join(str(item).strip() for item in camera_motion if str(item).strip()) if isinstance(camera_motion, list) else str(camera_motion or "").strip()
    aspect_ratio = str(shot.get("aspect_ratio") or script_result.get("aspect_ratio") or "9:16").strip()
    prompt = "；".join(item for item in (
        "人物自然口播，嘴型与驱动音频同步，保持参考人物脸部、发型、服装和身份一致",
        f"本镜旁白：{narration}" if narration else "",
        f"本镜画面动作：{shot_content}" if shot_content else "",
        f"景别：{shot_size}" if shot_size else "",
        f"视角：{viewpoint}" if viewpoint else "",
        f"运镜：{camera_motion_text}" if camera_motion_text else "",
        f"画幅：{aspect_ratio}",
        "只执行可见的自然口播和轻微配合动作，不生成字幕、文字、UI、品牌标识或额外人物",
    ) if item)
    defaults = {"Max_side_length": 1080, "intensity": 0, "Scale": 1.05, "instanceType": "plus"}
    values = {name: policy.get(name, default) for name, default in defaults.items()}
    trace = {
        "prompt_source": "director_locked_shot",
        "numeric_source": "director_locked_policy" if policy else "original_plugin_contract_default",
        "aspect_ratio_source": "director_locked_shot" if shot.get("aspect_ratio") else "director_locked_manifest",
    }
    return {
        "api_key": api_key, "image": image_url, "audio": audio_url,
        "Max_side_length": values["Max_side_length"], "prompt": prompt,
        "intensity": values["intensity"], "Scale": values["Scale"],
        "instanceType": values["instanceType"],
    }, trace


def _publish_local_audio(path: Path, auth: Mapping[str, str], task_dir: Path, prefix: str = "bgm") -> str:
    """把本地 BGM 发布为融合器可访问的临时 URL。"""
    if not path.is_file():
        raise RuntimeError(f"BGM 文件不存在：{path}")
    publisher = _tos_publisher_from_runtime_auth(
        auth,
        prefix=f"1256/bgm/{task_dir.name}",
    )
    result = publisher(
        path.read_bytes(),
        f"{prefix}-{hashlib.sha256(path.read_bytes()).hexdigest()[:16]}{path.suffix.lower() or '.mp3'}",
        {"mime_type": mimetypes.guess_type(path.name)[0] or "audio/mpeg", "source_name": path.name},
    )
    url = str(result.get("url") or "")
    if not url.startswith(("http://", "https://")):
        raise RuntimeError("BGM 发布后没有得到可访问 URL")
    return url


def _download_audio_output(url: str, target: Path) -> Path:
    """下载 BGM 终态文件，供剪辑层直接复用。"""
    import requests

    response = requests.get(url, timeout=120, stream=True)
    response.raise_for_status()
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_suffix(target.suffix + ".tmp")
    with temporary.open("wb") as handle:
        for chunk in response.iter_content(chunk_size=1024 * 1024):
            if chunk:
                handle.write(chunk)
    if not temporary.is_file() or temporary.stat().st_size < 5_000:
        temporary.unlink(missing_ok=True)
        raise RuntimeError("BGM 终态音频下载为空或文件过小")
    temporary.replace(target)
    return target


def _build_bgm_request(script_result: Mapping[str, object]) -> dict[str, object]:
    """从已冻结的编导大分段构造 BGM 生成输入，不新增用户入参。"""
    director_lock = script_result.get("director_lock")
    groups = director_lock.get("groups") if isinstance(director_lock, Mapping) else None
    timelines: list[dict[str, int]] = []
    cues: list[dict[str, object]] = []
    if isinstance(groups, list):
        for group in groups:
            if not isinstance(group, Mapping):
                continue
            timeline = group.get("timeline")
            if not isinstance(timeline, Mapping):
                continue
            start = int(timeline.get("start_us") or 0)
            end = int(timeline.get("end_us") or 0)
            if end <= start:
                continue
            metadata = group.get("metadata") if isinstance(group.get("metadata"), Mapping) else {}
            rhythm = str(metadata.get("rhythm") or "steady")
            scene = metadata.get("story_scene") if isinstance(metadata.get("story_scene"), Mapping) else {}
            cues.append({
                "music_role": rhythm,
                "emotion": "紧张推进" if rhythm in {"hook", "why", "conflict", "turn"} else "稳定收束",
                "energy": 4 if rhythm in {"hook", "why", "conflict", "turn"} else 2,
                "music_direction": str(scene.get("scene_purpose") or "跟随叙事节奏自然推进"),
                "transition_to_next": "crossfade",
                "segment_text": str(group.get("segment_text") or ""),
            })
            timelines.append({"start": start, "end": end})
    if not timelines:
        raise RuntimeError("编导锁定结果没有可用于 BGM 的时间线")
    return {"timelines": timelines, "music_cues": cues}


def _build_bgm_merge_params(
    script_result: Mapping[str, object],
    source_urls: list[str],
    *,
    source_type: str,
    generated_batch: Mapping[str, object] | None = None,
) -> dict[str, object]:
    """把 BGM 批处理结果完整映射到融合器，不丢弃后续音频段。"""

    if not source_urls:
        raise RuntimeError("BGM 没有可用于融合的音频 URL")
    lock_request = _build_bgm_request(script_result)
    merge_timelines: list[dict[str, int]] = [{
        "start": int(lock_request["timelines"][0]["start"]),
        "end": int(lock_request["timelines"][-1]["end"]),
    }]
    transition_schemes: list[str] = []
    if source_type == "generated" and isinstance(generated_batch, Mapping):
        raw_timelines = generated_batch.get("bgm_timelines")
        raw_transitions = generated_batch.get("transition_schemes")
        if not isinstance(raw_timelines, list) or len(raw_timelines) != len(source_urls):
            raise RuntimeError("BGM 生成结果的音频数量与时间线数量不一致")
        merge_timelines = [
            {"start": int(item["start"]), "end": int(item["end"])}
            for item in raw_timelines
            if isinstance(item, Mapping) and int(item.get("end", 0)) > int(item.get("start", 0))
        ]
        if len(merge_timelines) != len(source_urls):
            raise RuntimeError("BGM 生成结果包含无效时间线")
        transition_schemes = [str(item) for item in (raw_transitions or [])]
        if len(transition_schemes) != max(0, len(merge_timelines) - 1):
            raise RuntimeError("BGM 生成结果的过渡方案数量不匹配")
    return {
        "audio_urls": list(source_urls),
        "timelines": merge_timelines,
        "transition_schemes": transition_schemes,
    }


def _first_frame_assets_are_usable(
    assets: Mapping[str, object], shots: list[Mapping[str, object]]
) -> bool:
    """Check that a previous first-frame task has ordered local files and URLs."""

    image_paths = assets.get("image_paths")
    image_urls = assets.get("image_urls")
    if not isinstance(image_paths, list) or not isinstance(image_urls, list):
        return False
    required = len(shots)
    if required <= 0 or len(image_paths) < required or len(image_urls) < required:
        return False
    return all(
        str(image_paths[index] or "").strip()
        and Path(str(image_paths[index])).is_file()
        and str(image_urls[index] or "").startswith(("http://", "https://"))
        for index in range(required)
    )


def _run_asset_production_task(
    task_id: str,
    source_story_task_id: str,
    grid_layout: str = "3x3",
    *,
    mode: str = "full",
    base_asset_task_id: str = "",
    aspect_ratio: str | None = None,
    retry_shot_id: str = "",
    retry_shot_ids: list[str] | None = None,
    resume_from_checkpoint: bool = False,
) -> None:
    """执行 Image 2 / Seedance；其余服务缺少必要输入时必须显式阻断。"""
    def mark_failed_category(result_value: Mapping[str, object], stage: str, detail: str) -> dict:
        """总任务失败时同步收敛当前分支卡片，避免页面残留 running。"""

        stage_category = {
            "first_frame_images": "first_frame_images",
            "aigc_videos": "aigc_videos",
            "bgm": "bgm",
            "digital_humans": "digital_humans",
            "explanation_videos": "explanation_videos",
        }.get(str(stage or "").strip())
        # BGM/数字人是并行分支，最后一次 stage 写入不一定属于抛错分支。
        # 先用稳定的异常类型/业务关键词定位首帧，避免把 BGM 卡片误标为失败。
        detail_lower = str(detail or "").lower()
        if "firstframegridbatcherror" in detail_lower or "首帧" in str(detail or "") or "image2" in detail_lower:
            stage_category = "first_frame_images"
        elif "seedance" in detail_lower or "aigc 视频" in str(detail or ""):
            stage_category = "aigc_videos"
        elif "bgm" in detail_lower:
            stage_category = "bgm"
        elif "数字人" in str(detail or "") or "runninghub" in detail_lower:
            stage_category = "digital_humans"
        elif "说明镜头" in str(detail or "") or "remotion" in detail_lower:
            stage_category = "explanation_videos"
        if not stage_category:
            return dict(result_value)
        updated = dict(result_value)
        categories = dict(updated.get("categories") or {})
        category = dict(categories.get(stage_category) or {})
        # 断点无 taskId 时是安全阻断，不是可重复提交的普通失败。
        blocked = "状态不明确" in detail or "避免重复付费" in detail
        category.update(
            state="blocked" if blocked else "failed",
            message=(
                "请求状态不明确；不会自动重试。请点击首帧图片卡片并确认费用，系统将重新生成全部宫格。"
                if blocked and stage_category == "first_frame_images"
                else ("已阻止自动重试：供应商请求状态不明确，需人工核对 taskId。" if blocked else f"分支失败：{detail[:320]}")
            ),
            completed=int(category.get("completed") or 0),
            submitted=int(category.get("submitted") or 0),
        )
        categories[stage_category] = category
        updated["categories"] = categories
        return updated

    def update(
        category: str,
        state: str,
        message: str,
        completed: int = 0,
        *,
        submitted: int | None = None,
        progress: int = 0,
    ) -> None:
        snapshot = _task_snapshot(task_id) or {}
        result = dict(snapshot.get("result") or {})
        categories = dict(result.get("categories") or {})
        item = dict(categories.get(category) or {})
        item.update(state=state, message=message, completed=completed)
        if submitted is not None:
            item["submitted"] = submitted
        if state in {"failed", "blocked", "interrupted"}:
            item["failure_category"] = category
            item["last_query_at"] = _utc_timestamp()
            item["recoverable_when"] = (
                "确认供应商 task_id 状态后继续查询"
                if category in {"bgm", "digital_humans", "aigc_videos"}
                else "修复前置条件后重试失败镜头"
            )
        categories[category] = item
        result["categories"] = categories
        _set_task(task_id, state="running", stage=category, progress=progress, message=message, result=result, _preserve_terminal=True)

    task_dir: Path | None = None
    result: dict = {}
    try:
        only_digital = mode == "digital_only"
        task_snapshot = _task_snapshot(task_id) or {}
        previous_result = (
            dict(task_snapshot.get("result") or {})
            if resume_from_checkpoint and isinstance(task_snapshot.get("result"), Mapping)
            else {}
        )
        task_input = task_snapshot.get("input") if isinstance(task_snapshot, Mapping) else {}
        remotion_settings = normalize_style_override(
            task_input.get("remotion_settings") if isinstance(task_input, Mapping) else None
        )
        requested_retry_ids = {
            str(item or "").strip() for item in (retry_shot_ids or []) if str(item or "").strip()
        }
        if retry_shot_id:
            requested_retry_ids.add(str(retry_shot_id).strip())
        script_task = _latest_shot_script_task(source_story_task_id)
        script_result = script_task["result"]
        requested_aspect_ratio = str(aspect_ratio or "").strip()
        resolved_aspect_ratio = normalize_aspect_ratio(
            requested_aspect_ratio or script_result.get("aspect_ratio") or "9:16"
        )
        source_shots = script_result.get("shot_video_script")
        if not isinstance(source_shots, list) or not source_shots or not all(isinstance(item, dict) for item in source_shots):
            raise RuntimeError("逐镜脚本为空，不能创建素材任务")
        # 用户素材属于素材层输入，绝不回写或篡改已冻结的编导输出。
        shots = [dict(item) for item in source_shots]
        material_inputs = _load_material_inputs(source_story_task_id)
        style_paths = material_inputs["style_reference_images"]
        stored_visual_guidance_prompt = str(material_inputs.get("visual_guidance_prompt") or "").strip()
        visual_guidance_source = str(material_inputs.get("visual_guidance_source") or "").strip()
        # 注意力引导字段只由素材页用户填写；空 source 是早期保存格式，
        # 不能因此把已有用户原文静默丢弃。未知来源仍不应进入生图提示词。
        visual_guidance_prompt = (
            stored_visual_guidance_prompt
            if visual_guidance_source in {"", "explicit_user"}
            else ""
        )
        visual_guidance: dict[str, object] = {
            "status": "skipped",
            "reason": (
                "未检测到已保存的用户注意力引导，沿用逐镜脚本与参考图约束。"
                if stored_visual_guidance_prompt and not visual_guidance_prompt
                else "用户未填写额外视觉要求，沿用逐镜脚本与参考图约束。"
            ),
        }
        style_urls: list[str] = []
        if style_paths:
            # 画风参考图与宫格产物是两条不同的链路；Image2 创建时必须拿到参考图公网 URL。
            style_urls = publish_existing_grid_images(
                style_paths,
                _runtime_auth_document(),
                DIRECTOR_REVIEW_DIR / source_story_task_id / "style_reference_publish.json",
                force_refresh=True,
            )
            _attach_style_reference_urls(shots, style_urls)
            if resume_from_checkpoint and isinstance(previous_result.get("visual_guidance"), Mapping):
                visual_guidance = dict(previous_result["visual_guidance"])
            elif visual_guidance_prompt and style_urls:
                visual_guidance = _run_visual_guidance_model(visual_guidance_prompt, style_urls)
            elif visual_guidance_prompt:
                visual_guidance = {
                    "status": "blocked",
                    "reason": "已填写额外视觉要求，但没有可供视觉模型读取的画风参考图。",
                    "user_prompt": visual_guidance_prompt,
                }
        elif visual_guidance_prompt:
                visual_guidance = {
                    "status": "blocked",
                    "reason": "已填写额外视觉要求，但未选择画风/场景参考图。",
                    "user_prompt": visual_guidance_prompt,
                }
        # 用户注意力引导强化器是首帧 Prompt 的增强层：它只在本次任务存在
        # 首帧图片时运行一次，输出作为全局约束交给确定性宫格 Builder。它与
        # 旧视觉参考图分析无依赖，不会改写用户原文，也不会参与图片轮询。
        has_first_frame_images = any(item.get("first_frame_prompt") for item in shots)
        if visual_guidance_prompt and has_first_frame_images:
            previous_guidance = previous_result.get("visual_guidance")
            if (
                resume_from_checkpoint
                and isinstance(previous_guidance, Mapping)
                and str(previous_guidance.get("guidance_expansion_input_hash") or "").strip()
            ):
                for key, value in previous_guidance.items():
                    if str(key).startswith("guidance_expansion_") or key in {
                        "enhanced_directive", "original_user_guidance", "cache_hit",
                    }:
                        visual_guidance[str(key)] = value
            else:
                expansion_audit = _run_first_frame_guidance_expander(
                    visual_guidance_prompt,
                    grid_layout=grid_layout,
                    aspect_ratio=resolved_aspect_ratio,
                    reference_image_count=len(style_paths),
                )
                visual_guidance.update(expansion_audit)
                if expansion_audit.get("guidance_expansion_status") == "EXPANDED":
                    visual_guidance["reason"] = "轻量注意力引导模型已生成经来源校验的首帧全局约束。"
                elif expansion_audit.get("guidance_expansion_status") == "ERROR":
                    visual_guidance["reason"] = (
                        "轻量注意力引导模型未完成，已回退用户原文与确定性首帧规则。"
                    )
        # 即使视觉大模型暂时不可用，也不能丢弃用户的注意力引导；
        # 它会作为原文约束直接进入宫格共用提示词，并在模型恢复后叠加视觉模型结果。
        if visual_guidance_prompt and not visual_guidance.get("user_prompt"):
            visual_guidance["user_prompt"] = visual_guidance_prompt
        if visual_guidance_prompt:
            visual_guidance["source"] = "explicit_user"
            # 无论视觉模型是否可用，用户原文都必须进入每个首帧镜头和宫格提示词。
            _apply_visual_guidance(shots, visual_guidance)
        categories = _asset_categories(shots)
        if previous_result:
            previous_categories = previous_result.get("categories")
            if isinstance(previous_categories, Mapping):
                for category_name, previous_category in previous_categories.items():
                    if not isinstance(previous_category, Mapping):
                        continue
                    # Keep durable branch progress. A resumed run must never
                    # turn a succeeded paid branch back into queued/running.
                    previous_state = str(previous_category.get("state") or "")
                    previous_completed = int(previous_category.get("completed") or 0)
                    if previous_state in {"succeeded", "skipped"} or previous_completed > 0:
                        categories[str(category_name)] = dict(previous_category)
        image_shots = [item for item in shots if _shot_is_grid_image(item)]
        image_manifest: dict[str, object] = {}
        image_task_total = 0
        if image_shots:
            image_manifest = _asset_manifest_from_shots(
                image_shots, aspect_ratio=resolved_aspect_ratio
            )
            image_task_total = len(build_first_frame_grid_plan(
                image_manifest["shots"],
                cells_per_grid=9 if grid_layout == "3x3" else 4,
                grid_layout=grid_layout,
                aspect_ratio=resolved_aspect_ratio,
            )["batches"])
            categories["first_frame_images"].update(
                total=image_task_total,
                shot_total=len(image_shots),
                unit_label="宫格任务",
            )
        task_dir = DIRECTOR_REVIEW_DIR / source_story_task_id / "asset_production" / task_id
        task_dir.mkdir(parents=True, exist_ok=True)
        result = {
            "source_story_task_id": source_story_task_id,
            "source_shot_script_task_id": script_task["task_id"],
            "aspect_ratio": resolved_aspect_ratio,
            "aspect_ratio_source": "asset_user_override" if requested_aspect_ratio else "director_locked",
            "shot_count": len(shots),
            "categories": categories,
            "material_inputs": {
                "style_reference_count": len(style_paths),
                "digital_human_count": len(material_inputs["digital_human_images"]),
                "bgm_uploaded": bool(material_inputs.get("bgm_audio")),
                "bgm_name": Path(str(material_inputs["bgm_audio"])).name if material_inputs.get("bgm_audio") else None,
                "visual_guidance_prompt": stored_visual_guidance_prompt,
                "visual_guidance_source": visual_guidance_source,
                "visual_guidance_applied": bool(visual_guidance_prompt),
            },
            "visual_guidance": visual_guidance,
            "first_frame_prompt_trace": [{
                "shot_id": item["shot_id"], "prompt": item.get("first_frame_prompt"),
                "reference": item.get("first_frame_reference", {}),
            } for item in shots if item.get("first_frame_prompt")],
            "output_dir": str(task_dir),
            "remotion_settings": remotion_settings,
        }
        if previous_result:
            # Preserve already downloaded assets, provider task records and
            # audit metadata while refreshing deterministic preflight fields.
            preserved_result = dict(previous_result)
            preserved_result.update(result)
            preserved_result["categories"] = categories
            result = preserved_result
        if isinstance(script_result.get("segment_timelines"), list):
            result["segment_timeline_unit"] = str(
                script_result.get("segment_timeline_unit") or "microseconds"
            )
            result["segment_timeline_source"] = str(
                script_result.get("segment_timeline_source") or "director_lock.groups_from_capcut_stt"
            )
            result["segment_timelines"] = [
                dict(item)
                for item in script_result["segment_timelines"]
                if isinstance(item, Mapping)
            ]
        if isinstance(script_result.get("group_timelines"), list):
            result["group_timeline_unit"] = str(
                script_result.get("group_timeline_unit") or "microseconds"
            )
            result["group_timeline_source"] = str(
                script_result.get("group_timeline_source") or "director_lock.groups_from_capcut_stt"
            )
            result["group_timelines"] = [
                dict(item)
                for item in script_result["group_timelines"]
                if isinstance(item, Mapping)
            ]
        opening_title = _opening_title_from_story_payload(
            script_result,
            fallback_source=script_result.get("approved_copy") or "",
        )
        result["opening_title"] = opening_title
        if isinstance(script_result.get("secondary_segment_timelines"), list):
            result["secondary_segment_timeline_unit"] = str(
                script_result.get("secondary_segment_timeline_unit") or "microseconds"
            )
            result["secondary_segment_timeline_source"] = str(
                script_result.get("secondary_segment_timeline_source") or "director_lock.shots_from_capcut_stt"
            )
            result["secondary_segment_timelines"] = [
                dict(item)
                for item in script_result["secondary_segment_timelines"]
                if isinstance(item, Mapping)
            ]
        if isinstance(script_result.get("transition_points"), list):
            result["transition_timeline_unit"] = str(
                script_result.get("transition_timeline_unit") or "microseconds"
            )
            result["transition_timeline_source"] = str(
                script_result.get("transition_timeline_source") or "secondary_segment_timelines"
            )
            result["transition_timelines"] = [
                dict(item)
                for item in script_result.get("transition_timelines") or []
                if isinstance(item, Mapping)
            ]
            result["transition_points"] = [
                dict(item)
                for item in script_result["transition_points"]
                if isinstance(item, Mapping)
            ]
        if only_digital and base_asset_task_id:
            base_task = _task_snapshot(base_asset_task_id)
            base_result = base_task.get("result") if isinstance(base_task, Mapping) else None
            if isinstance(base_result, Mapping):
                preserved = dict(base_result)
                preserved["output_dir"] = str(task_dir)
                preserved["categories"] = dict(preserved.get("categories") or {})
                preserved["categories"]["digital_humans"] = dict(categories.get("digital_humans") or {})
                result = preserved
        _set_task(task_id, state="running", stage="material_preflight", progress=3, message="已读取冻结逐镜脚本，开始真实素材任务。", result=result)
        # 首帧任务的职责只有宫格生图、轮询取回和本地落盘；不能因为
        # 复用同一个素材任务入口，就提前要求其它素材分支的鉴权。
        auth_channels = _asset_production_auth_channels()
        auth_document = _require_runtime_auth_document(
            "未找到鉴权文档，无法调用素材服务",
            channel_ids=auth_channels,
        )

        def branch_already_succeeded(category_name: str, asset_key: str) -> bool:
            if not resume_from_checkpoint:
                return False
            category = previous_result.get("categories", {}).get(category_name) if isinstance(previous_result.get("categories"), Mapping) else None
            asset = previous_result.get(asset_key)
            asset_status = str(asset.get("status") or "") if isinstance(asset, Mapping) else ""
            records = asset.get("shot_results") if isinstance(asset, Mapping) else None
            record_success = isinstance(records, list) and bool(records) and all(
                isinstance(item, Mapping) and str(item.get("status") or "") in {"succeeded", "fallback_image"}
                for item in records
            )
            local_records = bool(records) and record_success and all(
                bool(str(item.get("video_path") or "").strip())
                and Path(str(item.get("video_path") or "")).is_file()
                for item in records
                if isinstance(item, Mapping)
            ) if isinstance(records, list) else False
            return (
                isinstance(category, Mapping)
                and (
                    str(category.get("state") or "") in {"succeeded", "skipped"}
                    or (asset_key == "aigc_video_assets" and local_records)
                )
                and (asset_status in {"succeeded", "skipped"} or record_success)
            )

        # 三条大分支在这里同时启动。AIGC 仍在首帧完成后才启动，因为它
        # 必须拿到对应镜头的首帧 URL；BGM/数字人不依赖首帧或 AIGC。
        # 当前两个分支的 transport 尚未接入，因此会并行完成“可执行性检查”
        # 并明确记录 blocked，而不是把未调用写成成功。
        def run_bgm_branch() -> None:
            if branch_already_succeeded("bgm", "bgm_assets"):
                update("bgm", "succeeded", "恢复任务：复用已落盘 BGM，不重新生成。", 1, submitted=1, progress=35)
                return
            # BGM 是可选素材。未上传且未明确配置生成凭据时，不应把可选分支
            # 当成素材生产的硬阻断；剪辑层会在没有 BGM 时继续使用旁白。
            if not material_inputs.get("bgm_audio"):
                update("bgm", "skipped", "未上传背景音乐，按可选分支跳过；不调用 BGM 生成接口。", progress=35)
                return
            try:
                bgm_dir = task_dir / "bgm"
                bgm_dir.mkdir(parents=True, exist_ok=True)
                bgm_auth = load_infinite_talk_auth_from_document(auth_document)
                publisher = _tos_publisher_from_runtime_auth(
                    bgm_auth,
                    prefix=f"1256/bgm/{task_id}",
                )
                bgm_input = material_inputs.get("bgm_audio")
                source_urls: list[str] = []
                source_type = "uploaded"
                generated_batch: Mapping[str, object] | None = None
                # 上传 BGM 不会进入生成分支，但最终结果仍需保持统一的
                # shot_results/task_ids 结构，避免引用未初始化的局部变量。
                bgm_records: dict[int, dict] = {}
                if bgm_input:
                    source_path = Path(str(bgm_input)).expanduser()
                    update("bgm", "running", "已检测到用户上传 BGM，跳过生成模型，正在发布并按总时长融合。", progress=8)
                    source_urls = [_publish_local_audio(source_path, bgm_auth, task_dir, "uploaded-bgm")]
                else:
                    source_type = "generated"
                    update("bgm", "running", "未上传 BGM，正在根据编导时间线调用 BGM 生成模型。", progress=8)
                    bgm_request = _build_bgm_request(script_result)
                    try:
                        transport = VolcengineMusicHTTPTransport.from_env()
                    except VolcengineMusicTransportError as exc:
                        raise RuntimeError(f"BGM 独立 AK/SK 未配置：{str(exc)[:260]}") from exc
                    previous_bgm = previous_result.get("bgm_assets") if isinstance(previous_result, Mapping) else {}
                    previous_bgm = previous_bgm if isinstance(previous_bgm, Mapping) else {}
                    previous_bgm_records = [
                        dict(item) for item in (previous_bgm.get("shot_results") or [])
                        if isinstance(item, Mapping) and str(item.get("task_id") or "").strip()
                    ]
                    if not previous_bgm_records:
                        previous_bgm_records = [
                            {"index": index, "task_id": str(value), "status": "submitted"}
                            for index, value in enumerate(previous_bgm.get("task_ids") or [])
                            if str(value or "").strip()
                        ]
                    bgm_records: dict[int, dict] = {
                        int(item.get("index", index)): dict(item)
                        for index, item in enumerate(previous_bgm_records)
                    }
                    bgm_record_lock = threading.Lock()

                    def persist_bgm_event(event: Mapping[str, object], *, state: str = "submitted") -> None:
                        task_run_id = str(event.get("task_id") or "").strip()
                        if not task_run_id:
                            return
                        request_value = event.get("request") if isinstance(event.get("request"), Mapping) else {}
                        with bgm_record_lock:
                            index = next(
                                (key for key, item in bgm_records.items() if str(item.get("task_id") or "") == task_run_id),
                                next(
                                    (key for key, item in bgm_records.items() if item.get("request") == dict(request_value)),
                                    max(bgm_records.keys(), default=-1) + 1,
                                ),
                            )
                            record = dict(bgm_records.get(index) or {})
                            record.update(
                                index=index,
                                task_id=task_run_id,
                                status=state,
                                request=dict(request_value),
                                last_query_at=_utc_timestamp() if state != "submitted" else record.get("last_query_at", ""),
                            )
                            bgm_records[index] = record
                            snapshot = _task_snapshot(task_id) or {}
                            latest_result = dict(snapshot.get("result") or result)
                            latest_bgm = dict(latest_result.get("bgm_assets") or {})
                            ordered = [bgm_records[key] for key in sorted(bgm_records)]
                            latest_bgm.update(
                                status="running",
                                shot_results=ordered,
                                task_ids=[str(item.get("task_id") or "") for item in ordered],
                            )
                            latest_result["bgm_assets"] = latest_bgm
                            _set_task(task_id, state="running", stage="bgm", progress=8, message="BGM 任务号已持久化，服务重启后将续查，不重复创建。", result=latest_result, _preserve_terminal=True)

                    def persist_bgm_query(event: Mapping[str, object]) -> None:
                        event = dict(event)
                        event["status"] = "running"
                        persist_bgm_event(event, state="running")

                    transport.task_created_reporter = persist_bgm_event
                    transport.task_query_reporter = persist_bgm_query
                    existing_bgm_task_ids = [
                        str(bgm_records[index].get("task_id") or "")
                        for index in sorted(bgm_records)
                    ] if resume_from_checkpoint else []
                    bgm_query_transport = getattr(transport, "query_bgm", None)
                    batch = run_bgm_generation(
                        bgm_request,
                        transport=transport.generate_bgm,
                        query_transport=bgm_query_transport if callable(bgm_query_transport) else None,
                        existing_task_ids=existing_bgm_task_ids,
                    )
                    generated_batch = batch if isinstance(batch, Mapping) else None
                    outputs = batch.get("gen_bgm_outputs") if isinstance(batch, Mapping) else None
                    generated = outputs[0] if isinstance(outputs, list) and outputs else None
                    if not isinstance(generated, Mapping):
                        raise RuntimeError("BGM 生成成功但没有返回批处理音频结果")
                    outputs = generated_batch.get("gen_bgm_outputs") if isinstance(generated_batch, Mapping) else None
                    if not isinstance(outputs, list) or not outputs:
                        raise RuntimeError("BGM 生成成功但没有返回批处理音频结果")
                    for output_index, output in enumerate(outputs):
                        if not isinstance(output, Mapping):
                            raise RuntimeError(f"BGM 批处理结果 {output_index} 不是对象")
                        output_url = str(((output.get("data") or {}).get("SongDetail") or {}).get("AudioUrl") or "")
                        if not output_url.startswith(("http://", "https://")):
                            raise RuntimeError(f"BGM 批处理结果 {output_index} 未返回可访问音频 URL")
                        source_urls.append(output_url)
                        raw_task_id = str(((output.get("data") or {}).get("TaskID") or ""))
                        with bgm_record_lock:
                            record = dict(bgm_records.get(output_index) or {})
                            record.update(index=output_index, task_id=raw_task_id or str(record.get("task_id") or ""), status="succeeded", audio_url=output_url, last_query_at=_utc_timestamp())
                            bgm_records[output_index] = record
                merge_params = _build_bgm_merge_params(
                    script_result,
                    source_urls,
                    source_type=source_type,
                    generated_batch=generated_batch,
                )
                update("bgm", "running", f"BGM 已取得 {len(source_urls)} 段，正在按时间线融合并发布。", progress=22)
                merged = FfmpegBgmMergeTransport(publisher=publisher)(merge_params)
                merged_url = str(merged.get("audio_url") or "")
                if not merged_url.startswith(("http://", "https://")):
                    raise RuntimeError("BGM 融合后没有返回可访问 URL")
                local_path = _download_audio_output(merged_url, bgm_dir / "bgm_final.mp3")
                snapshot = _task_snapshot(task_id) or {}
                live_result = dict(snapshot.get("result") or result)
                live_result["bgm_assets"] = {
                    "status": "succeeded",
                    "source_type": source_type,
                    "duration_s": merged.get("duration"),
                    "audio_path": str(local_path.resolve()),
                    "audio_url_available": True,
                    "source_segment_count": len(source_urls),
                    "source_timelines": merge_params["timelines"],
                    "transition_schemes": merge_params["transition_schemes"],
                    "shot_results": [bgm_records[index] for index in sorted(bgm_records)],
                    "task_ids": [str(bgm_records[index].get("task_id") or "") for index in sorted(bgm_records)],
                }
                _set_task(task_id, result=live_result)
                update("bgm", "succeeded", f"BGM 已{'由模型生成并' if source_type == 'generated' else ''}完成时长融合。", 1, submitted=1, progress=35)
            except Exception as exc:
                update("bgm", "failed", f"BGM 分支失败：{type(exc).__name__}：{str(exc)[:260]}", progress=35)

        def run_digital_branch() -> None:
            if branch_already_succeeded("digital_humans", "digital_human_assets"):
                previous_category = previous_result.get("categories", {}).get("digital_humans") if isinstance(previous_result.get("categories"), Mapping) else {}
                update(
                    "digital_humans",
                    "succeeded",
                    "恢复任务：复用已落盘数字人，不重新调用服务商。",
                    int(previous_category.get("completed") or 0) if isinstance(previous_category, Mapping) else 0,
                    submitted=int(previous_category.get("submitted") or 0) if isinstance(previous_category, Mapping) else 0,
                    progress=35,
                )
                return
            all_digital_shots = [item for item in shots if _shot_requires_digital_human(item)]
            digital_shots = [
                item for item in all_digital_shots
                if not requested_retry_ids or str(item.get("shot_id") or "") in requested_retry_ids
            ]
            if requested_retry_ids and not digital_shots:
                update("digital_humans", "failed", f"找不到需要重试的数字人镜头：{'、'.join(sorted(requested_retry_ids))}", progress=7)
                return
            if not digital_shots:
                update("digital_humans", "skipped", "数字人分支已并行检查：本次没有数字人镜头。", progress=7)
                return
            if not material_inputs["digital_human_images"]:
                # 没有用户形象图时按既定无数字人输入回退，不创建外部任务。
                # _apply_pending_digital_human_grid_fallback 会在首帧落盘后，
                # 用稳定选择的宫格图片生成本地短视频，保证混合说明镜头仍可渲染。
                _queue_digital_human_grid_fallback(
                    task_id,
                    [str(item.get("shot_id") or "") for item in all_digital_shots],
                    "未上传数字人形象图，按无输入回退到已有宫格首帧",
                )
                update("digital_humans", "running", "未上传数字人形象图，已排队使用已有宫格首帧回退。", progress=7)
                return
            missing_tts = _missing_digital_tts_assets(script_result, digital_shots)
            if missing_tts:
                update(
                    "digital_humans",
                    "blocked",
                    "数字人分支未启动：锁定 TTS 尚未全部落盘；请先等待编导/TTS 完成后再进入素材生产。缺失："
                    + "; ".join(missing_tts[:8]),
                    progress=7,
                )
                return
            try:
                try:
                    digital_auth = load_infinite_talk_auth_from_document(auth_document)
                except Exception as exc:
                    if not _is_digital_human_auth_error(exc):
                        raise
                    reason = f"{type(exc).__name__}: {str(exc)[:260]}"
                    _queue_digital_human_grid_fallback(
                        task_id,
                        [str(item.get("shot_id") or "") for item in all_digital_shots],
                        reason,
                    )
                    update(
                        "digital_humans",
                        "running",
                        "数字人后台登录/鉴权不可用，已跳过数字人调用；等待已有宫格首帧完成后自动替换对应坑位。",
                        progress=7,
                    )
                    return
                narration_by_group = _digital_narration_assets(script_result)
                image_paths = [Path(str(item)).expanduser() for item in material_inputs["digital_human_images"]]
                digital_dir = task_dir / "digital_humans"
                digital_dir.mkdir(parents=True, exist_ok=True)
                cache_path = _digital_human_cache_path(source_story_task_id)
                digital_cache = _load_digital_human_cache(cache_path)
                cache_entries = digital_cache["entries"]
                cache_dir = cache_path.parent / "digital_human_cache"
                audio_segment_dir = cache_path.parent / "digital_human_audio_cache"
                transport = RunningHubInfiniteTalkTransport(InfiniteTalkConfig(
                    api_key=digital_auth["api_key"],
                    health_check_seconds=0,
                    max_wait_seconds=None,
                    poll_interval_seconds=10,
                ))
                progress_lock = threading.Lock()
                existing_assets = result.get("digital_human_assets") if isinstance(result, Mapping) else {}
                existing_records = existing_assets.get("shot_results") if isinstance(existing_assets, Mapping) else []
                records: dict[str, dict] = {
                    str(item.get("shot_id") or ""): dict(item)
                    for item in existing_records or []
                    if isinstance(item, Mapping) and str(item.get("shot_id") or "") in {
                        str(item.get("shot_id") or "") for item in all_digital_shots
                    }
                }

                def persist(message: str, state: str = "running") -> None:
                    with progress_lock:
                        snapshot = _task_snapshot(task_id) or {}
                        live_result = dict(snapshot.get("result") or result)
                        ordered = [records[str(item["shot_id"])] for item in all_digital_shots if str(item["shot_id"]) in records]
                        live_result["digital_human_assets"] = {
                            "shot_results": ordered,
                            "task_ids": [str(item.get("task_id") or "") for item in ordered],
                            "video_paths": [str(item.get("video_path") or "") for item in ordered],
                            "succeeded_count": sum(item.get("status") == "succeeded" for item in ordered),
                            "failed_count": sum(item.get("status") == "failed" for item in ordered),
                        }
                        categories = dict(live_result.get("categories") or {})
                        categories["digital_humans"] = {
                            "label": "数字人",
                            "state": state,
                            "submitted": sum(item.get("status") in {"submitted", "succeeded", "failed"} for item in ordered),
                            "completed": sum(item.get("status") in {"succeeded", "failed"} for item in ordered),
                            "total": len(all_digital_shots),
                            "message": message,
                        }
                        live_result["categories"] = categories
                        denominator = max(1, len(all_digital_shots))
                        _set_task(task_id, state="running", stage="digital_humans", progress=7 + int(28 * len(ordered) / denominator), message=message, result=live_result, _preserve_terminal=True)

                def worker(index: int, shot: Mapping[str, object]) -> dict:
                    shot_id = str(shot.get("shot_id") or "")
                    group_id = str(shot.get("group_id") or "")
                    narration = narration_by_group.get(group_id)
                    if not isinstance(narration, Mapping):
                        raise RuntimeError(f"{shot_id} 缺少 {group_id} 的已锁定 TTS 音频登记")
                    audio_path, audio_window = _slice_digital_human_audio(
                        shot,
                        narration,
                        audio_segment_dir,
                    )
                    narration_text = str(shot.get("narration") or "").strip()
                    if not narration_text:
                        raise RuntimeError(f"{shot_id} 缺少逐镜脚本 narration，拒绝创建数字人任务")
                    image_path = image_paths[index % len(image_paths)]
                    if not image_path.is_file():
                        raise RuntimeError(f"{shot_id} 缺少数字人形象图：{image_path}")
                    cache_key = _digital_human_cache_key(shot, script_result, image_path, audio_path)
                    cached = cache_entries.get(cache_key) if isinstance(cache_entries, dict) else None
                    cached_path = Path(str(cached.get("video_path") or "")).expanduser() if isinstance(cached, Mapping) else Path()
                    if not cached_path.is_file() or cached_path.stat().st_size < 50_000:
                        cached_task_id = str(cached.get("task_id") or "") if isinstance(cached, Mapping) else ""
                        if cached_task_id:
                            terminal = transport.query({"api_key": digital_auth["api_key"], "task_ID": cached_task_id})
                            if str(terminal.get("status") or "") == "SUCCESS" and terminal.get("output_url"):
                                cached_path = _download_digital_output(str(terminal["output_url"]), cache_dir / f"{cache_key}.mp4")
                                cached = dict(cached)
                                cached.update(status="succeeded", video_path=str(cached_path.resolve()))
                                cache_entries[cache_key] = cached
                                _save_digital_human_cache(cache_path, digital_cache)
                            else:
                                cached = None
                                cache_entries.pop(cache_key, None)
                                _save_digital_human_cache(cache_path, digital_cache)
                    if cached_path.is_file() and cached_path.stat().st_size >= 50_000:
                        output = digital_dir / f"{shot_id}.mp4"
                        shutil.copy2(cached_path, output)
                        record = {
                            "shot_id": shot_id,
                            "group_id": group_id,
                            "task_id": str((cached or {}).get("task_id") or ""),
                            "status": "succeeded",
                            "video_path": str(output.resolve()),
                            "output_url_available": False,
                            "reused_paid_asset": True,
                            "reuse_cache_key": cache_key,
                            "narration": narration_text,
                            "start_us": int(audio_window["shot_start_us"]),
                            "end_us": int(audio_window["shot_end_us"]),
                            "duration_us": int(audio_window["duration_us"]),
                            "audio_path": str(audio_path.resolve()),
                            "audio_source_window": dict(audio_window),
                            "parameter_trace": (cached or {}).get("parameter_trace") or {"prompt_source": "director_locked_shot"},
                        }
                        records[shot_id] = record
                        persist(f"已复用已支付数字人 {sum(item.get('status') == 'succeeded' for item in records.values())}/{len(digital_shots)}：{shot_id}")
                        return record
                    image_url = _publish_digital_input(image_path, digital_auth, task_dir, "形象")
                    audio_url = _publish_digital_input(audio_path, digital_auth, task_dir, "音频")
                    create_params, parameter_trace = _digital_human_create_params(
                        shot,
                        script_result,
                        api_key=digital_auth["api_key"],
                        image_url=image_url,
                        audio_url=audio_url,
                    )
                    parameter_trace = {
                        **parameter_trace,
                        "narration_source": "shot_video_script.narration",
                        "audio_source": "group_tts_sliced_by_shot_timeline",
                        "audio_window_unit": "microseconds",
                    }
                    created = None
                    for attempt in range(3):
                        try:
                            created = transport.create(create_params)
                            break
                        except Exception as exc:
                            detail = str(exc).lower()
                            if "queue limit" not in detail and "http 421" not in detail:
                                raise
                            if attempt >= 2:
                                raise RuntimeError("RunningHub 数字人队列已满，连续退避 3 次仍未取得创建名额") from exc
                            wait_seconds = 20 * (attempt + 1)
                            persist(f"RunningHub 队列繁忙，数字人 {shot_id} 将于 {wait_seconds} 秒后重试（{attempt + 1}/3）")
                            time.sleep(wait_seconds)
                    if not isinstance(created, Mapping):
                        raise RuntimeError("RunningHub 创建任务没有返回结果")
                    task_run_id = str(created.get("task_ID") or "")
                    if not task_run_id:
                        raise RuntimeError("RunningHub 创建响应没有 task_ID")
                    record = {
                        "shot_id": shot_id,
                        "group_id": group_id,
                        "task_id": task_run_id,
                        "status": "submitted",
                        "narration": narration_text,
                        "start_us": int(audio_window["shot_start_us"]),
                        "end_us": int(audio_window["shot_end_us"]),
                        "duration_us": int(audio_window["duration_us"]),
                        "audio_path": str(audio_path.resolve()),
                        "audio_source_window": dict(audio_window),
                        "parameter_trace": parameter_trace,
                    }
                    cache_entries[cache_key] = {
                        "shot_id": shot_id,
                        "group_id": group_id,
                        "task_id": task_run_id,
                        "status": "submitted",
                        "narration": narration_text,
                        "start_us": int(audio_window["shot_start_us"]),
                        "end_us": int(audio_window["shot_end_us"]),
                        "duration_us": int(audio_window["duration_us"]),
                        "audio_source_window": dict(audio_window),
                        "parameter_trace": parameter_trace,
                    }
                    _save_digital_human_cache(cache_path, digital_cache)
                    records[shot_id] = record
                    persist(f"已创建数字人任务 {len(records)}/{len(digital_shots)}：{shot_id}")
                    terminal = transport.query({"api_key": digital_auth["api_key"], "task_ID": task_run_id})
                    if str(terminal.get("status") or "") != "SUCCESS" or not terminal.get("output_url"):
                        raise RuntimeError(str(terminal.get("msg") or "RunningHub 数字人任务未成功"))
                    output = _download_digital_output(str(terminal["output_url"]), digital_dir / f"{shot_id}.mp4")
                    cache_output = _download_digital_output(str(terminal["output_url"]), cache_dir / f"{cache_key}.mp4")
                    cache_entries[cache_key] = {
                        "shot_id": shot_id,
                        "group_id": group_id,
                        "task_id": task_run_id,
                        "status": "succeeded",
                        "video_path": str(cache_output.resolve()),
                        "narration": narration_text,
                        "start_us": int(audio_window["shot_start_us"]),
                        "end_us": int(audio_window["shot_end_us"]),
                        "duration_us": int(audio_window["duration_us"]),
                        "audio_path": str(audio_path.resolve()),
                        "audio_source_window": dict(audio_window),
                        "parameter_trace": parameter_trace,
                    }
                    _save_digital_human_cache(cache_path, digital_cache)
                    record.update(status="succeeded", video_path=str(output.resolve()), output_url_available=True)
                    records[shot_id] = record
                    persist(f"已完成数字人 {sum(item.get('status') == 'succeeded' for item in records.values())}/{len(digital_shots)}：{shot_id}")
                    return record

                # RunningHub InfiniteTalk 的 API 队列不是按 3 个并发任务开放；
                # 数字人分支仍与首帧/AIGC/BGM 并行，但本分支内部必须严格串行：
                # 当前镜头完成或失败后，才允许创建下一个镜头，避免平台队列拒绝。
                for index, shot in enumerate(digital_shots):
                    shot_id = str(shot.get("shot_id") or "")
                    try:
                        worker(index, shot)
                    except Exception as exc:
                        if _is_digital_human_auth_error(exc):
                            _queue_digital_human_grid_fallback(
                                task_id,
                                [str(item.get("shot_id") or "") for item in all_digital_shots],
                                f"{type(exc).__name__}: {str(exc)[:260]}",
                            )
                            persist(
                                "数字人后台登录/鉴权不可用，已停止后续数字人调用；等待已有宫格首帧完成后自动替换坑位。"
                            )
                            return
                        records[shot_id] = {
                            "shot_id": shot_id,
                            "status": "failed",
                            "error": f"{type(exc).__name__}: {str(exc)[:260]}",
                        }
                        persist(f"数字人镜头失败：{shot_id}；其余任务继续执行")
                succeeded = sum(item.get("status") == "succeeded" for item in records.values())
                failed = sum(item.get("status") == "failed" for item in records.values())
                persist(
                    f"数字人已完成 {succeeded}/{len(all_digital_shots)}；失败 {failed}，成功结果已保留。" if failed else f"数字人已完成 {succeeded}/{len(all_digital_shots)} 个镜头。",
                    "failed" if failed else "succeeded",
                )
            except Exception as exc:
                if _is_digital_human_auth_error(exc):
                    _queue_digital_human_grid_fallback(
                        task_id,
                        [str(item.get("shot_id") or "") for item in all_digital_shots],
                        f"{type(exc).__name__}: {str(exc)[:260]}",
                    )
                    update(
                        "digital_humans",
                        "running",
                        "数字人后台登录/鉴权不可用，已跳过数字人调用；等待已有宫格首帧完成后自动替换对应坑位。",
                        progress=7,
                    )
                    return
                update("digital_humans", "failed", f"数字人分支失败：{type(exc).__name__}：{str(exc)[:260]}", progress=35)

        def run_explanation_branch() -> None:
            """在首帧与数字人结果落盘后，执行 V3 说明镜头 Remotion 渲染。"""
            if branch_already_succeeded("explanation_videos", "explanation_assets"):
                previous_category = previous_result.get("categories", {}).get("explanation_videos") if isinstance(previous_result.get("categories"), Mapping) else {}
                update(
                    "explanation_videos",
                    "succeeded",
                    "恢复任务：复用已落盘说明镜头视频。",
                    int(previous_category.get("completed") or 0) if isinstance(previous_category, Mapping) else 0,
                    submitted=int(previous_category.get("submitted") or 0) if isinstance(previous_category, Mapping) else 0,
                    progress=92,
                )
                return
            explanation_shots = [
                item for item in shots
                if str(item.get("shot_class") or "") in {"explanation", "mixed_explanation"}
            ]
            if not explanation_shots:
                update("explanation_videos", "skipped", "当前 V3 脚本没有说明镜头。", progress=92)
                return
            live_result = dict((_task_snapshot(task_id) or {}).get("result") or result)
            update("explanation_videos", "running", f"首帧已完成，正在渲染 {len(explanation_shots)} 个说明镜头。", progress=84)
            try:
                render_width, render_height = _video_input_dimensions(resolved_aspect_ratio)
                explanation_dir = task_dir / "explanation"
                render_result = render_explanation_shots(
                    shots,
                    live_result,
                    explanation_dir,
                    packaging_override=live_result.get("remotion_settings")
                    if isinstance(live_result.get("remotion_settings"), Mapping)
                    else None,
                    width=render_width,
                    height=render_height,
                    fps=30,
                )
                latest = dict((_task_snapshot(task_id) or {}).get("result") or live_result)
                latest["explanation_assets"] = render_result
                _set_task(task_id, result=latest)
                update(
                    "explanation_videos",
                    "succeeded",
                    f"已完成 {render_result.get('succeeded_count', 0)} 个说明镜头 Remotion 渲染。",
                    int(render_result.get("succeeded_count") or 0),
                    submitted=int(render_result.get("succeeded_count") or 0),
                    progress=92,
                )
            except ExplanationRenderBlocked as exc:
                update("explanation_videos", "blocked", f"说明镜头未渲染：{str(exc)[:360]}", progress=92)
            except (ExplanationRenderError, ExplanationStyleLockError) as exc:
                update("explanation_videos", "failed", f"说明镜头渲染失败：{type(exc).__name__}：{str(exc)[:360]}", progress=92)
            except Exception as exc:
                update("explanation_videos", "failed", f"说明镜头分支异常：{type(exc).__name__}：{str(exc)[:360]}", progress=92)

        parallel_branches = None
        bgm_branch_future = None
        digital_branch_future = None
        parallel_branches = ThreadPoolExecutor(max_workers=2, thread_name_prefix="asset-branch")
        if only_digital:
            update("bgm", "skipped", "数字人补全模式：复用已有 BGM，不重新生成。", progress=5)
            digital_branch_future = parallel_branches.submit(run_digital_branch)
        else:
            bgm_branch_future = parallel_branches.submit(run_bgm_branch)
            digital_branch_future = parallel_branches.submit(run_digital_branch)

        if only_digital:
            digital_branch_future.result()
            parallel_branches.shutdown(wait=True)
            _apply_pending_digital_human_grid_fallback(task_id)
            result = dict((_task_snapshot(task_id) or {}).get("result") or result)
            result["evidence_level"] = "live_digital_human_retry"
            (task_dir / "asset_production.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
            digital_state = str((result.get("categories") or {}).get("digital_humans", {}).get("state") or "")
            if digital_state in {"failed", "blocked", "interrupted"}:
                final_message = "数字人补全任务部分失败；已保留成功结果和失败诊断，原首帧、AIGC 与 BGM 未重跑。"
                _set_task(task_id, state="failed", stage="digital_humans_retry_partial_failed", progress=100, message=final_message, result=result)
                _mark_voice_replacement_failed_preserved(task_id, final_message)
            else:
                _set_task(task_id, state="succeeded", stage="digital_humans_retry", progress=100, message="数字人补全任务已完成；首帧、AIGC 与 BGM 均复用原任务数据。", result=result)
                _commit_voice_replacement_after_asset_production(task_id)
            return

        image_state: dict = {}
        reused_first_frame = False
        # 同一素材任务的服务重启恢复不需要再次走 Image2；只要首帧裁切
        # 与 URL 已完整落盘，就直接进入依赖首帧的后续分支。
        if resume_from_checkpoint and isinstance(previous_result.get("first_frame_assets"), Mapping):
            persisted_images = dict(previous_result["first_frame_assets"])
            if _first_frame_assets_are_usable(persisted_images, image_shots):
                image_state = persisted_images
                reused_first_frame = True
        if not only_digital and base_asset_task_id:
            base_task = _task_snapshot(base_asset_task_id)
            base_result = base_task.get("result") if isinstance(base_task, Mapping) else None
            base_images = base_result.get("first_frame_assets") if isinstance(base_result, Mapping) else None
            if isinstance(base_images, Mapping):
                image_state = dict(base_images)
                base_paths = [str(value) for value in (base_images.get("image_paths") or []) if str(value or "").strip()]
                base_urls = [str(value) for value in (base_images.get("image_urls") or []) if str(value or "").strip()]
                if base_paths and (len(base_urls) < len(image_shots) or not all(url.startswith(("http://", "https://")) for url in base_urls[:len(image_shots)])):
                    base_urls = publish_existing_grid_images(
                        [Path(value) for value in base_paths[:len(image_shots)]],
                        auth_document,
                        task_dir / "first_frame_resume_publish.json",
                        force_refresh=False,
                    )
                    image_state["image_urls"] = list(base_urls)
                if _first_frame_assets_are_usable(image_state, image_shots):
                    result["first_frame_assets"] = image_state
                else:
                    image_state = {}
                    base_images = None
            if isinstance(base_images, Mapping) and image_state:
                reused_first_frame = True
                _set_task(
                    task_id,
                    result=result,
                    message="已复用原首帧裁切与 TOS URL，不重新创建首帧任务。",
                )
        if image_shots:
            image_total = len(image_shots)

            def on_image_progress(event: Mapping[str, object]) -> None:
                submitted = max(0, min(image_task_total, int(event.get("submitted") or 0)))
                completed = max(0, min(image_task_total, int(event.get("completed") or 0)))
                stage = str(event.get("stage") or "polling")
                if stage == "submitted":
                    stage_progress = 8 + int(12 * submitted / image_task_total)
                else:
                    stage_progress = 20 + int(22 * completed / image_task_total)
                update(
                    "first_frame_images",
                    "running",
                    str(event.get("message") or "正在并行生成首帧"),
                    completed,
                    submitted=submitted,
                    progress=stage_progress,
                )

            if reused_first_frame:
                update("first_frame_images", "succeeded", f"已复用原任务的 {image_total} 个首帧结果，未重复创建 Image2 任务", image_task_total, submitted=image_task_total, progress=42)
            else:
                update("first_frame_images", "running", f"准备创建 {image_task_total} 个 {grid_layout.replace('x', '×')} 宫格首帧任务，覆盖 {image_total} 个镜头", progress=8)
                image_state = generate_images_as_grids(
                    image_manifest,
                    auth_document,
                    task_dir,
                    grid_layout=grid_layout,
                    progress_reporter=on_image_progress,
                    checkpoint_path=task_dir / "first_frame_checkpoint.json",
                    resume=resume_from_checkpoint,
                    publish=True,
                )
            update("first_frame_images", "succeeded", f"已完成 {image_task_total} 个宫格首帧任务，已裁切回填 {image_total} 个镜头", image_task_total, submitted=image_task_total, progress=42)
            result = dict((_task_snapshot(task_id) or {}).get("result") or result)
            result["first_frame_assets"] = image_state
            _set_task(task_id, result=result)
        else:
            update("first_frame_images", "skipped", "编导锁定结果没有需要生成首帧的镜头", progress=42)

        video_shots = [item for item in shots if item.get("media_type") == "aigc_video"]
        if video_shots and branch_already_succeeded("aigc_videos", "aigc_video_assets"):
            previous_category = previous_result.get("categories", {}).get("aigc_videos") if isinstance(previous_result.get("categories"), Mapping) else {}
            update(
                "aigc_videos",
                "succeeded",
                "恢复任务：复用已落盘 AIGC 视频，不重新创建视频任务。",
                int(previous_category.get("completed") or len(video_shots)) if isinstance(previous_category, Mapping) else len(video_shots),
                submitted=int(previous_category.get("submitted") or len(video_shots)) if isinstance(previous_category, Mapping) else len(video_shots),
                progress=80,
            )
        elif video_shots:
            update("aigc_videos", "running", f"正在创建并轮询 {len(video_shots)} 个 Seedance 视频任务", progress=48)
            video_manifest = _asset_manifest_from_shots(
                video_shots, aspect_ratio=resolved_aspect_ratio
            )
            video_image_state = _prepare_video_input_image_state(
                image_state,
                image_shots,
                video_shots,
                aspect_ratio=resolved_aspect_ratio,
                auth_document=auth_document,
                task_dir=task_dir,
            )
            video_width, video_height = _video_input_dimensions(resolved_aspect_ratio)
            result["video_input"] = {
                "aspect_ratio": resolved_aspect_ratio,
                "width": video_width,
                "height": video_height,
                "normalized_count": len(image_shots),
            }
            _set_task(task_id, result=result)
            previous_video_records = (
                previous_result.get("aigc_video_assets", {}).get("shot_results")
                if isinstance(previous_result.get("aigc_video_assets"), Mapping)
                else []
            )
            partial_video_records: dict[str, dict] = {
                str(item.get("shot_id") or ""): dict(item)
                for item in (previous_video_records if isinstance(previous_video_records, list) else [])
                if isinstance(item, Mapping) and str(item.get("shot_id") or "").strip()
            } if resume_from_checkpoint else {}
            video_progress_lock = threading.Lock()

            def persist_video_record(record: Mapping[str, object], *, completed: int, message: str, progress: int) -> None:
                """创建成功即保存 task_id；进程重启后仍可凭它继续查询。"""
                shot_id = str(record.get("shot_id") or "")
                if not shot_id:
                    return
                with video_progress_lock:
                    partial_video_records[shot_id] = dict(record)
                    snapshot = _task_snapshot(task_id) or {}
                    live_result = dict(snapshot.get("result") or result)
                    live_records = [
                        partial_video_records[str(item.get("shot_id") or "")]
                        for item in video_shots
                        if str(item.get("shot_id") or "") in partial_video_records
                    ]
                    live_result["aigc_video_assets"] = {
                        "shot_results": live_records,
                        "video_task_ids": [str(item.get("task_id") or "") for item in live_records],
                        "video_paths": [str(item.get("video_path") or "") for item in live_records],
                        "succeeded_count": sum(item.get("status") == "succeeded" for item in live_records),
                        "failed_count": sum(item.get("status") == "failed" for item in live_records),
                        "submitted_count": sum(item.get("status") == "submitted" for item in live_records),
                    }
                    categories = dict(live_result.get("categories") or {})
                    category = dict(categories.get("aigc_videos") or {})
                    completed_now = sum(item.get("status") in {"succeeded", "failed"} for item in live_records)
                    failed_now = sum(item.get("status") == "failed" for item in live_records)
                    category_state = (
                        "running"
                        if completed_now < len(video_shots)
                        else ("failed" if failed_now else "succeeded")
                    )
                    category.update(
                        state=category_state,
                        submitted=sum(item.get("status") in {"submitted", "succeeded", "failed"} for item in live_records),
                        completed=completed_now,
                        total=len(video_shots),
                        message=message,
                    )
                    categories["aigc_videos"] = category
                    live_result["categories"] = categories
                    _set_task(task_id, state="running", stage="aigc_videos", progress=progress, message=message, result=live_result)

            def on_video_task_created(event: Mapping[str, object]) -> None:
                with video_progress_lock:
                    completed = sum(item.get("status") in {"succeeded", "failed"} for item in partial_video_records.values())
                persist_video_record(
                    event,
                    completed=completed,
                    message=f"已创建视频任务并保存断点：{event.get('shot_id') or ''}",
                    progress=48,
                )

            def on_video_progress(event: Mapping[str, object]) -> None:
                completed = int(event.get("completed") or 0)
                succeeded = int(event.get("succeeded") or 0)
                record = event.get("record") if isinstance(event.get("record"), Mapping) else {}
                failed = max(0, completed - succeeded)
                state = "running" if completed < len(video_shots) else ("failed" if failed else "succeeded")
                update(
                    "aigc_videos", state,
                    f"已完成查询 {completed}/{len(video_shots)}；成功 {succeeded}，当前镜头 {record.get('shot_id') or ''}",
                    succeeded, progress=48 + int(32 * completed / len(video_shots)),
                )
                if record:
                    persist_video_record(
                        record,
                        completed=completed,
                        message=f"已完成查询 {completed}/{len(video_shots)}；成功 {succeeded}，当前镜头 {record.get('shot_id') or ''}",
                        progress=48 + int(32 * completed / len(video_shots)),
                    )

            video_state = generate_videos(
                video_manifest, video_image_state, auth_document, task_dir,
                progress_reporter=on_video_progress,
                task_created_reporter=on_video_task_created,
                existing_records=previous_video_records if resume_from_checkpoint and isinstance(previous_video_records, list) else None,
                resume=resume_from_checkpoint,
            )
            result = dict((_task_snapshot(task_id) or {}).get("result") or result)
            result["aigc_video_assets"] = video_state
            _set_task(task_id, result=result)
            if int(video_state.get("failed_count") or 0):
                failed = [str(item.get("shot_id")) for item in video_state.get("shot_results", []) if isinstance(item, Mapping) and item.get("status") == "failed"]
                update(
                    "aigc_videos",
                    "failed",
                    f"AIGC 视频部分失败：{', '.join(failed)}；成功视频已保留，可在页面预览并单独补跑。",
                    int(video_state.get("succeeded_count") or 0),
                    submitted=len(video_state.get("shot_results") or []),
                    progress=80,
                )
            else:
                update("aigc_videos", "succeeded", f"已生成 {len(video_shots)} 个 AIGC 视频", len(video_shots), progress=80)
        else:
            update("aigc_videos", "skipped", "编导锁定结果没有 AIGC 视频镜头", progress=80)

        # 等待并行分支写入自己的最终状态；数字人从素材准备阶段即开始，不依赖 AIGC 完成。
        if bgm_branch_future is not None:
            bgm_branch_future.result()
        if digital_branch_future is not None:
            digital_branch_future.result()
        if parallel_branches is not None:
            parallel_branches.shutdown(wait=True)
        _apply_pending_digital_human_grid_fallback(task_id)
        # 说明镜头必须等待首帧和混合说明镜头所需的同任务数字人视频均落盘。
        run_explanation_branch()
        result = dict((_task_snapshot(task_id) or {}).get("result") or result)
        # v3.2 音效是独立业务分支：只读取已经锁定的计划，不触碰视觉资产。
        # 默认走本地音效库，避免选择 v3.2 就隐式产生外部费用；真实
        # Seed-Audio 需由调用方显式注入 transport。
        locked_for_sfx = result.get("director_lock") if isinstance(result.get("director_lock"), Mapping) else {}
        sfx_plan = locked_for_sfx.get("sound_effect_plan") if isinstance(locked_for_sfx, Mapping) else []
        if isinstance(sfx_plan, list) and sfx_plan:
            library_root = ROOT / "outputs"
            sfx_transport = None
            if library_root.is_dir() and any(library_root.rglob("*.mp3")):
                sfx_transport = local_library_transport(library_root)
            prior_sfx_rows = (previous_result.get("sound_effect_assets") or {}).get("shot_results") if isinstance(previous_result.get("sound_effect_assets"), Mapping) else []
            prior_sfx = {
                str(item.get("shot_id")): dict(item)
                for item in (prior_sfx_rows if isinstance(prior_sfx_rows, list) else [])
                if isinstance(item, Mapping) and str(item.get("shot_id") or "").strip()
            }
            sfx_result = produce_sound_effects(
                locked_for_sfx,
                media_route_lock=result.get("media_route_lock") if isinstance(result.get("media_route_lock"), Mapping) else None,
                provider="library",
                transport=sfx_transport,
                existing_results=prior_sfx,
            )
            result["sound_effect_assets"] = sfx_result
            result["sound_effect_plan"] = list(sfx_plan)
            sfx_failed = int(sfx_result.get("failed_count") or 0)
            update(
                "sound_effects",
                "failed" if sfx_failed else ("needs_review" if any(str(item.get("status") or "") == "needs_review" for item in sfx_result.get("shot_results", []) if isinstance(item, Mapping)) else "succeeded"),
                "独立音效分支已完成本地库校验；未自动调用外部 Seed-Audio。",
                int(sfx_result.get("generated_count") or 0),
                submitted=int(sfx_result.get("generated_count") or 0),
                progress=96,
            )
        result["evidence_level"] = "live_image2_and_seedance_partial"
        if task_dir is not None:
            task_dir.mkdir(parents=True, exist_ok=True)
            (task_dir / "asset_production.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
        categories = result.get("categories") if isinstance(result.get("categories"), Mapping) else {}
        failed_categories = [
            str(key) for key, value in categories.items()
            if isinstance(value, Mapping) and str(value.get("state") or "") in {"failed", "blocked", "interrupted"}
        ]
        if failed_categories:
            failed_messages = [
                str(value.get("message") or key)
                for key, value in categories.items()
                if key in failed_categories and isinstance(value, Mapping)
            ]
            final_message = "素材生产部分完成；已保留成功资产，失败分支可单独补跑。" + " ".join(failed_messages[:3])
            _set_task(
                task_id,
                state="failed",
                stage="asset_production_partial_failed",
                progress=100,
                message=final_message[:500],
                result=result,
            )
            _mark_voice_replacement_failed_preserved(task_id, final_message)
        else:
            _set_task(task_id, state="succeeded", stage="asset_production_completed", progress=100, message="首帧、AIGC、BGM、数字人与说明镜头分支均已完成；结果已落盘并可继续交给剪辑层。", result=result)
            _commit_voice_replacement_after_asset_production(task_id)
    except Exception as exc:
        TASK_LOGGER.exception("asset production task %s crashed", task_id)
        detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:320]
        snapshot = _task_snapshot(task_id) or {}
        preserved_result = dict(snapshot.get("result") or result)
        preserved_result = mark_failed_category(
            preserved_result,
            str(snapshot.get("stage") or ""),
            detail,
        )
        if task_dir is not None:
            try:
                task_dir.mkdir(parents=True, exist_ok=True)
                (task_dir / "asset_production.json").write_text(json.dumps(preserved_result, ensure_ascii=False, indent=2), encoding="utf-8")
            except OSError:
                TASK_LOGGER.exception("asset production result persistence failed for %s", task_id)
        _set_task(
            task_id,
            state="failed",
            stage="asset_production_failed",
            progress=100 if preserved_result else 0,
            message=f"素材生产失败：{type(exc).__name__}：{detail or '无错误详情'}；已保留已生成资产。",
            result=preserved_result,
        )
        _mark_voice_replacement_failed_preserved(
            task_id,
            f"{type(exc).__name__}: {detail or '无错误详情'}",
        )


def _create_asset_production_task(
    source_story_task_id: str,
    *,
    grid_layout: str = "3x3",
    mode: str = "full",
    base_asset_task_id: str = "",
    aspect_ratio: str | None = None,
    retry_shot_id: str = "",
    retry_shot_ids: list[str] | None = None,
    remotion_settings: Mapping[str, object] | None = None,
    force_rebuild: bool = False,
) -> dict:
    # 素材页允许从运行归档恢复旧故事。归档任务仍是只读的上游快照，
    # 新建素材任务时接管它即可，不能因为服务重启后不在内存而误报缺失。
    story_task = _handoff_story_task_snapshot(source_story_task_id)
    if not story_task or story_task.get("task_type") != "director_story_review" or story_task.get("state") != "succeeded":
        raise ValueError("未找到已完成的v2 编导任务")
    if (story_task.get("result") or {}).get("review_status") != "APPROVED":
        raise ValueError("故事尚未确认，不能执行素材生产")
    shot_script_task = _latest_shot_script_task(source_story_task_id)
    shot_script_result = shot_script_task.get("result") if isinstance(shot_script_task.get("result"), Mapping) else {}
    if shot_script_result.get("review_status") != "APPROVED":
        raise ValueError("最终视频脚本尚未确认，不能执行素材生产；请先回编导层确认")
    if grid_layout not in {"2x2", "3x3"}:
        raise ValueError("首帧宫格仅支持 2×2 或 3×3")
    requested_aspect_ratio = str(aspect_ratio or "").strip()
    if requested_aspect_ratio and requested_aspect_ratio not in SUPPORTED_ASPECT_RATIOS:
        raise ValueError("画幅仅支持 9:16、16:9、1:1、3:2、2:3")
    director_aspect_ratio = normalize_aspect_ratio(
        (story_task.get("result") or {}).get("aspect_ratio") or "9:16"
    )
    resolved_aspect_ratio = normalize_aspect_ratio(requested_aspect_ratio or director_aspect_ratio)
    if mode not in {"full", "digital_only"}:
        raise ValueError("素材任务模式无效")
    digital_shots = [
        item for item in shot_script_result.get("shot_video_script") or []
        if isinstance(item, Mapping) and _shot_requires_digital_human(item)
    ]
    retry_shot_id = str(retry_shot_id or "").strip()
    retry_ids = list(dict.fromkeys(
        str(item or "").strip() for item in (retry_shot_ids or []) if str(item or "").strip()
    ))
    if retry_shot_id and retry_shot_id not in retry_ids:
        retry_ids.append(retry_shot_id)
    if retry_ids and mode != "digital_only":
        raise ValueError("单镜头重试仅支持数字人补全模式")
    digital_ids = {str(item.get("shot_id") or "") for item in digital_shots}
    invalid_retry_ids = [item for item in retry_ids if item not in digital_ids]
    if invalid_retry_ids:
        raise ValueError("指定的数字人镜头不在当前冻结逐镜脚本中：" + "、".join(invalid_retry_ids))
    if mode == "digital_only":
        missing_tts = _missing_digital_tts_assets(shot_script_result, digital_shots)
        if missing_tts:
            raise ValueError(
                "数字人素材任务未启动：锁定 TTS 尚未全部落盘；请等待编导/TTS 任务完成后再试。缺失："
                + "; ".join(missing_tts[:8])
            )
    if mode == "digital_only":
        base = _task_snapshot(base_asset_task_id)
        if not base or base.get("task_type") != "asset_production":
            raise ValueError("未找到可用于数字人补全的原素材任务")
    if mode == "full" and base_asset_task_id:
        base = _task_snapshot(base_asset_task_id)
        base_result = base.get("result") if isinstance(base, Mapping) else None
        base_images = base_result.get("first_frame_assets") if isinstance(base_result, Mapping) else None
        if not base or base.get("task_type") != "asset_production" or not isinstance(base_images, Mapping):
            raise ValueError("未找到可复用首帧结果的原素材任务")
    normalized_remotion_settings = normalize_style_override(remotion_settings)
    input_payload = {
        "source_story_task_id": source_story_task_id,
        "grid_layout": grid_layout,
        "aspect_ratio": resolved_aspect_ratio,
        "mode": mode,
        "base_asset_task_id": base_asset_task_id,
        "retry_shot_ids": retry_ids,
        "remotion_settings": normalized_remotion_settings,
    }
    input_fingerprint = _task_input_fingerprint("asset_production", input_payload)
    # 页面刷新或重复点击不能创建第二条可能收费的素材任务。失败任务
    # 由专用 retry-* 入口处理；普通创建入口只复用已有任务快照。
    candidates: list[dict] = []
    with STYLE_TASKS_LOCK:
        candidates.extend(dict(item) for item in STYLE_TASKS.values() if isinstance(item, Mapping))
    candidates.extend(_persisted_task_snapshots())
    seen_ids: set[str] = set()
    for candidate in ([] if force_rebuild else candidates):
        candidate_id = str(candidate.get("task_id") or "").strip()
        if not candidate_id or candidate_id in seen_ids or candidate.get("task_type") != "asset_production":
            continue
        seen_ids.add(candidate_id)
        candidate_input = candidate.get("input") if isinstance(candidate.get("input"), Mapping) else {}
        candidate_fingerprint = str(candidate.get("input_fingerprint") or _task_input_fingerprint("asset_production", candidate_input))
        if candidate_fingerprint != input_fingerprint:
            continue
        state = str(candidate.get("state") or "")
        if state in {"queued", "running", "interrupted", "succeeded", "failed"}:
            reused = dict(candidate)
            reused["deduplicated"] = True
            reused["deduplication_message"] = (
                "已复用相同输入的素材任务；成功资产不会重复生成，失败分支请使用专用重试入口。"
            )
            return reused
    task_id = uuid.uuid4().hex
    now = int(time.time())
    task = {"task_id": task_id, "task_type": "asset_production", "source_story_task_id": source_story_task_id, "input": input_payload, "input_fingerprint": input_fingerprint, "grid_layout": grid_layout, "aspect_ratio": resolved_aspect_ratio, "aspect_ratio_source": "asset_user_override" if requested_aspect_ratio else "director_locked", "mode": mode, "base_asset_task_id": base_asset_task_id, "retry_shot_ids": retry_ids,
            "state": "queued", "stage": "queued", "progress": 0, "message": "素材生产任务正在排队", "created_at": now, "updated_at": now}
    with STYLE_TASKS_LOCK:
        STYLE_TASKS[task_id] = task
    # 素材任务不能只存在内存，否则重启可能重复调用外部素材接口。
    try:
        _persist_task_required(task)
    except TaskPersistenceError:
        with STYLE_TASKS_LOCK:
            STYLE_TASKS.pop(task_id, None)
        raise
    threading.Thread(target=_run_asset_production_task, args=(task_id, source_story_task_id, grid_layout), kwargs={"mode": mode, "base_asset_task_id": base_asset_task_id, "aspect_ratio": resolved_aspect_ratio, "retry_shot_id": retry_shot_id, "retry_shot_ids": retry_ids}, daemon=True).start()
    return _task_snapshot(task_id) or {"task_id": task_id}


def _asset_checkpoint_path(task: Mapping[str, object]) -> Path | None:
    """Return the durable first-frame checkpoint for an asset task."""

    result = task.get("result")
    output_dir = result.get("output_dir") if isinstance(result, Mapping) else None
    if not output_dir:
        return None
    try:
        return Path(str(output_dir)).expanduser() / "first_frame_checkpoint.json"
    except (TypeError, ValueError, OSError):
        return None


def _asset_checkpoint_exists(task: Mapping[str, object]) -> bool:
    path = _asset_checkpoint_path(task)
    try:
        return bool(path and path.is_file())
    except OSError:
        return False


def _asset_grid_entry_has_recoverable_handle(entry: Mapping[str, object]) -> bool:
    return bool(
        str(entry.get("local_grid_path") or "").strip()
        or str(entry.get("image_url") or "").strip()
        or str(entry.get("task_id") or "").strip()
    )


def _asset_expected_grid_ids(task: Mapping[str, object], checkpoint: Mapping[str, object]) -> list[str]:
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    categories = result.get("categories") if isinstance(result, Mapping) else {}
    first_frame = categories.get("first_frame_images") if isinstance(categories, Mapping) else {}
    first_frame = first_frame if isinstance(first_frame, Mapping) else {}
    try:
        total = int(first_frame.get("total") or 0)
    except (TypeError, ValueError):
        total = 0
    if total > 0:
        return [f"first_frame_grid_{index:03d}" for index in range(1, total + 1)]
    batches = checkpoint.get("batches")
    if isinstance(batches, Mapping):
        return sorted(str(key) for key in batches.keys() if str(key).strip())
    return []


def _asset_checkpoint_has_resumable_grid_handles(task: Mapping[str, object]) -> bool:
    """Return true only when every required grid can be queried or reused."""

    path = _asset_checkpoint_path(task)
    if not path or not path.is_file():
        return False
    try:
        checkpoint = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    batches = checkpoint.get("batches")
    if not isinstance(batches, Mapping) or not batches:
        return False
    merged: dict[str, dict[str, object]] = {
        str(key): dict(value) if isinstance(value, Mapping) else {}
        for key, value in batches.items()
    }
    handle_dir = path.with_name(f"{path.stem}.handles")
    if handle_dir.is_dir():
        for handle_path in handle_dir.glob("*.json"):
            try:
                handle = json.loads(handle_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(handle, Mapping):
                continue
            grid_id = str(handle.get("grid_id") or handle_path.stem).strip()
            if not grid_id:
                continue
            entry = dict(merged.get(grid_id) or {})
            entry.update(dict(handle))
            merged[grid_id] = entry
    expected_grid_ids = _asset_expected_grid_ids(task, checkpoint)
    # 旧素材快照可能在重生成阶段只保留了最后一个宫格句柄；
    # 该状态不能阻止用户通过“重新生成全部宫格”开启新一轮。
    if not expected_grid_ids:
        return False
    return all(
        isinstance(merged.get(grid_id), Mapping)
        and _asset_grid_entry_has_recoverable_handle(merged[grid_id])
        for grid_id in expected_grid_ids
    )


def _asset_task_has_unrecoverable_grid_checkpoint(task: Mapping[str, object]) -> bool:
    """Return true when first-frame checkpoint cannot be safely resumed."""

    if str(task.get("task_type") or "") != "asset_production":
        return False
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    categories = result.get("categories") if isinstance(result, Mapping) else {}
    first_frame = categories.get("first_frame_images") if isinstance(categories, Mapping) else {}
    first_frame = first_frame if isinstance(first_frame, Mapping) else {}
    text = " ".join(
        str(value or "")
        for value in (
            task.get("message"),
            task.get("error_detail"),
            first_frame.get("message"),
        )
    )
    ambiguous = (
        str(first_frame.get("state") or "").lower() in {"blocked", "failed", "interrupted"}
        or any(marker in text for marker in ("状态不明确", "避免重复付费", "provider task_id", "taskId", "task_id"))
    )
    return bool(
        ambiguous
        and _asset_checkpoint_exists(task)
        and not _asset_checkpoint_has_resumable_grid_handles(task)
    )


def _raise_grid_checkpoint_unrecoverable() -> None:
    raise ValueError(
        "首帧宫格断点缺少已创建任务的 task_id/图片URL，系统不会重复创建付费图片任务；"
        "请重新运行首帧批次，或等待包含完整 task_id 的断点自动恢复。"
    )


def _asset_task_can_resume_from_checkpoint(task: Mapping[str, object]) -> bool:
    """判断素材任务是否可以只查询已有的首帧 provider 句柄。"""

    if str(task.get("task_type") or "") != "asset_production":
        return False
    state = str(task.get("state") or "")
    if state in {"queued", "running", "interrupted"} and (
        str(task.get("error_code") or "") == "executor_restarted"
        or str(task.get("stage") or "") == "executor_restarted"
    ):
        result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
        categories = result.get("categories") if isinstance(result, Mapping) else {}
        first_frame = categories.get("first_frame_images") if isinstance(categories, Mapping) else {}
        if isinstance(first_frame, Mapping) and str(first_frame.get("state") or "").lower() == "succeeded":
            # 首帧已完整落盘时，恢复只负责继续未完成的后续分支，不再校验
            # 旧 Image2 断点，也不会再次创建图片任务。
            return True
        return bool(_asset_checkpoint_has_resumable_grid_handles(task))
    if state != "failed":
        return False
    task_input = task.get("input") if isinstance(task.get("input"), Mapping) else {}
    mode = str(task.get("mode") or task_input.get("mode") or "").strip().lower()
    if mode != "full":
        return False
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    categories = result.get("categories") if isinstance(result, Mapping) else {}
    first_frame = categories.get("first_frame_images") if isinstance(categories, Mapping) else {}
    if not isinstance(first_frame, Mapping):
        return False
    if str(first_frame.get("state") or "").lower() not in {"failed", "interrupted"}:
        return False
    return bool(_asset_checkpoint_has_resumable_grid_handles(task))


def _asset_resume_metadata(task: Mapping[str, object]) -> dict:
    """Expose a safe, path-free resume capability flag to the assets page.

    A task is clickable-recoverable only when the executor marked it as a
    restart interruption *and* the durable first-frame checkpoint exists.
    The UI must not infer recoverability from a progress percentage or from
    an old result payload, because doing so could create a duplicate paid
    image task after a restart.
    """

    snapshot = dict(task)
    if str(snapshot.get("task_type") or "") != "asset_production":
        return snapshot
    interrupted = (
        str(snapshot.get("state") or "") == "interrupted"
        and str(snapshot.get("error_code") or "") == "executor_restarted"
    )
    failed_query_resume = (
        str(snapshot.get("state") or "") == "failed"
        and _asset_task_can_resume_from_checkpoint(snapshot)
    )
    checkpoint_exists = _asset_checkpoint_exists(snapshot)
    available = bool(interrupted or failed_query_resume)
    snapshot["asset_resume_available"] = available
    if failed_query_resume or available:
        snapshot["asset_resume_status"] = "available"
    elif interrupted and not checkpoint_exists:
        snapshot["asset_resume_status"] = "missing_checkpoint"
    elif interrupted:
        snapshot["asset_resume_status"] = "missing_provider_handle"
    else:
        snapshot["asset_resume_status"] = "not_applicable"
    if failed_query_resume:
        snapshot["asset_resume_message"] = "上次外部查询超时；可继续查询已提交宫格，不会新建付费任务。"
    if interrupted and not available:
        snapshot["asset_resume_message"] = "首帧断点缺少已创建任务的 task_id/图片URL，不能安全自动恢复；系统不会重复创建付费图片任务。"
    return snapshot


def _resume_asset_production_task(task_id: str, *, automatic: bool = False) -> dict:
    """Resume one interrupted asset task from its per-grid checkpoint.

    The same task id and output directory are reused.  Existing BGM, digital
    human, video and explanation records are preserved by the worker; only a
    missing first-frame grid is queried or created.
    """

    requested_id = str(task_id or "").strip()
    task = _task_snapshot(requested_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到可恢复的素材生产任务")
    if not _asset_task_can_resume_from_checkpoint(task):
        raise ValueError("仅服务重启中断，或首帧查询超时且保留完整 provider task_id 的素材任务可以恢复")
    if not _asset_checkpoint_exists(task):
        raise ValueError("该素材任务没有首帧断点，已阻止自动重新创建付费任务")
    result_for_resume = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    categories_for_resume = result_for_resume.get("categories") if isinstance(result_for_resume, Mapping) else {}
    first_frame_for_resume = categories_for_resume.get("first_frame_images") if isinstance(categories_for_resume, Mapping) else {}
    first_frame_completed = isinstance(first_frame_for_resume, Mapping) and str(first_frame_for_resume.get("state") or "").lower() == "succeeded"
    if not first_frame_completed and not _asset_checkpoint_has_resumable_grid_handles(task):
        raise ValueError("首帧断点缺少已创建任务的 task_id/图片URL，不能安全自动恢复；系统不会重复创建付费图片任务。")
    task_input = task.get("input") if isinstance(task.get("input"), Mapping) else {}
    source_story_task_id = str(task.get("source_story_task_id") or task_input.get("source_story_task_id") or "").strip()
    if not source_story_task_id:
        raise ValueError("素材任务缺少 source_story_task_id，无法恢复")
    grid_layout = str(task.get("grid_layout") or task_input.get("grid_layout") or "3x3")
    mode = str(task.get("mode") or task_input.get("mode") or "full")
    base_asset_task_id = str(task.get("base_asset_task_id") or task_input.get("base_asset_task_id") or "")
    aspect_ratio = str(task.get("aspect_ratio") or task_input.get("aspect_ratio") or "")
    retry_ids = [
        str(value or "").strip()
        for value in (task.get("retry_shot_ids") or task_input.get("retry_shot_ids") or [])
        if str(value or "").strip()
    ]
    with ASSET_RESUME_LOCK:
        if requested_id in ASSET_RESUME_TASKS:
            return _task_snapshot(requested_id) or dict(task)
        ASSET_RESUME_TASKS.add(requested_id)
    failed_query_resume = str(task.get("state") or "") == "failed"
    resume_message = (
        "上次外部查询超时，已从首帧断点继续查询：只复用已提交宫格，不新建付费任务。"
        if failed_query_resume
        else (
            "服务重启后已自动恢复首帧断点：已提交的宫格继续查询，已落盘宫格不重复调用；"
            "已完成的其他素材保持不变。"
            if automatic
            else "已从首帧断点恢复：已提交的宫格继续查询，已落盘宫格不重复调用。"
        )
    )
    try:
        _set_task(
            requested_id,
            state="queued",
            stage="asset_recovery_queued",
            progress=max(1, int(task.get("progress") or 0)),
            message=resume_message,
            error_code="",
            error_detail="",
            _allow_interrupted_resume=True,
        )

        def run_resume() -> None:
            try:
                _run_asset_production_task(
                    requested_id,
                    source_story_task_id,
                    grid_layout,
                    mode=mode,
                    base_asset_task_id=base_asset_task_id,
                    aspect_ratio=aspect_ratio or None,
                    retry_shot_ids=retry_ids,
                    resume_from_checkpoint=True,
                )
            finally:
                with ASSET_RESUME_LOCK:
                    ASSET_RESUME_TASKS.discard(requested_id)

        threading.Thread(
            target=run_resume,
            name=f"asset-resume-{requested_id[:12]}",
            daemon=True,
        ).start()
    except Exception:
        with ASSET_RESUME_LOCK:
            ASSET_RESUME_TASKS.discard(requested_id)
        raise
    return _task_snapshot(requested_id) or dict(task)


def _automatic_asset_resume_enabled() -> bool:
    """Return whether startup may resume external asset tasks.

    Asset recovery can issue long-running provider queries as soon as the
    console starts.  That is unsafe for the normal page/server startup path:
    an old interrupted task can make the service appear to run for hours and
    can compete with a task the user explicitly starts from the page.  Keep
    recovery available as an explicit opt-in for an operator who has checked
    the persisted checkpoints.
    """

    return os.environ.get(AUTO_RESUME_ASSETS_ENV, "").strip() == "1"


def _auto_resume_asset_tasks() -> list[str]:
    """Resume checkpointed asset tasks only after an explicit opt-in.

    The page-level "继续查询已提交宫格" action still calls
    ``_resume_asset_production_task`` directly and is unaffected by this
    startup gate.  This function is deliberately guarded as well as gated at
    ``__main__`` so accidental future callers cannot silently restart paid or
    long-running provider polling.
    """

    if not _automatic_asset_resume_enabled():
        TASK_LOGGER.info(
            "automatic asset recovery disabled; set %s=1 to opt in",
            AUTO_RESUME_ASSETS_ENV,
        )
        return []

    resumed: list[str] = []
    for task in _persisted_task_snapshots():
        if not isinstance(task, Mapping) or task.get("task_type") != "asset_production":
            continue
        if str(task.get("state") or "") != "interrupted" or str(task.get("error_code") or "") != "executor_restarted":
            continue
        if not _asset_checkpoint_has_resumable_grid_handles(task):
            continue
        task_id = str(task.get("task_id") or "").strip()
        if not task_id:
            continue
        try:
            _resume_asset_production_task(task_id, automatic=True)
            resumed.append(task_id)
        except Exception as exc:
            TASK_LOGGER.warning("asset task %s automatic recovery skipped: %s", task_id, exc)
    if resumed:
        TASK_LOGGER.info("automatic asset recovery started for %d task(s)", len(resumed))
    return resumed


def _recover_completed_video_records(task_dir: Path, video_shots: list[dict], records: list[dict]) -> list[dict]:
    """从本机已下载视频恢复成功记录，避免控制台重启后重复计费。"""
    by_shot = {str(item.get("shot_id") or ""): dict(item) for item in records}
    for index, shot in enumerate(video_shots, start=1):
        shot_id = str(shot.get("shot_id") or "")
        path = task_dir / "videos" / f"video_{index:02d}.mp4"
        record = by_shot.get(shot_id)
        if path.is_file() and path.stat().st_size >= 50_000 and not (record and record.get("status") == "succeeded"):
            by_shot[shot_id] = {
                "index": index - 1,
                "shot_id": shot_id,
                "task_id": str((record or {}).get("task_id") or ""),
                "status": "succeeded",
                "video_path": str(path.resolve()),
                "recovered_from_local_file": True,
            }
    return [by_shot[str(item.get("shot_id") or "")] for item in video_shots if str(item.get("shot_id") or "") in by_shot]


def _reconcile_local_video_retry(task: dict) -> dict:
    """Recover a completed paid retry when the worker exited before snapshot persistence."""
    if task.get("task_type") != "asset_production":
        return task
    result = task.get("result")
    assets = result.get("aigc_video_assets") if isinstance(result, dict) else None
    records = assets.get("shot_results") if isinstance(assets, dict) else None
    output_dir = Path(str(result.get("output_dir") or "")).expanduser() if isinstance(result, dict) else Path()
    if not isinstance(records, list) or not records or not output_dir.is_dir():
        return task
    failed = [dict(item) for item in records if isinstance(item, dict) and item.get("status") == "failed"]
    if not failed:
        return task
    retry_root = output_dir / "video_retries"
    retry_dirs = []
    if retry_root.is_dir():
        retry_dirs = sorted((item for item in retry_root.iterdir() if item.is_dir()), key=lambda item: item.stat().st_mtime, reverse=True)
    retry_dir = next((item for item in retry_dirs if len(list((item / "videos").glob("video_*.mp4"))) >= len(failed)), None)
    if retry_dir is None:
        return task
    retry_files = sorted((retry_dir / "videos").glob("video_*.mp4"), key=lambda item: item.name)
    if any(not item.is_file() or item.stat().st_size < 50_000 for item in retry_files[:len(failed)]):
        return task
    failed_iter = iter(retry_files)
    recovered_records = []
    for record in records:
        item = dict(record)
        if item.get("status") == "failed":
            path = next(failed_iter)
            item.update(status="succeeded", video_path=str(path.resolve()), recovered_from_local_file=True)
            item.pop("error", None)
        recovered_records.append(item)
    latest_result = dict(result)
    latest_assets = dict(assets)
    latest_assets.update(
        shot_results=recovered_records,
        video_task_ids=[str(item.get("task_id") or "") for item in recovered_records],
        video_paths=[str(item.get("video_path") or "") for item in recovered_records],
        succeeded_count=len(recovered_records),
        failed_count=0,
    )
    latest_result["aigc_video_assets"] = latest_assets
    latest_result.setdefault("video_input", {"aspect_ratio": "9:16", "width": 720, "height": 1280, "normalized_count": len(recovered_records)})
    categories = dict(latest_result.get("categories") or {})
    video_category = dict(categories.get("aigc_videos") or {})
    video_category.update(state="succeeded", completed=len(recovered_records), total=len(recovered_records), message="已从本机补跑视频文件恢复成功状态，未重复调用模型。")
    categories["aigc_videos"] = video_category
    latest_result["categories"] = categories
    task = dict(task, state="succeeded", stage="asset_production_partial", progress=100, message="已恢复本机补跑成品；首帧与 AIGC 视频数据可继续复用。", result=latest_result, updated_at=int(time.time()))
    # 本地文件恢复是只读读取路径；若恢复快照写回失败，仍保留原状态供诊断。
    _persist_task(task)
    return task


def _retry_failed_asset_videos(asset_task_id: str, shot_id: str | None = None) -> dict:
    """补跑失败或中断缺失的视频，始终复用本机已完成首帧和视频。"""
    task = _task_snapshot(asset_task_id)
    if not task or task.get("task_type") != "asset_production":
        raise ValueError("未找到素材生产任务")
    if _asset_task_has_unrecoverable_grid_checkpoint(task):
        _raise_grid_checkpoint_unrecoverable()
    result = dict(task.get("result") or {})
    source_story_task_id = str(task.get("source_story_task_id") or "")
    script_task = _latest_shot_script_task(source_story_task_id)
    script_result = dict(script_task.get("result") or {})
    all_shots = [dict(item) for item in script_result.get("shot_video_script") or [] if isinstance(item, dict)]
    image_shots = [item for item in all_shots if item.get("first_frame_prompt")]
    video_shots = [item for item in all_shots if item.get("media_type") == "aigc_video"]
    task_dir = Path(str(result.get("output_dir") or "")).expanduser()
    if not str(task_dir):
        raise ValueError("当前任务缺少输出目录")
    task_dir.mkdir(parents=True, exist_ok=True)
    existing = dict(result.get("aigc_video_assets") or {})
    records = [dict(item) for item in existing.get("shot_results") or [] if isinstance(item, dict)]
    records = _recover_completed_video_records(task_dir, video_shots, records)
    selected_shot_id = str(shot_id or "").strip()
    video_ids = {str(item.get("shot_id") or "") for item in video_shots}
    if selected_shot_id and selected_shot_id not in video_ids:
        raise ValueError("指定的 AIGC 镜头不在当前冻结逐镜脚本中")
    existing_by_id = {str(item.get("shot_id") or ""): item for item in records}
    selected_record = existing_by_id.get(selected_shot_id) if selected_shot_id else None
    if selected_record and selected_record.get("status") == "succeeded":
        raise ValueError(f"{selected_shot_id} 已有成功视频，不能重复付费生成")
    if selected_record and selected_record.get("status") in {"submitted", "running"}:
        raise ValueError(f"{selected_shot_id} 仍在生成中，请等待当前任务结束")
    retry_ids = ({selected_shot_id} if selected_shot_id else {str(item.get("shot_id") or "") for item in video_shots}) - {
        str(item.get("shot_id") or "") for item in records if item.get("status") == "succeeded"
    }
    retry_shots = [item for item in video_shots if str(item.get("shot_id") or "") in retry_ids]
    if not retry_shots:
        raise ValueError("当前镜头没有需要补跑的 AIGC 视频；本机已完成视频均已复用")
    image_state = result.get("first_frame_assets")
    if not isinstance(image_state, Mapping):
        raise ValueError("当前任务缺少已生成首帧，不能只补跑视频")
    try:
        auth_document = _require_runtime_auth_document(
            "未找到鉴权文档，无法补跑视频",
            channel_ids=("video-generation", "audio-storage"),
        )
    except RuntimeError as exc:
        raise ValueError(str(exc)) from exc
    def worker() -> None:
        try:
            retried_by_id: dict[str, dict] = {}
            retry_progress_lock = threading.Lock()

            def persist_retry_record(record: Mapping[str, object], *, completed: int, message: str, progress: int) -> None:
                shot_id = str(record.get("shot_id") or "")
                if not shot_id:
                    return
                with retry_progress_lock:
                    retried_by_id[shot_id] = dict(record)
                    snapshot = _task_snapshot(asset_task_id) or {}
                    latest_result = dict(snapshot.get("result") or result)
                    merged_now = [
                        retried_by_id.get(
                            str(item.get("shot_id") or ""),
                            next((old for old in records if old.get("shot_id") == item.get("shot_id")), {"shot_id": item.get("shot_id"), "status": "pending"}),
                        )
                        for item in video_shots
                    ]
                    latest_result["aigc_video_assets"] = {
                        "shot_results": merged_now,
                        "video_task_ids": [str(item.get("task_id") or "") for item in merged_now],
                        "video_paths": [str(item.get("video_path") or "") for item in merged_now],
                        "succeeded_count": sum(item.get("status") == "succeeded" for item in merged_now),
                        "failed_count": sum(item.get("status") == "failed" for item in merged_now),
                        "submitted_count": sum(item.get("status") == "submitted" for item in merged_now),
                    }
                    categories = dict(latest_result.get("categories") or {})
                    categories["aigc_videos"] = {
                        "state": "running",
                        "submitted": sum(item.get("status") in {"submitted", "succeeded", "failed"} for item in merged_now),
                        "completed": sum(item.get("status") in {"succeeded", "failed"} for item in merged_now),
                        "total": len(video_shots),
                        "message": message,
                    }
                    latest_result["categories"] = categories
                    _set_task(asset_task_id, state="running", stage="aigc_video_retry", progress=progress, message=message, result=latest_result)

            def on_task_created(event: Mapping[str, object]) -> None:
                with retry_progress_lock:
                    completed = sum(item.get("status") in {"succeeded", "failed"} for item in retried_by_id.values())
                persist_retry_record(
                    event,
                    completed=completed,
                    message=f"已创建补跑视频任务并保存断点：{event.get('shot_id') or ''}",
                    progress=50,
                )

            def on_progress(event: Mapping[str, object]) -> None:
                completed = int(event.get("completed") or 0)
                record = event.get("record") if isinstance(event.get("record"), Mapping) else {}
                if record:
                    persist_retry_record(
                        record,
                        completed=completed,
                        message=f"正在恢复未完成镜头：本轮查询 {completed}/{len(retry_shots)}，当前 {record.get('shot_id') or ''}",
                        progress=50 + int(35 * completed / len(retry_shots)),
                    )
                else:
                    return

            retry_aspect_ratio = normalize_aspect_ratio(
                str(task.get("aspect_ratio") or script_result.get("aspect_ratio") or "9:16")
            )
            prepared_retry_images = _prepare_video_input_image_state(
                image_state,
                image_shots,
                retry_shots,
                aspect_ratio=retry_aspect_ratio,
                auth_document=auth_document,
                task_dir=task_dir / "video_retries" / "current",
            )
            latest_before_retry = dict((_task_snapshot(asset_task_id) or {}).get("result") or result)
            retry_width, retry_height = _video_input_dimensions(retry_aspect_ratio)
            latest_before_retry["video_input"] = {
                "aspect_ratio": retry_aspect_ratio,
                "width": retry_width,
                "height": retry_height,
                "normalized_count": len(image_shots),
            }
            _set_task(asset_task_id, result=latest_before_retry)
            retry_state = generate_videos(
                _asset_manifest_from_shots(retry_shots, aspect_ratio=retry_aspect_ratio),
                prepared_retry_images,
                auth_document,
                task_dir / "video_retries" / str(int(time.time())),
                progress_reporter=on_progress,
                task_created_reporter=on_task_created,
            )
            retried_by_id.update({str(item.get("shot_id") or ""): item for item in retry_state.get("shot_results") or [] if isinstance(item, dict)})
            existing_by_id = {str(item.get("shot_id") or ""): item for item in records}
            merged = [retried_by_id.get(str(item.get("shot_id") or ""), existing_by_id.get(str(item.get("shot_id") or ""), {"shot_id": item.get("shot_id"), "status": "failed"})) for item in video_shots]
            latest_result = dict((_task_snapshot(asset_task_id) or {}).get("result") or result)
            latest_assets = dict(existing)
            latest_assets.update({
                "shot_results": merged,
                "video_task_ids": [str(item.get("task_id") or "") for item in merged],
                "video_paths": [str(item.get("video_path") or "") for item in merged],
                "succeeded_count": sum(item.get("status") == "succeeded" for item in merged),
                "failed_count": sum(item.get("status") == "failed" for item in merged),
            })
            latest_result["aigc_video_assets"] = latest_assets
            categories = dict(latest_result.get("categories") or {})
            failed = [str(item.get("shot_id") or "") for item in merged if item.get("status") == "failed"]
            if failed:
                categories["aigc_videos"] = {"state": "failed", "completed": latest_assets["succeeded_count"], "total": len(merged), "message": f"补跑后仍失败：{', '.join(failed)}"}
                latest_result["categories"] = categories
                _set_task(asset_task_id, state="failed", stage="aigc_video_retry_failed", progress=0, message=f"素材生产失败：补跑后仍有 AIGC 视频失败：{', '.join(failed)}", result=latest_result)
            else:
                categories["aigc_videos"] = {"state": "succeeded", "completed": len(merged), "total": len(merged), "message": "缺失视频已补跑成功，已复用本机已有视频。"}
                latest_result["categories"] = categories
                latest_result["evidence_level"] = "live_image2_and_seedance_partial"
                _set_task(asset_task_id, state="succeeded", stage="asset_production_partial", progress=100, message="AIGC 视频补跑成功；BGM/数字人仍按当前任务配置处理。", result=latest_result)
        except Exception as exc:
            detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:320]
            _set_task(asset_task_id, state="failed", stage="aigc_video_retry_failed", progress=0, message=f"失败视频补跑异常：{type(exc).__name__}：{detail or '无错误详情'}")

    _set_task(asset_task_id, state="queued", stage="aigc_video_retry_queued", progress=0, message=f"准备恢复 {len(retry_shots)} 个未完成 AIGC 视频；已复用 {len(records) - len(retry_shots) if len(records) > len(retry_shots) else len([item for item in records if item.get('status') == 'succeeded'])} 个本机视频。")
    threading.Thread(target=worker, daemon=True).start()
    return _task_snapshot(asset_task_id) or {"task_id": asset_task_id}


def _run_director_shot_script_task(task_id: str, source_story_task_id: str, *, resume: bool = False) -> None:
    """故事通过后执行 197742 → 127095 → 116616 → 195692，不生成素材。"""
    def report(stage: str, progress: int, message: str) -> None:
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, int(progress))), message=message)
        _report_director_child_progress(
            source_story_task_id, stage=stage, progress=progress, message=message
        )

    try:
        story_task = _task_snapshot(source_story_task_id)
        if not story_task or story_task.get("task_type") != "director_story_review" or story_task.get("state") not in {"running", "succeeded"}:
            raise ValueError("原编导任务不存在或未成功完成")
        story_result = story_task.get("result")
        if not isinstance(story_result, dict):
            raise ValueError("原故事审核结果不存在")
        raw_director_result = story_result.get("director_result")
        director_package = str(
            story_result.get("director_package")
            or (raw_director_result.get("director_package") if isinstance(raw_director_result, Mapping) else "")
        ).strip().lower()
        director_package_spec = _resolve_director_package(director_package)
        director_dynamic_params = _normalize_director_dynamic_params(
            director_package_spec, story_result.get("director_dynamic_params"),
        )
        auth_document = _require_director_runtime_auth_document(
            "缺少方舟鉴权文档或已审核文案，不能生成逐镜脚本"
        )
        input_path = DIRECTOR_REVIEW_DIR / source_story_task_id / "approved_copy.json"
        if not input_path.is_file():
            raise RuntimeError("缺少已审核文案，不能生成逐镜脚本")
        director_result = (
            dict(raw_director_result) if isinstance(raw_director_result, Mapping) else {}
        )
        persisted = _task_snapshot(task_id) or {}
        persisted_result = persisted.get("result") if isinstance(persisted, Mapping) else {}
        persisted_result = persisted_result if isinstance(persisted_result, Mapping) else {}
        checkpoint = str(persisted_result.get("checkpoint") or "")
        checkpoint_director = persisted_result.get("director_result")
        performance = (
            dict(persisted_result.get("performance") or {})
            if isinstance(persisted_result.get("performance"), Mapping)
            else {}
        )
        if isinstance(checkpoint_director, Mapping):
            director_result = dict(checkpoint_director)
        # 无断点时才清除旧版治理快照；有断点必须复用已完成阶段。
        if checkpoint not in {"timeline_lock", "visual_direction", "video_prompt_director"}:
            director_result.pop("director_governance", None)
        if not isinstance(director_result.get("tts"), dict):
            raise RuntimeError("原故事审核没有真实 TTS 音频，不能复用")
        director_result["story_draft"] = story_result.get("story_draft")
        if checkpoint in {"timeline_lock", "visual_direction", "video_prompt_director"} and isinstance(persisted_result.get("director_lock"), Mapping):
            director_result["director_lock"] = dict(persisted_result["director_lock"])
            report("timeline_lock", 42, "已从断点恢复时间线锁定结果，跳过重复细化")
        else:
            if not isinstance(director_result.get("subtitle"), Mapping):
                raise RuntimeError("原故事审核没有剪映 STT 字幕时间线，不能进入逐镜脚本")
            report("shot_refinement", 12, "复用 STT 字幕坑位，正在调用方舟完成逐镜细化")
            director_result["shot_refinement"] = run_live_shot_refinement(director_result, auth_document)
            refinement_performance = director_result["shot_refinement"].get("performance")
            if isinstance(refinement_performance, Mapping):
                performance.update(refinement_performance)
            report("timeline_lock", 42, "逐镜已细化，正在锁定微秒时间线与字幕坑位")
            if director_package == "v3_2":
                director_result["director_lock"] = build_approved_director_lock(
                    director_result,
                    input_path,
                    include_sound_effect_plan=True,
                )
            else:
                # v3.1 及历史调用方保持原有调用形态，避免把 v3.2 专用
                # 关键字传播到旧的替身/集成入口。
                director_result["director_lock"] = build_approved_director_lock(
                    director_result,
                    input_path,
                )
            if director_package != "v3":
                pacing_policy = apply_consecutive_static_video_pacing(director_result, input_path)
                if pacing_policy.get("merged_spans") or pacing_policy.get("promoted_single_slot_ids"):
                    report(
                        "timeline_lock",
                        44,
                        "连续静态图片已按权重纠偏，正在锁定合并后的 AIGC 视觉槽位",
                    )
        segment_timelines = _segment_timelines_for_transition(
            director_result["director_lock"], director_package=director_package
        )
        secondary_segment_timelines = _secondary_segment_timelines_for_transition(
            director_result["director_lock"], director_package=director_package
        )
        transition_points = _transition_points_from_secondary_timelines(
            secondary_segment_timelines
        )
        opening_title = _opening_title_from_story_payload(
            story_result,
            fallback_source=story_result.get("approved_copy") or "",
        )
        _set_task(task_id, result={
            "source_story_task_id": source_story_task_id,
            "source_rewrite_id": story_result.get("source_rewrite_id"),
            "checkpoint": "timeline_lock",
            "director_result": director_result,
            "director_lock": director_result["director_lock"],
            "performance": performance,
        })
        aspect_ratio = str(story_result.get("aspect_ratio") or "9:16")
        material_plan = persisted_result.get("material_plan") if checkpoint in {"visual_direction", "video_prompt_director"} else None
        if isinstance(material_plan, Mapping):
            material_plan = dict(material_plan)
            report("visual_direction", 61, "已从断点恢复素材规划，跳过重复调用")
        else:
            report("visual_direction", 61, "时间线已锁定，正在调用方舟生成逐镜视角、景别与画面内容")
            material_plan = run_live_material_planning(
                director_result,
                auth_document,
                aspect_ratio=aspect_ratio,
                director_package=director_package,
                dynamic_params=director_dynamic_params,
            )
            material_performance = material_plan.get("performance") if isinstance(material_plan, Mapping) else None
            if isinstance(material_performance, Mapping):
                performance.update(material_performance)
        _set_task(task_id, result={
            "source_story_task_id": source_story_task_id,
            "source_rewrite_id": story_result.get("source_rewrite_id"),
            "checkpoint": "visual_direction",
            "director_result": director_result,
            "director_lock": director_result["director_lock"],
            "material_plan": material_plan,
            "performance": performance,
        })
        video_plan = persisted_result.get("video_plan") if checkpoint == "video_prompt_director" else None
        if isinstance(video_plan, Mapping):
            video_plan = dict(video_plan)
            report("video_prompt_director", 82, "已从断点恢复镜头动作方案，正在组装最终脚本")
        else:
            report("video_prompt_director", 82, "正在调用方舟生成每个镜头的动作与运镜方案")
            def on_video_prompt_progress(completed: int, total: int, shot_id: str) -> None:
                progress = 82 + round(10 * completed / max(total, 1))
                report(
                    "video_prompt_director",
                    min(progress, 92),
                    f"已完成 {completed}/{total} 个动态镜头动作方案（{shot_id}）",
                )

            video_plan = _run_live_video_prompt_script(
                director_result,
                material_plan,
                auth_document,
                on_video_prompt_progress,
            )
            video_performance = video_plan.get("performance") if isinstance(video_plan, Mapping) else None
            if isinstance(video_performance, Mapping):
                performance.update(video_performance)
        _set_task(task_id, result={
            "source_story_task_id": source_story_task_id,
            "source_rewrite_id": story_result.get("source_rewrite_id"),
            "checkpoint": "video_prompt_director",
            "director_result": director_result,
            "director_lock": director_result["director_lock"],
            "material_plan": material_plan,
            "video_plan": video_plan,
            "performance": performance,
        })
        _report_director_child_progress(source_story_task_id, stage="assembling", progress=94, message="镜头动作方案已完成，正在合并最终逐镜视频脚本")
        shot_script = _build_shot_video_script(director_result, material_plan, video_plan)
        if len(shot_script) <= len(director_result["director_output"]["segments"]):
            raise RuntimeError("逐镜脚本未实际拆分为更多小镜头，拒绝交付")
        for shot in shot_script:
            shot["aspect_ratio"] = aspect_ratio
            if shot.get("first_frame_prompt"):
                shot["image2_prompt"] = _compact_image2_prompt(shot)
        result = {
            "source_story_task_id": source_story_task_id,
            "source_rewrite_id": story_result.get("source_rewrite_id"),
            "director_package": director_package,
            "director_dynamic_params": director_dynamic_params,
            "script_schema_version": "narration_aligned_v3" if director_package == "v3" else "narration_aligned_v2",
            "aspect_ratio": aspect_ratio,
            "tts_cache": director_result["tts"].get("cache", {}),
            "director_lock": director_result["director_lock"],
            "material_plan": material_plan,
            "media_route_lock": material_plan.get("media_route_lock"),
            "media_route_schema_version": (material_plan.get("media_route_lock") or {}).get("schema_version", ""),
            "video_plan": video_plan,
            "shot_video_script": shot_script,
            "opening_title": opening_title,
            "performance": performance,
        }
        if segment_timelines:
            result["group_timeline_unit"] = "microseconds"
            result["group_timeline_source"] = "director_lock.groups_from_capcut_stt"
            result["group_timelines"] = segment_timelines
        if secondary_segment_timelines:
            result["segment_timeline_unit"] = "microseconds"
            result["segment_timeline_source"] = "director_lock.shots_from_capcut_stt"
            result["segment_timelines"] = secondary_segment_timelines
            result["secondary_segment_timeline_unit"] = "microseconds"
            result["secondary_segment_timeline_source"] = "director_lock.shots_from_capcut_stt"
            result["secondary_segment_timelines"] = secondary_segment_timelines
            result["transition_timeline_unit"] = "microseconds"
            result["transition_timeline_source"] = "secondary_segment_timelines"
            result["transition_timelines"] = secondary_segment_timelines
            result["transition_points"] = transition_points
        task_dir = DIRECTOR_REVIEW_DIR / source_story_task_id
        (task_dir / "shot_video_script.json").write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
        _set_task(task_id, state="succeeded", stage="shot_script_ready", progress=100, message=f"已生成 {len(shot_script)} 个逐镜视频脚本，等待你审核后进入素材生产。", result=result)
        _set_task(source_story_task_id, state="succeeded", stage="shot_script_ready", progress=100, message=f"已生成 {len(shot_script)} 个逐镜视频脚本，等待你审核。", result={**result, "shot_script_task_id": task_id})
        # 音色替代不能在逐镜脚本完成时提前切换；数字人、说明镜头及其余
        # 时间轴相关素材尚未完成时，旧 active 版本必须继续可用。
        _mark_voice_replacement_waiting_for_assets(source_story_task_id)
    except Exception as exc:
        TASK_LOGGER.exception("director shot script task %s crashed", task_id)
        detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:320]
        _set_task(
            task_id,
            state="failed",
            stage="shot_script_failed",
            message=f"逐镜视频脚本生成失败：{type(exc).__name__}：{detail or '无错误详情'}",
        )
        _set_task(source_story_task_id, state="failed", stage="shot_script_failed", progress=80, message=f"最终逐镜视频脚本生成失败：{detail or '无错误详情'}")
        _mark_voice_replacement_failed_preserved(
            source_story_task_id,
            f"{type(exc).__name__}: {detail or '无错误详情'}",
        )


def _create_director_shot_script_task(source_story_task_id: str) -> dict:
    story_task = _task_snapshot(source_story_task_id)
    if not story_task or story_task.get("task_type") != "director_story_review":
        raise ValueError("未找到指定的v2 编导任务")
    if story_task.get("state") not in {"running", "succeeded"}:
        raise ValueError("v2 编导任务尚未进入逐镜脚本阶段")

    # 故事任务完成时，后台会自动推进逐镜脚本；页面恢复轮询也可能同时
    # 触发该接口。按 source_story_task_id 复用已有任务，避免生成两条第二步。
    with DIRECTOR_TASK_CREATION_LOCK:
        existing = _latest_director_shot_script_task(
            source_story_task_id, states={"queued", "running", "succeeded", "interrupted"}
        )
        if existing is not None:
            if existing.get("state") == "interrupted":
                return _resume_director_shot_script_task(str(existing["task_id"]))
            return existing

        task_id = uuid.uuid4().hex
        now = int(time.time())
        with STYLE_TASKS_LOCK:
            STYLE_TASKS[task_id] = {
                "task_id": task_id,
                "task_type": "director_shot_script",
                "source_story_task_id": source_story_task_id,
                "input": {"source_story_task_id": source_story_task_id},
                "state": "queued",
                "stage": "queued",
                "progress": 0,
                "message": "逐镜视频脚本任务正在排队",
                "created_at": now,
                "updated_at": now,
            }
            task = dict(STYLE_TASKS[task_id])
        try:
            _persist_task_required(task)
        except TaskPersistenceError:
            with STYLE_TASKS_LOCK:
                STYLE_TASKS.pop(task_id, None)
            raise
    threading.Thread(target=_run_director_shot_script_task, args=(task_id, source_story_task_id), daemon=True).start()
    return _task_snapshot(task_id) or {"task_id": task_id}


def _resume_director_shot_script_task(task_id: str) -> dict:
    """Resume one interrupted child task without creating a second task line."""
    task = _task_snapshot(task_id)
    if not task or task.get("task_type") != "director_shot_script":
        raise ValueError("未找到可恢复的逐镜脚本任务")
    if task.get("state") != "interrupted":
        raise ValueError("仅执行器重启导致的中断逐镜任务可以继续")
    source_story_task_id = str(task.get("source_story_task_id") or "").strip()
    if not source_story_task_id:
        raise ValueError("逐镜任务缺少来源故事任务")
    _set_task(task_id, state="queued", stage="resume_queued", progress=int(task.get("progress") or 0), message="已读取断点，准备继续生成逐镜脚本", _allow_interrupted_resume=True)
    _set_task(source_story_task_id, state="running", stage="shot_script_resuming", progress=max(80, int((_task_snapshot(source_story_task_id) or {}).get("progress") or 80)), message="正在从断点恢复最终逐镜视频脚本", _allow_interrupted_resume=True)
    threading.Thread(target=_run_director_shot_script_task, args=(task_id, source_story_task_id), kwargs={"resume": True}, daemon=True).start()
    return _task_snapshot(task_id) or task


def _resume_director_story_task(task_id: str) -> dict:
    """Resume a parent director task, reusing its story or shot-script checkpoint."""
    task = _task_snapshot(task_id)
    if not task or task.get("task_type") != "director_story_review":
        raise ValueError("未找到可恢复的v2 编导任务")
    task_state = str(task.get("state") or "")
    retry_failed_runtime = task_state == "failed" and str(task.get("error_code") or "") == "director_runtime_failed"
    retry_failed_shot_script = task_state == "failed" and str(task.get("error_code") or "") == "shot_script_failed"
    if task_state != "interrupted" and not retry_failed_runtime and not retry_failed_shot_script:
        if task_state == "failed":
            raise ValueError("当前编导任务已失败，请先修复鉴权或模型配置后再重试；不能按执行器中断恢复")
        raise ValueError("仅执行器重启导致的中断编导任务可以继续")
    result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
    child_id = str(result.get("shot_script_task_id") or task.get("shot_script_task_id") or "").strip()
    if child_id:
        child = _task_snapshot(child_id)
        if child and child.get("state") == "interrupted":
            return _resume_director_shot_script_task(child_id)
    payload = task.get("input") if isinstance(task.get("input"), Mapping) else {}
    if not payload:
        payload = {
            "rewrite_id": result.get("source_rewrite_id"),
            "aspect_ratio": result.get("aspect_ratio") or "9:16",
            "director_package": result.get("director_package") or DEFAULT_DIRECTOR_PACKAGE,
            "voice_key": (result.get("voice_resolution") or {}).get("voice_key", "") if isinstance(result.get("voice_resolution"), Mapping) else "",
        }
    _set_task(
        task_id,
        state="queued",
        stage="retry_queued" if (retry_failed_runtime or retry_failed_shot_script) else "resume_queued",
        error_code="",
        error_detail="",
        message=(
            "已确认使用原任务输入重试编导，准备重新调用模型"
            if retry_failed_runtime
            else ("已读取已完成的剪映 STT 时间线，准备重新生成逐镜脚本" if retry_failed_shot_script else "已读取编导断点，准备继续工作")
        ),
        _allow_interrupted_resume=True,
    )
    threading.Thread(target=_run_director_story_task, args=(task_id, dict(payload)), kwargs={"resume": True}, daemon=True).start()
    return _task_snapshot(task_id) or task


def _create_case_rewrite(
    payload: dict, *, progress_reporter: Callable[[str, int, str], None] | None = None
) -> tuple[int, dict]:
    knowledge_source_records: list[dict[str, object]] = []
    try:
        payload, knowledge_source_records = _prepare_knowledge_source_rewrite_payload(payload)
    except ValueError as exc:
        return 422, {"status": "knowledge_source_blocked", "message": str(exc)}
    # Keep the third-party Cangjie boundary explicit even when the upstream
    # repository is unavailable.  This validates that every selected source is
    # already persisted in Obsidian and is not a browser-only success flag.
    if knowledge_source_records:
        try:
            knowledge_source_records = require_confirmed_sources(knowledge_source_records)
        except CangjieAdapterUnavailable as exc:
            return 409, {
                "status": "knowledge_source_confirmation_required",
                "message": str(exc),
                "knowledge_source_ids": [str(item.get("source_id") or "") for item in knowledge_source_records],
            }
    writing_context = _normalize_writing_task_context(payload)
    # Carry normalized context through the existing request object so all
    # downstream compatibility branches (including legacy case-video input)
    # use the same platform mapping and task dimensions.
    payload = {**payload, **writing_context}
    style_profile_id = str(payload.get("style_profile_id") or "").strip()
    account_id = str(payload.get("account_id") or "").strip()
    case_video_url = str(payload.get("case_video_url") or "").strip()
    source_content_id = str(payload.get("source_content_id") or "").strip()
    source_text = str(payload.get("source_text") or "").strip()
    topic_selection_id = str(payload.get("topic_selection_id") or "").strip()
    try:
        input_mode, input_value = _validate_case_rewrite_input(payload)
    except ValueError as exc:
        return 400, {"status": "invalid_input", "message": str(exc)}
    if input_mode == "case_video_url":
        # 主页链接不能进入“抖音案例视频 → 新文案”兼容链路。统一知识源
        # 入口会把它登记为 profile，再由 Obsidian 发起账号作品采集/蒸馏；
        # 这里提前给出明确指引，避免旧采集器返回“未指向单条视频”。
        detected_case_input = detect_source(case_video_url)
        if detected_case_input.get("material_type") == "profile":
            return 422, {
                "status": "profile_source_requires_registration",
                "message": "检测到博主主页链接，请在上方“知识源（自动识别）”登记后到 Obsidian 发起蒸馏；兼容模式只接受单条视频链接。",
                "detection": detected_case_input,
            }
    if not style_profile_id:
        return 400, {"status": "invalid_input", "message": "已审核风格包为必填"}
    requested_governance = str(payload.get("governance_mode") or "").strip().lower()
    writing_mode = str(payload.get("writing_mode") or "").strip().lower()
    production_mode = writing_mode == "production"
    # The new writing-governance page may submit a direct video URL, but it
    # must opt into the same governed review path as CONTENT_READY sources.
    # The old /writing page omits this flag and therefore keeps its legacy
    # approval contract until that entry is explicitly retired.
    joint_governance = input_mode in {"source_content_id", "source_text"} or (
        input_mode == "case_video_url" and requested_governance == "joint"
    )
    governance_source_id = source_content_id
    governance_selection_id = ""
    try:
        profile_record = STYLE_PACKAGE_STORE.get_profile(style_profile_id)
    except StylePackageStoreError as exc:
        return 404, {"status": "style_profile_missing", "message": str(exc)}
    if profile_record.get("review_status") != "APPROVED":
        return 409, {"status": "style_profile_unapproved", "message": "风格包尚未经人工审核，不能用于二创"}
    profile_enabled = profile_record.get("enabled")
    if isinstance(profile_enabled, str):
        profile_enabled = profile_enabled.strip().lower() not in {"", "0", "false", "no", "off", "disabled"}
    if profile_enabled is False:
        return 409, {"status": "style_profile_disabled", "message": "该风格包已停用，不能用于二创", "style_profile_id": style_profile_id}
    if production_mode:
        profile_summary = _profile_summary(profile_record)
        if not profile_summary.get("production_eligible"):
            return 409, {
                "status": "style_profile_not_production_eligible",
                "message": str(profile_summary.get("production_eligibility_reason") or "该风格包未达到生产调用门禁"),
                "style_profile_id": style_profile_id,
                "writing_dna_gate": profile_summary.get("writing_dna_gate", {}),
            }
    profile_payload = profile_record.get("style_profile") if isinstance(profile_record.get("style_profile"), Mapping) else {}
    # A profile distilled from an account carries the account identity.  If the
    # caller omitted it, derive it from the approved asset so the production
    # path cannot accidentally fall back to ungoverned account notes.
    account_id = account_id or str(profile_payload.get("account_id") or "").strip()
    if not writing_context["thinking_package_id"] and account_id:
        writing_context["thinking_package_id"] = account_id
    try:
        account_knowledge_context = _account_knowledge_context_for_rewrite(account_id)
    except (ObsidianRepositoryError, VaultConfigError) as exc:
        return 409, {
            "status": "account_knowledge_unavailable",
            "message": str(exc),
            "account_id": account_id,
        }
    creative_brief = normalize_creative_brief({
        "topic": writing_context.get("topic"),
        "audience": writing_context.get("audience"),
        "target_platform": writing_context.get("target_platform"),
        "personalized_slogan": payload.get("personalized_slogan"),
        "creative_direction": payload.get("creative_direction"),
    })
    try:
        case_item = None
        if progress_reporter is not None:
            progress_reporter("collecting", 10, "正在读取案例来源并准备文案输入")
        if input_mode == "source_text":
            try:
                manual_source = TOPIC_WRITING_GOVERNANCE_STORE.save_manual_source(
                    source_text,
                    title=payload.get("title") or "纯文案素材",
                    source_name=payload.get("source_name") or "",
                    selection_id=payload.get("selection_id") or "",
                    source_url=payload.get("source_url") or "",
                )
            except TopicWritingGovernanceError as exc:
                return 422, {"status": "source_text_invalid", "message": str(exc)}
            governance_source_id = str(manual_source.get("source_content_id") or "")
            case_item = _topic_writing_governance_case_item(governance_source_id)
        elif input_mode == "source_content_id":
            try:
                case_item = _topic_writing_governance_case_item(source_content_id)
            except TopicWritingGovernanceError as exc:
                return 422, {"status": "source_content_blocked", "message": str(exc), "source_content_id": source_content_id}
        elif topic_selection_id:
            writing_input = _topic_center_writing_input(topic_selection_id)
            if writing_input.get("status") != "ready":
                return 422, {"status": "topic_collection_blocked", "message": writing_input.get("message", "选题采集尚未完成"), "selection_id": topic_selection_id}
            case_item = writing_input["collected_source_content"]
        else:
            platform = _platform_from_url(case_video_url)
            if platform == "douyin":
                case_item = collect_douyin_case_video(case_video_url)
            elif platform == "bilibili":
                case_item = collect_case_video(case_video_url)
            else:
                return 422, {"status": "case_collection_blocked", "message": "当前支持抖音案例视频；B 站为兼容入口。"}
    except (BilibiliCollectorError, DouyinCollectorError) as exc:
        return 422, {"status": "case_collection_blocked", "message": str(exc)}
    if case_item.get("transcript_status") not in {"official_subtitle", "local_whisper", "collected_html", "manual_text"} or len(case_item.get("transcript", "")) < MIN_SOURCE_TEXT_CHARS:
        return 422, {
            "status": "case_transcript_missing", "message": "案例视频没有可用字幕/本地转写；未生成二创文案。",
            "case_item": case_item,
        }
    if joint_governance and input_mode == "case_video_url" and not governance_source_id:
        try:
            governed_source = TOPIC_WRITING_GOVERNANCE_STORE.save_video_source(
                case_item,
                source_url=case_item.get("source_url") or case_video_url,
                source_name=case_item.get("source_name") or "",
            )
        except TopicWritingGovernanceError as exc:
            return 422, {"status": "source_video_invalid", "message": str(exc), "case_item": case_item}
        governance_source_id = str(governed_source.get("source_content_id") or "")
        case_item = dict(case_item)
        case_item["source_content_id"] = governance_source_id
    if joint_governance:
        governance_selection_id = str(case_item.get("selection_id") or "").strip()
        if not governance_selection_id and governance_source_id:
            source_record = TOPIC_WRITING_GOVERNANCE_STORE.get_source(governance_source_id)
            governance_selection_id = str((source_record or {}).get("selection_id") or "").strip()
        if governance_selection_id:
            try:
                TOPIC_WRITING_GOVERNANCE_STORE.update_selection(
                    governance_selection_id,
                    state="WRITING",
                    source_content_id=governance_source_id,
                    message="正文素材已就绪，正在生成文案草案",
                )
            except TopicWritingGovernanceError:
                # The source itself remains the authoritative input; a missing
                # optional selection link must not break pure-text creation.
                governance_selection_id = ""
    try:
        if progress_reporter is not None:
            progress_reporter("transcribing", 35, "案例字幕已就绪，正在整理可用转写内容")
        content_transport = ArkStoryFailoverHTTPTransport.from_content_runtime_config()
        style_transport = ArkStoryFailoverHTTPTransport.from_style_runtime_config()
        review_transport = ArkStoryFailoverHTTPTransport.from_review_runtime_config()
        result = rewrite_case_copy(
            case_item=case_item,
            style_profile=profile_record["style_profile"],
            rewrite_goal=str(payload.get("rewrite_goal") or "保留事实与观点，重新表达"),
            publish_format=writing_context["publish_format"],
            target_duration=str(payload.get("target_duration") or "60 秒"),
            creative_brief=creative_brief,
            transport=style_transport,
            content_transport=content_transport,
            style_transport=style_transport,
            review_transport=review_transport,
            progress_reporter=progress_reporter,
            account_knowledge_context=account_knowledge_context,
        )
        if knowledge_source_records:
            result["knowledge_sources"] = knowledge_source_records
            result["knowledge_source_ids"] = [item["source_id"] for item in knowledge_source_records]
            result["asset_versions"] = {
                "style_profile_id": style_profile_id,
                "style_profile_version": str(profile_record.get("style_profile_version") or profile_record.get("approved_at") or "unknown"),
                "source_registry_version": "knowledge-source-v1",
            }
        result["writing_context"] = dict(writing_context)
        result["topic"] = writing_context["topic"]
        result["target_platform"] = writing_context["target_platform"]
        result["audience"] = writing_context["audience"]
        result["thinking_package_id"] = writing_context["thinking_package_id"]
        result["writing_mode"] = writing_mode or "legacy"
        if account_id:
            result["account_knowledge"] = {
                "account_id": account_id,
                "knowledge_status": account_knowledge_context.get("knowledge_status"),
                "distillation_status": account_knowledge_context.get("distillation_status"),
                "sample_count": account_knowledge_context.get("sample_count"),
                "evidence_work_ids": account_knowledge_context.get("evidence_work_ids", []),
            }
        # Persist the fixed execution chain and the safe human-writing gate on
        # the same rewrite record.  The adapter intentionally returns the
        # draft unchanged when the upstream checker is not locally verified;
        # it never fabricates a "de-AI" success.
        pipeline = result.get("pipeline") if isinstance(result, Mapping) else {}
        pipeline_gate = str(pipeline.get("gate") or "") .strip().upper() if isinstance(pipeline, Mapping) else ""
        human_writing = run_safe_human_writing_gate(
            str(result.get("rewritten_copy") or "") if isinstance(result, Mapping) else "",
            source_ids=[str(item.get("source_id") or "") for item in knowledge_source_records if str(item.get("source_id") or "")],
            fact_trace_complete=pipeline_gate != "BLOCKED",
            upstream_available=False,
        )
        result["human_writing"] = human_writing.to_dict()
        result["source_records"] = [dict(item) for item in knowledge_source_records]
        source_ids = [str(item.get("source_id") or "") for item in knowledge_source_records if str(item.get("source_id") or "")]
        result["knowledge_source_ids"] = source_ids
        result["knowledge_source_versions"] = {
            str(item.get("source_id") or ""): str(item.get("source_version") or "source-v1")
            for item in knowledge_source_records
            if str(item.get("source_id") or "")
        }
        existing_versions = result.get("asset_versions") if isinstance(result.get("asset_versions"), Mapping) else {}
        result["asset_versions"] = {
            **dict(existing_versions),
            "style_profile_id": style_profile_id,
            "style_profile_version": str(profile_record.get("style_profile_version") or profile_record.get("approved_at") or "unknown"),
            "account_id": account_id,
            "source_registry_version": "knowledge-source-v1",
            "orchestrator_version": "copywriting-orchestrator-v1",
            "thinking_package_id": writing_context["thinking_package_id"],
        }
        result["orchestration"] = build_execution_manifest(
            source_records=knowledge_source_records,
            style_profile_record={
                **dict(profile_record),
                "style_profile_id": style_profile_id,
                "style_profile_version": profile_record.get("style_profile_version") or profile_record.get("approved_at") or "unknown",
                "account_id": account_id,
            },
            account_knowledge_context=account_knowledge_context,
            task_context={**writing_context, "writing_mode": writing_mode or "legacy"},
            draft_status="BLOCKED" if pipeline_gate == "BLOCKED" else "REVIEW_PENDING",
            human_writing_status=human_writing.status,
            final_review_status="PENDING",
        )
    except ArkStoryConfigError as exc:
        if governance_selection_id:
            TOPIC_WRITING_GOVERNANCE_STORE.update_selection(governance_selection_id, state="REVIEW_BLOCKED", message="文案模型未配置，未生成 approved_copy")
        return 503, {"status": "model_not_configured", "message": str(exc), "case_item": case_item}
    except (ArkStoryTransportError, StylePackageError) as exc:
        if governance_selection_id:
            TOPIC_WRITING_GOVERNANCE_STORE.update_selection(governance_selection_id, state="REVIEW_BLOCKED", message="文案模型失败，未生成 approved_copy")
        return 502, {"status": "rewrite_failed", "message": str(exc), "case_item": case_item}
    pipeline = result.get("pipeline") if isinstance(result, Mapping) else {}
    if isinstance(pipeline, Mapping) and pipeline.get("gate") == "BLOCKED":
        # A blocked candidate must not archive the last approved copy. Keep it
        # as a pending audit record while the existing director input remains
        # available for recovery.
        record = STYLE_PACKAGE_STORE.save_rewrite(
            style_profile_id=style_profile_id, case_item=case_item, result=result
        )
        for source in knowledge_source_records:
            source_id = str(source.get("source_id") or "").strip()
            if source_id:
                try:
                    _knowledge_source_registry().bind_asset(source_id, str(record.get("rewrite_id") or ""))
                except KnowledgeSourceError:
                    pass
        if progress_reporter is not None:
            progress_reporter("blocked", 100, "审核模型阻断了该文案；已保存草案和审核报告，未进入编导层")
        if governance_selection_id:
            TOPIC_WRITING_GOVERNANCE_STORE.link_copy(
                record["rewrite_id"],
                selection_id=governance_selection_id,
                source_content_id=governance_source_id,
                state="REVIEW_BLOCKED",
                message="审核模型阻断，未生成 approved_copy",
            )
        return 409, {
            "status": "copy_review_blocked",
            "message": "审核模型判定该文案存在不可直接交付的问题，未生成 approved_copy。",
            "record": record,
        }
    archive_report = STYLE_PACKAGE_STORE.archive_existing_rewrites()
    if archive_report.get("errors"):
        return 500, {
            "status": "rewrite_archive_failed",
            "message": "旧二创草案未能完整归档，已阻止新草案进入当前工作流，避免新旧文案混用。",
            "archive": archive_report,
        }
    record = STYLE_PACKAGE_STORE.save_rewrite(style_profile_id=style_profile_id, case_item=case_item, result=result)
    for source in knowledge_source_records:
        source_id = str(source.get("source_id") or "").strip()
        if source_id:
            try:
                _knowledge_source_registry().bind_asset(source_id, str(record.get("rewrite_id") or ""))
            except KnowledgeSourceError:
                pass
    if joint_governance:
        TOPIC_WRITING_GOVERNANCE_STORE.link_copy(
            record["rewrite_id"],
            selection_id=governance_selection_id,
            source_content_id=governance_source_id,
            state="REVIEW_PENDING",
            message="文案草案已生成，等待人工审核；尚未生成 approved_copy",
        )
        if progress_reporter is not None:
            progress_reporter("review_pending", 100, "文案草案已生成，等待人工审核；尚未进入编导")
        return 201, {
            "status": "review_pending",
            "record": record,
            "archived_previous": archive_report,
            "input_mode": input_mode,
            "source_content_id": governance_source_id,
        }
    # Only a PASS or a reviewer-produced REVISE result is eligible for the
    # existing approved_copy gate used by the director layer.
    record = STYLE_PACKAGE_STORE.approve_rewrite(record["rewrite_id"])
    if progress_reporter is not None:
        progress_reporter("completed", 100, "新文案已生成，正在进入编导")
    return 201, {"status": "approved", "record": record, "archived_previous": archive_report}


def _run_case_rewrite_task(task_id: str, payload: dict) -> None:
    def report(stage: str, progress: int, message: str) -> None:
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, int(progress))), message=message)

    try:
        report("starting", 1, "新文案任务已启动")
        source_ids = _knowledge_source_ids(payload)
        if source_ids:
            _knowledge_source_mark_task(source_ids, task_id, "PROCESSING")
        status, result = _create_case_rewrite(payload, progress_reporter=report)
        if 200 <= status < 300:
            message = "文案已生成，等待人工审核" if result.get("status") == "review_pending" else "新文案已生成，正在进入编导"
            if source_ids:
                final_source_state = "PENDING_REVIEW" if result.get("status") == "review_pending" else "INGESTED"
                _knowledge_source_mark_task(source_ids, task_id, final_source_state)
            _set_task(task_id, state="succeeded", stage="completed", progress=100, message=message, result=result)
        else:
            if source_ids:
                for source_id in source_ids:
                    try:
                        _knowledge_source_registry().transition(source_id, "FAILED", error_code=str(result.get("status") or "rewrite_failed"), error_message=str(result.get("message") or "文案任务失败"))
                    except KnowledgeSourceError:
                        pass
            _set_task(task_id, state="failed", stage=str(result.get("status", "failed")), progress=0, message=str(result.get("message", "新文案生成失败")), result=result)
    except Exception as exc:
        TASK_LOGGER.exception("case rewrite task %s crashed", task_id)
        for source_id in _knowledge_source_ids(payload):
            try:
                _knowledge_source_registry().transition(source_id, "FAILED", error_code="task_failed", error_message=str(exc))
            except KnowledgeSourceError:
                pass
        _set_task(task_id, state="failed", stage="internal_error", progress=0, message=f"文案任务异常：{type(exc).__name__}：{str(exc)[:240]}")


def _resume_case_rewrite_task(task_id: str) -> dict:
    """Explicitly resume a rewrite interrupted by an executor restart."""

    task = _task_snapshot(task_id)
    if task is None or task.get("task_type") != "case_rewrite":
        raise ValueError("未找到可恢复的文案任务")
    state = str(task.get("state") or "")
    if state in TASK_ACTIVE_STATES:
        return task
    if state != "interrupted" or str(task.get("stage") or "") != "executor_restarted":
        raise ValueError("该文案任务不是执行器重启中断状态，不能自动恢复；请重新提交或保留原失败记录")
    payload = task.get("input")
    if not isinstance(payload, Mapping) or not (
        str(payload.get("case_video_url") or "").strip()
        or str(payload.get("source_content_id") or "").strip()
        or str(payload.get("topic_selection_id") or "").strip()
    ):
        raise ValueError("旧文案任务缺少可恢复输入，不能恢复")
    _set_task(
        task_id,
        state="queued",
        stage="resume_queued",
        progress=0,
        message="已恢复中断的文案任务，准备继续执行",
        lifecycle_status="active",
        error_code="",
        error_detail="",
        _allow_interrupted_resume=True,
    )
    threading.Thread(
        target=_run_case_rewrite_task,
        args=(task_id, dict(payload)),
        daemon=True,
    ).start()
    return _task_snapshot(task_id) or task


def _create_case_rewrite_task(payload: dict) -> dict:
    with CASE_REWRITE_CREATION_LOCK:
        return _create_case_rewrite_task_locked(payload)


def _create_case_rewrite_task_locked(payload: dict) -> dict:
    normalized_payload, knowledge_source_records = _prepare_knowledge_source_rewrite_payload(payload)
    writing_context = _normalize_writing_task_context(normalized_payload)
    normalized_payload = {**normalized_payload, **writing_context}
    input_mode, input_value = _validate_case_rewrite_input(normalized_payload)
    if str(normalized_payload.get("writing_mode") or "").strip().lower() == "production":
        style_profile_id = str(normalized_payload.get("style_profile_id") or "").strip()
        if not style_profile_id:
            raise ValueError("生产文案必须选择语言风格包")
        # 少样本资产作为实验版直接可用；正式门禁仅作为结果标记。
        _profile_summary(STYLE_PACKAGE_STORE.get_profile(style_profile_id))
    if input_mode == "source_text":
        # Persist manual text as a governed source before creating the async
        # task.  The task snapshot contains only its stable source_content_id,
        # never the potentially large raw text.
        try:
            manual_source = TOPIC_WRITING_GOVERNANCE_STORE.save_manual_source(
                input_value,
                title=normalized_payload.get("title") or "纯文案素材",
                source_name=normalized_payload.get("source_name") or "",
                selection_id=normalized_payload.get("selection_id") or "",
                source_url=normalized_payload.get("source_url") or "",
            )
        except TopicWritingGovernanceError as exc:
            raise ValueError(str(exc)) from exc
        normalized_payload["source_content_id"] = str(manual_source["source_content_id"])
        normalized_payload["source_text"] = ""
    elif input_mode == "source_content_id":
        try:
            TOPIC_WRITING_GOVERNANCE_STORE.get_source_for_copy(input_value)
        except TopicWritingGovernanceError as exc:
            raise ValueError(str(exc)) from exc
    creative_brief = normalize_creative_brief({
        "topic": writing_context.get("topic"),
        "audience": writing_context.get("audience"),
        "target_platform": writing_context.get("target_platform"),
        "personalized_slogan": normalized_payload.get("personalized_slogan"),
        "creative_direction": normalized_payload.get("creative_direction"),
    })
    normalized_payload.update(creative_brief)
    input_fingerprint = _task_input_fingerprint("case_rewrite", normalized_payload)
    existing = _active_case_rewrite_for_fingerprint(input_fingerprint)
    if existing is not None:
        existing = dict(existing)
        existing["deduplicated"] = True
        existing["status"] = "already_running"
        existing["message"] = "相同文案任务正在执行，已复用原任务"
        return existing
    task_id = uuid.uuid4().hex
    now = int(time.time())
    task_input = {
        "case_video_url": str(normalized_payload.get("case_video_url") or "").strip(),
        "source_content_id": str(normalized_payload.get("source_content_id") or "").strip(),
        "topic_selection_id": str(normalized_payload.get("topic_selection_id") or "").strip(),
        "account_id": str(normalized_payload.get("account_id") or "").strip(),
        "topic": writing_context["topic"],
        "target_platform": writing_context["target_platform"],
        "audience": writing_context["audience"],
        "thinking_package_id": writing_context["thinking_package_id"],
        "style_profile_id": str(normalized_payload.get("style_profile_id") or "").strip(),
        "rewrite_goal": str(normalized_payload.get("rewrite_goal") or "保留事实与观点，重新表达").strip(),
        "publish_format": writing_context["publish_format"],
        "target_duration": str(normalized_payload.get("target_duration") or "60 秒").strip(),
        "personalized_slogan": str(normalized_payload.get("personalized_slogan") or "").strip(),
        "creative_direction": str(normalized_payload.get("creative_direction") or "").strip(),
        "knowledge_source_ids": [str(item.get("source_id") or "") for item in knowledge_source_records if str(item.get("source_id") or "").strip()],
        "knowledge_source_versions": {
            str(item.get("source_id") or ""): str(item.get("source_version") or "source-v1")
            for item in knowledge_source_records
            if str(item.get("source_id") or "").strip()
        },
        "knowledge_source_records": [dict(item) for item in knowledge_source_records],
        "writing_context": dict(writing_context),
        "writing_mode": str(normalized_payload.get("writing_mode") or "").strip().lower() or "legacy",
        "orchestrator_version": "copywriting-orchestrator-v1",
        "governance_mode": str(normalized_payload.get("governance_mode") or ("joint" if input_mode in {"source_content_id", "source_text"} else "legacy")).strip(),
        "input_type": "manual_text" if input_mode == "source_text" else ("source_content" if input_mode == "source_content_id" else input_mode),
    }
    with STYLE_TASKS_LOCK:
        STYLE_TASKS[task_id] = {
            "task_id": task_id,
            "task_type": "case_rewrite",
            "input": task_input,
            "state": "queued",
            "stage": "queued",
            "progress": 0,
            "message": "新文案任务正在排队",
            "created_at": now,
            "updated_at": now,
            "workflow_version": TASK_WORKFLOW_VERSION,
            "schema_version": TASK_SCHEMA_VERSION,
            "input_fingerprint": input_fingerprint,
            "parent_task_id": "",
            "archive_id": "",
            "legacy_status": "current",
            "lifecycle_status": "active",
            "error_code": "",
            "error_detail": "",
        }
        task = dict(STYLE_TASKS[task_id])
    try:
        _persist_task_required(task)
    except TaskPersistenceError:
        with STYLE_TASKS_LOCK:
            STYLE_TASKS.pop(task_id, None)
        raise
    if knowledge_source_records:
        try:
            _knowledge_source_mark_task(
                [str(item.get("source_id") or "") for item in knowledge_source_records],
                task_id,
            )
        except (KnowledgeSourceError, OSError) as exc:
            with STYLE_TASKS_LOCK:
                STYLE_TASKS.pop(task_id, None)
            raise ValueError(f"知识源任务绑定失败：{exc}") from exc
    threading.Thread(target=_run_case_rewrite_task, args=(task_id, task_input), daemon=True).start()
    return _task_snapshot(task_id) or task


def _active_case_rewrite_for_fingerprint(input_fingerprint: str) -> dict | None:
    fingerprint = str(input_fingerprint or "").strip()
    if not fingerprint:
        return None
    for task in _list_style_tasks(limit=2000):
        if task.get("task_type") != "case_rewrite" or task.get("state") not in TASK_ACTIVE_STATES:
            continue
        if str(task.get("input_fingerprint") or "") == fingerprint:
            return task
    return None


def _active_case_rewrite_for_profile(style_profile_id: str) -> dict | None:
    profile_id = str(style_profile_id or "").strip()
    if not profile_id:
        return None
    for task in _list_style_tasks(limit=2000):
        if task.get("task_type") != "case_rewrite" or task.get("state") not in {"queued", "running"}:
            continue
        task_input = task.get("input")
        if isinstance(task_input, Mapping) and str(task_input.get("style_profile_id") or "").strip() == profile_id:
            return task
    return None


def _editing_canvas(aspect_ratio: str) -> tuple[int, int]:
    """Return the Windows draft canvas for the user-confirmed aspect ratio."""

    return {
        "9:16": (1080, 1920),
        "16:9": (1920, 1080),
        "1:1": (1080, 1080),
        "3:2": (1200, 800),
        "2:3": (800, 1200),
    }.get(aspect_ratio, (1080, 1920))


def _asset_result_readiness(
    asset_result: Mapping[str, object], shot_script: list[Mapping[str, object]]
) -> tuple[bool, str]:
    """Check whether a persisted asset result can enter the Windows edit layer.

    This is intentionally stricter than the asset-page progress state: a partial
    paid result is kept for preview/retry, but a draft must have every required
    visual, BGM and digital-human output with a real local file.
    """

    if not isinstance(asset_result, Mapping):
        return False, "素材结果不是对象"
    if not shot_script:
        return False, "逐镜脚本为空"
    by_shot = {str(item.get("shot_id") or ""): item for item in shot_script if isinstance(item, Mapping)}
    overrides = asset_result.get("media_type_overrides")
    overrides = overrides if isinstance(overrides, Mapping) else {}
    effective_type = lambda shot_id, item: str(overrides.get(shot_id) or item.get("media_type") or "")
    required_aigc = [shot_id for shot_id, item in by_shot.items() if effective_type(shot_id, item) == "aigc_video"]
    required_digital = [shot_id for shot_id, item in by_shot.items() if effective_type(shot_id, item) == "digital_human_video"]
    required_explanation = [
        shot_id for shot_id, item in by_shot.items()
        if str(item.get("shot_class") or "") in {"explanation", "mixed_explanation"}
        or effective_type(shot_id, item) in {"explanation", "mixed_explanation"}
    ]
    non_digital = [
        shot_id for shot_id, item in by_shot.items()
        if effective_type(shot_id, item) not in {"digital_human_video", "explanation", "mixed_explanation"}
    ]

    first_frame_by_shot = _first_frame_paths_by_shot(asset_result)
    fallbacks = asset_result.get("digital_human_fallbacks")
    if isinstance(fallbacks, Mapping):
        for shot_id, item in fallbacks.items():
            if isinstance(item, Mapping):
                path = _safe_director_review_file(item.get("image_path"))
                if path is not None:
                    first_frame_by_shot[str(shot_id)] = path
    missing_frames = [shot_id for shot_id in non_digital if shot_id not in first_frame_by_shot]
    if missing_frames:
        return False, f"首帧文件缺失：{', '.join(missing_frames[:8])}"
    if required_explanation and not any(shot_id in first_frame_by_shot for shot_id in required_aigc):
        return False, "说明镜头风格锁缺少同一任务已审核通过的 AIGC 首帧"

    def check_video_group(key: str, required_ids: list[str], label: str) -> tuple[bool, str]:
        group = asset_result.get(key)
        records = group.get("shot_results") if isinstance(group, Mapping) else None
        by_id = {str(item.get("shot_id") or ""): item for item in records or [] if isinstance(item, Mapping)}
        for shot_id in required_ids:
            record = by_id.get(shot_id)
            if not record or record.get("status") != "succeeded":
                return False, f"{label}未成功：{shot_id}"
            path = str(record.get("video_path") or "")
            if not path or not Path(path).is_file():
                return False, f"{label}文件缺失：{shot_id}"
        return True, ""

    ready, reason = check_video_group("aigc_video_assets", required_aigc, "AIGC 视频")
    if not ready:
        return False, reason
    ready, reason = check_video_group("digital_human_assets", required_digital, "数字人视频")
    if not ready:
        return False, reason

    explanation_group = asset_result.get("explanation_assets")
    explanation_records = explanation_group.get("shot_results") if isinstance(explanation_group, Mapping) else None
    explanation_by_id = {
        str(item.get("shot_id") or ""): item
        for item in explanation_records or []
        if isinstance(item, Mapping)
    }
    for shot_id in required_explanation:
        record = explanation_by_id.get(shot_id)
        if not record or record.get("status") != "succeeded":
            return False, f"说明镜头 Remotion 未成功：{shot_id}"
        output_path = str(record.get("output_path") or record.get("video_path") or "")
        if not output_path or not Path(output_path).is_file():
            return False, f"说明镜头 Remotion 文件缺失：{shot_id}"

    bgm = asset_result.get("bgm_assets")
    bgm_path = str(bgm.get("audio_path") or "") if isinstance(bgm, Mapping) else ""
    # BGM 为可选素材：明确 skipped 表示用户未提供音乐，不阻断进入剪辑层。
    if isinstance(bgm, Mapping) and str(bgm.get("status") or "") == "skipped":
        return True, ""
    if not isinstance(bgm, Mapping) or bgm.get("status") != "succeeded" or not Path(bgm_path).is_file():
        return False, "背景音乐未生成或本地文件缺失"
    return True, ""


def _editing_asset_candidates(
    source_story_task_id: str, shot_script: list[Mapping[str, object]]
) -> list[tuple[str, dict, bool, str, int]]:
    """Return current and archived asset results, newest first.

    The console task snapshot can be stale after a restart or a retry.  The paid
    result files under the story directory are therefore also considered, but
    only when their source story matches and their files pass the readiness gate.
    """

    candidates: list[tuple[str, dict, bool, str, int]] = []
    seen: set[str] = set()
    for task in _list_style_tasks(limit=2000, source_story_task_id=source_story_task_id):
        if task.get("task_type") != "asset_production":
            continue
        result = task.get("result")
        if not isinstance(result, Mapping):
            continue
        task_id = str(task.get("task_id") or "").strip()
        if not task_id or task_id in seen:
            continue
        ready, reason = _asset_result_readiness(result, shot_script)
        candidates.append((task_id, dict(result), ready, reason, int(task.get("updated_at") or 0)))
        seen.add(task_id)

    story_root = DIRECTOR_REVIEW_DIR / source_story_task_id / "asset_production"
    try:
        files = sorted(story_root.glob("*/asset_production.json"), key=lambda item: item.stat().st_mtime, reverse=True)
    except OSError:
        files = []
    for path in files:
        task_id = path.parent.name
        if task_id in seen:
            continue
        try:
            result = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(result, dict) or str(result.get("source_story_task_id") or "") != source_story_task_id:
            continue
        ready, reason = _asset_result_readiness(result, shot_script)
        candidates.append((task_id, result, ready, reason, int(path.stat().st_mtime)))
        seen.add(task_id)
    return sorted(candidates, key=lambda item: item[4], reverse=True)


def _load_editing_source_inputs(
    source_story_task_id: str,
) -> tuple[dict, dict, dict, str, dict]:
    """Load the approved director lock, latest shot script and reusable assets."""

    story_task = _handoff_story_task_snapshot(source_story_task_id)
    if not story_task or story_task.get("task_type") != "director_story_review" or story_task.get("state") != "succeeded":
        raise ValueError("未找到已完成的v2 编导任务")
    story_result = story_task.get("result") if isinstance(story_task.get("result"), Mapping) else {}
    if story_result.get("review_status") != "APPROVED":
        raise ValueError("故事尚未确认，不能生成剪映草稿")
    shot_task = _latest_shot_script_task(source_story_task_id)
    shot_result = shot_task.get("result") if isinstance(shot_task.get("result"), Mapping) else {}
    shot_script = [item for item in shot_result.get("shot_video_script") or [] if isinstance(item, Mapping)]
    candidates = _editing_asset_candidates(source_story_task_id, shot_script)
    ready = next((item for item in candidates if item[2]), None)
    if ready is None:
        reason = candidates[0][3] if candidates else "没有找到素材生产结果"
        raise ValueError(f"当前没有可交付的完整素材：{reason}。失败资产仍保留在素材生产页，可先补跑。")
    return story_task, shot_task, dict(shot_result), ready[0], ready[1]


def _editing_context(source_story_task_id: str) -> dict:
    """Expose only local readiness metadata needed by the editing page."""

    story_task = _handoff_story_task_snapshot(source_story_task_id)
    if not story_task:
        raise ValueError("未找到v2 编导任务")
    try:
        shot_task = _latest_shot_script_task(source_story_task_id)
        shot_result = shot_task.get("result") if isinstance(shot_task.get("result"), Mapping) else {}
        shot_script = [item for item in shot_result.get("shot_video_script") or [] if isinstance(item, Mapping)]
        candidates = _editing_asset_candidates(source_story_task_id, shot_script)
        candidate = candidates[0] if candidates else None
        ready = next((item for item in candidates if item[2]), None)
        story_result = story_task.get("result") if isinstance(story_task.get("result"), Mapping) else {}
        director_ratio = normalize_aspect_ratio(str(story_result.get("aspect_ratio") or "9:16"))
        asset_ratio = normalize_aspect_ratio(str((candidate[1] if candidate else {}).get("aspect_ratio") or director_ratio))
        draft_root = _resolve_jianying_draft_root()
        return {
            "status": "ready" if ready else "blocked",
            "source_story_task_id": source_story_task_id,
            "source_shot_script_task_id": shot_task.get("task_id"),
            "asset_task_id": ready[0] if ready else (candidate[0] if candidate else ""),
            "asset_state": "ready" if ready else "partial_or_failed",
            "asset_readiness_message": "完整素材可交付" if ready else (candidate[3] if candidate else "没有素材生产结果"),
            "director_aspect_ratio": director_ratio,
            "asset_aspect_ratio": asset_ratio,
            "recommended_aspect_ratio": asset_ratio,
            "shot_count": len(shot_script),
            "draft_root": str(draft_root),
            "draft_root_exists": draft_root.is_dir(),
            "draft_root_source": "service_default",
        }
    except (ValueError, KeyError) as exc:
        return {"status": "blocked", "source_story_task_id": source_story_task_id, "asset_readiness_message": str(exc)}


def _capcut_mate_base_url() -> str:
    """Return the configured CapCut Mate base URL without exposing query data."""

    value = os.environ.get("CAPCUT_MATE_BASE_URL", "http://127.0.0.1:30000").strip()
    if not value:
        return ""
    return value.split("?", 1)[0].split("#", 1)[0].rstrip("/")


def _open_capcut_probe(request: Request, timeout: float):
    """探测本机 CapCut 时绕过代理，并在端口关闭时快速失败。"""
    parsed = urlparse(request.full_url)
    host = (parsed.hostname or "").strip().lower()
    if host in {"127.0.0.1", "localhost", "::1"}:
        try:
            port = parsed.port or (443 if parsed.scheme.lower() == "https" else 80)
            with socket.create_connection((host, port), timeout=min(float(timeout), 0.25)):
                pass
        except (OSError, ValueError) as exc:
            raise URLError("CapCut Mate 本机端口不可达") from exc
        return build_opener(ProxyHandler({})).open(request, timeout=timeout)
    return urlopen(request, timeout=timeout)


def _probe_capcut_mate() -> dict[str, object]:
    """Probe CapCut Mate's documented API endpoint for the production gate."""

    base_url = _capcut_mate_base_url()
    if not base_url:
        return {
            "id": "capcut_mate",
            "label": "CapCut Mate 服务",
            "state": "blocked",
            "required": True,
            "message": "未配置 CAPCUT_MATE_BASE_URL。",
        }
    probe_url = base_url if base_url.endswith("/openapi.json") else f"{base_url}/openapi.json"
    try:
        request = Request(probe_url, headers={"User-Agent": "Daily-Update-Te-Console/1.0"})
        with _open_capcut_probe(request, timeout=3) as response:
            status = int(getattr(response, "status", 200))
            if status < 200 or status >= 400:
                raise OSError(f"HTTP {status}")
        return {
            "id": "capcut_mate",
            "label": "CapCut Mate 服务",
            "state": "ready",
            "required": True,
            "message": f"API 可访问：{base_url}",
            "endpoint": base_url,
        }
    except (HTTPError, URLError, OSError, TimeoutError, ValueError) as exc:
        return {
            "id": "capcut_mate",
            "label": "CapCut Mate 服务",
            "state": "blocked",
            "required": True,
            "message": f"API 不可访问：{type(exc).__name__}",
            "endpoint": base_url,
        }


def _video_production_preflight(
    editing_task_id: str = "",
    jianying_exe_path: object = None,
    confirmed_draft_path: object = None,
) -> dict[str, object]:
    """Build the fifth-tab production gate without creating a paid task."""

    task_id = str(editing_task_id or "").strip()
    selected_jianying_exe = _resolve_jianying_exe_path(jianying_exe_path)
    jianying_exe_ready = selected_jianying_exe.is_file() and selected_jianying_exe.suffix.lower() == ".exe"
    checks: list[dict[str, object]] = []
    draft_path = ""
    requested_draft_path = str(confirmed_draft_path or "").strip().strip('"')
    task = _task_snapshot(task_id) if task_id else None
    if not task_id:
        if requested_draft_path:
            draft_dir = Path(requested_draft_path).expanduser().resolve()
            if draft_dir.is_file() and draft_dir.name.lower() == "draft_content.json":
                draft_dir = draft_dir.parent
            content_path = draft_dir / "draft_content.json"
            draft_ready = draft_dir.is_dir() and content_path.is_file()
            draft_path = str(draft_dir) if draft_ready else ""
            checks.append({
                "id": "confirmed_draft",
                "label": "包装校对确认草稿",
                "state": "ready" if draft_ready else "blocked",
                "required": True,
                "message": "包装校对已确认，草稿文件可读取。" if draft_ready else f"包装校对确认的草稿不可读取：{draft_dir}",
            })
        else:
            checks.append({
                "id": "editing_task",
                "label": "已确认草稿任务",
                "state": "blocked",
                "required": True,
                "message": "缺少 editing_task 或包装校对确认的草稿路径。",
            })
    elif task is None or task.get("task_type") != "editing_draft":
        checks.append({
            "id": "editing_task",
            "label": "已确认草稿任务",
            "state": "blocked",
            "required": True,
            "message": "未找到有效的 Windows 草稿任务。",
        })
    elif task.get("state") != "succeeded":
        checks.append({
            "id": "editing_task",
            "label": "已确认草稿任务",
            "state": "pending",
            "required": True,
            "message": str(task.get("message") or "草稿任务尚未完成。"),
        })
    else:
        result = task.get("result") if isinstance(task.get("result"), Mapping) else {}
        draft_path = str(result.get("draft_path") or "").strip()
        draft_dir = Path(draft_path).expanduser() if draft_path else None
        content_path = draft_dir / "draft_content.json" if draft_dir else None
        draft_ready = bool(draft_dir and draft_dir.is_dir() and content_path and content_path.is_file())
        checks.append({
            "id": "editing_task",
            "label": "已确认草稿任务",
            "state": "ready" if draft_ready else "blocked",
            "required": True,
            "message": "草稿任务已完成，草稿文件可读取。" if draft_ready else "任务成功但本地 draft_content.json 不存在。",
        })

    checks.append({
        "id": "jianying_exe",
        "label": "剪映程序文件",
        "state": "ready" if jianying_exe_ready else "blocked",
        "required": True,
        "message": str(selected_jianying_exe) if jianying_exe_ready else f"文件不存在或不是 .exe：{selected_jianying_exe}",
        "path": str(selected_jianying_exe),
    })
    draft_root_ready = JIANYING_DRAFT_ROOT.is_dir()
    checks.append({
        "id": "jianying_draft_root",
        "label": "剪映草稿目录",
        "state": "ready" if draft_root_ready else "blocked",
        "required": True,
        "message": str(JIANYING_DRAFT_ROOT) if draft_root_ready else f"目录不存在：{JIANYING_DRAFT_ROOT}",
    })
    for executable in ("ffmpeg", "ffprobe"):
        path = shutil.which(executable)
        checks.append({
            "id": executable,
            "label": executable.upper(),
            "state": "ready" if path else "blocked",
            "required": True,
            "message": path or f"未找到 {executable}。",
        })
    checks.append(_probe_capcut_mate())
    checks.append({
        "id": "video_executor",
        "label": "最终视频制作执行器",
        "state": "blocked",
        "required": True,
        "message": "页面预检已接入；最终视频导出 transport 尚未接入，未创建伪造任务。",
    })
    blocked = [item for item in checks if item.get("required") and item.get("state") == "blocked"]
    pending = [item for item in checks if item.get("required") and item.get("state") == "pending"]
    status = "blocked" if blocked else "pending" if pending else "ready"
    return {
        "status": status,
        "can_start": status == "ready",
        "editing_task_id": task_id,
        "draft_path": draft_path,
        "jianying_exe_path": str(selected_jianying_exe),
        "checks": checks,
        "message": "全部预检通过，可以开始制作。" if status == "ready" else "依赖或执行器未就绪，暂不能开始制作。",
    }


def _wake_capcut_mate(
    editing_task_id: str = "",
    jianying_exe_path: object = None,
    confirmed_draft_path: object = None,
) -> dict[str, object]:
    """Start only the configured local CapCut Mate process, then re-run preflight."""

    before = _probe_capcut_mate()
    if before.get("state") == "ready":
        result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
        result["wake_message"] = "CapCut Mate 已在运行，已重新检查依赖。"
        return result
    base_url = _capcut_mate_base_url()
    parsed = urlparse(base_url)
    if parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:
        result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
        result["wake_message"] = "当前是远程 CapCut Mate 地址，未在本机启动进程。"
        return result
    root = CAPCUT_MATE_ROOT.expanduser().resolve()
    python_path = root / ".venv" / "Scripts" / "python.exe"
    pythonw_path = root / ".venv" / "Scripts" / "pythonw.exe"
    main_path = root / "main.py"
    if not root.is_dir() or not python_path.is_file() or not main_path.is_file():
        result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
        result["wake_message"] = f"本机 CapCut Mate 运行文件不完整：{root}"
        return result
    try:
        # Prefer pythonw.exe so the long-running API process never creates a
        # visible console window. Keep python.exe as a migration-safe fallback
        # for virtual environments that do not contain pythonw.exe.
        launcher_path = pythonw_path if pythonw_path.is_file() else python_path
        flags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) | getattr(subprocess, "CREATE_NO_WINDOW", 0)
        startupinfo = None
        if os.name == "nt" and hasattr(subprocess, "STARTUPINFO"):
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= getattr(subprocess, "STARTF_USESHOWWINDOW", 0)
            startupinfo.wShowWindow = 0
        subprocess.Popen(
            [str(launcher_path), str(main_path)],
            cwd=str(root),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.STDOUT,
            creationflags=flags,
            startupinfo=startupinfo,
            close_fds=True,
        )
    except (OSError, ValueError) as exc:
        result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
        result["wake_message"] = f"CapCut Mate 启动失败：{type(exc).__name__}"
        return result
    for _ in range(20):
        time.sleep(0.5)
        if _probe_capcut_mate().get("state") == "ready":
            result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
            result["wake_message"] = "CapCut Mate 已在后台唤醒，已重新检查依赖；不会保留黑色命令窗口。"
            return result
    result = _video_production_preflight(editing_task_id, jianying_exe_path, confirmed_draft_path)
    result["wake_message"] = "已尝试唤醒 CapCut Mate，但 30000 端口仍未通过检查。"
    return result


def _start_video_production(payload: Mapping[str, object]) -> dict[str, object]:
    """Respect the production gate; do not fabricate a final video task."""

    editing_task_id = str(payload.get("editing_task_id") or "").strip()
    result = _video_production_preflight(
        editing_task_id,
        payload.get("jianying_exe_path"),
        payload.get("draft_path"),
    )
    if not result.get("can_start"):
        result["status"] = "blocked"
        result["message"] = "视频制作未启动：" + str(result.get("message") or "预检未通过。")
        return result
    result["status"] = "blocked"
    result["can_start"] = False
    result["message"] = "视频制作未启动：最终视频制作 transport 尚未接入，未创建伪造任务。"
    return result


def _subtitle_correction_transport_from_runtime() -> SubtitleCorrectionTransport:
    return SubtitleCorrectionTransport.from_api_management(
        config_path=API_MANAGEMENT_CONFIG_PATH,
        auth_document=_runtime_auth_document(),
    )


def _apply_capcut_stt_subtitle_correction(
    raw_lock: Mapping[str, object],
    *,
    settings: Mapping[str, object] | None = None,
) -> tuple[dict[str, object], dict[str, object]]:
    """只接受编导锁定阶段已经完成的 TTS -> STT -> Mini 字幕结果。

    编辑阶段不得再次生成字幕，也不得接收旧锁定稿或 legacy 字幕来源；
    旧数据只能从归档中召回，不能进入当前生产链。
    """

    settings = settings or {}
    source = str(settings.get("subtitle_source") or "capcut_stt").strip().lower()
    if source not in {"", "capcut_stt", "capcut_stt_doubao_mini"}:
        raise ValueError("旧字幕来源已废弃；编辑链路只接受 capcut_stt_doubao_mini")
    precomputed = raw_lock.get("subtitle_pipeline")
    if (
        isinstance(precomputed, Mapping)
        and str(precomputed.get("status") or "").strip().lower() == "succeeded"
        and str(precomputed.get("source") or "").strip().lower() == "capcut_stt_doubao_mini"
        and isinstance(raw_lock.get("captions"), list)
        and raw_lock.get("captions")
    ):
        return dict(raw_lock), {
            "status": "skipped",
            "source": "locked_capcut_stt_doubao_mini",
            "reason": "锁定阶段已使用真实 TTS 音频完成 STT 与文本校对，避免重复调用",
            "timeline_unit": "microseconds",
            "pipeline": dict(precomputed),
        }
    raise ValueError(
        "当前编辑链路只接受编导锁定阶段已生成的 subtitle_pipeline；"
        "旧锁定稿必须先在归档中处理，不能在生产链路补做字幕"
    )



def _run_editing_task(task_id: str, payload: dict) -> None:
    """Create one Windows native Jianying draft from the latest complete assets."""

    def report(stage: str, progress: int, message: str) -> None:
        _set_task(task_id, state="running", stage=stage, progress=max(0, min(100, progress)), message=message)

    try:
        source_story_task_id = str(payload.get("story_task_id") or "").strip()
        report("loading_handoff", 8, "正在读取已审核编导锁定数据和可复用付费素材")
        _story_task, shot_task, shot_result, asset_task_id, asset_result = _load_editing_source_inputs(source_story_task_id)

        from workflow_1256.editing_layer import (
            compile_editing_layer,
            normalize_editing_settings,
            validate_windows_native_plan,
            write_windows_native_draft,
        )
        from workflow_1256.real_asset_handoff import build_live_asset_registry, director_from_lock

        user_settings = dict(payload.get("settings") or {}) if isinstance(payload.get("settings"), Mapping) else {}
        raw_director_lock = shot_result.get("director_lock") if isinstance(shot_result, Mapping) else None
        if not isinstance(raw_director_lock, Mapping):
            raise ValueError("逐镜脚本缺少 director_lock，不能生成字幕")
        report("subtitle_stt", 16, "正在读取编导锁定阶段已完成的 TTS-STT-Mini 字幕")
        corrected_director_lock, subtitle_pipeline = _apply_capcut_stt_subtitle_correction(
            raw_director_lock,
            settings=user_settings,
        )
        director = director_from_lock(corrected_director_lock)
        shot_script = [item for item in shot_result.get("shot_video_script") or [] if isinstance(item, Mapping)]
        packaging_application = _resolve_editing_packaging_application(
            payload,
            shot_script,
            shot_result.get("transition_points") or [],
            shot_result.get("transition_timeline_unit") or "microseconds",
            shot_result.get("opening_title")
            or asset_result.get("opening_title")
            or _opening_title_from_story_payload(
                shot_result.get("director_lock") if isinstance(shot_result.get("director_lock"), Mapping) else None,
                fallback_source=shot_result.get("approved_copy") or "",
            ),
        )
        asset_root = Path(str(asset_result.get("output_dir") or "")).expanduser().resolve()
        task_dir = DIRECTOR_REVIEW_DIR / source_story_task_id / "editing_tasks" / task_id
        report("mapping_assets", 30, f"正在把 {len(shot_script)} 个镜头映射到剪辑轨道")
        registry, transfer_report = build_live_asset_registry(
            director,
            shot_script,
            asset_result,
            asset_task_id=asset_task_id,
            prepared_root=task_dir / "editing_handoff_media",
        )
        requested_ratio = str(payload.get("aspect_ratio") or "").strip()
        if requested_ratio and requested_ratio not in SUPPORTED_ASPECT_RATIOS:
            raise ValueError("画幅仅支持 9:16、16:9、1:1、3:2、2:3")
        ratio = requested_ratio or normalize_aspect_ratio(str(asset_result.get("aspect_ratio") or "9:16"))
        requested_draft_name = str(payload.get("draft_name") or "").strip()
        draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
        if not draft_root.is_dir():
            raise ValueError(f"草稿保存目录不存在或不是文件夹：{draft_root}")
        width, height = _editing_canvas(ratio)
        effective_settings = normalize_editing_settings(user_settings)
        plan = compile_editing_layer(director, registry, width=width, height=height, fps=30)
        validate_windows_native_plan(plan)
        task_dir.mkdir(parents=True, exist_ok=True)
        registry_path = task_dir / "asset_registry.json"
        plan_path = task_dir / "editing_plan.json"
        handoff_path = task_dir / "editing_handoff.json"
        subtitle_path = task_dir / "subtitle_pipeline.json"
        corrected_lock_path = task_dir / "director_lock_subtitle_corrected.json"
        registry_path.write_text(json.dumps(registry.to_dict(), ensure_ascii=False, indent=2), encoding="utf-8")
        plan_payload = plan.to_dict()
        plan_payload["user_settings"] = user_settings
        plan_payload["effective_settings"] = effective_settings
        plan_payload["subtitle_pipeline"] = subtitle_pipeline
        plan_path.write_text(json.dumps(plan_payload, ensure_ascii=False, indent=2), encoding="utf-8")
        corrected_lock_path.write_text(json.dumps(corrected_director_lock, ensure_ascii=False, indent=2), encoding="utf-8")
        subtitle_path.write_text(json.dumps(subtitle_pipeline, ensure_ascii=False, indent=2), encoding="utf-8")
        # 这里已经完成了素材绑定和剪辑计划校验，治理契约中的合法状态是
        # EDIT_PLAN_READY；EDIT_MAPPING_READY 只是旧页面曾经使用的展示值，
        # 不属于 EditManifest.status，不能继续写入正式交接清单。
        handoff_payload = {
            "status": "EDIT_PLAN_READY",
            "source_story_task_id": source_story_task_id,
            "source_shot_script_task_id": shot_task.get("task_id"),
            "source_asset_task_id": asset_task_id,
            "timeline_unit": "microseconds",
            "aspect_ratio": ratio,
            "draft_name": requested_draft_name,
            "draft_root": str(draft_root),
            "canvas": {"width": width, "height": height, "fps": 30},
            "asset_registry_path": str(registry_path.resolve()),
            "editing_plan_path": str(plan_path.resolve()),
            "director_lock_subtitle_corrected_path": str(corrected_lock_path.resolve()),
            "subtitle_pipeline_path": str(subtitle_path.resolve()),
            "subtitle_pipeline": subtitle_pipeline,
            "transfer_report": transfer_report,
            "user_settings": user_settings,
            "effective_settings": effective_settings,
            "packaging_bundle": {
                "bundle_name": packaging_application.get("bundle_name"),
                "version": packaging_application.get("version"),
                "available_categories": packaging_application.get("available_categories", []),
                "missing_categories": packaging_application.get("missing_categories", []),
                "transition_timeline_unit": packaging_application.get("transition_timeline_unit", "microseconds"),
                "transition_timeline_source": packaging_application.get("transition_timeline_source", "none"),
                "transition_tolerance_us": packaging_application.get("transition_tolerance_us", TRANSITION_POINT_TOLERANCE_US),
                "transition_points": packaging_application.get("transition_points", []),
                "opening_title": packaging_application.get("opening_title", ""),
            } if packaging_application else None,
            "editing_manifest": plan.to_edit_manifest(status="EDIT_PLAN_READY").to_dict(),
        }
        handoff_path.write_text(json.dumps(handoff_payload, ensure_ascii=False, indent=2), encoding="utf-8")

        draft_name = _resolve_editing_draft_name(
            payload.get("draft_name"), source_story_task_id, task_id
        )
        handoff_payload["draft_name"] = draft_name
        report("writing_windows_draft", 62, "正在使用剪映小助手 Windows 原生 DraftFolder 创建草稿")
        draft_result = write_windows_native_draft(
            plan,
            capcut_mate_root=CAPCUT_MATE_ROOT,
            draft_root=draft_root,
            draft_name=draft_name,
            replace=bool(payload.get("replace")),
            settings=effective_settings,
            packaging_application=packaging_application,
        )
        handoff_payload["status"] = "DRAFT_STRUCTURALLY_VALID"
        handoff_payload["windows_native_result"] = draft_result.to_dict()
        handoff_path.write_text(json.dumps(handoff_payload, ensure_ascii=False, indent=2), encoding="utf-8")
        draft_result_payload = {
            "source_story_task_id": source_story_task_id,
            "source_shot_script_task_id": shot_task.get("task_id"),
            "source_asset_task_id": asset_task_id,
            "aspect_ratio": ratio,
            "draft_name": draft_name,
            "draft_root": str(draft_root),
            "subtitle_pipeline": subtitle_pipeline,
            "director_lock_subtitle_corrected_path": str(corrected_lock_path.resolve()),
            "user_settings": user_settings,
            "effective_settings": effective_settings,
            "draft_path": draft_result.draft_path,
            "duration_us": draft_result.duration_us,
            "tracks": draft_result.tracks,
            "media_paths_exist": draft_result.media_paths_exist,
            "effects_count": draft_result.effects_count,
            "transitions_count": draft_result.transitions_count,
            "packaging_report": getattr(draft_result, "packaging_report", {}),
            "transition_timeline": {
                "unit": (packaging_application or {}).get("transition_timeline_unit", "microseconds"),
                "source": (packaging_application or {}).get("transition_timeline_source", "none"),
                "tolerance_us": (packaging_application or {}).get("transition_tolerance_us", TRANSITION_POINT_TOLERANCE_US),
                "upstream_points": (packaging_application or {}).get("transition_points", []),
                "applied_points": (getattr(draft_result, "packaging_report", {}) or {}).get("transition_points", []),
            },
            "handoff_path": str(handoff_path.resolve()),
            "plan_path": str(plan_path.resolve()),
            "validation": draft_result.edit_manifest.validation,
        }
        # 先把草稿成功状态落盘，确保浏览器能收到终态；随后归档所有历史
        # 运行数据，避免归档动作把当前轮询任务变成 404。
        _set_task(
            task_id,
            state="succeeded",
            stage="draft_created",
            progress=100,
            message="Windows 剪映草稿已创建，媒体路径、平台标记和轨道结构已校验",
            result=draft_result_payload,
        )
        try:
            archive_report = _archive_runtime_data(
                source_story_task_id=source_story_task_id,
                completed_task_id=task_id,
            )
        except Exception as archive_exc:  # 归档失败不能回滚已经创建成功的草稿
            TASK_LOGGER.exception("runtime archive for editing task %s failed", task_id)
            archive_report = {
                "status": "failed",
                "archive_id": "",
                "archived_at": int(time.time()),
                "moved_count": 0,
                "moved": [],
                "preserved": [
                    "outputs/style_packages/profiles",
                    "outputs/director_tts_cache（付费 TTS 复用缓存）",
                ],
                "errors": [f"归档异常：{type(archive_exc).__name__}"],
            }
        with STYLE_TASKS_LOCK:
            completed_task = STYLE_TASKS.get(task_id)
            if completed_task is not None:
                completed_result = dict(completed_task.get("result") or {})
                completed_result["runtime_archive"] = archive_report
                completed_task["result"] = completed_result
                completed_task["message"] = "Windows 剪映草稿已创建；历史运行数据已归档，页面仅保留风格包。"
                completed_task["updated_at"] = int(time.time())
    except Exception as exc:
        detail = str(exc).replace("\r", " ").replace("\n", " ").strip()[:600]
        TASK_LOGGER.exception("editing task %s crashed", task_id)
        _set_task(
            task_id,
            state="failed",
            stage="draft_creation_failed",
            progress=100,
            message=f"Windows 草稿创建失败：{type(exc).__name__}：{detail or '无错误详情'}",
            result={
                "source_story_task_id": str(payload.get("story_task_id") or ""),
                "error": detail,
                "replaceable": "草稿已存在" in detail,
            },
        )


def _create_editing_task(payload: dict) -> dict:
    source_story_task_id = str(payload.get("story_task_id") or "").strip()
    if not source_story_task_id:
        raise ValueError("缺失 story_task_id；请从素材生产层进入剪辑交付")
    if _handoff_story_task_snapshot(source_story_task_id) is None:
        raise ValueError("未找到v2 编导任务")
    requested_ratio = str(payload.get("aspect_ratio") or "").strip()
    if requested_ratio and requested_ratio not in SUPPORTED_ASPECT_RATIOS:
        raise ValueError("画幅仅支持 9:16、16:9、1:1、3:2、2:3")
    requested_draft_name = str(payload.get("draft_name") or "").strip()
    replace_existing = bool(payload.get("replace"))
    draft_root = _resolve_jianying_draft_root(payload.get("draft_root"))
    if not draft_root.is_dir():
        raise ValueError(f"草稿保存目录不存在或不是文件夹：{draft_root}")
    for item in _list_style_tasks(limit=2000, source_story_task_id=source_story_task_id):
        if item.get("task_type") == "editing_draft" and item.get("state") in {"queued", "running"}:
            return item
    task_id = uuid.uuid4().hex
    now = int(time.time())
    task = {
        "task_id": task_id,
        "task_type": "editing_draft",
        "source_story_task_id": source_story_task_id,
        "input": {
            "source_story_task_id": source_story_task_id,
            "aspect_ratio": requested_ratio,
            "draft_name": requested_draft_name,
            "draft_root": str(draft_root),
            "replace": replace_existing,
        },
        "aspect_ratio": requested_ratio,
        "draft_name": requested_draft_name,
        "draft_root": str(draft_root),
        "replace": replace_existing,
        "state": "queued",
        "stage": "queued",
        "progress": 0,
        "message": "Windows 草稿任务正在排队",
        "created_at": now,
        "updated_at": now,
    }
    with STYLE_TASKS_LOCK:
        STYLE_TASKS[task_id] = task
    # 编辑交付任务也遵循“先持久化、后启动 worker”的统一契约。
    try:
        _persist_task_required(task)
    except TaskPersistenceError:
        with STYLE_TASKS_LOCK:
            STYLE_TASKS.pop(task_id, None)
        raise
    threading.Thread(target=_run_editing_task, args=(task_id, dict(payload)), daemon=True).start()
    return _task_snapshot(task_id) or task


def _api_management_first_env(names: tuple[str, ...]) -> tuple[str, str]:
    for name in names:
        value = os.environ.get(name, "").strip()
        if value:
            return name, value
    return "", ""


def _api_management_model_usage_label(source: str) -> str:
    if source in API_MANAGEMENT_MODEL_USAGE_LABELS:
        return str(API_MANAGEMENT_MODEL_USAGE_LABELS[source])
    return source.replace("_", " ").strip().title() or "模型"


def _api_management_model_env_names(channel_id: str) -> set[str]:
    channel_id = _api_management_channel_base_id(channel_id)
    channel = next(
        (item for item in API_MANAGEMENT_CHANNELS if str(item.get("id") or "") == str(channel_id)),
        None,
    )
    if not channel:
        return set()
    provider_ids = {str(item) for item in channel.get("provider_ids", ())}
    return {
        str(env_name)
        for spec in API_MANAGEMENT_SPECS
        if str(spec.get("id") or "") in provider_ids
        for env_name in spec.get("model_envs", ())
        if str(env_name).strip()
    }


def _backfill_expression_habits(style_profile_id: str) -> tuple[int, dict]:
    """Backfill an empty habit library from the saved transcript collection."""

    record = STYLE_PACKAGE_STORE.get_profile(style_profile_id)
    profile = record.get("style_profile") if isinstance(record.get("style_profile"), Mapping) else {}
    existing = profile.get("expression_habit_library") if isinstance(profile, Mapping) else None
    existing_habits = existing.get("habits") if isinstance(existing, Mapping) else []
    if isinstance(existing_habits, list) and existing_habits:
        return 200, {
            "status": "expression_habits_already_present",
            "message": "当前风格包已经有表达习惯库，无需重复补提取。",
            "record": record,
        }
    collection_id = str(record.get("collection_id") or "").strip()
    collection = STYLE_PACKAGE_STORE.get_collection(collection_id)
    items = collection.get("items") if isinstance(collection.get("items"), list) else []
    library = extract_expression_habit_library(items)
    if not library.get("habits"):
        return 409, {
            "status": "expression_habits_insufficient",
            "message": "已保存的转写样本不足以观察到可重复表达习惯，未修改风格包。",
            "sample_count": len(items),
        }
    updated = STYLE_PACKAGE_STORE.update_expression_habit_library(
        style_profile_id,
        library=library,
        warning="expression_habit_library: 已根据已保存转写补充抽象表达习惯，未保存原句",
    )
    return 200, {
        "status": "expression_habits_backfilled",
        "message": f"已从 {len(items)} 条已保存转写补充 {len(library['habits'])} 类表达习惯。",
        "record": updated,
    }


def _api_management_is_custom_model_source(source: str) -> bool:
    """Return whether a model slot was added from the API management page."""

    return bool(re.fullmatch(r"custom_model_[A-Za-z0-9_-]{1,80}", str(source or "").strip()))


def _api_management_channel_base_id(channel_id: str) -> str:
    text = str(channel_id or "").strip()
    return text.split("__custom_", 1)[0] if "__custom_" in text else text


def _api_management_is_custom_channel_id(channel_id: str) -> bool:
    return bool(re.fullmatch(r"[a-z0-9-]+__custom_[A-Za-z0-9_-]{1,80}", str(channel_id or "").strip()))


def _api_management_group_channel_specs(
    group: Mapping[str, object], config: Mapping[str, object] | None = None
) -> list[dict[str, object]]:
    """Build static channels plus user-added API credential groups."""

    group_id = str(group.get("id") or "")
    raw_removed_channels = (config or {}).get("removed_channels") if isinstance(config, Mapping) else {}
    raw_removed_for_group = (
        raw_removed_channels.get(group_id, [])
        if isinstance(raw_removed_channels, Mapping)
        else []
    )
    removed_ids = {
        str(item).strip()
        for item in raw_removed_for_group
        if str(item).strip()
    } if isinstance(raw_removed_for_group, (list, tuple, set)) else set()
    base_ids = [
        str(item).strip()
        for item in group.get("channel_ids", ())
        if str(item).strip() and str(item).strip() not in removed_ids
    ]
    all_base_ids = {
        str(item).strip()
        for item in group.get("channel_ids", ())
        if str(item).strip()
    }
    static_by_id = {
        str(channel.get("id") or ""): dict(channel)
        for channel in API_MANAGEMENT_CHANNELS
        if str(channel.get("id") or "") in all_base_ids
    }
    result = [dict(static_by_id[channel_id]) for channel_id in base_ids if channel_id in static_by_id]
    raw_api_channels = (config or {}).get("api_channels") if isinstance(config, Mapping) else {}
    raw_definitions = raw_api_channels.get(group_id, []) if isinstance(raw_api_channels, Mapping) else []
    if not isinstance(raw_definitions, (list, tuple)):
        return result
    existing_ids = {str(item.get("id") or "") for item in result}
    for raw_definition in raw_definitions:
        if not isinstance(raw_definition, Mapping):
            continue
        custom_id = str(raw_definition.get("id") or "").strip()
        base_id = str(raw_definition.get("base_channel_id") or "").strip()
        base = static_by_id.get(base_id)
        if not base or not _api_management_is_custom_channel_id(custom_id) or custom_id in existing_ids:
            continue
        label = str(raw_definition.get("label") or "").strip()[:80]
        clone = dict(base)
        clone["id"] = custom_id
        clone["base_channel_id"] = base_id
        clone["is_custom_channel"] = True
        clone["credential_name"] = label or "新增 API"
        result.append(clone)
        existing_ids.add(custom_id)
    return result


def _api_management_document_state(spec: Mapping[str, object]) -> tuple[bool, str]:
    markers = tuple(str(item) for item in spec.get("document_markers", ()) if str(item).strip())
    if not markers:
        return False, ""
    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        return False, "已禁用（8768 页面凭据专用）"
    document = Path(
        os.environ.get("DIRECTOR_AUTH_DOCUMENT", str(DEFAULT_AUTH_DOCUMENT))
    ).expanduser()
    if not document.is_file():
        return False, str(document)
    try:
        content = document.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False, str(document)
    # The shared Markdown auth document escapes underscores as ``\_``. The
    # runtime credential loader already accepts that form; normalize it here
    # as well so the API management page reports the same real state.
    normalized_content = content.replace("\\_", "_")
    return any(
        re.search(re.escape(marker), normalized_content, flags=re.IGNORECASE)
        for marker in markers
    ), str(document)


def _api_management_safe_url(value: str) -> str:
    value = value.strip()
    if not value:
        return ""
    try:
        parsed = urlparse(value)
    except ValueError:
        return value.split("?", 1)[0].split("#", 1)[0]
    if parsed.scheme and parsed.netloc:
        return parsed._replace(query="", fragment="").geturl()
    return value.split("?", 1)[0].split("#", 1)[0]


class _API_MANAGEMENT_DATA_BLOB(ctypes.Structure):
    _fields_ = [
        ("cbData", wintypes.DWORD),
        ("pbData", ctypes.POINTER(ctypes.c_ubyte)),
    ]


_API_MANAGEMENT_CRYPTPROTECT_LOCAL_MACHINE = 0x04


def _api_management_dpapi(data: bytes, *, protect: bool, flags: int = 0) -> bytes:
    """Encrypt/decrypt local API credentials with the current Windows user DPAPI."""
    if os.name != "nt":
        raise RuntimeError("API 密钥加密保存仅支持 Windows 当前用户凭据")
    input_buffer = ctypes.create_string_buffer(data)
    input_blob = _API_MANAGEMENT_DATA_BLOB(
        len(data),
        ctypes.cast(input_buffer, ctypes.POINTER(ctypes.c_ubyte)),
    )
    output_blob = _API_MANAGEMENT_DATA_BLOB()
    crypt32 = ctypes.WinDLL("Crypt32.dll", use_last_error=True)
    kernel32 = ctypes.WinDLL("Kernel32.dll", use_last_error=True)
    function = crypt32.CryptProtectData if protect else crypt32.CryptUnprotectData
    function.argtypes = [
        ctypes.POINTER(_API_MANAGEMENT_DATA_BLOB),
        wintypes.LPCWSTR,
        ctypes.POINTER(_API_MANAGEMENT_DATA_BLOB),
        wintypes.LPVOID,
        wintypes.LPVOID,
        wintypes.DWORD,
        ctypes.POINTER(_API_MANAGEMENT_DATA_BLOB),
    ]
    function.restype = wintypes.BOOL
    if not function(ctypes.byref(input_blob), None, None, None, None, flags, ctypes.byref(output_blob)):
        error_code = ctypes.get_last_error()
        raise OSError(error_code, "Windows DPAPI 操作失败")
    try:
        return ctypes.string_at(output_blob.pbData, output_blob.cbData)
    finally:
        kernel32.LocalFree(output_blob.pbData)


def _api_management_seal(data: bytes) -> bytes:
    """Use machine-scoped DPAPI so governed service restarts keep one keyring.

    The console may be restarted by a different local service identity than
    the one that opened the browser.  User-scoped DPAPI then makes an intact
    credential file unreadable after that identity change.  Machine scope
    keeps the values encrypted at rest while allowing the local governed
    service to read them across restarts; plaintext is never written to disk,
    returned by the API, or placed in task snapshots.
    """
    return b"M1:" + _api_management_dpapi(
        data,
        protect=True,
        flags=_API_MANAGEMENT_CRYPTPROTECT_LOCAL_MACHINE,
    )


def _api_management_unseal(data: bytes) -> bytes:
    if data.startswith(b"M1:"):
        return _api_management_dpapi(data[3:], protect=False)
    if data.startswith(b"U1:"):
        return _api_management_dpapi(data[3:], protect=False)
    # Read files created before the scope marker was introduced.
    try:
        return _api_management_dpapi(data, protect=False)
    except OSError:
        return _api_management_dpapi(data, protect=False, flags=_API_MANAGEMENT_CRYPTPROTECT_LOCAL_MACHINE)


def _api_management_normalize_extra_keys(value: object) -> list[str]:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError:
            return []
    if not isinstance(value, (list, tuple)):
        return []
    result: list[str] = []
    for item in value:
        if not isinstance(item, str):
            continue
        text = item.strip()
        if text and text not in result:
            result.append(text)
    return result


def _api_management_extra_keys_from_env(env_name: str) -> list[str]:
    return _api_management_normalize_extra_keys(os.environ.get(env_name, ""))


def _api_management_set_secret_health(
    state: str,
    *,
    scope: str = "",
    error_code: str = "",
    message: str = "",
    recovery_backup_path: str = "",
) -> None:
    _API_MANAGEMENT_SECRET_HEALTH.update({
        "state": str(state or "unknown"),
        "scope": str(scope or ""),
        "path": str(API_MANAGEMENT_SECRET_PATH),
        "error_code": str(error_code or ""),
        "message": str(message or "")[:240],
        "recovery_backup_path": str(recovery_backup_path or ""),
    })
    os.environ[API_MANAGEMENT_SECRET_STATUS_ENV] = str(state or "unknown")
    if message:
        os.environ[API_MANAGEMENT_SECRET_ERROR_ENV] = str(message)[:240]
    else:
        os.environ.pop(API_MANAGEMENT_SECRET_ERROR_ENV, None)


def _api_management_secret_health_snapshot() -> dict[str, object]:
    return {
        **_API_MANAGEMENT_SECRET_HEALTH,
        "path": str(API_MANAGEMENT_SECRET_PATH),
    }


def _api_management_tts_primary_page_key() -> str:
    """Return only the TTS primary key saved by the API management page.

    Voice-clone V3 is a data-plane operation that shares the TTS primary
    ``X-Api-Key``.  It must never infer a credential from inherited
    environment variables, the legacy auth document, or the TTS backup key.
    Keeping this lookup in one helper prevents the page snapshot, auth audit,
    and the actual voice-clone transport from drifting apart.
    """

    secrets = _api_management_load_secrets()
    tts_secrets = secrets.get("tts", {}) if isinstance(secrets, Mapping) else {}
    if not isinstance(tts_secrets, Mapping):
        return ""
    health = _api_management_secret_health_snapshot()
    if str(health.get("state") or "") == "unreadable":
        return ""
    return str(tts_secrets.get("primary_api_key") or "").strip()


def _api_management_effective_credential_source() -> str:
    state = str(_API_MANAGEMENT_SECRET_HEALTH.get("state") or "unknown")
    if state == "loaded":
        return "page_encrypted"
    if state == "unreadable":
        return "page_secret_unreadable"
    if state == "missing":
        return "environment_or_document"
    return state or "unknown"


def _api_management_secret_read_error(exc: Exception) -> tuple[str, str]:
    error_code = str(
        getattr(exc, "winerror", "")
        or getattr(exc, "errno", "")
        or type(exc).__name__
    )
    if isinstance(exc, OSError) and getattr(exc, "winerror", None) in {2, 13, 31}:
        message = "Windows DPAPI 无法在当前服务身份下解密本机密钥文件"
    else:
        message = "本机加密 API 凭据无法读取，请重新输入"
    return error_code, message


def _api_management_load_secrets(*, strict: bool = False) -> dict[str, dict[str, object]]:
    if not API_MANAGEMENT_SECRET_PATH.is_file():
        _api_management_set_secret_health("missing")
        return {}
    try:
        encoded = API_MANAGEMENT_SECRET_PATH.read_text(encoding="ascii").strip()
        sealed = base64.b64decode(encoded)
        scope = "user" if sealed.startswith(b"U1:") else ("machine" if sealed.startswith(b"M1:") else "legacy")
        decrypted = _api_management_unseal(sealed)
        raw = json.loads(decrypted.decode("utf-8"))
        channels = raw.get("channels") if isinstance(raw, Mapping) else {}
        if not isinstance(channels, Mapping):
            _api_management_set_secret_health("invalid", scope=scope, message="本机加密 API 凭据内容不是合法通道映射")
            return {}
        result: dict[str, dict[str, object]] = {}
        for channel_id, values in channels.items():
            if not isinstance(values, Mapping):
                continue
            normalized: dict[str, object] = {}
            for field, value in values.items():
                field_name = str(field)
                if field_name == "extra_api_keys":
                    extra_keys = _api_management_normalize_extra_keys(value)
                    if extra_keys:
                        normalized[field_name] = extra_keys
                elif str(value).strip():
                    normalized[field_name] = str(value).strip()
            if normalized:
                result[str(channel_id)] = normalized
        _api_management_set_secret_health("loaded", scope=scope)
        return result
    except Exception as exc:
        error_code, message = _api_management_secret_read_error(exc)
        _api_management_set_secret_health(
            "unreadable",
            error_code=error_code,
            message=message,
        )
        if strict:
            raise ValueError(message) from exc
        return {}


def _seed_audio_transport_from_api_management(*, local_output_dir: str | Path | None = None) -> SeedAudioHTTPTransport:
    """使用 API 管理页的独立 sound-effect 通道构造 transport，不自动联网。"""
    secrets = _api_management_load_secrets(strict=True)
    channel = secrets.get("sound-effect")
    # 火山方舟 API Key 是项目级凭证；Seed-Audio 与 TTS 使用同样的
    # Bearer API Key 鉴权。若未单独保存 sound-effect 通道，复用现有
    # TTS/Ark Key，最终是否具备 Seed-Audio 邀测权限交由官方接口判定。
    if not isinstance(channel, Mapping):
        channel = secrets.get("tts")
    if not isinstance(channel, Mapping):
        raise ValueError("API 管理页没有可复用的方舟 API Key；不会调用公网接口")
    config = _api_management_load_config()
    groups = config.get("groups") if isinstance(config, Mapping) else {}
    settings = groups.get("sound-effect") if isinstance(groups, Mapping) else {}
    settings = settings if isinstance(settings, Mapping) else {}
    endpoint = str(settings.get("endpoint") or "").strip() or None
    try:
        timeout_value = float(settings.get("timeout_seconds")) if settings.get("timeout_seconds") is not None else None
    except (TypeError, ValueError):
        timeout_value = None
    return SeedAudioHTTPTransport.from_api_management_secrets({"sound-effect": channel}, api_url=endpoint, timeout=timeout_value, local_output_dir=local_output_dir)


def _api_management_write_secrets(secrets: Mapping[str, Mapping[str, object]]) -> None:
    payload = json.dumps({"version": 1, "channels": secrets}, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    encoded = base64.b64encode(_api_management_seal(payload)).decode("ascii")
    API_MANAGEMENT_SECRET_PATH.parent.mkdir(parents=True, exist_ok=True)
    temporary = API_MANAGEMENT_SECRET_PATH.with_suffix(".tmp")
    temporary.write_text(encoded + "\n", encoding="ascii")
    temporary.replace(API_MANAGEMENT_SECRET_PATH)


def _api_management_first_secret_env(names: tuple[str, ...]) -> tuple[str, str]:
    for name in names:
        value = os.environ.get(name, "").strip()
        if value:
            return name, value
    return "", ""


def _api_management_image2_runtime_targets(config: Mapping[str, object] | None = None) -> list[dict[str, object]]:
    """构造按 API1/API2 隔离的 GPT Image 2 All 异步运行时目标。

    页面托管模式只读取 DPAPI 解密出的通道密钥，绝不回退到继承环境变量或旧鉴权文档。
    """
    config = config or _api_management_load_config()
    group = next((item for item in API_MANAGEMENT_GROUPS if str(item.get("id") or "") == "image-generation"), None)
    if not group:
        return []
    channel_specs = _api_management_group_channel_specs(group, config)
    by_id = {str(item.get("id") or ""): item for item in channel_specs}
    raw_api_groups = config.get("api_groups") if isinstance(config, Mapping) else {}
    failover = raw_api_groups.get("image-generation") if isinstance(raw_api_groups, Mapping) else {}
    raw_order = failover.get("order") if isinstance(failover, Mapping) else None
    order = [str(value).strip() for value in raw_order if str(value).strip() in by_id] if isinstance(raw_order, (list, tuple)) else []
    order.extend(channel_id for channel_id in by_id if channel_id not in order)
    groups = config.get("groups") if isinstance(config, Mapping) else {}
    groups = groups if isinstance(groups, Mapping) else {}
    secrets = _api_management_load_secrets()
    base_settings = groups.get("image-generation") if isinstance(groups.get("image-generation"), Mapping) else {}
    base_endpoint = str(base_settings.get("endpoint") or "").strip() if isinstance(base_settings, Mapping) else ""
    base_endpoint = base_endpoint or os.environ.get("IMAGE2_BASE_URL", "").strip() or "https://api.apimodels.app/v1/"
    result: list[dict[str, object]] = []
    for channel_id in order:
        settings = groups.get(channel_id) if isinstance(groups.get(channel_id), Mapping) else {}
        settings = settings if isinstance(settings, Mapping) else {}
        stored = secrets.get(channel_id) if isinstance(secrets.get(channel_id), Mapping) else {}
        stored = stored if isinstance(stored, Mapping) else {}
        endpoint = str(settings.get("endpoint") or base_endpoint).strip() or base_endpoint
        model_id = str(settings.get("primary_model") or "").strip()
        slots = settings.get("model_slots")
        if not model_id and isinstance(slots, Mapping):
            model_id = next((str(value).strip() for value in slots.values() if str(value).strip()), "")
        model_id = model_id or os.environ.get("IMAGE2_MODEL", "").strip() or "gpt-image-2-all"
        if model_id in {"image2", "gpt-image-2"}: model_id = "gpt-image-2-all"
        quality = str(settings.get("quality") or os.environ.get("IMAGE2_QUALITY") or "low").strip().lower()
        if quality not in {"low", "medium", "high", "auto"}: quality = "low"
        keys: list[str] = []
        for field in ("primary_api_key", "backup_api_key"):
            value = str(stored.get(field) or "").strip()
            if value and value not in keys: keys.append(value)
        for value in _api_management_normalize_extra_keys(stored.get("extra_api_keys")):
            if value not in keys: keys.append(value)
        if not keys:
            continue
        result.append({"channel_id": channel_id, "endpoint": endpoint, "model_id": model_id, "quality": quality, "timeout_seconds": max(90, min(900, int(settings.get("timeout_seconds") or 180))), "api_keys": keys})
    return result


def _api_management_apply_secret_runtime() -> None:
    for spec in API_MANAGEMENT_EXTRA_SECRET_RUNTIME.values():
        os.environ.pop(str(spec["env"]), None)
    # 旧 BGM transport 使用 API Key；当前 imagination 直连只认独立 AK/SK，
    # 清掉历史 BGM API Key，防止任何旧入口把它误当成音乐凭据。
    for legacy_name in ("ARK_BGM_API_KEY", "ARK_BGM_BACKUP_API_KEY"):
        os.environ.pop(legacy_name, None)
    secrets = _api_management_load_secrets()
    # 页面上的第二个 API 配置组是独立凭据，不应覆盖基础 API 的主 Key。
    # 对支持 API 级降级的通道，把自定义配置组的主/备用 Key 追加到
    # 基础通道的额外 Key 列表；这样 transport 会按“基础 API → API2”
    # 使用各自密钥，而不是把 API1 的密钥伪装成 API2。密钥只存在当前
    # 进程环境，仍不会写入普通配置、日志或页面返回值。
    extra_keys_by_base: dict[str, list[str]] = {}
    for channel_id, fields in secrets.items():
        base_channel_id = _api_management_channel_base_id(channel_id)
        if _api_management_is_custom_channel_id(channel_id):
            extra_spec = API_MANAGEMENT_EXTRA_SECRET_RUNTIME.get(base_channel_id)
            if extra_spec:
                target = extra_keys_by_base.setdefault(base_channel_id, [])
                for field in ("primary_api_key", "backup_api_key"):
                    value = str(fields.get(field) or "").strip()
                    if value and value not in target:
                        target.append(value)
            continue
        aliases = API_MANAGEMENT_SECRET_RUNTIME.get(base_channel_id, {})
        for field, value in fields.items():
            if field == "extra_api_keys":
                extra_keys_by_base.setdefault(base_channel_id, []).extend(
                    _api_management_normalize_extra_keys(value)
                )
                continue
            if not value:
                continue
            for env_name in aliases.get(field, ()):
                os.environ[str(env_name)] = str(value)
    for base_channel_id, extra_keys in extra_keys_by_base.items():
        spec = API_MANAGEMENT_EXTRA_SECRET_RUNTIME.get(base_channel_id)
        if not spec:
            continue
        normalized = list(dict.fromkeys(str(value).strip() for value in extra_keys if str(value).strip()))
        if normalized:
            os.environ[str(spec["env"])] = json.dumps(normalized, ensure_ascii=False)


def _api_management_require_runtime_credentials(channel_ids: Sequence[str]) -> None:
    """阻止外部任务在页面密钥不可解密时静默回退到旧文档/环境变量。"""

    health = _api_management_secret_health_snapshot()
    if str(health.get("state") or "") != "unreadable":
        return
    requested = [str(value).strip() for value in channel_ids if str(value).strip()]
    label = "、".join(requested) or "当前 API 通道"
    raise RuntimeError(
        f"{label} 未启动：{health.get('message') or '本机加密 API 凭据无法读取'}；"
        "已阻止鉴权文档/环境变量回退，请在 8768/API 管理重新输入凭据"
    )


def _api_management_save_secrets(channel_id: str, raw_secrets: Mapping[str, object]) -> None:
    base_channel_id = _api_management_channel_base_id(channel_id)
    aliases = API_MANAGEMENT_SECRET_RUNTIME.get(base_channel_id, {})
    extra_spec = API_MANAGEMENT_EXTRA_SECRET_RUNTIME.get(base_channel_id)
    if not raw_secrets:
        # A normal configuration save is also the safe re-key path: when the
        # current service identity can read the existing keyring, rewrite it
        # with the current machine-scoped DPAPI format without asking the user
        # to paste any secret again.
        secrets = _api_management_load_secrets(strict=True)
        if secrets:
            _api_management_write_secrets(secrets)
        return
    if not aliases:
        if raw_secrets and not extra_spec:
            raise ValueError("当前 API 通道不支持页面密钥配置")
        return
    updates: dict[str, object] = {}
    extra_keys_update: list[str] | None = None
    for field, value in raw_secrets.items():
        field_name = str(field)
        if field_name == "extra_api_keys":
            if not extra_spec:
                raise ValueError("当前 API 通道不支持新增备用 API Key")
            extra_keys_update = _api_management_normalize_extra_keys(value)
            updates[field_name] = extra_keys_update
            continue
        if field_name not in aliases:
            raise ValueError("密钥字段不适用于当前 API 通道")
        text = str(value or "").strip()
        if text:
            updates[field_name] = text
    if not updates:
        return
    try:
        secrets = _api_management_load_secrets(strict=True)
    except ValueError:
        # 可能是服务身份变更后留下的旧 DPAPI 文件。用户这次明确输入了
        # 新凭据，允许用新内容恢复运行时，同时把旧密文隔离留证，避免无提示覆盖。
        recovery_dir = API_MANAGEMENT_SECRET_PATH.parent / "unreadable-secret-recovery"
        recovery_dir.mkdir(parents=True, exist_ok=True)
        recovery_path = recovery_dir / (
            API_MANAGEMENT_SECRET_PATH.name
            + "."
            + time.strftime("%Y%m%d-%H%M%S")
            + ".bak"
        )
        try:
            shutil.copy2(API_MANAGEMENT_SECRET_PATH, recovery_path)
        except OSError:
            recovery_path = Path("")
        _api_management_set_secret_health(
            "recovery_pending",
            recovery_backup_path=str(recovery_path) if str(recovery_path) else "",
            message="旧本机密钥无法解密；已隔离，正在使用用户刚输入的新凭据重建",
        )
        secrets = {}
    channel_secrets = dict(secrets.get(channel_id) or {})
    for field, value in updates.items():
        if field != "extra_api_keys":
            channel_secrets[field] = value
    if extra_keys_update is not None:
        existing_extra = _api_management_normalize_extra_keys(channel_secrets.get("extra_api_keys"))
        if not extra_keys_update and not existing_extra and len(updates) == 1:
            return
        merged_extra = list(dict.fromkeys(existing_extra + extra_keys_update))
        limit = int(extra_spec["limit"]) if extra_spec else 0
        if limit and len(merged_extra) > limit:
            raise ValueError(f"额外备用 API Key 最多只能配置 {limit} 条")
        if merged_extra:
            channel_secrets["extra_api_keys"] = merged_extra
        else:
            channel_secrets.pop("extra_api_keys", None)
    secrets[channel_id] = channel_secrets
    _api_management_write_secrets(secrets)


def _api_management_delete_secrets(channel_id: str) -> None:
    secrets = _api_management_load_secrets(strict=True)
    if channel_id not in secrets:
        return
    secrets.pop(channel_id, None)
    _api_management_write_secrets(secrets)


def _api_management_load_config() -> dict[str, object]:
    default = {
        "version": 1,
        "groups": {},
        "api_groups": {},
        "api_functions": {},
        "api_channels": {},
        "removed_channels": {},
    }
    try:
        raw = json.loads(API_MANAGEMENT_CONFIG_PATH.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, UnicodeDecodeError, json.JSONDecodeError):
        return default
    if not isinstance(raw, Mapping):
        return default
    groups = raw.get("groups")
    api_groups = raw.get("api_groups")
    api_functions = raw.get("api_functions")
    api_channels = raw.get("api_channels")
    removed_channels = raw.get("removed_channels")
    raw_guidance_expander = raw.get("first_frame_guidance_expander")
    normalized_api_channels = dict(api_channels) if isinstance(api_channels, Mapping) else {}
    normalized_groups = dict(groups) if isinstance(groups, Mapping) else {}
    # TTS 的新版 V3 endpoint、model 和 resource_id 是协议固定项。清除
    # 历史页面/环境遗留的可编辑字段，避免服务重启后再次把旧配置带回运行时；
    # 主/备用 API Key、策略和超时仍由页面配置保留。
    for channel_id, raw_tts_settings in list(normalized_groups.items()):
        if _api_management_channel_base_id(str(channel_id)) != "tts" or not isinstance(raw_tts_settings, Mapping):
            continue
        migrated_tts_settings = dict(raw_tts_settings)
        for legacy_field in (
            "endpoint", "region", "app_id", "primary_model", "backup_model",
            "model_slots", "model_names", "model_order",
        ):
            migrated_tts_settings.pop(legacy_field, None)
        normalized_groups[str(channel_id)] = migrated_tts_settings
    # 历史声音复刻配置不再进入运行时；即使旧配置文件仍包含该键，
    # 读取时也会丢弃，避免服务重启后重新暴露定制音色入口。
    normalized_groups.pop("voice-clone-admin", None)
    normalized_api_channels.pop("voice-clone-admin", None)
    # TTS 只保留一个官方通道。历史页面曾允许新增“另一套 TTS API”，
    # 但当前主/副 Key 已在官方 TTS 通道内部管理；继续保留重复通道会让
    # 页面显示两个相同的 TTS 接入点，并把旧配置误当成 API 级降级。
    for channel_id in list(normalized_groups):
        if _api_management_channel_base_id(str(channel_id)) == "tts" and str(channel_id) != "tts":
            normalized_groups.pop(channel_id, None)
    raw_tts_channels = normalized_api_channels.get("tts")
    if isinstance(raw_tts_channels, (list, tuple)):
        normalized_api_channels["tts"] = [
            item for item in raw_tts_channels
            if isinstance(item, Mapping) and str(item.get("id") or "") == "tts"
        ]
    normalized_api_groups = dict(api_groups) if isinstance(api_groups, Mapping) else {}
    tts_group = normalized_api_groups.get("tts")
    if isinstance(tts_group, Mapping):
        migrated_tts_group = dict(tts_group)
        raw_order = migrated_tts_group.get("order")
        if isinstance(raw_order, (list, tuple)):
            migrated_tts_group["order"] = [
                str(channel_id) for channel_id in raw_order
                if str(channel_id).strip() == "tts"
            ]
        normalized_api_groups["tts"] = migrated_tts_group
    normalized_api_groups.pop("voice-clone-admin", None)
    normalized_api_functions = dict(api_functions) if isinstance(api_functions, Mapping) else {}
    normalized_api_functions.pop("voice-clone-admin", None)
    normalized_removed_channels = dict(removed_channels) if isinstance(removed_channels, Mapping) else {}
    normalized_removed_channels.pop("voice-clone-admin", None)
    normalized_guidance_expander: dict[str, object] | None = None
    if isinstance(raw_guidance_expander, Mapping):
        try:
            guidance_config = VisualGuidanceExpanderConfig.from_mapping(
                {"first_frame_guidance_expander": raw_guidance_expander}
            )
            normalized_guidance_expander = {
                "enabled": guidance_config.enabled,
                "provider": guidance_config.provider,
                "model": guidance_config.model,
                "model_version": guidance_config.model_version,
                "temperature": guidance_config.temperature,
                "max_tokens": guidance_config.max_tokens,
                "timeout": guidance_config.timeout,
                "mode": guidance_config.mode,
            }
        except (TypeError, ValueError):
            # 配置异常时保持安全默认关闭；首帧主链不会因为可选强化层崩溃。
            normalized_guidance_expander = None
    normalized_config = {
        "version": 1,
        "groups": normalized_groups,
        "api_groups": normalized_api_groups,
        "api_functions": normalized_api_functions,
        "api_channels": normalized_api_channels,
        "removed_channels": normalized_removed_channels,
    }
    if normalized_guidance_expander is not None:
        normalized_config["first_frame_guidance_expander"] = normalized_guidance_expander
    # 迁移不能只停留在内存快照：否则服务重启后仍会再次读取旧的
    # OpenAPI 地址和 TTS 降级项。保留未知顶层字段，仅回写已治理的配置段。
    persisted_config = dict(raw)
    persisted_config.update(normalized_config)
    if persisted_config != dict(raw):
        try:
            _api_management_write_config(persisted_config)
        except (OSError, TypeError, ValueError):
            # 配置读取仍应可用；落盘失败由服务日志/后续健康检查暴露，
            # 不能因为一次迁移写入失败而阻断 API 管理页面。
            pass
    return normalized_config


def _api_management_runtime_audit(groups: list[dict[str, object]]) -> dict[str, object]:
    """报告节点真实入口和页面配置的关系，不把它伪装成服务商鉴权成功。"""

    channel_by_id: dict[str, dict[str, object]] = {}
    declared_channel_by_node: dict[str, str] = {}
    for group in groups:
        for channel in group.get("channels", ()):
            if not isinstance(channel, Mapping):
                continue
            channel_id = str(channel.get("id") or "")
            if not channel_id:
                continue
            channel_by_id[channel_id] = dict(channel)
            # 自定义 API 配置组复用基础通道的节点描述，但不是新的执行器
            # 入口；不能让它覆盖节点的基础通道声明，否则会把已接入的
            # 运行时误报成 route_mismatch。
            if channel.get("is_custom_channel"):
                continue
            for node in channel.get("nodes", ()):
                if isinstance(node, Mapping):
                    node_id = str(node.get("id") or "")
                    if node_id:
                        declared_channel_by_node[node_id] = channel_id

    audits: list[dict[str, object]] = []
    for node_id, binding in API_MANAGEMENT_NODE_RUNTIME.items():
        effective_channel_id = str(binding.get("channel_id") or "")
        secondary_channel_ids = tuple(
            str(value).strip()
            for value in binding.get("secondary_channel_ids", ())
            if str(value).strip() and str(value).strip() != effective_channel_id
        )
        dependency_channel_ids = list(dict.fromkeys(
            [value for value in (effective_channel_id, *secondary_channel_ids) if value]
        ))
        declared_channel_id = declared_channel_by_node.get(node_id, "")
        runtime_kind = str(binding.get("runtime_kind") or "external")
        channel = channel_by_id.get(effective_channel_id)
        if runtime_kind == "local":
            status = "local"
            status_label = "本地处理"
            auth_source = "无需外部鉴权"
        elif not effective_channel_id or channel is None:
            status = "unwired"
            status_label = "未接入"
            auth_source = "未找到 API 配置组"
        elif effective_channel_id == "voice-clone-admin":
            # 新版声音复刻通道没有独立密钥。训练、get_voice 查询依赖
            # TTS 主 API Key；试听只读取训练返回的 demo_audio，不发起 TTS。
            # 这里直接审计 TTS 通道，避免因管理卡 secret_fields 为空而错误
            # 报成“环境变量回退”。副 Key 永远不计入训练/查询节点。
            tts_channel = channel_by_id.get("tts") or {}
            tts_secret_status = tts_channel.get("secret_status")
            tts_has_primary = bool(
                isinstance(tts_secret_status, Mapping)
                and tts_secret_status.get("primary_api_key")
            )
            tts_runtime = tts_channel.get("credential_runtime")
            tts_runtime_source = (
                str(tts_runtime.get("source") or "")
                if isinstance(tts_runtime, Mapping)
                else str(tts_channel.get("source") or "")
            )
            tts_page_secret = tts_has_primary and "页面本机加密凭据" in tts_runtime_source
            tts_env_secret = tts_has_primary and not tts_page_secret
            if not tts_has_primary:
                status = "blocked"
                status_label = "缺少 TTS 主 API Key"
                auth_source = "TTS 主 API Key 缺失"
            elif tts_page_secret:
                status = "wired"
                status_label = "已绑定运行时"
                auth_source = "页面本机加密凭据（复用 TTS 主 API Key）"
            elif tts_env_secret:
                status = "env_fallback"
                status_label = "环境变量回退"
                auth_source = "环境变量（复用 TTS 主 API Key）"
            else:
                status = "blocked"
                status_label = "TTS 凭据不可读取"
                auth_source = "TTS 凭据不可读取"
        else:
            channel_status = str(channel.get("status") or "missing")
            secret_status = channel.get("secret_status")
            has_page_secret = isinstance(secret_status, Mapping) and any(bool(value) for value in secret_status.values())
            source = str(channel.get("source") or "")
            if channel_status == "missing":
                status = "blocked"
                status_label = "鉴权缺失"
            elif channel_status == "partial":
                status = "partial"
                status_label = "部分配置"
            elif has_page_secret:
                status = "wired"
                status_label = "已绑定运行时"
            elif "鉴权文档" in source:
                status = "document_fallback"
                status_label = "鉴权文档回退"
            else:
                status = "env_fallback"
                status_label = "环境变量回退"
            auth_source = (
                "页面本机加密凭据"
                if has_page_secret
                else ("鉴权文档" if "鉴权文档" in source else "环境变量")
            )
        route_mismatch = bool(
            runtime_kind != "local"
            and declared_channel_id
            and effective_channel_id
            and declared_channel_id != effective_channel_id
        )
        if route_mismatch:
            status = "route_mismatch"
            status_label = "页面映射与执行器不一致"
        business_plan_status = (
            "不适用"
            if runtime_kind == "local"
            else ("已由统一执行器读取" if node_id == "writing.subtitle-correction" else "尚未由统一执行器读取")
        )
        audits.append({
            "node_id": node_id,
            "entrypoint": str(binding.get("entrypoint") or ""),
            "declared_channel_id": declared_channel_id,
            "effective_channel_id": effective_channel_id,
            "dependency_channel_ids": dependency_channel_ids,
            "status": status,
            "status_label": status_label,
            "auth_source": auth_source,
            "auth_mode": str(binding.get("auth_mode") or "未声明"),
            "auth_verified": False,
            "auth_verification_status": "不适用" if runtime_kind == "local" else "未执行供应商调用验证",
            "business_plan_status": business_plan_status,
            "note": str(binding.get("note") or ""),
        })
    counts = {
        "total": len(audits),
        "wired": sum(item["status"] == "wired" for item in audits),
        "document_fallback": sum(item["status"] == "document_fallback" for item in audits),
        "env_fallback": sum(item["status"] == "env_fallback" for item in audits),
        "partial": sum(item["status"] == "partial" for item in audits),
        "blocked": sum(item["status"] in {"blocked", "unwired", "route_mismatch"} for item in audits),
        "local": sum(item["status"] == "local" for item in audits),
        "auth_unverified": sum(not bool(item["auth_verified"]) for item in audits if item["status"] not in {"local", "unwired"}),
        "business_plan_unapplied": sum(item["business_plan_status"] == "尚未由统一执行器读取" for item in audits),
    }
    return {**counts, "nodes": audits}


def _api_management_write_config(config: Mapping[str, object]) -> None:
    API_MANAGEMENT_CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)
    temporary = API_MANAGEMENT_CONFIG_PATH.with_suffix(".tmp")
    temporary.write_text(
        json.dumps(dict(config), ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    temporary.replace(API_MANAGEMENT_CONFIG_PATH)


def _api_management_apply_runtime_config(config: Mapping[str, object] | None = None) -> None:
    # 所有生产 transport 都必须指向同一份项目持久配置；否则页面写入
    # .runtime-governance-live 后，字幕模块仍可能按自身默认值读取 AppData 旧文件。
    os.environ["API_MANAGEMENT_CONFIG_PATH"] = str(API_MANAGEMENT_CONFIG_PATH)
    # 清除历史声音复刻的 AppID/AccessToken/AK/SK 和上传 API Key，
    # 防止旧版鉴权静默进入新版 TTS 运行时。
    for legacy_name in (
        "VOICE_CLONE_ADMIN_ACCESS_KEY",
        "VOICE_CLONE_ADMIN_SECRET_KEY",
        "VOICE_CLONE_ADMIN_APP_ID",
        "VOICE_CLONE_ADMIN_ACCESS_TOKEN",
        "VOICE_CLONE_UPLOAD_API_KEY",
    ):
        os.environ.pop(legacy_name, None)
    for env_name in API_MANAGEMENT_MODEL_FALLBACK_RUNTIME.values():
        os.environ.pop(str(env_name), None)
    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        # 清掉服务继承来的旧 Key，防止页面没有填写备用 Key 时仍被旧环境变量
        # 当成“已配置”。明确把文档入口置空，transport 会保留页面主 Key，
        # 但不会再偷偷取《鉴权信息 .md》里的旧备用 Key。
        for channel_id in API_MANAGEMENT_PAGE_MANAGED_CHANNELS:
            aliases = API_MANAGEMENT_SECRET_RUNTIME.get(channel_id, {})
            for env_names in aliases.values():
                for env_name in env_names:
                    os.environ.pop(str(env_name), None)
        os.environ["STORY_WRITER_AUTH_DOCUMENT"] = ""
        os.environ["DIRECTOR_AUTH_DOCUMENT"] = ""
        os.environ["ARK_TTS_AUTH_DOCUMENT"] = ""
    else:
        os.environ.setdefault("STORY_WRITER_AUTH_DOCUMENT", str(DEFAULT_AUTH_DOCUMENT))
        os.environ.setdefault("DIRECTOR_AUTH_DOCUMENT", str(DEFAULT_AUTH_DOCUMENT))
        os.environ.setdefault("ARK_TTS_AUTH_DOCUMENT", str(DEFAULT_AUTH_DOCUMENT))
    _api_management_apply_secret_runtime()
    config = config or _api_management_load_config()
    # 首帧用户注意力引导强化器复用 API 管理中已加密注入的文本通道；这里
    # 只导出非敏感的开关、模型与超时，绝不复制或落盘任何 API Key。
    for env_name in (
        "FIRST_FRAME_GUIDANCE_EXPANDER_ENABLED",
        "FIRST_FRAME_GUIDANCE_EXPANDER_PROVIDER",
        "FIRST_FRAME_GUIDANCE_EXPANDER_MODEL",
        "FIRST_FRAME_GUIDANCE_EXPANDER_MODEL_VERSION",
        "FIRST_FRAME_GUIDANCE_EXPANDER_TEMPERATURE",
        "FIRST_FRAME_GUIDANCE_EXPANDER_MAX_TOKENS",
        "FIRST_FRAME_GUIDANCE_EXPANDER_TIMEOUT",
        "FIRST_FRAME_GUIDANCE_EXPANDER_MODE",
    ):
        os.environ.pop(env_name, None)
    raw_guidance_expander = (
        config.get("first_frame_guidance_expander")
        if isinstance(config, Mapping)
        else None
    )
    if isinstance(raw_guidance_expander, Mapping):
        env_values = {
            "FIRST_FRAME_GUIDANCE_EXPANDER_ENABLED": raw_guidance_expander.get("enabled"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_PROVIDER": raw_guidance_expander.get("provider"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_MODEL": raw_guidance_expander.get("model"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_MODEL_VERSION": raw_guidance_expander.get("model_version"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_TEMPERATURE": raw_guidance_expander.get("temperature"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_MAX_TOKENS": raw_guidance_expander.get("max_tokens"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_TIMEOUT": raw_guidance_expander.get("timeout"),
            "FIRST_FRAME_GUIDANCE_EXPANDER_MODE": raw_guidance_expander.get("mode"),
        }
        for env_name, value in env_values.items():
            if value not in (None, ""):
                os.environ[env_name] = str(value)
    # Export the configured language-model API1/API2 order for transports that
    # execute outside this module (for example the 8790 account-knowledge
    # worker).  This is metadata only; credentials remain in process memory.
    os.environ.pop("API_MANAGEMENT_LANGUAGE_MODEL_ORDER", None)
    raw_api_groups = config.get("api_groups") if isinstance(config, Mapping) else {}
    language_model_group = (
        raw_api_groups.get("language-model")
        if isinstance(raw_api_groups, Mapping)
        else None
    )
    raw_language_order = (
        language_model_group.get("order")
        if isinstance(language_model_group, Mapping)
        else None
    )
    if isinstance(raw_language_order, (list, tuple)):
        language_order = list(dict.fromkeys(
            str(value).strip()
            for value in raw_language_order
            if str(value).strip()
        ))
        if language_order:
            os.environ["API_MANAGEMENT_LANGUAGE_MODEL_ORDER"] = json.dumps(
                language_order, ensure_ascii=False
            )
    groups = config.get("groups") if isinstance(config, Mapping) else {}
    if not isinstance(groups, Mapping):
        return
    for group_id, raw_settings in groups.items():
        normalized_group_id = str(group_id)
        aliases = API_MANAGEMENT_GROUP_RUNTIME.get(normalized_group_id)
        if not aliases or not isinstance(raw_settings, Mapping):
            continue
        fixed_protocol = normalized_group_id in API_MANAGEMENT_FIXED_PROTOCOL_CHANNELS
        if fixed_protocol:
            # 新版 V3 TTS 的请求地址由 transport 固定，历史 endpoint 环境值
            # 即使存在也必须从当前服务进程移除。
            for env_name in aliases.get("endpoint", ()):
                os.environ.pop(str(env_name), None)
            for env_name in aliases.get("primary_model", ()):
                os.environ.pop(str(env_name), None)
            for env_name in aliases.get("backup_model", ()):
                os.environ.pop(str(env_name), None)
        for field, env_names in aliases.items():
            if fixed_protocol and field in {"endpoint", "primary_model", "backup_model"}:
                continue
            value = raw_settings.get(field)
            if value in (None, ""):
                continue
            for env_name in env_names:
                os.environ[str(env_name)] = str(value)
        model_slots = raw_settings.get("model_slots")
        if isinstance(model_slots, Mapping) and not fixed_protocol:
            for source, value in model_slots.items():
                source_name = str(source).strip()
                if source_name not in _api_management_model_env_names(normalized_group_id):
                    continue
                model_value = str(value or "").strip()
                if model_value:
                    os.environ[source_name] = model_value
                else:
                    os.environ.pop(source_name, None)
        fallback_env = API_MANAGEMENT_MODEL_FALLBACK_RUNTIME.get(normalized_group_id)
        if fallback_env and isinstance(model_slots, Mapping):
            raw_order = raw_settings.get("model_order")
            ordered_sources = (
                [str(value).strip() for value in raw_order if str(value).strip()]
                if isinstance(raw_order, (list, tuple))
                else [str(source).strip() for source in model_slots]
            )
            ordered_models = list(dict.fromkeys(
                str(model_slots.get(source) or "").strip()
                for source in ordered_sources
                if str(model_slots.get(source) or "").strip()
            ))
            if ordered_models:
                os.environ[str(fallback_env)] = json.dumps(ordered_models, ensure_ascii=False)
    image2_targets = _api_management_image2_runtime_targets(config)
    if image2_targets:
        os.environ[API_MANAGEMENT_IMAGE2_RUNTIME_ENV] = json.dumps(image2_targets, ensure_ascii=False, separators=(",", ":"))
    else:
        os.environ.pop(API_MANAGEMENT_IMAGE2_RUNTIME_ENV, None)
    # TikHub transport 在模块加载时会读取一次环境变量。页面保存后必须
    # 立即重建同一实例，否则新 Token 只存在环境变量，选题情报仍会使用旧配置。
    if "TIKHUB_TRANSPORT" in globals():
        refreshed_tikhub = TikHubTransport.from_env()
        globals()["TIKHUB_TRANSPORT"] = refreshed_tikhub
        intelligence = globals().get("TOPIC_INTELLIGENCE")
        if intelligence is not None:
            intelligence.tikhub = refreshed_tikhub


def _runtime_auth_document() -> Path:
    """返回当前运行时可传给 transport 的鉴权文件路径。"""

    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        # 页面凭据模式绝不能触碰用户 Documents 中的历史文档。该路径刻意
        # 不创建，transport 只能使用 API 管理页已经注入的运行时凭据。
        return TASK_RUNTIME_DIR / "page-credentials-only.md"
    configured = os.environ.get("DIRECTOR_AUTH_DOCUMENT", "").strip()
    return Path(configured).expanduser() if configured else Path(DEFAULT_AUTH_DOCUMENT).expanduser()


def _require_runtime_auth_document(
    missing_message: str, *, channel_ids: Sequence[str] = ()
) -> Path:
    auth_document = _runtime_auth_document()
    if auth_document.is_file():
        return auth_document
    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        _api_management_require_runtime_credentials(channel_ids)
        return auth_document
    raise RuntimeError(missing_message)


def _asset_production_auth_channels() -> tuple[str, ...]:
    """返回完整素材任务实际会使用的鉴权频道。"""

    return (
        "image-generation",
        "video-generation",
        "digital-human",
        "bgm-audio",
        "audio-storage",
    )


def _director_runtime_auth_document() -> Path:
    """兼容既有调用名；页面模式下返回不可用的文档哨兵路径。"""

    return _runtime_auth_document()


def _director_runtime_has_page_credentials() -> bool:
    """确认页面托管的 Seed 2.1 凭据和主模型均已注入当前运行时。"""

    secret_aliases = API_MANAGEMENT_SECRET_RUNTIME.get("director-seed21", {})
    runtime_aliases = API_MANAGEMENT_GROUP_RUNTIME.get("director-seed21", {})
    has_primary_key = any(
        os.environ.get(str(name), "").strip()
        for name in secret_aliases.get("primary_api_key", ())
    )
    has_primary_model = any(
        os.environ.get(str(name), "").strip()
        for name in runtime_aliases.get("primary_model", ())
    )
    return has_primary_key and has_primary_model


def _require_director_runtime_auth_document(missing_message: str) -> Path:
    """旧文档和 API 管理页面凭据二选一，禁止页面模式回退到旧文档。"""

    auth_document = _require_runtime_auth_document(
        missing_message, channel_ids=("director-seed21",)
    )
    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        if _director_runtime_has_page_credentials():
            return auth_document
        raise RuntimeError(
            "API 管理未配置可用的编导 Seed 2.1 主 API Key 或主模型，无法启动真实编导任务"
        )
    return auth_document


def _api_management_provider_snapshot(spec: Mapping[str, object]) -> dict[str, object]:
    credential_envs = tuple(str(item) for item in spec.get("credential_envs", ()) if str(item).strip())
    credential_secret_envs = tuple(str(item) for item in spec.get("credential_secret_envs", ()) if str(item).strip())
    backup_envs = tuple(str(item) for item in spec.get("backup_envs", ()) if str(item).strip())
    backup_secret_envs = tuple(str(item) for item in spec.get("backup_secret_envs", ()) if str(item).strip())
    url_envs = tuple(str(item) for item in spec.get("url_envs", ()) if str(item).strip())
    model_envs = tuple(str(item) for item in spec.get("model_envs", ()) if str(item).strip())
    credential_name, _credential_value = _api_management_first_env(credential_envs)
    credential_secret_name, _credential_secret_value = _api_management_first_env(credential_secret_envs)
    backup_name, _backup_value = _api_management_first_env(backup_envs)
    backup_secret_name, _backup_secret_value = _api_management_first_env(backup_secret_envs)
    url_name, url_value = _api_management_first_env(url_envs)
    model_source_name, model_value = _api_management_first_env(model_envs)
    document_configured, document_path = _api_management_document_state(spec)
    local_only = bool(spec.get("local_only"))
    primary_has_any = bool(
        any(os.environ.get(name, "").strip() for name in credential_envs)
        or any(os.environ.get(name, "").strip() for name in credential_secret_envs)
    )
    backup_has_any = bool(
        any(os.environ.get(name, "").strip() for name in backup_envs)
        or any(os.environ.get(name, "").strip() for name in backup_secret_envs)
    )
    primary_ready = bool(credential_name and (credential_secret_name if credential_secret_envs else True))
    backup_ready = bool(backup_name and (backup_secret_name if backup_secret_envs else True))
    has_partial_credential = bool(
        (primary_has_any and not primary_ready)
        or (backup_has_any and not backup_ready)
    )
    if local_only:
        status = "ready" if url_value else "missing"
        status_label = "已配置" if url_value else "未配置"
    elif primary_ready:
        status = "ready"
        status_label = "已配置"
    elif document_configured:
        status = "document"
        status_label = "鉴权文档"
    elif has_partial_credential or backup_ready:
        status = "partial"
        status_label = "部分配置"
    else:
        status = "missing"
        status_label = "未配置"
    source_parts: list[str] = []
    if primary_ready:
        source_parts.append(
            f"环境变量：{credential_name} + {credential_secret_name}"
            if credential_secret_envs
            else f"环境变量：{credential_name}"
        )
    elif primary_has_any and credential_secret_envs:
        source_parts.append("环境变量：AK/SK 不完整")
    if backup_ready:
        source_parts.append(
            f"备用：{backup_name} + {backup_secret_name}"
            if backup_secret_envs
            else f"备用：{backup_name}"
        )
    elif backup_has_any and backup_secret_envs:
        source_parts.append("备用：AK/SK 不完整")
    if document_configured:
        source_parts.append(f"鉴权文档：{Path(document_path).name}")
    if local_only and url_name:
        source_parts.append(f"本机地址：{url_name}")
    if not source_parts:
        source_parts.append("未发现有效配置")
    endpoint = _api_management_safe_url(url_value or str(spec.get("default_url") or ""))
    model = model_value or str(spec.get("default_model") or spec.get("default_service") or "")
    slot_meta = API_MANAGEMENT_MODEL_SLOT_META.get(str(spec.get("id") or ""), {})
    slot_title = str(slot_meta.get("title") or "模型")
    slot_count_label = str(slot_meta.get("count_label") or "模型")
    model_options = [
        {
            "source": env_name,
            "model_id": os.environ.get(env_name, "").strip() or str(API_MANAGEMENT_MODEL_DEFAULTS.get(env_name) or ""),
            "model_name": "",
            "display_name": "",
            "usage_label": _api_management_model_usage_label(env_name),
            "value": os.environ.get(env_name, "").strip() or str(API_MANAGEMENT_MODEL_DEFAULTS.get(env_name) or ""),
            "configured": bool(os.environ.get(env_name, "").strip()),
            "slot_title": slot_title,
            "slot_count_label": slot_count_label,
        }
        for env_name in model_envs
    ]
    return {
        "id": str(spec.get("id") or ""),
        "name": str(spec.get("name") or ""),
        "kind": str(spec.get("kind") or ""),
        "status": status,
        "status_label": status_label,
        "source": "；".join(source_parts),
        "endpoint": endpoint,
        "endpoint_source": url_name or ("默认值" if endpoint else ""),
        "model": model,
        "model_source": model_source_name or ("默认值" if model else ""),
        "credential_envs": list(credential_envs),
        "credential_secret_envs": list(credential_secret_envs),
        "backup_envs": list(backup_envs),
        "backup_secret_envs": list(backup_secret_envs),
        "url_envs": list(url_envs),
        "model_envs": list(model_envs),
        "model_options": model_options,
        "model_slot_title": slot_title,
        "model_slot_count_label": slot_count_label,
        "note": str(spec.get("note") or ""),
        "local_only": local_only,
        "default_region": str(spec.get("default_region") or ""),
        "default_service": str(spec.get("default_service") or ""),
        "default_version": str(spec.get("default_version") or ""),
        "read_only_first": bool(spec.get("read_only_first")),
    }


def _api_management_channel_snapshot(
    channel: Mapping[str, object],
    providers: Mapping[str, Mapping[str, object]],
    saved_settings: Mapping[str, object],
) -> dict[str, object]:
    provider_ids = [str(item) for item in channel.get("provider_ids", ())]
    linked = [providers[item] for item in provider_ids if item in providers]
    states = [str(item.get("status") or "missing") for item in linked]
    if linked and all(state in {"ready", "document"} for state in states):
        status = "ready"
        status_label = "已配置"
    elif any(state in {"ready", "document", "partial"} for state in states):
        status = "partial"
        status_label = "部分配置"
    else:
        status = "missing"
        status_label = "待配置"
    channel_id = str(channel.get("id") or "")
    is_custom_channel = bool(channel.get("is_custom_channel"))
    base_channel_id = _api_management_channel_base_id(channel_id)
    aliases = API_MANAGEMENT_GROUP_RUNTIME.get(base_channel_id, {})
    secret_aliases = API_MANAGEMENT_SECRET_RUNTIME.get(base_channel_id, {})
    stored_secrets = _api_management_load_secrets().get(channel_id, {})
    secret_health = _api_management_secret_health_snapshot()
    secret_unreadable = str(secret_health.get("state") or "") == "unreadable"
    if secret_unreadable and secret_aliases and not is_custom_channel:
        status = "blocked"
        status_label = "凭据不可读取"
    extra_spec = API_MANAGEMENT_EXTRA_SECRET_RUNTIME.get(base_channel_id)
    stored_extra_keys = _api_management_normalize_extra_keys(stored_secrets.get("extra_api_keys"))
    runtime_extra_keys = _api_management_extra_keys_from_env(str(extra_spec["env"])) if extra_spec else []
    extra_key_count = len(list(dict.fromkeys(stored_extra_keys + runtime_extra_keys)))
    saved = dict(saved_settings)
    raw_saved_model_names = saved.get("model_names")
    saved_model_names = (
        {str(key).strip(): str(value or "").strip() for key, value in raw_saved_model_names.items()}
        if isinstance(raw_saved_model_names, Mapping)
        else {}
    )
    raw_saved_model_slots = saved.get("model_slots")
    saved_model_slots_present = isinstance(raw_saved_model_slots, Mapping)
    saved_model_slots = (
        {str(key).strip(): str(value or "").strip() for key, value in raw_saved_model_slots.items()}
        if saved_model_slots_present
        else {}
    )
    raw_saved_model_order = saved.get("model_order")
    saved_model_order_present = isinstance(raw_saved_model_order, (list, tuple))
    saved_model_order = (
        [str(value).strip() for value in raw_saved_model_order if str(value).strip()]
        if isinstance(raw_saved_model_order, (list, tuple))
        else []
    )
    endpoint_env, endpoint_value = _api_management_first_env(tuple(aliases.get("endpoint", ())))
    region_env, region_value = _api_management_first_env(tuple(aliases.get("region", ())))
    primary_model_env, primary_model_value = _api_management_first_env(tuple(aliases.get("primary_model", ())))
    backup_model_env, backup_model_value = _api_management_first_env(tuple(aliases.get("backup_model", ())))
    linked_endpoint = next((str(item.get("endpoint") or "") for item in linked if item.get("endpoint")), "")
    linked_model = next((str(item.get("model") or "") for item in linked if item.get("model")), "")
    strategy_env, strategy_value = _api_management_first_env(tuple(aliases.get("strategy", ())))
    attempts_env, attempts_value = _api_management_first_env(tuple(aliases.get("max_attempts", ())))
    timeout_env, timeout_value = _api_management_first_env(tuple(aliases.get("timeout_seconds", ())))
    try:
        max_attempts = max(1, min(5, int(saved.get("max_attempts") or attempts_value or 2)))
    except (TypeError, ValueError):
        max_attempts = 2
    try:
        timeout_default = int(channel.get("default_timeout_seconds") or 120)
    except (TypeError, ValueError):
        timeout_default = 120
    try:
        timeout_seconds = max(5, min(900, int(saved.get("timeout_seconds") or timeout_value or timeout_default)))
    except (TypeError, ValueError):
        timeout_seconds = 120
    quality = str(saved.get("quality") or ("low" if base_channel_id == "image-generation" else "")).strip().lower()
    if base_channel_id == "image-generation" and quality not in {"low", "medium", "high", "auto"}:
        quality = "low"
    allowed_strategies = tuple(str(item) for item in channel.get("strategy_options", ()))
    strategy = str(saved.get("strategy") or strategy_value or channel.get("default_strategy") or "").strip()
    if allowed_strategies:
        if strategy not in allowed_strategies:
            strategy = str(channel.get("default_strategy") or allowed_strategies[0])
    else:
        strategy = ""
    endpoint = str(saved.get("endpoint") or ("" if is_custom_channel else (endpoint_value or linked_endpoint)) or "")
    endpoint_source = "本地配置" if saved.get("endpoint") else (endpoint_env or ("默认值" if endpoint else ""))
    if base_channel_id == "voice-clone-admin" and not is_custom_channel:
        # 新版声音复刻只允许固定 v3 数据面；即使磁盘中仍有历史 endpoint，
        # 运行时也不能把它展示或传给 transport。
        endpoint = DEFAULT_VOICE_CLONE_URL
        endpoint_source = "固定新版 v3 协议"
    if base_channel_id == "tts":
        # 所有 TTS 配置组（包括历史自定义 API2）共用同一个新版 V3
        # endpoint；模型/资源由 transport 和音色目录决定，页面不得编辑。
        endpoint = DEFAULT_ARK_TTS_URL
        endpoint_source = "固定新版 v3 协议"
    default_region = str(channel.get("default_region") or next((str(item.get("default_region") or "") for item in linked if item.get("default_region")), ""))
    region = str(saved.get("region") or ("" if is_custom_channel else (region_value or default_region)) or "")
    primary_model = str(saved.get("primary_model") or ("" if is_custom_channel else (primary_model_value or linked_model)) or "")
    backup_model = str(saved.get("backup_model") or ("" if is_custom_channel else backup_model_value) or next((str(item.get("default_version") or "") for item in linked if item.get("default_version")), ""))
    primary_model_source = "本地配置" if saved.get("primary_model") else (primary_model_env or ("默认值" if primary_model else ""))
    backup_model_source = "本地配置" if saved.get("backup_model") else backup_model_env
    if base_channel_id == "tts":
        primary_model = DEFAULT_TTS_MODEL
        primary_model_source = "固定新版 v3 协议"
        backup_model = ""
        backup_model_source = ""
    model_slots: list[dict[str, object]] = []
    seen_model_sources: set[str] = set()
    model_slot_indexes: dict[str, int] = {}
    model_slot_titles: list[str] = []
    model_slot_count_labels: list[str] = []
    # 每个环境变量对应一个真实的模型/接入点来源。相同 ID 的业务角色
    # 会合并为一个接入点并保留 sources；不同 ID 必须全部保留并可排序。
    consolidate_builtin_models = base_channel_id in API_MANAGEMENT_CONSOLIDATED_MODEL_CHANNELS
    for provider in (() if is_custom_channel else linked):
        for option in provider.get("model_options", ()):
            if not isinstance(option, Mapping):
                continue
            source = str(option.get("source") or "").strip()
            model_id = str(option.get("model_id") or option.get("value") or "").strip()
            # 一旦页面保存了 model_slots，它就是当前 API 的显式接入点清单。
            # 被用户删除的空内置槽位不能在下一次刷新时被 provider 默认项重新补回。
            if saved_model_order_present and not _api_management_is_custom_model_source(source) and source not in saved_model_order:
                continue
            model_name = str(
                saved_model_names.get(source)
                or option.get("model_name")
                or option.get("display_name")
                or ""
            ).strip()
            usage_label = str(
                option.get("usage_label")
                or option.get("label")
                or _api_management_model_usage_label(source)
            ).strip()
            slot_title = str(option.get("slot_title") or "模型")
            slot_count_label = str(option.get("slot_count_label") or "模型")
            if not source or source in seen_model_sources:
                continue
            seen_model_sources.add(source)
            model_slot_titles.append(slot_title)
            model_slot_count_labels.append(slot_count_label)
            custom_model = _api_management_is_custom_model_source(source)
            # 内置槽位按真实接入点 ID 去重：多个业务角色共用同一个 ID 时
            # 只显示一个接入点并保留 sources；不同 ID 必须逐项展示并可排序。
            model_key = (
                f"custom:{source}"
                if custom_model
                else (model_id if model_id else f"__unset__:{source}")
            )
            existing_index = model_slot_indexes.get(model_key)
            if existing_index is not None:
                existing = model_slots[existing_index]
                sources = list(existing.get("sources") or [existing.get("source") or ""])
                if source not in sources:
                    sources.append(source)
                usage_labels = list(existing.get("usage_labels") or [existing.get("usage_label") or ""])
                if usage_label and usage_label not in usage_labels:
                    usage_labels.append(usage_label)
                existing["sources"] = sources
                existing["usage_labels"] = [item for item in usage_labels if item]
                existing["usage_label"] = "、".join(existing["usage_labels"])
                if consolidate_builtin_models and not custom_model:
                    # 只展示第一个预置模型名称；其余名称是历史角色别名，
                    # 不再把它们拼成一个看似包含多个模型的标题。
                    existing_model_id = str(existing.get("model_id") or existing.get("value") or "").strip()
                    if not existing_model_id and model_id:
                        existing["model_id"] = model_id
                        existing["value"] = model_id
                        existing["label"] = model_name or model_id
                    existing_name = str(existing.get("model_name") or "").strip()
                    if not existing_name and model_name:
                        existing["model_name"] = model_name
                        existing["label"] = model_name
                        existing["display_name"] = model_name
                    existing["model_names"] = [str(existing.get("model_name") or "").strip()]
                    existing["model_names"] = [item for item in existing["model_names"] if item]
                else:
                    model_names = list(existing.get("model_names") or [])
                    if model_name and model_name not in model_names:
                        model_names.append(model_name)
                    existing["model_names"] = model_names
                    existing["model_name"] = " / ".join(model_names)
                    existing["display_name"] = existing["model_name"]
                existing["display_name"] = existing["model_name"]
                existing["configured"] = bool(existing.get("configured") or option.get("configured"))
                continue
            model_slot_indexes[model_key] = len(model_slots)
            model_slots.append({
                "source": source,
                "sources": [source],
                "label": model_name or model_id or "未设置",
                "model_id": model_id,
                "model_name": model_name,
                "display_name": model_name,
                "model_names": [model_name] if model_name else [],
                "usage_label": usage_label,
                "usage_labels": [usage_label] if usage_label else [],
                "value": model_id,
                "configured": bool(option.get("configured")),
                "editable": True,
                "slot_title": slot_title,
                "slot_count_label": slot_count_label,
            })
    if not model_slots and not is_custom_channel:
        fallback_sources = [
            str(env_name)
            for provider in linked
            for env_name in provider.get("model_envs", ())
            if str(env_name).strip()
        ]
        for index, (value, label) in enumerate(((primary_model, "当前模型"), (backup_model, "当前备用模型"))):
            if value and index < len(fallback_sources):
                source = fallback_sources[index]
                model_name = saved_model_names.get(source, "")
                model_slots.append({
                    "source": source,
                    "sources": [source],
                    "label": model_name or value,
                    "model_id": value,
                    "model_name": model_name,
                    "display_name": model_name,
                    "model_names": [model_name] if model_name else [],
                    "usage_label": _api_management_model_usage_label(source) or label,
                    "usage_labels": [_api_management_model_usage_label(source) or label],
                    "value": value,
                    "editable": True,
                })
                model_slot_titles.append("模型")
                model_slot_count_labels.append("模型")
    for source, model_id in saved_model_slots.items():
        if not _api_management_is_custom_model_source(source):
            continue
        model_name = saved_model_names.get(source, "")
        if not model_id and not model_name:
            continue
        model_slots.append({
            "source": source,
            "sources": [source],
            "label": model_name or model_id or "未命名模型",
            "model_id": model_id,
            "model_name": model_name,
            "display_name": model_name,
            "model_names": [model_name] if model_name else [],
            "usage_label": "自定义模型",
            "usage_labels": ["自定义模型"],
            "value": model_id,
            "configured": bool(model_id),
            "editable": True,
            "slot_title": "模型",
            "slot_count_label": "模型",
        })
        model_slot_titles.append("模型")
        model_slot_count_labels.append("模型")
    if saved_model_order:
        slots_by_source: dict[str, dict[str, object]] = {}
        for slot in model_slots:
            slot_source = str(slot.get("source") or "").strip()
            sources = slot.get("sources")
            sources = sources if isinstance(sources, (list, tuple)) else [slot_source]
            for source in sources:
                source_name = str(source or "").strip()
                if source_name:
                    slots_by_source.setdefault(source_name, slot)
        ordered_slots: list[dict[str, object]] = []
        seen_slots: set[int] = set()
        for source in saved_model_order:
            slot = slots_by_source.get(source)
            if slot is None or id(slot) in seen_slots:
                continue
            ordered_slots.append(slot)
            seen_slots.add(id(slot))
        for slot in model_slots:
            if id(slot) not in seen_slots:
                ordered_slots.append(slot)
                seen_slots.add(id(slot))
        model_slots = ordered_slots
    fixed_protocol_defaults: dict[str, str] = {}
    fixed_endpoints: list[dict[str, str]] = []
    if base_channel_id == "tts":
        # Seed TTS 2.0 的 model 与 resource ID 是当前 transport 的固定协议
        # 参数；用户配置 TTS 时只应填写 API Key，不能误导为还要选模型。
        fixed_protocol_defaults = {
            "model": DEFAULT_TTS_MODEL,
            "resource_id": DEFAULT_TTS_RESOURCE_ID,
        }
        model_slots = []
        model_slot_titles = ["固定协议参数"]
        model_slot_count_labels = ["固定项"]
    elif base_channel_id == "voice-clone-admin":
        # 声音复刻和普通 TTS 共用主 Key，但有两条独立、不可编辑的 V3
        # 接入点。显式下发给配置页，避免只展示训练地址而误导为 TTS endpoint。
        fixed_endpoints = [
            {
                "id": "voice_clone",
                "label": "创建 / 训练音色",
                "url": DEFAULT_VOICE_CLONE_URL,
                "mode": "上传声音文件（外部写入）",
            },
            {
                "id": "get_voice",
                "label": "查询训练状态",
                "url": DEFAULT_VOICE_QUERY_URL,
                "mode": "只读查询",
            },
        ]
    if is_custom_channel:
        visible_secret_fields = [field for field in secret_aliases if str(field).startswith("primary_")]
        has_secret = any(bool(stored_secrets.get(field)) for field in visible_secret_fields)
        if base_channel_id in API_MANAGEMENT_FIXED_PROTOCOL_CHANNELS:
            # 固定协议通道没有模型/资源输入框；只要该 API 配置组有主
            # API Key 即可视为可用，endpoint 由新版 transport 提供。
            has_any_config = bool(has_secret)
            configured = bool(has_secret)
        else:
            has_model = any(str(item.get("model_id") or item.get("value") or "").strip() for item in model_slots)
            has_any_config = bool(endpoint or has_model or has_secret)
            configured = bool(endpoint and has_model and (has_secret or not visible_secret_fields))
        status = "ready" if configured else ("partial" if has_any_config else "missing")
        status_label = {"ready": "已配置", "partial": "部分配置", "missing": "待配置"}[status]
    model_slot_titles = list(dict.fromkeys(item for item in model_slot_titles if item))
    model_slot_count_labels = list(dict.fromkeys(item for item in model_slot_count_labels if item))
    model_slot_title = " / ".join(model_slot_titles) if model_slot_titles else "模型"
    model_slot_count_label = model_slot_count_labels[0] if len(model_slot_count_labels) == 1 else "配置项"
    sources = list(dict.fromkeys(str(item.get("source") or "") for item in linked if item.get("source")))
    effective_source = (
        "页面本机加密凭据"
        if secret_aliases and stored_secrets and not secret_unreadable
        else ("凭据文件不可读取，已阻止回退" if secret_unreadable and secret_aliases else ("未配置新的 API 凭据" if is_custom_channel else "；".join(sources)))
    )
    # 声音复刻和 Seed-Audio 都可复用页面保存的 TTS 主 X-Api-Key。
    # 页面状态必须反映实际 transport 的凭据选择，避免音效可用却误报
    # “凭证丢失”；这里只读取是否存在，绝不把密钥放入快照。
    voice_clone_tts_key_from_page = False
    sound_effect_tts_key_from_page = False
    credential_envs = list(dict.fromkeys(
        name for item in linked for name in (item.get("credential_envs") or [])
    ))
    backup_envs = list(dict.fromkeys(
        name for item in linked for name in (item.get("backup_envs") or [])
    ))
    resource_kind = str(channel.get("resource_kind") or "model")
    visible_secret_aliases = {
        field: envs
        for field, envs in secret_aliases.items()
        if str(field).startswith("primary_")
        or (
            str(field) in (
                "backup_api_key",
                "backup_access_key",
                "backup_secret_key",
            )
            and str(channel.get("id") or "") in API_MANAGEMENT_INTERNAL_BACKUP_CHANNELS
            and not is_custom_channel
        )
        or (resource_kind == "object_storage" and str(field).startswith("backup_"))
    }
    secret_status = {
        field: (
            False
            if secret_unreadable
            else bool(stored_secrets.get(field) or (not is_custom_channel and _api_management_first_secret_env(tuple(envs))[1]))
        )
        for field, envs in visible_secret_aliases.items()
    }
    capabilities: dict[str, object] = {}
    if base_channel_id == "sound-effect" and not is_custom_channel:
        has_sound_effect_primary_key = bool(stored_secrets.get("primary_api_key"))
        tts_primary_page_key = _api_management_tts_primary_page_key()
        sound_effect_tts_key_from_page = bool(
            not has_sound_effect_primary_key and tts_primary_page_key
        )
        if secret_unreadable:
            status = "blocked"
            status_label = "凭据不可读取"
            effective_source = "凭据文件不可读取，已阻止回退"
        elif has_sound_effect_primary_key:
            status = "ready"
            status_label = "已配置"
            effective_source = "页面本机加密凭据"
        elif sound_effect_tts_key_from_page:
            status = "ready"
            status_label = "复用 TTS 主 API Key"
            effective_source = "复用 TTS 主 API Key"
        else:
            status = "missing"
            status_label = "待配置音效或 TTS 主 API Key"
            effective_source = "缺少音效或 TTS 主 API Key"
        capabilities = {
            "generate": bool(has_sound_effect_primary_key or sound_effect_tts_key_from_page),
            "shared_credential_channel": "tts" if sound_effect_tts_key_from_page else "",
            "credential_precedence": "sound-effect_then_tts-primary",
        }
    if base_channel_id == "voice-clone-admin" and not is_custom_channel:
        # 新版声音复刻训练和查询固定复用 TTS 主 X-Api-Key；试听不发起
        # TTS，只读取训练返回的 demo_audio。本卡不保存旧版 AppID、
        # AccessToken 或 AK/SK。
        # 声音复刻只能认 API 管理页 DPAPI 中的 TTS 主 Key。即使当前进程
        # 仍继承了同名环境变量，也不能把它显示成“已配置”，否则用户会
        # 误以为声音复刻已绑定当前页面账号。
        tts_primary_page_key = _api_management_tts_primary_page_key()
        has_tts_primary_key = bool(tts_primary_page_key)
        voice_clone_tts_key_from_page = bool(tts_primary_page_key)
        if secret_unreadable:
            status = "blocked"
            status_label = "TTS 凭据不可读取"
        else:
            status = "ready" if has_tts_primary_key else "missing"
            status_label = "复用 TTS 主 API Key" if has_tts_primary_key else "待配置 TTS 主 API Key"
        effective_source = (
            "复用 TTS 主 API Key"
            if has_tts_primary_key and voice_clone_tts_key_from_page
            else ("TTS 凭据不可读取" if secret_unreadable else "缺少 TTS 主 API Key")
        )
        capabilities = {
            "upload": bool(has_tts_primary_key),
            "query": bool(has_tts_primary_key),
            "shared_credential_channel": "tts",
            "requires_app_id": False,
            "legacy_app_id_ignored": True,
            "preview": "requires_tts_api_key_and_enabled_voice",
        }
    credential_runtime_source = (
        "页面本机加密凭据"
        if stored_secrets and not secret_unreadable
        else ("凭据文件不可读取，已阻止回退" if secret_unreadable else "环境变量/鉴权文档回退")
    )
    if base_channel_id == "voice-clone-admin" and not is_custom_channel:
        credential_runtime_source = (
            "页面本机加密凭据（复用 TTS 主 API Key）"
            if voice_clone_tts_key_from_page and not secret_unreadable
            else ("凭据文件不可读取，已阻止回退" if secret_unreadable else "缺少 TTS 主 API Key")
        )
    elif base_channel_id == "sound-effect" and not is_custom_channel:
        credential_runtime_source = (
            "页面本机加密凭据（复用 TTS 主 API Key）"
            if sound_effect_tts_key_from_page and not secret_unreadable
            else (
                "页面本机加密凭据"
                if stored_secrets and not secret_unreadable
                else ("凭据文件不可读取，已阻止回退" if secret_unreadable else "缺少音效或 TTS 主 API Key")
            )
        )
    return {
        "id": str(channel.get("id") or ""),
        "name": str(channel.get("name") or ""),
        "kind": str(channel.get("kind") or ""),
        "resource_kind": resource_kind,
        "status": status,
        "status_label": status_label,
        "provider_ids": provider_ids,
        "provider_names": [str(item.get("name") or "") for item in linked],
        "source": effective_source or "未发现有效配置",
        "endpoint": _api_management_safe_url(endpoint),
        "endpoint_source": endpoint_source,
        "region": region,
        "region_source": "本地配置" if saved.get("region") else (region_env or ("默认值" if region else "")),
        "primary_model": primary_model,
        "primary_model_source": primary_model_source,
        "backup_model": backup_model,
        "backup_model_source": backup_model_source,
        "model_slots": model_slots,
        "model_count": len(model_slots),
        "model_slot_title": model_slot_title,
        "model_slot_count_label": model_slot_count_label,
        "fixed_protocol_defaults": fixed_protocol_defaults,
        "fixed_endpoints": fixed_endpoints,
        "credential_envs": credential_envs,
        "backup_envs": backup_envs,
        "secret_fields": list(visible_secret_aliases),
        "secret_status": secret_status,
        "capabilities": capabilities,
        "credential_runtime": {
            "state": str(secret_health.get("state") or "unknown"),
            "scope": str(secret_health.get("scope") or ""),
            "source": credential_runtime_source,
            "message": str(secret_health.get("message") or ""),
            "recovery_backup_path": str(secret_health.get("recovery_backup_path") or ""),
        },
        "credential_name": str(channel.get("credential_name") or "").strip(),
        "base_channel_id": base_channel_id,
        "is_custom_channel": is_custom_channel,
        "extra_key_supported": bool(extra_spec),
        "extra_key_limit": int(extra_spec["limit"]) if extra_spec else 0,
        "extra_key_count": extra_key_count,
        "nodes": [dict(item) for item in channel.get("nodes", ()) if isinstance(item, Mapping)],
        "strategy": strategy,
        "strategy_options": list(allowed_strategies),
        "max_attempts": max_attempts,
        "timeout_seconds": timeout_seconds,
        "quality": quality,
        "management_only": bool(channel.get("management_only")),
        "read_only_first": bool(channel.get("read_only_first")),
        "default_service": str(next((item.get("default_service") for item in linked if item.get("default_service")), "") or ""),
        "default_version": str(next((item.get("default_version") for item in linked if item.get("default_version")), "") or ""),
        "note": str(channel.get("note") or ""),
        "config": {
            "endpoint": endpoint,
            "region": region,
            "primary_model": primary_model,
            "backup_model": backup_model,
            "strategy": strategy,
            "max_attempts": max_attempts,
            "timeout_seconds": timeout_seconds,
            "quality": quality,
        },
    }


def _api_management_normalize_group_failover(
    group: Mapping[str, object],
    raw_settings: Mapping[str, object] | None,
    *,
    strict: bool = False,
) -> dict[str, object]:
    channel_ids = tuple(str(item) for item in group.get("channel_ids", ()) if str(item).strip())
    raw = raw_settings if isinstance(raw_settings, Mapping) else {}
    raw_order = raw.get("order", channel_ids)
    if not isinstance(raw_order, (list, tuple)):
        if strict:
            raise ValueError("API 之间的降级顺序必须是数组")
        raw_order = channel_ids
    order: list[str] = []
    for item in raw_order:
        channel_id = str(item).strip()
        if channel_id not in channel_ids:
            if strict:
                raise ValueError("API 降级顺序包含不属于当前 API 类型的调用集合")
            continue
        if channel_id not in order:
            order.append(channel_id)
    for channel_id in channel_ids:
        if channel_id not in order:
            order.append(channel_id)
    if strict and not order:
        raise ValueError("API 之间至少需要一个调用集合")
    return {
        "order": order,
        "enabled": len(channel_ids) > 1,
    }


def _api_management_normalize_function_failover(
    raw_settings: Mapping[str, object] | None,
    *,
    default_priority: str = "api_first",
    strict: bool = False,
) -> dict[str, object]:
    raw = raw_settings if isinstance(raw_settings, Mapping) else {}
    priority = str(raw.get("priority") or default_priority).strip()
    if priority not in API_MANAGEMENT_API_FAILOVER_PRIORITY_LABELS:
        if strict:
            raise ValueError("功能降级优先级只能是 API 优先或模型优先")
        priority = "api_first"
    return {
        "priority": priority,
        "priority_label": API_MANAGEMENT_API_FAILOVER_PRIORITY_LABELS[priority],
    }


def _api_management_group_failover_plan(
    channels: list[Mapping[str, object]],
    failover: Mapping[str, object],
) -> list[dict[str, object]]:
    by_id = {str(channel.get("id") or ""): channel for channel in channels}
    ordered_channels = [by_id[channel_id] for channel_id in failover.get("order", ()) if channel_id in by_id]
    slots_by_channel: dict[str, list[Mapping[str, object]]] = {}
    for channel in ordered_channels:
        channel_id = str(channel.get("id") or "")
        slots = [
            item for item in channel.get("model_slots", ())
            if isinstance(item, Mapping)
            and str(item.get("model_id") or item.get("value") or "").strip()
        ]
        slots_by_channel[channel_id] = slots
    entries: list[tuple[Mapping[str, object], Mapping[str, object] | None]] = []
    priority = str(failover.get("priority") or "api_first")
    if priority == "model_first":
        max_slots = max((len(items) for items in slots_by_channel.values()), default=0)
        if not max_slots:
            entries = [(channel, None) for channel in ordered_channels]
        for slot_index in range(max_slots):
            for channel in ordered_channels:
                slots = slots_by_channel.get(str(channel.get("id") or ""), [])
                if slot_index < len(slots):
                    entries.append((channel, slots[slot_index]))
    else:
        for channel in ordered_channels:
            slots = slots_by_channel.get(str(channel.get("id") or ""), [])
            if not slots:
                entries.append((channel, None))
                continue
            for slot in slots:
                entries.append((channel, slot))
    plan: list[dict[str, object]] = []
    for index, (channel, slot) in enumerate(entries, start=1):
        provider_names = [str(item) for item in channel.get("provider_names", ()) if str(item).strip()]
        model_id = str(
            (slot or {}).get("model_id")
            or (slot or {}).get("value")
            or ""
        ).strip() if slot else ""
        model_name = str((slot or {}).get("model_name") or "").strip() if slot else ""
        plan.append({
            "step": index,
            "api_id": str(channel.get("id") or ""),
            "api_name": " / ".join(provider_names) or str(channel.get("name") or "API 凭据集合"),
            "channel_name": str(channel.get("name") or ""),
            "model_source": str(slot.get("source") or "") if slot else "",
            "model_name": model_name or "未命名模型",
            "model_id": model_id or "未设置",
            "model_value": model_id,
        })
    return plan


def _api_management_group_snapshot(
    group: Mapping[str, object],
    providers: Mapping[str, Mapping[str, object]],
    saved_groups: Mapping[str, object],
    saved_api_groups: Mapping[str, object],
    saved_api_functions: Mapping[str, object],
    saved_api_channels: Mapping[str, object] | None = None,
    saved_removed_channels: Mapping[str, object] | None = None,
) -> dict[str, object]:
    channel_specs_list = _api_management_group_channel_specs(
        group,
        {
            "api_channels": saved_api_channels or {},
            "removed_channels": saved_removed_channels or {},
        },
    )
    channel_ids = tuple(str(channel.get("id") or "") for channel in channel_specs_list if str(channel.get("id") or ""))
    channel_specs = {str(channel.get("id") or ""): channel for channel in channel_specs_list}
    channels: list[dict[str, object]] = []
    for channel_id in channel_ids:
        channel = channel_specs.get(channel_id)
        if channel is None:
            continue
        raw_settings = saved_groups.get(channel_id, {})
        if not isinstance(raw_settings, Mapping) and len(channel_ids) == 1:
            raw_settings = saved_groups.get(str(group.get("id") or ""), {})
        channels.append(
            _api_management_channel_snapshot(
                channel,
                providers,
                raw_settings if isinstance(raw_settings, Mapping) else {},
            )
        )
    # management_only 通道（例如声音复刻上传/状态管理）是可选的管理能力，
    # 不能阻断同一 API 组里的实际合成能力。TTS 组的可用性只由运行时通道
    # 决定；如果某个组全是管理通道，才退回使用全部通道计算状态。
    runtime_channels = [item for item in channels if not item.get("management_only")]
    status_channels = runtime_channels or channels
    states = [str(item.get("status") or "missing") for item in status_channels]
    if any(state == "blocked" for state in states):
        status = "blocked"
        status_label = "凭据不可读取"
    elif channels and all(state in {"ready", "document"} for state in states):
        status = "ready"
        status_label = "已配置"
    elif any(state in {"ready", "document", "partial"} for state in states):
        status = "partial"
        status_label = "部分配置"
    else:
        status = "missing"
        status_label = "待配置"
    nodes: list[dict[str, object]] = []
    for channel in runtime_channels:
        if channel.get("is_custom_channel"):
            continue
        for raw_node in channel.get("nodes", []):
            if not isinstance(raw_node, Mapping):
                continue
            node = dict(raw_node)
            node["channel_id"] = channel["id"]
            node["channel_name"] = channel["name"]
            node["label"] = f"{channel['name']} · {node.get('label') or node.get('id') or ''}"
            nodes.append(node)
    provider_names = list(dict.fromkeys(
        name
        for channel in channels
        for name in (channel.get("provider_names") or [])
        if name
    ))
    credential_envs = list(dict.fromkeys(
        name
        for channel in channels
        for name in (channel.get("credential_envs") or [])
        if name
    ))
    backup_envs = list(dict.fromkeys(
        name
        for channel in channels
        for name in (channel.get("backup_envs") or [])
        if name
    ))
    single = channels[0] if len(channels) == 1 else {}
    group_id = str(group.get("id") or "")
    effective_group = dict(group)
    # 管理通道不加入 API 之间的运行时降级顺序；它们仍保留在 channels
    # 中供配置中心展示和显式管理。
    effective_group["channel_ids"] = tuple(
        str(channel.get("id") or "")
        for channel in channels
        if str(channel.get("id") or "") and not channel.get("management_only")
    ) or channel_ids
    api_order_settings = _api_management_normalize_group_failover(
        effective_group,
        saved_api_groups.get(group_id) if isinstance(saved_api_groups, Mapping) else {},
    )
    api_failover = {
        "order": list(api_order_settings["order"]),
        "enabled": bool(api_order_settings["enabled"]),
    }
    raw_function_settings = (
        saved_api_functions.get(group_id, {})
        if isinstance(saved_api_functions, Mapping)
        else {}
    )
    raw_function_settings = raw_function_settings if isinstance(raw_function_settings, Mapping) else {}
    functions: list[dict[str, object]] = []
    for channel in runtime_channels:
        if channel.get("is_custom_channel"):
            continue
        for raw_node in channel.get("nodes", []):
            if not isinstance(raw_node, Mapping):
                continue
            function_id = str(raw_node.get("id") or "").strip()
            if not function_id:
                continue
            function_failover = _api_management_normalize_function_failover(
                raw_function_settings.get(function_id, {}),
            )
            function_failover["plan"] = _api_management_group_failover_plan(
                channels,
                {"order": api_order_settings["order"], "priority": function_failover["priority"]},
            )
            functions.append({
                "id": function_id,
                "label": str(raw_node.get("label") or function_id),
                "channel_id": str(channel.get("id") or ""),
                "channel_name": str(channel.get("name") or ""),
                "failover": function_failover,
            })
    return {
        "id": group_id,
        "name": str(group.get("name") or ""),
        "kind": str(group.get("kind") or ""),
        "status": status,
        "status_label": status_label,
        "channel_ids": list(channel_ids),
        "channel_count": len(channels),
        "channels": channels,
        "provider_names": provider_names,
        "source": "；".join(f"{item['name']}：{item['source']}" for item in channels)
        or "未发现有效配置",
        "endpoint": str(single.get("endpoint") or ""),
        "endpoint_source": str(single.get("endpoint_source") or ("多通道" if channels else "")),
        "primary_model": str(single.get("primary_model") or ""),
        "primary_model_source": str(single.get("primary_model_source") or ""),
        "backup_model": str(single.get("backup_model") or ""),
        "backup_model_source": str(single.get("backup_model_source") or ""),
        "model_slots": list(single.get("model_slots") or []) if single else [],
        "model_count": int(single.get("model_count") or 0) if single else 0,
        "model_slot_title": str(single.get("model_slot_title") or "模型") if single else "模型",
        "model_slot_count_label": str(single.get("model_slot_count_label") or "模型") if single else "模型",
        "api_failover": api_failover,
        "functions": functions,
        "credential_envs": credential_envs,
        "backup_envs": backup_envs,
        "nodes": nodes,
        "strategy": str(single.get("strategy") or "") if single else "",
        "strategy_options": list(single.get("strategy_options") or []) if single else [],
        "max_attempts": single.get("max_attempts") if single else 0,
        "timeout_seconds": single.get("timeout_seconds") if single else 0,
        "note": str(group.get("note") or ""),
        "config": dict(single.get("config") or {}) if single else {},
    }


def _api_management_snapshot() -> dict[str, object]:
    config = _api_management_load_config()
    _api_management_apply_runtime_config(config)
    auth_document_env = os.environ.get("DIRECTOR_AUTH_DOCUMENT", "").strip()
    auth_document_label = (
        auth_document_env
        if auth_document_env
        else ("已禁用（8768 页面凭据专用）" if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS else str(DEFAULT_AUTH_DOCUMENT))
    )
    providers = {
        str(spec.get("id") or ""): _api_management_provider_snapshot(spec)
        for spec in API_MANAGEMENT_SPECS
    }
    saved_groups = config.get("groups") if isinstance(config, Mapping) else {}
    saved_groups = saved_groups if isinstance(saved_groups, Mapping) else {}
    saved_api_groups = config.get("api_groups") if isinstance(config, Mapping) else {}
    saved_api_groups = saved_api_groups if isinstance(saved_api_groups, Mapping) else {}
    saved_api_functions = config.get("api_functions") if isinstance(config, Mapping) else {}
    saved_api_functions = saved_api_functions if isinstance(saved_api_functions, Mapping) else {}
    saved_api_channels = config.get("api_channels") if isinstance(config, Mapping) else {}
    saved_api_channels = saved_api_channels if isinstance(saved_api_channels, Mapping) else {}
    saved_removed_channels = config.get("removed_channels") if isinstance(config, Mapping) else {}
    saved_removed_channels = saved_removed_channels if isinstance(saved_removed_channels, Mapping) else {}
    groups = [
        _api_management_group_snapshot(
            group,
            providers,
            saved_groups,
            saved_api_groups,
            saved_api_functions,
            saved_api_channels,
            saved_removed_channels,
        )
        for group in API_MANAGEMENT_GROUPS
    ]
    missing = [
        {
            "id": item["id"],
            "name": item["name"],
            "status_label": item["status_label"],
            "nodes": item["nodes"],
        }
        for item in groups
        if item["status"] in {"missing", "partial", "blocked"}
    ]
    runtime_audit = _api_management_runtime_audit(groups)
    return {
        "generated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "runtime": {
            "pid": os.getpid(),
            "root": str(ROOT),
            "auth_document": str(Path(auth_document_label).expanduser())
            if auth_document_env
            else auth_document_label,
            "config_path": str(API_MANAGEMENT_CONFIG_PATH),
            "secret_path": str(API_MANAGEMENT_SECRET_PATH),
        },
        "summary": {
            "total": len(groups),
            "ready": sum(item["status"] == "ready" for item in groups),
            "partial": sum(item["status"] == "partial" for item in groups),
            "missing": sum(item["status"] == "missing" for item in groups),
            "blocked": sum(item["status"] == "blocked" for item in groups),
            "needs_attention": len(missing),
        },
        "secret_runtime": _api_management_secret_health_snapshot(),
        "groups": groups,
        "missing": missing,
        "runtime_audit": runtime_audit,
    }


def _api_management_route_preview(node_id: str) -> dict[str, object]:
    """计算单个业务节点的降级尝试序列；只读，不发送供应商请求。"""

    requested_node_id = str(node_id or "").strip()
    if not requested_node_id:
        raise ValueError("缺少 node_id")
    snapshot = _api_management_snapshot()
    runtime_nodes = {
        str(item.get("node_id") or ""): item
        for item in (snapshot.get("runtime_audit", {}).get("nodes", ())
                     if isinstance(snapshot.get("runtime_audit"), Mapping) else ())
        if isinstance(item, Mapping) and str(item.get("node_id") or "").strip()
    }
    runtime_node = runtime_nodes.get(requested_node_id)
    if runtime_node is None:
        raise ValueError("未找到该运行时节点")
    for group in snapshot.get("groups", ()):
        if not isinstance(group, Mapping):
            continue
        for function in group.get("functions", ()):
            if not isinstance(function, Mapping) or str(function.get("id") or "") != requested_node_id:
                continue
            failover = function.get("failover") if isinstance(function.get("failover"), Mapping) else {}
            plan = [dict(item) for item in failover.get("plan", ()) if isinstance(item, Mapping)]
            business_plan_applied = False
            if requested_node_id == "writing.subtitle-correction":
                # 字幕纠错不是通用故事模型链：运行时只选择每个 API 通道中
                # 名称含 Mini 的槽位，并按 language-model 的 API 顺序切换。
                channels_by_id = {
                    str(channel.get("id") or ""): channel
                    for snapshot_group in snapshot.get("groups", ())
                    if isinstance(snapshot_group, Mapping)
                    for channel in snapshot_group.get("channels", ())
                    if isinstance(channel, Mapping) and str(channel.get("id") or "").strip()
                }
                mini_plan: list[dict[str, object]] = []
                for step, channel_id in enumerate(runtime_node.get("dependency_channel_ids", ()), start=1):
                    channel = channels_by_id.get(str(channel_id))
                    if channel is None:
                        continue
                    slots = channel.get("model_slots") if isinstance(channel.get("model_slots"), (list, tuple)) else ()
                    mini_slot = next(
                        (
                            slot for slot in slots
                            if isinstance(slot, Mapping)
                            and "mini" in str(slot.get("model_name") or "").lower()
                            and str(slot.get("model_id") or slot.get("value") or "").strip()
                        ),
                        None,
                    )
                    if mini_slot is None:
                        continue
                    provider_names = [str(item) for item in channel.get("provider_names", ()) if str(item).strip()]
                    model_id = str(mini_slot.get("model_id") or mini_slot.get("value") or "").strip()
                    mini_plan.append({
                        "step": len(mini_plan) + 1,
                        "api_id": str(channel.get("id") or ""),
                        "api_name": " / ".join(provider_names) or str(channel.get("name") or "API 凭据集合"),
                        "channel_name": str(channel.get("name") or ""),
                        "model_source": str(mini_slot.get("source") or ""),
                        "model_name": str(mini_slot.get("model_name") or "Doubao-Seed-2.0-mini"),
                        "model_id": model_id,
                        "model_value": model_id,
                    })
                if mini_plan:
                    plan = mini_plan
                    business_plan_applied = True
            return {
                "mode": "dry_run",
                "message": "仅计算调用顺序，不发送请求，不产生第三方费用。",
                "node": {
                    "node_id": requested_node_id,
                    "entrypoint": runtime_node.get("entrypoint", ""),
                    "status": runtime_node.get("status", ""),
                    "status_label": runtime_node.get("status_label", ""),
                    "auth_source": runtime_node.get("auth_source", ""),
                    "auth_mode": runtime_node.get("auth_mode", ""),
                    "dependency_channel_ids": list(runtime_node.get("dependency_channel_ids", ())),
                },
                "function": {
                    "group_id": str(group.get("id") or ""),
                    "label": str(function.get("label") or requested_node_id),
                    "channel_id": str(function.get("channel_id") or ""),
                    "priority": str(failover.get("priority") or "api_first"),
                    "priority_label": str(failover.get("priority_label") or "API 优先"),
                    "business_plan_applied": business_plan_applied,
                },
                "plan": plan,
            }
    raise ValueError("该节点尚未登记业务降级配置")


def _api_management_verification_http_json(
    url: str,
    headers: Mapping[str, str],
    payload: Mapping[str, object],
    timeout: float,
) -> tuple[int, Mapping[str, object]]:
    """发送受控验证请求；只返回 HTTP 状态和 JSON 结构，不保留供应商正文。"""

    request = Request(
        url,
        data=json.dumps(dict(payload), ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={"Content-Type": "application/json", "Accept": "application/json", **headers},
    )
    raw: bytes
    try:
        with urlopen(request, timeout=timeout) as response:
            status = int(getattr(response, "status", 200))
            raw = response.read()
    except HTTPError as exc:
        # 鉴权失败只需要 HTTP 状态；不把供应商错误正文带回本地页面或日志。
        return int(exc.code), {}
    except (URLError, TimeoutError, OSError):
        try:
            import requests

            response = requests.post(
                url,
                json=dict(payload),
                headers={"Accept": "application/json", **headers},
                timeout=timeout,
            )
        except Exception as fallback_exc:
            raise RuntimeError("网络请求失败") from fallback_exc
        status = int(response.status_code)
        raw = response.content
    try:
        parsed = json.loads(raw.decode("utf-8", errors="replace"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return status, {}
    return status, parsed if isinstance(parsed, Mapping) else {}


def _api_management_verification_failure(
    exc: Exception,
    *,
    http_status: int | None = None,
) -> dict[str, object]:
    """把真实调用异常压缩为不泄露响应正文的验证结果。"""

    text = str(exc).lower()
    status = http_status
    match = re.search(r"\bhttp\s+(\d{3})\b", text)
    if status is None and match:
        status = int(match.group(1))
    if status in {401, 403}:
        result_status = "auth_failed"
        message = "供应商拒绝鉴权或权限不足"
        auth_verified = False
    elif status == 429:
        result_status = "rate_limited"
        message = "供应商限流；本次不能据此判定密钥无效"
        auth_verified = True
    elif status is not None and 400 <= status < 500:
        result_status = "provider_rejected"
        message = "供应商拒绝了验证请求参数或资源"
        auth_verified = True
    elif any(marker in text for marker in ("网络请求失败", "timed out", "timeout", "连接", "dns")):
        result_status = "network_error"
        message = "网络或连接失败，尚未判定鉴权结果"
        auth_verified = False
    elif status is not None and status < 400 and any(
        marker in text
        for marker in ("响应缺少", "响应不是", "响应结构", "json", "音频", "duration")
    ):
        result_status = "provider_response_invalid"
        message = "供应商已响应，但返回内容未通过当前协议校验"
        auth_verified = True
    elif "配置" in text or "不能为空" in text or "未配置" in text:
        result_status = "config_error"
        message = "本机运行时配置不完整，未发起有效验证"
        auth_verified = False
    else:
        result_status = "failed"
        message = "验证请求失败，未判定鉴权结果"
        auth_verified = False
    result: dict[str, object] = {
        "status": result_status,
        "auth_verified": auth_verified,
        "message": message,
    }
    if status is not None:
        result["http_status"] = status
    return result


def _api_management_channel_context(channel: Mapping[str, object]) -> dict[str, object]:
    nodes = [
        dict(node)
        for node in channel.get("nodes", ())
        if isinstance(node, Mapping) and str(node.get("id") or "").strip()
    ]
    return {
        "channel_id": str(channel.get("id") or ""),
        "channel_name": str(channel.get("name") or channel.get("id") or ""),
        "node_ids": [str(node.get("id") or "") for node in nodes],
        "node_labels": [str(node.get("label") or node.get("id") or "") for node in nodes],
    }


def _api_management_channel_models(channel: Mapping[str, object]) -> list[dict[str, str]]:
    result: list[dict[str, str]] = []
    seen: set[str] = set()
    slots = channel.get("model_slots") if isinstance(channel.get("model_slots"), (list, tuple)) else ()
    for slot in slots:
        if not isinstance(slot, Mapping):
            continue
        model_id = str(slot.get("model_id") or slot.get("value") or "").strip()
        if not model_id or model_id in seen:
            continue
        seen.add(model_id)
        result.append({
            "model_id": model_id,
            "model_name": str(slot.get("model_name") or slot.get("label") or model_id),
        })
    if result:
        return result
    config = channel.get("config") if isinstance(channel.get("config"), Mapping) else {}
    for field in ("primary_model", "backup_model"):
        model_id = str(config.get(field) or channel.get(field) or "").strip()
        if model_id and model_id not in seen:
            seen.add(model_id)
            result.append({"model_id": model_id, "model_name": model_id})
    return result


def _api_management_story_credentials() -> list[tuple[str, str]]:
    """复用故事 transport 的真实主/备用鉴权顺序，不读取或打印明文。"""

    transport = ArkStoryFailoverHTTPTransport.from_runtime_config()
    result: list[tuple[str, str]] = []
    for index, item in enumerate(transport.transports):
        key = str(item.config.api_key or "").strip()
        if not key:
            continue
        label = "主 API Key" if index == 0 else f"备用 API Key {index}"
        if key not in {value for value, _label in result}:
            result.append((key, label))
    return result


def _api_management_director_credentials(timeout: float) -> list[tuple[str, str]]:
    document = Path(
        os.environ.get("DIRECTOR_AUTH_DOCUMENT", str(DEFAULT_AUTH_DOCUMENT))
    ).expanduser()
    transport = DualSeed21TurboTextTransport(
        document,
        max_tokens=8,
        timeout=timeout,
        json_mode=False,
    )
    result: list[tuple[str, str]] = []
    for index, item in enumerate(transport.auths):
        key = str(item[0] or "").strip()
        if not key:
            continue
        label = "主 API Key" if index == 0 else f"备用 API Key {index}"
        if key not in {value for value, _label in result}:
            result.append((key, label))
    return result


def _api_management_verify_story_channel(channel: Mapping[str, object]) -> list[dict[str, object]]:
    context = _api_management_channel_context(channel)
    endpoint = str(channel.get("endpoint") or "").strip()
    models = _api_management_channel_models(channel)
    try:
        credentials = _api_management_story_credentials()
    except Exception as exc:
        failure = _api_management_verification_failure(exc)
        return [{**context, **failure, "scope": "故事与文案模型"}]
    if not endpoint or not models or not credentials:
        return [{
            **context,
            "scope": "故事与文案模型",
            "status": "config_error",
            "auth_verified": False,
            "message": "缺少 API 地址、模型或 API Key，未发起验证",
        }]
    config = channel.get("config") if isinstance(channel.get("config"), Mapping) else {}
    try:
        timeout = min(45.0, max(5.0, float(config.get("timeout_seconds") or channel.get("timeout_seconds") or 120)))
    except (TypeError, ValueError):
        timeout = 45.0
    results: list[dict[str, object]] = []
    for key, credential_label in credentials:
        for model in models:
            observed_status: list[int | None] = [None]

            def requester(
                url: str,
                headers: Mapping[str, str],
                payload: Mapping[str, object],
                request_timeout: float,
            ) -> Mapping[str, object]:
                request_payload = dict(payload)
                request_payload["max_output_tokens"] = 8
                request_payload["temperature"] = 0
                status, response = _api_management_verification_http_json(
                    url, headers, request_payload, request_timeout
                )
                observed_status[0] = status
                if status >= 400:
                    raise ArkStoryTransportError(f"HTTP {status}")
                return response

            item: dict[str, object] = {
                **context,
                "scope": "故事与文案模型",
                "credential_slot": credential_label,
                "credential_source": _api_management_effective_credential_source(),
                "model_id": model["model_id"],
                "model_name": model["model_name"],
            }
            try:
                transport = ArkStoryHTTPTransport(
                    ArkStoryConfig(
                        api_key=key,
                        model=model["model_id"],
                        api_url=endpoint,
                        timeout=timeout,
                    ),
                    requester=requester,
                )
                transport("受控鉴权验证。", "仅回复 OK。")
                item.update({
                    "status": "passed",
                    "auth_verified": True,
                    "message": "供应商已接受最小请求",
                })
            except Exception as exc:
                item.update(_api_management_verification_failure(exc, http_status=observed_status[0]))
            if observed_status[0] is not None:
                item["http_status"] = observed_status[0]
            results.append(item)
    return results


def _api_management_verify_director_channel(channel: Mapping[str, object]) -> list[dict[str, object]]:
    context = _api_management_channel_context(channel)
    endpoint = str(channel.get("endpoint") or "").strip()
    models = _api_management_channel_models(channel)
    config = channel.get("config") if isinstance(channel.get("config"), Mapping) else {}
    try:
        timeout = min(45.0, max(5.0, float(config.get("timeout_seconds") or channel.get("timeout_seconds") or 120)))
    except (TypeError, ValueError):
        timeout = 45.0
    try:
        credentials = _api_management_director_credentials(timeout)
    except Exception as exc:
        failure = _api_management_verification_failure(exc)
        return [{**context, **failure, "scope": "Seed 2.1 编导文本"}]
    if not endpoint or not models or not credentials:
        return [{
            **context,
            "scope": "Seed 2.1 编导文本",
            "status": "config_error",
            "auth_verified": False,
            "message": "缺少 API 地址、模型或 API Key，未发起验证",
        }]
    results: list[dict[str, object]] = []
    for key, credential_label in credentials:
        for model in models:
            item: dict[str, object] = {
                **context,
                "scope": "Seed 2.1 编导文本",
                "credential_slot": credential_label,
                "credential_source": _api_management_effective_credential_source(),
                "model_id": model["model_id"],
                "model_name": model["model_name"],
            }
            status_value: int | None = None
            try:
                status, response = _api_management_verification_http_json(
                    endpoint,
                    {"Authorization": "Bearer " + key},
                    {
                        "model": model["model_id"],
                        "messages": [{"role": "user", "content": "仅回复 OK。"}],
                        "thinking": {"type": "disabled"},
                        "temperature": 0,
                        "max_tokens": 8,
                    },
                    timeout,
                )
                status_value = status
                if status >= 400:
                    raise RuntimeError(f"HTTP {status}")
                if not isinstance(response.get("choices"), list) or not response.get("choices"):
                    raise RuntimeError("响应结构无效")
                item.update({
                    "status": "passed",
                    "auth_verified": True,
                    "message": "供应商已接受最小请求",
                    "http_status": status,
                })
            except Exception as exc:
                item.update(_api_management_verification_failure(
                    exc,
                    http_status=status_value if isinstance(status_value, int) else None,
                ))
                if isinstance(status_value, int):
                    item["http_status"] = status_value
            results.append(item)
    return results


def _api_management_verify_tts_channel(channel: Mapping[str, object]) -> list[dict[str, object]]:
    context = _api_management_channel_context(channel)
    item: dict[str, object] = {**context, "scope": "TTS"}
    try:
        transport = ArkTTSHTTPTransport.from_env()
        voice = _resolve_story_voice()
        result = transport.synthesize_local(SpeechSynthesisRequest(
            text="好",
            speed_ratio=1.0,
            voice_id=voice["speaker_id"],
            speaker_id=voice["speaker_id"],
            custom_speaker_id=voice.get("custom_speaker_id") or None,
            language="中文",
            resource_id=voice.get("resource_id"),
            model=voice.get("model"),
        ))
        metadata = result.get("metadata") if isinstance(result, Mapping) else {}
        item.update({
            "status": "passed",
            "auth_verified": True,
            "message": "供应商已接受最短 TTS 请求；音频未保存、未上传",
            "auth_slot": str(metadata.get("auth_slot") or "主 API Key") if isinstance(metadata, Mapping) else "主 API Key",
            "voice_key": voice["voice_key"],
            "resource_id": voice.get("resource_id", ""),
            "model": voice.get("model", ""),
            "duration_seconds": float(result.get("duration") or 0) if isinstance(result, Mapping) else 0,
            "audio_bytes": len(result.get("audio") or b"") if isinstance(result, Mapping) and isinstance(result.get("audio"), (bytes, bytearray)) else 0,
        })
    except Exception as exc:
        item.update(_api_management_verification_failure(exc))
    return [item]


def _api_management_verify_voice_clone_admin_channel(channel: Mapping[str, object]) -> list[dict[str, object]]:
    """报告新版声音复刻与 TTS API Key 的共享关系，不发起训练请求。"""
    context = _api_management_channel_context(channel)
    item: dict[str, object] = {**context, "scope": "新版声音复刻"}
    # 这里只做配置关系审计，不发起外部请求；状态也只认页面密文中的
    # TTS 主 Key，避免把旧环境变量误报为当前账号已绑定。
    has_tts_primary_key = bool(_api_management_tts_primary_page_key())
    return [{
        **item,
        "status": "not_checked",
        "auth_verified": False,
        "credential_source": "shared_tts_primary_api_key" if has_tts_primary_key else "tts_primary_api_key_missing",
        "message": (
            "新版声音复刻固定复用 TTS 主 API Key；副 API Key 仅用于 TTS 合成跌落。"
            "本次未上传声音或发起训练，请在编导弹窗确认后执行音色训练/按 speaker_id 查询"
            if has_tts_primary_key
            else "未配置 TTS 主 API Key；声音复刻训练与查询不会发起请求"
        ),
    }]


def _api_management_verify_tos_channel(channel: Mapping[str, object]) -> list[dict[str, object]]:
    context = _api_management_channel_context(channel)
    configs = _tos_bucket_configs_from_runtime_auth({})
    if not configs:
        return [{
            **context,
            "scope": "TOS 存储桶",
            "status": "config_error",
            "auth_verified": False,
            "message": "缺少 Access Key、Secret Key、桶、Endpoint 或 Region，未发起探测",
        }]
    results: list[dict[str, object]] = []
    for index, config in enumerate(configs):
        item: dict[str, object] = {
            **context,
            "scope": "TOS 存储桶",
            "bucket_slot": "主存储桶" if index == 0 else f"备用存储桶 {index}",
            "bucket": config.bucket,
            "endpoint": _api_management_safe_url(config.endpoint),
            "region": config.region,
        }
        try:
            import tos

            client = tos.TosClientV2(
                config.access_key,
                config.secret_key,
                config.endpoint,
                region=config.region,
            )
            response = client.head_bucket(config.bucket)
            status = getattr(response, "status_code", None)
            if isinstance(status, int) and status >= 400:
                raise RuntimeError(f"HTTP {status}")
            item.update({
                "status": "passed",
                "auth_verified": True,
                "message": "TOS 已接受桶权限探测；未上传对象",
            })
            if isinstance(status, int):
                item["http_status"] = status
        except Exception as exc:
            item.update(_api_management_verification_failure(exc))
        results.append(item)
    return results


def _api_management_not_checked(channel: Mapping[str, object], reason: str) -> dict[str, object]:
    return {
        **_api_management_channel_context(channel),
        "scope": str(channel.get("name") or channel.get("id") or "外部 API"),
        "status": "not_checked",
        "auth_verified": False,
        "message": reason,
    }


def _voice_clone_transport_from_page() -> VoiceCloneTransport:
    """构造新版声音复刻 transport，并优先读取 API 管理页的 TTS 主 Key。

    声音复刻卡片不保存自己的密钥。生产服务先从 DPAPI 密文中的 ``tts``
    通道取主 Key，直接构造 v3 transport；只有独立脚本/旧测试没有页面密文
    时才保留 ``from_env`` 兼容入口。无论哪条路径都不会读取备用 Key。
    """

    primary_api_key = _api_management_tts_primary_page_key()
    if primary_api_key:
        page_factory = getattr(VoiceCloneTransport, "from_api_key", None)
        if callable(page_factory):
            return page_factory(primary_api_key)
        # 测试替身/旧独立脚本可能只提供 from_env；真实新版 transport
        # 始终具备上面的 from_api_key，不会走到这里。
        return VoiceCloneTransport.from_env()
    # 正式 8768 服务必须以 API 管理中心为唯一凭据源。不能因为页面没有
    # 主 Key 就偷偷读取进程继承的环境变量，否则声音复刻可能落到错误账号，
    # 也会绕过用户在页面上看到的鉴权状态。独立脚本/测试导入时仍保留
    # from_env 兼容，但不会改变正式生产链路。
    if _API_MANAGEMENT_RUNTIME_ENFORCE_PAGE_CREDENTIALS:
        raise VoiceCloneError("新版声音复刻未配置 TTS 主 API Key；请先在 API 管理中心填写并保存")
    return VoiceCloneTransport.from_env()


def _voice_clone_status_readonly(payload: Mapping[str, object]) -> dict[str, object]:
    """通过新版 ``get_voice`` 查询普通或后付费自定义音色状态。"""

    if str(payload.get("confirm") or "").strip() != "readonly-voice-status":
        raise ValueError("声音复刻状态查询需要 confirm=readonly-voice-status")
    TASK_LOGGER.info("voice_clone stage=status_query status=started")
    _api_management_require_runtime_credentials(("tts",))
    try:
        transport = _voice_clone_transport_from_page()
        targets: list[tuple[str, str]] = []
        raw_targets = payload.get("voices")
        if isinstance(raw_targets, list):
            for item in raw_targets:
                if not isinstance(item, Mapping):
                    continue
                provider_id = str(item.get("speaker_id") or "").strip()
                custom_id = str(item.get("custom_speaker_id") or "").strip()
                if provider_id or custom_id:
                    targets.append((provider_id, custom_id))
        if not targets:
            raw_speaker_ids = payload.get("speaker_ids") if isinstance(payload.get("speaker_ids"), list) else []
            if not raw_speaker_ids and str(payload.get("speaker_id") or "").strip():
                raw_speaker_ids = [payload.get("speaker_id")]
            top_custom = str(payload.get("custom_speaker_id") or "").strip()
            targets = [
                (str(item).strip(), top_custom if index == 0 else "")
                for index, item in enumerate(raw_speaker_ids)
                if str(item).strip()
            ]
        if not targets:
            raise ValueError("声音复刻状态查询必须提供 speaker_id；后付费音色还需 custom_speaker_id")
        results: list[dict[str, object]] = []
        for provider_id, custom_id in targets:
            if custom_id:
                results.append(transport.query(provider_id, custom_speaker_id=custom_id))
            else:
                # 保持测试替身/独立脚本对普通真实 speaker_id 的最小旧签名兼容。
                results.append(transport.query(provider_id))
        statuses = [{
            "SpeakerID": str(item.get("speaker_id") or (custom_id or provider_id)),
            "ProviderSpeakerID": str(item.get("provider_speaker_id") or provider_id),
            "CustomSpeakerID": str(item.get("custom_speaker_id") or custom_id),
            "State": str(item.get("training_status") or "Unknown"),
            "Status": item.get("status"),
            "DemoAudio": str(item.get("demo_audio") or ""),
            "ResourceID": "seed-icl-2.0",
        } for (provider_id, custom_id), item in zip(targets, results)]
        aggregate_response = {"Result": {"Statuses": statuses}}
        result = {
            "action": "get_voice",
            "results": results,
            "response": aggregate_response,
        }
        sync = _sync_voice_catalog_statuses(result)
        response = {
            "status": "ready",
            "evidence_level": "live_readonly_voice_clone",
            "result": result,
            "catalog_sync": sync,
        }
        TASK_LOGGER.info(
            "voice_clone stage=status_query status=succeeded count=%s",
            len(results),
        )
        return response
    except (ValueError, VoiceCloneError, VoiceCatalogStoreError) as exc:
        TASK_LOGGER.warning(
            "voice_clone stage=status_query status=failed error=%s",
            str(exc)[:300],
        )
        raise ValueError(str(exc)) from exc


def _official_voice_key(speaker_id: str) -> str:
    """为官方列表项生成稳定的本地 voice_key；不把 provider ID 当作可变展示名。"""

    digest = hashlib.sha256(str(speaker_id).encode("utf-8")).hexdigest()[:10]
    return f"official_{digest}"


def _voice_clone_prepaid_slot_rows(payload: Mapping[str, object]) -> list[dict[str, object]]:
    """解析用户从新版控制台复制的预付费/免费槽位。

    新版数据面没有把“项目有多少槽位”作为训练请求的自动发现参数；
    因此这里提供一个本地导入入口。导入只保存真实 ``speaker_id`` 元数据，
    不调用旧资源控制面、不购买槽位，也不会把文本当成自定义 ID 自动猜测。
    """

    raw_slots = payload.get("slots")
    candidates: list[object] = list(raw_slots) if isinstance(raw_slots, list) else []
    if not candidates:
        raw_ids = payload.get("speaker_ids")
        if isinstance(raw_ids, list):
            candidates = list(raw_ids)
        else:
            raw_text = str(
                payload.get("speaker_ids_text")
                or payload.get("slot_ids_text")
                or payload.get("speaker_id_text")
                or ""
            ).strip()
            if raw_text:
                candidates = [item for item in re.split(r"[\s,，;；、]+", raw_text) if item]
    if not candidates:
        raise ValueError("请粘贴新版控制台音色库中的 speaker_id；支持一行一个或逗号分隔")
    if len(candidates) > 100:
        raise ValueError("一次最多导入 100 个音色槽位")

    raw_names = payload.get("slot_names")
    names = list(raw_names) if isinstance(raw_names, list) else []
    rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for index, candidate in enumerate(candidates, start=1):
        if isinstance(candidate, Mapping):
            speaker_id = str(
                candidate.get("speaker_id")
                or candidate.get("SpeakerID")
                or candidate.get("VoiceType")
                or candidate.get("id")
                or ""
            ).strip()
            display_name = str(
                candidate.get("display_name")
                or candidate.get("name")
                or candidate.get("Name")
                or ""
            ).strip()[:80]
            display_name_explicit = bool(display_name)
            gender = _official_voice_gender(candidate.get("gender") or candidate.get("Gender"))
            language_values = _official_voice_languages(
                candidate.get("languages") or candidate.get("Languages")
            )
        else:
            speaker_id = str(candidate or "").strip()
            display_name = ""
            display_name_explicit = False
            gender = "neutral"
            language_values = ["zh-CN"]
        if not speaker_id:
            continue
        if speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
            raise ValueError("预付费/免费槽位不能使用固定值 custom_speaker_id")
        if len(speaker_id) > 256 or any(char.isspace() or ord(char) < 32 for char in speaker_id):
            raise ValueError(f"speaker_id 不合法：{speaker_id[:80]}")
        if speaker_id in seen:
            continue
        seen.add(speaker_id)
        if not display_name and index <= len(names):
            display_name = str(names[index - 1] or "").strip()[:80]
            display_name_explicit = bool(display_name)
        rows.append({
            "speaker_id": speaker_id,
            "display_name": display_name or f"预付费槽位 {index}",
            "display_name_explicit": display_name_explicit,
            "gender": gender,
            "languages": language_values,
            "resource_id": "seed-icl-2.0",
        })
    if not rows:
        raise ValueError("没有解析到有效的 speaker_id")
    return rows


def _voice_clone_import_prepaid_slots(payload: Mapping[str, object]) -> dict[str, object]:
    """把已有预付费/免费槽位导入本地目录，供编导弹窗选择训练。"""

    if str(payload.get("confirm") or "").strip() != "import-prepaid-voice-slots":
        raise ValueError("导入预付费槽位需要 confirm=import-prepaid-voice-slots")
    rows = _voice_clone_prepaid_slot_rows(payload)
    store = _voice_catalog_store()
    catalog = store.load()
    voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
    imported: list[str] = []
    updated: list[str] = []
    for row in rows:
        speaker_id = str(row["speaker_id"])
        target = next(
            (
                item for item in voices
                if isinstance(item, Mapping)
                and effective_speaker_id(item) == speaker_id
            ),
            None,
        )
        if isinstance(target, Mapping):
            if str(target.get("voice_type") or "official") == "official":
                raise ValueError(f"speaker_id 已登记为官方音色，不能改写为预付费槽位：{speaker_id}")
            if str(target.get("billing_mode") or "") == "postpaid_custom" or str(target.get("speaker_id") or "").strip() == CUSTOM_SPEAKER_PROTOCOL_ID:
                raise ValueError(f"speaker_id 已登记为后付费自定义音色，不能改写为预付费槽位：{speaker_id}")
            voice_key = str(target.get("voice_key") or "").strip()
            existing_tags = [str(tag).strip() for tag in (target.get("style_tags") or []) if str(tag).strip()]
            if "预付费槽位" not in existing_tags:
                existing_tags.append("预付费槽位")
            patch = {
                "display_name": str(row["display_name"]) if row.get("display_name_explicit") else str(target.get("display_name") or row["display_name"]),
                "voice_type": "custom",
                "billing_mode": "prepaid_slot",
                "slot_source": "console_prepaid",
                "speaker_id": speaker_id,
                "custom_speaker_id": "",
                "resource_id": "seed-icl-2.0",
                "model": DEFAULT_TTS_MODEL,
                "gender": str(row["gender"]),
                "languages": list(row["languages"]),
                "style_tags": existing_tags,
            }
            catalog = store.update(voice_key, patch)
            voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
            updated.append(voice_key)
            continue

        voice_key = f"prepaid_{hashlib.sha256(speaker_id.encode('utf-8')).hexdigest()[:12]}"
        existing_keys = {
            str(item.get("voice_key") or "")
            for item in voices
            if isinstance(item, Mapping)
        }
        while voice_key in existing_keys:
            voice_key += "_x"
        voice = {
            "voice_key": voice_key,
            "display_name": str(row["display_name"]),
            "provider": "volcengine",
            "voice_type": "custom",
            "billing_mode": "prepaid_slot",
            "slot_source": "console_prepaid",
            "speaker_id": speaker_id,
            "custom_speaker_id": "",
            "resource_id": "seed-icl-2.0",
            "model": DEFAULT_TTS_MODEL,
            "gender": str(row["gender"]),
            "languages": list(row["languages"]),
            "style_tags": ["预付费槽位"],
            # 导入只证明用户拥有/看到该槽位，不能伪造真实 TTS 验收。
            "enabled": True,
            "verified": False,
            "training_status": "slot_imported",
            "authorization_status": "console_slot",
            "preview_url": "",
        }
        catalog = store.register(voice)
        voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
        imported.append(voice_key)

    slots = [
        dict(item) for item in voices
        if isinstance(item, Mapping) and str(item.get("billing_mode") or "") == "prepaid_slot"
    ]
    return {
        "status": "ready",
        "action": "import_prepaid_voice_slots",
        "imported_count": len(imported),
        "updated_count": len(updated),
        "slot_count": len(slots),
        "imported_voice_keys": imported,
        "updated_voice_keys": updated,
        "slots": slots,
        "catalog": catalog,
        "message": "已有预付费/免费槽位已保存；不会购买槽位。上传音频时请选择槽位，上传动作只训练该 speaker_id。",
    }


def _official_voice_gender(value: object) -> str:
    text = str(value or "").strip().lower()
    if text in {"男", "male", "m"}:
        return "male"
    if text in {"女", "female", "f"}:
        return "female"
    return "neutral"


def _official_voice_languages(value: object) -> list[str]:
    languages: list[str] = []
    if isinstance(value, list):
        for item in value:
            if isinstance(item, Mapping):
                item = item.get("Language") or item.get("language")
            text = str(item or "").strip()
            if text:
                languages.append(text)
    return list(dict.fromkeys(languages)) or ["zh-CN"]


def _sync_official_voice_catalog(result: Mapping[str, object]) -> dict[str, object]:
    """把新版目录响应中的展示元数据合并到唯一目录；不会启用新音色。"""

    response = result.get("response") if isinstance(result.get("response"), Mapping) else {}
    provider_result = response.get("Result") if isinstance(response, Mapping) else {}
    speakers = provider_result.get("Speakers") if isinstance(provider_result, Mapping) else []
    if not isinstance(speakers, list):
        return {"listed_count": 0, "added_voice_keys": [], "updated_voice_keys": [], "catalog_written": False}
    store = _voice_catalog_store()
    catalog = store.load()
    voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
    by_speaker = {
        str(item.get("speaker_id") or "").strip(): item
        for item in voices
        if isinstance(item, Mapping) and str(item.get("speaker_id") or "").strip()
    }
    added: list[str] = []
    updated: list[str] = []
    for item in speakers:
        if not isinstance(item, Mapping):
            continue
        speaker_id = str(item.get("VoiceType") or item.get("SpeakerID") or item.get("speaker_id") or "").strip()
        if not speaker_id:
            continue
        resource_id = str(item.get("ResourceID") or item.get("resource_id") or "seed-tts-2.0").strip()
        # 官方目录当前只允许 TTS 1/2 资源；目录契约的第一版官方音色
        # 统一使用 seed-tts-2.0，避免把未知资源静默写成可调用音色。
        if resource_id != "seed-tts-2.0":
            continue
        display_name = str(item.get("Name") or item.get("name") or speaker_id).strip()[:80]
        language_values = _official_voice_languages(item.get("Languages") or item.get("languages"))
        labels: list[str] = []
        for key in ("NormalLabels", "SpecialLabels"):
            values = item.get(key)
            if isinstance(values, list):
                labels.extend(str(value).strip() for value in values if str(value).strip())
        existing = by_speaker.get(speaker_id)
        if isinstance(existing, Mapping):
            voice_key = str(existing.get("voice_key") or "").strip()
            patch: dict[str, object] = {
                "display_name": display_name,
                "provider": "volcengine",
                "voice_type": "official",
                "resource_id": resource_id,
                "languages": language_values,
                "gender": _official_voice_gender(item.get("Gender") or item.get("gender")),
            }
            if labels:
                patch["style_tags"] = labels
            trial = str(item.get("TrialURL") or item.get("trial_url") or "").strip()
            if trial.startswith(("http://", "https://")) and not str(existing.get("preview_url") or "").strip():
                patch["preview_url"] = trial
            store.update(voice_key, patch)
            updated.append(voice_key)
            continue
        voice_key = _official_voice_key(speaker_id)
        while any(str(entry.get("voice_key") or "") == voice_key for entry in voices if isinstance(entry, Mapping)):
            voice_key = f"{voice_key}_x"
        trial = str(item.get("TrialURL") or item.get("trial_url") or "").strip()
        voice = {
            "voice_key": voice_key,
            "display_name": display_name,
            "provider": "volcengine",
            "voice_type": "official",
            "speaker_id": speaker_id,
            "resource_id": resource_id,
            "model": DEFAULT_TTS_MODEL,
            "gender": _official_voice_gender(item.get("Gender") or item.get("gender")),
            "languages": language_values,
            "style_tags": labels,
            # provider 列表不等于当前账号已授权；新条目保持停用，需人工验证后启用。
            "enabled": False,
            "verified": False,
            "training_status": "listed",
            "authorization_status": "unknown",
            "preview_url": trial if trial.startswith(("http://", "https://")) else "",
        }
        store.register(voice)
        # 真实 VoiceCatalogStore 会在自己的快照上写入；测试/扩展实现也可能
        # 直接修改 load() 返回的列表，因此只在本地快照尚未出现时追加一次。
        if not any(
            isinstance(entry, Mapping) and str(entry.get("voice_key") or "") == voice_key
            for entry in voices
        ):
            voices.append(voice)
        by_speaker[speaker_id] = voice
        added.append(voice_key)
    return {
        "listed_count": len([item for item in speakers if isinstance(item, Mapping)]),
        "added_voice_keys": added,
        "updated_voice_keys": updated,
        "catalog_written": bool(added or updated),
    }


def _voice_catalog_list_official(payload: Mapping[str, object]) -> dict[str, object]:
    """读取本地已核验官方音色目录，不再调用旧版 OpenAPI 列表接口。"""

    if str(payload.get("confirm") or "").strip() != "readonly-voice-catalog-list":
        raise ValueError("官方音色列表查询需要 confirm=readonly-voice-catalog-list")
    catalog = _voice_catalog_store().load()
    voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
    official = [item for item in voices if isinstance(item, Mapping) and str(item.get("voice_type") or "") == "official"]
    return {
        "status": "ready",
        "evidence_level": "local_voice_catalog",
        "result": {
            "action": "local_catalog",
            "response": {"Result": {"Speakers": [
                {
                    "VoiceType": str(item.get("speaker_id") or ""),
                    "Name": str(item.get("display_name") or ""),
                    "Gender": str(item.get("gender") or "neutral"),
                    "Languages": list(item.get("languages") or []),
                    "ResourceID": str(item.get("resource_id") or "seed-tts-2.0"),
                    "TrialURL": str(item.get("preview_url") or ""),
                }
                for item in official
            ]}},
        },
        "catalog_sync": {
            "listed_count": len(official),
            "added_voice_keys": [],
            "updated_voice_keys": [],
            "catalog_written": False,
            "source": "local_catalog",
        },
    }


def _voice_clone_training_state(value: object) -> tuple[str, str]:
    """把新版 voice_clone/get_voice 的状态值归一为目录状态。"""

    raw = str(value if value is not None else "").strip()
    lowered = raw.lower()
    if lowered in {"2", "4", "success", "active", "ready"}:
        return ("Active" if lowered in {"4", "active"} else "Success", "active")
    if lowered in {"1", "training", "processing", "queued"}:
        return ("Training", "pending")
    if lowered in {"3", "failed", "error"}:
        return ("Failed", "failed")
    if lowered in {"0", "notfound", "unknown", ""}:
        return (raw or "Unknown", "pending")
    return (raw, "pending")


def _voice_clone_generate_custom_speaker_id() -> str:
    """生成符合新版 V3 规则且尽量避免本地目录冲突的后付费音色代号。

    新版接口要求后付费请求同时带固定的 ``speaker_id=custom_speaker_id``
    和一个客户维度唯一的 ``custom_speaker_id``。页面不再要求用户先找或
    手填平台 ID，因此由服务端在真正上传前生成代号，并在响应中返回给页面。
    """

    try:
        catalog = _voice_catalog_snapshot()
    except (RuntimeError, VoiceCatalogStoreError):
        catalog = {"voices": []}
    used = {
        effective_speaker_id(item)
        for item in (catalog.get("voices") or [])
        if isinstance(item, Mapping)
    }
    for _ in range(8):
        # V3 要求自定义代号以字母开头，且不能使用协议固定值
        # ``custom_speaker_id``；该格式也便于用户在状态查询时复制。
        candidate = f"custom_zh_{uuid.uuid4().hex}"
        if candidate not in used:
            return normalize_custom_speaker_id(candidate)
    raise ValueError("无法生成唯一 custom_speaker_id，请稍后重试")


def _voice_clone_prepaid_slot_candidates() -> list[dict[str, object]]:
    """返回可供用户选择的新版预付费/免费音色槽位。

    V3 的训练接口要求 ``speaker_id`` 必选；这里的目录只用于展示/选择
    用户已经开通的槽位，不会购买槽位，也不会替供应商生成新的 ID。
    """

    try:
        catalog = _voice_catalog_snapshot()
    except (RuntimeError, VoiceCatalogStoreError) as exc:
        raise ValueError(f"音色目录不可用，无法自动选择预付费槽位：{exc}") from exc
    rows: list[dict[str, object]] = []
    for item in catalog.get("voices", ()):
        if not isinstance(item, Mapping):
            continue
        provider_speaker_id = str(item.get("speaker_id") or "").strip()
        custom_speaker_id = str(item.get("custom_speaker_id") or "").strip()
        billing_mode = str(item.get("billing_mode") or "").strip().lower()
        slot_source = str(item.get("slot_source") or "").strip().lower()
        is_prepaid_slot = billing_mode == "prepaid_slot" or (
            str(item.get("voice_type") or "").strip().lower() == "custom"
            and not custom_speaker_id
            and slot_source in {"console_prepaid", "prepaid", "voice_clone_v3"}
        )
        if not is_prepaid_slot or not provider_speaker_id:
            continue
        if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
            continue
        if item.get("enabled") is False:
            continue
        # 官方文档说明启用/Active 后不能再次训练；其它状态（包括导入、
        # 训练成功或失败）仍可由用户决定是否重训。
        training_state = str(item.get("training_status") or "").strip().lower()
        if training_state in {"active", "enabled", "locked"}:
            continue
        rows.append(dict(item))

    # ``updated_at`` 是目录写入时的 UTC ISO 字符串。空值排在前面，之后
    # 选择最久未更新的槽位，避免连续无 ID 上传一直覆盖同一个槽位。
    rows.sort(key=lambda item: (str(item.get("updated_at") or ""), str(item.get("voice_key") or "")))
    return rows


def _voice_clone_resolve_prepaid_speaker_id(
    payload: Mapping[str, object], requested_speaker_id: str
) -> tuple[str, str, bool]:
    """解析普通/预付费音色目标。

    返回 ``(speaker_id, voice_key, auto_selected)``。显式传入的 ID 不要求
    已存在于本地目录，方便用户直接按官方 ID 更新；只有调用方明确传入
    本地 ``voice_key`` 时才读取目录做槽位一致性校验。该解析器用于已有
    音色训练/更新；首次创建的空 ``speaker_id`` 由上层按官方 V3 示例放行。
    """

    explicit_speaker_id = str(
        requested_speaker_id
        or payload.get("prepaid_slot_speaker_id")
        or ""
    ).strip()
    requested_voice_key = str(
        payload.get("prepaid_slot_voice_key")
        or payload.get("slot_voice_key")
        or ""
    ).strip()
    if requested_voice_key:
        candidates = _voice_clone_prepaid_slot_candidates()
        target = next(
            (item for item in candidates if str(item.get("voice_key") or "").strip() == requested_voice_key),
            None,
        )
        if target is None:
            raise ValueError("指定的预付费槽位不存在、已停用或已锁定；请重新选择可用槽位")
        slot_speaker_id = str(target.get("speaker_id") or "").strip()
        if explicit_speaker_id and explicit_speaker_id != slot_speaker_id:
            raise ValueError("speaker_id 与所选预付费槽位不一致")
        return slot_speaker_id, requested_voice_key, not bool(explicit_speaker_id)

    if explicit_speaker_id:
        # 官方返回/控制台复制的真实 ID 是权威值；本地目录只用于页面展示，
        # 不应成为直接更新请求的前置条件。
        return explicit_speaker_id, "", False

    raise ValueError(
        "已有预付费/免费音色训练或更新必须提供真实 speaker_id；"
        "首次创建请使用 prepaid_create 并留空 speaker_id。已有槽位无需再次购买"
    )


def _voice_clone_import_official_prepaid(payload: Mapping[str, object]) -> dict[str, object]:
    """核验并登记已由新版控制台创建的预付费音色。

    页面从用户刚在火山音色库复制的剪贴板读取 ``speaker_id``，本服务只用
    TTS 主 Key 调用新版 ``get_voice`` 做一次只读核验。只有供应商明确返回
    相同 ID 后才写入本地目录；不上传音频、不购买槽位，也不读取 AK/SK 或
    浏览器登录会话。
    """

    if str(payload.get("confirm") or "").strip() != "register-official-prepaid-voice":
        raise ValueError("登记官方预付费音色需要 confirm=register-official-prepaid-voice")
    speaker_id = str(payload.get("speaker_id") or "").strip()
    display_name = str(payload.get("display_name") or "").strip()[:80]
    if not speaker_id:
        raise ValueError("未从剪贴板读取到 speaker_id；请先在火山音色库点击复制音色 ID")
    if speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID or len(speaker_id) > 256 or any(
        char.isspace() or ord(char) < 32 for char in speaker_id
    ):
        raise ValueError("剪贴板中的 speaker_id 不合法；请从新版火山音色库重新复制")

    TASK_LOGGER.info("voice_clone stage=official_import status=started")
    _api_management_require_runtime_credentials(("tts",))
    try:
        result = _voice_clone_transport_from_page().query(speaker_id)
        returned_speaker_id = str(result.get("speaker_id") or "").strip()
        if not returned_speaker_id or returned_speaker_id != speaker_id:
            raise ValueError("新版 get_voice 未确认与剪贴板一致的 speaker_id，已拒绝登记")
        training_status, authorization_status = _voice_clone_training_state(result.get("status"))
        registered = _voice_clone_upsert_catalog(
            speaker_id=returned_speaker_id,
            display_name=display_name or returned_speaker_id,
            training_status=training_status,
            authorization_status=authorization_status,
            version="2.0",
            preview_url=str(result.get("demo_audio") or "").strip(),
            resource_id="seed-icl-2.0",
        )
        TASK_LOGGER.info(
            "voice_clone stage=official_import status=succeeded voice_key=%s training_status=%s",
            registered["voice_key"],
            training_status,
        )
        return {
            "status": "registered",
            "action": "get_voice",
            "speaker_id": returned_speaker_id,
            "training_status": training_status,
            "authorization_status": authorization_status,
            "voice_key": registered["voice_key"],
            "catalog": registered["catalog"],
            "provider": {
                "action": "get_voice",
                "speaker_id": returned_speaker_id,
                "status": result.get("status"),
                "training_status": result.get("training_status"),
                "demo_audio": result.get("demo_audio", ""),
            },
        }
    except (VoiceCloneError, VoiceCatalogStoreError, ValueError) as exc:
        TASK_LOGGER.warning("voice_clone stage=official_import status=failed error=%s", str(exc)[:300])
        raise ValueError(str(exc)) from exc


def _voice_clone_train(payload: Mapping[str, object]) -> dict[str, object]:
    """在新版 V3 中首次创建或训练预付费音色，并保留受控后付费模式。

    V3 的后付费协议允许客户端上传音频并使用
    ``speaker_id=custom_speaker_id`` + 客户自定义代号创建音色；本地页面在
    未填写代号时生成唯一 ``custom_speaker_id``。首次预付费创建按新版 V3
    官方示例允许空 ``speaker_id``，由已开通的额度分配音色并返回真实 ID；
    已有音色更新仍必须绑定真实槽位 ``speaker_id``。
    所有路径均只使用 TTS 主 API Key。
    """

    if str(payload.get("confirm") or "").strip() != "voice-clone-training":
        raise ValueError("声音复刻训练需要 confirm=voice-clone-training")
    display_name = str(payload.get("display_name") or "").strip()[:80]
    if not display_name:
        raise ValueError("声音复刻训练必须提供音色名称")
    requested_speaker_id = str(payload.get("speaker_id") or "").strip()
    requested_custom_speaker_id = str(payload.get("custom_speaker_id") or "").strip()
    prepaid_slot_voice_key = str(
        payload.get("prepaid_slot_voice_key")
        or payload.get("slot_voice_key")
        or ""
    ).strip()
    mode_hint = str(payload.get("mode") or payload.get("creation_mode") or "").strip().lower()
    supported_modes = {"postpaid_create", "prepaid_create", "prepaid_train", "prepaid_update"}
    if mode_hint not in supported_modes:
        raise ValueError("声音复刻操作方式仅支持 prepaid_create、prepaid_train、prepaid_update 或 postpaid_create")
    operation = mode_hint
    postpaid_create = operation == "postpaid_create"
    prepaid_create = operation == "prepaid_create"
    custom_speaker_id_generated = False
    if postpaid_create:
        if requested_speaker_id and requested_speaker_id != CUSTOM_SPEAKER_PROTOCOL_ID:
            raise ValueError("后付费自定义创建的 speaker_id 必须为固定值 custom_speaker_id")
        if requested_custom_speaker_id:
            requested_custom_speaker_id = normalize_custom_speaker_id(requested_custom_speaker_id)
        else:
            requested_custom_speaker_id = _voice_clone_generate_custom_speaker_id()
            custom_speaker_id_generated = True
        requested_speaker_id = CUSTOM_SPEAKER_PROTOCOL_ID
        prepaid_slot_voice_key = ""
        speaker_id_auto_selected = False
    elif prepaid_create:
        if requested_custom_speaker_id or requested_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
            raise ValueError("首次预付费槽位创建不能使用 custom_speaker_id")
        # 官方 V3 首次创建示例把 speaker_id 传空，由供应商在已开通的
        # 预付费/免费额度内分配并返回真实 ID；若用户明确选择已有槽位，
        # 则继续使用该真实 ID 训练，避免覆盖错误资源。
        if not requested_speaker_id and not prepaid_slot_voice_key:
            speaker_id_auto_selected = True
        else:
            requested_speaker_id, prepaid_slot_voice_key, speaker_id_auto_selected = (
                _voice_clone_resolve_prepaid_speaker_id(payload, requested_speaker_id)
            )
    else:
        if requested_custom_speaker_id or requested_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
            raise ValueError(
                "预付费/免费槽位训练不能使用 custom_speaker_id；请选择已有真实 speaker_id"
            )
        requested_speaker_id, prepaid_slot_voice_key, speaker_id_auto_selected = (
            _voice_clone_resolve_prepaid_speaker_id(payload, requested_speaker_id)
        )
    encoded = str(payload.get("audio_base64") or "").strip()
    if not encoded:
        raise ValueError("声音复刻训练必须提供音频文件")
    try:
        audio = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("音频文件不是合法的 Base64 数据") from exc
    if not audio:
        raise ValueError("音频文件不能为空")
    if len(audio) > MAX_AUDIO_BYTES:
        raise ValueError("音频文件不能超过 10MB")
    filename = str(payload.get("filename") or "").strip()
    audio_format = str(payload.get("audio_format") or Path(filename).suffix.lstrip(".") or "").lower()
    if not audio_format:
        raise ValueError("无法识别音频格式，请上传 wav、mp3、ogg、m4a、aac 或 pcm")
    _api_management_require_runtime_credentials(("tts",))
    upload_succeeded = False
    try:
        # 上传与创建都属于同一次新版 V3 voice_clone 写入；日志只记录阶段、
        # 模式、格式和字节数，不记录原始音频内容或任何鉴权值。
        TASK_LOGGER.info(
            "voice_clone stage=upload status=started mode=%s filename=%s format=%s bytes=%s",
            operation,
            Path(filename).name,
            audio_format,
            len(audio),
        )
        allow_provider_generated_speaker_id = bool(prepaid_create and not requested_speaker_id)
        train_kwargs: dict[str, object] = {
            "speaker_id": requested_speaker_id,
            "custom_speaker_id": requested_custom_speaker_id,
            "allow_provider_generated_speaker_id": allow_provider_generated_speaker_id,
            "language": int(payload.get("language") or 0),
            "reference_text": str(payload.get("reference_text") or "").strip(),
            "demo_text": str(payload.get("demo_text") or "").strip(),
            "enable_audio_denoise": bool(payload.get("enable_audio_denoise")),
            "disable_volume_normalization": bool(payload.get("disable_volume_normalization")),
        }
        result = _voice_clone_transport_from_page().train(audio, audio_format, **train_kwargs)
        upload_succeeded = True
        TASK_LOGGER.info(
            "voice_clone stage=upload status=succeeded mode=%s format=%s bytes=%s",
            operation,
            audio_format,
            len(audio),
        )
        returned_speaker_id = str(result.get("speaker_id") or "").strip()
        provider_speaker_id = str(
            result.get("provider_speaker_id") or returned_speaker_id or requested_speaker_id
        ).strip()
        returned_custom_speaker_id = str(result.get("custom_speaker_id") or "").strip()
        if postpaid_create:
            # Transport 已将后付费响应绑定为实际 custom_speaker_id；对兼容
            # 测试替身/代理响应，回退到本次请求生成的代号，但不接受空值。
            effective_speaker = returned_custom_speaker_id or (
                returned_speaker_id
                if returned_speaker_id and returned_speaker_id != CUSTOM_SPEAKER_PROTOCOL_ID
                else requested_custom_speaker_id
            )
            if returned_custom_speaker_id and returned_custom_speaker_id != requested_custom_speaker_id:
                raise ValueError("新版声音复刻返回的 custom_speaker_id 与请求目标不一致")
            catalog_provider_speaker_id = CUSTOM_SPEAKER_PROTOCOL_ID
            catalog_custom_speaker_id = effective_speaker
        else:
            effective_speaker = returned_speaker_id
            catalog_provider_speaker_id = provider_speaker_id or effective_speaker
            catalog_custom_speaker_id = ""
        if not effective_speaker:
            raise ValueError("新版声音复刻未返回或无法确认真实音色代号，已拒绝登记")
        provider_generated_speaker_id = allow_provider_generated_speaker_id
        if (
            not postpaid_create
            and requested_speaker_id
            and returned_speaker_id
            and returned_speaker_id != requested_speaker_id
        ):
            raise ValueError("新版声音复刻返回的 speaker_id 与请求目标不一致")
        training_status, authorization_status = _voice_clone_training_state(result.get("status"))
        registered = _voice_clone_upsert_catalog(
            speaker_id=catalog_provider_speaker_id,
            custom_speaker_id=catalog_custom_speaker_id,
            display_name=display_name,
            training_status=training_status,
            authorization_status=authorization_status,
            version="2.0",
            preview_url=str(result.get("demo_audio") or "").strip(),
            resource_id="seed-icl-2.0",
        )
        TASK_LOGGER.info(
            "voice_clone stage=create status=succeeded mode=%s voice_key=%s provider_speaker_id=%s custom_speaker_id=%s training_status=%s",
            operation,
            registered["voice_key"],
            catalog_provider_speaker_id,
            catalog_custom_speaker_id,
            training_status,
        )
        return {
            "status": "submitted",
            "action": "voice_clone",
            "speaker_id": effective_speaker,
            "provider_speaker_id": catalog_provider_speaker_id,
            "custom_speaker_id": catalog_custom_speaker_id,
            "requested_speaker_id": requested_speaker_id,
            "requested_custom_speaker_id": requested_custom_speaker_id,
            "prepaid_slot_voice_key": prepaid_slot_voice_key,
            "speaker_id_auto_selected": bool(speaker_id_auto_selected),
            "creation_mode": (
                "created" if (postpaid_create or prepaid_create) else ("updated" if operation == "prepaid_update" else "trained")
            ),
            "creation_variant": "postpaid_custom" if postpaid_create else "prepaid_slot",
            "custom_speaker_id_generated": bool(custom_speaker_id_generated),
            "speaker_id_generated_by_provider": provider_generated_speaker_id,
            "training_status": training_status,
            "authorization_status": authorization_status,
            "voice_key": registered["voice_key"],
            "catalog": registered["catalog"],
            "provider": {
                "action": "voice_clone",
                "speaker_id": returned_speaker_id,
                "provider_speaker_id": provider_speaker_id,
                "custom_speaker_id": returned_custom_speaker_id,
                "status": result.get("status"),
                "training_status": result.get("training_status"),
                "demo_audio": result.get("demo_audio", ""),
            },
        }
    except (VoiceCloneError, VoiceCatalogStoreError, ValueError) as exc:
        TASK_LOGGER.warning(
            "voice_clone stage=%s status=failed mode=%s error=%s",
            "create" if upload_succeeded else "upload",
            operation,
            str(exc)[:300],
        )
        raise ValueError(str(exc)) from exc


def _voice_clone_generated_key(display_name: str, speaker_id: str) -> str:
    """生成稳定且不含原始音频信息的本地 voice_key。"""

    label = re.sub(r"[^A-Za-z0-9_-]+", "_", str(display_name or "").strip()).strip("_").lower()
    label = label[:40]
    digest = hashlib.sha256(str(speaker_id).encode("utf-8")).hexdigest()[:10]
    return f"custom_{label or 'voice'}_{digest}"


def _voice_clone_upsert_catalog(
    *,
    speaker_id: str,
    custom_speaker_id: str = "",
    display_name: str,
    training_status: str,
    authorization_status: str,
    version: object = None,
    preview_url: str = "",
    resource_id: str = "",
) -> dict[str, object]:
    """登记或更新同一实际音色代号，保持 voice_key 不变。"""

    provider_speaker_id = str(speaker_id or "").strip()
    actual_speaker_id = str(custom_speaker_id or "").strip() or provider_speaker_id
    if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID:
        try:
            actual_speaker_id = normalize_custom_speaker_id(actual_speaker_id)
        except VoiceCatalogError as exc:
            raise VoiceCatalogStoreError(str(exc)) from exc
    if not provider_speaker_id or not actual_speaker_id:
        raise VoiceCatalogStoreError("登记音色必须提供 speaker_id 或 custom_speaker_id")
    store = _voice_catalog_store()
    catalog = store.load()
    voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
    target = next((item for item in voices if effective_speaker_id(item) == actual_speaker_id), None)
    previous_verified = bool(target.get("verified")) if isinstance(target, Mapping) else False
    previous_tags = {str(tag) for tag in (target.get("style_tags") or [])} if isinstance(target, Mapping) else set()
    same_version = not str(version or "").strip() or f"复刻版本 {str(version).strip()[:40]}" in previous_tags
    ready_state = str(training_status or "").strip().lower() in {"success", "active", "ready"}
    bound_resource_id = str(resource_id or "seed-icl-2.0").strip() or "seed-icl-2.0"
    if bound_resource_id not in CUSTOM_VOICE_RESOURCE_IDS:
        raise VoiceCatalogStoreError(
            "声音复刻状态返回了不受支持的 resource_id：" + bound_resource_id
        )
    resource_changed = isinstance(target, Mapping) and str(
        target.get("resource_id") or ""
    ).strip() not in {"", bound_resource_id}
    patch = {
        "display_name": str(display_name or "").strip()[:80] or speaker_id,
        "voice_type": "custom",
        "billing_mode": "postpaid_custom" if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID else "prepaid_slot",
        "slot_source": "voice_clone_v3",
        "speaker_id": provider_speaker_id,
        "custom_speaker_id": actual_speaker_id if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID else "",
        "resource_id": bound_resource_id,
        "model": "seed-tts-2.0-standard",
        "training_status": str(training_status or "Unknown"),
        "authorization_status": str(authorization_status or "pending"),
        "enabled": training_status in {"Success", "Active", "ready", "Ready"},
        # 状态轮询不应无条件抹掉已完成的真实 TTS 验收；若训练版本变化，
        # 通过 version 标签让新版本重新回到未验证状态。
        "verified": bool(previous_verified and ready_state and same_version and not resource_changed),
    }
    if resource_changed:
        # 资源版本变化意味着 TTS 请求契约变化；旧的真实验收不能继续证明
        # 新资源可用，且已生成时间轴必须由上层失效/重建流程处理。
        patch["enabled"] = False
    if version is not None and str(version).strip():
        patch["style_tags"] = [f"复刻版本 {str(version).strip()[:40]}"]
    if preview_url:
        patch["preview_url"] = str(preview_url).strip()
    if isinstance(target, Mapping):
        voice_key = str(target.get("voice_key") or "").strip()
        updated = store.update(voice_key, patch)
    else:
        voice_key = _voice_clone_generated_key(str(display_name), actual_speaker_id)
        voice = {
            "voice_key": voice_key,
            "display_name": patch["display_name"],
            "provider": "volcengine",
            "voice_type": "custom",
            "billing_mode": "postpaid_custom" if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID else "prepaid_slot",
            "slot_source": "voice_clone_v3",
            "speaker_id": provider_speaker_id,
            "custom_speaker_id": actual_speaker_id if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID else "",
            "resource_id": bound_resource_id,
            "model": "seed-tts-2.0-standard",
            "gender": "neutral",
            "languages": ["zh-CN"],
            "style_tags": [],
            "enabled": bool(patch["enabled"]),
            "verified": False,
            "training_status": patch["training_status"],
            "authorization_status": patch["authorization_status"],
            "preview_url": str(patch.get("preview_url") or ""),
        }
        updated = store.register(voice)
    return {
        "voice_key": voice_key,
        "catalog": updated,
        "training_status": patch["training_status"],
        "authorization_status": patch["authorization_status"],
        "speaker_id": provider_speaker_id,
        "custom_speaker_id": actual_speaker_id if provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID else "",
    }


def _voice_clone_primary_tts_transport() -> ArkTTSHTTPTransport:
    """构造仅使用 TTS 主 Key 的传输层（历史兼容 helper）。

    该 helper 目前不再被声音复刻试听调用；试听必须读取训练返回的
    ``demo_audio``。保留它是为了兼容尚未清理的旧内部调用/测试，正式
    声音复刻训练和查询不会通过此函数引入备用 Key；试听不调用 TTS。
    """

    # 8768 启动时会把 API 管理页密文注入 TTS 运行时；这里读取的
    # ``ARK_TTS_API_KEY`` 已是页面 TTS 主 Key。保留统一配置构造，避免
    # 试听链路引入第二套凭据或破坏现有 TTS 参数契约。
    config = ArkTTSConfig.from_env(allow_legacy_document=False)
    return ArkTTSHTTPTransport(
        replace(
            config,
            backup_api_key="",
            extra_api_keys=(),
            failover_strategy="primary_only",
        )
    )


def _voice_clone_preview(payload: Mapping[str, object]) -> dict[str, object]:
    """发布训练接口返回的 ``demo_audio``；绝不发起正式 TTS 合成。

    V3 训练/状态接口返回的试听地址约一小时有效。用户点击编导弹窗的
    “试听”后，本地把该短音频下载到受控目录，再用本地地址播放。试听
    不是生产验收，不得单独把音色标记为 ``verified``/``enabled``；真实
    TTS、实际时长、STT 和时间轴校验统一由 ``/api/voices/acceptance``
    完成。这样试听不会把后付费音色转正，也不会消耗 TTS 副 Key 或生成
    新的时间轴。
    """

    if str(payload.get("confirm") or "").strip() != "paid-voice-preview":
        raise ValueError("定制音色试听需要 confirm=paid-voice-preview")
    voice_key = str(payload.get("voice_key") or "").strip()
    if not voice_key:
        raise ValueError("试听必须提供 voice_key")
    voice = _resolve_voice_for_paid_preview(voice_key)
    TASK_LOGGER.info("voice_clone stage=preview status=started voice_key=%s", voice_key)
    try:
        preview_url, size = _voice_clone_download_demo_audio(
            str(voice.get("preview_url") or ""), voice_key
        )
        # 试听只登记可复用的本地 demo_audio 地址；不能把短试听误当作
        # 正式 TTS/STT 时间轴验收。verified/enabled 只能由下方受控闭环
        # 在全部步骤成功后一次性写入。
        _voice_catalog_store().update(
            voice_key,
            {
                "preview_url": preview_url,
            },
        )
        response = {
            "status": "ready",
            "voice_key": voice_key,
            "preview_url": preview_url,
            "preview_source": "voice_clone_demo_audio",
            "formal_tts_called": False,
            "verified": False,
            "enabled": False,
            "bytes": size,
        }
        TASK_LOGGER.info(
            "voice_clone stage=preview status=succeeded voice_key=%s bytes=%s",
            voice_key,
            size,
        )
        return response
    except (VoiceCatalogStoreError, OSError, ValueError) as exc:
        TASK_LOGGER.warning(
            "voice_clone stage=preview status=failed voice_key=%s error=%s",
            voice_key,
            str(exc)[:300],
        )
        raise ValueError(str(exc)) from exc


def _voice_acceptance_safe_name(voice_key: str) -> str:
    """把 voice_key 转成证据目录名，不允许用户输入形成路径穿越。"""

    label = re.sub(r"[^A-Za-z0-9_-]+", "_", str(voice_key or "").strip()).strip("_")
    return (label[:48] or "voice") + "-" + uuid.uuid4().hex[:12]


def _voice_acceptance_evidence_path(voice_key: str) -> Path:
    """创建一次性、受控的本地验收证据目录。"""

    root = VOICE_ACCEPTANCE_DIR.resolve()
    candidate = (root / _voice_acceptance_safe_name(voice_key)).resolve()
    try:
        candidate.relative_to(root)
    except ValueError as exc:  # pragma: no cover - safe-name 已限制字符
        raise ValueError("真实闭环验收证据目录无效") from exc
    candidate.mkdir(parents=True, exist_ok=False)
    return candidate


def _voice_acceptance_sanitize(value: object) -> object:
    """保存供应商摘要时移除凭据并把不可 JSON 类型变成短摘要。"""

    if isinstance(value, Mapping):
        sanitized: dict[str, object] = {}
        for key, item in value.items():
            name = str(key)
            folded = re.sub(r"[^a-z0-9]", "", name.lower())
            if any(marker in folded for marker in ("apikey", "accesskey", "secretkey", "authorization", "accesstoken", "token")):
                sanitized[name] = "<redacted>"
            else:
                sanitized[name] = _voice_acceptance_sanitize(item)
        return sanitized
    if isinstance(value, (list, tuple)):
        return [_voice_acceptance_sanitize(item) for item in value]
    if isinstance(value, (bytes, bytearray)):
        return f"<bytes:{len(value)}>"
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def _voice_acceptance_write_json(path: Path, value: object) -> None:
    """原子写入验收证据 JSON，避免服务中断留下半个文件。"""

    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
    try:
        temporary.write_text(
            json.dumps(_voice_acceptance_sanitize(value), ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        temporary.replace(path)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


def _voice_acceptance_timeline_validation(
    subtitle: Mapping[str, object],
    *,
    audio_duration_seconds: float,
) -> dict[str, object]:
    """校验 STT 字幕/分段镜头时间线没有越过实际音频边界。"""

    if not isinstance(subtitle, Mapping):
        raise ValueError("STT 返回结果不是对象，无法验收时间轴")
    try:
        groups, total = _require_capcut_stt_timelines({"subtitle": dict(subtitle)})
    except Exception as exc:
        raise ValueError(f"STT 字幕/镜头时间轴契约校验失败：{exc}") from exc
    try:
        duration = float(audio_duration_seconds)
    except (TypeError, ValueError) as exc:
        raise ValueError("实际音频时长不是有效秒数") from exc
    if not math.isfinite(duration) or duration <= 0:
        raise ValueError("实际音频时长必须是大于 0 的有限秒数")
    audio_end_us = int(round(duration * 1_000_000))
    # ffprobe 与剪映上传时长之间允许一个很小的序列化误差；超过 50ms
    # 就是字幕或镜头时间线越界，不能继续写入 verified。
    tolerance_us = TRANSITION_POINT_TOLERANCE_US
    total_end = int(total["end"])
    if total_end > audio_end_us + tolerance_us:
        raise ValueError(
            f"STT 总时间线超过实际音频时长：{total_end / 1_000_000:.3f}s > {duration:.3f}s"
        )
    captions = subtitle.get("captions")
    if not isinstance(captions, list) or not captions:
        raise ValueError("STT 未返回可验收字幕")
    previous_end = 0
    caption_windows: list[dict[str, object]] = []
    for index, raw in enumerate(captions, start=1):
        if not isinstance(raw, Mapping):
            raise ValueError(f"字幕[{index}] 不是对象")
        try:
            start = int(raw.get("start_us"))
            end = int(raw.get("end_us"))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"字幕[{index}] 时间不是整数微秒") from exc
        if start < 0 or end <= start:
            raise ValueError(f"字幕[{index}] 存在负数、倒序或空时间窗")
        if start < previous_end:
            raise ValueError(f"字幕[{index}] 与上一条字幕重叠或倒序")
        if end > audio_end_us + tolerance_us:
            raise ValueError(
                f"字幕[{index}] 超过实际音频时长：{end / 1_000_000:.3f}s > {duration:.3f}s"
            )
        previous_end = end
        caption_windows.append({
            "caption_id": str(raw.get("caption_id") or ""),
            "group_id": str(raw.get("group_id") or ""),
            "start_us": start,
            "end_us": end,
            "text": str(raw.get("text") or ""),
        })
    return {
        "status": "passed",
        "timeline_unit": "microseconds",
        "audio_duration_seconds": duration,
        "audio_duration_microseconds": audio_end_us,
        "tolerance_microseconds": tolerance_us,
        "group_timelines": groups,
        "total_timeline": total,
        "caption_count": len(caption_windows),
        "caption_windows": caption_windows,
        "no_negative": True,
        "no_reverse": True,
        "no_overlap": True,
        "groups_contiguous": True,
        "timeline_within_audio": True,
    }


def _voice_clone_acceptance(payload: Mapping[str, object]) -> dict[str, object]:
    """执行一次受控的 V3 定制音色真实闭环验收。

    该入口不上传训练样本，也不创建新的音色；上传/创建由编导弹窗的
    ``/api/voices/clone`` 完成。这里仅对已经登记且训练成功的音色执行：
    get_voice → demo_audio 试听 → 一次正式 TTS → 本地时长 → CapCut STT →
    时间轴校验。全部成功后才把目录标记为 verified/enabled。
    """

    if str(payload.get("confirm") or "").strip() != "voice-acceptance":
        raise ValueError("真实闭环验收需要 confirm=voice-acceptance")
    if payload.get("allow_external_write") is not True:
        raise ValueError("真实闭环验收必须明确确认 allow_external_write=true")
    if payload.get("write_local_evidence") is not True:
        raise ValueError("真实闭环验收必须明确确认 write_local_evidence=true")
    voice_key = str(payload.get("voice_key") or "").strip()
    if not voice_key or "/" in voice_key or "\\" in voice_key:
        raise ValueError("真实闭环验收必须提供合法 voice_key")
    acceptance_text = str(payload.get("text") or payload.get("acceptance_text") or "").strip()
    if not acceptance_text:
        raise ValueError("真实闭环验收必须提供一段 TTS 验收文本")
    if len(acceptance_text) > 300:
        raise ValueError("TTS 验收文本不能超过 300 个字符")

    evidence_dir: Path | None = None
    events: list[dict[str, object]] = []
    started_at = time.perf_counter()

    def log(stage: str, status: str, message: str, **details: object) -> None:
        event = {
            "timestamp": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "stage": stage,
            "status": status,
            "message": str(message),
            **{key: _voice_acceptance_sanitize(value) for key, value in details.items()},
        }
        events.append(event)
        if evidence_dir is not None:
            try:
                with (evidence_dir / "events.jsonl").open("a", encoding="utf-8", newline="\n") as stream:
                    stream.write(json.dumps(event, ensure_ascii=False) + "\n")
            except OSError:
                # 证据目录创建成功后，日志写入失败仍记录到服务日志；不把
                # 凭据或原始音频写入日志内容。
                pass
        TASK_LOGGER.info(
            "voice_acceptance voice_key=%s stage=%s status=%s message=%s",
            voice_key,
            stage,
            status,
            message,
        )

    try:
        evidence_dir = _voice_acceptance_evidence_path(voice_key)
        request_summary = {
            "schema_version": "voice-acceptance-v1",
            "voice_key": voice_key,
            "acceptance_text": acceptance_text,
            "confirm": "voice-acceptance",
            "allow_external_write": True,
            "write_local_evidence": True,
            "started_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "max_wait_seconds": VOICE_ACCEPTANCE_MAX_WAIT_SECONDS,
            "status_poll_interval_seconds": VOICE_ACCEPTANCE_STATUS_POLL_INTERVAL_SECONDS,
            "max_retries": VOICE_ACCEPTANCE_MAX_RETRIES,
            "policy": {
                "api_version": "v3",
                "voice_clone_credential": "tts_primary_x_api_key",
                "tts_failover": "primary_only_for_custom_voice",
                "legacy_credentials": False,
            },
        }
        _voice_acceptance_write_json(evidence_dir / "request_summary.json", request_summary)
        log("preflight", "started", "已通过确认门禁，开始真实闭环验收")

        catalog = _voice_catalog_snapshot()
        voice = next(
            (item for item in catalog.get("voices", ()) if isinstance(item, Mapping) and str(item.get("voice_key") or "") == voice_key),
            None,
        )
        if not isinstance(voice, Mapping):
            raise ValueError("未找到指定 voice_key；请先在编导弹窗上传并登记新版 V3 音色")
        if str(voice.get("voice_type") or "").strip().lower() != "custom":
            raise ValueError("真实闭环验收仅针对已登记的定制音色")
        provider_speaker_id = str(voice.get("speaker_id") or "").strip()
        custom_speaker_id = str(voice.get("custom_speaker_id") or "").strip()
        if custom_speaker_id and not provider_speaker_id:
            provider_speaker_id = CUSTOM_SPEAKER_PROTOCOL_ID
        if not provider_speaker_id or (provider_speaker_id == CUSTOM_SPEAKER_PROTOCOL_ID and not custom_speaker_id):
            raise ValueError("定制音色缺少可查询的 speaker_id/custom_speaker_id")

        if time.perf_counter() - started_at > VOICE_ACCEPTANCE_MAX_WAIT_SECONDS:
            raise ValueError("真实闭环验收已超过 15 分钟，按硬停止条件终止")
        log("voice_clone_status", "started", "正在用新版 V3 get_voice 查询训练状态")
        status_results: list[dict[str, object]] = []
        status_retry_count = 0
        last_status_error = ""
        query_result: Mapping[str, object] = {}
        status_result: Mapping[str, object] = {}
        while True:
            if time.perf_counter() - started_at >= VOICE_ACCEPTANCE_MAX_WAIT_SECONDS:
                raise ValueError("真实闭环验收已超过 15 分钟，按硬停止条件终止")
            try:
                current_status_result = _voice_clone_status_readonly({
                    "confirm": "readonly-voice-status",
                    "voices": [{"speaker_id": provider_speaker_id, "custom_speaker_id": custom_speaker_id}],
                })
                if not isinstance(current_status_result, Mapping):
                    raise ValueError("新版 V3 get_voice 返回结果不是对象")
                raw_results = current_status_result.get("results")
                current_query = (
                    raw_results[0]
                    if isinstance(raw_results, list)
                    and raw_results
                    and isinstance(raw_results[0], Mapping)
                    else {}
                )
                if not current_query:
                    raise ValueError("新版 V3 get_voice 未返回音色状态")
                status_result = current_status_result
                query_result = current_query
                status_results.append({
                    "training_status": str(
                        current_query.get("training_status")
                        or current_query.get("state")
                        or current_query.get("status")
                        or "Unknown"
                    ),
                    "demo_audio_present": bool(str(current_query.get("demo_audio") or "").strip()),
                })
                # 供应商状态 2/4（Success/Active）才允许进入试听与正式 TTS；
                # Training 是正常异步状态，不计入“重试”次数，只受 15 分钟
                # 总截止时间约束。其它状态按硬停止条件立即失败。
                raw_training_status = (
                    current_query.get("training_status")
                    or current_query.get("state")
                    or current_query.get("status")
                )
                training_status, authorization_status = _voice_clone_training_state(raw_training_status)
                normalized_training_status = str(training_status).strip().lower()
                if normalized_training_status in {"success", "active", "ready"}:
                    break
                if normalized_training_status in {"failed", "notfound", "unknown"}:
                    raise ValueError(f"音色训练状态不可用：{training_status}")
                if normalized_training_status != "training":
                    raise ValueError(f"音色训练状态不可用：{training_status}")
                remaining = VOICE_ACCEPTANCE_MAX_WAIT_SECONDS - (time.perf_counter() - started_at)
                if remaining <= 0:
                    raise ValueError("真实闭环验收已超过 15 分钟，按硬停止条件终止")
                log(
                    "voice_clone_status",
                    "waiting",
                    "音色仍在训练，按 10 秒间隔查询（最长 15 分钟）",
                    training_status=training_status,
                    remaining_seconds=round(remaining, 1),
                )
                time.sleep(min(VOICE_ACCEPTANCE_STATUS_POLL_INTERVAL_SECONDS, remaining))
            except Exception as exc:
                message = str(exc) or type(exc).__name__
                # Training 的等待不是错误；这里只对查询/响应异常计数。
                if "训练状态不可用：Training" not in message and "音色尚未完成训练" not in message:
                    if message == last_status_error or status_retry_count >= VOICE_ACCEPTANCE_MAX_RETRIES:
                        raise
                    last_status_error = message
                    status_retry_count += 1
                    log(
                        "voice_clone_status",
                        "retrying",
                        "新版 V3 get_voice 查询失败，执行唯一一次重试",
                        retry=status_retry_count,
                        error=message[:240],
                    )
                    continue
                raise
        _voice_acceptance_write_json(
            evidence_dir / "voice_clone_response_summary.json",
            {
                "status_result": status_result,
                "query": dict(query_result),
                "status_queries": status_results,
                "status_retry_count": status_retry_count,
            },
        )
        returned_custom = str(query_result.get("custom_speaker_id") or "").strip()
        returned_speaker = str(query_result.get("speaker_id") or query_result.get("provider_speaker_id") or "").strip()
        effective_expected = custom_speaker_id or provider_speaker_id
        effective_returned = returned_custom or returned_speaker
        if effective_returned and effective_returned != effective_expected:
            raise ValueError("get_voice 返回的音色代号与目录登记不一致，已停止验收")
        log("voice_clone_status", "succeeded", "新版 V3 get_voice 状态为可用", training_status=training_status)

        preview_source = str(query_result.get("demo_audio") or voice.get("preview_url") or "").strip()
        if not preview_source:
            raise ValueError("新版 V3 get_voice 未返回 demo_audio，无法完成试听")
        log("preview", "started", "正在下载训练返回的 demo_audio 试听")
        local_preview_url, preview_bytes = _voice_clone_download_demo_audio(preview_source, voice_key)
        log("preview", "succeeded", "试听音频已保存到本地", preview_url=local_preview_url, bytes=preview_bytes)

        if time.perf_counter() - started_at > VOICE_ACCEPTANCE_MAX_WAIT_SECONDS:
            raise ValueError("真实闭环验收已超过 15 分钟，按硬停止条件终止")
        log("tts", "started", "正在用登记的定制音色调用一次新版 V3 TTS")
        tts_voice = dict(voice)
        tts_voice["speaker_id"] = provider_speaker_id
        tts_voice["provider_speaker_id"] = provider_speaker_id
        tts_voice["training_status"] = training_status
        tts_voice["authorization_status"] = authorization_status
        tts_voice["preview_url"] = local_preview_url
        tts_output_dir = evidence_dir / "tts"
        tts_result = generate_tts(
            {"voice_key": voice_key, "shots": [{"narration_text": acceptance_text}]},
            _runtime_auth_document(),
            tts_output_dir,
            voice_override=tts_voice,
        )
        tts_contract = _tts_contract_view(tts_result)
        audio_paths = tts_contract.get("audio", {}).get("paths") if isinstance(tts_contract.get("audio"), Mapping) else []
        if not isinstance(audio_paths, list) or len(audio_paths) != 1:
            raise ValueError("真实 TTS 未返回恰好一个本地音频文件")
        audio_path = Path(str(audio_paths[0])).expanduser().resolve()
        if not audio_path.is_file() or audio_path.stat().st_size <= 0:
            raise ValueError("真实 TTS 音频未实际落盘")
        # 即使 generate_tts 已记录 duration，这里仍对最终落盘文件再跑一次
        # ffprobe，确保验收时间轴不使用供应商响应 duration。
        actual_duration_seconds = float(_probe_written_audio_duration(audio_path))
        if not math.isfinite(actual_duration_seconds) or actual_duration_seconds <= 0:
            raise ValueError("ffprobe 未返回有效的真实音频时长")
        _voice_acceptance_write_json(
            evidence_dir / "tts_response_summary.json",
            {
                "tts_result": tts_result,
                "audio_path": str(audio_path),
                "audio_bytes": audio_path.stat().st_size,
                "actual_duration_seconds": actual_duration_seconds,
                "voice_key": voice_key,
                "speaker_id": tts_voice.get("speaker_id"),
                "provider_speaker_id": provider_speaker_id,
                "custom_speaker_id": custom_speaker_id,
            },
        )
        log("tts", "succeeded", "真实 TTS 音频已落盘并由 ffprobe 读取时长", audio_path=str(audio_path), duration_seconds=actual_duration_seconds)

        if time.perf_counter() - started_at > VOICE_ACCEPTANCE_MAX_WAIT_SECONDS:
            raise ValueError("真实闭环验收已超过 15 分钟，按硬停止条件终止")
        log("stt", "started", "正在把真实 TTS 音频送入 CapCut STT")
        subtitle = run_live_subtitle_pipeline({
            "director_output": {"segments": [acceptance_text]},
            "tts": tts_result,
        })
        _voice_acceptance_write_json(evidence_dir / "stt_response_summary.json", subtitle)
        log("stt", "succeeded", "CapCut STT 已返回字幕和分段时间线", caption_count=subtitle.get("caption_count") or len(subtitle.get("captions") or []))

        timeline_validation = _voice_acceptance_timeline_validation(
            subtitle,
            audio_duration_seconds=actual_duration_seconds,
        )
        _voice_acceptance_write_json(evidence_dir / "timeline_validation.json", timeline_validation)
        log("timeline", "succeeded", "字幕与镜头时间轴通过首尾、顺序、重叠和音频边界校验")

        # 只有正式 TTS、实际时长、STT 和时间轴全部通过，才允许写入本地
        # verified/enabled；试听和只读状态查询均不能触发这两个字段。
        catalog_patch = {
            "preview_url": local_preview_url,
            "training_status": training_status,
            "authorization_status": authorization_status,
            "verified": True,
            "enabled": True,
        }
        updated_catalog = _voice_catalog_store().update(voice_key, catalog_patch)
        log("catalog", "succeeded", "完整闭环通过，已登记 verified/enabled")
        acceptance_result = {
            "status": "succeeded",
            "evidence_level": "live_external_voice_acceptance",
            "voice_key": voice_key,
            "speaker_id": custom_speaker_id or provider_speaker_id,
            "provider_speaker_id": provider_speaker_id,
            "custom_speaker_id": custom_speaker_id,
            "preview_url": local_preview_url,
            "audio_path": str(audio_path),
            "actual_duration_seconds": actual_duration_seconds,
            "captions": subtitle.get("captions", []),
            "timeline_validation": timeline_validation,
            "catalog": updated_catalog,
            "evidence_dir": str(evidence_dir),
            "events_path": str(evidence_dir / "events.jsonl"),
            "elapsed_ms": round((time.perf_counter() - started_at) * 1000, 1),
        }
        _voice_acceptance_write_json(evidence_dir / "acceptance_result.json", acceptance_result)
        return acceptance_result
    except Exception as exc:
        message = str(exc) or type(exc).__name__
        log("acceptance", "failed", message)
        if evidence_dir is not None:
            try:
                _voice_acceptance_write_json(
                    evidence_dir / "acceptance_result.json",
                    {
                        "status": "blocked_or_failed",
                        "voice_key": voice_key,
                        "error": message,
                        "evidence_dir": str(evidence_dir),
                        "events_path": str(evidence_dir / "events.jsonl"),
                        "elapsed_ms": round((time.perf_counter() - started_at) * 1000, 1),
                    },
                )
            except OSError:
                pass
        if isinstance(exc, ValueError):
            raise
        raise ValueError(message) from exc


def _sync_voice_catalog_statuses(result: Mapping[str, object]) -> dict[str, object]:
    """将只读接口返回的状态同步到本地目录，不改变供应商资源。"""

    response = result.get("response") if isinstance(result.get("response"), Mapping) else {}
    provider_result = response.get("Result") if isinstance(response, Mapping) else {}
    statuses = provider_result.get("Statuses") if isinstance(provider_result, Mapping) else []
    if not isinstance(statuses, list):
        return {"updated_voice_keys": [], "status_count": 0, "catalog_written": False}
    catalog = _voice_catalog_store().load()
    voices = catalog.get("voices") if isinstance(catalog.get("voices"), list) else []
    by_speaker = {
        effective_speaker_id(item): item
        for item in voices
        if isinstance(item, Mapping) and effective_speaker_id(item)
    }
    # 预付费/旧版目录仍可能按 provider speaker_id 查询；后付费固定值
    # 不作为唯一键，避免多个自定义音色互相覆盖。
    for item in voices:
        provider_id = str(item.get("speaker_id") or "").strip() if isinstance(item, Mapping) else ""
        if provider_id and provider_id != CUSTOM_SPEAKER_PROTOCOL_ID:
            by_speaker.setdefault(provider_id, item)
    state_to_auth = {
        "active": "active", "success": "ready", "training": "pending",
        "failed": "failed", "notfound": "unknown", "unknown": "unknown",
        "expired": "expired", "reclaimed": "reclaimed",
    }
    updated: list[str] = []
    for item in statuses:
        if not isinstance(item, Mapping):
            continue
        custom_speaker_id = str(item.get("CustomSpeakerID") or item.get("custom_speaker_id") or "").strip()
        speaker_id = str(item.get("SpeakerID") or item.get("speaker_id") or "").strip()
        lookup_id = custom_speaker_id or speaker_id
        voice = by_speaker.get(lookup_id)
        if voice is None:
            continue
        # 新版 get_voice 返回状态和试听地址；资源版本固定按训练接口使用
        # seed-icl-2.0，避免把未知值写入目录后再被 TTS 使用。
        resource_id = str(item.get("ResourceID") or item.get("resource_id") or "seed-icl-2.0").strip()
        if resource_id in CUSTOM_VOICE_RESOURCE_IDS and str(voice.get("voice_type") or "custom") == "custom":
            if str(voice.get("resource_id") or "").strip() != resource_id:
                voice["resource_id"] = resource_id
                # 资源版本变化后，旧 TTS 试听不能证明新资源；重新验证前
                # 不允许普通编导选择该音色。
                voice["verified"] = False
                voice["enabled"] = False
        state = str(item.get("State") or item.get("state") or "Unknown").strip()
        if state:
            voice["training_status"] = state
            voice["authorization_status"] = state_to_auth.get(state.lower(), state.lower())
        demo_audio = str(item.get("DemoAudio") or item.get("demo_audio") or "").strip()
        if demo_audio.startswith(("http://", "https://")):
            voice["preview_url"] = demo_audio
        if custom_speaker_id and str(voice.get("speaker_id") or "").strip() == CUSTOM_SPEAKER_PROTOCOL_ID:
            voice["custom_speaker_id"] = custom_speaker_id
        updated.append(str(voice.get("voice_key") or ""))
    updated = list(dict.fromkeys(item for item in updated if item))
    if updated:
        _voice_catalog_store().save(catalog)
    return {"updated_voice_keys": updated, "status_count": len(statuses), "catalog_written": bool(updated)}


def _api_management_controlled_auth_verify(payload: Mapping[str, object]) -> dict[str, object]:
    if str(payload.get("confirm") or "").strip() != "controlled-auth-verification":
        raise ValueError("受控鉴权验证需要 confirm=controlled-auth-verification")
    default_channels = ("story-writing", "director-seed21", "tts", "audio-storage")
    raw_channels = payload.get("channels")
    if raw_channels is None:
        channel_ids = list(default_channels)
    elif isinstance(raw_channels, (list, tuple)):
        channel_ids = list(dict.fromkeys(str(value).strip() for value in raw_channels if str(value).strip()))
    else:
        raise ValueError("channels 必须是字符串数组")
    allowed_channels = {str(item.get("id") or "") for item in API_MANAGEMENT_CHANNELS}
    unknown = [value for value in channel_ids if value not in allowed_channels]
    if unknown:
        raise ValueError("存在未登记的 API 通道：" + ", ".join(unknown))
    snapshot = _api_management_snapshot()
    channels = {
        str(channel.get("id") or ""): channel
        for group in snapshot.get("groups", ())
        if isinstance(group, Mapping)
        for channel in group.get("channels", ())
        if isinstance(channel, Mapping) and str(channel.get("id") or "").strip()
    }
    results: list[dict[str, object]] = []
    secret_health = _api_management_secret_health_snapshot()
    secret_unreadable = str(secret_health.get("state") or "") == "unreadable"
    for channel_id in channel_ids:
        channel = channels.get(channel_id)
        if channel is None:
            results.append({
                "channel_id": channel_id,
                "status": "config_error",
                "auth_verified": False,
                "message": "当前页面配置中未找到该 API 通道",
            })
        elif secret_unreadable and _api_management_channel_base_id(channel_id) in API_MANAGEMENT_SECRET_RUNTIME:
            results.append({
                **_api_management_channel_context(channel),
                "scope": str(channel.get("name") or channel_id),
                "status": "config_error",
                "auth_verified": False,
                "credential_source": "page_secret_unreadable",
                "message": str(secret_health.get("message") or "本机加密 API 凭据无法读取")
                + "；未回退鉴权文档或环境变量",
            })
        elif channel_id == "story-writing":
            # The optional internal backup credential is a second credential
            # layer.  It is not required when the primary language-model API
            # exposes model/endpoint fallbacks (including Mini); those slots
            # are verified below with the primary key.
            results.extend(_api_management_verify_story_channel(channel))
        elif channel_id == "director-seed21":
            if channel_id in API_MANAGEMENT_INTERNAL_BACKUP_CHANNELS and not bool(
                (channel.get("secret_status") or {}).get("backup_api_key")
            ):
                results.append({
                    **_api_management_channel_context(channel),
                    "scope": "内部备用 API Key",
                    "status": "config_error",
                    "auth_verified": False,
                    "credential_source": "page_secret_missing",
                    "message": "页面未配置内部备用 API Key；已阻止旧鉴权文档/环境变量回退",
                })
            results.extend(_api_management_verify_director_channel(channel))
        elif channel_id == "tts":
            if channel_id in API_MANAGEMENT_INTERNAL_BACKUP_CHANNELS and not bool(
                (channel.get("secret_status") or {}).get("backup_api_key")
            ):
                results.append({
                    **_api_management_channel_context(channel),
                    "scope": "内部备用 API Key",
                    "status": "config_error",
                    "auth_verified": False,
                    "credential_source": "page_secret_missing",
                    "message": "页面未配置内部备用 API Key；已阻止旧鉴权文档/环境变量回退",
                })
            results.extend(_api_management_verify_tts_channel(channel))
        elif channel_id == "audio-storage":
            results.extend(_api_management_verify_tos_channel(channel))
        else:
            results.append(_api_management_not_checked(
                channel,
                "该通道需要创建生图、视频、数字人或 BGM 任务；本轮为避免产生付费任务，暂不自动调用。",
            ))
    checked = [item for item in results if item.get("status") != "not_checked"]
    summary = {
        "total": len(results),
        "passed": sum(item.get("status") == "passed" for item in results),
        "auth_failed": sum(item.get("status") == "auth_failed" for item in results),
        "rate_limited": sum(item.get("status") == "rate_limited" for item in results),
        "provider_rejected": sum(item.get("status") == "provider_rejected" for item in results),
        "network_error": sum(item.get("status") == "network_error" for item in results),
        "config_error": sum(item.get("status") == "config_error" for item in results),
        "provider_response_invalid": sum(item.get("status") == "provider_response_invalid" for item in results),
        "not_checked": sum(item.get("status") == "not_checked" for item in results),
        "auth_verified": sum(bool(item.get("auth_verified")) for item in checked),
    }
    return {
        "mode": "controlled_live",
        "status": "completed",
        "message": "受控鉴权验证已完成；未创建生图、视频、数字人或 BGM 任务。",
        "verified_channels": channel_ids,
        "summary": summary,
        "results": results,
        "generated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
    }


def _api_management_controlled_subtitle_verify(payload: Mapping[str, object]) -> dict[str, object]:
    """用真实字幕 Mini transport 验证 API1/API2 顺序，不创建编辑任务。"""

    if str(payload.get("confirm") or "").strip() != "controlled-subtitle-verification":
        raise ValueError("字幕 Mini 业务验收需要 confirm=controlled-subtitle-verification")
    _api_management_require_runtime_credentials(("story-writing", "director-seed21"))
    transport = _subtitle_correction_transport_from_runtime()
    corrected, report = transport.correct([
        {
            "caption_id": "governance.001",
            "group_id": "governance",
            "text": "治理验收测试文本",
            "reference_text": "治理验收测试文本",
            "start_us": 0,
            "end_us": 1_000_000,
        }
    ])
    failed_attempts = [
        {
            "provider": str(item.get("provider") or ""),
            "reason": str(item.get("reason") or ""),
        }
        for item in (report.get("failed_attempts") or [])
        if isinstance(item, Mapping)
    ]
    return {
        "mode": "controlled_business",
        "status": "completed",
        "message": "字幕 Mini 真实业务验收完成；未创建剪辑、视频或付费任务。",
        "provider": str(report.get("provider") or ""),
        "model_id": str(report.get("model_id") or ""),
        "model_name": str(report.get("model_name") or ""),
        "attempt": int(report.get("attempt") or 0),
        "failover": bool(report.get("failover")),
        "failed_attempts": failed_attempts,
        "caption_count": len(corrected),
        "credential_source": _api_management_effective_credential_source(),
        "generated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
    }


def _api_management_save_config(payload: Mapping[str, object]) -> dict[str, object]:
    group_id = str(payload.get("group_id") or "").strip()
    config = _api_management_load_config()
    group = next((item for item in API_MANAGEMENT_GROUPS if str(item.get("id") or "") == group_id), None)
    if group is None:
        channel = next((item for item in API_MANAGEMENT_CHANNELS if str(item.get("id") or "") == group_id), None)
        if channel is None:
            raise ValueError("API 类型不存在")
        group = next(
            (item for item in API_MANAGEMENT_GROUPS if group_id in tuple(item.get("channel_ids", ()))),
            None,
        )
        if group is None:
            raise ValueError("API 通道未归类")
        channel_id = group_id
    else:
        channel_id = str(payload.get("channel_id") or "").strip()
        if not channel_id:
            channel_ids = tuple(str(item) for item in group.get("channel_ids", ()) if str(item).strip())
            if group_id in channel_ids and len(channel_ids) > 1:
                # 兼容旧页面直接以通道 id 保存的请求，例如旧版 video-generation。
                channel_id = group_id
            elif len(channel_ids) == 1:
                channel_id = channel_ids[0]
            else:
                raise ValueError("多通道 API 类型必须指定调用通道")
    channel_specs = {
        str(item.get("id") or ""): item
        for item in _api_management_group_channel_specs(group, config)
    }
    new_channel_definition: dict[str, str] | None = None
    if channel_id not in channel_specs:
        raw_definition = payload.get("channel_definition")
        if not _api_management_is_custom_channel_id(channel_id) or not isinstance(raw_definition, Mapping):
            raise ValueError("调用通道不属于当前 API 类型")
        base_channel_id = str(raw_definition.get("base_channel_id") or "").strip()
        base_channel_ids = {str(item).strip() for item in group.get("channel_ids", ()) if str(item).strip()}
        if base_channel_id not in base_channel_ids or _api_management_channel_base_id(channel_id) != base_channel_id:
            raise ValueError("新增 API 配置组的基础通道无效")
        label = str(raw_definition.get("label") or "").strip()[:80]
        if not label:
            label = f"{base_channel_id} · 新增 API"
        existing_definitions = config.get("api_channels") if isinstance(config, Mapping) else {}
        existing_definitions = existing_definitions if isinstance(existing_definitions, Mapping) else {}
        existing_for_group = existing_definitions.get(group_id, [])
        existing_ids = {
            str(item.get("id") or "").strip()
            for item in existing_for_group
            if isinstance(item, Mapping)
        } if isinstance(existing_for_group, (list, tuple)) else set()
        if channel_id in existing_ids:
            raise ValueError("新增 API 配置组编号已存在，请重新点击 +")
        base_channel = next(
            (item for item in API_MANAGEMENT_CHANNELS if str(item.get("id") or "") == base_channel_id),
            None,
        )
        if base_channel is None:
            raise ValueError("新增 API 配置组的基础通道不存在")
        channel = dict(base_channel)
        channel["id"] = channel_id
        channel["base_channel_id"] = base_channel_id
        channel["is_custom_channel"] = True
        channel["credential_name"] = label
        channel_specs[channel_id] = channel
        new_channel_definition = {
            "id": channel_id,
            "base_channel_id": base_channel_id,
            "label": label,
        }
    channel = channel_specs.get(channel_id)
    if channel is None:
        raise ValueError("API 调用通道不存在")
    if payload.get("delete_channel") is True:
        groups = dict(config.get("groups") or {})
        groups.pop(channel_id, None)
        config["groups"] = groups
        if channel.get("is_custom_channel"):
            api_channels = dict(config.get("api_channels") or {})
            definitions = api_channels.get(group_id, [])
            if isinstance(definitions, (list, tuple)):
                api_channels[group_id] = [
                    dict(item) for item in definitions
                    if isinstance(item, Mapping) and str(item.get("id") or "") != channel_id
                ]
            config["api_channels"] = api_channels
        else:
            removed_channels = dict(config.get("removed_channels") or {})
            removed_for_group = removed_channels.get(group_id, [])
            removed_for_group = list(removed_for_group) if isinstance(removed_for_group, (list, tuple)) else []
            if channel_id not in removed_for_group:
                removed_for_group.append(channel_id)
            removed_channels[group_id] = removed_for_group
            config["removed_channels"] = removed_channels
            api_functions = dict(config.get("api_functions") or {})
            function_settings = api_functions.get(group_id)
            if isinstance(function_settings, Mapping):
                removed_function_ids = {
                    str(node.get("id") or "")
                    for node in channel.get("nodes", ())
                    if isinstance(node, Mapping)
                }
                api_functions[group_id] = {
                    str(function_id): value
                    for function_id, value in function_settings.items()
                    if str(function_id) not in removed_function_ids
                }
                config["api_functions"] = api_functions
        api_groups = dict(config.get("api_groups") or {})
        group_failover = api_groups.get(group_id)
        if isinstance(group_failover, Mapping):
            group_failover = dict(group_failover)
            group_failover["order"] = [
                str(value) for value in group_failover.get("order", ())
                if str(value) != channel_id
            ]
            api_groups[group_id] = group_failover
            config["api_groups"] = api_groups
        _api_management_delete_secrets(channel_id)
        _api_management_write_config(config)
        _api_management_apply_runtime_config(config)
        return _api_management_snapshot()
    effective_group = dict(group)
    # 保存 API 顺序时只接受可实际发起业务请求的通道；管理通道
    # （如声音复刻状态同步）仍可单独保存自身参数，但不会成为 TTS 的
    # 备用 API 或影响合成可用性。
    effective_group["channel_ids"] = tuple(
        channel_id
        for channel_id, channel in channel_specs.items()
        if not channel.get("management_only")
    ) or tuple(channel_specs)
    raw_settings = payload.get("settings")
    if not isinstance(raw_settings, Mapping):
        raise ValueError("settings 必须是对象")
    raw_secrets = payload.get("secrets") or {}
    if not isinstance(raw_secrets, Mapping):
        raise ValueError("secrets 必须是对象")
    raw_group_settings = payload.get("group_settings") or {}
    if not isinstance(raw_group_settings, Mapping):
        raise ValueError("group_settings 必须是对象")
    base_channel_id = _api_management_channel_base_id(channel_id)
    raw_resource_secrets = payload.get("resource_secrets") or {}
    if not isinstance(raw_resource_secrets, Mapping):
        raise ValueError("resource_secrets 必须是对象")
    raw_resource_settings = raw_settings.get("resource_management")
    if raw_resource_settings is None and isinstance(payload.get("resource_settings"), Mapping):
        raw_resource_settings = payload.get("resource_settings")
    if base_channel_id == "voice-clone-admin":
        # 新版 V3 声音复刻只保存固定地址/超时；任何旧版资源控制面字段
        # （AK/SK、AppID、ProjectName、槽位或 resource_management）都直接
        # 拒绝，避免废弃配置重新进入当前运行时。
        legacy_settings = sorted(
            key for key in raw_settings
            if str(key) in {
                "region", "app_id", "primary_model", "backup_model", "model_slots",
                "model_names", "model_order", "strategy", "project_name", "service", "version",
            }
        )
        legacy_secret_fields = sorted(
            key for key in raw_secrets
            if str(key) in {"access_key", "secret_key", "resource_access_key", "resource_secret_key", "access_token", "app_id"}
        )
        if legacy_settings or legacy_secret_fields or raw_resource_settings not in (None, {}) or raw_resource_secrets:
            fields = ", ".join(str(key) for key in (legacy_settings or legacy_secret_fields))
            detail = f"（字段：{fields}）" if fields else ""
            raise ValueError(
                "新版声音复刻只接受固定 v3 地址和超时，不接受旧版 AppID/AK/SK、"
                f"区域、ProjectName、槽位或 resource_management{detail}；请在编导弹窗按新版规则上传音频"
            )
        if raw_secrets:
            raise ValueError(
                "新版声音复刻不接受独立密钥；训练和查询复用 TTS 主 API Key，试听只读取训练返回的 demo_audio"
            )
        raw_settings = {
            str(key): value
            for key, value in raw_settings.items()
            if str(key) in {"endpoint", "timeout_seconds"}
        }
    elif raw_resource_settings is not None or raw_resource_secrets:
        raise ValueError("旧版音色资源管理设置已移除；请从编导弹窗使用新版 V3 voice_clone")
    normalized_api_failover: dict[str, object] | None = None
    normalized_function_settings: dict[str, dict[str, object]] | None = None
    if "api_failover" in raw_group_settings:
        raw_api_failover = raw_group_settings.get("api_failover")
        if not isinstance(raw_api_failover, Mapping):
            raise ValueError("api_failover 必须是对象")
        normalized = _api_management_normalize_group_failover(effective_group, raw_api_failover, strict=True)
        normalized_api_failover = {
            "order": list(normalized["order"]),
        }
    if "function_settings" in payload:
        raw_function_settings = payload.get("function_settings")
        if not isinstance(raw_function_settings, Mapping):
            raise ValueError("function_settings 必须是对象")
        group_channel_ids = {
            str(item).strip()
            for item in group.get("channel_ids", ())
            if str(item).strip()
        }
        valid_function_ids = {
            str(node.get("id") or "").strip()
            for candidate in API_MANAGEMENT_CHANNELS
            if str(candidate.get("id") or "") in group_channel_ids
            for node in candidate.get("nodes", ())
            if isinstance(node, Mapping) and str(node.get("id") or "").strip()
        }
        normalized_function_settings = {}
        for raw_function_id, raw_function_config in raw_function_settings.items():
            function_id = str(raw_function_id or "").strip()
            if function_id not in valid_function_ids:
                raise ValueError("功能降级配置包含不属于当前 API 类型的功能节点")
            if not isinstance(raw_function_config, Mapping):
                raise ValueError("功能降级配置必须是对象")
            normalized = _api_management_normalize_function_failover(raw_function_config, strict=True)
            normalized_function_settings[function_id] = {
                "priority": str(normalized["priority"]),
            }
    if any(key in raw_settings for key in ("api_key", "primary_api_key", "backup_api_key", "secret_key")):
        raise ValueError("密钥不通过此接口保存；请继续使用现有环境变量或鉴权文档")
    allowed = {"endpoint", "region", "app_id", "primary_model", "backup_model", "model_slots", "model_names", "model_order", "strategy", "max_attempts", "timeout_seconds", "quality"}
    settings: dict[str, object] = {}
    for key, value in raw_settings.items():
        if key not in allowed:
            continue
        if key == "model_slots":
            if not isinstance(value, Mapping):
                raise ValueError("model_slots 必须是对象")
            allowed_sources = _api_management_model_env_names(channel_id)
            normalized_slots: dict[str, str] = {}
            for source, model_value in value.items():
                source_name = str(source).strip()
                if source_name not in allowed_sources and not _api_management_is_custom_model_source(source_name):
                    raise ValueError("模型槽位不属于当前 API 通道")
                normalized_slots[source_name] = str(model_value or "").strip()
            if len(normalized_slots) > 64:
                raise ValueError("单个 API 最多保存 64 个模型槽位")
            settings[key] = normalized_slots
            continue
        if key == "model_names":
            if not isinstance(value, Mapping):
                raise ValueError("model_names 必须是对象")
            allowed_sources = _api_management_model_env_names(channel_id)
            normalized_names: dict[str, str] = {}
            for source, model_name in value.items():
                source_name = str(source).strip()
                if source_name not in allowed_sources and not _api_management_is_custom_model_source(source_name):
                    raise ValueError("模型名称槽位不属于当前 API 通道")
                normalized_names[source_name] = str(model_name or "").strip()
            if len(normalized_names) > 64:
                raise ValueError("单个 API 最多保存 64 个模型名称")
            settings[key] = normalized_names
            continue
        if key == "model_order":
            if not isinstance(value, (list, tuple)):
                raise ValueError("model_order 必须是数组")
            allowed_sources = _api_management_model_env_names(channel_id)
            normalized_order: list[str] = []
            for source in value:
                source_name = str(source or "").strip()
                if not source_name:
                    continue
                if source_name not in allowed_sources and not _api_management_is_custom_model_source(source_name):
                    raise ValueError("模型顺序包含不属于当前 API 通道的模型槽位")
                if source_name not in normalized_order:
                    normalized_order.append(source_name)
            if len(normalized_order) > 64:
                raise ValueError("单个 API 最多保存 64 个模型顺序槽位")
            settings[key] = normalized_order
            continue
        if key in {"endpoint", "region", "app_id", "primary_model", "backup_model"}:
            text = str(value or "").strip()
            if key == "app_id" and _api_management_channel_base_id(channel_id) == "voice-clone-admin":
                raise ValueError("新版声音复刻不需要额外鉴权参数")
            if key == "endpoint" and text:
                parsed = urlparse(text)
                if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                    raise ValueError("接口地址必须是 http/https 地址")
                text = _api_management_safe_url(text)
                if _api_management_channel_base_id(channel_id) == "voice-clone-admin" and text != DEFAULT_VOICE_CLONE_URL:
                    raise ValueError("新版声音复刻 endpoint 固定为新版 v3 voice_clone，不接受旧接口地址")
            elif key == "region" and text:
                if len(text) > 80 or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", text):
                    raise ValueError("区域必须是有效的云服务 Region 标识")
            elif key == "app_id" and text:
                if len(text) > 128 or any(char in text for char in "\r\n"):
                    raise ValueError("AppID 长度或格式不合法")
            settings[key] = text
        elif key == "strategy":
            strategy = str(value or "").strip()
            if not strategy:
                continue
            if strategy not in tuple(str(item) for item in channel.get("strategy_options", ())):
                raise ValueError("降级策略不适用于当前 API 通道")
            settings[key] = strategy
        elif key == "quality":
            quality = str(value or "").strip().lower()
            if _api_management_channel_base_id(channel_id) == "image-generation":
                if quality not in {"low", "medium", "high", "auto"}:
                    raise ValueError("Image2 质量只能是 low、medium、high 或 auto")
                settings[key] = quality
        else:
            try:
                number = int(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"{key} 必须是整数") from exc
            lower, upper = (1, 5) if key == "max_attempts" else (5, 900)
            if number < lower or number > upper:
                raise ValueError(f"{key} 必须在 {lower} 到 {upper} 之间")
            settings[key] = number
    if base_channel_id in API_MANAGEMENT_FIXED_PROTOCOL_CHANNELS:
        # 页面只保存 TTS 地址、Key、策略与超时；模型/资源 ID 必须回到
        # transport 的固定默认值，避免历史页面配置覆盖协议参数。
        for key in ("primary_model", "backup_model", "model_slots", "model_names", "model_order"):
            settings.pop(key, None)
        if channel_id == "tts":
            submitted_endpoint = str(settings.get("endpoint") or "").strip()
            if submitted_endpoint and _api_management_safe_url(submitted_endpoint) != DEFAULT_ARK_TTS_URL:
                raise ValueError("新版 TTS endpoint 固定为新版 v3 unidirectional，不接受旧接口地址")
            # endpoint 由新版 transport 固定，不写入页面配置；这样旧地址
            # 不会在下一次服务启动时重新出现。
            settings.pop("endpoint", None)
    if channel_id in API_MANAGEMENT_CONSOLIDATED_MODEL_CHANNELS:
        # 兼容旧版本常量；当前集合为空，不再把多个真实接入点合并为一个。
        # 若外部旧调用方显式重新启用该集合，沿用旧归一化逻辑，避免破坏历史契约。
        consolidated_sources = _api_management_model_env_names(channel_id)
        raw_slots = settings.get("model_slots")
        if isinstance(raw_slots, Mapping):
            slots = {str(key): str(value or "").strip() for key, value in raw_slots.items()}
            canonical_source = next(
                (source for source, value in slots.items() if source in consolidated_sources and value),
                "",
            )
            canonical_model = slots.get(canonical_source, "") if canonical_source else ""
            if canonical_model:
                for source in consolidated_sources:
                    slots[source] = canonical_model
                settings["model_slots"] = slots
                raw_names = settings.get("model_names")
                if isinstance(raw_names, Mapping):
                    names = {str(key): str(value or "").strip() for key, value in raw_names.items()}
                    canonical_name = names.get(canonical_source, "")
                    if canonical_name:
                        for source in consolidated_sources:
                            names[source] = canonical_name
                        settings["model_names"] = names
                raw_order = settings.get("model_order")
                if isinstance(raw_order, (list, tuple)):
                    normalized_order: list[str] = []
                    canonical_added = False
                    for source in raw_order:
                        source_name = str(source or "").strip()
                        if not source_name:
                            continue
                        if source_name in consolidated_sources:
                            if canonical_added:
                                continue
                            source_name = canonical_source or source_name
                            canonical_added = True
                        if source_name not in normalized_order:
                            normalized_order.append(source_name)
                    settings["model_order"] = normalized_order
    groups = dict(config.get("groups") or {})
    previous = dict(groups.get(channel_id) or {})
    if base_channel_id in API_MANAGEMENT_FIXED_PROTOCOL_CHANNELS:
        for legacy_field in (
            "endpoint", "region", "app_id", "primary_model", "backup_model",
            "model_slots", "model_names", "model_order",
        ):
            previous.pop(legacy_field, None)
    if base_channel_id == "voice-clone-admin":
        # 保存新版配置时清除历史控制面字段，保证旧配置不会污染 V3 数据面。
        previous.pop("resource_management", None)
        for legacy_field in ("app_id", "access_key", "secret_key", "access_token", "project_name", "service", "version", "region"):
            previous.pop(legacy_field, None)
    previous.update(settings)
    groups[channel_id] = previous
    config["groups"] = groups
    if new_channel_definition is not None:
        api_channels = dict(config.get("api_channels") or {})
        definitions = api_channels.get(group_id, [])
        definitions = list(definitions) if isinstance(definitions, (list, tuple)) else []
        definitions.append(new_channel_definition)
        api_channels[group_id] = definitions
        config["api_channels"] = api_channels
    if normalized_api_failover is not None:
        api_groups = dict(config.get("api_groups") or {})
        api_groups[group_id] = normalized_api_failover
        config["api_groups"] = api_groups
    if normalized_function_settings is not None:
        api_functions = dict(config.get("api_functions") or {})
        previous_functions = api_functions.get(group_id)
        previous_functions = dict(previous_functions) if isinstance(previous_functions, Mapping) else {}
        # 功能级尝试次数从未接入真实执行器；保留优先级，清除旧的无效字段。
        previous_functions = {
            str(function_id): {
                "priority": str(value.get("priority") or "api_first"),
            }
            for function_id, value in previous_functions.items()
            if isinstance(value, Mapping)
        }
        previous_functions.update(normalized_function_settings)
        api_functions[group_id] = previous_functions
        config["api_functions"] = api_functions
    _api_management_save_secrets(channel_id, raw_secrets)
    _api_management_write_config(config)
    _api_management_apply_runtime_config(config)
    return _api_management_snapshot()


