    # 历史的 CSS/脚本覆盖层不再注入。生产页已在服务端替换为唯一的新版表单；
    # 因而历史 syncMode() 无法再写回“填写 speaker_id”的旧版状态文案。
    # 最终生产页硬门禁：兼容替换全部完成后，移除所有声音复刻/定制音色
    # DOM。历史实现仍保留在源码中供审计，但不能通过后续模板替换重新暴露。
    page_text = re.sub(r'<section id="voiceClonePanel"(?:\s|>).*?</section>', "", page_text, flags=re.S)
    page_text = re.sub(r'<section id="voiceAcceptancePanel"(?:\s|>).*?</section>', "", page_text, flags=re.S)
    # 删除历史声音复刻样式和脚本本身，不能只隐藏 DOM；否则旧逻辑仍会
    # 在浏览器端注册点击监听并继续污染生产页。
    def _drop_legacy_voice_assets(match: re.Match[str]) -> str:
        block = match.group(0)
        markers = ("voice-clone", "voiceClone", "voice-slot-import", "voice-manager-create-guide", "open_voice_clone", "submitV3VoiceClone", "submitVoiceClone")
        return "" if any(marker.casefold() in block.casefold() for marker in markers) else block

    page_text = re.sub(r"<(?:style|script)\b[^>]*>[\s\S]*?</(?:style|script)>", _drop_legacy_voice_assets, page_text, flags=re.I)
    page_text = re.sub(
        r'<button id="(?:openVoiceClone|newVoiceClone|openVoiceClonePostpaid|newVoiceClonePostpaid)"(?:\s|>)[^>]*>.*?</button>',
        "",
        page_text,
        flags=re.S,
    )
    page_text = re.sub(r'<a[^>]+href="[^"]*open_voice_clone[^"]*"[^>]*>.*?</a>', "", page_text, flags=re.S | re.I)
    page_text = page_text.replace(
        "新音色先在火山新版控制台使用预付费槽位创建，获得真实 speaker_id 后自动核验并登记到本地；本地不会上传到后付费 custom_speaker_id。",
        "",
    )
    page_text = page_text.replace(
        "在生成 TTS 前选择音色。定制音色可直接在本弹窗上传声音文件创建或更新；训练成功后点击卡片“试听并验收”，再进入 TTS，由剪映 STT 生成唯一时间轴。",
        "在生成 TTS 前选择官方音色并试听；生成结果继续交给剪映 STT 生成唯一时间轴。",
    )
    page_text = page_text.replace("音色管理与试听", "官方 TTS 音色与试听", 1)
    page_text = page_text.replace("上传/创建定制音色", "", 1)
    page_text = page_text.replace("上传/训练定制音色", "", 1)
    page_text = page_text.replace("创建预付费定制音色", "", 1)
    page = page_text.encode("utf-8")
    # 运行时硬门禁：历史脚本保留在源码中供审计，但生产页面绝不能再
    # 暴露官网上传/剪贴板登记入口。若未来有人误把历史片段重新拼回页面，
    # 这里直接拒绝提供页面，避免用户再次被带离本地后台。
    forbidden_runtime_markers = (
        "https://console.volcengine.com/speech/new/experience/clone",
        "openOfficialPrepaidClone",
        "navigator.clipboard.readText",
    )
    rendered_text = page.decode("utf-8")
    leaked_markers = [marker for marker in forbidden_runtime_markers if marker in rendered_text]
    if leaked_markers:
        raise RuntimeError(
            "编导页检测到已废弃的官网音色上传入口，已阻止提供页面："
            + ", ".join(leaked_markers)
        )
    return page


