    governance_script += b"<script>(()=>{const map=document.getElementById('videoStyleCategoryMap');const existing=document.getElementById('packagingExistingTemplates');const count=document.getElementById('packagingExistingCount');const empty=document.getElementById('packagingExistingEmpty');const bundle=document.getElementById('packagingBundleName');const version=document.getElementById('packagingBundleVersion');const styleList=document.getElementById('packagingStyleList');if(!map||!count||!bundle)return;const labels={'\u7247\u5934':'opening','\u56fe\u7247':'image','\u6570\u5b57\u4eba':'digital_human','AIGC':'aigc','\u8bf4\u660e\u955c\u5934':'explanation','\u6df7\u5408\u8bf4\u660e\u955c\u5934':'mixed_explanation','\u7247\u5c3e':'ending'};let latest=[];const cards=()=>Array.from(map.querySelectorAll('.video-style-category-item'));const paint=()=>{const by=new Map(latest.map(item=>[String(item.category||''),item]));cards().forEach(card=>{const category=card.dataset.category||labels[card.querySelector('strong')?.textContent||'']||'';if(category)card.dataset.category=category;const item=by.get(category);card.classList.toggle('template-ready',!!item);card.classList.toggle('template-missing',!item);let state=card.querySelector('.packaging-category-template-state');if(!state){state=document.createElement('span');state.className='packaging-category-template-state';card.appendChild(state)}state.textContent=item?'\u5df2\u914d\u7f6e \u00b7 v'+(item.version||'1.0'):'\u672a\u914d\u7f6e';card.setAttribute('aria-label',(card.querySelector('strong')?.textContent||category)+' '+state.textContent)});const total=cards().length||7;const ready=Math.min(by.size,total);count.textContent=ready+'/'+total+' \u5df2\u914d\u7f6e';if(empty){empty.hidden=false;empty.textContent=ready<total?'\u8fd8\u6709 '+(total-ready)+' \u4e2a\u5206\u7c7b\u672a\u914d\u7f6e\uff0c\u8bf7\u901a\u8fc7\u65b0\u589e\u5b50\u6a21\u677f\u8865\u9f50\u3002':'\u4e03\u4e2a\u5206\u7c7b\u5b50\u6a21\u677f\u5df2\u5168\u90e8\u914d\u7f6e\u3002'}};const refresh=async()=>{const name=String(bundle.value||'').trim();if(!name)return;const query=new URLSearchParams({bundle_name:name,version:String(version?.value||'1.0')});try{const response=await fetch('/api/editing/packaging-bundles/category-templates?'+query.toString(),{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.message||'');latest=Array.isArray(data.templates)?data.templates:[];paint()}catch(_error){latest=[];paint()}};new MutationObserver(paint).observe(map,{childList:true,subtree:true});if(existing)new MutationObserver(()=>existing.querySelectorAll('.packaging-existing-template').forEach(card=>card.classList.add('template-ready')).observe(existing,{childList:true,subtree:true});if(styleList)styleList.addEventListener('click',()=>window.setTimeout(refresh,80),true);bundle.addEventListener('input',refresh);bundle.addEventListener('change',refresh);window.setTimeout(refresh,120)})();</script>"
