TOPIC_CENTER_BRIDGE_URL = str(
    os.environ.get("HORIZON_TOPIC_BRIDGE_URL") or "http://127.0.0.1:8791"
).strip().rstrip("/")
TOPIC_CENTER_DECISIONS_PATH = ROOT / "outputs" / "topic_center" / "topic_decisions.json"
# 选题队列暂不属于当前生产链路。保留旧路径和相关接口，便于后续恢复，
# 当前采用结果只写入这个归档文件，不再自动交给采集器或文案节点。
TOPIC_CENTER_QUEUE_ENABLED = False
TOPIC_CENTER_ARCHIVE_PATH = ROOT / "outputs" / "topic_center" / "selection_archive.json"
# 历史队列数据不删除、不覆盖，仅作为后续恢复时的参考。
TOPIC_CENTER_QUEUE_PATH = ROOT / "outputs" / "topic_center" / "collection_queue.json"
TOPIC_CENTER_COLLECTION_RESULTS_PATH = ROOT / "outputs" / "topic_center" / "collection_results.json"
TOPIC_CENTER_STORAGE_LOCK = threading.RLock()
TOPIC_WRITING_GOVERNANCE_PATH = ROOT / "outputs" / "topic_center" / "governance.json"
TOPIC_WRITING_GOVERNANCE_STORE = TopicWritingGovernanceStore(TOPIC_WRITING_GOVERNANCE_PATH)
TRENDRADAR_ROOT = Path(
    os.environ.get("TRENDRADAR_ROOT") or (ROOT / "external" / "TrendRadar")
).expanduser()
TRENDRADAR_ADAPTER = TrendRadarAdapter(TRENDRADAR_ROOT)
TIKHUB_TRANSPORT = TikHubTransport.from_env()
TOPIC_CENTER_INTELLIGENCE_CACHE_PATH = ROOT / "outputs" / "topic_center" / "intelligence_cache.json"
TOPIC_CENTER_WATCHLIST_PATH = ROOT / "outputs" / "topic_center" / "account_watchlist.json"
TOPIC_INTELLIGENCE = TopicIntelligenceService(
    TRENDRADAR_ADAPTER,
    TIKHUB_TRANSPORT,
    TOPIC_CENTER_INTELLIGENCE_CACHE_PATH,
)

# TrendRadar 新闻库调度由选题中心统一管理。页面只允许三个业务频率，
# 每次变更都会先触发一次真实抓取，再按保存的周期继续执行。
TOPIC_CENTER_REFRESH_SCHEDULE_PATH = ROOT / "outputs" / "topic_center" / "trendradar_refresh_schedule.json"
TOPIC_CENTER_REFRESH_INTERVALS = (1, 6, 12)
_TRENDRADAR_REFRESH_LOCK = threading.Lock()
_TRENDRADAR_SCHEDULER_LOCK = threading.RLock()
_TRENDRADAR_SCHEDULER_WAKE = threading.Event()
_TRENDRADAR_SCHEDULER_STOP = threading.Event()
_TRENDRADAR_SCHEDULER_THREAD: threading.Thread | None = None


def _default_trendradar_refresh_schedule() -> dict[str, object]:
    return {
        "version": 1,
        "enabled": True,
        "interval_hours": 1,
        "updated_at": "",
        "last_run_at": "",
        "last_run_status": "idle",
        "last_run_message": "尚未执行；修改频率后会立即更新新闻库。",
        "next_run_at": "",
        "next_run_epoch": 0.0,
    }


def _load_trendradar_refresh_schedule() -> dict[str, object]:
    schedule = _default_trendradar_refresh_schedule()
    try:
        raw = json.loads(TOPIC_CENTER_REFRESH_SCHEDULE_PATH.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, UnicodeDecodeError, json.JSONDecodeError):
        raw = {}
    if isinstance(raw, Mapping):
        schedule.update({str(key): value for key, value in raw.items() if str(key) in schedule})
    try:
        interval = int(schedule.get("interval_hours") or 1)
    except (TypeError, ValueError):
        interval = 1
    schedule["interval_hours"] = interval if interval in TOPIC_CENTER_REFRESH_INTERVALS else 1
    try:
        schedule["next_run_epoch"] = float(schedule.get("next_run_epoch") or 0.0)
    except (TypeError, ValueError):
        schedule["next_run_epoch"] = 0.0
    schedule["enabled"] = bool(schedule.get("enabled", True))
    return schedule


def _save_trendradar_refresh_schedule(schedule: Mapping[str, object]) -> dict[str, object]:
    normalized = _default_trendradar_refresh_schedule()
    normalized.update({str(key): value for key, value in schedule.items() if str(key) in normalized})
    try:
        interval = int(normalized.get("interval_hours") or 1)
    except (TypeError, ValueError) as exc:
        raise ValueError("interval_hours 必须是 1、6 或 12") from exc
    if interval not in TOPIC_CENTER_REFRESH_INTERVALS:
        raise ValueError("新闻库更新频率只能选择每小时、每6小时或每12小时")
    normalized["interval_hours"] = interval
    normalized["enabled"] = True
    _write_topic_json(TOPIC_CENTER_REFRESH_SCHEDULE_PATH, normalized)
    return normalized


def _trendradar_python_path() -> Path:
    configured = str(os.environ.get("TRENDRADAR_PYTHON") or "").strip()
    if configured:
        return Path(configured).expanduser()
    candidates = (
        TRENDRADAR_ROOT / ".venv" / "Scripts" / "python.exe",
        TRENDRADAR_ROOT / ".venv" / "bin" / "python",
    )
    return next((path for path in candidates if path.is_file()), candidates[0])


def _trendradar_schedule_public(schedule: Mapping[str, object]) -> dict[str, object]:
    """去掉内部调度字段，供页面展示，不暴露进程命令或凭据。"""
    return {
        "status": "ready",
        "enabled": bool(schedule.get("enabled", True)),
        "interval_hours": int(schedule.get("interval_hours") or 1),
        "updated_at": str(schedule.get("updated_at") or ""),
        "last_run_at": str(schedule.get("last_run_at") or ""),
        "last_run_status": str(schedule.get("last_run_status") or "idle"),
        "last_run_message": str(schedule.get("last_run_message") or ""),
        "next_run_at": str(schedule.get("next_run_at") or ""),
    }


def _next_trendradar_run(interval_hours: int) -> tuple[str, float]:
    due_epoch = time.time() + int(interval_hours) * 3600
    due_text = datetime.fromtimestamp(due_epoch, tz=timezone.utc).isoformat(timespec="seconds")
    return due_text, due_epoch


def _run_trendradar_refresh() -> None:
    """执行一次真实 TrendRadar 抓取；锁保证页面点击和周期任务不重叠。"""
    if not _TRENDRADAR_REFRESH_LOCK.acquire(blocking=False):
        return
    try:
        schedule = _load_trendradar_refresh_schedule()
        started_at = time.time()
        started_text = utc_now()
        schedule.update({
            "last_run_at": started_text,
            "last_run_status": "running",
            "last_run_message": "正在抓取 TrendRadar 新闻源；页面不会触发 TikHub 计费调用。",
            "updated_at": started_text,
        })
        _save_trendradar_refresh_schedule(schedule)
        executable = _trendradar_python_path()
        if not executable.is_file():
            raise RuntimeError(f"未找到 TrendRadar Python 运行时：{executable}")
        child_env = os.environ.copy()
        # 强制本地 SQLite，关闭分析/通知并禁止执行完成后打开浏览器；
        # 这次任务只更新新闻库，不改变下游文案链路。
        child_env.update({
            "GITHUB_ACTIONS": "true",
            "PYTHONIOENCODING": "utf-8",
            "STORAGE_BACKEND": "local",
            "STORAGE_HTML_ENABLED": "false",
            "STORAGE_TXT_ENABLED": "false",
            "AI_ANALYSIS_ENABLED": "false",
            "SCHEDULE_ENABLED": "false",
        })
        command = [str(executable), "-m", "trendradar"]
        kwargs: dict[str, object] = {
            "cwd": str(TRENDRADAR_ROOT),
            "env": child_env,
            "capture_output": True,
            "text": True,
            "encoding": "utf-8",
            "errors": "replace",
            "timeout": 600,
            "check": False,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            )
        completed = subprocess.run(command, **kwargs)
        refreshed = _load_trendradar_refresh_schedule()
        finished_text = utc_now()
        health = TRENDRADAR_ADAPTER.health()
        if completed.returncode == 0:
            status = "succeeded"
            message = "新闻库更新完成"
            crawl = str(health.get("latest_crawl") or health.get("database_date") or "")
            if crawl:
                message += f"；最新快照 {crawl}"
        else:
            status = "failed"
            message = f"TrendRadar 抓取失败（退出码 {completed.returncode}）"
        interval = int(refreshed.get("interval_hours") or 1)
        next_text, next_epoch = _next_trendradar_run(interval)
        refreshed.update({
            "last_run_at": finished_text,
            "last_run_status": status,
            "last_run_message": message,
            "updated_at": finished_text,
            "next_run_at": next_text,
            "next_run_epoch": next_epoch,
        })
        _save_trendradar_refresh_schedule(refreshed)
    except subprocess.TimeoutExpired:
        refreshed = _load_trendradar_refresh_schedule()
        next_text, next_epoch = _next_trendradar_run(int(refreshed.get("interval_hours") or 1))
        refreshed.update({
            "last_run_at": utc_now(),
            "last_run_status": "failed",
            "last_run_message": "TrendRadar 抓取超时（超过 10 分钟），未伪造新闻数据。",
            "updated_at": utc_now(),
            "next_run_at": next_text,
            "next_run_epoch": next_epoch,
        })
        _save_trendradar_refresh_schedule(refreshed)
    except Exception as exc:
        refreshed = _load_trendradar_refresh_schedule()
        next_text, next_epoch = _next_trendradar_run(int(refreshed.get("interval_hours") or 1))
        refreshed.update({
            "last_run_at": utc_now(),
            "last_run_status": "failed",
            "last_run_message": f"新闻库更新未执行：{type(exc).__name__}。",
            "updated_at": utc_now(),
            "next_run_at": next_text,
            "next_run_epoch": next_epoch,
        })
        _save_trendradar_refresh_schedule(refreshed)
    finally:
        _TRENDRADAR_REFRESH_LOCK.release()
        _TRENDRADAR_SCHEDULER_WAKE.set()


def _trigger_trendradar_refresh() -> bool:
    if _TRENDRADAR_REFRESH_LOCK.locked():
        return False
    threading.Thread(target=_run_trendradar_refresh, name="trendradar-refresh", daemon=True).start()
    return True


def _trendradar_scheduler_loop() -> None:
    while not _TRENDRADAR_SCHEDULER_STOP.is_set():
        schedule = _load_trendradar_refresh_schedule()
        due_at = float(schedule.get("next_run_epoch") or 0.0)
        wait_seconds = max(1.0, min(300.0, due_at - time.time())) if due_at else 300.0
        _TRENDRADAR_SCHEDULER_WAKE.wait(wait_seconds)
        _TRENDRADAR_SCHEDULER_WAKE.clear()
        if _TRENDRADAR_SCHEDULER_STOP.is_set():
            return
        schedule = _load_trendradar_refresh_schedule()
        if schedule.get("enabled", True) and float(schedule.get("next_run_epoch") or 0.0) <= time.time():
            _trigger_trendradar_refresh()


def _start_trendradar_scheduler() -> None:
    global _TRENDRADAR_SCHEDULER_THREAD
    with _TRENDRADAR_SCHEDULER_LOCK:
        if _TRENDRADAR_SCHEDULER_THREAD and _TRENDRADAR_SCHEDULER_THREAD.is_alive():
            _TRENDRADAR_SCHEDULER_WAKE.set()
            return
        _TRENDRADAR_SCHEDULER_STOP.clear()
        _TRENDRADAR_SCHEDULER_THREAD = threading.Thread(
            target=_trendradar_scheduler_loop,
            name="trendradar-scheduler",
            daemon=True,
        )
        _TRENDRADAR_SCHEDULER_THREAD.start()


def _topic_center_refresh_schedule(payload: Mapping[str, object]) -> dict[str, object]:
    try:
        interval = int(payload.get("interval_hours") or 0)
    except (TypeError, ValueError) as exc:
        raise ValueError("interval_hours 必须是 1、6 或 12") from exc
    if interval not in TOPIC_CENTER_REFRESH_INTERVALS:
        raise ValueError("新闻库更新频率只能选择每小时、每6小时或每12小时")
    now_text = utc_now()
    schedule = _load_trendradar_refresh_schedule()
    schedule.update({
        "enabled": True,
        "interval_hours": interval,
        "updated_at": now_text,
        "last_run_status": "queued",
        "last_run_message": "已保存频率，正在立即更新新闻库。",
        "next_run_at": "",
        "next_run_epoch": 0.0,
    })
    saved = _save_trendradar_refresh_schedule(schedule)
    _start_trendradar_scheduler()
    started = _trigger_trendradar_refresh()
    saved["refresh_started"] = started
    saved["message"] = (
        "已保存更新频率，正在立即更新新闻库。"
        if started else "已有新闻库更新任务执行中，频率已保存；本次不会重复发起请求。"
    )
    return _trendradar_schedule_public(saved) | {"refresh_started": started, "message": saved["message"]}


def _write_topic_json(path: Path, value: object) -> None:
    """以同目录临时文件替换方式写入选题状态，避免半写 JSON。"""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
    try:
        temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        temporary.replace(path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def _horizon_bridge_request(path: str, method: str = "GET", payload: Mapping[str, object] | None = None) -> dict:
    """Call the isolated Horizon bridge without importing its dependency set here."""
    url = TOPIC_CENTER_BRIDGE_URL + "/" + str(path or "").lstrip("/")
    body = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        body = json.dumps(dict(payload), ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json; charset=utf-8"
    try:
        request = Request(url, data=body, headers=headers, method=str(method or "GET").upper())
        with urlopen(request, timeout=35) as response:
            raw = response.read().decode("utf-8", errors="replace")
            value = json.loads(raw) if raw else {}
            return dict(value) if isinstance(value, Mapping) else {"status": "invalid_response", "message": "Horizon 返回格式无效"}
    except HTTPError as exc:
        try:
            raw = exc.read().decode("utf-8", errors="replace")
            value = json.loads(raw) if raw else {}
            return dict(value) if isinstance(value, Mapping) else {"status": "bridge_error", "message": f"Horizon bridge HTTP {exc.code}"}
        except (OSError, ValueError):
            return {"status": "bridge_error", "message": f"Horizon bridge HTTP {exc.code}"}
    except (OSError, URLError, ValueError) as exc:
        return {"status": "bridge_unavailable", "message": f"Horizon 测试服务不可用：{exc}"}


def _trendradar_health() -> dict[str, object]:
    """返回 TrendRadar 本地快照的真实健康状态。"""
    return TRENDRADAR_ADAPTER.health()


def _trendradar_candidates(
    intent: str = "",
    tags: Sequence[str] = (),
    sources: Sequence[str] = (),
) -> dict[str, object]:
    """从 TrendRadar 本地 SQLite 快照读取联合治理候选。"""
    return TRENDRADAR_ADAPTER.candidates(intent=intent, tags=tags, sources=sources)


def _topic_center_topics(
    intent: str = "",
    tags: Sequence[str] = (),
    sources: Sequence[str] = (),
    limit: int = 50,
) -> dict[str, object]:
    """唯一生产选题入口：只从TrendRadar读取自动推荐主题。"""
    return TOPIC_INTELLIGENCE.topics(intent=intent, tags=tags, sources=sources, limit=limit)


def _topic_center_find_candidate(candidate_id: str) -> dict[str, Any] | None:
    clean_id = str(candidate_id or "").strip()
    if not clean_id:
        return None
    result = _topic_center_topics(limit=200)
    candidates = result.get("candidates") if isinstance(result.get("candidates"), list) else []
    return next((dict(item) for item in candidates if isinstance(item, Mapping) and str(item.get("candidate_id") or "") == clean_id), None)


def _topic_center_enrich(candidate_id: str, payload: Mapping[str, object] | None = None) -> dict[str, Any]:
    candidate = _topic_center_find_candidate(candidate_id)
    if candidate is None:
        return {"status": "topic_missing", "candidate_id": candidate_id, "contents": [], "message": "未找到TrendRadar主题，请刷新后重试"}
    options = dict(payload or {})
    raw_platforms = options.get("platforms")
    platforms = [str(item).strip().lower() for item in raw_platforms] if isinstance(raw_platforms, list) else ["douyin", "xiaohongshu", "weibo", "zhihu", "wechat"]
    try:
        limit = max(1, min(int(options.get("limit") or 20), 50))
    except (TypeError, ValueError):
        limit = 20
    return TOPIC_INTELLIGENCE.enrich(
        candidate,
        platforms=platforms,
        limit=limit,
        wechat_ghid=str(options.get("wechat_ghid") or "").strip(),
        force=str(options.get("force") or "").strip().lower() in {"1", "true", "yes"},
    )


_TOPIC_PREVIEW_MAX_CHARS = 360
_TOPIC_PREVIEW_SOCIAL_PLATFORMS = frozenset({"douyin", "xiaohongshu", "weibo", "zhihu", "wechat"})


def _topic_center_preview(candidate_id: str) -> dict[str, Any]:
    """按用户查看动作读取新闻源的截断正文预览。

    TrendRadar 的 SQLite 快照只保存标题和 URL，不含正文；这里仅对非社交
    平台的公开文章 URL 做只读 HTML 预览。抖音/小红书/微博/知乎/公众号正文
    仍留给 TikHub 查询和主素材采集阶段，避免页面打开时产生付费调用。
    预览结果不写入治理源，也不能进入 CONTENT_READY。
    """
    candidate = _topic_center_find_candidate(candidate_id)
    if candidate is None:
        return {"status": "topic_missing", "candidate_id": candidate_id, "content_preview": "", "message": "未找到TrendRadar主题，请刷新后重试"}
    source_url = str(candidate.get("url") or candidate.get("source_url") or "").strip()
    if not re.match(r"^https?://[^\s]+$", source_url, flags=re.IGNORECASE):
        return {"status": "invalid_input", "candidate_id": candidate_id, "content_preview": "", "message": "该主题没有可读取的真实来源链接"}
    platform = str(candidate.get("platform") or "").strip().lower()
    if platform in _TOPIC_PREVIEW_SOCIAL_PLATFORMS or any(platform.startswith(item + "-") for item in _TOPIC_PREVIEW_SOCIAL_PLATFORMS):
        return {
            "status": "deferred",
            "candidate_id": candidate_id,
            "source_url": source_url,
            "content_preview": "",
            "message": "该平台正文需在查询相关内容后由 TikHub 详情或主素材采集获取；当前不自动计费。",
        }
    result = collect_topic_source(
        {
            "selection_id": "preview-" + str(candidate_id).strip(),
            "source_url": source_url,
            "platform": platform,
            "title": str(candidate.get("title") or "").strip(),
            "source_metadata": {"preview_only": True, "provider": "TrendRadar"},
        },
        timeout=15.0,
    )
    content = str(result.get("content") or "").strip()
    preview = content[:_TOPIC_PREVIEW_MAX_CHARS]
    if not preview:
        return {
            "status": str(result.get("status") or "content_missing"),
            "candidate_id": candidate_id,
            "source_url": source_url,
            "content_preview": "",
            "content_type": str(result.get("content_type") or ""),
            "message": str(result.get("message") or "来源页面未返回可展示正文"),
        }
    return {
        "status": "ready",
        "candidate_id": candidate_id,
        "source_url": source_url,
        "title": str(result.get("title") or candidate.get("title") or "").strip(),
        "content_preview": preview,
        "content_preview_source": "source_html_preview",
        "content_length": len(content),
        "content_type": str(result.get("content_type") or "html_text"),
        "message": "已读取来源页面正文预览；该预览不会进入文案链路。",
    }


def _topic_center_cached_contents(candidate_id: str, query: Mapping[str, Sequence[str]] | None = None) -> dict[str, Any]:
    options = query or {}
    raw_platforms = options.get("platforms") if isinstance(options, Mapping) else None
    platforms = [str(item).strip().lower() for item in raw_platforms] if isinstance(raw_platforms, list) else ["douyin", "xiaohongshu", "weibo", "zhihu", "wechat"]
    result = TOPIC_INTELLIGENCE.cached_enrich(candidate_id, platforms=platforms)
    if result is None:
        return {"status": "not_enriched", "candidate_id": candidate_id, "contents": [], "message": "请先点击查询相关内容"}
    return result


def _topic_center_selection_create(payload: Mapping[str, object]) -> dict[str, Any]:
    """把用户选定的主素材/参考素材交给现有治理Store。"""
    selection_payload = dict(payload)
    content_items = selection_payload.get("content_items")
    if not isinstance(content_items, list) or not content_items:
        raise ValueError("建立选题包前必须先查询并选择至少一条真实内容")
    primary_id = str(selection_payload.get("primary_content_id") or "").strip()
    if not primary_id:
        raise ValueError("必须指定一条primary_content_id作为主素材")
    primary = next((item for item in content_items if isinstance(item, Mapping) and str(item.get("content_id") or "") == primary_id), None)
    if not isinstance(primary, Mapping):
        raise ValueError("primary_content_id不在当前查询结果中")
    short_video_ids = [
        str(item.get("content_id") or "")
        for item in content_items
        if isinstance(item, Mapping) and filter_short_videos([item])[1]
    ]
    if short_video_ids:
        raise ValueError("不能选择时长不超过1分钟的视频；请重新查询并选择超过1分钟的主素材或参考素材")
    selection_payload.setdefault("source_url", primary.get("url") or primary.get("source_url") or "")
    selection_payload.setdefault("title", primary.get("title") or "")
    selection_payload.setdefault("source_name", primary.get("platform") or primary.get("provider") or "TikHub")
    selection_payload.setdefault("platform", primary.get("platform") or "article")
    metadata = selection_payload.get("source_metadata") if isinstance(selection_payload.get("source_metadata"), Mapping) else {}
    selection_payload["source_metadata"] = {
        **dict(metadata),
        "provider": "TrendRadar+TikHub",
        "primary_content_id": primary_id,
        "reference_content_ids": selection_payload.get("reference_content_ids") or [],
    }
    selection = TOPIC_WRITING_GOVERNANCE_STORE.save_selection(selection_payload)
    return {
        "status": "accepted",
        "selection": selection,
        "governance_state": selection.get("state"),
        "message": "主素材已确认，下一步采集正文或字幕；采集成功后才能进入文案。",
    }


def _topic_center_health() -> dict[str, object]:
    """返回TrendRadar/TikHub联合能力的真实配置状态，不发起计费请求。"""
    return TOPIC_INTELLIGENCE.health()


def _topic_center_accounts_save(payload: Mapping[str, object]) -> dict[str, Any]:
    accounts = payload.get("accounts")
    if not isinstance(accounts, list):
        raise ValueError("accounts 必须是数组")
    return TOPIC_INTELLIGENCE.save_watchlist(TOPIC_CENTER_WATCHLIST_PATH, accounts)


def _topic_center_candidates(
    intent: str = "",
    tags: Sequence[str] = (),
    sources: Sequence[str] = (),
) -> dict:
    """从 Horizon 的最新分阶段结果生成可采用的选题候选。"""
    intent = str(intent or "").strip()
    clean_tags = list(dict.fromkeys(str(tag).strip() for tag in tags if str(tag).strip() and len(str(tag).strip()) <= 24))
    clean_sources = list(dict.fromkeys(str(source).strip() for source in sources if str(source).strip()))
    query = "intent=" + quote(intent)
    query += "".join("&tags=" + quote(tag) for tag in clean_tags)
    query += "".join("&sources=" + quote(source) for source in clean_sources)
    result = _horizon_bridge_request("/api/candidates?" + query)
    if result.get("status") == "source_missing":
        horizon_sources = [
            source
            for source in clean_sources
            if source in {"rss", "rss_36kr", "rss_zhihu", "google_news"}
        ]
        fetched = _horizon_bridge_request(
            "/api/pipeline/fetch",
            "POST",
            {"hours": 24, "sources": ["rss"] if horizon_sources else None},
        )
        if fetched.get("status") == "ready":
            result = _horizon_bridge_request("/api/candidates?" + query)
    if result.get("status") in {"bridge_unavailable", "bridge_error"}:
        result.setdefault("candidates", [])
        result.setdefault("source", "Horizon")
    return result


def _topic_center_douyin_hot(board: str = "hot_search", *, force: bool = False) -> dict:
    """读取抖音热点上游，仅作为页面上半部的信源展示。"""
    query = "board=" + quote(str(board or "hot_search").strip())
    if force:
        query += "&force=1"
    result = _horizon_bridge_request("/api/douyin/hot?" + query)
    if result.get("status") in {"bridge_unavailable", "bridge_error"}:
        result.setdefault("items", [])
        result.setdefault("source", "抖音热点")
    return result


def _topic_center_source_snapshot(candidate_id: str) -> dict[str, object] | None:
    """从 Horizon 最新候选恢复被采用选题的可消费字段。"""
    result = _horizon_bridge_request("/api/candidates/" + quote(str(candidate_id or "").strip(), safe=""))
    candidate = result.get("candidate") if isinstance(result, Mapping) else None
    return dict(candidate) if isinstance(candidate, Mapping) else None


def _archive_topic_selection(package: Mapping[str, object]) -> dict[str, object]:
    """保存选题归档；这是当前链路的终点，不是采集队列。"""
    return upsert_queue_item(TOPIC_CENTER_ARCHIVE_PATH, dict(package))


def _load_topic_decisions() -> dict[str, object]:
    if not TOPIC_CENTER_DECISIONS_PATH.is_file():
        return {}
    try:
        value = json.loads(TOPIC_CENTER_DECISIONS_PATH.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return dict(value) if isinstance(value, Mapping) else {}


def _topic_selection_payload_fields(
    payload: Mapping[str, object], snapshot: Mapping[str, object]
) -> dict[str, object]:
    """合并客户端候选和桥快照，客户端字段只作显式回退。"""
    source_url = str(
        payload.get("source_url")
        or snapshot.get("source_url")
        or snapshot.get("url")
        or ""
    ).strip()
    title = str(payload.get("title") or snapshot.get("title") or "").strip()
    source_name = str(
        payload.get("source_name")
        or snapshot.get("source_name")
        or snapshot.get("source")
        or ""
    ).strip()
    rank = payload.get("rank") if payload.get("rank") is not None else snapshot.get("rank")
    tags_value = payload.get("tags")
    tags = tags_value if isinstance(tags_value, (list, tuple)) else ([tags_value] if tags_value else [])
    metadata = (
        payload.get("source_metadata")
        if isinstance(payload.get("source_metadata"), Mapping)
        else (snapshot.get("source_metadata") if isinstance(snapshot.get("source_metadata"), Mapping) else {})
    )
    return {
        "source_url": source_url,
        "title": title,
        "source_name": source_name,
        "rank": rank,
        "intent": str(payload.get("intent") or "").strip(),
        "tags": [str(item) for item in tags if str(item).strip()],
        "source_metadata": dict(metadata),
    }


def _set_archived_topic_state(package: dict[str, object], decision: str) -> dict[str, object]:
    collection_state = "archived" if decision == "accepted" else (
        "archived_ignored" if decision == "ignored" else "archived_later"
    )
    collection_message = {
        "accepted": "已归档；选题队列和采集节点暂未启用",
        "ignored": "用户已忽略；未进入采集",
        "later": "用户暂缓；未进入采集",
    }[decision]
    package["collection"] = {
        "state": collection_state,
        "route": "not_configured",
        "result_id": "",
        "message": collection_message,
    }
    package["writing"] = {
        "state": "not_requested",
        "input_type": "collected_source_content",
        "message": "暂不进入文案消费，等待后续接入采集节点" if decision == "accepted" else "暂未进入文案消费",
    }
    package["updated_at"] = utc_now()
    return package


def _save_topic_center_decision(payload: dict) -> dict:
    candidate_id = str(payload.get("candidate_id") or "").strip()
    decision = str(payload.get("status") or "").strip().lower()
    if not candidate_id or decision not in {"accepted", "ignored", "later"}:
        raise ValueError("需要 candidate_id，以及 accepted、ignored 或 later 状态")
    with TOPIC_CENTER_STORAGE_LOCK:
        archive = load_queue(TOPIC_CENTER_ARCHIVE_PATH)
        existing = next(
            (
                dict(item)
                for item in archive["items"]
                if isinstance(item, Mapping) and item.get("candidate_id") == candidate_id
            ),
            None,
        )
        snapshot: Mapping[str, object] = {}
        provider = str((payload.get("source_metadata") or {}).get("provider") or "").strip().lower() if isinstance(payload.get("source_metadata"), Mapping) else ""
        # TrendRadar 候选已经携带真实标题、URL 和平台元数据；联合治理链
        # 不再回查 Horizon，避免新入口在采用阶段又隐式依赖旧信源桥。
        if (existing is None or decision == "accepted") and provider != "trendradar":
            snapshot = _topic_center_source_snapshot(candidate_id) or {}
        fields = _topic_selection_payload_fields(payload, snapshot)
        if decision == "accepted" and (not fields["source_url"] or not fields["title"]):
            raise ValueError("采用选题缺少可交给采集节点的 source_url/title")

        if existing is not None and decision != "accepted":
            package = existing
            package["decision"] = decision
        else:
            package = build_topic_selection_package(
                candidate_id=candidate_id,
                decision=decision,
                source_url=str(fields["source_url"]),
                title=str(fields["title"]),
                source_name=str(fields["source_name"]),
                rank=fields["rank"],
                intent=str(fields["intent"]),
                tags=list(fields["tags"]),
                source_metadata=fields["source_metadata"],
            )
        package = _set_archived_topic_state(package, decision)
        _archive_topic_selection(package)

        decisions = _load_topic_decisions()
        decisions[candidate_id] = decision
        _write_topic_json(TOPIC_CENTER_DECISIONS_PATH, decisions)

        return {
            "status": "saved",
            "candidate_id": candidate_id,
            "decision": decision,
            "selection_id": package["selection_id"],
            "collection_status": package["collection"]["state"],
            "collection_route": package["collection"]["route"],
            "archive_path": str(TOPIC_CENTER_ARCHIVE_PATH),
            "queue_enabled": TOPIC_CENTER_QUEUE_ENABLED,
            "message": "选题已归档；队列与采集功能暂未启用",
            "main_chain_write": False,
        }


def _collect_topic_queue_item(payload: dict) -> dict:
    """历史队列消费者；当前功能已归档，保留实现供后续恢复。"""
    if not TOPIC_CENTER_QUEUE_ENABLED:
        raise ValueError("选题队列功能已归档，暂未启用")
    selection_id = str(payload.get("selection_id") or "").strip()
    queue = load_queue(TOPIC_CENTER_QUEUE_PATH)
    item = next((dict(entry) for entry in queue["items"] if isinstance(entry, Mapping) and entry.get("selection_id") == selection_id), None)
    if not item:
        raise ValueError("未找到对应的已采用选题包")
    if item.get("decision") != "accepted":
        raise ValueError("只有 accepted 选题才能进入采集节点")
    result = collect_topic_source(item, timeout=max(5.0, min(float(payload.get("timeout_seconds") or 20), 60.0)))
    result_id = f"collection-{selection_id}"
    result["result_id"] = result_id
    try:
        results = json.loads(TOPIC_CENTER_COLLECTION_RESULTS_PATH.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        results = {}
    if not isinstance(results, dict):
        results = {}
    results[selection_id] = result
    TOPIC_CENTER_COLLECTION_RESULTS_PATH.parent.mkdir(parents=True, exist_ok=True)
    TOPIC_CENTER_COLLECTION_RESULTS_PATH.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")

    collection = dict(item.get("collection") or {})
    writing = dict(item.get("writing") or {})
    collection["state"] = str(result.get("status") or "failed")
    collection["result_id"] = result_id
    collection["message"] = str(result.get("message") or "采集节点已返回结果")
    if result.get("status") == "ready":
        writing["state"] = "ready"
        writing["message"] = "已生成 collected_source_content，可交给文案节点"
    else:
        writing["state"] = "blocked_collection"
        writing["message"] = "采集未达到文案消费条件，未进入文案节点"
    item["collection"] = collection
    item["writing"] = writing
    item["updated_at"] = utc_now()
    upsert_queue_item(TOPIC_CENTER_QUEUE_PATH, item)
    return {
        "status": "saved",
        "selection_id": selection_id,
        "collection": collection,
        "writing": writing,
        "result": result,
        "result_path": str(TOPIC_CENTER_COLLECTION_RESULTS_PATH),
        "main_chain_write": False,
    }


def _topic_center_writing_input(selection_id: str) -> dict:
    """历史队列消费入口；队列未启用时明确阻断，不传空链接。"""
    selection_id = str(selection_id or "").strip()
    if not TOPIC_CENTER_QUEUE_ENABLED:
        return {
            "status": "topic_queue_archived",
            "message": "选题队列功能已归档，暂未接入文案节点",
            "selection_id": selection_id,
        }
    queue = load_queue(TOPIC_CENTER_QUEUE_PATH)
    item = next((dict(entry) for entry in queue["items"] if isinstance(entry, Mapping) and entry.get("selection_id") == selection_id), None)
    if not item:
        return {"status": "selection_missing", "message": "未找到对应的选题包", "selection_id": selection_id}
    collection = dict(item.get("collection") or {})
    if collection.get("state") != "ready":
        return {
            "status": "blocked_collection_required",
            "message": str(item.get("writing", {}).get("message") or "采集尚未完成，不能进入文案节点"),
            "selection_id": selection_id,
            "collection": collection,
        }
    try:
        results = json.loads(TOPIC_CENTER_COLLECTION_RESULTS_PATH.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        results = {}
    result = results.get(selection_id) if isinstance(results, dict) else None
    if not isinstance(result, Mapping) or result.get("status") != "ready" or len(str(result.get("content") or "")) < 80:
        return {"status": "blocked_collection_required", "message": "采集结果缺少可供文案消费的正文", "selection_id": selection_id}
    return {
        "status": "ready",
        "selection_id": selection_id,
        "collected_source_content": {
            "platform": item.get("platform", "article"),
            "source_url": item.get("source_url", ""),
            "title": result.get("title") or item.get("title", ""),
            "source_metadata": item.get("source_metadata") if isinstance(item.get("source_metadata"), Mapping) else {},
            "transcript": result.get("content", ""),
            "transcript_status": "collected_html",
            "collection_result_id": result.get("result_id", ""),
        },
    }


def _topic_writing_governance_accept(payload: Mapping[str, object]) -> dict:
    """把候选采用写入当前联合治理对象，不再双写历史归档。"""
    selection_payload = dict(payload)
    selection_payload["decision"] = "accepted"
    selection = TOPIC_WRITING_GOVERNANCE_STORE.save_selection(selection_payload)
    return {
        "status": "accepted",
        "selection": selection,
        "governance_state": selection.get("state"),
        "message": "选题已采用，下一步提取新闻正文；尚未进入文案生成。",
    }


def _topic_writing_governance_extract(selection_id: str, payload: Mapping[str, object] | None = None) -> dict:
    """提取选题正文；失败结果也落盘，便于页面查看和重试。"""
    selection = TOPIC_WRITING_GOVERNANCE_STORE.get_selection(selection_id)
    if selection is None:
        raise TopicWritingGovernanceError("未找到对应的 topic_selection")
    TOPIC_WRITING_GOVERNANCE_STORE.update_selection(
        selection_id,
        state="EXTRACTING",
        message="正在提取新闻正文，请稍候",
    )
    request_selection = dict(selection)
    # topic_collection 使用 collection.route 判断热点搜索等特殊入口；
    # 默认 article_html 不会触碰历史队列。
    if not isinstance(request_selection.get("collection"), Mapping):
        request_selection["collection"] = {"route": "article_html"}
    options = dict(payload or {})
    try:
        timeout = max(5.0, min(float(options.get("timeout_seconds") or 20), 60.0))
    except (TypeError, ValueError):
        timeout = 20.0
    try:
        result = collect_topic_source(request_selection, timeout=timeout)
    except Exception as exc:
        # Keep extraction failures auditable and retryable instead of leaving a
        # selection stuck in EXTRACTING or returning an unstructured 500.
        result = {
            "status": "failed",
            "selection_id": selection_id,
            "source_url": selection.get("source_url") or "",
            "final_url": selection.get("source_url") or "",
            "title": selection.get("title") or "",
            "content": "",
            "content_type": "",
            "error_code": "collector_exception",
            "message": f"正文提取异常：{type(exc).__name__}",
        }
    source = TOPIC_WRITING_GOVERNANCE_STORE.save_extraction_result(selection_id, result)
    current = TOPIC_WRITING_GOVERNANCE_STORE.get_selection(selection_id) or selection
    return {
        "status": current.get("state"),
        "selection": current,
        "source": source,
        "collector_result": dict(result),
        "retryable": source.get("status") != "CONTENT_READY",
        "message": source.get("message") or current.get("message") or "正文提取完成",
    }


def _topic_writing_governance_manual_source(payload: Mapping[str, object]) -> dict:
    source = TOPIC_WRITING_GOVERNANCE_STORE.save_manual_source(
        payload.get("source_text") if payload.get("source_text") is not None else payload.get("text"),
        title=payload.get("title"),
        source_name=payload.get("source_name"),
        selection_id=payload.get("selection_id"),
        source_url=payload.get("source_url"),
    )
    selection_id = str(payload.get("selection_id") or "").strip()
    selection = TOPIC_WRITING_GOVERNANCE_STORE.get_selection(selection_id) if selection_id else None
    return {
        "status": "CONTENT_READY",
        "source": source,
        "selection": selection,
        "message": "纯文案已保存，可进入文案创作。",
    }


def _topic_writing_governance_archive_source(source_content_id: str, payload: Mapping[str, object] | None = None) -> dict:
    """将素材从文案待处理队列移出，但保留完整治理历史。"""
    reason = str((payload or {}).get("reason") or "user_remove_queue").strip()
    source = TOPIC_WRITING_GOVERNANCE_STORE.archive_source(source_content_id, reason=reason)
    return {
        "status": "ARCHIVED",
        "source": source,
        "message": "已移出创作队列，历史记录仍保留。",
    }


def _topic_writing_governance_case_item(source_content_id: str) -> dict:
    source = TOPIC_WRITING_GOVERNANCE_STORE.get_source_for_copy(source_content_id)
    input_type = str(source.get("input_type") or "news_article").strip()
    return {
        "platform": source.get("platform") or ("manual" if input_type == "manual_text" else "article"),
        "source_url": source.get("source_url") or "",
        "source_name": source.get("source_name") or "",
        "title": source.get("title") or "",
        "source_metadata": source.get("source_metadata") if isinstance(source.get("source_metadata"), Mapping) else {},
        "transcript": source.get("content") or "",
        "transcript_status": source.get("transcript_status") or ("manual_text" if input_type == "manual_text" else "collected_html"),
        "source_content_id": source.get("source_content_id") or source_content_id,
        "input_type": input_type,
    }


def _validate_case_rewrite_input(payload: Mapping[str, object]) -> tuple[str, str]:
    """Validate the new strict three-way source contract.

    ``topic_selection_id`` remains a legacy compatibility input only when none
    of the new fields is supplied; the new page always uses ``source_content_id``.
    """
    values = {
        "case_video_url": str(payload.get("case_video_url") or "").strip(),
        "source_content_id": str(payload.get("source_content_id") or "").strip(),
        "source_text": str(payload.get("source_text") or "").strip(),
    }
    present = [name for name, value in values.items() if value]
    fallback_selection = str(payload.get("topic_selection_id") or "").strip()
    if len(present) > 1:
        raise ValueError("/api/case-rewrites 严格三选一：case_video_url、source_content_id、source_text 只能填写一个")
    if present and fallback_selection:
        raise ValueError("新文案输入不能同时填写 topic_selection_id；请使用 source_content_id")
    if not present and not fallback_selection:
        raise ValueError("/api/case-rewrites 必须提供 case_video_url、source_content_id 或 source_text 之一")
    return (present[0] if present else "topic_selection_id"), values.get(present[0], "") if present else fallback_selection


